INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekliyorum', 'bekliyorum-baris-guc-6b2nq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Içimi donduran yoklugunmuydu? 

Yoksa sensizlikmi bu buruk karanlik? 

Oysa sana günesi verecektim

Umudu verecektim,sevgiyi sinirsizca

Sensiz geçen hergün kayip; hergün izdirap

Sana bir türkü tadinda yasam vaad ediyorum

Umudum,isigim çikip gel; bekliyorum..............

30.12.2003  sda ozlt   MSN:  [email protected]', 'Içimi donduran yoklugunmuydu?  Yoksa sensizlikmi bu buruk karanlik?  Oysa sana günesi verecektim Umudu verecektim,sevgiyi sinirsizca Sensiz ...', ARRAY['Türk Edebiyatı','Şiir','Barış Güç']::text[], 8.5, '{"poet":"Barış Güç","poet_slug":"baris-guc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bekliyorum-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-baris-guc-vpl16', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aralik ayiydi,günlerden sali; iyi hatirliyorum

Neydi beni sana çeken hiç bilmiyorum

Benim için yaratildigini simdi anliyorum

Zaman istedin gülüm bende bekliyorum

Sensiz geçen hiçbir günü günden saymiyorum

Senden ayri geçen yillara yaniyorum

Çabuk olalim diye haykiriyorum

Zaman istedin gülüm bende bekliyorum

01.01.2004   sda ozlt      msn:  [email protected]', 'Aralik ayiydi,günlerden sali; iyi hatirliyorum Neydi beni sana çeken hiç bilmiyorum Benim için yaratildigini simdi anliyorum Zaman istedin g...', ARRAY['Türk Edebiyatı','Şiir','Barış Güç']::text[], 8.5, '{"poet":"Barış Güç","poet_slug":"baris-guc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/zaman-104-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birtanem (Akrostiş)', 'birtanem-akrostis-hasan-ozen-vk9ej', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'B eni bana sorma BİRTANEM

 İ çimdeki fırtınaları sana anlatamam

R ehberi gözlerimdir kalbimin

T ohumlarını göreceksin aşkımın

A ma onlara hayatı sen vereceksin

N eden diye sorma; Çünkü

E vet dersen yaşayacak onlar, Hayır dersen

M atemimde gözyaşlarımla boğulacaklar.', 'B eni bana sorma BİRTANEM  İ çimdeki fırtınaları sana anlatamam R ehberi gözlerimdir kalbimin T ohumlarını göreceksin aşkımın A ma onlara ha...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özen']::text[], 8.5, '{"poet":"Hasan Özen","poet_slug":"hasan-ozen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/birtanem-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığımı Süsler Kokun', 'yalnizligimi-susler-kokun-goktu-kara-l4d0y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bulamıyorum? 

bulamıyorum.

bulamıyorum! 

bulamıyorum,

yalnızlığı süsler kokun

alçak basınç alanındaki direnişin

kar yağışı 

isabet

(sevdan) 

buluyorum! 

buluyorum.

buluyorum,

buluyorum? 

yalnızlığı süsler kokun', 'bulamıyorum?  bulamıyorum. bulamıyorum!  bulamıyorum, yalnızlığı süsler kokun alçak basınç alanındaki direnişin kar yağışı  isabet (sevdan) ...', ARRAY['Türk Edebiyatı','Şiir','Göktu Kara']::text[], 8.5, '{"poet":"Göktu Kara","poet_slug":"goktu-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yalnizligimi-susler-kokun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgine Hasret (Akrostiş)', 'sevgine-hasret-akrostis-hasan-ozen-od7mm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'S en yoktun bir zamanlar hayatımda

E lem yoktu,hasret yoktu,aşk yoktu,

V e böylesi acılar yoktu beni kahreden

G eceler boyu ağlamaklığım yoktu

 İ çimde daha önce tatmadığım duygular yoktu

N e sen vardın bir zamanlar ne bu görkemli sevdalar

E llerimin boş kalışına aldırmışlığım yoktu

H ayatım daha bir sade,daha bir sessizdi

A cıyla elem bir uzak zamandı

S en yoktun bir zamanlar hayatımda

R esimlerle, şiirlerle avunmuşluğum yoktu

E llerimin AŞK şiirleri yazmışlığı yoktu

T ükenmişliğim,Çaresizliğim,Perişanlığım yoktu', 'S en yoktun bir zamanlar hayatımda E lem yoktu,hasret yoktu,aşk yoktu, V e böylesi acılar yoktu beni kahreden G eceler boyu ağlamaklığım yok...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özen']::text[], 8.5, '{"poet":"Hasan Özen","poet_slug":"hasan-ozen","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevgine-hasret-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölesiye Sevdim (Akrostiş)', 'olesiye-sevdim-akrostis-hasan-ozen-vs3iq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ö nünde diz çöksem iki büklüm

L af etmesem de tek kelime

E llerimi uzatmasam da yine 

S evdiğimi anlarmısın ölesiye

 İ çine baksam gözlerinin

Y aşla dolmasa da gözlerim

E llerimi uzatmasam da yine

S evdiğimi anlarmısın ölesiye

E traftan çekindiğimi bilmesen

V eda edip gitsem de sana

D ünyamın yıkıldığını söylemesem de

 İ çimdeki yangınları,fırtınaları

M ısralarımdan anlarmısın sevdiğimi ölesiye', 'Ö nünde diz çöksem iki büklüm L af etmesem de tek kelime E llerimi uzatmasam da yine  S evdiğimi anlarmısın ölesiye  İ çine baksam gözlerini...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özen']::text[], 8.5, '{"poet":"Hasan Özen","poet_slug":"hasan-ozen","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/olesiye-sevdim-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Çıkar', 'ne-cikar-sadik-softa-tk3fj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Rüzgar olmuş akıl baştan savrulur.

Akıl kalmaz yürek baştan kavrulur.

Pusatlanır yiğit baştan doğrulur.

Kapılara kilit vursan ne çıkar? 

Tüm yollara tuzak kursan ne çıkar? 

Bir zülüfün teli düşmüş savrulur.

Bakışına yürek düşmüş kavrulur.

Çatık kaşa hilâl düşmüş kıvrılır.

Kapılara kilit vursan ne çıkar? 

Tüm yollara tuzak kursan ne çıkar? 

Ela gözden bir damla yaş savrulur.

Damla damla yavaş yavaş kavrulur.

Hüzün çökmüş, dudaklardan kıvrılır.

Kapılara kilit vursan ne çıkar? 

Tüm yollara tuzak kursan ne çıkar?', 'Rüzgar olmuş akıl baştan savrulur. Akıl kalmaz yürek baştan kavrulur. Pusatlanır yiğit baştan doğrulur. Kapılara kilit vursan ne çıkar?  Tüm...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ne-cikar-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Dersin', 'ne-dersin-hasan-ozen-35xn6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen yanmayı bilirmisin alev alev

Hiç yandımı yüreğin

Hiç parçalandımı lime lime

Şakakların zonkladımı an be an

Pervasızca şuursuzca dolaştınmı sokaklarda

Görebilmek ümidiyle seni

Hayır! ... Tabii ki hayır.

Sen seni tanıyıp,Seni ölesiye sevmedin ki! ...

Sen sensiz kalmadın ki

Nereden bileceksin sensizliği

Sen sensiz kalmadın ki

Benim seni ölesiye seven

Benim sensizliğin acısı ile yanıp kavrulan

Çaresizliğimi hissettinmi hiç bir an olsun

Şu an neler yapmakta diye iç geçirdin mi

Sabrımın tükenmekte olduğunu anlayabilirmisin

Çıldırmanın eşiğinde olduğumu farkettin mi

Ne dersin yetişir mi artık bu kadar

Yoksa daha ERKEN mi Ne dersin', 'Sen yanmayı bilirmisin alev alev Hiç yandımı yüreğin Hiç parçalandımı lime lime Şakakların zonkladımı an be an Pervasızca şuursuzca dolaştın...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özen']::text[], 8.5, '{"poet":"Hasan Özen","poet_slug":"hasan-ozen","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ne-dersin-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leblebi', 'leblebi-nevin-kalafatoglu-ty9ej', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'avuç dolusuydu leblebi

biri yere düştü

geldi beri

basıldı üstüne

ezildi.

oysa bir tadı vardı

gideceği yer belli

bir taneydi! 

yenilemedi

lezzet bile veremedi.

yok oldu gitti

zavallı leblebi...

01.01.2004', 'avuç dolusuydu leblebi biri yere düştü geldi beri basıldı üstüne ezildi. oysa bir tadı vardı gideceği yer belli bir taneydi!  yenilemedi lez...', ARRAY['Türk Edebiyatı','Şiir','Nevin Kalafatoğlu']::text[], 8.5, '{"poet":"Nevin Kalafatoğlu","poet_slug":"nevin-kalafatoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/leblebi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolların Ötesi', 'yollarin-otesi-sadik-softa-uyz80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilirim hiçbir yolun, olmasa da bir sonu,

Dönüp dursan durmadan, başlanan yerde biter.

Sen biter san bir yolu, biter diye beklerken,

Bittiği yerden başlar, bütün yolların sonu.

Aşmasını bilirsen, dağ, tepe, ırmak ırmak,

Yollara düşmeye gör, akla gelmez hiç durmak.

Boşadır bütün uğraş, sızlanmak ve bağırmak,

Bittiği yerden başlar bütün yolların sonu.

Yolların ötesinde yine bir yolculuk var; 

Yollar kement atanda, yeni yolculuk başlar.

Hayat başlar yol başlar, hayat biter yol başlar; 

Bittiği yerden başlar, bütün yolların sonu.', 'Bilirim hiçbir yolun, olmasa da bir sonu, Dönüp dursan durmadan, başlanan yerde biter. Sen biter san bir yolu, biter diye beklerken, Bittiği...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yollarin-otesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiyi Haketmek Gerek (Akrostiş)', 'sevgiyi-haketmek-gerek-akrostis-hasan-ozen-ov5mt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'S evmek senin de hakkın gülüm

E ğer bilirsen sevmeyi

V eda etmen gerektiğinde

G izleyebilirsen içindeki yangını

 İ şte o zaman haketmişsindir sevmeyi

Y aşlar gözlerinde değil,kalbinde ise eğer

 İ şte o zaman haketmişsindir sevmeyi

H aketmek gerek, bedeli vardır herşeyin

A şkın bedeli acılardır,hüzünlerdir

K aranlık gecelerde isyanlardır dayanabildiğince

E fkardır sigara dumanı misali dağılmayan

K or ateşte donmak,Kutuplarda yanmaktır

E smektir deli rüzgar misali

T epedir aşılması gereken dağdır

M anştır geçilecek deryadır

E ğer bilirsen sevmeyi

K aranlık geceni aydınlatan şuadır

G özlerde başlarmış sevgi

E ğer bilirsen sevmeyi

R üyalar bile sevgiye çıkar

E ğer dinlersen SEVENİ

K onuşma sus,Sevgiyi haketmek gerek', 'S evmek senin de hakkın gülüm E ğer bilirsen sevmeyi V eda etmen gerektiğinde G izleyebilirsen içindeki yangını  İ şte o zaman haketmişsindi...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özen']::text[], 8.5, '{"poet":"Hasan Özen","poet_slug":"hasan-ozen","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sevgiyi-haketmek-gerek-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör Olsun Gözlerim (Akrostiş)', 'kor-olsun-gozlerim-akrostis-hasan-ozen-xwblp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'K ör olsun gözlerim

Ö mür boyu ağladılar

R ezil oldum her aşkımda

O vefasızlara bağlandılar

L anet olsun kaderime

S abır çıktı hep falıma

U mut ettim yarınımda

N e acılar yaşattılar

G özlerimdir tüm dertleri çektiren

Ö mür boyu hep dünyaya küstüren

Z ehredip her günümü  yaşamımdan bezdiren

L anet olsun size kör olun gözler

E llerimin boş kalışına 

R encide olan kalbimin kırılışına aldırmadınız

 İ  nadına sevecek başka güzeller buldunuz

M utluluğu çok gördünüz,Kör olun gözler', 'K ör olsun gözlerim Ö mür boyu ağladılar R ezil oldum her aşkımda O vefasızlara bağlandılar L anet olsun kaderime S abır çıktı hep falıma U ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özen']::text[], 8.5, '{"poet":"Hasan Özen","poet_slug":"hasan-ozen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kor-olsun-gozlerim-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırılası Kalbim (Akrostiş)', 'kirilasi-kalbim-akrostis-hasan-ozen-p71s8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'K ırılası kalbim, atmayası nabzım

 I zdırapları acıları sanki benimle yaşamadılar

R iyakarlıktan onlar da nasibini almış

 I rgat bedenimi bencilce harcadılar

L episka saçlara vuruldum kalbim yüzünden

A çmayan güllere,tütmeyen ocaklara döndüm

S aymadım ki kimbilir böyle kaç güzel

 I rgat bedenimi bencilce harcadılar

K o gitsin diyemiyorsun ki dostum

A nlamadığın, boşa geçen bir yaşam varken

L episka saçlara vuruluyorsun, Fakat

B edenin harcansa bile ruhun senin ya! ...

 İ çinden kendince kendini avutuyorsun

M asum bedenin bencilce harcansa bile, ruhun senin ya! ...', 'K ırılası kalbim, atmayası nabzım  I zdırapları acıları sanki benimle yaşamadılar R iyakarlıktan onlar da nasibini almış  I rgat bedenimi be...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özen']::text[], 8.5, '{"poet":"Hasan Özen","poet_slug":"hasan-ozen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kirilasi-kalbim-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyah ve Beyaz', 'siyah-ve-beyaz-enes-onal-bgw1y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SİYAH VE BEYAZ

Anna sayfamı çevir

Sana göre çok kirliyim.

Sen bembeyaz parşömensin,

Ben simsiyah mürekkebim

Damlarsam aheste büyürüm üzerinde

Farkedemezsin.

Sen kristalsin Anna

Ben keçe gibiyim.

Binlerce parçaya ayrılırsın,

Daha ilk uçurumumda.

Birleşemezsin.

Sen padişahın tek kızısın Anna

En iyi ok atabilen almalı seni,

En iyi kılıç kuşanabilen,

Götürmeli o pespembe rüyalarına.

Eğer varsa

Ağlayamazsın.

Ben burda kalacağım Anna

Karbonmonoksit soluyup gece uyanacağım.

Anla Yavrum

Pegasus''u boyayan gölgen,

Yetmiyor beni birazcık olsun açmaya

Başaramazsın.

Ağlama Anna

Yaşlar zift gibi duruyor pınarlarında.

Her damlanda

Marmara düşüyor üstüme ağlama

Anna çek nurunu kuyumdan,

Yaşatamazsın.

Anna kapa gözlerini,uyanacağım.

Anla yavrum,

Kan kaybediyor ışık,

Bana her bakışında

Güneş tutuluyor,yıldızlar kayıyor.

Aydınlatamazsın.

Anna İsa gibi göklere çekilmelisin

Korkuyorum; 

Kaybolacaksın diye anaforumda.

Yarasaların içinde anka gibi

Seçileceksin diye semada.

Kaybolamazsın.

Anna

Yaşayamazsın sen burada; 

Bu içine ışık değmeyen,

Yedi kat dipteki odada.

Bu köpeklerin su içmediği,

Sineklere bile sıla olmayan,

Güneşin es geçtiği bataklıkta.

Olamazsın Anna,

Yapamazsın yavrum,

Yaşayamazsın.

Sen melikelerle yarışmalısın Anna

Perilerle dolaşmalısın.

Papatyalardan taç yapıp,

Cenneti kıskandırmalısın.

Beni anlamalısın Aşkım; 

Kalamazsın...', 'SİYAH VE BEYAZ Anna sayfamı çevir Sana göre çok kirliyim. Sen bembeyaz parşömensin, Ben simsiyah mürekkebim Damlarsam aheste büyürüm üzerind...', ARRAY['Türk Edebiyatı','Şiir','Enes Önal']::text[], 8.5, '{"poet":"Enes Önal","poet_slug":"enes-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/siyah-ve-beyaz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Göre Değil', 'bana-gore-degil-ozgur-sirius-ey5cc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dostlar bir bir yol alıyor

Aşka düşen çok yanıyor

Gönlüm burda zor kalıyor

Gitmek bana göre değil

Sen olmasan deli gönül

Açarmıydı kırmızı gül

Çağırıyor seni bülbül

Uçmak bana göre değil 

Aşık Özgür benim adım

Yangınım var acı tadım

Aşk şerbetinden bir yudum

İçmek bana göre diğil', 'Dostlar bir bir yol alıyor Aşka düşen çok yanıyor Gönlüm burda zor kalıyor Gitmek bana göre değil Sen olmasan deli gönül Açarmıydı kırmızı g...', ARRAY['Türk Edebiyatı','Şiir','Özgür Sirius']::text[], 8.5, '{"poet":"Özgür Sirius","poet_slug":"ozgur-sirius","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bana-gore-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göze Alsaydın', 'goze-alsaydin-nedim-saatcioglu-9xq5s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yedi kat zindanda seni bulurdum

Dizimde bir gece düşe dalsaydın

Sana kader kadar yakın olurdum

Benimle her şeyi göze alsaydın

Acılar kalbime tutsak olmazdı

Hayalin aklımı esir almazdı

Geceler boyunca gözüm dalmazdı

Benimle her şeyi göze alsaydın

Sevgiye en muhtaç olduğun anda

Gelirdim ellerim olsa da kanda

Aşk denen kuralsız bu zor oyunda

Benimle her şeyi göze alsaydın

Ayrılık yoluma tuzak kurmazdı

Ellerim saçımı yolup durmazdı

Sensizlik acısı tene vurmazdı

Benimle her şeyi göze alsaydın', 'Yedi kat zindanda seni bulurdum Dizimde bir gece düşe dalsaydın Sana kader kadar yakın olurdum Benimle her şeyi göze alsaydın Acılar kalbime...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/goze-alsaydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül be Özüm', 'gul-be-ozum-gunes-davenport-wa5pb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gül be özüm,

anlamaya ramak kaldı.

azı da, çoğu da gördün,

ne fark vardı arada,

hissetmek istediklerinden başka? 

sende doğdu, sende öldü güzellik,

kayıt koyduğunca tatsızlaştı yaşanan.

nicesi sardı veya sarstı, salladı seni,

kah sevinç oldu, kah ise acı, seni uyaran.

oysa şimdi tam ortadasın.

bu boşluk misali hale dayan! 

duygusuz belki,

ama fazlasıyla duyarlı,

bu hal farklı, zor anlaşılan,

ama seni sana uyandıracak olan.

gül be özüm,

an’lamaya az kaldı...', 'gül be özüm, anlamaya ramak kaldı. azı da, çoğu da gördün, ne fark vardı arada, hissetmek istediklerinden başka?  sende doğdu, sende öldü gü...', ARRAY['Türk Edebiyatı','Şiir','Güneş Davenport']::text[], 8.5, '{"poet":"Güneş Davenport","poet_slug":"gunes-davenport","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gul-be-ozum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaf Dağı Masalı ( serbest )', 'kaf-dagi-masali-serbest-nedim-saatcioglu-1xo6z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerimde fırtınalar dindi

Yüreğimdeki alevler

Yerini küllere bıraktı

Biliyor musun hasretin de 

Eskisi kadar ağır gelmiyor bana

Arada bir o yeşil

Gözlerin geliyor aklıma

Bazen gülüşünü özlese de gözlerim

Hasretine alıştım galiba

Kimi gün sessizliği

Bir ıslık çığlığının önüne katıp

                                     sürüklüyorum

Kimi gün sensizliği yaşasa da yüreğim

Yokluğuna alıştım galiba

Bilirsin hani bir kaf dağı masalı vardır

Sen benim kaf dağı masalımsın

Her zaman var olan

Ama hiç bir zaman olmayan', 'Gözlerimde fırtınalar dindi Yüreğimdeki alevler Yerini küllere bıraktı Biliyor musun hasretin de  Eskisi kadar ağır gelmiyor bana Arada bir ...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kaf-dagi-masali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutların Ötesi', 'umutlarin-otesi-gunes-davenport-o9zse', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'umut, hep ‘yarın’ der.

delice korkar bugünden.

kaçar bugün ile gelenden.

yaşaması ‘yarın’a bağlıdır çünkü,

yaşar, hep erteleyerek yaşamı.

ama sevgi, kabul eder ya olanı,

hem de yadsımadan olamayanı! 

umutların ötesidir sevgi...', 'umut, hep ‘yarın’ der. delice korkar bugünden. kaçar bugün ile gelenden. yaşaması ‘yarın’a bağlıdır çünkü, yaşar, hep erteleyerek yaşamı. am...', ARRAY['Türk Edebiyatı','Şiir','Güneş Davenport']::text[], 8.5, '{"poet":"Güneş Davenport","poet_slug":"gunes-davenport","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/umutlarin-otesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Şarkı', 'sessiz-sarki-gunes-davenport-mlcmh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '‘iki’de ‘bir’in deneyimidir dostluk.

yenmek adına, asal yalnızlığı,

yalnızlığın dayanılmazlığını,

hem yaşamı duyumsayışta

hem ise yol’u algılayışta.

var oluşunu onaylama güdüsüdür

yek diğerinin tavırlarında.

kendine döner bakışların

her anlaşmada, uzlaşmada

hatta kıran kırana çatışmalarda.

onunla daha çok ‘var’sındır gibi,

daha doğru, daha anlamlı,

daha güzel, çok güzelsindir,

seni bütünlediğine inandığınla.

ortak bir şarkı bestelemek

ve beraber seslemektir dostluk,

ta ki şarkı söylenmeden duyulana dek

sevginin ritminde doğal ve içten

yürek atışı misali dengelenene dek.', '‘iki’de ‘bir’in deneyimidir dostluk. yenmek adına, asal yalnızlığı, yalnızlığın dayanılmazlığını, hem yaşamı duyumsayışta hem ise yol’u algı...', ARRAY['Türk Edebiyatı','Şiir','Güneş Davenport']::text[], 8.5, '{"poet":"Güneş Davenport","poet_slug":"gunes-davenport","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sessiz-sarki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevinçtir İlacı Acının', 'sevinctir-i-laci-acinin-gunes-davenport-bqd29', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sevinçtir ilacı acının,

bir gülümseme kurutur gözyaşlarını.

ne denli derinse de hüsran ve hüzün

mutsuzluğu mutluluk seyreltir ancak.

paylaşalım deriz, tamam,

ama salt ağlayarak mı? 

beraberce beslemek mi gerek,

zaten yüklü olan sıkıntı alanını? 

olguya katkın olursa ne ala.

ama n’olur ortaklaşma adına

olumsuzu hemence benimseme.

ağıt değil, bir şarkı olsun yaşamın

notalar sınırlı, herkese aynı ama,

sen iyiyi, doğruyu ve güzeli bestele.', 'sevinçtir ilacı acının, bir gülümseme kurutur gözyaşlarını. ne denli derinse de hüsran ve hüzün mutsuzluğu mutluluk seyreltir ancak. paylaşa...', ARRAY['Türk Edebiyatı','Şiir','Güneş Davenport']::text[], 8.5, '{"poet":"Güneş Davenport","poet_slug":"gunes-davenport","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevinctir-ilaci-acinin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelen ve Giden', 'gelen-ve-giden-gunes-davenport-pqvio', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'her gelen, her giden,

kendini arıyordur

kendinden uzaklarda,

sende veya ‘başka’larda.

ve bulamayışının çaresizliğinde

ağırdır sevgi adına sunduğu

çöker üstüne, dağılırsın…

o kendi uçuşuna hazırdır yine

sen, paramparça kalırsın…', 'her gelen, her giden, kendini arıyordur kendinden uzaklarda, sende veya ‘başka’larda. ve bulamayışının çaresizliğinde ağırdır sevgi adına su...', ARRAY['Türk Edebiyatı','Şiir','Güneş Davenport']::text[], 8.5, '{"poet":"Güneş Davenport","poet_slug":"gunes-davenport","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gelen-ve-giden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuzluk', 'sonsuzluk-gunes-davenport-mson9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'serçe için kafesinin ötesidir sonsuzluk,

karınca için de bir tepenin arkası…

insansa öteleri de öteler,

zihnin o koşumsuz atında.

ve uzanır uzaklara

tüm yorgunluğunca.

sonra…

bir an dalar yüreğine

duyumsar sonsuzluğu sonluluğunda

yakında, çok yakınında…', 'serçe için kafesinin ötesidir sonsuzluk, karınca için de bir tepenin arkası… insansa öteleri de öteler, zihnin o koşumsuz atında. ve uzanır ...', ARRAY['Türk Edebiyatı','Şiir','Güneş Davenport']::text[], 8.5, '{"poet":"Güneş Davenport","poet_slug":"gunes-davenport","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sonsuzluk-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Gibisin', 'ben-gibisin-gunes-davenport-5hf6m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'tıpkı ben gibisin,

yıllarca ve umarsızca

inanan ben gibisin.

sevgi diye yanmış, buralar-ötesi,

yorulmuş, yıpranmış, de ki, paramparça! 

ama değil mi ki vazgeçmemiş insandan,

hele de güzelliğe olan inadından,

evren de vazgeçmemiş ondan.

denemekten, sınamaktan,

yeni yeni paylaşımlar sunmaktan.

evet, tıpkı ben gibisin,

-kendime kaçışımdan bir önceki kapıda,

vazgeçişim-öncesi gibisin…', 'tıpkı ben gibisin, yıllarca ve umarsızca inanan ben gibisin. sevgi diye yanmış, buralar-ötesi, yorulmuş, yıpranmış, de ki, paramparça!  ama ...', ARRAY['Türk Edebiyatı','Şiir','Güneş Davenport']::text[], 8.5, '{"poet":"Güneş Davenport","poet_slug":"gunes-davenport","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ben-gibisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimse Tutunamadı', 'kimse-tutunamadi-umut-ulbegi-ultbt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Değiştim diyorum

değiştim diyorsun

değiştik diyorlar

--Kimse duyuramadı 

aşkın pilinin bittiğini düşünüyorum

aşkın pilinin bittiğini düşünüyorsun

aşkın pilinin bittiğini düşünüyorlar

--Kimse söyleyemedi

Mantık 

beş kıtayı yakıyor

ya aşk

ateşle eş anlamlıyken 

hangimizi selamlıyor...

Değişim 

dudaklarımızın ucunda

ya tutku

ölümle eş anlamlıyken

kimlerin kollarında...

Seviyorum diyorum

seviyorum diyorsun

seviyorum diyorlar

--Kimse tutunamadı

Ölümün olduğu yerde

dönüş te var

yalan da var...', 'Değiştim diyorum değiştim diyorsun değiştik diyorlar --Kimse duyuramadı  aşkın pilinin bittiğini düşünüyorum aşkın pilinin bittiğini düşünüy...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kimse-tutunamadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-nazife-abayli-pp04d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerinde ne bir öfke,

Ne de kin gördüm.

Ellerin kadar 

Sıcak,

Yüreğin kadar 

Mert,

Sözlerin kadar 

Sevecen,

Bakıyor onlar.', 'Gözlerinde ne bir öfke, Ne de kin gördüm. Ellerin kadar  Sıcak, Yüreğin kadar  Mert, Sözlerin kadar  Sevecen, Bakıyor onlar....', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gozlerin-89-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerini Acıtma Rüyalarınla', 'gozlerini-acitma-ruyalarinla-umut-ulbegi-bjqdx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Masmavi yatak

sıcak

iki rüya fazla görmek için

gözlerimi bırak 

gözlerin acıyacak

Aslına uygun

tasarlanmış taklitleri severim

en eski oyuncakçısıyım bu şehrin

oyunu bırak

Gittin gideli

yanıtsız

''seviyorum''lar

yaza kadar

kışlıklarda saklı kalacak', 'Masmavi yatak sıcak iki rüya fazla görmek için gözlerimi bırak  gözlerin acıyacak Aslına uygun tasarlanmış taklitleri severim en eski oyunca...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gozlerini-acitma-ruyalarinla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiye Dair', 'sevgiye-dair-ajda-meseli-ghbre', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Susamış bir cana su vermektir sevgi

Kanayan yaraya tuz basmaktır sevgi

Bir soğuk kış günü ısınmaktır

Yaşamı saran bir pırıltıdır sevgi.', 'Susamış bir cana su vermektir sevgi Kanayan yaraya tuz basmaktır sevgi Bir soğuk kış günü ısınmaktır Yaşamı saran bir pırıltıdır sevgi....', ARRAY['Türk Edebiyatı','Şiir','Ajda Meşeli']::text[], 8.5, '{"poet":"Ajda Meşeli","poet_slug":"ajda-meseli","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevgiye-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık', 'karanlik-gurbuz-vural-ouki4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karanlığı aydınlatan,bir gülümseme.

Gülümsemenin arkasında bir karanlık,

karanlığa gülümsüyorsun,

arkandaki karanlığa aldırmadan...', 'Karanlığı aydınlatan,bir gülümseme. Gülümsemenin arkasında bir karanlık, karanlığa gülümsüyorsun, arkandaki karanlığa aldırmadan......', ARRAY['Türk Edebiyatı','Şiir','Gürbüz Vural']::text[], 8.5, '{"poet":"Gürbüz Vural","poet_slug":"gurbuz-vural","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/karanlik-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-ajda-meseli-vwmj0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevgidir, aşktır dökülen damlalarda.

Ne güzel yağıyor yağmur dışarıda.

Alıp başını gideceksin böyle havalarda...

Gözünün gördüğü yere, güneşi görene kadar.

Yağmur gibi akar gözlerimden yaşlar.

Yalnızca bulutlar derdimi anlar.

Alıp başını gideceksin,diyar diyar...

Yağmur bitip derdin dinene kadar.

Var mıdır daha güzel bir sebat,

Yağmurda yürümek kadar? 

Yolunu kesecektir elbet karlı dağlar.

Yürümeli yine de alkım belirene kadar.

Çisil çisil yağmur dışarıda

Damla damla yaşlar yanağımda

Bedenim,pencere kenarında.

Hayalim,ufuklar ardında.

Yağmur gibi sevgiyle yoğruluyor dünya.

Tozdan,kirden yavaş yavaş arınıyor yollar.

Yağmur gibi aktıkça gözlerimden yaşlar 

Hüzünler biter yüreğimde,sevinçler başlar.', 'Sevgidir, aşktır dökülen damlalarda. Ne güzel yağıyor yağmur dışarıda. Alıp başını gideceksin böyle havalarda... Gözünün gördüğü yere, güneş...', ARRAY['Türk Edebiyatı','Şiir','Ajda Meşeli']::text[], 8.5, '{"poet":"Ajda Meşeli","poet_slug":"ajda-meseli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yagmur-101-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diş Ağrısı Gibi', 'dis-agrisi-gibi-ajda-meseli-41wpc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir diş ağrısı gibi sevdan.

Hani diş içten çürüdüğü zaman 

Anlayamazsın...

Bir sızı duyarsın,çikolata yediğin zaman.

Tadı yok olunca damağından

Acı da kalmaz hani...

İşte böyle bir şey:

Benim sana âşık olmam.', 'Bir diş ağrısı gibi sevdan. Hani diş içten çürüdüğü zaman  Anlayamazsın... Bir sızı duyarsın,çikolata yediğin zaman. Tadı yok olunca damağın...', ARRAY['Türk Edebiyatı','Şiir','Ajda Meşeli']::text[], 8.5, '{"poet":"Ajda Meşeli","poet_slug":"ajda-meseli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dis-agrisi-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanılgı', 'yanilgi-gurbuz-vural-7f0cn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yanılmışız meğer,

dolu dolu yaşadığımızı zannettiğimiz hayatta,

yalınmışız meğer.

yaşananlar yalanmış meğer.', 'Yanılmışız meğer, dolu dolu yaşadığımızı zannettiğimiz hayatta, yalınmışız meğer. yaşananlar yalanmış meğer....', ARRAY['Türk Edebiyatı','Şiir','Gürbüz Vural']::text[], 8.5, '{"poet":"Gürbüz Vural","poet_slug":"gurbuz-vural","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yanilgi-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-ajda-meseli-fulxq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen,

Ne ilk,ne de sonsun gönlümde.

Bir akşam üstüydü...

Tutuştu yüreğim,

Bir kibrit alevinde.

Sen,

Aşkı yeniden getirensin gönlüme.

Çalıp şu deli yüreği,

Fırlatıp atansın yerlere.

Sonra da yar olansın

Bambaşka bir sevgiliye.

Sen,tıpkı benim gibi

Ne istediğini bilmeyen...

Ama yoğrulmak isteyen sonsuz bir sevgiyle

Sen,

Hırçın esen rüzgarlar misali

Yüreğimde fırtınalar estiren

Bir meçhulsün sen.', 'Sen, Ne ilk,ne de sonsun gönlümde. Bir akşam üstüydü... Tutuştu yüreğim, Bir kibrit alevinde. Sen, Aşkı yeniden getirensin gönlüme. Çalıp şu...', ARRAY['Türk Edebiyatı','Şiir','Ajda Meşeli']::text[], 8.5, '{"poet":"Ajda Meşeli","poet_slug":"ajda-meseli","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sen-316-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitiş', 'bitis-ajda-meseli-wlh7f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dudağımda yalnızlık türküsü

Koyuldum yola.

Vakit geceyarısı gönlümde...

Terkedildim; 

Varamadan kavuşmanın tadına.', 'Dudağımda yalnızlık türküsü Koyuldum yola. Vakit geceyarısı gönlümde... Terkedildim;  Varamadan kavuşmanın tadına....', ARRAY['Türk Edebiyatı','Şiir','Ajda Meşeli']::text[], 8.5, '{"poet":"Ajda Meşeli","poet_slug":"ajda-meseli","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bitis-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulutlar Arasında', 'bulutlar-arasinda-ajda-meseli-36wi9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kâh toz pembe bulutlar dolaşır gökyüzünde,

Kâh kara bulutlar.

Aşkındır bana bunları yaratan.

Hayal penceremi açıp baktığım zaman,

Bazen uçarım, pembe bulutlar arasında.

Bazen de sefil hissederim kendimi,

Kara bulutların koynunda.', 'Kâh toz pembe bulutlar dolaşır gökyüzünde, Kâh kara bulutlar. Aşkındır bana bunları yaratan. Hayal penceremi açıp baktığım zaman, Bazen uçar...', ARRAY['Türk Edebiyatı','Şiir','Ajda Meşeli']::text[], 8.5, '{"poet":"Ajda Meşeli","poet_slug":"ajda-meseli","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bulutlar-arasinda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şerbetli Şiir', 'serbetli-siir-ajda-meseli-ntaue', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İşi ne zamanın? ! 

Akıp gidiyor işte...

Senli miyim, sensiz miyim

Aldırmıyor bile bu işe. 

Hayat sensiz de yaşanıyor ama 

Sen olduğun zaman yanımda,

Bir fincan şerbete benziyor hayat

Tam kıvamında.', 'İşi ne zamanın? !  Akıp gidiyor işte... Senli miyim, sensiz miyim Aldırmıyor bile bu işe.  Hayat sensiz de yaşanıyor ama  Sen olduğun zaman ...', ARRAY['Türk Edebiyatı','Şiir','Ajda Meşeli']::text[], 8.5, '{"poet":"Ajda Meşeli","poet_slug":"ajda-meseli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/serbetli-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Aşkıma', 'i-lk-askima-ajda-meseli-owkoy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sudan korkmak gibi bir şeydi,seni sevmek.

Oldum olası açılmadım hiç denizin derinliklerine.

Hep boğulmaktan korktum.

Dalgalar vurdukça yüzüme,

Ben kıyıya koştum.', 'Sudan korkmak gibi bir şeydi,seni sevmek. Oldum olası açılmadım hiç denizin derinliklerine. Hep boğulmaktan korktum. Dalgalar vurdukça yüzüm...', ARRAY['Türk Edebiyatı','Şiir','Ajda Meşeli']::text[], 8.5, '{"poet":"Ajda Meşeli","poet_slug":"ajda-meseli","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ilk-askima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akıtma Gözümün Yaşını Irmak Gibi', 'akitma-gozumun-yasini-irmak-gibi-ajda-meseli-1o7yn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akıtma gözümün  yaşını ırmak gibi.

Al kollarına sar beni.

Bir sevda yeli esti gönül bahçemde,

gönlüm gecelerce arzular seni.', 'Akıtma gözümün  yaşını ırmak gibi. Al kollarına sar beni. Bir sevda yeli esti gönül bahçemde, gönlüm gecelerce arzular seni....', ARRAY['Türk Edebiyatı','Şiir','Ajda Meşeli']::text[], 8.5, '{"poet":"Ajda Meşeli","poet_slug":"ajda-meseli","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/akitma-gozumun-yasini-irmak-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mısralar Arasında', 'misralar-arasinda-ajda-meseli-irv8s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu gece de sabaha vardım

Tükendi kelimeler. 

Uyku zamanıdır şimdi,

İçimi dökmüşüm beyaz sayfalara

Gönlüm rahat,

Hiç derdi kalmamışçasına. 

Gönül rahatlığıyla dal gönlüm

Güzel uykulara.

Sevgilin aramamış, boşver! 

Ne pembe rüyalar bekler seni şimdi...

Hakkındır,

Uyu da gör.', 'Bu gece de sabaha vardım Tükendi kelimeler.  Uyku zamanıdır şimdi, İçimi dökmüşüm beyaz sayfalara Gönlüm rahat, Hiç derdi kalmamışçasına.  G...', ARRAY['Türk Edebiyatı','Şiir','Ajda Meşeli']::text[], 8.5, '{"poet":"Ajda Meşeli","poet_slug":"ajda-meseli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/misralar-arasinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asla fırsat vermemişim', 'asla-firsat-vermemisim-nazife-abayli-5xgm5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Söyledikçe çoğalan,

Bir türküyle durulmuşum,

Aşka,sevdaya dair.

Büyümüşüm,

İnsan insan,

Yürek yürek.

Yaşamımdan,

Atmışım,

Yalanı,öfkeyi,

Kini,kibiri,

Süzmüşüm,

Hüzünlerden sevinci.

Bir yürekte eritip,

Sevgiyi bulmuşum.

Hız almışım yaşanası,

Her günden,

Herkesi kardeş bilmişim.

Karar kılıp dostlukta,

Ne yalana,ne dolana,

Ne kavgaya,ne gareze,

Asla fırsat vermemişim.', 'Söyledikçe çoğalan, Bir türküyle durulmuşum, Aşka,sevdaya dair. Büyümüşüm, İnsan insan, Yürek yürek. Yaşamımdan, Atmışım, Yalanı,öfkeyi, Kin...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/asla-firsat-vermemisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalıdan Görünüş', 'yalidan-gorunus-alaettin-isik-qm5lz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Penceremin süsüdür gemiler,

Sesler, kuş sesleri,

Kuşlar, martılar..

Renkler  mavi, yeşil,

Tonları farklı

Bir de kırmızılar var,

Yalnızca çatılar..

Odamın kokusunda deniz,

Onla yatar, ona uyanılır.

Perdeler kalkmış,

Karşımda dalga dalga gidiyor,

Sonra durup sakinler..

Deniz,

Sanki beni seyreyler.

Salına salına geçer vapurlar,

Düdük sesleri kulağımda.

O beyaz kuşların çığlığı,

Odamda yankılanır,

Bir an sanki uçarım..

...

Tek bir mekan seç deseler,

Hemen seni seçerim,

Çünkü bu şehri ben,

Sende yaşarım..

01/01/2004', 'Penceremin süsüdür gemiler, Sesler, kuş sesleri, Kuşlar, martılar.. Renkler  mavi, yeşil, Tonları farklı Bir de kırmızılar var, Yalnızca çat...', ARRAY['Türk Edebiyatı','Şiir','Alaettin Işık']::text[], 8.5, '{"poet":"Alaettin Işık","poet_slug":"alaettin-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yalidan-gorunus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin yerine', 'senin-yerine-nazife-abayli-pbj0u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevmek ve sevilmek,

Başlamış sende.

Yollara koyulmuşsun,

Tatlı bir hevesle.

Cancağazım,

Gönlüm düştü bir kez, 

Gönlüne,

Sen yorulma,

Kal orda,

Ben gelirim,

Senin yerine.', 'Sevmek ve sevilmek, Başlamış sende. Yollara koyulmuşsun, Tatlı bir hevesle. Cancağazım, Gönlüm düştü bir kez,  Gönlüne, Sen yorulma, Kal ord...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/senin-yerine-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayallerim ve sen', 'hayallerim-ve-sen-ferit-teksoy-3u3za', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çıksam yükseklere bulutlara ulaşsam

Bir kolumda tabularım diğerinde sen

Fırlatsam tabularımı yüksekten kayalara

Bin parça etsem...

***

İndirsem diğer kolumdan seni ıssız adaya

Kıyısında hayallerim ve içinde sen

Yaksam tüm gemileri çaksam kibriti

Küllerini savursam...

***

Bir sen olsan o adada birde ben

Tepemizde kızgın güneş bir o yaksa bir sen

Bir o yaksa bir ben yaksam

Yaksam,kavursam.

31 Ekim 2002', 'Çıksam yükseklere bulutlara ulaşsam Bir kolumda tabularım diğerinde sen Fırlatsam tabularımı yüksekten kayalara Bin parça etsem... *** İndir...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hayallerim-ve-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha Çok', 'daha-cok-bekir-mutlu-gokcesu-1a04r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Daha çok gülmeli

Daha çok sevmeli

Daha çok el ele vermeli

Daha çok konuşmalı

Daha çok söylemeli

Daha çok sarılıp

Daha çok sarmalamalı

Ve daha çok inanmalı

Aldanmak pahasına

Yenilendi yıl

Yenilenme zamanı

Güneşi ziyan etmemeli

Daha çok olmalı', 'Daha çok gülmeli Daha çok sevmeli Daha çok el ele vermeli Daha çok konuşmalı Daha çok söylemeli Daha çok sarılıp Daha çok sarmalamalı Ve dah...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/daha-cok-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su Romantik Oruspuluk', 'su-romantik-oruspuluk-sores-welat-demir-mn7hj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben dedim dogru dedim iyi halt ettim sanki

Aslinda ne romantik seydir 

			var ya su oruspuluk,..', 'Ben dedim dogru dedim iyi halt ettim sanki Aslinda ne romantik seydir  			var ya su oruspuluk,.....', ARRAY['Türk Edebiyatı','Şiir','Sores Welat Demir']::text[], 8.5, '{"poet":"Sores Welat Demir","poet_slug":"sores-welat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/su-romantik-oruspuluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Tarihle Yargilayin', 'beni-tarihle-yargilayin-sores-welat-demir-ke6of', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yasak bir kandil alevinin

Yasaklanmis karanliga isildadigi bir iz

Yahut sinirlari asan kacak bir bulut degilim ben.

Beni imgelerden sor güzelim

Felsefeyle anla, bilimle, ilimle ve yüzüme gül

Ve unutma 

Beni her zaman tarihle yargila 

Cünkü ben bir erkegim,..

(Besinci Mevsim adli siir kitabindan)', 'Yasak bir kandil alevinin Yasaklanmis karanliga isildadigi bir iz Yahut sinirlari asan kacak bir bulut degilim ben. Beni imgelerden sor güze...', ARRAY['Türk Edebiyatı','Şiir','Sores Welat Demir']::text[], 8.5, '{"poet":"Sores Welat Demir","poet_slug":"sores-welat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/beni-tarihle-yargilayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen misin...', 'sen-misin-dilek-farhood-k369f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen misin bana anne diyecek,

Sen misin kalbinden sevgi verecek,

Sen misin belki de bana benzeyecek,

Sen misin beni mutlu edecek? 

****

Sen misin bana gulumseyecek,

Sen misin kucagima guller serecek,

Sen misin dunyayi kesfedecek,

Sen misin yarinima umut verecek? 

****

Sen misin bizleri sevince bogacak,

Sen misin minigim dunyama dogacak,

Sen misin gunesim beni isitacak,

Sen misin canimin parcasi nurum olacak? 

****

Sen misin askimizin lezzetli meyvesi,

Sen misin bizim icin yasam gayesi,

Sen misin simdiden evimizin nesesi,

Sen misin hayatimin buyuk hediyesi', 'Sen misin bana anne diyecek, Sen misin kalbinden sevgi verecek, Sen misin belki de bana benzeyecek, Sen misin beni mutlu edecek?  **** Sen m...', ARRAY['Türk Edebiyatı','Şiir','Dilek Farhood']::text[], 8.5, '{"poet":"Dilek Farhood","poet_slug":"dilek-farhood","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sen-misin-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annenin Kizina Mektubu (I)', 'annenin-kizina-mektubu-i-sores-welat-demir-4xke0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ANNENIN KIZINA MEKTUBU -I

Actim

Susuzdum

Ben degil Gülüm ölmesin diye gittim ele

Bakmadilar

Alay edip güldüler

git dediler

Gittim

Kapi kapi dolastim

Bebegim dedim

Ölüyor dedim

Adi gül dedim

Gül yasamali dedim

Acidilar

Acinmak istemiyorum dedim

Yalnizca yardim edin dedim

Utandilar

Yüzleri burustu

Sanki hatali olan bendim

Sanki bendim utanilacak bir sey yapan

Sanki yardim istemek suctu o gün

Ah kizim, evladim

Üzgünüm

Bin kez kirdilar körpe dallarimi

Bin kez yiktilar hayallerimi

Sana caldigim sütü veriyorum

Affet kizim beni, n''olur affet

Bütün ayiplari ben yükleneyim,..

(Besinci Mevsim adli siri kitabindan)', 'ANNENIN KIZINA MEKTUBU -I Actim Susuzdum Ben degil Gülüm ölmesin diye gittim ele Bakmadilar Alay edip güldüler git dediler Gittim Kapi kapi ...', ARRAY['Türk Edebiyatı','Şiir','Sores Welat Demir']::text[], 8.5, '{"poet":"Sores Welat Demir","poet_slug":"sores-welat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/annenin-kizina-mektubu-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakma Sen Ağladığıma', 'bakma-sen-agladigima-yasar-pullu-lj0dh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Piç bir tohum düşmüş içine...

Ayrık otu tanımaz 

bir deli fişkın ım bende...

..........................................................

Bakma sen ağladığıma

çaklallar tam tedbir

üzerimde gezerken.

Bizim köye değeneksiz girilmiyor hala

Evet seni seviyorum

ağlamam ondan değil

sana yalvarmamda

al aşkını kurtar beni

yüzünde sürgün izleri

dilencilik yapamaz ki bu sevda.

De ki bir serçe vuruldu

puşt bir şafakta

bir şahin uçtu

bize de ayrılık düştü....

Artık seni beklemiyorum

karanlık sokaklarda

sende bakma karlı dağlara.....', 'Piç bir tohum düşmüş içine... Ayrık otu tanımaz  bir deli fişkın ım bende... .......................................................... Bakm...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Püllü']::text[], 8.5, '{"poet":"Yaşar Püllü","poet_slug":"yasar-pullu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bakma-sen-agladigima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babanin Cocuguna Mektubu (I)', 'babanin-cocuguna-mektubu-i-sores-welat-demir-ag7ba', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Üsüyordum

Hastaydim

Ben degil Umutum ölmesin diye gittim ele 

Kactilar

Yalan icin binbir dereden su getirdiler

Dolastim

Onurmus gururmus artik dinlemedim

Sokak sokak kapi kapi dilendim

Gözüm icin 

Yüregim icin

Bir tanecik Umut''um icin dedim

Üzüldüler 

Dua ettiler

Ben duanizi degil yardiminizi istiyorum dedim

Gittiler

Sanki yardim istemek suctu 

Sanki yardim duayla karsilanabiliyordu

Sanki dilsiz kaldim o gün

Ah oglum, evladim bir tanecik yüregim

Bin kez kirdilar hep onardigim yüregimi

Bin kez korkuya cevirdiler dünyami

Sana caldigim ilaci veriyorum

Affet oglum beni, affet

Günahini bir milyon kez ben cekeyim,..

(Besinci Mevsim adli siir kitabindan)', 'Üsüyordum Hastaydim Ben degil Umutum ölmesin diye gittim ele  Kactilar Yalan icin binbir dereden su getirdiler Dolastim Onurmus gururmus art...', ARRAY['Türk Edebiyatı','Şiir','Sores Welat Demir']::text[], 8.5, '{"poet":"Sores Welat Demir","poet_slug":"sores-welat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/babanin-cocuguna-mektubu-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatımın güzeli', 'hayatimin-guzeli-zulfikar-geyik-ct7uh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen hayatımın en güzeli (yıldızı) 

Ben hayatın anlamsızı? 

Sen sevgimin en güzeli (baharı) 

Ben sevginin laneti? 

Sen çölde narin çiçek

Beni senin hasretin bitirecek? 

Sen dünyada bir melek

Ben hayatta kaybolmuş sefalet? 

Sen ölümün suskunluğu? 

Ben hayattın anlamsızı

Sen hayatın güzeliği? 

Ben hayatın içindeki düşü? 

                                                             zülfikar geyik

                                                                           01 01 2004', 'Sen hayatımın en güzeli (yıldızı)  Ben hayatın anlamsızı?  Sen sevgimin en güzeli (baharı)  Ben sevginin laneti?  Sen çölde narin çiçek Beni...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Geyik']::text[], 8.5, '{"poet":"Zülfikar Geyik","poet_slug":"zulfikar-geyik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hayatimin-guzeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Kimdim?', 'ben-kimdim-bekir-mutlu-gokcesu-gd7ix', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kendim

İçimde bir yerlerde 

Başlayan

Deniz aşırı, dağ ötesi

Nerede bittiğini bilemediğim

Küçük dünyam

Gözüm bir yerlerden ısırıyor

Ben kimdim?', 'Kendim İçimde bir yerlerde  Başlayan Deniz aşırı, dağ ötesi Nerede bittiğini bilemediğim Küçük dünyam Gözüm bir yerlerden ısırıyor Ben kimdi...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ben-kimdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cocugun Anne ve Babasina Mektubu (ı)', 'cocugun-anne-ve-babasina-mektubu-i-sores-welat-demir-ofjfy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ÇOCUĞUN ANNE VE BABASINA MEKTUBU - I

Güzel annem

Cici babam

Büyüdüm

Yeşerdim

Biliyorum çok çektiniz

Bin kez yaraladilar yüreğinizi

Bin kez korkuya boğdular gecelerinizi

Bin kez ölümlediler

Ayıpladılar sizi

Ama yinede doğumdayız

İşte yine sevinçteyiz yeni bir yaşam için

Yeni güller ve yeni umutlar için

Ve unutmayacağız 

Gün gelecek büyük kavgalarımıza 

Anı deyip güleceğiz hep birlikte ağlayacağız

Ve yükselecek bütün yeryüzü 

Aşkın ışıltılarıyla parıldayıncaya dek

Siz kötü hiçbir şey yapmadınız ki

Anne baba

Sağolun!

(Beşinci Mevsim adlı şiir kitabindan)', 'ÇOCUĞUN ANNE VE BABASINA MEKTUBU - I Güzel annem Cici babam Büyüdüm Yeşerdim Biliyorum çok çektiniz Bin kez yaraladilar yüreğinizi Bin kez k...', ARRAY['Türk Edebiyatı','Şiir','Sores Welat Demir']::text[], 8.5, '{"poet":"Sores Welat Demir","poet_slug":"sores-welat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/cocugun-anne-ve-babasina-mektubu-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzünüz Gülsün', 'yuzunuz-gulsun-sores-welat-demir-6y6pa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'YÜZÜNÜZ GÜLSÜN

Kahreden bir acidir belki her gidis

Her veda uzun yolculuklarin basladigi anda

Ama kimse akil etmedi defterine not düsmeyi

Asklari, birliktelikleri, anilari,..

Yüzünüz gülsün

Yoksa daha cok zor olur, hasretlikler icin

Gülün bir defa daha

Ki kolay olsun gidenler icin,..

(Besinci Mevsim adli siir kitabindan)', 'YÜZÜNÜZ GÜLSÜN Kahreden bir acidir belki her gidis Her veda uzun yolculuklarin basladigi anda Ama kimse akil etmedi defterine not düsmeyi As...', ARRAY['Türk Edebiyatı','Şiir','Sores Welat Demir']::text[], 8.5, '{"poet":"Sores Welat Demir","poet_slug":"sores-welat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yuzunuz-gulsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Kaybetmedik Gidenleri', 'biz-kaybetmedik-gidenleri-melih-coskun-a5i0t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biz kaybetmedik gidenleri 

Gidenler kaybetti aslında sevgimizi...

Belki de hiç bilmediler 

Böyle sevildiklerini 

Belki korktular 

Bu kadar sevilip de sevememekten 

Biz kaybetmedik sevmeleri 

Onlar kaybetti aslında bizi...', 'Biz kaybetmedik gidenleri  Gidenler kaybetti aslında sevgimizi... Belki de hiç bilmediler  Böyle sevildiklerini  Belki korktular  Bu kadar s...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/biz-kaybetmedik-gidenleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahraman', 'kahraman-adnan-ferit-nsfm8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Önüm arkam sağım solum sobe,

kendim yumdum,

kendim saklandım

ve yaşam boyu hep kendimi sobeledim.

Misketlerim vardı çok,

hiç eksilmediler,

hiç çoğalmadılar da.

Çünkü hep kendimle oynadım,

hep kendimi yendim

hep kendime yenildim,

kazanan da kaybeden de her zaman bendim.

Ebesi de bendim, 

sobeleneni de yaşamımın.

Yaşamdan üttüklerimle

yaşama ütüldüklerimi,

hiç bir zaman dert etmedim.

Bir hayal kahramanıydım aynı zamanda.

Uçan halımda,

Sinbad bir yanımda

Peter Pan diğer yanımda.

Onlarla oynadım,

onlarla yaşadım.

Fasulyeden de oynasam

kahramandım kendi dünyamda..', 'Önüm arkam sağım solum sobe, kendim yumdum, kendim saklandım ve yaşam boyu hep kendimi sobeledim. Misketlerim vardı çok, hiç eksilmediler, h...', ARRAY['Türk Edebiyatı','Şiir','Adnan Ferit']::text[], 8.5, '{"poet":"Adnan Ferit","poet_slug":"adnan-ferit","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kahraman-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokun Bana Aşkınla', 'dokun-bana-askinla-oguzkan-bolukbasi-xrsik', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Taşıdığım, yılların coşkusu

İçimde bir damla su 

Gibi aslında

Damlasa taşıracak nehirleri

Ellerin tiriyorken tuttuğun gülleri

Düşürme yere

Bekle 

Sana yürüyorum göğsümü gere gere

Sensizliğin tükenmesinin başlangıcındayım

Yolun ucunda duruyorsun

Çağırıyorsun

Bir yarım kalmış günü tamamlamaya

Zerdalilerin çağla zamanı

Kayısı ağacındayım

Seninle 

Bir öpüşme arzusunu söylediğimde

Aşağıya ittiğin daldayım

Şimdi buradayım

Öpecek misin beni

İtecek misin beni

Taşıdığım, yılların coşkusunu

Yani

Yüreğindeki bir damla suyunu

İçmeye geldim

Sun bana

Dokun bana……….', 'Taşıdığım, yılların coşkusu İçimde bir damla su  Gibi aslında Damlasa taşıracak nehirleri Ellerin tiriyorken tuttuğun gülleri Düşürme yere B...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/dokun-bana-askinla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakın', 'sakin-bekir-mutlu-gokcesu-9bypp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bilemezsin

Nasıl özlediğimi

Bilme zaten

Anlamazsın 

Nasıl sevdiğimi

Anlama

Sorma halimi

Sorma sakın

Sen kadar özgürüm

Sen kadar sana yakın

Ben de seviyorum 

Deme sakın', 'Bilemezsin Nasıl özlediğimi Bilme zaten Anlamazsın  Nasıl sevdiğimi Anlama Sorma halimi Sorma sakın Sen kadar özgürüm Sen kadar sana yakın B...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sakin-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölü III', 'olu-iii-ahmet-aksoy-298j9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kimse yokluğunu hissetmiyorsa

……….yoksun,

ama bu hiç var olmadığın

……anlamına gelmez.', 'kimse yokluğunu hissetmiyorsa ……….yoksun, ama bu hiç var olmadığın ……anlamına gelmez....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/olu-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostlar', 'dostlar-sukran-gunay-pcq0q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'DOSTLAR

Yaşlandıkça akıllandım sanır insan, oysa her sabah yeniden doğar her can.

Senelerin kucağında nice arkadaşlarım oldu, her gördüğümü dostum sandım. Her birine gönülden bağlandım.

Dost sandıklarım, zemheride yapayalnız bıraktılar. Kimileri çıkarları bitince pabucumu dama attılar.

Birileri hiç beklemediğim zamanlarda çaldılar kapımı. Hızır denen bunlar galiba dedim zihnimde; odsuz ocaksız yuvamda yaktılar ocağımı.

Dostlar edindim, dilleri gönülden. Güller sundular öpülesi gönüllerinden. Sazı sözü hoş bildim, yüreğime sevgiler ektim. 

Dostlarım oldu etrafımı saran, sözleri ama canımı yakan. Vicdanım karşıma çıktı, eğrilerim ağır bastı. Oh be! Ne güzel! Her biri yollarıma ışık saçtı. Onlar, onlar ki hayatımda iyi ki vardı. 

Dost acı söyler yakarmış, pişmemiş cana bu yaraşırmış, cahil başım sağır Sultan’a bile ulaşmışmış.

Dostlar çıktı dağda bayırda, ummadığım anlarda, şu nice olduğunu bilmediğim zihnime; ektiler, ektiler, ektiler…

Yollarımı gündüz ettiler...

Şükranca', 'DOSTLAR Yaşlandıkça akıllandım sanır insan, oysa her sabah yeniden doğar her can. Senelerin kucağında nice arkadaşlarım oldu, her gördüğümü ...', ARRAY['Türk Edebiyatı','Şiir','Şükran Günay']::text[], 8.5, '{"poet":"Şükran Günay","poet_slug":"sukran-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dostlar-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seveceksen Şimdi Sev,Beş Dakika Sonra Değil', 'seveceksen-simdi-sev-bes-dakika-sonra-degil-murat-nail-guney-5n9l1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seveceksen beni, şimdi sev,

Beş dakika sonra değil.

En çok şu an ihtiyacı var  gönül bağımın çiçeğe,

Gideceksen; şimdi git,

Unut aşkımı, seven yüreğimi,

Al bendeki hatıralarını...Şimdi al,

Beş dakika, beş ay, beş yıl sonra değil...

Sen de kopacaksan...Tam alışmışken yüreğim sıcaklığına,

Şimdi kop,

Beş dakika, beş ay, beş mevsim sonra değil...

Bilsin ki; zavallı, kimsesiz, deli yüreğim yokluğunu,

Ben de vazgeçeyim bu beş para etmez hayattan...

Şimdi kıracağım ruhumu hapseden zincirleri bir seferde,

Şimdi mahrum edeceğim kaderimi, bana zulmetme şansından,

Şimdi indireceğim gözlerime kurşundan perdeleri, sonsuza dek,

Görmesin başka yalan gözleri, ağlamasın için-için diye...

Bir dakika bile beklemeyeceğim, güneşin yeniden doğuşunu,

Aydınlatmayacak nasılsa sensizliğin kör karanlığını,

Ve şimdi son darbeyi vuracağım beni yanıltan kalbime,

Bu gece bitireceğim sıradaki acıları, beş dakika sonra değil...

Bir yemin et, Bir söz ver bana Seveceksen. Sınırsız...Dupduru...

Hatalarımla, günahlarımla, olduğum gibi sev beni seveceksen.

BEŞ DAKİKA DÜŞÜNME, SENİ UNUTMUŞ OLABİLECEĞİM İHTİMALİNİ...

Beş mevsim, beş asır bekletme beni yokluğunun açmazlarında...

Beş dakika sonra gel, Capcanlı, sımsıkı sar üşüyen yüreğimi...

Beş dakika yaşamaz bu deli yürek sensiz nasıl olsa küçüğüm...

Varlığınla yokluğunun arasında bırakma beni beş dakika bile,

Ya gerçekten ver yüreğini koşulsuz, ya gerçekten git acılarım büyümeden.

Git ki,           

Ben de beş dakika beklemeyeyim sensiz yaşamak için,

Gideyim adam gibi, alıp başımı dünyadan beş dakika sonra...

Bilmesin kimse, deli sevdamın benden önce bittiğini,

Üşümesin sevgisizlikten kocaman yüreğim...

Şarkılar da bensiz kalsın, şiirlerde,aşklar da bu yaz,

Yaşamın acılarını, başka sevenler çeksin biraz...

İster yak at, Hasretinle sana her gece yazdıklarımı,

İster sakla kalbinin bir köşesinde yer varsa anılarımı.

Çok güzel şeyler yaşadım içimde sayende,

Bir gün gidersen biriciğim: 

MUTLULUK DİLEKLERİM KALSIN SENDE...', 'Seveceksen beni, şimdi sev, Beş dakika sonra değil. En çok şu an ihtiyacı var  gönül bağımın çiçeğe, Gideceksen; şimdi git, Unut aşkımı, sev...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/seveceksen-simdi-sev-bes-dakika-sonra-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin yalnızlığın', 'senin-yalnizligin-aydin-bayrakdar-9bsy8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir düşünce aldı beynimi dün akşcam

düşündüm seni sevebilir miyim diye

öyle ya sevmek de hak ister

sevilen bunu benden zor öğrenir ne desem

insanların sana hayranlığını görürüm

bu minvalde yaralarım depreşir

kimse açamaz sana sevgisini

senin erdemin bunu engeller

ben de bu mağdurlardan biriyim

sonunda karar verdim tek başıma

seni asla sevmeyeceğim

öğrendim çevrendeki insanların 

armudun iyisini bana yedirmeyeceğini

senin için üzülmedim desem yalan olur

nerde kaldı sana kavuşmak

hiçbir aşığın sana aşkını açamadı

bu da seni yalnızlığa bağladı', 'bir düşünce aldı beynimi dün akşcam düşündüm seni sevebilir miyim diye öyle ya sevmek de hak ister sevilen bunu benden zor öğrenir ne desem ...', ARRAY['Türk Edebiyatı','Şiir','Aydın Bayrakdar']::text[], 8.5, '{"poet":"Aydın Bayrakdar","poet_slug":"aydin-bayrakdar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/senin-yalnizligin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Muskasını Takmaz', 'ask-muskasini-takmaz-bekir-gedikoglu-g82dj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nazlı olan bu kalbim

Beklemekten güverdi

Kalbimin kapısını

 Kimse çalıp girmedi

Şu leziz dudaklarım

Yıllardır öpülmedi

Ateşimi alacak

Kimse ilaç vermedi

Yanaklarım güzeldir

Amor’u hiç aratmaz

Neden biri gelipte

Bunları hiç okşamaz

Gözlerimiz renkleri

Dünyaya destan oldu

Merak edip görecek

Bir aşık olmuyordu

Boynumun güzelliği

Kuğuları aratmaz

Güzellerden birisi

Aşk muskasını takmaz

Ankara,  1 Ocak 2004', 'Nazlı olan bu kalbim Beklemekten güverdi Kalbimin kapısını  Kimse çalıp girmedi Şu leziz dudaklarım Yıllardır öpülmedi Ateşimi alacak Kimse ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ask-muskasini-takmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Yıl', 'yeni-yil-hafize-zuluflu-b9nm1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu gün yıl yeni

Sevdam eskisi gibi

canım benim

belki bu yıl bana bir armağan verirsin

faksından sonra

kendin gelirsin....', 'Bu gün yıl yeni Sevdam eskisi gibi canım benim belki bu yıl bana bir armağan verirsin faksından sonra kendin gelirsin.......', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yeni-yil-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanat', 'sanat-celal-sahin-79j03', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hileye kanmış

Cennet Bahçesinden kovulmuş,

Yaratılmış

Eski günlerini arar olmuş,

Her güzelliği sanatlaştırmış:

Resim yapma sanatı,

Yemek pişirme sanatı,

Güzel konuşma sanatı,

Para kazanma sanatı,

Mutlu olma sanatı..........

Bütün sanatlar birleşip 

Tek bir sanat adını koyamamış; 

SEVGİYLE YAŞAMA sanatı', 'Hileye kanmış Cennet Bahçesinden kovulmuş, Yaratılmış Eski günlerini arar olmuş, Her güzelliği sanatlaştırmış: Resim yapma sanatı, Yemek piş...', ARRAY['Türk Edebiyatı','Şiir','Celal Şahin']::text[], 8.5, '{"poet":"Celal Şahin","poet_slug":"celal-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sanat-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Yalancısı', 'askin-yalancisi-ceyda-ayfer-oz-hqcvx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güneşin doğduğu yerdeyim

Arayışların bittiği gökkuşağı çizgisinde

Pamuk bulutların içinde

Gökyüzünün üstündeyim

Ellerim üşümüyor ki

Sen gidince boynum bükük kalmadı

Sana dair şiir yazmadım ki hiç

Söyleyecek bir sitemim olmadı

Sen kimdin ki arkadan ağlayacaktım

Ne paylaşmıştık ki hatırlayayım

İlk paragrafı ben yazmamıştım ki

Son noktayı koyan ben olayım

Sen ki hiç benim olmayan

Kaçak bir tavşan

Uçup uçup rüzgarında mı savrulayım

Hayattan çalıp çalıp

Hepsini sana mı sunayım

Sen benim olmadın ki hiç

Aşkın yalancısıydın

Neden sana inanayım

Bana ne söyledin ki

Uykumda sesini duyayım

Seni deli gibi özlemem için ne sebep var

Ben de aşkın yalancısıyım

Yolun açık olsun

Arkana hiç bakma ki

Aklında hep böyle kalayım!', 'Güneşin doğduğu yerdeyim Arayışların bittiği gökkuşağı çizgisinde Pamuk bulutların içinde Gökyüzünün üstündeyim Ellerim üşümüyor ki Sen gidi...', ARRAY['Türk Edebiyatı','Şiir','Ceyda Ayfer Öz']::text[], 8.5, '{"poet":"Ceyda Ayfer Öz","poet_slug":"ceyda-ayfer-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/askin-yalancisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben~deniz', 'ben-deniz-ceyda-ayfer-oz-kdfy2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Denize bakarken

Denize akarım ben

Mavi dedin mi

Yeşile çalarım ben

Gri oluverir 

Coşar çoşar da,

Deniz olurum ben, 

Deniz olur ben…', 'Denize bakarken Denize akarım ben Mavi dedin mi Yeşile çalarım ben Gri oluverir  Coşar çoşar da, Deniz olurum ben,  Deniz olur ben…...', ARRAY['Türk Edebiyatı','Şiir','Ceyda Ayfer Öz']::text[], 8.5, '{"poet":"Ceyda Ayfer Öz","poet_slug":"ceyda-ayfer-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ben-deniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorsan', 'sorsan-vedat-sarapci-8rlga', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eğer sevda nedir diye sorsan,

Seni tarif ederdim,

Eğer özlem nedir demiş olsan,

Senin diğer adın derdim,

Eğer çiçekler solmuş desen,

Çiçeklere ne gerek,

Sen varsın ya derdim.

(İstanbul, 26 Nisan 2001)', 'Eğer sevda nedir diye sorsan, Seni tarif ederdim, Eğer özlem nedir demiş olsan, Senin diğer adın derdim, Eğer çiçekler solmuş desen, Çiçekle...', ARRAY['Türk Edebiyatı','Şiir','Vedat Şarapcı']::text[], 8.5, '{"poet":"Vedat Şarapcı","poet_slug":"vedat-sarapci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sorsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benden Bıkmışsın Demek...', 'benden-bikmissin-demek-ceyda-ayfer-oz-oh2l3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Olmamaktan yana mı saymalı cümleleri

İçinde büyütürken eksilmişlikleri,

Saymadan mı gitmeli yoklukları,

Varlıkların altında mı ezilmeli, /yok etmeli! 

Senden haber almadan mı geçirmeli saatleri,

Cendereler sokağında mı tüketmeli adresleri,

Bilmemeli mi yolların kapalı olduğunu,

Sana ulaşmamalı mı, /boyun mu bükmeli kahpe kadere,

Sen mi olmalısın yanı başımda,

Ben mi olmalıyım bir terk-i diyar kervanında…

Akmasın mı yaşlar, sen olmadığın anlar,

Konuşmasın  mı bu yürek,

/Sus…Nasılsa gözlerimden anlar…

Ben sana demedim mi suskunluğumun en şiddetli sesisin diye? 

Anlamadıysan bırak, belki bir anlayan çıkar…

Ben şimdi en yoğun hava kümesi,

En şiddetli şimşek ötesi bir sarsılma ile

Kanat çırparken sana varmaya sebep,

Sen kaç kaçabildiğince

Benden bıkmışsın demek…', 'Olmamaktan yana mı saymalı cümleleri İçinde büyütürken eksilmişlikleri, Saymadan mı gitmeli yoklukları, Varlıkların altında mı ezilmeli, /yo...', ARRAY['Türk Edebiyatı','Şiir','Ceyda Ayfer Öz']::text[], 8.5, '{"poet":"Ceyda Ayfer Öz","poet_slug":"ceyda-ayfer-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/benden-bikmissin-demek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsim Sonbahar', 'mevsim-sonbahar-ceyda-ayfer-oz-ixomn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kuşlar susmak üzere

Mevsim ''Sonbahar''

Doğa örtüsünü örtmek üzere

Birisi ardına bakmadan

Gitmek üzere...

Kaç yıl geçmiş

Kaç mevsim

Gelişin-gidişin arasında

Bunca yıl kendimi mi eylemişim

Sonsuz mudur bu bekleyişim

Bahar geldi diye

Boşuna mı seslenişim

Yaz olmuş

Susuz kalmış da topraklar

Ben su diye yokluğunu içmişim

Sonbahar mı bu gülüm? 

Bu gidişin  bir ''son'' mu? 

Bu bekleyişin bir sonu yok mu? 

Son bir kez de olsa

Bahar artık gelmeyecek mi? 

Bu hüznüm hiç dinmeyecek mi? ..', 'Kuşlar susmak üzere Mevsim ''Sonbahar'' Doğa örtüsünü örtmek üzere Birisi ardına bakmadan Gitmek üzere... Kaç yıl geçmiş Kaç mevsim Gelişin-gi...', ARRAY['Türk Edebiyatı','Şiir','Ceyda Ayfer Öz']::text[], 8.5, '{"poet":"Ceyda Ayfer Öz","poet_slug":"ceyda-ayfer-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/mevsim-sonbahar-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Git!', 'artik-git-ceyda-ayfer-oz-ak7q8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tarif edilmez duygular içindeyim

Giden olup gidiyorum

Gelen olup susuyorum

Ardıma bakmadan

Geri gelemiyorum

Tarifsiz hüzünler içindeyim

Oysa hani hep güldürecektin beni

Solarsa bir gün didemin ışıkları

Hani çekip gidecektin

Gittin! 

Şimdi gitmiş mi oluyorsun

Issız bırakınca bütün evreni

Yaşanılası bir tat kalmamışken

Şimdi güldürmüş mü oluyorsun

Bu küçük şairini

Sustum! 

Tarifsiz bir suskunluk şimdi

Yazacak bir tebessümüm yok

Kelimeler sustu

İçimdeki ışıklar

Martılar

Doğa

Yüreğim

Hepsi sustu gidişinle

Git! 

Bir adım bile durma

Sustu göz pınarlarım çağlamıyor

Git! 

Adın yok semalarda

Git! 

Şarkın yok dilimde mırıldandığım

Git! 

Sana ait hiç bir şey yok bu diyarlarda

Git! 

Her şeyi al, her şeyi bırak ve

Git! 

Yeni sayfa açıyorum bak

Git ki açılsın beyazlıklar

Gün doğsun

Güneş doğsun

Çok üşüyorum

Artık Git! ...', 'Tarif edilmez duygular içindeyim Giden olup gidiyorum Gelen olup susuyorum Ardıma bakmadan Geri gelemiyorum Tarifsiz hüzünler içindeyim Oysa...', ARRAY['Türk Edebiyatı','Şiir','Ceyda Ayfer Öz']::text[], 8.5, '{"poet":"Ceyda Ayfer Öz","poet_slug":"ceyda-ayfer-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/artik-git-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mihnetim Olmayacak', 'mihnetim-olmayacak-murat-demir-1hwaj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Defter oldum gönlüne

Kalem olup yazmadın

Kitap olsaydım demek

Açıpta okumazdın

Yazma yada okuma

Mihnetim olmayacak

Anlaşıldı yüreğin

Beni anlamayacak

Name name kutuna

Her gün girdim almadın

Aradan yıllar geçti

Arayıpta sormadın

Alma yada hiç sorma

Mihnetim olmayacak

Bilki,bu güneş hergün

Tek sana doğmayacak

Mendil oldum eline

Paçavraya çevirdin

Götürmeden gözüne

Tel tel yapıp devirdin

Devir yada devirme

Mihnetim olmayacak

Bu zavallı kollarım

Seni saramayacak', 'Defter oldum gönlüne Kalem olup yazmadın Kitap olsaydım demek Açıpta okumazdın Yazma yada okuma Mihnetim olmayacak Anlaşıldı yüreğin Beni an...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/mihnetim-olmayacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Usta ve Çırak', 'usta-ve-cirak-oguzkan-bolukbasi-s6296', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayatın ustaları

Bilir yaşam lezzetini

Ağız tadı değildir bu

Gönüldür 

Tatlıya karışan

Acılardan ders alır

Özeti ışık saçan bir ömürdür

Hayatın çırakları

Yol bulmakta zorlanır

Kimi dağılır gider

Kimi bir ustaya kapılanır

İnsan olur yapılanır

Öğrenir aynı kapta karıştırmayı

Sevinci ve kederi

Gün gelir o da yakar

Işık saçan feneri

Kim ustadır

Kim çırak

Ediyor isen merak

Yol uzundur ömür kısa

Dokunduğun yürekte

Ellerin yanıyorsa

Gözlerin kamaşıyorsa

Her baktığında

Şanslısın 

İşte karşında usta

Sadece izini sür

Seni canana götürür', 'Hayatın ustaları Bilir yaşam lezzetini Ağız tadı değildir bu Gönüldür  Tatlıya karışan Acılardan ders alır Özeti ışık saçan bir ömürdür Haya...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/usta-ve-cirak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyleşi', 'soylesi-tabir-gokce-otclb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '- Dost''a-

Dedi ki; 

“gece mavisi düşüm”

Dedim ki; 

O en uzak yıldızlardan

Ve oldukça cömertçe

En karanlık gecelerden

Ve inanılmaz sevgilerce

Umutsuzluğun gölgesinden

Ve anlamlı gülüşlerle

Ve o eski sevgiliye

Mükemmel armağandır

İzdüşüm

Dedi ki; 

“düştüğüm yetim iz’im ben”

Dedim ki; 

Düşmüşse İz bir yüreğe

Ki yetim olmak niye? 

Duydum hüznün coşkuda

Kendine zulüm niye? 

Bak, gör yalnız değilsin

Yalnızsan bu can niye? 

Sevgiyle yaratıldın 

Hayata küsmek niye? 

Dedi ki; 

“İzlerim silik”

Dedim ki; 

Yaşamak, insan ömründen öte

Silik bir iz olsa bile

Sen ki ak kağıda düşmüşsün

Okuyan lal olsa gelir dile

Susma haykır gönlünce

Arda kalmasın sözün

Silinen izler olsun bırak

Bize yadigar özün

Dedi ki; 

“düşlerim yorgun”

Dedim ki; 

Güneştir yükselen uyan

Uyan artık sen bahar değil misin? 

Uyan ki hayat senin ardından gelsin

Yorulmak, tükeniştir düşte bile

Hazan, son değil 

Son değil hiçbir zaman

Dedi ki; 

“ölü baharım ben”

Dedim ki; 

Ölmez bahar, yanılgıdasın

Bahar başlangıçtır, sen hala başındasın

Unut kışı, kar, boran geride kalsın

Sen ki yepyeni hayata kırpıp gözlerini

Bağrında filizlenen çiğdeme bakacaksın

Efkarlıyım bu gün,', '- Dost''a- Dedi ki;  “gece mavisi düşüm” Dedim ki;  O en uzak yıldızlardan Ve oldukça cömertçe En karanlık gecelerden Ve inanılmaz sevgilerce...', ARRAY['Türk Edebiyatı','Şiir','Tabir Gökçe']::text[], 8.5, '{"poet":"Tabir Gökçe","poet_slug":"tabir-gokce","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/soylesi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Büyük Benim', 'en-buyuk-benim-burhan-gumus-oobvn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağıt yakmayacağım, biblos kadınları gibi.

Adonis’te kimmiş

En büyük benim

Paris gibi olacağım.Zampara Paris. Büyük ferdiyetçi.

Truvayı yakacağım. Lakin Hellen için değil

Benim Hellen’im başka

“Vur fakat dinle”de demeyeceğim. Ey! Atinalı

Şapşal, şımarık, zavallı general.

Dünlerim bugünleri aydınlatacak

Fenerler hiç sönmeyecek

Rüzgar gizli dehlizlerimden giremeyecek.

Artistlik yapmayacağım

Ne Sofakles

Ne de Shakespeare türü tragetyalarda oynamayacağım

Yıldızlara kayabaşı söylemeyeceğim

Lirik, epik ve de pastoral takılmayacağım

Hemde nostaljik ve romantik

Satim anasını

Ben miyim dünyanın delisi. Akıllıyım ben. Akıllı.

Bilin ki en büyük ülküm faustçu olmak

Düşünmek ve yaşamak ve de içtepi 

Ölesiye içtepi.

Başımı eğmeyeceğim

......................................ezeceğim.

kırılmayacağım

......................................kıracağım

Var mı diyeceğiniz Ben Sezarım

Taştan çıplak kadınlar yaratan Romalı

Kim demiş kadının adı yok diye

Külliyen yalan

İşte Afrodit, işte Artemis ve Keleopatra

Varlığımın ilaheleri

ACILARLA 

.....................yaşamayacağım

Faraza yaşanmış ne varsa

Aha çiziyorum

..........................koynumdan

..................................kafamdan

........................................yüreğimden atıyorum.

KURDUĞUM SARAYDA

zevk-ü sefa içinde

bir elim yağda

bil elim balda

KRALLAR GİBİ YAŞAYACAĞIM

Demokrasi nerde başlar nerde biter

Ülkeye dair

Evrene dair

Bilin ki benden sorulur.

En büyük benim. Ben.

Ben med-

yayım.

Med ve yay', 'Ağıt yakmayacağım, biblos kadınları gibi. Adonis’te kimmiş En büyük benim Paris gibi olacağım.Zampara Paris. Büyük ferdiyetçi. Truvayı yakac...', ARRAY['Türk Edebiyatı','Şiir','Burhan Gümüş']::text[], 8.5, '{"poet":"Burhan Gümüş","poet_slug":"burhan-gumus","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/en-buyuk-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Laf Ola (1)', 'laf-ola-1-tabir-gokce-kotrf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çok bilen çok yanılıyorsa eğer

Bilgi niye ki, Niye verilir değer? 

Rab bile “oku” dedi, 

Dört de kitap indirdi

O aksini düşünse

Cahile pirim verirdi

Bence bilmek adına çok fazla çalışmalı

Beyhude laf yerine bilgece konuşmalı', 'Çok bilen çok yanılıyorsa eğer Bilgi niye ki, Niye verilir değer?  Rab bile “oku” dedi,  Dört de kitap indirdi O aksini düşünse Cahile pirim...', ARRAY['Türk Edebiyatı','Şiir','Tabir Gökçe']::text[], 8.5, '{"poet":"Tabir Gökçe","poet_slug":"tabir-gokce","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/laf-ola-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Hamur', 'hayat-hamur-hakki-hakan-kaya-bbom7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir beyaz toz 

elinde senin hayat,

yatmış rüzgar pusuya

avı olmuş savurmak,

bir arada 

amaç olanları

tek bir 

amaçsız yapmak,

bir başka yaşam,

sıvı ve akışkan

tutamazsan elinden akar,

nemi kalır avucunda

parmaklarının 

arasından kayan,

yaşamın hamurudur

iki çekim noktası,

asıl olan varlıktır

kendi ellerinde

hamuru bulundur,

yoğur; 

istediğin şekli ver

kat kendini karıştır,

tatlıda olsa

acıda olsa

kendi hamurunu

kendin mayala

kendin pişir...', 'Bir beyaz toz  elinde senin hayat, yatmış rüzgar pusuya avı olmuş savurmak, bir arada  amaç olanları tek bir  amaçsız yapmak, bir başka yaşa...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/hayat-hamur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatın Yırtıklarını Dikiyorum', 'hayatin-yirtiklarini-dikiyorum-emin-baydil-mpacx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Vurmuş,

vurulmuşum habersiz,

kuzey rüzgârlarına, bağrım açık habire,

hepsi başımda benim; kar, fırtına ve tipi...

sonbaharımın artakalmış yenik ve yorgun şu günlerinde

ümitlerimi galebe çalmış yine zaman.

Bir taraflarım dökülmüş

ve kırağı düşmüş saçlarıma gün batımı.

Artık şebneme yer kalmamış, sabaha karşı

sanki, herşey dona çekmiş ve ölmüş...

Düşünmeme fırsat vermiyor,

patlayan şakaklarım... ense köküm...

Yapma be nazlı gülüm! ... Son yazım, olma benim! ..

hergün mü hergün küs

söyler misin hep böyle, bir ömür nasıl geçer? 

En sonunda, otuz yıllık bir dâvadan çıkan hüküm; 

geçmez ki bir gün daha, bu ayrılık mukadder...

Bir deprem geçirmiş kalbim,

yarıklarında aklım fikrim perişan,

başım gözüm kan revan

ve gözyaşlarım sele dönmüş, bendimi yıkmış....

Şu sıralar pek meşgulsün,

neler yapıyorsun? diye, soran olursa, onlara:

hayatın yırtıklarını, dikiyorum durmadan,

dişlerim de ağrıyor öte yandan,

ve ağzımda bir yumurtayla dolaşmaktayım,

görmüyor musunuz? 

Ya o çektirecek bana, günbegün hem de böyle,

ya da ben çektireceğim onları,

çaresi yok, diyorum...', 'Vurmuş, vurulmuşum habersiz, kuzey rüzgârlarına, bağrım açık habire, hepsi başımda benim; kar, fırtına ve tipi... sonbaharımın artakalmış ye...', ARRAY['Türk Edebiyatı','Şiir','Emin Baydil']::text[], 8.5, '{"poet":"Emin Baydil","poet_slug":"emin-baydil","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/hayatin-yirtiklarini-dikiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğitenler Utansın', 'egitenler-utansin-murat-demir-c0u4t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yok olurken,kazma kürekle var ettiğimiz

Her karışını,kanlarımızla suladığımız

Kana doymuş bu toprakların,kana ihtiyacı

Varmı sanıyorsunuz

Elin oğlu uzayın nimetlerinden yararlanırken

O ilkel dünyanızda siz neden? kimin için

Debeleniyorsunuz

Yok resimmiş,askermiş,asker sesiymiş....

Bunlar bayatladı artık,geçiniz bunları geçiniz

Görülmuyormu sanıyorsunuz,ortaçağ karanlıklarından gelen

Fikriniz,fikirleriniz

Anlaşılıyorki siz ulus milleti olmamış,kana doymamış

El etek sakal öpmekten kurtulamamışsınız

Gönderde dalgalanan bayrağımıza

Üzerinde özgürce gezdiğimiz topraklarımıza hiç bakmamışsınız

Hangi şartlarda,kimler sayesinde bizim oldu diye

Yarasalar ışığı ne zaman sevmiştirki

Sizi kınıyorsam namertim

Sadece acıyorum

Eğitenler utansın

Bu cumhuriyet sizi adam edemediğse

Gavur dediğiniz adamlar.............eder.', 'Yok olurken,kazma kürekle var ettiğimiz Her karışını,kanlarımızla suladığımız Kana doymuş bu toprakların,kana ihtiyacı Varmı sanıyorsunuz El...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/egitenler-utansin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan', 'i-nsan-i-brahim-yamac-rlr7f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'insan

ölümle hayat arasında

ucu açık iki turun kısa adı

hayat

iki acziyet bir kuvvet

ve ölüm

hayatın öz evladı', 'insan ölümle hayat arasında ucu açık iki turun kısa adı hayat iki acziyet bir kuvvet ve ölüm hayatın öz evladı...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yamaç']::text[], 8.5, '{"poet":"İbrahim Yamaç","poet_slug":"i-brahim-yamac","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/insan-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Yıl', 'yeni-yil-hatice-ari-1104l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yeni yıl derler,

Yeni erekler derler,

Neler neler umut ederler; 

Oysa karın doyurur mu umut? 

Sanma ellerinde bir lokma

Kağıt helva,

Ekmek bedava, 

Su bedava...

Yeni yıl derler,

Yeni erekler derler,

Yenileri umut ederler,

Ya eski yıl,

Ne oldu ona? 

Bir çizik üstüne.

Ya şu beden,

Onun katbekatı eski değil mi? 

Bak şu tene; 

Çizik çizik üstüne,

Bir de, altında 

Kendini görmeyi dene..', 'Yeni yıl derler, Yeni erekler derler, Neler neler umut ederler;  Oysa karın doyurur mu umut?  Sanma ellerinde bir lokma Kağıt helva, Ekmek b...', ARRAY['Türk Edebiyatı','Şiir','Hatice Arı']::text[], 8.5, '{"poet":"Hatice Arı","poet_slug":"hatice-ari","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yeni-yil-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fındık ve Fıtık,', 'findik-ve-fitik-caglar-akarsu-m1fin', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Fındık ve  Fıtık,

...

Konuşurken sürekli arkasından,

Dilimizde ki fındıkları,ağaçlardan,

Her gece,”pal ormanı”da topladık,

İçine öyle anlamlar doldu ki,

Elimizde bir çekiç kırdık,durduk,

Bir an, parmaklarımızda vurduk,

Anla işte, bir an,pir  olduk! ! 

...

Konuşurken insanlar, dinleyenler,

Sağlık sektörünü  sanki ihya etti,

Erkekler “ fıtık illeti” ile mustarip 

Kadınlar çene düşüklüğünde,öncü,

Tüm sözler zamane şartlarında,

Yarı hasta  olmuş ülkemizde,

Ağlarken,gülmeyi uygun gördük,

..

Sözleri dinlemek,  bazen işkence oldu,

Bol sirkeli işkembe, atıp tuttu,

Her sözün ve yazının anlamı farklı,

İnsan bu hiç belli olmuyor,işte! ! 

Bazen fındık oluyor, bazen fıtık.

...

Caglar akarsu', 'Fındık ve  Fıtık, ... Konuşurken sürekli arkasından, Dilimizde ki fındıkları,ağaçlardan, Her gece,”pal ormanı”da topladık, İçine öyle anlaml...', ARRAY['Türk Edebiyatı','Şiir','Cağlar Akarsu']::text[], 8.5, '{"poet":"Cağlar Akarsu","poet_slug":"caglar-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/findik-ve-fitik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gibiyim', 'gibiyim-hifzi-ozbekmez-cjzg8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beni de çok masum durgun sanmayın

Fırtınada esen yeller gibiyim

Şu garip halime bakıp kanmayın

Deresinden taşan seller gibiyim

Ne kadar bu gönlüm garip olsa da

Sevda güllerim açmadan solsa da

Kara bahtım acılarla dolsa da

Kar üstünde açan güller gibiyim 

Gurbet elin uzun dar yollarında

Ahtı mı almadım yar kollarında

Hayatın boş geçen zamanlarında 

Her daim perişan haller gibiyim

Kara sevdalara bir ömür vermiş 

Varını yoğunu bu yolda sermiş

Sevmişte canından daha çok sevmiş

Sevdasından coşan diller gibiyim

Her sevda sonunda perişan hali

Yarin mah cemaline lal olmuş dili

Ömrünün başında öteden beri

Ta dibinden kopmuş kollar gibiyim

Latifiyim bir mutluluk bulmamış

Bir cananı bir yareni olmamış

Ömrü boşa geçmiş zaman kalmamış

Elvedalar diyen eller gibiyim

2003', 'Beni de çok masum durgun sanmayın Fırtınada esen yeller gibiyim Şu garip halime bakıp kanmayın Deresinden taşan seller gibiyim Ne kadar bu g...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gibiyim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni İstiyor', 'seni-i-stiyor-hifzi-ozbekmez-3smta', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hasret ne zaman bitecek 

Bak gönül seni istiyor

Hasretin deli edecek

Bak gönül seni istiyor

Deli eder hasret beni

Gülüm çok özledim seni

Görmek için gül sineni

Bak gönül seni istiyor

Sözlerin mutlu etmiyor

Mektuplarında yetmiyor

Dertler çoğaldı bitmiyor

Bak gönül seni istiyor

Gündüz hayal gece düşte

Aşka düştüm ben bu yaşta 

Nasıl dersen öyle işte 

Bak gönül seni istiyor

Hayranım bir gonca güle 

Ne olur çektirme çile

İmkansızdır bile bile

Bak gönül seni istiyor

Uzayan gurbet yolunda

Öter bülbül gül dalında

Her gecenin sabahında

Bak gönül seni istiyor

Latifide oldu şaşkın

Deli edecek bu aşkın

Özlemin gönlümde taşkın

Bak gönül seni istiyor

2003', 'Hasret ne zaman bitecek  Bak gönül seni istiyor Hasretin deli edecek Bak gönül seni istiyor Deli eder hasret beni Gülüm çok özledim seni Gör...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/seni-istiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün Geleceğim', 'bir-gun-gelecegim-hifzi-ozbekmez-15xmj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilmiyorum nasıl niçin

Sana bir gün geleceğim

Mah cemalin görmek için

Sana bir gün geleceğim

Tutmak için ellerini

Görmek için gözlerini

Sevmek için yüzlerini

Sana bir gün geleceğim

Halin hatırın sormaya

Yanında bir gün kalmaya

Bilemem hangi haftaya

Sana bir gün geleceğim

Latifi sen sarmaya

Senden muradın almaya

Yanında köle olmaya 

Sana bir gün geleceğim

13 HAZİRAN  2003 CUMA SAAT: 05:00', 'Bilmiyorum nasıl niçin Sana bir gün geleceğim Mah cemalin görmek için Sana bir gün geleceğim Tutmak için ellerini Görmek için gözlerini Sevm...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-gun-gelecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyorsun', 'diyorsun-hifzi-ozbekmez-stftt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Söyle güzel bana söyle 

Beni nasıl seviyorsun

Bir dostmuyum sana böyle

Yoksa aşkım mı  diyorsun

Niyetin nedir bileyim

Göz yaşlarımı sileyim

Söyle kalbinde nerdeyim

Deli şaşkın mı diyorsun

Boşa heveslenip durma

Kendini de boşa yorma

Böyle şeyleri hiç sorma

Gönlün taşkın mı diyorsun

Kararsızım Latifiyim 

Ben sensiz dünya neyleyim

Sen söyle bende bileyim

Sınır aştın mı diyorsun

13 HAZİRAN  2003 CUMA SAAT: 05:30', 'Söyle güzel bana söyle  Beni nasıl seviyorsun Bir dostmuyum sana böyle Yoksa aşkım mı  diyorsun Niyetin nedir bileyim Göz yaşlarımı sileyim ...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/diyorsun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '2 Ocak 2004', '2-ocak-2004-oguzkan-bolukbasi-7ojn0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İş yerimdeyim

Yalnızım

Çalışanlara izin verdim çarşambadan

Pazartesiye kadar gelmeyin

Yeni yılda biraz daha zaman ayrın sevdiklerinize

Ben bakarım telefona

Temizliğe

Çalan zile

Kapıcıya

Postacıya 

Hayat için çalışmak lazım

Çalışmak için hayat değil

Sevindiler

Topu topu dört kişiydiler

Bugün gelmediler', 'İş yerimdeyim Yalnızım Çalışanlara izin verdim çarşambadan Pazartesiye kadar gelmeyin Yeni yılda biraz daha zaman ayrın sevdiklerinize Ben b...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/2-ocak-2004-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatsana', 'anlatsana-hifzi-ozbekmez-qto3s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Acep nicedir hallerin

Tatlımıdır ki dillerin

İncemidir o bellerin

Gülüm biraz anlatsana

Çabuk kızar küsermisin

Rüzgar gibi esermisin

Sende şiir yazarmısın

Gülüm biraz anlatsana

Kısamı uzun mu boyun

Bilmem tatlımıdır huyun

Kimlere dayanır soyun

Gülüm biraz anlatsana

Hayatında biri var mı

Gönül kapın yoksa dar mı

Kalbinde sevdiğin yar mı

Gülüm biraz anlatsana

Gözler mavimi elamı 

Saçlarında beyaz var mı

Kaderin kara yazar mı

Gülüm biraz anlatsana

Bakışın delimi eder

Gözlerin dalıp mı  gider

Sevdiklerin sana ne der

Gülüm biraz anlatsana    

Hep güler mi senin yüzün

Karamıdır kaşın gözün

Baldan tatlımıdır sözün

Gülüm biraz anlatsana

Girdin latifi gönlüne

Neşe kattın sen ömrüne

Bu konuda düşüncen ne

Gülüm biraz anlatsana

14 HAZİRAN  2003 CUMARTESİ  SAAT: 07:30', 'Acep nicedir hallerin Tatlımıdır ki dillerin İncemidir o bellerin Gülüm biraz anlatsana Çabuk kızar küsermisin Rüzgar gibi esermisin Sende ş...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/anlatsana-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Güzelsin', 'ne-guzelsin-hifzi-ozbekmez-3ubkw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şu garip gönlüme doldun

Ne güzelsin canım yarim

Şiirlere konu oldun

Ne güzelsin canım yarim

Aşktan döndürdün başımı

Akıtma sen göz yaşımı

Çabuk bitirdin işimi

Ne güzelsin canım yarim

Beni hülyalara saldın

Aklımı başımdan aldın

Sen gönlümde baki kaldın

Ne güzelsin canım yarim

Kelam söyleyemez oldum

Aşkından sarardım soldum

Karşında da divan durdum

Ne güzelsin canım yarim

Dillerin benzer bülbüle

Hallerin benzer bir güle

Unutamam bir gün bile

Ne güzelsin canım yarim

Sevdanla şiir yazarım

Sensiz hayattan bezerim

Değmesin sana nazarım

Ne güzelsin canım yarim

Bakışların bir ok gibi

Sende kötülük yok gibi

Sevdan da bana hak gibi

Ne güzelsin canım yarim

Latifinin yarisin sen

Hem yoğu hem varısın sen

Ömrümün tek karısın sen

Ne güzelsin canım yarim

14 HAZİRAN  2003 CUMARTESİ  SAAT: 08:15', 'Şu garip gönlüme doldun Ne güzelsin canım yarim Şiirlere konu oldun Ne güzelsin canım yarim Aşktan döndürdün başımı Akıtma sen göz yaşımı Ça...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ne-guzelsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tetikteki Son Mermi', 'tetikteki-son-mermi-seray-mng-2y2az', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tetikteki son mermin olamalıyım

Çekmelisin,vurmalısın beni.

Düşünmeden,

Ellerin hiç titremeden.

Anıları silmelisin sonra

Duyguları,tüm yaşananları...

Nerdeler diye sorma.

Bir ölü toprağı gibi,

Dökmelisin üstüme tüm yalanlarını

Beni sen gömmelisin

Ölmek nedir işte o an görmelisin! 

Vurmalısın beni.

Bilmelisin tetikteki son mermi.

Dönüp gitmeden,

Tek bir anıyı bile sektirmeden

Tam kalbimden vurmalısın.

Bende ne ''sen'' kalmalı yaşanan,

Ne de bir damla kan beni yaşatan.

Tam isabet almalısın,

Tam kalbimden vurmalısın.

İşte sevgili...

Bu artık son şansın

Belki de içindeki şeytanla son dansın! 

Önce doğrult silahını

Sonra soluksuz yolla son mermini.

İşte tam karşındayım.

Başka şansın yok bilmelisin.

Kalbimi hedeflemelisin.

Son kurşunla her şeyi silmelisin.

Beni sen gömmelisin,

Ölmek nedir işte o an görmelisin! 

                                         (31.12.2003)', 'Tetikteki son mermin olamalıyım Çekmelisin,vurmalısın beni. Düşünmeden, Ellerin hiç titremeden. Anıları silmelisin sonra Duyguları,tüm yaşan...', ARRAY['Türk Edebiyatı','Şiir','Seray Mng']::text[], 8.5, '{"poet":"Seray Mng","poet_slug":"seray-mng","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/tetikteki-son-mermi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maviden Mora Geçiş', 'maviden-mora-gecis-utku-yildirim-7kbiw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Başkaları bulur

Yerin altında sakladığım şehri

Uykularım alır

Karalar giymiş beni

Bulutlar saklar

İçimde büğüttüğüm aşkı

Hayallerim girer

Mutluluk şarhoşu olmuş gözlerime...

Sesin gelir kulağıma

Mavilerin ötesinden

Morların içinden

Bırakma beni ellerinden...', 'Başkaları bulur Yerin altında sakladığım şehri Uykularım alır Karalar giymiş beni Bulutlar saklar İçimde büğüttüğüm aşkı Hayallerim girer Mu...', ARRAY['Türk Edebiyatı','Şiir','Utku Yıldırım']::text[], 8.5, '{"poet":"Utku Yıldırım","poet_slug":"utku-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/maviden-mora-gecis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün,Bugün,Yarın', 'dun-bugun-yarin-ali-hamdi-eray-emfhy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Küçücüktüm,büyüdüm.

Mamamı yiye yiye,

Coşuyor,koşuyordum,

Annecim diye,diye.

Okuluma başladım,

Öğrendim önce türkü,

Türkçemizi öğrendim,

Ve canım Atatürk''ü

Türkiyem yazıyorum,

Hududu çiziyorum,

Benim Vatan''ım diye,

Oynayıp, geziyorum.

Arkadaşım kardeşim,

Onu candan severim.

Kim sevmez kardeşini,

Kardeşim canım benim.

Yarın için yarına,

Çalışıp güvenmeli,

Yurt''ta cihanda barış,

Atamın,bilinmeli.

Hürriyet,cumhuriyet,

Yoludur ilkemizin,

Yarınlar bizlerindir

Yarınlar hepimizin', 'Küçücüktüm,büyüdüm. Mamamı yiye yiye, Coşuyor,koşuyordum, Annecim diye,diye. Okuluma başladım, Öğrendim önce türkü, Türkçemizi öğrendim, Ve ...', ARRAY['Türk Edebiyatı','Şiir','Ali Hamdi Eray']::text[], 8.5, '{"poet":"Ali Hamdi Eray","poet_slug":"ali-hamdi-eray","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dun-bugun-yarin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostluk agaci', 'dostluk-agaci-sema-gorur-f2gck', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dostluk agaci

Bir masaldIr yasadigimiz,

Pembeler içinde alti kiz,

Melekleri ürperten safligimiz,

Ve alti bedende tek canimiz! 

Leylam''in tatli gülüsleri,

Yosun gözleri,

Birde, etrafina günes gibi saçtigi 

Yasama sevinci var.

Artik uzaklardan geliyor 

Leylamin ayak sesleri.

Aysem''in ay''i kiskandiran güzelligi,

Nârin, edali hareketleri,

Birde toz pembe bir kalbi var…

Yakinda, yepyeni ufuklar açacak

Basinda esen kavak yelleri.

Zeynebim''in deli dolu hareketleri,

Insani öldüren o gözleri,

Birde tertemiz bir yüregi var.

Artik uzaklardan geliyor 

Zeynebimin ayak sesleri.

Birde Asiyam var benim! 

Kara bulutlar arasinda günesim,

Sevincim,

Biricik Asiyam var benim,

Biricigim! 

Ipegim,

Dostluk agacimizin altin yapragi,

Hasret ile doldu yüregi

Diger yapraklar kopali.

Dostluk agacimiz

Yemyesil, bembeyaz, toz pembe…

Yemyesil, Leylam''in gözleri gibi,

Bembeyaz, Zeynebim''in gelinligi gibi,

Toz pembe, Aysem''in yüregi gibi.

Dostluk agacimiz

Masmavi, cesur ve ebedî…

Masmavi, Asiyam''in bahti gibi,

Cesur ve ebedî, dostlugumuz gibi.

Bir masaldir yasadigimiz,

Pembeler içinde alti kiz

Melekleri ürperten safligimiz,

Ve alti bedende tek canimiz! 

Bir masaldir yasattigimiz

Yemyesil dostluk agacimiz.

Agacimizin güzelligi ebedî,

Bizi alti beden tek can kilan

Dostlugumuz gibi.', 'Dostluk agaci Bir masaldIr yasadigimiz, Pembeler içinde alti kiz, Melekleri ürperten safligimiz, Ve alti bedende tek canimiz!  Leylam''in tat...', ARRAY['Türk Edebiyatı','Şiir','Sema Görür']::text[], 8.5, '{"poet":"Sema Görür","poet_slug":"sema-gorur","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/dostluk-agaci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan', 'yalan-hasan-ozen-adyja', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalan üzerine kurdum dünyamı

Beni seviyor diyordum,yalanmış

Koca bir yalan.

Neyse önemli değil unuturum diyordum

O öncekinden daha büyük yalan', 'Yalan üzerine kurdum dünyamı Beni seviyor diyordum,yalanmış Koca bir yalan. Neyse önemli değil unuturum diyordum O öncekinden daha büyük yal...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özen']::text[], 8.5, '{"poet":"Hasan Özen","poet_slug":"hasan-ozen","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yalan-85-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serde Delikanlılık Var ya! ...', 'serde-delikanlilik-var-ya-hasan-ozen-j0y7c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gün olur bir dosta rastlarım yolda

Sorar ''nasılsın? .. ''derim ki; İyiyim.

Halbuki yalan! vallahi yalan''..

Adet olmuş ya ''iyiyim'' demek

Kendimi kandırıyorum,Dosta hoş görünmek isterken

Aslında çok kötüyüm,

Aslında çıldırmak üzereyim,

Aslında öleceğim hasretinden,

Ama diyemiyorum

Serde delikanlılık var ya! ...', 'Gün olur bir dosta rastlarım yolda Sorar ''nasılsın? .. ''derim ki; İyiyim. Halbuki yalan! vallahi yalan''.. Adet olmuş ya ''iyiyim'' demek Kendi...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özen']::text[], 8.5, '{"poet":"Hasan Özen","poet_slug":"hasan-ozen","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/serde-delikanlilik-var-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben zaten hep hayallere aşık olurum', 'ben-zaten-hep-hayallere-asik-olurum-hasan-ozen-2sovy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben zaten hep hayallere aşık olurum

Yine bir hayalin peşinde koştum bu yıl da

Bak, koca bir yıl geçti bir hayalin peşinde

Bir yıl daha yaşlandık, bir yıl daha

Ben akıllanmayacağım,ben akıllanmayacağım', 'Ben zaten hep hayallere aşık olurum Yine bir hayalin peşinde koştum bu yıl da Bak, koca bir yıl geçti bir hayalin peşinde Bir yıl daha yaşla...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özen']::text[], 8.5, '{"poet":"Hasan Özen","poet_slug":"hasan-ozen","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ben-zaten-hep-hayallere-asik-olurum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başbakan''ımıza', 'basbakan-imiza-ali-hamdi-eray-k6qwx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Saygılarımla

Başbakanım,karaoğlan

Bu sözümü duyman gerek,

Özüm,sözüm birdir ama,

Senin bunu bilmen gerek.

Bu milletim seni sevdi,

Saygı duydu güven duydu,

Kaç kişiye nasip oldu,

Bütün bunlar bilmen gerek.

Şairliğin sınır aştı,

Siyah saçın beyazlaştı,

Güneş guruba yaklaştı,

Artık eve dönmen gerek.

            İzmir    2002', 'Saygılarımla Başbakanım,karaoğlan Bu sözümü duyman gerek, Özüm,sözüm birdir ama, Senin bunu bilmen gerek. Bu milletim seni sevdi, Saygı duyd...', ARRAY['Türk Edebiyatı','Şiir','Ali Hamdi Eray']::text[], 8.5, '{"poet":"Ali Hamdi Eray","poet_slug":"ali-hamdi-eray","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/basbakan-imiza-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Cümle Alem', 'ah-cumle-alem-hasan-ozen-0y7qq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Esme rüzgar,Yağma yağmur

Bana mutluluk şarkılarını Aşkın melodisini çalmayın

Ağustos böcekleri

Bana aşktan söz etmeyin,Ah cümle alem

Doğma güneş,çıkma ay

Benim kupkuru, kapkaranlık

Sade dünyamı aydınlatmayın

Sokak lambaları

Bana aşktan söz etmeyin, Ah cümle alem

Bakma esmerim,gülme kumralım

Benim dostsuz,düşmansız

Yalnızlıklar kalemi kuşatmayın 

Aşk perileri

Bana aşktan söz etmeyin,Ah cümle alem

Mecnun kör oldu,Leyla kahroldu

Ferhat dağ deldi,Şirin mest oldu

Bense bir hiç oldum

Aşk tanrıları

Bana aşktan söz etmeyin,Ah cümle alem

Bir güzel sevdim yaşım küçüktü,

Bir güzel sevdim yaşı küçüktü,

Bir güzel sevdim aşkı küçüktü

Bana aşktan söz etmeyin,Ah cümle alem

Hasan''ım der hep aldandım

Bir gün güldüm,bir yıl yandım

Yalan sevda sana kandım

Bırak beni cümle alem', 'Esme rüzgar,Yağma yağmur Bana mutluluk şarkılarını Aşkın melodisini çalmayın Ağustos böcekleri Bana aşktan söz etmeyin,Ah cümle alem Doğma g...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özen']::text[], 8.5, '{"poet":"Hasan Özen","poet_slug":"hasan-ozen","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ah-cumle-alem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızca Kalp Vardır Atan', 'yalnizca-kalp-vardir-atan-hasan-ozen-5g8cr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşka yasak olmuyor gülüm

Eğer bir kıvılcım düşmüşse içine

Bir kere kıpırdandı ise yüreğinde ılık ılık

Kurtulacağım diye düşün dur artık

Ama nafile tüm uğraşlar

Tüm dertler bir olur artık

Tüm uzuvlar durur

Göz görmez,kulak işitmez olur,

Yalnızca kalp vardır atan

İmtihan başlamıştır bir kere

El tutmaz,ayak yürümez,

Beyin çalışmaz olur,

İliklerine kadar aşk dolar damarların

Ilık ılık hissedersin içinde kıpırdayan duyguyu

Sel misali coşar,volkan misali patlarsın

Bulutlar yağmur getirmez artık

Yalnızca onu taşır,

Sabahlar ona doğar, akşamlar ona batar

Bütün yollar ona çıkar

Ah! ... Bir kırabilsen zincirlerini 

Ama nafile boşa tüm uğraşlar

Tüm dertler bir olur artık

Tüm uzuvlar durur

Göz görmez,kulak işitmez olur,

Yalnızca kalp vardır atan', 'Aşka yasak olmuyor gülüm Eğer bir kıvılcım düşmüşse içine Bir kere kıpırdandı ise yüreğinde ılık ılık Kurtulacağım diye düşün dur artık Ama ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özen']::text[], 8.5, '{"poet":"Hasan Özen","poet_slug":"hasan-ozen","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yalnizca-kalp-vardir-atan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşarken Ölmek', 'yasarken-olmek-hasan-ozen-vuri7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşamak varsa dünyada 

Sevmeden yaşamak düşünülemez

Dünya SEVGİ üzerine kurulmuş,

Allah(cc)  sevmek,peygamberi sevmek

Kur''anı sevmek,insanları sevmek

Doğayı sevmek, ağaçları sevmek

Yemyeşil yaprak açan ağaçları,

Şelaleden akan suyu sevmek

Onca insanı temizleyen

Yemeklerimize kattığımız suyu

Uçan kuşu,esen yeli sevmek

Sevmek güzel şey,Sevmek müthiş bir duygu

Sevmek yaşamak demek

Sevmek nefes almak, yürümek,koşmak demek

Çağlayanlar, nehirler misali coşmak demek

Ama! ... İşte var ya! ....

Bir vefasızı bir hayırsızı sevmek

Yaşarken ölmek demek', 'Yaşamak varsa dünyada  Sevmeden yaşamak düşünülemez Dünya SEVGİ üzerine kurulmuş, Allah(cc)  sevmek,peygamberi sevmek Kur''anı sevmek,insanla...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özen']::text[], 8.5, '{"poet":"Hasan Özen","poet_slug":"hasan-ozen","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yasarken-olmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çeker Giderim....', 'ceker-giderim-i-brahim-ethem-bingul-59onu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'En olmadık bir yerde,

En olmadık şekilde,

Tanışırsınız bir gün

Genç ve güzel biriyle

Önceleri, çekingen ve ürkek durursunuz

Uzaktan uzağa bakar, takiptesiniz her an

Yureğiniz kıpırdar, bu kalbe ilk darbedir

Derken anlarsınız ki; siz ona aşıksınız...

Bilmezsiniz ne yapacağınızı 

Aşkınız avare eder sizi

O, artık kalbe dolmuş,

Herşeyiniz olmuştur...

Onunla kalkar, onunla yatarsınız 

Adını duysanız çarpar kalbiniz

Anlaşılır ki siz,

Dayanılmaz aşk girdabinda

Hem onunla,hem onsuz 

Hem gerçek, hem rüyada 

Sonu meçhul hülyada

Çekilmez, dayanılmaz derin izdıraplarda

Çile çekmektesiniz...

İstersiniz ki bilsin, sizin bu aşkınızı

Toplarsınız cesaret, çıkarsınız önüne

Sevginizi, kalbinizi anlatır; ona yalvarırsınız 

Aşkınıza bir cevap, bir ''''evet'''' beklersiniz

Dinlerken ciddi ciddi 

Sevinç kaplar kalbini

''''Tamam, oldu nihayet! ''''  ''''başardim'''' der içiniz

O, söze başlar, kalbiniz hızla atar

Fakat onda umursamaz bir tavır 

Cevabı size ''''hayır'''' 

Dondurur kanınızı 

Başlar sizde bir sızı

Konuşur tane tane,

Der ki; ''''ne ilk seven, siz ''''

''''Ne de son olacaksınız! .'' ''

Siz, bu kadar severken 

Ona (her şeyim)    derken

Sizin sevginiz bitmiş,

Sanki hiçe gitmiştir...

Kırılmış bir gururla,

Reddedilmişinizdir

Yapacak hiçbirşey yok 

Çekilip gidersiniz 

O, yolunu çizmiştir

Sizi reddeylemiştir

Kalırsınız bir halde; aşkla nefret arası 

Hem ona, hem kendine 

Nefret dolar kalbiniz

O büyük aşkınızla gurur duyar içiniz 

''''Bu aşk ona değmezmiş! .'''' derken

Bu söz bu aşka dair sizin son sözünüzdür

Ve çeker gidersiniz.', 'En olmadık bir yerde, En olmadık şekilde, Tanışırsınız bir gün Genç ve güzel biriyle Önceleri, çekingen ve ürkek durursunuz Uzaktan uzağa ba...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/ceker-giderim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar Olsaydım', 'ruzgar-olsaydim-sadik-softa-3s5m7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Özgürce yürüyüp, hürce uçarak,

Dağdan dağa, belden bele giderdim.

Kendim çizer idim, kendi yolumu,

Yoldan yola, elden ele giderdim.

Hız alarak nefes nefes koşardım.

Dere, tepe demez bir bir aşardım.

Özgür olup, özgürlüğü yaşardım.

Yağmur olup selden sele giderdim.

Soğuğa aldırmaz, buza aldırmaz,

Bahara aldırmaz, yaza aldırmaz,

Cümbüşe aldırmaz, saza aldırmaz,

Perde perde telden tele giderdim.

Efsunlardım tabiatı baharda,

Tan vaktinde serinlerdim seherde,

Gece gündüz demez her an her yerde,

Rüzgar olur yelden yele giderdim.', 'Özgürce yürüyüp, hürce uçarak, Dağdan dağa, belden bele giderdim. Kendim çizer idim, kendi yolumu, Yoldan yola, elden ele giderdim. Hız alar...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ruzgar-olsaydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olur Çalma Kalbimi (Akrostiş)', 'ne-olur-calma-kalbimi-akrostis-hasan-ozen-eukk2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'N e olur çalma kalbimi

E llerinle ateşlere atma ne olur

O nulmaz dertlere düşürme beni

L üle lüle saçlarını sallama işte

U mutla yollarına baktırma

R enklerini toz pembe yapma dünyamın

Ç ekip gideceksen günün birinde

A lma ahımı ne olur

L anet ettirme isyan ettirme 

M atem tutturma geceler boyu

A şkımın kıymetini bileceksen gel

K albim senindir al gülüm 

A şka susamışım asırlardır

L okomotifi ol umutsuz sevdamın

B ulutlar olsun şahidimiz,bir de ay

 İ liklerimize işlesin bu sevda

M esele işte tam burada

 İ çimde birşeyler oluyor.', 'N e olur çalma kalbimi E llerinle ateşlere atma ne olur O nulmaz dertlere düşürme beni L üle lüle saçlarını sallama işte U mutla yollarına b...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özen']::text[], 8.5, '{"poet":"Hasan Özen","poet_slug":"hasan-ozen","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ne-olur-calma-kalbimi-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ozgurluge', 'ozgurluge-sair-kayadakicicek-tb400', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Düş''ün,bir yılan gibi şimdi koynumda olan

Gülüşün,en sadık düşümdür,beni sana taassup kılan.', 'Düş''ün,bir yılan gibi şimdi koynumda olan Gülüşün,en sadık düşümdür,beni sana taassup kılan....', ARRAY['Türk Edebiyatı','Şiir','Şair Kayadakicicek']::text[], 8.5, '{"poet":"Şair Kayadakicicek","poet_slug":"sair-kayadakicicek","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/ozgurluge-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Manolis', 'ah-manolis-huseyin-cayikli-net0s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'incifer''e

ben boyle beklemezdim

hediye gibiydin bir aralık aksamı cikip geldin.

cok bekledim seni

bir omur kadar...

ah manolis nerelerdeydin...', 'incifer''e ben boyle beklemezdim hediye gibiydin bir aralık aksamı cikip geldin. cok bekledim seni bir omur kadar... ah manolis nerelerdeydin...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ah-manolis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişmanlık', 'pismanlik-esma-ozdemir-8cu70', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Büyük harflerle söylüyorum; 

Pişmanım,

Artık

İnsanları

Eskisi gibi sevemediğime! 

Kabahat otuzlu yıllarda mı

Eskimekte mi? 

Kabahat, yaşlanmakta mı

Bilemiyorum! 

Aynalara bakıyorum,

Değişmişim…

Tam da istediğim gibi

Değişmeliyim... diyordum

Bak işte, değiştim; 

Kendimi aynada

Tanıyamıyorum! 

Ne kaleler örmüşüm meğer

Yüksek topuklu! 

Ne kalkanlar edinmişim kendime 

Siyah sürme kapaklı

Dal budak eklenmişim

Gül gibi 

Savunmasız güzelliğime...

Kana, dikene bürünmüşüm

İpek bürümcükler içinde

Dokunmuşum,

İşlenmişim bir kere, Gülüm

Örülmüşüm

Kendi iskeletime

Tutunmuşum

Çıplak gerçeklere...

İnsanların, bir yüzü dost

Bir yüzü, insan

Bir yüzü sevecen

Bir yüzü var ya, ahh! 

Bir yüzü candan,

Bir yüzü, koruyan

Bir yüzü, beni kendine bağlayan! 

Ama, neden çiçeğim

Neden

İnsanların öteki yüzü yok? ...

Neden, bu kapkara boşluk; 

Gözlerimde mi...

Kalbimde mi? 

Kara bende mi 

Kara, yıllarda mı? 

Fezada büyük bir karadelik; 

İnsanların öte yüzü yok! 

Yum gözlerini bebeğim,

Bundan gerisi sadece

Karanlık! 

Ola ki, düşme içine

Simetrisiz yüzlerin

Aynada

Kaybolma kendi silinmişliğinde!', 'Büyük harflerle söylüyorum;  Pişmanım, Artık İnsanları Eskisi gibi sevemediğime!  Kabahat otuzlu yıllarda mı Eskimekte mi?  Kabahat, yaşlanm...', ARRAY['Türk Edebiyatı','Şiir','Esma Özdemir']::text[], 8.5, '{"poet":"Esma Özdemir","poet_slug":"esma-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/pismanlik-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezarın Mısralarım', 'mezarin-misralarim-nihat-tasdemir-wp3do', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ve nihayet

	Can çekişiyorsun mısralarımda

	Merak etme; 

	Birazdan gömeceğim seni buralara

	Ve son kez adını anacağım üç defa

	Damla, damla üç gözyaşı… 

	Dönüp te ardıma bile bakmayacağım,

	Ve yasını tutmayacağım ele güne karşı.

	Zamanı çoktan gelmişti zaten

	Bir önceki şiirimde kararlıydım,

	Ne yapalım kısmet bu şiireymiş.

	Ölümün yavaş, yavaş olmalıydı.

	Cümleler olabildiğince fütursuz,

	Olabildiğince devrik kurulmalıydı.

	Nokta yok, virgül yok, imla yok...

	Senin gibi serseri, senin gibi duyarsız olmalıydı.

	Senin gibi kuralsız ve senin gibi manasız olmalıydı mezarın

	Yalvarma boşuna; 

	Kelimeler duymazlar sesini.

	Duysalar bile aldırmazlar zaten,

	Bu benim şiirim...

	Emin ol! 

	Hak ettiğin gibi, 

Hak ettiğin yerde veriyorsun son nefesini

	Ve bundan sonraki hiçbir şiirimde 

	Göremeyecekler artık,

	Ne seni ne de izini

YORGUN YALNIZLIKLAR isimli kitabımdan...', 'Ve nihayet 	Can çekişiyorsun mısralarımda 	Merak etme;  	Birazdan gömeceğim seni buralara 	Ve son kez adını anacağım üç defa 	Damla, damla ü...', ARRAY['Türk Edebiyatı','Şiir','Nihat Taşdemir']::text[], 8.5, '{"poet":"Nihat Taşdemir","poet_slug":"nihat-tasdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/mezarin-misralarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Son Şiirim', 'bu-son-siirim-nihat-tasdemir-4o98c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu, son şiirim...

Sana yazılanların sonuncusu.

Artık, hiç bir şey ifade etmez

Ve tek bir mısra bile yazdıramaz bana

“Sensizlik Olgusu”

Yazılanlar mazide,

Yazılacaklar ise sensizlikte gizli.

Ve hiçbir zaman yazamayacağım 

Yazılmışların en iyisini.

Yazdım. Ama hep yazdım.

Gittiğinden beri kendimi şiirlere adadım.

Şiirlerimi ise sana...

Seni sevdiğimi nasıl haykırsam ki; 

Dünyada sevgiyi bilmeyen yürek,

Duymayan kulak kalmasın istedim,

Ama yapamadım.

Hasretini kağıda nasıl döksem ki; 

Hasret şiirleri bir, bir utansın istedim.

Ama başaramadım.

Artık yalnızlar limanından ayrılıyorum.

Bilmediğim okyanuslara açılacağım.

Ve her gün farklı rüzgarlar okşayacak yelkenlerimi.

Bu, bu sana yazdığım son şiirim.

Elveda şiirlerimin prensesi.

Elveda yaralı gönlümün kibirli efendisi.

Elveda kahpeliğin, kalleşliğin simgesi.

Elveda yalnızlık ikliminin bitki örtüsü.

Elveda karakışım, elveda hazanım.

Bundan öncekiler gibi, bu şiirimi de

Hiçbir zaman okuyamayacaksın.

Ve hiçbir zaman dinlemeyeceksin sesimden.

İçin hiçbir zaman cız etmeyecek, ağlamayacak,

Ve uykusuz hiçbir günü geçirmeyeceksin.

Bunlar bana has marifetler...

Sen, yolunu yıllar önce çizmiştin.

Ben, bense avundum, avuttum,

Nice boşluklara savruldum ve 

Nice ateşlerde kavruldum.

Ama artık son! Doğru yolu buldum.

Elveda yolsuzum.

Elveda insaftan yoksunum.

YORGUN YALNIZLIKLAR isimli kitabımdan...', 'Bu, son şiirim... Sana yazılanların sonuncusu. Artık, hiç bir şey ifade etmez Ve tek bir mısra bile yazdıramaz bana “Sensizlik Olgusu” Yazıl...', ARRAY['Türk Edebiyatı','Şiir','Nihat Taşdemir']::text[], 8.5, '{"poet":"Nihat Taşdemir","poet_slug":"nihat-tasdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/bu-son-siirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle', 'seninle-sadik-softa-qc1fv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zamana hükmeder gece ve gündüz,

Yüreğim seninle gönlüm seninle,

Her zaman, her yerde, benden bakarsın,

Bedenim seninle, gönlüm seninle.

Seninle yatarım, seninle uyur,

Gözlerim yerine, rüyanı görür,

Beni benden alır, peşinde sürür,

Hayalim seninle, özüm seninle.

Şarkılarım senle, türküm seninle,

Hedefim seninle, ülküm seninle,

Bütün geleceğim, mahkum seninle,

Şiir mısra mısra, sözüm seninle.

Çözemedim bende, sendeki gizi,

Takip ediyorum, kalpteki izi,

Birlikte soluyup, nefesimizi,

Dirimliğim senle, ölüm seninle.', 'Zamana hükmeder gece ve gündüz, Yüreğim seninle gönlüm seninle, Her zaman, her yerde, benden bakarsın, Bedenim seninle, gönlüm seninle. Seni...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seninle-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neşesi kaçmış adam', 'nesesi-kacmis-adam-olcay-kose-7y5he', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kusura bakma gökyüzü 

bugün hiç neşem yok 

artık kalmışım sofranda

açım ufuklarına 

aşka

sevdaya

ağlamaya', 'kusura bakma gökyüzü  bugün hiç neşem yok  artık kalmışım sofranda açım ufuklarına  aşka sevdaya ağlamaya...', ARRAY['Türk Edebiyatı','Şiir','Olcay Köse']::text[], 8.5, '{"poet":"Olcay Köse","poet_slug":"olcay-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/nesesi-kacmis-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Başka Sarıyor Ağırdan', 'bir-baska-sariyor-agirdan-sadik-softa-ifzjy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Islak gözlerinde sevdaların ahengi,

Delirmiş dereler, akar pırıltılı sular,

Mektuplara akıyor zaman ağırdan,

Hikâyelerini yazıyorum yalnızlığımın,

Göçmen kuşlar sesleniyor gurbet acılığında,

Yol uzuyor, yorgunluk sarıyor ağırdan.

Çarpa çarpa götürüyor rüzgarlar bulutları,

Çarpa çarpa titretiyor yüzümü ayaz,

Gurbet kaybetmiş yolumu, yol kıvrımlarında,

İnceden inceye akıyor dereden sular,

Azap kokusunda tortulaşıyor mesafeler,

Gözümde büyüyor yalnızlık sarıyor ağırdan.

Evet... sıradaki gün, sıradaki akşam,

Tadını unuttum gözlerinden akan yaşin,

Kahkahası tufana tutuldu sevdamın,

Kokusunu unuttum... kar yağdı...bugün kasım,

Evet, tam üç metre, birkaç adam boyu,

Yol kalmadı, beyazlık sarıyor ağırdan.

Duygular şaha kalkamaz ki, yorgun düştü,

Şakaklarım daha da ak, daha bir durgun,

Sınırları belirsizleşti dağların, tepelerin,

Renk kalmadı... alabora... fırtınalar,

Yüreğimde büyüdü, tunçlaştı sevdan,

Hasretin daha bir başka sarıyor ağırdan.', 'Islak gözlerinde sevdaların ahengi, Delirmiş dereler, akar pırıltılı sular, Mektuplara akıyor zaman ağırdan, Hikâyelerini yazıyorum yalnızlı...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-baska-sariyor-agirdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek üzerine', 'sevmek-uzerine-olcay-kose-fz5mo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'şimdi özür dilemeyi öğrendi

bakarken küfürlü gözlerime

tasasızda sevdasızdı

şimdi öğrendi

gidenin ardından

ağlamayı', 'şimdi özür dilemeyi öğrendi bakarken küfürlü gözlerime tasasızda sevdasızdı şimdi öğrendi gidenin ardından ağlamayı...', ARRAY['Türk Edebiyatı','Şiir','Olcay Köse']::text[], 8.5, '{"poet":"Olcay Köse","poet_slug":"olcay-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sevmek-uzerine-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim?', 'kim-olcay-kose-f4n7u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kim galip şimdi söyle

ardından ağlayan ben mi? 

giderken sızlayan

sen mi?', 'kim galip şimdi söyle ardından ağlayan ben mi?  giderken sızlayan sen mi?...', ARRAY['Türk Edebiyatı','Şiir','Olcay Köse']::text[], 8.5, '{"poet":"Olcay Köse","poet_slug":"olcay-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kim-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Yeter', 'bana-yeter-nur-tanir-fxo61', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yanlızlığı bana bırak ne olur,

Senin olsun mutlu yaşantılar,

Ağlamak tek tesellim bu gercek; 

Sen gül herşeye gülebildiğin kadar.

Yıldızlar senin olsun hep

Bana karanlığını ver gecenin

Al bütün pırıltılarını semanın

Çözümünü verme o bir hecelik bilmecenin.

Gel desemde gelme sakın 

Ben yanlızlığın o kör kuyusundayım artık 

Aldırma betbahtlığıma boş ver

İstersen yaşamakta senin olsun

Ölüm bana yeter.', 'Yanlızlığı bana bırak ne olur, Senin olsun mutlu yaşantılar, Ağlamak tek tesellim bu gercek;  Sen gül herşeye gülebildiğin kadar. Yıldızlar ...', ARRAY['Türk Edebiyatı','Şiir','Nur Tanır']::text[], 8.5, '{"poet":"Nur Tanır","poet_slug":"nur-tanir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bana-yeter-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Hadi*', 'hadi-olcay-kose-w36ok', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'çiğniyorum kurallarını 

hadi beni terket

ne geçecek eline

görelim', 'çiğniyorum kurallarını  hadi beni terket ne geçecek eline görelim...', ARRAY['Türk Edebiyatı','Şiir','Olcay Köse']::text[], 8.5, '{"poet":"Olcay Köse","poet_slug":"olcay-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hadi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'aşka gözle başka bir BAKIŞ', 'aska-gozle-baska-bir-bakis-olcay-kose-2bnue', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kiralık katil tuttum

