INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Akşam', 'dun-aksam-vedat-didari-rgiz7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dün akşam ben bir serseri

Hüzün ağlattım penceremde

Aklıma geldi de  ağlayan gözleri

O uzak kentteki son gecemde

Kutsal bir morluk içerken

Ufuktan yorgun denizleri

Bir yel üfürdü içimden

Mâziden kalan son izleri

Birden ağlayan gözleri

Aklıma geldi son gecemde

Dün akşam ben bir serseri

Hüzün ağlattım penceremde', 'Dün akşam ben bir serseri Hüzün ağlattım penceremde Aklıma geldi de  ağlayan gözleri O uzak kentteki son gecemde Kutsal bir morluk içerken U...', ARRAY['Türk Edebiyatı','Şiir','Vedat Didari']::text[], 8.5, '{"poet":"Vedat Didari","poet_slug":"vedat-didari","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dun-aksam-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Evinden Şiirler 7', 'deli-evinden-siirler-7-oguzkan-bolukbasi-59fa4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hicvin pervanesinde

Pervasız

Ve arsız gezen ışıksız yıldızlar

Kaya parçaları gibi deli bozuk

Başı bozuk

Çarpacaklar ilk zararsız gezegene

Önüne gelene

Ocaktosun yirmi beşinden

Mayıstosun sonuna kadar

Yangında yanacak şeytanlar

Kifayetsiz muhteris

İlk hafızadır histeresis osiloskop camında

Biz seyrederken balık gibi

Yapay zeka göründü yaşamın ekranında

Her cismin bir dalgası var

Siz daha dalga geçin kuyruğunda dalgalar olanlar

Keşfe açık evren

Derdimiz aşksa

Aşkın icadı ne zaman

Küçük tepelerinde memelerin

Bıyığı yeni terlemiş bir oğlan çocuğunun değil

Aşkını soruyorum ilk insanın

Baktığın yere göre değişiyorsa gördüklerin

Doğruyu nereden göreceksin

Aslında gerçeği

Kim veli

Kim deli

Kim bilmeli

Şimdi ocak ayındayız

Şömine ayı niye yok

Ağustos ayı Augustus diye bir Sezar’dan

Ben olsam Zafer koyardım adını

Ekim’e Cumhuriyet 

Haziran’a Yazbaşı

Temmuza Sıcak derdim

Eylül’e İzmir

Kasım’a Hazansonu

Şubat’a Kışsonu

Mart’a Baharbaşı

Nisan’a Çiçekayı

Mayıs’a İstanbul

Aralık’a Ankara

Ocak’a Başay

Ne güzel yakışırdı

Bana hiçbir şey sormuyorlar

Deli evleri karantinada

Kendi kendine konuşmada diller

Ah bilseniz ne akıllıdır

Bizim gibi deliler

(realite sabit algı değişkendir- bir başka deli evi sakininden)', 'Hicvin pervanesinde Pervasız Ve arsız gezen ışıksız yıldızlar Kaya parçaları gibi deli bozuk Başı bozuk Çarpacaklar ilk zararsız gezegene Ön...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/deli-evinden-siirler-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Siir Yazmak Gelmiyor Içimden', 'bugun-siir-yazmak-gelmiyor-icimden-sair-ozlem-uwmq0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bugün şiir yazmak gelmiyor içimden

Sadece  düşünmek ve anlamak  istiyorum..

İnsanları ve kendimi şöyle bir ölçüp tartmak,

Yaşadığım bu duygu karmaşasını çözmek istiyorum...

Kendimi aşmak, beni saran bu görünmez çemberi kırmak istiyorum.

Çelikten midir nedir,

Bir türlü kıramıyorum....

Bugün şiir yazmak gelmiyor içimden dedim ya,

Gelmiyor gerçekten, saçmalıyorum işte! 

Varsın biraz da saçmalıklar yazayım ne çıkar

Zaten hayat bir saçmalık,

Yaşamak ve yaşamamak kararsızlığı bir saçmalık.

Nedenini bir türlü anlayamadığım mutsuzluğum,

Bir saçmalık...

Bugün şiir yazmak gelmiyor içimden

Ama rahat durmadı bu mutlu insanlar...

Mutlu insanlara öyle şaşıyorum ki

Şu dünyada mutlu olacak ne buluyorlar? 

Hiç mi bakmıyorlar çabucak geçen  günlere? 

Eskiyen gözlerine, ellerine, yüzlerine...

Atılan her adımın  yeni bir başlangıca gittiğini bile bile,

Her insanda  yeni bir dünya arayıp,

Sevgiye ölesiye değer verirsen

Mutluluğu bulman çok zor arkadaş! 

İnce düşünen için bunlar belki anlamlı

''Boşversene sen'' diyen için bir yığın söz kalabalığı...

Bu söz kalabalığı var ya arkadaş,

Hayatı kılandır anlamlı...

(Tüm Siir Severlere)', 'Bugün şiir yazmak gelmiyor içimden Sadece  düşünmek ve anlamak  istiyorum.. İnsanları ve kendimi şöyle bir ölçüp tartmak, Yaşadığım bu duygu...', ARRAY['Türk Edebiyatı','Şiir','Şair Özlem']::text[], 8.5, '{"poet":"Şair Özlem","poet_slug":"sair-ozlem","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bugun-siir-yazmak-gelmiyor-icimden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'FerahFezam', 'ferahfezam-sule-aydemir-qjz9a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dün gece 

saksımı çalmışlar

gönlü ferah bir 

yaşam sonrası

kalıplaşmış toprağım

varan kırk dört yıl

bu yüzdendir

kalıp çalınınca

dağılmamışlığım

saksısız büyüyorum

toprağa kök salmış

huzurla bedenim

ferahfezam çiçeklerim

gökkuşağından 

fazlaca renklerim

yıllar

saksımı çalmışlar

köklerimi bırakmışlar

çürümedi bedenim

boş geçmedi senelerim

kış ortası olgunlaşan 

meyvelerim var benim

nice baharları 

çiçeklerimi kıskanan

kelebekler için 

beklerim

___________renklerin ötesi

________________ferahfezam 

__________________geleceğimin

________________________sıcacık 

__________________________gölgesi



www.sevgikupu.com', 'dün gece  saksımı çalmışlar gönlü ferah bir  yaşam sonrası kalıplaşmış toprağım varan kırk dört yıl bu yüzdendir kalıp çalınınca dağılmamışl...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ferahfezam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybedecek Hiç Bir Şeyi Olmayana', 'kaybedecek-hic-bir-seyi-olmayana-k-muran-esen-06lmr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eğer sofranda 

Ekmeğini bölüştüğün biri yoksa 

Veya / özlemini çektiğin bir yar

Uzaklarda, 

Ya da kaybetmekten korktuğun sevdan 

Kopmamışsa hiç yüreğinden bir parça 

Hasreti duymamış, solumamışsan 

Ağlamamışsan gidenin arkasından....... 

 Sözlüklerde ''ayrılık'' senin için 

Yazsa da olur, yazmasa da.

İçinden taşıp dökülen duygulardan yoksunsan eğer 

Bir şiirin her dizesinde gülümseyen yüzler belirmiyorsa hiç 

 Ya da coşturmuyor / ağlatmıyor / düşündürmüyorsa seni, 

Dinlediğin şarkılar / hiç kimseyi çağrıştırmıyorsa, 

 Söylediğin türküler yapraklarını titretmiyorsa efil efil 

 Damarlarında kan yerine hasretler / sevgiler yeşermiyorsa adam boyu 

 Davullar çalmıyorsa gümbür gümbür........ 

Şarkılar çalsa da olur senin için, çalmasa da.

Yağmur damlası kadar bile bir iz bırakmadıysan arkanda 

 Mütevazi bir sandala bile kürek olamadıysan 

Susturmadıysan ağlayan bir çocuğu 

 Öpmediysen / sarmadıysan bir yüreği 

Bırakıp gitmekten korktuğun 

 Ondan düşüp yine ona konduğun bir çift nemli gözden yoksunsan 

 Ya da hayatında elini uzatacağın birinden mahrumsan eğer 

Toksa gönlün sevgilere / aşklara 

Başkasının gözyaşları içine akmıyor 

Damlamıyorsa yüreğine........ 

Yaşam senin için / olsa da olur, olmasa da..

Sevgilere sırtı dönük bir yürek; 

Çekmecede unutulmuş bir mendil 

Açılmayan kör bir kapı 

 Yağış bilmez kuru bir gök gibidir. 

O yürekler 

Ne şiirden etkilenir 

 Ne şarkıyla hüzünlenir

Su sesi gibi gelir ölüm......

Ölümden korkmak için 

 Bir sevdiğin / bir sevenin 

Sığınacak bir yüreğin 

Arkandan ağlayacak bir çift gözün olması gerekir.......

Bu dünyada / kaybedecek hiçbir şeyi olmayana 

Ayrılıktan korkmayana 

Ölüm / gelse de olur, gelmese de.', 'Eğer sofranda  Ekmeğini bölüştüğün biri yoksa  Veya / özlemini çektiğin bir yar Uzaklarda,  Ya da kaybetmekten korktuğun sevdan  Kopmamışsa ...', ARRAY['Türk Edebiyatı','Şiir','Kâmuran Esen']::text[], 8.5, '{"poet":"Kâmuran Esen","poet_slug":"k-muran-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/kaybedecek-hic-bir-seyi-olmayana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asude Gönlüm', 'asude-gonlum-i-brahim-bayraktar-2a6y2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir yumağın iki ucu gibiyiz,

İçteki ben, dıştaki sen,

Sevdayı dolamışsın boynuma,

Dolayan sensin, dolanan ben.

Terin sinmiş tenime,

Tenim, tenine muhtaç,

Karışmışız birbirimize,

Aranan sensin, arayan ben.

Başını yaslayıp yanık bağrıma,

Tel tel zülüfleri döktün alnına,

Beyhude geçen günlerin aşkına,

Taranan sensin, tarayan ben.

Hazanı yaşarken asude ömrüm,

Cemalinle şenlendi yeniden,

İçim kıpır kıpır, yüreğim oynak,

Oynatan sensin, oynayan ben.

08.01.2004', 'Bir yumağın iki ucu gibiyiz, İçteki ben, dıştaki sen, Sevdayı dolamışsın boynuma, Dolayan sensin, dolanan ben. Terin sinmiş tenime, Tenim, t...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/asude-gonlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karmakarışık', 'karmakarisik-gokhan-kirman-ggavv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nedir bu her gece her gece şiir yazma mevzusu diyorlar,

Uyumak eldemi bunca acı,dert,kederle; Gerile gerile.

Genç yaşımda beyazlayan saçlarımı tek tek yolmak,

Zoruma gidiyor her gece bu işleri yapmak.

Başımda yeller esiyor püfür püfür serin serin,

Aşkının kalbimde açtığı yara çok derin.

Aşk denilince aklına ne gelir senin,

Belki bir bilmece,belki bir oyun.

Kayıkların dalgalarla sohbetini dinliyorum,

Her gece bu saatlerde.

Bir hoş oluyor onların kavgaları,

Kimi zaman dalgalar kazanıyor,kimi zaman kayıklar.

Her telden çalar derdi dağları aşan sazım,

Benki boynu büküğüm yerde kalan sazdan.

Artık elimi eteğimi çektim sevgiden vede aştan,

Haberim yok hiçbir şeyden evrenden vede dünyadan.

Yollarda avare avare gezer oldum,

Meçhule doğru gidiyorum adım adım.

Belki bir gün benimde duyulur adım,

İşte o zaman seni bulur ararım.

Delirmemek elde değil bu insanların arasında,

Kimi politika siyaset diyor,kiminin umrunda değil dünya.

Herbiri ayrı dünyalardan gibi bakıyor bir başkasına,

Delirmemek elde değil bu insanların arasında! ..', 'Nedir bu her gece her gece şiir yazma mevzusu diyorlar, Uyumak eldemi bunca acı,dert,kederle; Gerile gerile. Genç yaşımda beyazlayan saçları...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Kirman']::text[], 8.5, '{"poet":"Gökhan Kirman","poet_slug":"gokhan-kirman","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/karmakarisik-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buza Sardım Ateşi', 'buza-sardim-atesi-naime-erlacin-w3aq1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kuşlar vuruluyor yüreğimde

örseleniyor çiçekler

kan sızıyor damarlarından fidanın

tütüyor hasret sinmiş gözler 

sabahın kör alacasında

sustuk tüm susmalar gibi

gülücük kondurduk gözyaşlarına

titreyen bir alevin gölgesinde

ayrılık gergefi dokuduk yine 

sarıldık birbirimize üşürken gönüller

kan bağımız 

can bağımızla el ele

ah çocuk! 

o son bakışlar var ya hani

o son dakika 

öldürüyor adamı

ölümü bilmiyor da insan 

yürüyüp gidiyor işte

ağır yükmüş gurbet

bir kuş daha düştü biz ağlarken bu sabah

son çiçek kanarken içimizde

buza sardım ateşi 

korkma! 

biliyor musun 

kaç dönümlük yürek var bende 

gurbete kurban olsun diye yaratılmadı sevgi

yürek sımsıcak kalır ateşler buza kesse de 

(*)    Başta “can çiçeğim”, biricik kızım olmak üzere bütün gurbetçi dostlara sevgilerimle…

(08 Ocak 2003)', 'kuşlar vuruluyor yüreğimde örseleniyor çiçekler kan sızıyor damarlarından fidanın tütüyor hasret sinmiş gözler  sabahın kör alacasında sustu...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/buza-sardim-atesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çapraz', 'capraz-ahmet-fahri-sezgin-1lill', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kimse görmedi

Düşüncelerimi

Hep karanlık

Hep bulanık

Sudaki izler

Hatıra denen

Arsız sarmaşık

Ardına bakma

Kör eden ışık

Meyhanesizler

Temelsiz bina

Medetsiz şarap

Var mı biletin

Dönmeye bitap

Sen mi değiştin

Sır mı döküldü

Kutup yıldızı

Kadehte güldü

Gerçeği gizler

Cam kırıkları

Yolculuk sonu

Kış fırtınası

Zamana dönmek

Asit yarası

Çözülür dizler

Çözülür dilim

Biter mendilim

Akıllı kuşlar

Unutmak ölüm

Delilik gizler

Varsa zamanın

Önünde tuzak

Limana geldin

Kara cok uzak

Yerin denizler

Derin denizler', 'Kimse görmedi Düşüncelerimi Hep karanlık Hep bulanık Sudaki izler Hatıra denen Arsız sarmaşık Ardına bakma Kör eden ışık Meyhanesizler Temel...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Fahri Sezgin']::text[], 8.5, '{"poet":"Ahmet Fahri Sezgin","poet_slug":"ahmet-fahri-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/capraz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-1', 'mektuplar-1-halil-kosem-ytjjy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '“her mektup bir delildir” (kutadgubilig – yusuf has hacip) 

kardeşim  hepimiz

dingin kerpiç yontulara yazılmış yazgılarla

karıklara savrulan soyu bellisiz tohum gibiyiz

bize özgüdür

kıraçta büyümek at sürmek

çakır dikenleri pıtraklar arasında

melez ekmeği yiyerek

büyürken biraz söğüt dalıyız

zemheride ayrılmış gövdesinden

ve toprağa sokulmuş yarası

büyümelisin şimdi sen

çavdar büklerinde ötüşen kekliklerle

ardıç torularının yalnızlığında

umudunu kanatan pıtraklar

ve dizlerini dalayan kırkikindi dikenlerle

büyümelisin...', '“her mektup bir delildir” (kutadgubilig – yusuf has hacip)  kardeşim  hepimiz dingin kerpiç yontulara yazılmış yazgılarla karıklara savrulan...', ARRAY['Türk Edebiyatı','Şiir','Halil Kösem']::text[], 8.5, '{"poet":"Halil Kösem","poet_slug":"halil-kosem","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mektuplar-1-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-2', 'mektuplar-2-halil-kosem-fltmj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'her mektup yazılı tarihidir, tarif edilemeyen aşkların

baharı ayaza çakılmış bir çiçektir yeniden

ve tekrarıdır ister istemez yazılan herşey

naylon aşkların ipeğe benzeyen tenine yazılmasıyla başlar

her mektup bir ülkedir gözlerin kadar

gözlerinden büyük bir ülke görmedim ki daha

her akşam atmacalar üşüşür gözlerine

ya yağmurla kovalarsın bir kuytuda

ya gezdirirsin bütün ülkelerin sen kokan sabahlarını

bir fırtına savrulur

kabarır nefesin dudakların titrer

çakılır kalır kör saatlerin kör sesine

yalanlanır bütün tarih, keskin ve yumuşak

okunmuş sarı gazeteler gibi savruluruz sokaklarda

deniz kokusu gelmez olur

bulvarlar sen kokmaz artık

saçlarında alabildiğine yalnız bir kent kokar

bir kent ki o kadar yakın o kadar uzak

ne seni getirir ne beni götürür

sesin dallanır akşamların kaçamak saatlerinde

bir otobüs kalkar bir mendil sallanır bir gülüş kalır mahzun

sesinden bakarsın ben duymam görürüm bakışların kalır', 'her mektup yazılı tarihidir, tarif edilemeyen aşkların baharı ayaza çakılmış bir çiçektir yeniden ve tekrarıdır ister istemez yazılan herşey...', ARRAY['Türk Edebiyatı','Şiir','Halil Kösem']::text[], 8.5, '{"poet":"Halil Kösem","poet_slug":"halil-kosem","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/mektuplar-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-3', 'mektuplar-3-halil-kosem-9a1qg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'her şarkının bir notası ayrılıktır

ağlamayı öğrenmeseydim

seni düşündükçe

her mevsim bahar olmasaydı...

uçmayan kuşlardır nakışlarında

beyaz zakkum dalına çizilmiş

gözyaşına dönen bir çift kanat

çerçevelenmiş eğreti duvarlarda

türküleri yitik bir adam ağlar

bütün saat farklarında dünyanın

begonvillerin lila renginde akşamüzerleri

gecikmiş bir hayatı taşır cebinde

sensiz çıkılmış yolculuğum yok

biliyorsun

pusulasını unutup unutup gittiğim

hasreti yakılmış satırlarda...', 'her şarkının bir notası ayrılıktır ağlamayı öğrenmeseydim seni düşündükçe her mevsim bahar olmasaydı... uçmayan kuşlardır nakışlarında beyaz...', ARRAY['Türk Edebiyatı','Şiir','Halil Kösem']::text[], 8.5, '{"poet":"Halil Kösem","poet_slug":"halil-kosem","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mektuplar-3-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-tevfik-fikret-jif4v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Küçük, muttarid, muhteriz darbeler  

Kafeslerde, camlarda pür ihtizaz  

Olur dembedem nevha-ger, nagme-saz  

Kafeslerde, camlarda pür ihtizaz

Küçük, muttarid, muhteriz darbeler...

  

Sokaklarda seylabeler ağlaşır

Ufuk yaklaşır, yaklaşır, yaklaşır; 

Bulutlar karardıkça zerrata bir      

Ağır, muhtazır dalgalanmak gelir; 

   

Bürür bir soğuk, gölge etrafı hep,   

Numayan olur gündüzün nısf-ı şeb.

Söner şimdi, manzur olurken demin

Hayulası karşımda bir alemin.

Açılmaz ne bir yüz, ne bir pencere;  

Bakıldıkça vahşet çöker yerlere. 

    

Geçer boş sokaktan, hayalet gibi,

Şitaban u puşide-ser bir sabi;     

O dem leyl-i yadımda, solgun, tebah, 

Surur bir kadın bir rıda-yı siyah

  

Saçaklarda kuşlar -hazindir bu pek! - 

Susarlar, uzaktan ulur bir köpek. 

Öter guş-ı ruhumda boş bir enin,     

Boğuk bir tezad-ı sukun u tanın; 

  

Küçük, pür heves, gevherin katreler  

Sokaklarda, damlarda pür ihtizaz    

Olur muttasıl nevha-ger, nağme-saz

Sokaklarda, damlarda pür ihtizaz  

Küçük, pür heves, gevherin katreler...   

          YAĞMUR

    (Günümüz Türkçe''siyle)

Küçük, tekdüze, ürkek vuruşlar

Kafeslerde, camlarda titreşerek

Dürmadan türkü söyler, ağıt yakar

Kafeslerde, camlarda titreşerek 

Küçük, tekdüze, ürkek vuruşlar

                                    

Sokaklarda seller ağlaşır

Ufuk yaklaşır, yaklaşır, yaklaşır; 

Bulutlar karardıkca zerrelere bir

Ağır, olgun dalgalanma gelir; 

Bir soğuk gölge çevreyi bürür,

Gündüzden geceyarısı görünür.

Söner şimdi, görünürken demin

Maddesi karşımda bir alemin

Açılmaz ne bir yüz, ne bir pencere;  

Bakıldıkça vahşet çöker yerlere.

Geçer boş sokaktan, hayalet gibi

Koşarak bir Cocuk, başı Ortülü

O sıra, andığım gece, solgun ve bitkin,

Sürür bir kara Carşafı bir kadın

Saçaklarda kuşlar - acıdır bu pek! -

Susarlar, uzaktan ulur bir köpek.

Oter ruhumun kulağında boş bir inilti,

Boğuk bir sessizlikle tınlamanın çelişkisi

Küçük, istek dolu, inci gibi damlalar

Sokaklarda, damlarda hep titreşir

Ezgi söyler durmadan, ağıt yakar

Sokaklarda, damlarda hep titreşir

Küçük, istek dolu, inci gibi damlalar...

                            Tevfik Fikret 

                                  (1897)', 'Küçük, muttarid, muhteriz darbeler   Kafeslerde, camlarda pür ihtizaz   Olur dembedem nevha-ger, nagme-saz   Kafeslerde, camlarda pür ihtiza...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Fikret']::text[], 8.5, '{"poet":"Tevfik Fikret","poet_slug":"tevfik-fikret","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/yagmur-103-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-4', 'mektuplar-4-halil-kosem-nkj77', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kara serviler gibi çığlıklarım oldu

gömütlüklerin suskunluğunda...

makyajı tazelenmiş ölümlerden kalan

tez ulaşan kara haber

namluya sürüldü gümüş renginde sözün

kendine iyi bak... diye biten mektuplar

bir burcuna daha çakıldım 

ela gözlerine gurbet bürüdü...

bir parça sıva daha döküldü duvarlarından

korunmasız kaleleri düştü  ayrılıkların 

kendi yurdumda eskitip bütün gurbet türkülerini

koç boynuzu bir kilimde baktım', 'kara serviler gibi çığlıklarım oldu gömütlüklerin suskunluğunda... makyajı tazelenmiş ölümlerden kalan tez ulaşan kara haber namluya sürüldü...', ARRAY['Türk Edebiyatı','Şiir','Halil Kösem']::text[], 8.5, '{"poet":"Halil Kösem","poet_slug":"halil-kosem","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mektuplar-4-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '“Nehir Şiir” Ustasına Özet', 'nehir-siir-ustasina-ozet-halil-kosem-tf2ho', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bütün atları biz koşturduk

eşikte bizi bekler bütün gebe kadınlar

ağıtlarda biz yandık, bizden geçti yolu isyanların

bütün sevdaların beşiğini biz salladık

biz söyledik mektupsuz köylerin ninnisini

ey şiir! işte bileklerim...

yuvalımıdır kuşların dalında', 'bütün atları biz koşturduk eşikte bizi bekler bütün gebe kadınlar ağıtlarda biz yandık, bizden geçti yolu isyanların bütün sevdaların beşiği...', ARRAY['Türk Edebiyatı','Şiir','Halil Kösem']::text[], 8.5, '{"poet":"Halil Kösem","poet_slug":"halil-kosem","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/nehir-siir-ustasina-ozet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk', 'cocuk-halil-kosem-t18t7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kekre bir çağla tadı genzimde

alıcı kuşlardan kaçkın

turna bakışların türkülerde ürkek

kendi gurbetini omuzlayıp

geldin gene şehrime 

gecenin kolları iğde dalı üstünde

akşamüstü ürpermesi gibi duyarım geldiğini

su serpen bir kadın ağlar

yollar yırtılır içimde', 'kekre bir çağla tadı genzimde alıcı kuşlardan kaçkın turna bakışların türkülerde ürkek kendi gurbetini omuzlayıp geldin gene şehrime  geceni...', ARRAY['Türk Edebiyatı','Şiir','Halil Kösem']::text[], 8.5, '{"poet":"Halil Kösem","poet_slug":"halil-kosem","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/cocuk-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel''e Ve Çirkin''e', 'guzel-e-ve-cirkin-e-taciser-kaygisiz-5exqz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güzel''e

Dudakların bal gibi

Dilinse zehir senin.

Gözlerin deniz gibi,

Bakışların mermi senin.

Kendin öyle güzelsin,

dğşğncelerin yağlı bir urgan senin.

Güzeller güzeli olsan ne yazarş

Ruhun çirkin senin.

Çirkin''e

Çirkinsin belki bir çoğundan

Ama bir bakışın varki,

Erir buzlar geliverir kutuplardan.

O işven, o cilven,

Özverin, sessizliğin,hoşgörün.

Öyle güzel, öyle güzelsinki sen,

Noturedam''ım kamburu ol istersen.', 'Güzel''e Dudakların bal gibi Dilinse zehir senin. Gözlerin deniz gibi, Bakışların mermi senin. Kendin öyle güzelsin, dğşğncelerin yağlı bir u...', ARRAY['Türk Edebiyatı','Şiir','Taciser Kaygısız']::text[], 8.5, '{"poet":"Taciser Kaygısız","poet_slug":"taciser-kaygisiz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/guzel-e-ve-cirkin-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanrim', 'tanrim-suat-oktay-65ah0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'unuttun beni tanrim! 

Bak buradayim iste

Biraktigin yerden bir adim ötede! 

Bu eli kolu, bacagi veren sendin..

Sendin bu yüzü, kasi gözü veren! 

Ve beni var eden...

Ne oldu tanrim

ne oldu da beni unuttun? 

Bu benim tanrim ben...

Buradayim hala,

biraktigin yerden bir adim ötede, bekliyorum! 

Nefes aliyor, bagriyor, cagriyor, agliyorum; 

sesimi duyuramiyorum...

Unuttun beni, duy sesimi tanrim,

bu ses, bu haykiris, yakaris benim! 

Bu kas, bu göz, bu göz yasi...

bu hüzün, bu aci...

yüregimde atan sanci

Unuttun beni tanrim.

Oysa sana ait bir sey var bende.

Layik gördügün bu bedende...

Bu sonsuz, kocaman küçük evrende..

Buradayim iste..

Sen benim, ben senin icinde..

Ben buyum iste! 

unutma beni tanrim! 

7-12-03 Skövde(Isvec)', 'unuttun beni tanrim!  Bak buradayim iste Biraktigin yerden bir adim ötede!  Bu eli kolu, bacagi veren sendin.. Sendin bu yüzü, kasi gözü ver...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/tanrim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşadıkça Kimbilir', 'yasadikca-kimbilir-engin-namli-k416f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir demet gül gibi mi yar sevilir

Seveni ben nasıl anlayacağım

Tanımadan kahrı nasıl çekilir

Gerçek seveni nerde bulacağım

Aşkın değişmez kuralı belli midir

Hangi bendine tabi olacağım

Sevginin aziz olanı bendedir

Desem gönlüme kimi alacağım

Bir bakışla kim yüreğini verir

Gökteki dağları mı aşacağım

Bunca zorluğun tarifi kimdedir

Yerini nerde nasıl bulacağım

Aşk kemaline ermek mi gerekir

O tatlı düşle mi avunacağım

Garip gönlüm yaşadıkça kimbilir

Ben daha neleri tanıyacağım 

22:05 07.01.2004', 'Bir demet gül gibi mi yar sevilir Seveni ben nasıl anlayacağım Tanımadan kahrı nasıl çekilir Gerçek seveni nerde bulacağım Aşkın değişmez ku...', ARRAY['Türk Edebiyatı','Şiir','Engin Namlı']::text[], 8.5, '{"poet":"Engin Namlı","poet_slug":"engin-namli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yasadikca-kimbilir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aglamak...', 'aglamak-suat-oktay-jqgoq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aglamak geldi icimden

özlemim sizdi  damla diye gözumden

özumden, sözumden; 

ruhumun orta yerinden...

Gözum segirdi, elim dudagim titredi

cook uzaklarda bir yerde

tutsak bir bedende

bir nefes tazelendi

Dilimden yiten bir tad

kalbimden eksilen bir ad

azad yuregim azad

kanat gözumu kanat

Aglamak gekdi icimden

yuregimden, taa derinden 

titreyen sesimden,

bir kac damlaydi sadece, sizan gönlumden! 

28-12-03 (Mashult-Isvec)', 'Aglamak geldi icimden özlemim sizdi  damla diye gözumden özumden, sözumden;  ruhumun orta yerinden... Gözum segirdi, elim dudagim titredi co...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aglamak-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaos (Bunalım)', 'kaos-bunalim-orhun-basat-m5adq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'l

                 ‘’ben / balkonda rakı / yarım ay.

                 iki kişilik kalabalık etmiyor..’’

	                            II              

                Sen beni alıp	

	Çocuk parklarına götürmelisin			

                      - sevecen bir baba gibi, özlediğin -.

	Bana bir kadeh rakı verip, 

	                         salıncaklara bindirmelisin.

	Belki de yüzümde okuyup bu mutluluğu, 

	bir daha bulamaz nasıl olsa deyip, 

	beni o çocuk parkında bırakıp gitmelisin..

                                           III

	Anlarsınız birazdan, sarhoşum bu akşam.

                            - biraz Nazım okudum, ondan -

	biraz da bir şeyler kaldığından, 

	muhabbet - i sevdadan..

                                          IV

	Zor durumdayım, 

	kendime  bir mezar kazmak durumundayım.

	(denizleri, Küçük İskender gibi; 

	‘’gel pisi, pisi ‘’ diye çağırmaktansa..) .

	Ya da, iç kanamalarıma

	dostlar basmak zorundayım..

                                       V

                Ben kirli çarşaflarda öldürülen 

                şekillenmemiş bir sperma değilim, 

                iğfalden doğma, 

                orospu artığı gece..

                Direnmesini bilirim..

	                          VI

	Ben manyağım.

	Ben deliyim.

	Tüm sıkıntılara bir iskele, 

	ve yüzünde denizler taşıyan biriyim.

                                  VII

	Ayrı balkonlarda içilen rakılar, eğer:

	Rayından çıkan

	ve  bir midye tarlasına gömülen tren, 

	zıpkını yemiş bir balığın bunalımına

                                                 - ucuz turlarla -

                yeni konuklar götüren 

                ve şiirlerime

                tarifesiz  bir vapur gibi giren..

                Saçmalıklarsa, 

                Artık yeter demeliyiz

                ve bir daha içmemeliyiz...

                                VIII

                Resmini çekiyorum gecenin, 

                flaş patlamıyor.

               Şans işte..

               Bu benim hayatım ve korkusu, 

               korkular ki dinmez, 

               hayat ki içinde bir tek 

		kibrit olan, bir kibrit kutusu; 

              o da yanar mı, yanmaz mı? 

              Bilinmez..

                      IX

Ben, yazmaya yeminliyim, çocuk..

Üstüme gelme.

Bunları şiir zannedip de

sevinme..

                      X

	(mutfakta bulaşık yıkıyor, karım.

		senin ancak bulaşık yıkarken huzur bulan, 

			ve şiir yazmayı hayalcilik olarak yorumlayan

			                                  	ruhunu kutsarım..) 

                                  XI

Bitti bulaşık, 

söndü mutfakta ışık, 

ve balkonda yazılan şiir..

Şiirler ki 

zehirlerin en ürktüğü şeylerdir..

                      XII (bir başka ışıkta devam) 

Ve bundan sonraki şiirler

ve bundan sonraki geceler

ve ne varsa yaşamak adına 

ve - özellikle - benim adıma 

yaşanmamışların tadına bir çağrı

ve mermi uçlarındaki ölümlerin habercisi..

Ölümden öte şiirler var mı? 

Sevgi - anasız babasız bir yetimse -

yeni sevgiler doğar mı? 					

                     XIII

                 Şimdi intihar, 

                 - ve tüm sevgilere noterden vekalet, 

                               ya da dostlara ihanet - zamanıdır.

	Ki yeniden doğuşları andırır.

	(Perde iner, 

	ışıklar, bu kez, benim tarafımdan kapatılır.) 

                                  XIV (Özet) 

	Zokayı midesine kadar yutmuş

                yarım bir izmarit, 

	kendisini ikiye bölen lüfere; 

	hayatın tadını anlatmaktadır..', 'l                  ‘’ben / balkonda rakı / yarım ay.                  iki kişilik kalabalık etmiyor..’’ 	                            II     ...', ARRAY['Türk Edebiyatı','Şiir','Orhun Basat']::text[], 8.5, '{"poet":"Orhun Basat","poet_slug":"orhun-basat","theme":"Türk Şiiri","is_hero":false,"total_lines":95,"source_url":"https://www.antoloji.com/kaos-bunalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duzen duzene...', 'duzen-duzene-suat-oktay-j86ba', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Duzeni duzen, insan

insani duzen, duzen

bu duzeni duzen duzene...

duzen duzer, duzulen duzulur! 

duzenle duzulen, duzulur gider...

duzulen gelmez, gelse de gulmez,

gulse de bilmez, bilse de gulmez...

ölen öldu mu, bir daha ölmez...

duzen bu, duzdu mu böyle duzer! 

e, duzeni duzen insan, insani da duzen, duzen...

iste budur duzen! 

tek kelimeyle; ''duzen duzer''

özene bezene

bu siir bitmez,

uzayip gider böyle...

1995-Bursa', 'Duzeni duzen, insan insani duzen, duzen bu duzeni duzen duzene... duzen duzer, duzulen duzulur!  duzenle duzulen, duzulur gider... duzulen g...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/duzen-duzene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne yazık...', 'ne-yazik-i-brahim-ethem-bingul-mt8nr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine ses çıkmaz oldu senden

Ne çabuk döndün verdiğin sözden

Oysa bir selamın bile yeterdi bana,

Söylemiştim her fırsatta bunu sana.

Zorla olmuyor, zorla sevilmiyor insan

Ne yazıkki geç anladım bunu ben

Senin sevgin bu mu? Bu mu değerim? 

Bir sor kalbine bumu doğrusu.

Hayatında öncelik sıram ne acaba diye sordum

Kendi kendime dün akşam otururken yine sensiz

Saydım, saydım bana göre sıramı

Ne yazıkki çok gerilerde buldum kendimi hatta sonlarda

Bumu değerim, diye sordum kendi kendime

Değiştiremem ki seni, ben hiç yapamam ki bunu

Zorla olmuyor hayatta bazı şeyler ne yazıkki

Kaybedince anlıyor insan,insanın değerini

Umarım anlarsın kaybedince sende,değerimi.', 'Yine ses çıkmaz oldu senden Ne çabuk döndün verdiğin sözden Oysa bir selamın bile yeterdi bana, Söylemiştim her fırsatta bunu sana. Zorla ol...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ne-yazik-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş', 'gunes-sair-ufuckooi-2abgk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İkimizde özlüyoruz seni

Ne o birini ısıtabiliyor,

Ne de birisi beni', 'İkimizde özlüyoruz seni Ne o birini ısıtabiliyor, Ne de birisi beni...', ARRAY['Türk Edebiyatı','Şiir','Şair Ufuckooi']::text[], 8.5, '{"poet":"Şair Ufuckooi","poet_slug":"sair-ufuckooi","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/gunes-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebegime...', 'bebegime-suat-oktay-295vk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Burada gunler kisa, gölgeler uzun oluyor bebegim! 

kislari soguk ve karanlik...

Biraz cikinca gunes, uzayiveriyor gölgeler; 

gri adamlar gibi, yayiliyor kar uzerine...

Ben gölgeden hic korkmadim bebegim; 

varsin gölge korkaklari yavsak olsun! 

ben asla korkmam:

ne gölgeden, ne yalnizliktan, nen de yalancidan...

lakin yalandir, zemberek olan

zemberek cözulup, yalan soktu mu? 

yilani da, seni de, beni de zehirler bebegim...

yalan gercegin zehri, zehrin gercegi! 

ben senin kadar gercek, gercek kadar zehirim...

yilan beni isiramaz, benim gölgem burada

daha da uzuyor, cunku...

unuttun mu, yoksa? 

boyum 1.94`tu, bebegim! 

6-01-2004 (Nödinge-Göteborg', 'Burada gunler kisa, gölgeler uzun oluyor bebegim!  kislari soguk ve karanlik... Biraz cikinca gunes, uzayiveriyor gölgeler;  gri adamlar gib...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bebegime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hercai', 'hercai-sema-aka-jyewm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hercai gönlünde bir yer açtım kendime

Rengini ben verdim sevgimle

Keşke bende senin kardelenin olsaydım

Sen solduğunda ben gönlünde açsaydım

Kadifemsi teninde gezinseydi ellerim

Kara gözlerine baksaydı yeşil gözlerim

Sarı saçlarında güneşi yakalayıp

Pembe yanaklarına bir buse kondurabilseydim

Ama nafile sen bir hercaisin

İstediğin gönüllere kök salar yerleşirsin

Gönül kafesime hapsetsem bile seni

Gül yüzünü soldurur çekip gidersin

Alı al, moru mor hercai menekşem benim

08.01.2004', 'Hercai gönlünde bir yer açtım kendime Rengini ben verdim sevgimle Keşke bende senin kardelenin olsaydım Sen solduğunda ben gönlünde açsaydım...', ARRAY['Türk Edebiyatı','Şiir','Sema Aka']::text[], 8.5, '{"poet":"Sema Aka","poet_slug":"sema-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hercai-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağımlılar,,', 'bagimlilar-caglar-akarsu-xav3w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bağımlılar,,

...

Mahzun  boynunu büktü,

Hüzünlü gözlerinde bir isyan,

Dalga-dalga tüm benliğini sararken,

Yıkık bir evin soğuk salonunda,

Ayaklarını döşemeye sürerek, yürüdü,

Üzerinde renkleri solmuş, bir palto,

birkaç kez ökçe vurulmuş,

Boyası dökülmüş ayakkabıları,

Halsiz, vücudunu çekemiyordu,

Eski binanın tahtaları gıcırdarken,

İçinde ki iniltiler, kendini sarıyordu,

 Zamana isyan etti, çaresizce,

...

Duvarda asılı kalmış bir çerçevede,

Mezun olduğu yılı yazan bir diploma,

Her yıl aldığı başarılar, bir köşede,

Hiçbir kapıyı açmadıktan sonra,

Ne işe yarar,diye düşündü,

Kaç tane iş yerinin, merdivenlerini aşındırdı,

Hepsi yüzüne kapattılar,” iş yok! ”diye

Bir kenara itilmiş kalmış,

Mecalsiz, cılız bedeni ile,

Midesine giren kramplara aldırış etmeden,

Bir bardak suyu, kuru ekmekle içti,

...

Bitmez ihtilaller, yıkılan hükümetler,

Her yeni doğan bebeğin üzerinde borç,

Yüklenir dururken, bir biri ardına,

Ülkenin içinde ki krizler, büyüyordu,

Binlerce fakülte mezunu işsiz insan,

Köşe başında, seyyar satıcılık yapıyordu,

Bu kadar emek, bu kadar çalışma,

Heba olup, yok olup da gidiyordu,

Sonunda isyan etti,

...

Bir gece vakti,teslim olmuş benliğini,

Esir alarak, kendini, kendinden çaldılar,

Hiçbir zaman kullanmak istemediği,

Madde bağımlısı olmak biçare,

Şartlar zorluklara doğru yol alırken,

Yürütmüştü günler,unutmak için,

Derin bir soluk çekti yüreğine,

Acı bir lezzet, ruhunu sardı,

Titreyen elleri ve boş midesi,

Genç adam  boğazına  tıkanan

Hıçkırıklarını haykırmaktan gizledi,

İğne delikleri ile delik deşik kolları,

Kararmış bir dünya, siyahlaşmıştı

...

Günler sonra...

 Bu oda da, tek başına buldular,

Soğuktan kaskatı kesilmiş cesedini,

Arkasından haber salacak,  kimse bulamadılar,

Köşe deki hastanenin morguna koydular,

Yanı başında, sararmış bir diploma,

Kimliği yazılı  minik bir not bıraktılar.

...

caglar akarsu

2004/ocak', 'Bağımlılar,, ... Mahzun  boynunu büktü, Hüzünlü gözlerinde bir isyan, Dalga-dalga tüm benliğini sararken, Yıkık bir evin soğuk salonunda, Ay...', ARRAY['Türk Edebiyatı','Şiir','Cağlar Akarsu']::text[], 8.5, '{"poet":"Cağlar Akarsu","poet_slug":"caglar-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/bagimlilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnizlik', 'yalnizlik-suat-oktay-lfenz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Biraz yalnizlik

iyi gelir insana...

hem ben yanliz degilim ki; 

yanimda ben varim (ya) ...', 'Biraz yalnizlik iyi gelir insana... hem ben yanliz degilim ki;  yanimda ben varim (ya) ......', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yalnizlik-131-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lilith', 'lilith-mustafa-sureyya-sezgin-93zp9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''Sevgi ışıklıdır ısıtır”

Demişti ulu yaratan

Adem denedi önce birlikteliği

İhtirasla tutuşunca

Lilith tercih etti tekliği.

Duygular hırsa kapılınca

Sarıverdi alevler her yanı

Kül etti güzel olanı.

Bencillik yok edince  sevgiyi

Lilith terk etti  Ademi

Yürümedi o günden bu güne

Kadın erkek denkliği

Lilith’ten gelen şeytan tüyü

Havva’ya da bulaştı

O zamandan  bu yana

Kadınlar şeytanlaştı.

İstanbul, 08.01.2004', '''Sevgi ışıklıdır ısıtır” Demişti ulu yaratan Adem denedi önce birlikteliği İhtirasla tutuşunca Lilith tercih etti tekliği. Duygular hırsa ka...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/lilith-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mariya', 'mariya-omer-albayrak-l56kp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Elâ gözlerime, siyah saçıma,

Bakıpta abayı yakma Mariya! 

Ben evliyim, boşa düşme ardıma,

Beyhude kafayı bozma Mariya! 

Türküm her milletten fazla gururum,

Dünya ateş alsa olmaz umurun.

Senin olur günde dokuz randevun,

O zaman keçiler kaçar Mariya! 

Baban Hollandalı, anan bir Alman,

Sen bir Katoliksin, ben bir Müslümân.

Domuz eti yemeyince duraman,

Yasaktır dinimde benim, Mariya! 

Sen Incil okursun, bende Kur-an’ı; 

Sen çan sesi dinlen, bende Ezan’ı.

Senden doğacağın olmaz imanı,

Çekilmez vebâlin yükü Mariya! 

Sen ıslataman o boyalı tırnağı,

Bende yıkayamam kabı kacağı.

Sen beygir olursun kavga kaşağı,

Ben tımar edemem hergün Mariya! 

Kayserili’yim yerim sucuk, pastırma,

Soğanla, sarımsak katıktır bana.

“Ağzın kokar” diye başlan dırdıra,

Billâhi kaşınır sırtın Mariya! 

Güzelsin Mariya lâleler gibi,

Gönül heykeline koydum çelengi.

Hollanda Ömer’in olamaz yurdu,

Benim yurdum ANADOLU, Mariya! ...', 'Elâ gözlerime, siyah saçıma, Bakıpta abayı yakma Mariya!  Ben evliyim, boşa düşme ardıma, Beyhude kafayı bozma Mariya!  Türküm her milletten...', ARRAY['Türk Edebiyatı','Şiir','Ömer Albayrak']::text[], 8.5, '{"poet":"Ömer Albayrak","poet_slug":"omer-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/mariya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Güvercin', 'beyaz-guvercin-ruhsel-bariscimen-jrcwh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her sabah uyandığımda

Şarkılar yollarım sana

Yüreğimin şarkısını,

Bizim şarkımızı

Duyuyormusun onu? 

Her gün sevgilerimi 

Yolluyorum sana

Alıyormusun onları? 

Sarıyormusun yüreğine? 

Gün batarken sana en son

Beyaz bir güvercin yolluyorum

Tüm umutlarım yüklü onda

Sakın bana geri yollama...', 'Her sabah uyandığımda Şarkılar yollarım sana Yüreğimin şarkısını, Bizim şarkımızı Duyuyormusun onu?  Her gün sevgilerimi  Yolluyorum sana Al...', ARRAY['Türk Edebiyatı','Şiir','Ruhsel Barışçimen']::text[], 8.5, '{"poet":"Ruhsel Barışçimen","poet_slug":"ruhsel-bariscimen","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/beyaz-guvercin-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyle Bi Şeyler', 'boyle-bi-seyler-bekir-mutlu-gokcesu-4otkt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '...

“Sen de olsaydın keşke”

Dedim ya hani, dalmışım

Bakışımın erişebildiği

En ötelerde sen de kalmışım

İki dize yaklaşırken sana

Üç dize uzaklaşmışım dünyaya

Diz boyu özlem 

Bu gidip, gelmeler arasında

Derken davetsiz misafirler

Ansızın düşlerimin ortasında

Bir adam ve bir köpek

Yani hayat, yani gerçek

Biz de varız diyerek 

Geziniyorlar bakış açımda

Hoplayıp, zıplıyorlar

Satır aralarımda

Sana topladığım sözcükler

Saçılıp, savruluyor, uçuşuyor

Kuş tüyü misali havalarda

Karışıyor kafam

Şimdi ne işi var diyorum 

Bu adamla köpeğin hayatımızda

Böyle bi şeyler, ne olsun işte

Gülüyorum kendime

Sen de gerçek olsaydın keşke...', '... “Sen de olsaydın keşke” Dedim ya hani, dalmışım Bakışımın erişebildiği En ötelerde sen de kalmışım İki dize yaklaşırken sana Üç dize uza...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/boyle-bi-seyler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk''ın Sözü', 'ask-in-sozu-refik-recep-pelit-8lilj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Herkes aşık olurda 

Aşk ne der ki  bu işe 

Aşk bakar  bakar 

Güler belki de bize 

Aşk’a dair her dize 

Aşk şaşar belki bize 

Aşk aşk diye diye 

Aşk küser belki bize 

Adını aşk koyar 

Sığamayız aya yıla 

Aşk uğruna diye diye 

Terk ederiz ocak sıla 

Aşk bizi anlamaz ya 

Biz aşk’tan anlarmıyız 

Aşk peşinden koşar durur

Maşuku hiç sallarmıyız 

Aşk  ıslatmış ustümüzü

Yakmışız tütsümüzü

Düşüverdik yüz üstü 

Aşk çoktan bize küstü

Aşk  gönülde bir sesti

Çığlıklarda sessizdi

Duyamadık her sesi 

Beyazı Karası kirlisi

Aşk denen şey neydi

Rüzgarlarda devrildi 

Dedik ki aşk esti

Gerçek içinde tezvirdi

Aşk’ı cendere ile

Limon yapıp sıkmışız 

Aşk’ın suyuna dalarak

Çırılçıplak kalmışız 

Aşk’a sınır çizerek

Döşeklere gömmüşüz

Alevlenip yanmadan 

Dumanında sönmüşüz

Aşk sanmışız her şeyi 

Türlü hayaller görmüşüz 

Aşk değilmiş demeyip

Yaşamadan ölmüşüz 

Aşkı da bir dinlesek 

Acep ne der ki bize 

Adımı anmayın sakın 

Aşk yakışmaz densize 

Benzetmeyin rezile

Benzetmeyin yezite

Aşk benzer bir denize

Haramım hepinize', 'Herkes aşık olurda  Aşk ne der ki  bu işe  Aşk bakar  bakar  Güler belki de bize  Aşk’a dair her dize  Aşk şaşar belki bize  Aşk aşk diye di...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/ask-in-sozu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı yelekli Kız', 'kirmizi-yelekli-kiz-memet-zeki-ates-l3dyb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kırmızı yeleği nede yakışır

Yürüdükçe gül memeler tokuşur

Gözlerin, gözümle birhoş bakışır.

Öldürdün beni,beni kırmızı yelekli kız

Alacağım seni,seni Dünyalar tolansa vız

Saçlarını omuzuna döküşün

Sokağın başında dönüp bakışın

Çaresizmiş gibi boyun büküşün

Öldürür beni,beni kırmızı yelekli kız

Alacağım seni,seni Dünyalar toplansa vız

İpliğini makarana sarışın

Camın kenarında dantel örüşün

Mektubuma tez,tez cevap verişin

Öldürür beni,beni kırmızı yelekli kız

Alacağım seni,seni Dünyalar tolansa vız

Heyecandan ağlar gibi oluşun

Derin,derin hülyalara dalışın

Gel deyince hemen çıkıp gelişin

Öldürür beni,beni kırmızı yelekli kız

Alacağım seni,seni Dünyalar toplansa vız', 'Kırmızı yeleği nede yakışır Yürüdükçe gül memeler tokuşur Gözlerin, gözümle birhoş bakışır. Öldürdün beni,beni kırmızı yelekli kız Alacağım ...', ARRAY['Türk Edebiyatı','Şiir','Memet Zeki Ateş']::text[], 8.5, '{"poet":"Memet Zeki Ateş","poet_slug":"memet-zeki-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kirmizi-yelekli-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Başka Kadındı Nazan-2', 'bir-baska-kadindi-nazan-2-nazife-abayli-rzhpy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Okuyunca dünkü şiirimi,

Aradı Nazan beni.

Dünya üstüme gelse,

Aldırmam, dedi.

Ve devam etti.....

Biriyle tanışmış geçenlerde,

Kıpırtılar başlamış,

Heyecanla yüreğinde.

Ara sıra buluşur,

Sohbet ederlermiş,

Söylediğine göre,iyi biriymiş.

Özü sözü bir,

Yüreği hoş,

Görmeyi,

İsterse,sevmeyi bilirmiş.

Düşlerine alırlarmış birbirlerini,

Hayaller kurarlarmış.

Tutkulularmış.........

Baharı yaşıyorum,diyor Nazan,

İlkbaharı.

Dallarımda yeniden çiçekler açtı.

Üzmüyor artık beni,

Yaşamın akışı.

Gökkuşağının bir parçasıyız,

Renklerimiz aynı.

Aynı şarkıları mırıldanır,

Aynı türküleri söyleriz.

Sevdaya dair,

Aşka dair.

Ne şiddet var yaşantımızda

Ne çatışma.

Ne kavga,

Ne talan,ne ziyan.

Saygı var.

Aşk var.

Birlikte yaşattığımız,

Sevgimiz var.

Sevindim Nazan''ın mutlu olmasına.

Yürekten sevindim.

Onlara uzun uzun,

Ömürler diledim.

Sevilesi......

Yaşanılası......', 'Okuyunca dünkü şiirimi, Aradı Nazan beni. Dünya üstüme gelse, Aldırmam, dedi. Ve devam etti..... Biriyle tanışmış geçenlerde, Kıpırtılar baş...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/bir-baska-kadindi-nazan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demişsin', 'demissin-emin-baydil-qg3ww', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ömür gelmiş geçiyor,

Bana uslan demişsin.

Geçse de yanma, boş ver! 

Geri yaslan demişsin...

Çayda çıra ol yeter,

Eski sokak yol yeter,

Anlat anlat dol yeter,

Bana paslan demişsin...

Deniz ayrı, göl ayrı,

Gemi, vapur, sal ayrı,

Yağmur ayrı, sel ayrı,

Düş de ıslan demişsin...

Mendilin olmaz oya,

Uyursun doya doya,

At kendini kuyuya! 

Şimdi seslen demişsin...

Emin''im ki, söz başka,

Kastettiğin öz başka,

Ocak başka, köz başka,

Bana aslan demişsin...

Not: Bu şiiri, Yaşar Püllü Beyefendi’ye gönderiyorum.', 'Ömür gelmiş geçiyor, Bana uslan demişsin. Geçse de yanma, boş ver!  Geri yaslan demişsin... Çayda çıra ol yeter, Eski sokak yol yeter, Anlat...', ARRAY['Türk Edebiyatı','Şiir','Emin Baydil']::text[], 8.5, '{"poet":"Emin Baydil","poet_slug":"emin-baydil","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/demissin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Eyler', 'deli-eyler-nazife-abayli-ajn3z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevdam...

Dile geldi yine,

Yanık yanık,

Türkü söyler.

Korkarım,

Bir gün beni,

Kor eyler,

Duman eyler.

Yüreğim,

Sen olmadan,

Malı,mülkü,

Neyler? 

Korkarım.

Sensizlik,

Bu gece beni,

Biçare eyler,

Deli eyler!', 'Sevdam... Dile geldi yine, Yanık yanık, Türkü söyler. Korkarım, Bir gün beni, Kor eyler, Duman eyler. Yüreğim, Sen olmadan, Malı,mülkü, Neyl...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/deli-eyler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eridim', 'eridim-nazife-abayli-3htv4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hani bir gün,

Çıkıp geleceğim,

Demiştim ya kapına.

Geldim....................

Seslendim..............

Ses vermedin........

Belli ki,evde değildin,

Bekledim...

Bekledim...

Bekledim...

Yağan kar ile birlikte,

Ben de ERİDİM.', 'Hani bir gün, Çıkıp geleceğim, Demiştim ya kapına. Geldim.................... Seslendim.............. Ses vermedin........ Belli ki,evde değ...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/eridim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle bir yerdeyim ki...', 'oyle-bir-yerdeyim-ki-nazife-abayli-dabwl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öyle bir yerdeyim ki; 

Örümcek ağları,

Sarmış etrafımı.

Üstüme üstüme,

Geliyorlar...

Uzatırım elimi,

Bulaşırlar.

Yapış yapış.

Tiksinirim...

Yırtmak isterim,

Bir hamlede.

Yırtıp çıkmak,

Tutsaklıktan kurtulmak..

Yırtamam.............

Örümcekler,

Öylesine sağlam,

Örmüşlerki ağlarını.......', 'Öyle bir yerdeyim ki;  Örümcek ağları, Sarmış etrafımı. Üstüme üstüme, Geliyorlar... Uzatırım elimi, Bulaşırlar. Yapış yapış. Tiksinirim... ...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/oyle-bir-yerdeyim-ki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su', 'su-davut-suphan-7wt20', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'suyun azizliğiyle sevmek seni

yokuluğuyla çokluğuyla sevmek

uçup bulut olmak

kapılmak rüzgara ve gelmek senin kıyına

sonra güneşi bir hava da yağmur olmak

bardaktan boşalırcasına yağmak..

bir filize can vermek

toprağı aşındırmadan yağmak

seller sular gibi

damla damla büyümek,ırmak olup akmak

ve sizin evin ordan geçmek

gelip kovanı daldırdığında

seyretmek yakamozu sende

kovana dolmak evine girmek

olamayacağım kadar yakın olmak sana

elini yıkarken tutmak elini

içerken öpmek dudaklarından

teninin her zerresine dokunmak

öleceğimi bile bile

ve akıp gitmek tıpkı geldiğim gibi

bilinmeden kalınmadan

bir şekilde tekrar bulut olmak

tekrar yağmak,tekrar dolmak,tekrar olmak

susuz kalma pahasına hep senle

aşkı sulara gömmek içimdeki sulara

ve hayalini düşlemek yağmur ormanlarında', 'suyun azizliğiyle sevmek seni yokuluğuyla çokluğuyla sevmek uçup bulut olmak kapılmak rüzgara ve gelmek senin kıyına sonra güneşi bir hava d...', ARRAY['Türk Edebiyatı','Şiir','Davut Süphan']::text[], 8.5, '{"poet":"Davut Süphan","poet_slug":"davut-suphan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/su-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşimsin', 'gunesimsin-nazife-abayli-z4l0s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne sesin geliyor uzaklardan,

Ne de nefesin.

Ne, üşüyen ellerimi ısıtan,

Ellerin,

Ne de,

Gülümseyen gözlerin.

Tenin bile,

Dokunmuyor tenime.

Olsun be Sevgilim..

Küs değil,

Yüreğim yüreğine...

Bilirsin sen,

Yanımda olmasanda..

Bulutlar ne kadar sık,

Ne kadar kara,

Ne kadar yoğun,

Ve..............

Ne kadar yorgun,

Olurlarsa olsunlar,

Onların ardından,

Daima parlayan,

GÜNEŞİMSİN.', 'Ne sesin geliyor uzaklardan, Ne de nefesin. Ne, üşüyen ellerimi ısıtan, Ellerin, Ne de, Gülümseyen gözlerin. Tenin bile, Dokunmuyor tenime. ...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gunesimsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatabilirmisin Kader Denilip Geçileni', 'anlatabilirmisin-kader-denilip-gecileni-derin-oger-ocmw3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anlatabilirmisin 

Şu kader denilip geçileni

Tanıyabilirmisin günü ucundan

Açıp okuyabilirmisin bir mektup gibi

Buruşturup atabilirmisin yaşanacak belirsizliği

Anlatabilirmisin

Yağmurun çıplaklığını

Niye hep geri çeker deniz dalgalarını

Dağlara taşlara vurur da yüreğin yankısı gibi

Anlatabilirmisin süsleyip boşluğa astığımız düşlerimizi.

Anlatabilirmisin

Onca garip sevdayı

İçimizden dökemediğimiz yanlarımızı

Göğsümüzde soldurduğumuz gül yapraklarını

Anlatabilirmisin hantal günlere öylesine acele dağılışlarımızı.

Anlatabilirmisin 

İçine düştüğümüz şu yolculuğu

Yaz özlemle sonbahar niye hazin eser

Niye bir görünüp bir kaybolur dallara serili çiçekler

Yol buruk yolcu buruk bilinmez kim kimi  terkeder

Anlatabilirmisin bana kader denilip geçileni

Anlatabilirmisin..................', 'Anlatabilirmisin  Şu kader denilip geçileni Tanıyabilirmisin günü ucundan Açıp okuyabilirmisin bir mektup gibi Buruşturup atabilirmisin yaşa...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/anlatabilirmisin-kader-denilip-gecileni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalebent Mahkum', 'kalebent-mahkum-ali-osman-yilmaz-my5ce', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey giden yıl! 

Nasıl dertlenmeyeyim senden? 

Beni kendimden koparıp,

Gönlümü kaptırdın ‘O’ güzele,

Sonra acımadın bana,

Vurdun yerden yere.

Ve bana gösterdin,

Büyük bir ibretle,

Ölümün ve yaşamın üstündeki,

Elemin ve mutluluğun gücünü,

Sevmeye aç,aşka aç,

Yüreğimde,beyaz bir,

Zambağı yeşerttin,

Sevda çiçeğimi kurutup ardından,

İçimdeki yalnızlığa kelepçeledin.

Beni,yüreğimde,

Onsuz yaşamaya kalebent edip,

Müebbete mahkum ettin.

Nasıl şikayet etmeyeyim senden.

Şikayetlerimi anlatırken sana,

Yaşamdan dertlenmiyorum ben,

Bilirim ki ancak,

Yaşamdan kuşku duyanlar,

Şikayet eder,yakınırlar.

Seninle geçen günlerimden,

Pişmanlıkta duymadım,

Çünkü yaşamdaki gerçeği,

Arayanlar,benim gibi,

Acı çekmeye mahkumdurlar.', 'Ey giden yıl!  Nasıl dertlenmeyeyim senden?  Beni kendimden koparıp, Gönlümü kaptırdın ‘O’ güzele, Sonra acımadın bana, Vurdun yerden yere. ...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kalebent-mahkum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haberin Ola', 'haberin-ola-ali-osman-yilmaz-yqauz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dışarda kar yağıyor,

Ortalık bembeyaz,

Kendimi kar altında,

Dalları yükünü almış,

Saçlarına ak düşmüş,

Zamansız yaşlanmış,

Çıplak bir ağaç gibi,

Görüyorum.

Ama bekleyin biraz,

İlk bahar gelecek,

Aşk ve sevda çiçeklerinin,

Yapraklarından dokuduğu,

Yeşil pelerinini üstüme serecek,

Gözlerimdeki gülümsemelerimi,

Herkesten gizleyen,

Gözyaşlarım dinecek,

Ve gelen baharla birlikte,

Ölüm duygusundan arınıp,

Yaşamaya dört elle sarılarak,

Yeniden sevdalanacağım,

Yeni aşklara kanat açacağım,

Ey güzel,haberin ola.', 'Dışarda kar yağıyor, Ortalık bembeyaz, Kendimi kar altında, Dalları yükünü almış, Saçlarına ak düşmüş, Zamansız yaşlanmış, Çıplak bir ağaç g...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/haberin-ola-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk An,İlk Görüş', 'i-lk-an-i-lk-gorus-ali-osman-yilmaz-2sn6y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İlk görüş,

O andır ki,böler,

Yaşamın sarhoşluğunu,

Uyanışımızdan,.

O ilk alevdir ki,

Tutuşturur yüreğimizin,

Varını yoğunu.

O ilk nağmedir ki,

Yazdığımız,

İşlenir yüreklerimizin,

Gümüş telleri üzerine.

O kısacık andır ki,

Titretir yüreklerimizi,

Başlar gümbürdeyerek atmaya.

O ilk bakıştır ki,

Çözer sonsuzluğun içindeki,

Geleceğin sırlarını.

O ilk tohumdur ki,

Aşk tanrıçası tarafından,

Dağıtılır tüm gönüllere,

Ve sevgilinin gözleriyle,

Sevdalı elleriyle ekilir,

Aşk bahçelerine,

Tutkularımızla yeşerir,

Sevgi dolu can tarafından,

Biçilerek dağıtılır,tüm evrene', 'İlk görüş, O andır ki,böler, Yaşamın sarhoşluğunu, Uyanışımızdan,. O ilk alevdir ki, Tutuşturur yüreğimizin, Varını yoğunu. O ilk nağmedir k...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ilk-an-ilk-gorus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ela Ela', 'ela-ela-sadik-softa-k1r43', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne bakarsın ela ela

Şimdiye dek görmedin mi? 

Bakar durursun etrafa 

Önceden hiç görmedin mi? 

Birden bir hoş oluverdin

Gözlerinle soruverdin

Beni yeni görüverdin

Önceden hiç görmedin mi? 

Karşılaşırdık evelden

Konuşurduk hem gönülden

Sanki tanıştık yeniden

Önceden hiç görmedin mi? 

Süzüyorsun ela ela

Benziyorsun bir ceylana

Tutuldun mu şimdi bana? 

Önceden hiç görmedin mi? 

Şimdi konuşmak istersin

Bilmem ki kalpten ne dersin? 

Benim gibi sever misin? 

Önceden hiç sevmedin mi? 

Yanakların al al olmuş

Neden öyle elma gibi? 

Utanma ne olur söyle

Yoksa beni sevmedin mi? 

Sadık Softa’ya ne dersin

Benle gönül mü eylersin? 

Yoksa sen de sever misin? 

Önceden hiç sevmedin mi?', 'Ne bakarsın ela ela Şimdiye dek görmedin mi?  Bakar durursun etrafa  Önceden hiç görmedin mi?  Birden bir hoş oluverdin Gözlerinle soruverdi...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ela-ela-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hamile', 'hamile-ahmet-kurt-xzqkn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine tuhaf bir sancım var, 

Bu doğuma ben ebeyim. 

Yeryüzünde tek hancı var, 

Bense garip göçebeyim. 

Kalem kırık, kelam yitik, 

Çaldım ama düşmez tetik, 

Deme sakın değil etik, 

Ne hünkarım, ne de beyim. 

Dolaşırım düzü, dağı, 

Bulamadım henüz çağı, 

Çözemedim gizli ağı, 

Delifişek eski deyim. 

Zihnim sanki gezgin gibi, 

Kuyu derin, yoktur dibi, 

Fırtınalar eser gibi, 

Beyinlerde arbedeyim. 

Ruhum esir, kalbim buruk, 

Saçım beyaz, rengim donuk, 

Çırpınırım çıkmaz soluk, 

Öyle garip seferdeyim. 

Kurdoğlunun çok zor işi, 

Karışıyor erkek dişi, 

Şimdi çeker biri fişi, 

Ben bir şiire gebeyim.', 'Yine tuhaf bir sancım var,  Bu doğuma ben ebeyim.  Yeryüzünde tek hancı var,  Bense garip göçebeyim.  Kalem kırık, kelam yitik,  Çaldım ama ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hamile-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelincik Tarlası Yüreğim', 'gelincik-tarlasi-yuregim-zeki-ergin-10lk6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'genç düşünmeli insan

kırçiçekleri gibi olmalı

yüreği insanın

zemheri soğuklarında ısınmalı 

bahar düşleriyle

gelincik tarlası olmalı  yürekler

sıcacık düşünmeli insan

alıp başını gitmeli arada bir

uzak denizlere

arada bir çocukça gülmeli

sevecen olup

dağlarda türkü söylemeli

_erenköy 8oca04

_dağlara ver sırtını yt:haz09', 'genç düşünmeli insan kırçiçekleri gibi olmalı yüreği insanın zemheri soğuklarında ısınmalı  bahar düşleriyle gelincik tarlası olmalı  yürekl...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gelincik-tarlasi-yuregim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fotoğraf', 'fotograf-i-brahim-i-spir-gd4ng', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'acemi gülüş sırıtır yüzü kara

yanyana değiliz fotoğraf fulü

topla karanlığı gökyüzü

çoğalsın harı güneşin

bir kuş kelebek gibi yenlik

ve mermi kadar sesli

düşler ölü soğukluğunda

toplanır scak denizlere

dağlar seslenir ovaya

uğuldamaya başlar

önüne geçilmez

illaki düğün', 'acemi gülüş sırıtır yüzü kara yanyana değiliz fotoğraf fulü topla karanlığı gökyüzü çoğalsın harı güneşin bir kuş kelebek gibi yenlik ve mer...', ARRAY['Türk Edebiyatı','Şiir','İbrahim İspir']::text[], 8.5, '{"poet":"İbrahim İspir","poet_slug":"i-brahim-i-spir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/fotograf-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı; ''UMUT '' Olacak..!', 'adi-umut-olacak-umut-gul-z75hc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gün

kesilecek Çığlıklar

Nefes alacağız

Susacak ölüm kusan makineler

Ağlamayacak  çocuklar

Isırırlarken elma şekerlerini

Kıpkırmızı dudaklarıyla

Söyleyecekler Atlı karıncada şen şarkılarını

………………………….

Umudum o dur ki…

Sevgiye yazılacak şiirler

Umuda uzanacak tüm yollar

Ankara da seğmenler

Aydın da efeler

Erzurum da dadaşlar

Ve tüm cümle gardaşlar

Tutuşacaklar halaya

Kimi bağlama çalacak

Kimi kemençe

Kimi tulumunu alacak

Kimi tempo tutacak

Kırk gün kırk gece

Akıllara ziyan bir şenlik olacak

Dağ başlarında  yakılacak ateşler

Yorulmadan ayaklar

Uyuklamadan başlar

Tez gelsin artık muştucular

Yıkılacak tabular

Yok olacak korkular

Gömülecek yedi kat yerin dibine

Bu anlamsız töreler

Vurguncular, soyguncular, hortumcular

Üfürükçüler, şeyhler,müritler

Yok olacak yalanlar ve de talanlar

Yanmayacak artık ozanlar

Donmayacak soğuktan garibanlar

Üç kuruşa satılmayacak on beşinde genç kızlar

Yıkılmayacak hiç uğruna ocaklar

Bir lokma aş için gurbete düşmeyecek civan yiğitler

Ağıtlar düzmeyecek ardından kınalı gelinler

Ölmeyecek acından cami avlusunda bebekler

Kana bulanmayacak bembeyaz gelinlikler

.......................................................................

Bir gün…

Barış kadın anne olacak

Ve doğacak  o gül yüzlü bebek

Kız yada erkek hiç fark etmeyecek

Bildiğim bir şey var 

Adı; umut olacak..! 

Adı; “UMUT”  olacak….', 'Bir gün kesilecek Çığlıklar Nefes alacağız Susacak ölüm kusan makineler Ağlamayacak  çocuklar Isırırlarken elma şekerlerini Kıpkırmızı dudak...', ARRAY['Türk Edebiyatı','Şiir','Umut Gül']::text[], 8.5, '{"poet":"Umut Gül","poet_slug":"umut-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/adi-umut-olacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemlerim Firarda', 'ozlemlerim-firarda-hikmet-karakus-7kdc2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yalnızlığımı yüreğime hapsettim

sevginle birlikte...

Ama özlemlerim firarda,

Seni hep arar dururum,

Söyle bana; 

Seni nasıl bulurum? 

(Ank.1999)', 'Yalnızlığımı yüreğime hapsettim sevginle birlikte... Ama özlemlerim firarda, Seni hep arar dururum, Söyle bana;  Seni nasıl bulurum?  (Ank.1...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Karakuş']::text[], 8.5, '{"poet":"Hikmet Karakuş","poet_slug":"hikmet-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ozlemlerim-firarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şerefine', 'serefine-zafer-murat-cetintas-pmc9i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu gece seni unutmanın şerefine kadeh kaldırıyorum

Seni unutmanın şerefine bir daha

Bir daha içiyorum

Burası hiçbir alem dairesini içine almadığı

İsli basık bir meyhane

Masalar taştan,sandalyeler kütükten

Kırık bi lüküs asılı simsiyah olmuş tavanda

Yeni keşfettim burayı

Sen burasını bilmezsin

Duvarlarda perişanlığım

Seni anıyorlar

Bense unutmak istiyorum.

Bu gece perişanım vede dertliyim

Artık mısralara sığmıyor kahrım

Aklıma gldikçe ettiklerin

Kadehlerden medet umuyorum.

Bu gece sarhoşum

Buz gibi masalara düşüyor başım

Sıktıkça suyunu çıkarıyorum boşalan kadehlerin

Bu gece seni unutmanın şerefine kadeh kaldırıyorum

Seni unutmanın şerefine bir daha

Bir daha içiyorum

                                              MURAT REİS', 'Bu gece seni unutmanın şerefine kadeh kaldırıyorum Seni unutmanın şerefine bir daha Bir daha içiyorum Burası hiçbir alem dairesini içine alm...', ARRAY['Türk Edebiyatı','Şiir','Zafer Murat Çetintaş']::text[], 8.5, '{"poet":"Zafer Murat Çetintaş","poet_slug":"zafer-murat-cetintas","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/serefine-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-k-muran-esen-kebr7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bilir misiniz,

İğne atsanız yere düşmeyecek

Bir kalabalıkta yalnızlığı? 

Hiç yaşadınız mı,

Başkalarının yanındayken

Anlatılmaz, anlaşılmaz yalnızlığı? 

Bir derdim yok.

Ama mutlu da değilim.

Sensizim.

Ailemin yanındayken bile

Sanki kimsesizim.

Katbettiğim bir şey yok,

Ama arıyorum.

Üzüldüğüm hiç bir şey yok,

Ama ağlıyorum.

Bu gürültüde sessizliği,

Bu kalabalıkta yalnızlığı yaşıyorum.', 'Bilir misiniz, İğne atsanız yere düşmeyecek Bir kalabalıkta yalnızlığı?  Hiç yaşadınız mı, Başkalarının yanındayken Anlatılmaz, anlaşılmaz y...', ARRAY['Türk Edebiyatı','Şiir','Kâmuran Esen']::text[], 8.5, '{"poet":"Kâmuran Esen","poet_slug":"k-muran-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yalnizlik-132-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yenildim', 'yenildim-bekir-mutlu-gokcesu-5cyfu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geceler yalnız

Geceler sessiz

Benim gibi…

Müzik susmuş

Çiçekler solmuş

Geceler soğuk

Geceler karanlık

Dertliler yine dertli

Sarhoşlar yine sarhoş

Kimsesizler kimsesiz

Zaman yine geçmekte

Zaman en güçlü

Ve her şeye galip

Sevgiler sonunda

Ne yazık ki malüp

İçsem içesim var

Uyusam uyuyasım

Sabaha dek

Koşsam koşasım yok

Yorgunum, yenildim…

(Sararmış Sayfalardan)', 'Geceler yalnız Geceler sessiz Benim gibi… Müzik susmuş Çiçekler solmuş Geceler soğuk Geceler karanlık Dertliler yine dertli Sarhoşlar yine s...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yenildim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayperi'' m (yıllara yenik bir aşkın öyküsü)', 'ayperi-m-yillara-yenik-bir-askin-oykusu-hidir-cam-j6vj4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'AYPERİM

Dün bir gül yollamışsın

Kokusuna gizlemiş bir dil yollamışsın Ayperim

dayanamıyorum

yalvarıyorum ne olur durma gel diye

saçlarımdan uçuşan

yüreğimde tutuşan ömür bir yel diye

Oysa biliyorsun

dördüncü mevsimimi de çoktan tükettiğimi.

Zemheri tipilerine karışıp

tükenip bittiği...

.

Oysa biliyorsun 

ayaklarımın göz hapsinde ki naçarlığını

ve yüreğimin ayaklarımda tutsak kaldığını.

Yaşam, öğünürken zaman değirmeninde

törelerin gençliğimi nasıl çaldığını

.

Şimdi mümkün mü eyy Ayperim

cemreyi yeniden düşürmek buzul yüreğime.

Ya da anıları sil baştan yaşamak

sil baştan yaşamak yaşanmamışları

Şimdi mümkün mü eyyy Ayperim

zamanı mühürleyip

günü batıdan doğurmak

bir gün de olsa

.

Miladım sendin 

Bir düş görmüştüm

yirmi beş yıl evvel

Üç yıl uyanamadım

gel de bana sor

bir ömre değer.

.

Sonra ayrılıklar girdi araya

evlilikler girdi

Can, canı doğurdu

can cana boğuldu

çocuklar girdi

.

Her aşk bir düştür 

uyanınca biter

Her düş bir aşktır 

yaşamaktan da beter

Ben, seni hep düşlerimde gördüm 

uyanınca yokluğunda sevdim Ayperim

varlığından da güzeldin

.

Sen yoksun aslında biliyorum

ellerin yok

ayakların yok

gözlerin yok

Ama varsın; 

Bak bir kuş konuyor pencereme

yağmurlar yağıyor, 

yıldırımlar çakıyor

Bir çocuk ağlıyor bahçemde 

gözyaşlarına boğuluyorum

Yokluğunla varsın Ayperim

varlığınla yoksun 

yirmi iki yıldır.

.

Bir ömür borçlandım yaşama 

Bir can kiraladım,

kefilim sendin

Son taksidim boynumda

tökezleyen yüreğimle ödüyorum

Gel diyorsun bana

Gel diyorsun ama

Ben, benim bensizliğime

sana gidiyorum

.

Vakit çok geç,

Yorgunum, 

kollarım kalkmıyor Ayperim

benden bu kadar.

Kendi ataşına yanan

tenden bu kadar.

.

Yolsuzluğun kavşağında

bir yol ayrımındayım 

Hiç dermanım kalmadı

bunun da farkındayım

.

Dün tükendi

gün tükendi 

Can, göğe yöneldi

yön tükendi

.

Çok geç öğrendim 

Çok güç öğrendim

Yaşamak için aşk

aşk için yaşamak gerek.

Yoksa ikisinden biri 

mümkün mü Ayperim

atmıyor

atmaz 

atmaz bu yürek...', 'AYPERİM Dün bir gül yollamışsın Kokusuna gizlemiş bir dil yollamışsın Ayperim dayanamıyorum yalvarıyorum ne olur durma gel diye saçlarımdan ...', ARRAY['Türk Edebiyatı','Şiir','Hıdır Çam']::text[], 8.5, '{"poet":"Hıdır Çam","poet_slug":"hidir-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":98,"source_url":"https://www.antoloji.com/ayperi-m-yillara-yenik-bir-askin-oykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Esra', 'adi-esra-hasan-kaya-invmq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çok değişti sokağımız

Mahalle tanınmaz oldu

Yol geçti Hakkı amcanın bostanından

O yeşil marullar,

Bademler, sırıklı Ayşe kadın yok artık

Ahşap evlerin pencerelerinden yarı beline kadar sarkan 

Kadınlar, kızlar, cam güzelleri de yok

Kıvırcık kız kocaya varacaktı

Olmadı

Otuz beşin de birine gelin gidiyordu

Laf aramızda az can yakmadı

Greyfurt büyüklüğü memeleri

Ve kıvırcık saçlarıyla 

Hepimiz, sokağımız biz

Bir yerlere gidiyoruz 

Bilinmedik istasyonlarda 

                    anlık bekleyişler içindeyiz

Bilinmeze kalkan son trende

Üçüncü mevki yolculuklar bizimkisi

Yollardayız, yollar bizden başlıyor

Bizde bitiyor.

Koca bir şehir aldı başını gitti

Senin çekip gitmene neden kızdık 

Anlamadım...

Seni hiç anlamadık

Yüreğini kıvırcık kızın 

Saçlarına doladığında da anlamamıştık

Sen içimizdeki deliydin

Uslu, ağırbaşlı susmalarımıza

Baş kaldırış

Kadir’i bilirsin, arada bir görüşürüz

Her görüşmede seni sorar

Ve durmadan romatizmasından yakınır

Ayşe’yi gördüm geçenlerde

Üsküdar Beşiktaş motor iskelesinde

Motor bekliyordu

O tanımasaydı beni

Ben asla tanıyamazdım

İnsan bu kadar değişir

Ayakta durmamıza engel 

Depremler yaşıyoruz

Unutmadan söyleyeyim

Üzerimde kalmasın

Son zamanlarda baş ağrılarından 

Göz açamıyorum

Ve unutkanlık başladı

Kıvırcık Kızın sana çok selamı var.

Sahi adı neydi şu kızın

Temmuz sıcağı gözleri ışıldar 

                      seni her sorduğunda

Habersiz kaldığında 

Gülüşü solan Eylül yaprağı

Bu yüzden çok yalan söyledim

İyi dedim

Sana selamı var, özlemiş dedim

Dün Salacağa gittim

O küçük ahşap iskele şimdi kahvehane

Biraz oturdum

Bir de çay içtim

Kız Kulesini seyrettim

Biliyorum kıskandın 

Bunu yazdım diye belki de kızdın bana

Ama sen son halini görmedin 

                               Kız Kulesinin

İyi ki de görmedin

Çürüyen yanımız, yorgunluğumuz

Yalnızlığımız

Zamana yenik düşüşümüz.

Yüzmeyi burada öğrendik

Çocuk bedenlerimizi burada bıraktık

Boğazın sularına

Bu kıyalarda titredik mavi,serin 

Şimdi beyaz patiska donlarıyla

Üç beş aymaz çocuk yüzüyor

Az önce geldiler 

Boya sandıklarıyla

Boğaz kirlendi diyorlar ya

İnanma 

Biz kirlendik

Her renkten, 

Her cinsten kirliliğimiz akıyor

Mavinin, yeşilin yerine', 'Çok değişti sokağımız Mahalle tanınmaz oldu Yol geçti Hakkı amcanın bostanından O yeşil marullar, Bademler, sırıklı Ayşe kadın yok artık Ahş...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kaya']::text[], 8.5, '{"poet":"Hasan Kaya","poet_slug":"hasan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":82,"source_url":"https://www.antoloji.com/adi-esra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbetteyken', 'gurbetteyken-gulsen-senderin-2ex1h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her şey burda yabancı güller eller yabancı 

Bir tek sen gülümseyen bana teselli veren 

Metrolarda tramvaylarda tüm yollar yabancı 

Akşamın yangınında sensin beni bekleyen 

Viyana meydanları, valslar, diller yabancı... 

Sabrım hiç kalmadı sonu gelsin şu gurbetin 

Düşlerimde İstanbul köprüler ışıl ışıl 

Israrla hazzını arar sezdikçe vuslatın 

Nerde Bakırköy,nerde anılarıyla sahil 

Viyana meydanları, valslar,diller yabancı... 

Yol hazırlığı başladı kalbimde heyecan 

Hasret ile yandığım her şey beni bekliyor 

Beni hep bağrına basan, gülümseyen vatan 

Yeşeren umutla içime sevgi ekliyor 

Viyana meydanları, valslar, diller yabancı... 

08-01-2004- Perşembe – 12. Viyana', 'Her şey burda yabancı güller eller yabancı  Bir tek sen gülümseyen bana teselli veren  Metrolarda tramvaylarda tüm yollar yabancı  Akşamın y...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gurbetteyken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Evinden Şiirler 8', 'deli-evinden-siirler-8-oguzkan-bolukbasi-xt4xe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Meyhanesinde şarap içilirdi 

Mezeler leblebi ve peynir

Yanında bir gençlik nasıl yenir

Anlatırdım

Siz aşkın yasak olduğu günleri bilir misiniz

Devrimleri

Tanrı dağlarına gidenleri

Diğerleri

Yani hayat var diyenleri

Ot diye dövdükleri günleri bilir misiniz

Üç gençle kurulan dar ağaçlarında

Onüç yılda onlarca kişinin sallandırıldığını

Sokak ortalarında

Doğru sanılanlar uğruna kardeşlerin vurulduğunu

Tanrı adına mahkemelerin kurulduğunu

Onun içindir 

Altmışsekiz kuşağı

Yetmişsekiz kuşağı

Saramadı hiç bir beli

Dünyayı kurtarma ideali

Onları bile kurtaramadı

En önemlisi kendimiz olmaktı

Kendimiz gibi davranmaktı

Kendi ateşimizde yanmaktı

Sağdan ve soldan ve ortadan

Akıl çıkınca rotadan

Aklın isyanını yaşamak zordur

Bedenin isyanına dönüşür, kızgınlıklar

Akıl üretir

Beden dövüşür

Akılsız beden büzüşür kalır kendi gölgesini döver sonunda

Her meyhane dönüşünde

Kurtarılmış bir vatan bırakırdık meyhaneciye

Hepimiz vatan severdik

Hepimiz can verirdik

Hepimiz kıbrıs dedik

Ya taksim

Ya ölüm mitinglerine giderdik

Taksim sağlandı

Şimdi endişe var

Bazı planlar

Ben düşünemiyorum canlar

Kıbrısta şehitlikler var

Bize düşmez düşünmek

Bizden akıllılar

Hakkımızı yemezler

Değil mi

Efendim

Annan 

Yandım anam olmasın

(yeteneksiz kuşaklar yine telef olmasın uşaklar- başka bir deli evi sakini)', 'Meyhanesinde şarap içilirdi  Mezeler leblebi ve peynir Yanında bir gençlik nasıl yenir Anlatırdım Siz aşkın yasak olduğu günleri bilir misin...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/deli-evinden-siirler-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluğuma Küçük Bir Gezinti', 'cocukluguma-kucuk-bir-gezinti-nazife-abayli-tpsye', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çocukluğumda,

Babam maden ocağından,

Senelik izne ayrıldığında,

Köyüne götürürdü,

Annemi,beni,kardeşlerimi.

Karayolu yoktu o zamanlar,

Sarıldık mı dağların yamaçlarına,

Elimizde çantalar,

Yürür,yürür,yürürdük..

Uzun boyluydu babam.

Attığı adımlara yetişmek için,

Koşardı arkasından annem.

Bizler çocuktuk,

Oynar,koşar,zıplar,

Onlardan önce köyün başına varırdık.

Ninem gördümü bizi,

Başlardı ağlamaya.

Dur ağlama,daha yeni geldik,

Derdi babam.

Gideceğimiz güne ağlarmış,

Meğerse ninem.

Akşam oldumu,

Kör karanlıkta sokakta,

Ateş böceklerini yakalamaya  çalışırken,

Birbirimizle çarpışırdık.

Ağlardık,sızlardık,canımız yanınca.

Eve koşardık,

Annemin çağrışıyla.

Gaz lambası ışığında,

Fındık ayıklar,

Birbirimize atardık.

Çuvallar dolusu çok gelirdi,

Arta kalanlar bizleri eğlendirirdi.

Mısır soyardık bazen.

Köyün tüm gençleri gelirdi.

Köy türküleri söylenir bir taraftan,

Bir taraftan gelinlik kızlar seçilirdi.

Sabah oldumu,

Ninemin sacda pişirdiği,

Mısır ekmeğinin kokusuyla

Uyanırdık.

Hemen sofra başına toplanırdık.

Tarlasında kendi yetiştirdiği

Günebakanları sıkarak,

Süzerek elde ettiği,

Ayçiçek yağını,

Kara,kapkara tavaya döken ninem,

İçine birde yumurta kırardı.

Hele o,ocakta demlenen çayın tadını,

Senelerdir unutamam.

Tarlada, bahçede çalışırken annem ve ninem,

Bizler, ağaç dallarına,

Kurduğumuz salıncakta sallanır,

Yeşilliklerde boğuşurduk.

Üç mevsim yaşadığımız şehirin,

İntikamını alırcasına,

Kır çiçeklerini toplar,

Rengarenk yaz güllerini koklar,

Taklalar atardık.

Çok severdim,

Ellerimizdeki hasır sepetlere,

Kiraz,vişne,

Çeşit çeşit meyve toplamayı.

Ninem,

Kumanya almak için,

Şehrin pazarında satardı.

Sabah beşte kalkılırdı.

Sarılır küfelere yükler,

Yollara çıkılırdı.

Heyecanla beklerdim,

Ninemin pazar dönüşünü,

Kazandığı parayla,

Bize halkalı şeker de alırdı çünkü.

Kolumuza takar bilezik yapardık.

Yemeye kıyamazdık.

Şimdi..............

Kalmadı hiç biri.

Ne mısır ekmeği,

Ne halkalı şekeri.

Yıllardır görmedim köyümü.

Zaten ninemde,

Yıllar önce öldü.

Elimde olsa yine,

Koşardım tarlalarına,

Yemyeşil kırlarına.

Yaz güllerini koklar,

Kır çiçeklerini toplar,

Taç yapardım başıma.

Özgürlüğün adını

Kocaman kocaman yazardım,

Dağlarının yamaçlarına.', 'Çocukluğumda, Babam maden ocağından, Senelik izne ayrıldığında, Köyüne götürürdü, Annemi,beni,kardeşlerimi. Karayolu yoktu o zamanlar, Sarıl...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":91,"source_url":"https://www.antoloji.com/cocukluguma-kucuk-bir-gezinti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluğun Ezgisi', 'mutlulugun-ezgisi-filiz-angay-1l2i1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kardeşime...

Yalnızlığın sessizliğinden geldim

Soğuktu, umutsuzdu.

Ufkun sonsuzluğunu,

Güneşin sıcaklığını,

Umutların heyecanını toplayıp

Doğanın ritmini ekledim,

Ve sana üfledim,

Mutluluğun ezgisi kulaklarına dolsun diye...', 'Kardeşime... Yalnızlığın sessizliğinden geldim Soğuktu, umutsuzdu. Ufkun sonsuzluğunu, Güneşin sıcaklığını, Umutların heyecanını toplayıp Do...', ARRAY['Türk Edebiyatı','Şiir','Filiz Angay']::text[], 8.5, '{"poet":"Filiz Angay","poet_slug":"filiz-angay","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/mutlulugun-ezgisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Panzehir', 'panzehir-nazife-abayli-s9wp4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu gece ansızın,

Karanlık bastı odamı.

Göremez oldum etrafımı.

Bir ses duydum,

Sinsice,

Derinden,

İrkildim.

Usul usul yaklaşan,

Bir sağdan,bir soldan,

Yalnızlığımdı gelen.

Dolandı birdenbire,

Önce ayaklarıma,

Sonra kollarıma,

Ve boğazıma.

Nefes alamaz oldum.

Boğuldum.......

Tuttuğum gibi ellerimle,

Kavradım iyice.

Pencereden dışarı,

Tüm kuvvetimle,

Savurdum.

Ama nafile,

Gitmem diye dayattı.

Önce ayaklarıma,

Sonra kollarıma,

Ve............

Tüm vücuduma,

Zehrini akıttı.

Öyle bir yaktı,

Öyle bir yaktı ki damarlarımı,

Kıvrım kıvrım kıvrandım.

Alıp elime kör bir bıçak,

Kanını akıtamadım.

Acısını............

Bir başıma yaşadım.

Haykırdım,başkaldırdım,

Sesimi sana duyuramadım.

Ey............! 

Dönülmez yollara,

Giden sevgili.

Gel artık,

Neredeysen? 

Yalnızlığımın,

Panzehirin sen!', 'Bu gece ansızın, Karanlık bastı odamı. Göremez oldum etrafımı. Bir ses duydum, Sinsice, Derinden, İrkildim. Usul usul yaklaşan, Bir sağdan,b...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/panzehir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balık Burcuyum Ben.', 'balik-burcuyum-ben-ali-osman-yilmaz-a862o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bilirmisiniz? 

Balık burcuyum ben.

23 şubatta,soğuk mu? Soğuk,

Camı çerçevesi olmayan,

Murat dayının ahırdan bozma,

İzmit körfezine tepeden bakan,

Küçücük bir köyde,

Yuvacık’ta doğmuşum.

Zavallı anacığım,

Göçmen geldikleri bu köyde,

Benden önce bir kardeşimi,

Doğurmuş,ama yaşatamamış,

Benim doğduğum evde soğuktan,

Kaybetmiş,bir aylıkken,

Acılarıyla birlikte,

Toprağa vermiş.

Kader işte,ne diyeceksin? 

O kardeşim yaşasaydı şimdi,

Ben yaşamıyor olacaktım,

Bu sevda acısını çekmeyecek,

Bu şiirleri yazmayacaktım.

Her şey benden önce,

Doğup ta yaşayamayan,

Ve soğuktan donarak ölen,

Adına,sağır Alilerin delisi denen,

Dayıları Bilal’in adı verilen,

Abim Bilal’in ölmesiyle başlamış.

Çocuk aşkıyla annem,

İlk fırsatta peydahlamış hemen,

Ve ben soğuk bir 23 şubat günü,

Güneş balık burcundayken,

Bu şiirleri yazmak için,

Sevda ateşinde yanıp,har olmak için,

İzmit’in Yuvacık köyünde,

Balık burcunda,

Dünyaya gelmişim.', 'Bilirmisiniz?  Balık burcuyum ben. 23 şubatta,soğuk mu? Soğuk, Camı çerçevesi olmayan, Murat dayının ahırdan bozma, İzmit körfezine tepeden ...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/balik-burcuyum-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Naçar Kaldım.', 'nacar-kaldim-ali-osman-yilmaz-6bnwp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Okyanusun ortasında,

Fırtınaya tutulmuş,

Yelkenliyim şimdi.

Dayanılmaz etkisiyle tayfun,

Esiyor dört bir yandan,

Ne yelken kodu,ne direk,

Kırdı kopardı hepsini,

Naçar kaldım,yalnız,

Çıldırmış gibi bulutlar,

Habire çakmakta şimşek,

Tanrının mı bu gazap? 

Yoksa senin mi bilmem? 

Bir sancak tarafından vuruyor,

Bir iskele tarafından dalgalar,

Yıldırımlar yağdırıyor gökyüzü,

Üzerime,üzerime.

Bense ellerim semaya açılmış,

Gönlümse sana yönelmiş,

Bir tanrıya dua etmekteyim,

Birde senin sesini duymayı,

Nasıl beklemekteyim? 

Ne senden bir ses gelir,

Ne tanrıdan bir yardım,

Tek bir umut bile vermez,

Kaldım anlayacağın,

Senden sonra,

Çaresiz.', 'Okyanusun ortasında, Fırtınaya tutulmuş, Yelkenliyim şimdi. Dayanılmaz etkisiyle tayfun, Esiyor dört bir yandan, Ne yelken kodu,ne direk, Kı...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/nacar-kaldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünmeden Olmuyor.', 'seni-dusunmeden-olmuyor-ali-osman-yilmaz-d5xh0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni düşünmemeyi,

Bir başarabilsem? 

Ama olmuyor işte,

Bana her şey,

Seni hatırlatıp,

Seni düşündürüyor.

Seni düşündükçe çıldırıyorum,

Çıldırdıkça seni düşünüyorum,

Fasit bir daire içindeyim,

Girdabına yakalanmış,

Arzın derinliklerine doğru,

Çekiliyorum.', 'Seni düşünmemeyi, Bir başarabilsem?  Ama olmuyor işte, Bana her şey, Seni hatırlatıp, Seni düşündürüyor. Seni düşündükçe çıldırıyorum, Çıldı...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-dusunmeden-olmuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol...', 'yol-ferit-teksoy-dfpbo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dün bu yoldan geçtim,farklıydı

Denizler daha maviydi sanki

Daha dumanlıydı karşıdaki dağ

Orman daha yeşil,ırmak coşkulu

***

-Bak! ..diyordu bir el,bir parmağıyla

-Bu yeşile,doğaya bayılıyorum

Zamanda farklıydı onun yanında

Uçup gidiyordu içtiğimiz çayın buharı gibi

***

''İkinci bahar''ı söylerken tatlı sesiyle

Bizi anlatıyordu o şarkı sözleriyle

O liseli bir kız ben delikanlı

Dün böyleydi bu yol,böyle anlamlı

***

Başım omuzunda,elimde eli

Böyle bitirmiştik mesafeleri

Kahrolası tren bozulsun diye

Çok dualar ettik birlikte

***

Gürültüyle durdu o son durakta

Kopardı elimden sevdiğim eli

Bugün aynı yolda bir gün sonrası

Ne zaman geçiyor,nede yol..kahrolası

20 Aralık 2000', 'Dün bu yoldan geçtim,farklıydı Denizler daha maviydi sanki Daha dumanlıydı karşıdaki dağ Orman daha yeşil,ırmak coşkulu *** -Bak! ..diyordu ...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yol-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tercihleriyle Yaşar İnsan.', 'tercihleriyle-yasar-i-nsan-ali-osman-yilmaz-si04w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni ben tercih etmedim,

Beni sen tercih ettin önce,

Umut dolu,özlem dolu yazıların,

Senin kokularınla birlikte,

Geldikçe,yüreğimin atışı,

Bir başkalaşır oldu.

Ta moskova’lardan attığın oltana,

Takıp yanında götürdün yüreğimi,

Neden bilmem ardından,

Kanatarak sevdalı yüreğimi,

Hem de oltanı bile çıkarmadan,

Bıraktın gittin beni? 

İnsanlar tercihleriyle yaşarmış,

Madem oralardan tercih ettin beni,

Yaşayamadan bir gün bile seni,

Neden? neden? terkedip bıraktın?', 'Seni ben tercih etmedim, Beni sen tercih ettin önce, Umut dolu,özlem dolu yazıların, Senin kokularınla birlikte, Geldikçe,yüreğimin atışı, B...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tercihleriyle-yasar-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adımı Bıraktım', 'adimi-biraktim-zafer-zengin-etnika-yrbu6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bıraktım,

ne kadar gülümseme varsa,

hepsini,hepsini,

cocuklara bıraktım...

..

beyaz peynir,

ve biraz şiir aldım yanıma...

..

bıraktım,

ne kadar aşk öyküsü varsa,

hepsini,hepsini,

aşk''ı yaşamamış cocuklara...

..

çayı mı,

ve biraz sevda sarkısı aldım, yanıma...

..

bıraktım,

ne kadar hasret varsa,

hepsini, hepsini,

uzakta yaşayan cocuklara...

..

ekmeğimi

ve hüzünleri aldım yanıma...

..

ağır geliyor,

yazamıyorsun bir kaç şiir,

peşinden koşuyor tüm satırlar,

yazdıkça büyüyorsun,

büyüdükçe şair oluyorsun...

..

bıraktım kendime şiirleri

küçügüm dizelerim gibi...

..

şairim,

çay''a, beyaz peynire, hüzne bağlanmış,

Adımı Bıraktım...

29 aralık 2003', 'bıraktım, ne kadar gülümseme varsa, hepsini,hepsini, cocuklara bıraktım... .. beyaz peynir, ve biraz şiir aldım yanıma... .. bıraktım, ne ka...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/adimi-biraktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Kızıldı Bu Sonbaharda', 'deniz-kizildi-bu-sonbaharda-aslihan-tunca-jcwio', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Alı al yosun 

Moru mor gökyüzü 

Esir kırmızısı denizin ortasında 

Ve bir sonbahar akşamında yazdım bu şiiri 

Gözümün yaşı, 

Ömrümün yarısıyla... 

Yaşadıklarımın değeri yok 

Yaşayamadıklarıma yanarım ben 

Gecelerim söner, özlemlerim kalır 

Ferim gider, gözyaşım kalır 

Ömrüm biter, kızıl sevdalarım kalır bu kağıtta 

Karanfili koklarsın 

Rüzgarın ıslığını duyarsın 

Ağlarsın hani, 

Dünya dursa umurun da değildir 

Sebepli sebepsiz döktüğün tek damlanın yanında 

Ben, o tek damlanın peşindeyim 

Bu sonbahar akşamı 

Alı al yosun 

Moru mor gökyüzü 

Esir kırmızısı denizin ortasında 

Ve bir sonbahar akşamında yazdım bu şiiri 

Gözümün yaşı, 

Ömrümün yarısıyla...', 'Alı al yosun  Moru mor gökyüzü  Esir kırmızısı denizin ortasında  Ve bir sonbahar akşamında yazdım bu şiiri  Gözümün yaşı,  Ömrümün yarısıyl...', ARRAY['Türk Edebiyatı','Şiir','Aslıhan Tunca']::text[], 8.5, '{"poet":"Aslıhan Tunca","poet_slug":"aslihan-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/deniz-kizildi-bu-sonbaharda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazamazsam af ola! ...', 'yazamazsam-af-ola-i-brahim-ethem-bingul-hejze', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dostlar hastayım

Hem maddi yürek,

Hem mana yürek,

Taşımıyor bu beden artık,

Hem yüreğimi, hem yüreğimi,

Bedenim yoruldu, 

Yüreğim yoruldu,

Biliyorum da bir çare diyordum,

Bu yorgun yüreğimle birisini sevdim,

İyidi, hoştu işte kalp nakli dedim,

Beden kabul etmedi,

Uymadı...

Doktor''un dediği uymazmış

O da başkasına aitmiş,

İnanın dostlar

Son şansımdı

Şimdi hem maddi yürek,

Hemde mana yürek,

Hasta,

Yazamazsamda af ola...', 'Dostlar hastayım Hem maddi yürek, Hem mana yürek, Taşımıyor bu beden artık, Hem yüreğimi, hem yüreğimi, Bedenim yoruldu,  Yüreğim yoruldu, B...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yazamazsam-af-ola-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Himalaya’daki Deniz Kabukları', 'himalaya-daki-deniz-kabuklari-bekir-mutlu-gokcesu-nx97e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir kelebeğin ömrü

Çok uzun o kelebeğe

Kaç kanat çırptı

Kaç yürek çarptı

Dile kolay...

Dolu yaşadı baharı

O minicik bedende

O bir kelebekti

Başka yaşam bilemezdi

Ya bir insanın ömrü

Çok kısa bir insana

Oysa oluyordu

Hatta dışı gevremişti

Çiğ kalmıştı biraz içi

Tam da pişiyordu

Bir gün bir şey oldu

Yanıverdi

Kaç bahara ertelendi

Ya dağ, ya deniz

Nasıl oldu? 

Kaç bin yılın hikayesi

Gidip sorsak Himalaya’ya

Ne gördüm ki der

Şu dünyada

Oysa 

Üzerindeki deniz kabukları

Hala suya hasret yanmakta...

Hem de kaç bin yıldır

Adı üstünde deniz kabuğu

Ne yapsın Himalaya’yı...

Az yaşa, çok yaşa

İllaki öz yaşa

Galiba', 'Bir kelebeğin ömrü Çok uzun o kelebeğe Kaç kanat çırptı Kaç yürek çarptı Dile kolay... Dolu yaşadı baharı O minicik bedende O bir kelebekti ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/himalaya-daki-deniz-kabuklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık Kalem', 'kirik-kalem-huseyin-cayikli-3dxsl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'coğrafyalarımı satıyorum bir aşka.kendimi bilmeden sana veriyorum.içine camdan kolyeler yaptım kırıyorum biriktirdiğim acılarımı.senden öncede aynımıydı bu dunya yoksa biz değiştirdik mi acılarımızla yapma yalandan olusan dunyayı.elimizde ne kaldı aşktan başka.deniz fenerleri hala aynımıydı.yeni tanısmıstık seninle içimizde alınçtan kocaman kolyeler saklıydı cocuksu gulmelerimiz iki yabancının birbirini tanımasıydı.sen kocaman ısıklı bir kente gidiyorsun.gocmen kuslarım yine basımda ususuyor.ask kısıyı yatakta yalnız bırakabiliyor.kutsal gucleri olan eski yunan tanrıları aldanmıslar sana.askın tanrısı aslında yalnızlıgıdır insanın.bir kadına yani sana tutunmak ibadet sayılmıs askın kutsallıgında.kalemi kırdım kutsa beni aşkla istediğin tanrıyı kandır.cografyalarımız ayrı seninle aynı kente oysa kayboluyoruz...ne tuhaf değil mi yasamak sevmek sevişmek.vefasız mı kaldık sevdaya...kalemlerimizi kaç kere kırdık ask ugruna kaç kere sevdik eskide kalan hatalarımızı onlarla kaç sefer seviştik bir odada.yalnızlıgı ne zaman koynumuza soktuk.şimdi kim kırdı kalemi yalnızlıgın yalnızlıgım yalnızlıkları...aska dair kim yazdı.ne tanrıymıs bunlar kac sefer aldattılar bizi.sen ne zaman tanrı rolune girdin beni aşka aforoz ettin.şimdi soyle bana asş kaç kere guler insana.kaç kere beni sen yapar.kaç kere ben tanrı olurum eski tanrılar korkar.soyle bana sen mi kırdın bu kalemi yoksa bu dunyadan senmi sorumlusun? şimdi sana seni yazıyorum putlasmıs tanrıları bahane ederek seni unutmaya calısıyorum deniz fenerlerinin altında.aşka dair ne yazdım biliyormusun deniz fenerlerini...yazarken kalemim kırıldı sen cıkıp geldin içim eridi dunyadaki butun deniz fenerleri o an tekrar yandı...', 'coğrafyalarımı satıyorum bir aşka.kendimi bilmeden sana veriyorum.içine camdan kolyeler yaptım kırıyorum biriktirdiğim acılarımı.senden önce...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/kirik-kalem-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Acısı', 'ask-acisi-tugay-kocak-bxva4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Üzgünüm dostlarım,hatta perişan.

Bu tarifi sevdim tam uydu bana.

Böyle zamanlarda beni anlayan,

Dost varsa Dünya’da bir o’ydu bana

Söküp atamadım içimden yası.

Ne zaman bitecek yürek yarası? 

Benim hüzünlerin kara sevdası.

Ne aşkı azaldı,ne doydu bana.

Kıvrılıp yatarım şöyle kenarda.

Bu gece sarhoşum,aklım firarda.

Kalbim acı çeker,belki yanarda,

Çünkü bu ayrılık çok koydu bana.', 'Üzgünüm dostlarım,hatta perişan. Bu tarifi sevdim tam uydu bana. Böyle zamanlarda beni anlayan, Dost varsa Dünya’da bir o’ydu bana Söküp ata...', ARRAY['Türk Edebiyatı','Şiir','Tugay Koçak']::text[], 8.5, '{"poet":"Tugay Koçak","poet_slug":"tugay-kocak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-acisi-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçmedi Yare Sözümüz', 'gecmedi-yare-sozumuz-semih-zaman-fb0an', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gül doğmuş oysa bülbül ölmüş neye yarar

hem artık eskisi gibi kokmuyormuş 

her yanını diken sarmış

gül,ellerin gülü,yaban gülü

dikenli çehrelere bürünen gül

gülüm,

doğum günün kutlu olsun

gül doğmuş oysa bülbül ölmüş neye yarar

onu sevmeye,sevdikçe koklamaya

ve ölmeye kokladıkça

muktedir tek varlık bülbül ölmüş

gül doğsa neye yarar...

doğum günün kutlu olsun gülüm

sana yaptığım boncuktan hiç kuş konamayacaksa da 

pencerene,

kutlu olsun ellerin gülü...

gülüm demek isterdim ama varmıyor dilim

yetmiyor gücüm,

gurur sussa,bülbül tövbe etse

kalem yazmıyor

herşeye yazılıyor da

ayrılığa hasrete bile

bir şu ihanete yazılmıyor...

doğum günün kutlu olsun yaban gülü,

rahat uyu,

mekanın yüreğim olsun 

senden başkasına dar yüreğim...', 'gül doğmuş oysa bülbül ölmüş neye yarar hem artık eskisi gibi kokmuyormuş  her yanını diken sarmış gül,ellerin gülü,yaban gülü dikenli çehre...', ARRAY['Türk Edebiyatı','Şiir','Semih Zaman']::text[], 8.5, '{"poet":"Semih Zaman","poet_slug":"semih-zaman","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gecmedi-yare-sozumuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elindeyse...', 'elindeyse-semih-zaman-awn51', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'eğer elindeyse ne olur bu gece gelme rüyama

sensizlikle uğraşmaktan yoruldum

düş de olsa seninle ilgilenememekten korkuyorum da

elindeyse eğer gelme,ne olur

o elle tutulur heyacanı yaşayamamak da olsa bedeli gelme

ne olur gelme...', 'eğer elindeyse ne olur bu gece gelme rüyama sensizlikle uğraşmaktan yoruldum düş de olsa seninle ilgilenememekten korkuyorum da elindeyse eğ...', ARRAY['Türk Edebiyatı','Şiir','Semih Zaman']::text[], 8.5, '{"poet":"Semih Zaman","poet_slug":"semih-zaman","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/elindeyse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitik Gül', 'yitik-gul-semih-zaman-r73qc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bahçenin rızası olmadan gül derilmez 

her ne kadar o varlık boyutunda ne varsa

güzelliğe dair,

sindirmişse de sinesine; 

her ne kadar o

sırlı yaradılışın gayesi ise de

baçenin rızası olamdan gül derilmez

direnişim gülü olmaz...', 'bahçenin rızası olmadan gül derilmez  her ne kadar o varlık boyutunda ne varsa güzelliğe dair, sindirmişse de sinesine;  her ne kadar o sırl...', ARRAY['Türk Edebiyatı','Şiir','Semih Zaman']::text[], 8.5, '{"poet":"Semih Zaman","poet_slug":"semih-zaman","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yitik-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya da...', 'ya-da-semih-zaman-y365w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ya verme adresini

ki bulamyım seni

ya da aç şu kapıyı gireyim içeri

sıkılmadım da yoruldum beklemekten

anla ev sahibiolmak istiyorum

misafirlik bana göre değil anla 

anlatamasam da...', 'ya verme adresini ki bulamyım seni ya da aç şu kapıyı gireyim içeri sıkılmadım da yoruldum beklemekten anla ev sahibiolmak istiyorum misafir...', ARRAY['Türk Edebiyatı','Şiir','Semih Zaman']::text[], 8.5, '{"poet":"Semih Zaman","poet_slug":"semih-zaman","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ya-da-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman da aciz Kalınca', 'zaman-da-aciz-kalinca-semih-zaman-w8mih', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'zaman 

herşeyin çaresi

hasretleri btirir

acıları dindirir

peki neden benim vuslatıma çare bulamıyor

bu yüzeysel coğrafyada..

yoksa bu ölümcül hastalık

doktor zamanın ihtisas alanına girmiyor mu...?', 'zaman  herşeyin çaresi hasretleri btirir acıları dindirir peki neden benim vuslatıma çare bulamıyor bu yüzeysel coğrafyada.. yoksa bu ölümcü...', ARRAY['Türk Edebiyatı','Şiir','Semih Zaman']::text[], 8.5, '{"poet":"Semih Zaman","poet_slug":"semih-zaman","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/zaman-da-aciz-kalinca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmadı...', 'olmadi-semih-zaman-9zjo0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sövemedim uyandırmaya...', 'Sövemedim uyandırmaya......', ARRAY['Türk Edebiyatı','Şiir','Semih Zaman']::text[], 8.5, '{"poet":"Semih Zaman","poet_slug":"semih-zaman","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/olmadi-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu mu...?', 'bu-mu-semih-zaman-u93j9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'göz kapaklarının  kapanması ise uyumak

dediğiniz,

yanak kaslarının kasılmasıysa gülmek

ve soluk alıp vermekse yaşmak,

uyuyorum,gülüyorum, yaşıyorum

ağlıyorum,ölüyorum,uyanamıyorum...', 'göz kapaklarının  kapanması ise uyumak dediğiniz, yanak kaslarının kasılmasıysa gülmek ve soluk alıp vermekse yaşmak, uyuyorum,gülüyorum, ya...', ARRAY['Türk Edebiyatı','Şiir','Semih Zaman']::text[], 8.5, '{"poet":"Semih Zaman","poet_slug":"semih-zaman","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bu-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mağduiyetim...', 'magduiyetim-semih-zaman-swr1r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'meğer her inişin bir çıkışı değil

her uykunun bir uyanışı varmış

yani çarptıktan sonra plakası alınamyan

bir araçmış aşk denilen

ve hiç bir zaman amaç olamazmış

mağlubiyetin mağdurları için...', 'meğer her inişin bir çıkışı değil her uykunun bir uyanışı varmış yani çarptıktan sonra plakası alınamyan bir araçmış aşk denilen ve hiç bir ...', ARRAY['Türk Edebiyatı','Şiir','Semih Zaman']::text[], 8.5, '{"poet":"Semih Zaman","poet_slug":"semih-zaman","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/magduiyetim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günaydın', 'gunaydin-gulden-karabudak-ahvz1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bilmem; 

belki bir Günaydın''la aydınlanır günün

Belki bir kelimeyle çoğalır gülüşün

bir parça mutluluk takılır belki gözlerine

Belki bir başka açarsın defterini bugün

Başka türlü bakarsın yaşamın tadına

Bir başka gülücük yansır dudaklarına

Umuda hoşgeldin derken

Umutsuzluğa yasak koyarsın belki

Belki; 

belki bir barış şarkısı takılır aklına

Belki bir bebeğin ellerine tutunup

Pembe bir bulutla oynarsın bugün

Belki de; 

Hiç bilmediğin o duyguyu yaşarken

Yaşamın reset düğmesine basıp

yeniden basladığın,

O gün olur bugün...

                          

                        09.01.2004

                            02.20', 'Bilmem;  belki bir Günaydın''la aydınlanır günün Belki bir kelimeyle çoğalır gülüşün bir parça mutluluk takılır belki gözlerine Belki bir baş...', ARRAY['Türk Edebiyatı','Şiir','Gülden Karabudak']::text[], 8.5, '{"poet":"Gülden Karabudak","poet_slug":"gulden-karabudak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gunaydin-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-seref-kaya-vtei5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ahhh nasil özledim seni ankara rüzgari

Yildizlarin altinda dolasmak ne güzel

Yaz yagmurlarinda yasemen kokulu bulvarlarda

Isinlarim kayboldu gözlerini görmem gerek

Dik kayalar gibi esir düstüm rüzgarina

Es estikce vuruyor yüregime

Gökyüzünün yedi rengi yok gözlerinde

Ahh ela gözlüm yillar oldu filizlendi gönlümde

09 01 04 Ffm.seref kaya', 'Ahhh nasil özledim seni ankara rüzgari Yildizlarin altinda dolasmak ne güzel Yaz yagmurlarinda yasemen kokulu bulvarlarda Isinlarim kayboldu...', ARRAY['Türk Edebiyatı','Şiir','Şeref Kaya']::text[], 8.5, '{"poet":"Şeref Kaya","poet_slug":"seref-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ozlem-135-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum Günü*', 'dogum-gunu-bayram-tunca-4x6vb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine gelip geçti şu ömürden bir yıl daha 

Ömrümün çoğu gelip geçti kaldı azı aha

Çok ağlayıp az güldüm, ne söylem daha 

Gidersem, gelmem herkes gibi bir daha 

01.01.2004-01.01', 'Yine gelip geçti şu ömürden bir yıl daha  Ömrümün çoğu gelip geçti kaldı azı aha Çok ağlayıp az güldüm, ne söylem daha  Gidersem, gelmem her...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dogum-gunu-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baris Getirmistim Oysa', 'baris-getirmistim-oysa-baris-guc-asuui', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kalpsizler ordusunun iyi kalpli yenik esiriydim ben

Sevgi adinda yasadisi bir örgüt kurmak suçundan yargilanan 

Ölüm korkusu degildi,sensizlik kabusuydu beni korkutan

Sarapnel parçalari degildi bu kalbimi bir nehir gibi kanatan

Beni anlayamamandi,iskence yaparcasina içimi acitan

Bir atom bombasi düsmüstü yüregime cigerlerimi parçalarcasina

Bir tank ezip geçseydi bu kadar agir yaralamazdi beni

Bu uzaklardan gelen ses mermi sesimi yoksa seninin sesinmiydi

Bu enkaz yiginlari altindan gelen sevgi çigliklarini duymuyormusun? 

Senin ugruna ölen bu aptal asigi  görmüyormusun

Mayindan arindirilmis kalbimi vermistim oysa ben sana

Baris getirmistim gözüm; bu acimasiz savasa

09.01.2003 sda ozlt   MSN:   [email protected]', 'Kalpsizler ordusunun iyi kalpli yenik esiriydim ben Sevgi adinda yasadisi bir örgüt kurmak suçundan yargilanan  Ölüm korkusu degildi,sensizl...', ARRAY['Türk Edebiyatı','Şiir','Barış Güç']::text[], 8.5, '{"poet":"Barış Güç","poet_slug":"baris-guc","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/baris-getirmistim-oysa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi Gel', 'hadi-gel-orhun-basat-wt97k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tek tek öp, 

Hüzünlerini ve dünlerini, vedalaş; 

Koy yüreğindeki yerine ve unut. 

Damıt gecelerini, temizlen. 

Yüreğini sessiz akıntılara bırak, 

Yönetme rüzgarlarını, 

Bırak küreklerini, dinlen. 

Kapa bütün ışıkları ve kıyılarıma gel, 

Her dalgada binlerce çoğalarak. 

Hadi gel. 

Yalnızca, 

Gözlerini ve kemanını getir. 

Gerisi kendi gelir.', 'Tek tek öp,  Hüzünlerini ve dünlerini, vedalaş;  Koy yüreğindeki yerine ve unut.  Damıt gecelerini, temizlen.  Yüreğini sessiz akıntılara bı...', ARRAY['Türk Edebiyatı','Şiir','Orhun Basat']::text[], 8.5, '{"poet":"Orhun Basat","poet_slug":"orhun-basat","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hadi-gel-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye Mektuplar 1', 'sevgiliye-mektuplar-1-oguzkan-bolukbasi-mt5i3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevgili sevgilim

Bu mektubu sana ta uzaklardan

Yani

Saçlarını okşarken yazıyorum

Çünkü sana yapışık olsam bile hasret yaşıyorum

Doymak bilmeyen bir ateş var içimde

Ne kadar sarsam ısınamıyorum

Saçlarının kızılında sabahlar doğuruyor

Akşamlar batırıyorum

Melek yüzünü öperek uykuya yatırıyorum

Sevgili sevgilim

Sen titrediğinde üşüdüğümü biliyor musun

Sen ağladığında gözlerimin yandığını

Bir adım uzağında sensiz kaldığımı

Tabiat kanunları çalışmıyor seninleyken

Mesela yüreğim yerçekimine uymuyor

Bedenim sıcakta genleşmiyor

Su yüz derecede kaynamıyor

Sen ne dersen o oluyor

Sevgili sevgilim

Var olduğunu düşündüğümde

Gözlerim karanlıkta yol buluyor

Daima seninim', 'Sevgili sevgilim Bu mektubu sana ta uzaklardan Yani Saçlarını okşarken yazıyorum Çünkü sana yapışık olsam bile hasret yaşıyorum Doymak bilme...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sevgiliye-mektuplar-1-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Name', 'gul-name-abdulkadir-karaman-kb10x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her tarafım yanar andıkça gülüm

Usanmam, anarım yandıkça gülüm! 

Susuzluğum sensin, açlığım da sen! 

Merhamet, yanarım kandıkça gülüm! 

Her ân gözlerimde döner hayâlin

Susarım, hep kandım sandıkça gülüm! 

Banarsam sevdâna kanarım sandım

Çöllere dönerim, bandıkça gülüm! 

Kalbim gözlerinde rehine kaldı

Bırakma, canını sundukça gülüm! 

Aşkın alev; canım, ruhumu yakıtı

Hasretinle üfle söndükçe gülüm! 

Temizlenir kirden, silinir gamı

Alevinde aşkın yundukça gülüm! 

Pervânene imdat etme, isterse

Belki olgunlaşır döndükçe gülüm! 

27.03.03', 'Her tarafım yanar andıkça gülüm Usanmam, anarım yandıkça gülüm!  Susuzluğum sensin, açlığım da sen!  Merhamet, yanarım kandıkça gülüm!  Her ...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gul-name-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiğdem', 'cigdem-volkan-ates-aq7p8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zamansız gelir ölüm

Bir gece ansızın çekip gidersin

Sabahı, güneşi, insanları bir daha göremezsin

Göremezsin sefaleletini insanların

Seni kurban eden insanlara 

Söyleyecek sözün yok mu ÇİĞDEM! ! 

Konuşsana küçük kız

Affeder misin onları seni paraya kurban ettikleri için? 

Konuşsana konuşsana...

Sen zamansız soldurulmuş ÇİĞDEM

Ben kaç kez vuruldum bu sokaklarda

Senin katillerin benim katilim oldu her gün

Arkanda bıraktıklarının gözleri yaşlı

Anan baban küçük kardeşlerin

Kan damlar hepsinin gözlerinden

Sensizlik mi daha zor yoksa yoksulluk mu? 

Konuşsana! 

Konuşamazsın ki sen

Çünkü sen 4 yaşında ölü bir kız çouğu! 

Konuşamaz ki ölüler

Ben konuşurum senin yerine

Merak etme sen alınacaktır öcün

Ellerimde dünyanın en güçlü silahını taşıyorum:

İnsanlık damlayan kanlı keskin bir kalem! ! ! 

Not:Halkın sağlığı vicdansızlara emanet... Bursa’da yaşayan 3 çocuklu Bayram ailesi, 80 milyon lira tutan ilaç parasını bulamayınca, zatürre olan kızları, 

4 yaşındaki ÇİĞDEM’i kaybetti...', 'Zamansız gelir ölüm Bir gece ansızın çekip gidersin Sabahı, güneşi, insanları bir daha göremezsin Göremezsin sefaleletini insanların Seni ku...', ARRAY['Türk Edebiyatı','Şiir','Volkan Ateş']::text[], 8.5, '{"poet":"Volkan Ateş","poet_slug":"volkan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/cigdem-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-volkan-ates-aq7af', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çığlıklarla yıkılmış bir şehrin sokaklarında

Gezinen yaralı bir derviş gönlüm

Karanlık düşlere armağan edilmiş

Yalan bir dünyanın bekçileriyiz...

Seyyah gönüllere kucak açmayı

Yüzyıllar öncesinde bırakmışız

Hangisi daha ağır gelir insana

Kimsesiz bir sokak köpeği olmak mı

Yoksa zamansız çıkıp gelen bir tanrı misafiri olmak mı? 

Diyelem ki bir sokak köpeğisin

İki ihtimal var önünde

Birincisi; karanlık yıldızlı bir gecede

Hiç kimse hissetmeden, hiç kimse duymadan

Acımasızca öldürülmek! 

İkincisi; sahte, hiçbir insanın olmadığı bir dünyada

Bir şeyler anlatmaya çalışarak geçer ömrün

Ama anlatabileceğin insanlar yok ki! 

Her iki durumda da ölüsün...

Esas soru şu: Hangisi daha onurlu bir ölüm

Diyelim ki bir tanrı misafiri

Diyar diyar dolaşan bir abdalsın

İnsanlara, insanlardan daha çok aşık 

Bu zamanın içinde yitip gitmiş bir zerresin

Tıpkı bataklıkta açan çiçekler gibi

Tıpkı...

Kim anlar seni, kim sever seni? 

HİÇ KİMSE! 

Neden biliyor musun

Bataklıklar, üzerinde yetişen güzelliklerden habersizdir

Görmek için çaba da sarfetmez

Belki kurbağalar görür ama

Onlar da kendi gürültülerinden, duyamazlar sözlerini

Ey dost senin için tek ve yegane bir yol var

Sevda kokulu insanlar diyarına doğru yol almak 

İhtimaller senin gibi dervişler için değil

Ancak köpekler ve köpekçe yaşayanlar için

Yolun insanlara rastgelsin! 

NOT: İnsanlarımız toprak gibi kokar, bağrında adını bile bilmediğimiz binlerce çiçek yetiştirirdi bir zamanlar! Yağmurlar bize can verirdi, ne çabuk bataklığa dönüştük? Sevda  çocukları hep ANADOLU adlı vatanımda yetişti! Anadolu’nun damarlarındaki kandan hiçbir zaman şüpheye kapılmadım. Ben anadoluyum, sizler anadolusunuz. Bütün insanlar bu anadolu adlı adada hep bir arada kardeşçe yaşamıştır ve sonsuza kadar da bu böyle olacaktır...', 'Çığlıklarla yıkılmış bir şehrin sokaklarında Gezinen yaralı bir derviş gönlüm Karanlık düşlere armağan edilmiş Yalan bir dünyanın bekçileriy...', ARRAY['Türk Edebiyatı','Şiir','Volkan Ateş']::text[], 8.5, '{"poet":"Volkan Ateş","poet_slug":"volkan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/zaman-105-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Gözlüm', 'gece-gozlum-volkan-ates-1ryxb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gece çektin gittin bu diyardan

Geride bir yıldızlar kaldı

Bir de içimdeki derin mavilik

Sensizlik, koyu karanlık bir gece

İçimde sabahlara hasret bir çocuk! 

Yılgınlığım yalanlarına

Küskünlüğüm zannetme ki gözlerine

Geceden karanlık, aydınlıktan daha aydınlık gözlerine

Diyecek hiçbir lafım yok! 

Kızgınlığım kendime

Görmek için gözlerini hep geceye

Hep sessizliğe bürünmüşlüğüme

Aldanışlarım hiçbir zaman bu kadar büyük

Bu kadar can yakıcı değildi çocuk

Koskocaman bir okyanusta ıssız bir adadayım çocuk

Bir, gece kadar karanlık gözlerine

Bir de içimdeki sessiz maviliğe aşığım ben çocuk

İnan bana çoktan unuttum ismini

İçimde gece karanlığında yakılmış

Mavi bir isyan kaldı sadece

Gerisi senin gibi, benim gibi koca bir yalan! 

Dünya kadar büyük, kainat kadar sonsuz bir yalan...', 'Bir gece çektin gittin bu diyardan Geride bir yıldızlar kaldı Bir de içimdeki derin mavilik Sensizlik, koyu karanlık bir gece İçimde sabahla...', ARRAY['Türk Edebiyatı','Şiir','Volkan Ateş']::text[], 8.5, '{"poet":"Volkan Ateş","poet_slug":"volkan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gece-gozlum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne', 'anne-rahmi-aksoy-pp9i2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anne

Bu yüreği bana sen verdin

Büyütmekti tek derdin

Uykumun ahengi için 

Kaç sineğin kanına girdin

Sensiz tutmuyor ellerim

Düz zeminde kayıyorum

Ömrüm boyunca yediğim tekmeyi

Dokuz ay boyunca attıklarıma sayıyorum

Bir kahvenin kırk yıl hatırı var

Sırf bu yüzden 

Seksen yıl borcum var

Bir çift kahve göz için

Seni görmediğim her demimi

Ay sayıyorum

Basmadığın her zemini

Fay sayıyorum

Adını anmadığım an

Dilim damağıma büyük geliyor

Sesini duymadığım zaman 

Kulaklarım bana yük geliyor

Ödenmez hakkın biliyorum

Fakat borcum borç inkar etmiyorum

Bir kutsal sermaye verdin 

Hiç kar etmiyorum', 'Anne Bu yüreği bana sen verdin Büyütmekti tek derdin Uykumun ahengi için  Kaç sineğin kanına girdin Sensiz tutmuyor ellerim Düz zeminde kayı...', ARRAY['Türk Edebiyatı','Şiir','Rahmi Aksoy']::text[], 8.5, '{"poet":"Rahmi Aksoy","poet_slug":"rahmi-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/anne-72-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefasız', 'vefasiz-hicabi-ceylan-hggmz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Özlemlerim uzadıkça, uzadı

Ta gökkuşağına

Seni ölesiye

Ama ölesiye sevdim

Yemin ederim Kitabıma Allah’ıma

Sen! Silahı dayadın da şakağıma

Bastında tetiğe

Öl dedin de ölmedim mi ben

Mor dağların esintisi 

Vuruyor suratıma

Her nefeste seni

Seni çekiyorum içime

Bir veda bile etmeden gidişin var ya

İşte o! Gidiyor gücüme

Sen! Sevmek nedir hiç bilmedin ki

Toprak oldum serildim ayaklarına

Basarak geçtin, görmedin ki

Beni çok özledin de

Çağırdın, gel dedin de! gelmedim mi? 

Artık istemiyorum çık git

Çıtta! Git bu canımdan

Hiç umudum kalmamışken yarından

Söyle bıçak kadar keskin sözlerini

Söyle ki! Göreceksin her bir damlada

Sen! Sen akacaksın kanımdan', 'Özlemlerim uzadıkça, uzadı Ta gökkuşağına Seni ölesiye Ama ölesiye sevdim Yemin ederim Kitabıma Allah’ıma Sen! Silahı dayadın da şakağıma Ba...', ARRAY['Türk Edebiyatı','Şiir','Hicabi Ceylan']::text[], 8.5, '{"poet":"Hicabi Ceylan","poet_slug":"hicabi-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/vefasiz-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidenin Ardından', 'gidenin-ardindan-naime-erlacin-dpo35', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '- ayrılık sevgiyi yalnızca çoğaltır, sevgi gerçekse eğer….

ayrılık ateşi düştü ya

çıkmalı artık yüreğimden

yağmurla bereket olmalı dizelerime

hüzünlü bir şarkıdır oysa gönlüm

kanıyor divaneliğinden

derdimi sözlediğim gök yabancı bugün 

sevene tutkundu

yangını bilirdi o

anlatamıyorum

suç bende olmalı! 

özlüyorum seni fırtına seslim

boşaldı kalp odaları

duvarlar sağır

zift akşamlar bekçiliği düştü yine 

kokunu alıyor da öyle tütüyor yürek 

yolun hep açık olsun  gülenyüz bebek 

(09 Ocak 2003)', '- ayrılık sevgiyi yalnızca çoğaltır, sevgi gerçekse eğer…. ayrılık ateşi düştü ya çıkmalı artık yüreğimden yağmurla bereket olmalı dizelerim...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gidenin-ardindan-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mor Dağlarının Ötesinde', 'mor-daglarinin-otesinde-turgay-uceren-a1tmc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sen, bekleyen su, şafağa yakın hala

kıpırtılarınla rüzgar bekleyen şiddetle 

bir iç denizin ışığını hapis etmiş 

mağarasında gövdenin

- denizini dalgalandıramıyor ay, 

çekimsiz yasa –

yolunu arayan bir yer altı damarı

güneşe, ağır ağır akmak için yatağında

her an patlamaya hazır, gece 

avuç içine sığdırdığın güneş

- kendini zorlayan zirve –

mor dağlarının ötesinde..', 'sen, bekleyen su, şafağa yakın hala kıpırtılarınla rüzgar bekleyen şiddetle  bir iç denizin ışığını hapis etmiş  mağarasında gövdenin - deni...', ARRAY['Türk Edebiyatı','Şiir','Turgay Uçeren']::text[], 8.5, '{"poet":"Turgay Uçeren","poet_slug":"turgay-uceren","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mor-daglarinin-otesinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küfe', 'kufe-gulsen-senderin-2v52s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Omuzlarımda ağır bir küfe 

İçinde aşkını taşıyorum 

Bu yükle bilinmezliklerin 

Kor acısını yaşıyorum... 

Belimi büken bu sancıdan 

Bir an kurtulsam mı diyorum 

Sol yanımdaki ağrıların 

Nar ateşiyle yanıyorum... 

Sırtımdaki ağır küfeden 

İnan ki kurtulacağım 

Kim bilir belki de bu yükü 

Sana...Sana toptan satacağım... 

05 – 04 – 2002. Beylerbeyi Vapuru', 'Omuzlarımda ağır bir küfe  İçinde aşkını taşıyorum  Bu yükle bilinmezliklerin  Kor acısını yaşıyorum...  Belimi büken bu sancıdan  Bir an ku...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kufe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tütün Sarmış Ayrılık', 'tutun-sarmis-ayrilik-hakki-hakan-kaya-3yvsi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kavuruyorken içimdeki, vasfı bilinmez arzular,

İnanıyor yüreğim, her kanat çırpışa,

Değişiyor birden, rüzgarın yönü kuvveti,

Alıyor yerini, bir gizemli karmaşa.

Düşünüyorken sevmeyi, hep bir yerden yarımlık,

Arıyorken rüzgarında, sevgi tohumunda sarımlık,

Paylaşılmış mutluluk, hasrete çalar dumanı,

Bekliyorken kavuşmayı, tütün sarmış ayrılık.', 'Kavuruyorken içimdeki, vasfı bilinmez arzular, İnanıyor yüreğim, her kanat çırpışa, Değişiyor birden, rüzgarın yönü kuvveti, Alıyor yerini, ...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tutun-sarmis-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana gülüm demekle', 'sana-gulum-demekle-omer-albayrak-vcfmm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mademki adın güldür,

Her gül, bir bülbülündür.

Gönlümün bahçesinde,

Aç ta beni sevindir.

Madem benzersin güle,

Lâyıksın bir bülbüle,

Beni hicrana salıp,

Oynama kalbim ile.

Baharsın çiçek çiçek,

Açarsın öbek öbek,

Gönlümün heykelini,

Süsleyen nazlı çelenk.

Bilmem ki, neden hazan

Gibi solarsın bazan? 

Gülüm hasretin ile,

Bülbülün oldum çoktan.

Sana gülüm demekle,

Gücenme koklamadım.

Adını söylemekle,

Kalbime saklamadım.', 'Mademki adın güldür, Her gül, bir bülbülündür. Gönlümün bahçesinde, Aç ta beni sevindir. Madem benzersin güle, Lâyıksın bir bülbüle, Beni hi...', ARRAY['Türk Edebiyatı','Şiir','Ömer Albayrak']::text[], 8.5, '{"poet":"Ömer Albayrak","poet_slug":"omer-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sana-gulum-demekle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülistan', 'gulistan-omer-albayrak-h7acz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Körebe dolaşmışım dünyayı karanlıkta,

Bir bayram arifesi ayıldım mezarlıkta.

Nûrdan çiçekler açmış taşların arasında,

Görmedim emsalini hiçbir gülistanlıkta...

Sanki yere indirmiş Arş’ın meleklerini,

Gark etmiş mağfirete bütün sevdiklerini.

Bir Fatiha okuyup, bin şefaat dilendi; 

Bu arzu bir kor gibi yaktı iliklerimi...

Huzura gark olmuştu kâinat sanki burda,

Bu ihtişam yanında, dünya ne kadar hurda? 

Karanlıklar gönlümde dalga dalgaz nûr oldu; 

Gönül bayram eyledi durduğum ihtiramda...

Silindi ruhum pastan, tevhidin nuru ile,

Dirildim yeni baştan Islâmın şuuru ile.

Resulü’nün nûruyla haşır-neşir haşra dek; 

Ayrıldım sevgililer uyurken yari ile...

** Henüz ömrünün baharında iken

    Bir gül fidanı gibi toprağına verdiğim

    Oğlum Uğur’un mekânı “Gülistan”

    Taşlıklarla mezarlığı **', 'Körebe dolaşmışım dünyayı karanlıkta, Bir bayram arifesi ayıldım mezarlıkta. Nûrdan çiçekler açmış taşların arasında, Görmedim emsalini hiçb...', ARRAY['Türk Edebiyatı','Şiir','Ömer Albayrak']::text[], 8.5, '{"poet":"Ömer Albayrak","poet_slug":"omer-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gulistan-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şulenin Işıltısına', 'bir-sulenin-isiltisina-yildiz-yildiz-zujho', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Toprağa kök salmış ya bedenim,

Suyum dost şiirlerden gelir 

Karbondioksitim dost sitemi.

Gözgörmez karanlık olsa her yanım

Fotosentezime bir Şulenin ışıltısı yeter.

Üretir yüreğim sevgileri.

Bir kıvılcım tutuşturur ölü aşkları.

Öleni var mı ki aşkın? 

Akıl ''bitti'' dediğinde,

Kabulkar oluverse yürek

Kanatmasa çiçekleri

Can çekişmelerin ince sızısı

Ölüyü öldürene sürükletirlermiş,

Bırak kim öldürdüyse o sürüsün aşkın ölüsünü

Sen yaşar ve büyütürken aşkı

Öleni öpsün ölüm

Sen şeker pembesi 

Elma çiçekleri açasın

Eflatun aşklı bir bahar öpsün yüreğini

Yok ille de yaz olsun dersen

Kızıl olsun dersen çiçeklerim

Tamamlansın  haziranın

Yaşayan aşkların narına yansın yüreğin

Kelebek gönlüne gülsün nar çiçeklerin

Doğum günümde beni inanılmaz mutlu eden Şule''ciğime sevgilerle', 'Toprağa kök salmış ya bedenim, Suyum dost şiirlerden gelir  Karbondioksitim dost sitemi. Gözgörmez karanlık olsa her yanım Fotosentezime bir...', ARRAY['Türk Edebiyatı','Şiir','Yıldız Yıldız']::text[], 8.5, '{"poet":"Yıldız Yıldız","poet_slug":"yildiz-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-sulenin-isiltisina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Yoksun', 'artik-yoksun-hurrem-kececi-zt11p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Artık yoksun,

Zaman akıp geçti ellerimizin arasından.

Yalvarmak, yakarmak fayda etmez.....

Hiç görmediğimiz, bilmediğimiz ''zaman''

Ayırdı bizi belki de...! 

Geriye; 

Kazağımdaki kokun,

Kulağımdaki sesin ve 

Gözlerimdeki hayelin kaldı...

Aaa...! Unuttum birde o 

Ayrılık Mektubun....', 'Artık yoksun, Zaman akıp geçti ellerimizin arasından. Yalvarmak, yakarmak fayda etmez..... Hiç görmediğimiz, bilmediğimiz ''zaman'' Ayırdı biz...', ARRAY['Türk Edebiyatı','Şiir','Hürrem Keçeci']::text[], 8.5, '{"poet":"Hürrem Keçeci","poet_slug":"hurrem-kececi","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/artik-yoksun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
