INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vurdum Duymaz', 'vurdum-duymaz-gokhan-karaduman-qstqg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Vurdumduymaz 

Kafasina takmaz 

Sevdadan asktan 

Hiç anlamaz 

Fesattir adi 

Kiskanç soyadi 

Feminist mi nedir 

Bana aci çektirir 

Sevmiyorum der 

Kapimda gezer 

Aslinda sever 

O da beni ister 

Nedendir bilinmez 

Saklar sir gibi 

Hep ayni yerde 

Bitirir filmi 

Vurdumduymaz 

Kafasina takmaz 

Sevdadan asktan 

O hiç anlamaz 

“Biliyorum sen istemiyorsun, ama ben yan cebine', 'Vurdumduymaz  Kafasina takmaz  Sevdadan asktan  Hiç anlamaz  Fesattir adi  Kiskanç soyadi  Feminist mi nedir  Bana aci çektirir  Sevmiyorum ...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Karaduman']::text[], 8.5, '{"poet":"Gökhan Karaduman","poet_slug":"gokhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/vurdum-duymaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum', 'gidiyorum-gokhan-karaduman-zefbw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu gün, 

Gelişinin gün dönümü. 

Geldiğin yerde, 

Elini ilk tuttuğum istasyondayım. 

Günlerden Salı, 

Üzerimde, Sensizliğin Yıkıntısı. 

Anıların arasında kaldım, 

Sensizliğin Namlusu şakağımda. 

Ben Yıkılmışlığın arifesinde, 

Seni Arıyorum. 

Sen ise o bitmek bilmez, 

Eğlencelerindesin. 

Ben seni, 

Bedenimden sakınırken, 

Sen Aşkımızı, 

Sigara Dumanlarında Tüketiyorsun. 

Üstelik, 

Üstelik O, Bana, 

Sevdim, 

Seviyorum diyen, 

Dudakların harcıyor beni. 

Oysa ben, seni. 

Yeni doğan bir bebek gibi masum, 

Her gün camına konan güvercin gibi sadık 

Ve Fanatik bir taraftar gibi, Çılgınca Sevdim. 

Biliyorum, istemiyorsun, 

Gidiyorum Bu Gece, 

Senin geldiğin, gardan, 

Bu kez, ben yola çıkıyorum. 

Ama, nereye, 

Neden Ve Ne için gittiğimi bilmeden. 

Amaçsızca, 

Çıkarsızca gidiyorum 

Ve, o çok sevdiğin 

Eğlenceli, bol yalanlı şehri 

Sana bırakıyorum. 

Gidiyorum, 

Duygularım Siyaha Boyanmadan, 

Sevgim Nefrete Dönüşmeden, 

Adamlığımdan ödün vermeden, 

Ve seni içimden atmadan, Gidiyorum. 

GİDİYORUM! 

GÖKHAN KARADUMAN 

''şiir denizi'' adlı kitabımdan', 'Bu gün,  Gelişinin gün dönümü.  Geldiğin yerde,  Elini ilk tuttuğum istasyondayım.  Günlerden Salı,  Üzerimde, Sensizliğin Yıkıntısı.  Anıla...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Karaduman']::text[], 8.5, '{"poet":"Gökhan Karaduman","poet_slug":"gokhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/gidiyorum-81-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayramlar', 'bayramlar-halil-baba-takkabulan-wltbi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Arz’dan arş’a dualar yükselir

Arş’tan arz’a mağfiret iner

Affedince Yaradan

Kanayan yaram diner 

25.11.2003 Sarıgümüş, Bingöl', 'Arz’dan arş’a dualar yükselir Arş’tan arz’a mağfiret iner Affedince Yaradan Kanayan yaram diner  25.11.2003 Sarıgümüş, Bingöl...', ARRAY['Türk Edebiyatı','Şiir','Halil Baba Takkabulan']::text[], 8.5, '{"poet":"Halil Baba Takkabulan","poet_slug":"halil-baba-takkabulan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bayramlar-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Bana Bırak..', 'beni-bana-birak-gokhan-karaduman-o83oi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu hayatı, hiç paylaşmadık seninle, 

Elin, elime değmedi, 

Gözlerim, bakmadı 

Gözlerinin içine. 

Hiçbir şarkıyı seçmedik ikimiz, 

Sana şiirler yazmadım, 

Türküler yakmadım, gözlerin için. 

Bir tek gülüşün uğruna, 

Harcamadım ömrümü. 

Kadehlerde, gözlerini görmedim, 

Kurşun gibi sözlerini duymadım belki, 

Pasta haneler de, Sabahı, Akşam etmedik birlikte. 

Belki çok sevdik, 

Belki de hiç sevmedik birbirimizi. 

Görüyorsun işte, 

Eserini görüyorsun, 

Yine Belki lerin, Farzetmelerin, 

Sözcüklerin, arkasında 

Avutmaya çalışıyorum kendimi. 

Öylesi kırdın, 

Öylesi yıprattın ki sen beni, 

Artık, kalemim bile, 

Yazmak istemiyor ismini. 

İçimde sen doluydun, 

Seninle güne doğuyor, 

Seninle kapıyordum gözlerimi, 

Dualarımda sen vardın, 

İsyanlarımda sen. 

Ahhh! 

Sen yokmusun sen, 

Nasıl da kandırdın, 

Nasılda oynadın benimle. 

Benki asırları sığdırmıştım yıllara, 

Ne acılar, 

Ne yokluklar görmüştüm de, 

Yıkılıp kalmamıştım böyle tek başıma, 

Ne çile yağmurları, 

Yağmıştı da başımdan, 

Böyle ıslanmamış, tükenmemiştim, 

Şimdi, kendi gözyaşımda boğuluyorum sayende. 

Hadi artık git, 

İster yeni sevdalara, 

İster yeni kucaklara git, 

Ama ne olur, yalvarırım daha fazla tüketmeden, 

Beni bana bırak. 

Gökhan KARADUMAN', 'Bu hayatı, hiç paylaşmadık seninle,  Elin, elime değmedi,  Gözlerim, bakmadı  Gözlerinin içine.  Hiçbir şarkıyı seçmedik ikimiz,  Sana şiirl...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Karaduman']::text[], 8.5, '{"poet":"Gökhan Karaduman","poet_slug":"gokhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/beni-bana-birak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
