INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Gelmeden Gel', 'olum-gelmeden-gel-baris-guc-8rdln', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir hirsiz gibi habersizce saçlara düsen aklar

Davetsiz bir misafir gibi yüzümüze çöken kirisikliklar

Git gide yaslanan çocuklugumuz

Bosalan bir kadeh gibi yavas yavas tükenen ömrümüz

Toprakla olan randevumuz

Bilmiyorum sen ve ben daha neyi bekliyoruz? 

21.01.2004       sda ozlt   MSN:   [email protected]', 'Bir hirsiz gibi habersizce saçlara düsen aklar Davetsiz bir misafir gibi yüzümüze çöken kirisikliklar Git gide yaslanan çocuklugumuz Bosalan...', ARRAY['Türk Edebiyatı','Şiir','Barış Güç']::text[], 8.5, '{"poet":"Barış Güç","poet_slug":"baris-guc","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/olum-gelmeden-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Arzum', 'son-arzum-bekir-gedikoglu-gyjkv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir sel geldi aniden 

Aşkım üstüne

Kumlarını bırakıp

Gitti denize

Dönüp de baktığımda bahtsız mazime

Tek neşem sendin

 Benim kalbimde

Kumsala indim, ben yalınayak

Ayaklarım yanıyor aldırmıyorum

Asıl, kalbimdeki ateşi bastıracak

Bir yar arıyorum, bulamıyorum

Denize daldım, ben çırılçıplak

Engine açıldım, kulaç atarak

-----artık,……gayemi,-----açıklıyorum

-----son arzum,

-----sahile ulaşamamak', 'Bir sel geldi aniden  Aşkım üstüne Kumlarını bırakıp Gitti denize Dönüp de baktığımda bahtsız mazime Tek neşem sendin  Benim kalbimde Kumsal...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/son-arzum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Afeti', 'kar-afeti-bayram-tunca-xqg3i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kar yağmayacak galiba derken

Öyle bir kar yağdı ki; diz boyu 

Kesildi şehrin elektrik ile suyu

Tam da bayram arifesindeyken

Olmadı derde derman, senaryo planı

Soğuktan dondu nice insanların kanı

Zayi oldu, nice insanımızın malı/canı

Bu belleğimize kazınan kalıcı bir anı

Teknik ve beşer, bugün de aciz kaldı 

Yüzlerce insan yollarda mahsur kaldı

Kar bora fırtına kaç kulun canını aldı

Mazideki duyulan endişe nerde kaldı

Kesildi elektrik/su, halk perişan oldu

Yetkililer, sırrı kadem basıp kayboldu

Kaybolmayanlarsa, suçu halkta buldu

Velhasıl, olan yine gariban halkı oldu

Kardan tratuvar ve buz patenti oluştu

Soğuktan kullar sağa sola koşuşturdu

Boğaz Köprüsünün, çelik halatı koptu

Kar boradan ademoğlunun ödü koptu

Yağan karı tuz değil gözyaşımız eritti

Yetkililerin duyarsızlığı bizleri delirtti

Bereket ki askerimiz yardıma seğirtti

Birazcık olsun, teselli olmamıza yetti

Söylesem sözüm geçmez kalır havada

Elinki toprak altında/bizimkisi havada

Bak, fırtınadan kesildi yine elektrik/su

Ders almadığımız kaçıncı hadisedir bu

Ah koptu yine nakil hatları karanlık bastı

Yoktu aslında bu şairin hiç kimseye kastı

Şair, milletimizin yaralarına parmak bastı

Acı/tatlı bir kar fırtınası daha geldi/geçti

Varsın, bu sözlerimden kimileri az alınsın

Tüm nakil hatlarımız toprak altına alınsın

Dilerim ki, bu tür olaylardan ibret alınsın

Ta çağdaş medeniyet seviyesine ulaşılsın

B. Tunca/22.01.2003-22.01', 'Kar yağmayacak galiba derken Öyle bir kar yağdı ki; diz boyu  Kesildi şehrin elektrik ile suyu Tam da bayram arifesindeyken Olmadı derde der...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/kar-afeti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkilem', 'i-kilem-hakki-hakan-kaya-lraud', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'çağırıyor ışığım

bir yanım

güneşe dönük

gölgeme bakar 

diğer yanım

havada tuhaf

yetişmesi gerekiyor 

sanki bir yere

serpiştiriyor 

ne varsa avucunda

alelacele

tereddütler içerisinde

gülüyor bir çocuk

elinde dondurma

kartopu oynarken

ikilem tutuyor elinde

ikilemi bilmeden

meraklanma çocuk

erimez dondurman

hava kış

hava soğuk...', 'çağırıyor ışığım bir yanım güneşe dönük gölgeme bakar  diğer yanım havada tuhaf yetişmesi gerekiyor  sanki bir yere serpiştiriyor  ne varsa ...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ikilem-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Döngü', 'dongu-hakki-hakan-kaya-jzuv1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'pişmanlıktır

yaşananlardan 

sonra gelen,

gelen yaşanır

düşünülmeden,

sonra gerçek vurur

kaygı bulutları 

sorgu sislerinden.

ve çekersin kendini,

örtülü gerçeğin 

dağılınca sisleri,

yıkıntılar içinde gezersin

sessizce yıkılırsın 

bakarken yıktıklarına

cam kırığı yüreğin

parçalanırsın.

bir sabah uyanırsın,

girersin yeniden 

bilinçsiz arayışına

yaşadığın eksikliğin, 

zaman bağlamıştır

geçmişe kabuğunu,

dünü görmez

dünü bilmezsin,

boş verirsin her şeye

fırtınanın pençesinde

kuru yaprak bedenin

fırtınanın götürdüğü yere.

gelen alınır yeniden

gelen yaşanır,

gelenin ardından gelen

yine pişmanlıktır...', 'pişmanlıktır yaşananlardan  sonra gelen, gelen yaşanır düşünülmeden, sonra gerçek vurur kaygı bulutları  sorgu sislerinden. ve çekersin kend...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/dongu-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece', 'sadece-demet-kaytan-f75ch', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senin için herşey olurum

İstersen kışın güneşin olur ısıtırım

Yazın yağmurun olur serinletirim

Yıldızın olur yol gösteririm

Sen istersen

Dişin olup yatağına serilirim

Nikâhına girer karın olurum

Geceyken gündüzü yaşatırım

Senin için herşey olurum

Kulun olur kölelik yaparım

Halın olur ayaklarına serilirim

Sadece paran olmam

İhtiyaç duyduğunda harcanan

Zevkin için dağıtılan', 'Senin için herşey olurum İstersen kışın güneşin olur ısıtırım Yazın yağmurun olur serinletirim Yıldızın olur yol gösteririm Sen istersen Diş...', ARRAY['Türk Edebiyatı','Şiir','Demet Kaytan']::text[], 8.5, '{"poet":"Demet Kaytan","poet_slug":"demet-kaytan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sadece-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkla Severim', 'askla-severim-demet-kaytan-xlza2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben sevdimmi aşkla severim

Bedenimle ruhumla kalbimle

Kanım akar gerekirse

Gerekirse gözyaşlarım senin için

Yalansız riyasız

Ben sevdim mi adam gibi severim

Kadınlığımla yüreğimle mertçe

Dişiliğimi sererim önüne

Maskesiz severim şarkılarımla

Ben sevdimmi delikanlı gibi severim

İhanet etmeksizin

Parasız

Senin için kışı yaşarım yaz da bile

Gerekirse servetimi koyarım

Canımı koyarım senin uğruna', 'Ben sevdimmi aşkla severim Bedenimle ruhumla kalbimle Kanım akar gerekirse Gerekirse gözyaşlarım senin için Yalansız riyasız Ben sevdim mi a...', ARRAY['Türk Edebiyatı','Şiir','Demet Kaytan']::text[], 8.5, '{"poet":"Demet Kaytan","poet_slug":"demet-kaytan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/askla-severim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yedekteki Kadınım', 'yedekteki-kadinim-demet-kaytan-jgf1f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben yedekteki kadınım

Gecelerin dostu karanlıkların kraliçesiyim

Güneşi sen istersen görebilen 

Hep sonbaharı yaşayan

Git dediğinde giden çağırdığında gelen

Ben yedekteki kadınım

Adım ne 

Bende bilmem

Bazen Mehtap Bazen Sevtap...

Şarkılarda sarhoş eden kadehlere şarap olan

Ben yedekteki kadınım

Fırtana gibi yaşayan boş kalple gezen

Hayatı umarsızca yaşan 

Yaşak ilişkilerin kahramananı

Düzgün yatakların kırışık çarşafları

Ben yedekteki kadınım

Saçlarına aklar düşen üstüne boya çektiren

Efkârlandımı sigarasından bir nefes çeken

Kederlendimi geçmişini silen

Ben yedekteki kadınım', 'Ben yedekteki kadınım Gecelerin dostu karanlıkların kraliçesiyim Güneşi sen istersen görebilen  Hep sonbaharı yaşayan Git dediğinde giden ça...', ARRAY['Türk Edebiyatı','Şiir','Demet Kaytan']::text[], 8.5, '{"poet":"Demet Kaytan","poet_slug":"demet-kaytan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yedekteki-kadinim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşeydin', 'herseydin-demet-kaytan-seog0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Benim için sen herşeydin

Ağlamayı sende öğrendim

Defalarca kırılıp tamir edilmeyi

Bazen tanırdın beni bazen tanımaz

Günün olurdum yarını belli olmayan

Karın olurdum gübre olup tohumlarını tutan

Dişin olurdum toplantılarında yer kaplayan

Yosman olurdum yatağında gönlünü eğleyen

Bazen paspas olurdum çiğnenen

Bazen başında taç olurdum göklere çıkardığın

Hafta içlerin olurdum işlerini yapan

Hafta sonların olurdum içini ferahlatan

İçki sofralarında mezen olurdum

Benim için sen herşeydin

Senin için ben aslında hiçbirşeydim', 'Benim için sen herşeydin Ağlamayı sende öğrendim Defalarca kırılıp tamir edilmeyi Bazen tanırdın beni bazen tanımaz Günün olurdum yarını bel...', ARRAY['Türk Edebiyatı','Şiir','Demet Kaytan']::text[], 8.5, '{"poet":"Demet Kaytan","poet_slug":"demet-kaytan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/herseydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye Mektuplar 2', 'sevgiliye-mektuplar-2-oguzkan-bolukbasi-9dao1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevgili sevgilim

Kar yağıyor başıbozuk bir şekilde

Yer gök beyaza döndü

Sevdiğin günlerdi karlı günler

Sanki çocuksu bir düğündü

Yere yatar ellerini açardın

Kalkınca sanki karlar üzerinde kalırdın

Ellerinde kocaman eldivenler 

Kızak olurdu bize merdivenler

Çığlık çığlığa

Bırakırdık yokuş aşağı

Düzlüğe geldiğinde

Kızak bir tarafta

Bizler bir tarafta

Gülüşlerimiz her tarafta

Sevgili sevgilim

Şimdilerde soğuk pek sevilmiyor

Cambaz gibi yollarda 

Yengeç misali yürüyorken

Bir düşme korkusu oluştu nedense

Senin gibi düşmekten korkmuyor kimse

Sevgili sevgilim

Kar yağıyor

İstanbul teslim oluyor

Ulubatlı kar bayraklarını her yere dikmiş

Kıs kıs gülüyor

Koca şehir ağır ağır yürüyor

Bir gecede yaşlanmış adam misali

Damlar beyaza bürünüyor

Kar bu sevgili sevgilim

Nedense yaşlılığı düşündürüyor', 'Sevgili sevgilim Kar yağıyor başıbozuk bir şekilde Yer gök beyaza döndü Sevdiğin günlerdi karlı günler Sanki çocuksu bir düğündü Yere yatar ...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sevgiliye-mektuplar-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Minyatür', 'minyatur-mete-tugluk-ykolo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yıl ay gün saat an

ve hava

ve acı çığlık çığlığa

su

kumaş

ve ışık sonunda

tutmanın hazzı

için ve dışın ayrılması

yasakla tanışmak

ağlamak 

gülmek

öykünmek

ve sevgi

ve nefret

ve insan olmak üç yaşında minyatür…', 'yıl ay gün saat an ve hava ve acı çığlık çığlığa su kumaş ve ışık sonunda tutmanın hazzı için ve dışın ayrılması yasakla tanışmak ağlamak  g...', ARRAY['Türk Edebiyatı','Şiir','Mete Tuğluk']::text[], 8.5, '{"poet":"Mete Tuğluk","poet_slug":"mete-tugluk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/minyatur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçiçe', 'i-cice-mete-tugluk-ms508', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'dokun bir kurbağanın ıslak başına

bulantı saplanmasın parmağına

bak 

mezartaşı ve üstündeki bülbüle

yanıtla

onu ona çözüyor mu ayakları

bağlıyor mu yoksa…', 'dokun bir kurbağanın ıslak başına bulantı saplanmasın parmağına bak  mezartaşı ve üstündeki bülbüle yanıtla onu ona çözüyor mu ayakları bağl...', ARRAY['Türk Edebiyatı','Şiir','Mete Tuğluk']::text[], 8.5, '{"poet":"Mete Tuğluk","poet_slug":"mete-tugluk","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/icice-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-murat-demir-684wq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüz yüze söylenecek

Söz mü bıraktın bende

Sevmek için görecek

Göz mü bıraktın bende

Sen nasıl canan mışsın

Sen nasıl bir can mışsın

Perişan ettin beni

Sen nasıl insan mışsın

Beraber yürünecek

Yol mu bıraktın bende

Tutupta sarılacak

Kol mu bıraktın bende

Bak anlarsın bak bana

Bak anlarsın yanmama

Bu nasıl bir sevdaymış

Baksana ağlamama

Ellerden saklanacak

Sır mı bıraktın bende

Koparıp koklanacak

Gül mu bıraktın bende

Ak ettin saçımı sen

Akıttın yaşımı sen

Ne duşmanım ne dostum

Sen yaktın başımı sen', 'Yüz yüze söylenecek Söz mü bıraktın bende Sevmek için görecek Göz mü bıraktın bende Sen nasıl canan mışsın Sen nasıl bir can mışsın Perişan ...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sen-328-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyük Söz', 'buyuk-soz-melek-midikoglu-7i5q8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kimselerden duymadım ki,

Görmedim ki,

Gitmedim ki O''ndan...

Sevmedimse sevilmedim ki.

Güzel değilsem, yalan da değildim,

Dua da ettim,

Gönülde birdim sever idim,

Hep tektim! 

Bundan böyle küstüm aşka

Yolu yokuşsa döndüm terse

Sevmeyeceğim sevilmeyeceğim

Gelse bile görmeyeceğim.', 'Kimselerden duymadım ki, Görmedim ki, Gitmedim ki O''ndan... Sevmedimse sevilmedim ki. Güzel değilsem, yalan da değildim, Dua da ettim, Gönül...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/buyuk-soz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.İkilem', 'i-kilem-melek-midikoglu-0c61t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ruhunu ikinciyle tokuşturdu

Rastlantılarda buluştu

İğrelti otu

Tutku 

Kurudu

Oysa ki

Taş çatlasa

Ben çatlamazdım aşk''a.

Yakışana,

Oğul''un Beybabasına.', 'Ruhunu ikinciyle tokuşturdu Rastlantılarda buluştu İğrelti otu Tutku  Kurudu Oysa ki Taş çatlasa Ben çatlamazdım aşk''a. Yakışana, Oğul''un Be...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ikilem-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karlar Altında Kalbim', 'karlar-altinda-kalbim-gulay-yildiz-5qkdd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Milyonuncu kez gidiyorum hesapsız sevdanın ardından

Her seferinde hatalardan kalanlara sığınıyorum

Gözlerin ağlamaklı artık, zor herşey diyorsun, hissediyorum

Hatalar sinsilesi,

Sen beni ben dostları yaraladık 

Zaman affetmeyeceğim nidalarını savuruyor gökyüzüne

Oysa kalbim...

Bu soğuk kış gecesinde

Sıkışmış bir pranganın içine, daraldıkça ısınıyor

Daraldıkça, büyüyor...

Hasretinle, acımı savurup harmanlıyor fırtına

Özleminle, gözyaşımı akıtıyor gökyüzü

Donan öpücüklere yağıyor kar bu gece

Kalbim prangada...

Pranga karlar altında...', 'Milyonuncu kez gidiyorum hesapsız sevdanın ardından Her seferinde hatalardan kalanlara sığınıyorum Gözlerin ağlamaklı artık, zor herşey diyo...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/karlar-altinda-kalbim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğrendim', 'ogrendim-demet-kaytan-097iw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öğrendim hayatın zorluğunu

Yolların hep çıkmazla dolu olduğunu

Hergün bir yıkım yaşanması gerektiğini

Ağlamanın yerinini gülmenin aldığını

Öğrendim her yaranın zamanla kapandığını

En büyük pişmanlıkların bile zamanla son bulunduğunu

Beyazlar giyince mutlu olunmadığını

Maviler giyince gökte bulut olunmadığını

Görmedim sevipte yanmayanını

Ardından ağlamayanını

Öğrendim hayata gülümsemenin güzel yanını

Sonrasında mutluluk hissettiğimi

Acıda olsa hayatla başa şıkmayı

Herşeye rağmen aşksız yaşanmadığını

Zamanın alışmayı öğrettiğini

Gerçek aşkı asla unutturmadığını', 'Öğrendim hayatın zorluğunu Yolların hep çıkmazla dolu olduğunu Hergün bir yıkım yaşanması gerektiğini Ağlamanın yerinini gülmenin aldığını Ö...', ARRAY['Türk Edebiyatı','Şiir','Demet Kaytan']::text[], 8.5, '{"poet":"Demet Kaytan","poet_slug":"demet-kaytan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ogrendim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Gerçekten Aldatmadım Ey Aşk', 'seni-gercekten-aldatmadim-ey-ask-demet-kaytan-mpedq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni gerçekten aldatmadım ey aşk

Bedensel bir aldatmaydı bu

Ruhum sana hep sadık kaldı

Tek gecelikti tek düze idi

Onlar sarışındı esmerdi 

Bazıları asım bazıları yedeklerim

Farklı zevklerimdi

Seni gerçekten aldatmadım ey aşk

Benimki sadece kumardı

Bir zar atıyordum bazen şişman bazen zayıf

Taşlar düşeş gelirse büyük ikramiye

Seni gerçekten aldatadım ey aşk

Ten temasıydı

Kalbim hep senin oldu

Onlar deniz gözlü yeşil gözlü şehla gözlü

Kiraz dudaklı al yanaklı

Soluk benizli ince dudaklı

Benim yasaklarımdı

Belki bir tür oyun

Belki bir tür inat

Seni gerçekten aldatmadım ey aşk

Bazen kaptan oldum bazen gemi  bazen yolcu

Bazen liman oldum zincir vurulan', 'Seni gerçekten aldatmadım ey aşk Bedensel bir aldatmaydı bu Ruhum sana hep sadık kaldı Tek gecelikti tek düze idi Onlar sarışındı esmerdi  B...', ARRAY['Türk Edebiyatı','Şiir','Demet Kaytan']::text[], 8.5, '{"poet":"Demet Kaytan","poet_slug":"demet-kaytan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/seni-gercekten-aldatmadim-ey-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldız ''ım', 'yildiz-im-demet-kaytan-5dg1o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen benim gecem gündüzüm 

Baharım

Kalbimde ki ışığım

Asla terketmeyenim

Yalansızım

Sen benim 

Elim ayağım

Gözüm kulağım

Her gece aklımdan hiç çıkmayanım

Birde bana söz versen

Ah hiç gitmesen

Adı YILDIZ olanım

Gökyüzüne servet saçanım

Bilsen bu hayatta yolumu kaybettiğimi

Uzatırsın elini

Sen benim gecem gündüzüm

Baharım

Kalbimde ki ışığım

Asla terk etmeyenim yalansızım', 'Sen benim gecem gündüzüm  Baharım Kalbimde ki ışığım Asla terketmeyenim Yalansızım Sen benim  Elim ayağım Gözüm kulağım Her gece aklımdan hi...', ARRAY['Türk Edebiyatı','Şiir','Demet Kaytan']::text[], 8.5, '{"poet":"Demet Kaytan","poet_slug":"demet-kaytan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yildiz-im-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen İstanbul', 'sen-i-stanbul-demet-kaytan-eb965', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Selam sana İstanbul

Ben buralardayken her yer karanlık

Sanki herşey berbat

Sen İstanbul

O güzellikler arasında bir beni kötü eden

Nice zenginler arasında ezdiğin bir ben

Kurşunlarını hedeflediğin

O sır edip yok ettiğin

Giderken ağlayarak geri dönmeye söz veren ben

Şimdi bana nerelerii verirsen ver

Dar gelir senden', 'Selam sana İstanbul Ben buralardayken her yer karanlık Sanki herşey berbat Sen İstanbul O güzellikler arasında bir beni kötü eden Nice zengi...', ARRAY['Türk Edebiyatı','Şiir','Demet Kaytan']::text[], 8.5, '{"poet":"Demet Kaytan","poet_slug":"demet-kaytan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sen-istanbul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göz Koyduğum', 'goz-koydugum-demet-kaytan-c3ajh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yinemi gidenim oluyorsun

Sen yıllar önce göz koyduğum

Nereye gidiyorsun

Bak senin için kapattım bu falı

Bakalım ne diyecek çingene bacı

İstesem kalanım olurmusun

Sevenim koruyanım

Dün hiç yaşanmadı desem

Yine gidermisin

Yalvarsam yakarsam

Aşkımız sonsuz olacak desem

Şiir olup mısralar tutacak desem

Benim olurmusun

Sen benim sonum olacak desem

Erkeğim olurmusum', 'Yinemi gidenim oluyorsun Sen yıllar önce göz koyduğum Nereye gidiyorsun Bak senin için kapattım bu falı Bakalım ne diyecek çingene bacı İste...', ARRAY['Türk Edebiyatı','Şiir','Demet Kaytan']::text[], 8.5, '{"poet":"Demet Kaytan","poet_slug":"demet-kaytan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/goz-koydugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Yeniden Ben Olmak İstiyorum', 'ben-yeniden-ben-olmak-i-stiyorum-demet-kaytan-qiqpo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ve ben yeniden ben olmak istiyorum

Yalnızlığıma yalnizlık katılmadan

Yollarıma bir yenisi eklenmeden

Aklım soru soraken

Yeni cevapları unutmadan

Kalbim seni aldatmadan

Ruhumla şeytanı buluşturmadan

Eller gibi yalan karışmadan

Ve ben yeniden ben olmak istiyorum

Yüreğimdeki alev kor olmadan

İçimdeki umutlar tükenmeden

Yazlarım kış olmadan

Gözlerimin feri sönmeden

Çarpan kalbim durmadan

Gündüzlerim gece olmadan

Emanetim sahibine kavuşmadan

Ben yeniden ben olmak istiyorum', 'Ve ben yeniden ben olmak istiyorum Yalnızlığıma yalnizlık katılmadan Yollarıma bir yenisi eklenmeden Aklım soru soraken Yeni cevapları unutm...', ARRAY['Türk Edebiyatı','Şiir','Demet Kaytan']::text[], 8.5, '{"poet":"Demet Kaytan","poet_slug":"demet-kaytan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ben-yeniden-ben-olmak-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-demet-kaytan-kpnkn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben sensiz geçen gecelerde

Seni düşledim hayallerimde

En çok gülüşünü özledim o gül yüzünde

Hani beni ilk öptüğün yerde

Seni düşündüm her gezdiğim yerde

En çok elimi tutuşunu özledim o caddelerde

Hani beraber gittiğimiz o yerlered

Bir fincan çayı özledim kendimce

Sen yoksun diye esirgedim nefsimden sessizce', 'Ben sensiz geçen gecelerde Seni düşledim hayallerimde En çok gülüşünü özledim o gül yüzünde Hani beni ilk öptüğün yerde Seni düşündüm her ge...', ARRAY['Türk Edebiyatı','Şiir','Demet Kaytan']::text[], 8.5, '{"poet":"Demet Kaytan","poet_slug":"demet-kaytan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sensiz-69-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Zaman', 'ne-zaman-demet-kaytan-6clgj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne zaman uykuya dalsam

Hemen gece olur uyandığımda

Göremem bir türlü gündüzleri

En uzun günde bile

Karanlık olur birden bire

Ne zaman evden çıksam yürümeye

En kısa yollar bile uzun gelir şu dizlerime

Hep dar çıkmaz sokaklar çıkar karşıma

Doğrular bile eğrilir birdenbire

Ne zaman dilek tutsam

Yıldızlar kaymaz olur o anda

İsteklerim son bulur biranda', 'Ne zaman uykuya dalsam Hemen gece olur uyandığımda Göremem bir türlü gündüzleri En uzun günde bile Karanlık olur birden bire Ne zaman evden ...', ARRAY['Türk Edebiyatı','Şiir','Demet Kaytan']::text[], 8.5, '{"poet":"Demet Kaytan","poet_slug":"demet-kaytan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ne-zaman-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şehirde', 'bu-sehirde-demet-kaytan-el2fo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu şehirde ben çık sensiz kaldım

Sessiz yaşadım

Yalanlara dolanlara

İstemeden kandım

Gün gün gündüzsüz gece yaşadım

Bu şehirde ben çok yalnız kaldım

Sessiz sedasız ağladım

İçten içe çığlıklar attım

Yazları kış yaşadım

Ah ben adam gibi adama

Ah ben doğru söze

Bu hayattta aşkı için yaşayana

Hasret kaldım', 'Bu şehirde ben çık sensiz kaldım Sessiz yaşadım Yalanlara dolanlara İstemeden kandım Gün gün gündüzsüz gece yaşadım Bu şehirde ben çok yalnı...', ARRAY['Türk Edebiyatı','Şiir','Demet Kaytan']::text[], 8.5, '{"poet":"Demet Kaytan","poet_slug":"demet-kaytan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bu-sehirde-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-demet-kaytan-ywnof', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İsteyipte söyleyemediğim

Karalar bağladığım

Gözlerimi kapatıp geçtiğim

Duyupta duymadığım

Okuyupta anlamadığım

Anlayıpta anlamamazlıktan geldiğim

Gün gelip dolup dolup taştığım

İntikamını almak istediğim

Çok şey var sende hayat

İsteyipte alamadığım

Alıpta kaybettiğim

Uğruna gözyaşı döktüğüm

Kucağıma alamadığım

Yıllarca beklediğim

Bekleyenip olupta gidemediğim

Gidipte dönemediğim

Sende bana ait olan çok şey var hayat', 'İsteyipte söyleyemediğim Karalar bağladığım Gözlerimi kapatıp geçtiğim Duyupta duymadığım Okuyupta anlamadığım Anlayıpta anlamamazlıktan gel...', ARRAY['Türk Edebiyatı','Şiir','Demet Kaytan']::text[], 8.5, '{"poet":"Demet Kaytan","poet_slug":"demet-kaytan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hayat-110-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden Gelsem Dünyaya', 'yeniden-gelsem-dunyaya-demet-kaytan-j90pf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yeniden gelsem dünyaya

Giderdim gözümün görmediği yerlere

Sen beni sevdikçe

Dönüşü olmasada o yerlere

Hiç korkmaz arayıp sormaz

Atardım kendimi dehlizlere

Yeniden gelsem dünyaya

Ömrüm yoluna olsa amade

Pişman olsam yine her gece

Hiç kormaz aldırmaz

Rüzgar olup eserdim oralara', 'Yeniden gelsem dünyaya Giderdim gözümün görmediği yerlere Sen beni sevdikçe Dönüşü olmasada o yerlere Hiç korkmaz arayıp sormaz Atardım kend...', ARRAY['Türk Edebiyatı','Şiir','Demet Kaytan']::text[], 8.5, '{"poet":"Demet Kaytan","poet_slug":"demet-kaytan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yeniden-gelsem-dunyaya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek İstedim', 'sevmek-i-stedim-demet-kaytan-n3x3e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu hayatta sevmek istedim

Seç dediler

Günleri dedim

Gece bekletir

Seni korkutur dediler

Renkleri dedim

Kırmızı

Ateş olup yakar dediler

Sarı

Ayrılık getirir

Delirtir dediler

Yeşil

Mura’tır hep bekletir dediler

Beyaz

Kefen olup giydirirler dediler

Ben hayatta sevmek istedim

Seninle birlikte günleri

Günlerle birlikte renkleri

Kısaca seninle hayatı

Beraber sevmek istedim', 'Bu hayatta sevmek istedim Seç dediler Günleri dedim Gece bekletir Seni korkutur dediler Renkleri dedim Kırmızı Ateş olup yakar dediler Sarı ...', ARRAY['Türk Edebiyatı','Şiir','Demet Kaytan']::text[], 8.5, '{"poet":"Demet Kaytan","poet_slug":"demet-kaytan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevmek-istedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bende Bensin', 'sen-bende-bensin-demet-kaytan-b6zyc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen bende bensin

Hüznünle kederinle isminle

Farklı zamanlarda aynı yerlerde

Gündüzleri gelen

Sözleri değerli kılan

Yazın açıp kışın solan

Dağlar aşıp sesini duyuran

Kapanan yolları açan

Sen bende bensin

Dünyaya meyden okuyan

Hayatı efeler gibi yaşayan

Parayı şöhret yapan

Maneviyatı servet yapan

Sen bende bensin', 'Sen bende bensin Hüznünle kederinle isminle Farklı zamanlarda aynı yerlerde Gündüzleri gelen Sözleri değerli kılan Yazın açıp kışın solan Da...', ARRAY['Türk Edebiyatı','Şiir','Demet Kaytan']::text[], 8.5, '{"poet":"Demet Kaytan","poet_slug":"demet-kaytan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sen-bende-bensin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal Bu Ya!', 'hayal-bu-ya-naime-erlacin-uymp4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'doğuya biletim kesilmedi hiç

batı ile doğunun 

örtüştüğü güneyim ben

badem ağaçlarıyla bezenmiş düşlerden gelir

asmalı bağ evlerine giderim

vakitsiz delinir gözlerim bilge bir dağda 

kirpiklerim muamma izleklerde titrer 

buz ayazlara düşerim ağustosta

yüzümde kar 

gözden taşırdığım tuz tenime akar

unutulmuşlardan bir su arkı içinde

camdan köprüler kurar düzlükten tepeye

tepeden düzlüğe göçerim

bir ses...bir mekan 

yakın tarihten bir zaman

sıkça çağırır vadesi dolmamış ayrılıklar gibi

oysa çok kalabalık buralar

göğsümde dünya dolusu insan var! 

kışı yaza döndüren kentler kayıp şimdi

aynaya yansıyan 

geçmişi izleyip su arkının içinde 

bir ehram kölesi gibi usanmaksızın 

köprüler inşa ederim

ruhumu kaptırdığım Anadolu ey! 

ilkyazdan renkler nakışladığım sevda

bir hayal ülkesini yalayan  gurbetimsin

hüznümsün sen 

seni başka türlü severim

yer... özlenen bir mekan

zaman...yaşanmamışlardan bir an

kişiler...yok artık

hayal bu ya kuruldu işte! 

(26 Ocak 2004)', 'doğuya biletim kesilmedi hiç batı ile doğunun  örtüştüğü güneyim ben badem ağaçlarıyla bezenmiş düşlerden gelir asmalı bağ evlerine giderim ...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/hayal-bu-ya-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Içtigim Gözyasimdi Yoklugun', 'ictigim-gozyasimdi-yoklugun-baris-guc-0y0fm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir sarmasigin agaci simsiki sarmasi gibi sarmak isterdim yüregini

Haciz koymak isterdim beynine,baska hiç kimseyi düsünmesin diye

Içtigin sigaranin dumani olmak isterdim,cigerlerinde hapis yatmak

Bir yaz esintisi olmak isterdim,yüzüne oksarcasina degmek

Bir kadeh olmak isterdim,dudaklarini her dokunusunda kesfetmek

Ve....beni anlamani isterdim, tahliye etmeni yüregindeki müebbetten

26.01.2004    sda ozlt   MSN:  [email protected]', 'Bir sarmasigin agaci simsiki sarmasi gibi sarmak isterdim yüregini Haciz koymak isterdim beynine,baska hiç kimseyi düsünmesin diye Içtigin s...', ARRAY['Türk Edebiyatı','Şiir','Barış Güç']::text[], 8.5, '{"poet":"Barış Güç","poet_slug":"baris-guc","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ictigim-gozyasimdi-yoklugun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Manifesto', 'manifesto-oguzkan-bolukbasi-3zhao', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'beni üzmek için

değerli olmalısın

eğerli isen üzemezsin

önemli olmalısın

nemli isen ıslattığınla kalırsın

anlatabilmelisin

dinleyebilmelisin

inleyebilmelisin aynı duyguyla

sevinebilmelisin aynı coşkuyla

aksi takdirde

görmem 

duymam bile seni

o nedenle yerli yersiz girip

kirletme bahçemi', 'beni üzmek için değerli olmalısın eğerli isen üzemezsin önemli olmalısın nemli isen ıslattığınla kalırsın anlatabilmelisin dinleyebilmelisin...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/manifesto-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmenden Geçtim', 'sevmenden-gectim-ercan-sari-14oyw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevmek yanlızlıksa

Zincir vurun sevdama

Seni arzularken

Yoksun yanımda

Çıkar savaşı değildi bu

Beni neden yaraladın

Kör düğüm ettin aşkımı

Perişan bıraktın

Kim vurduya gittim

Bu sevda yüzünden

Hançer yedim senden

Hiç beklemeden

Sevgimi verince

Hasret kaldım yüzüne

Beni sevmende geçtim

Yanarım giden günlerime', 'Sevmek yanlızlıksa Zincir vurun sevdama Seni arzularken Yoksun yanımda Çıkar savaşı değildi bu Beni neden yaraladın Kör düğüm ettin aşkımı P...', ARRAY['Türk Edebiyatı','Şiir','Ercan Sarı']::text[], 8.5, '{"poet":"Ercan Sarı","poet_slug":"ercan-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevmenden-gectim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işığım...', 'isigim-ceyda-ayfer-oz-vns11', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sensin aksimin döşendiği

Serseri mayın gibi,

Sensin soluksuz girdapların sebebi

Adının yutkunulmuş ilk harfi gibi...

Gözü kararmışlığım köşe kapmaca derdinde

Zindanımın çelik iskelesinde...

İçeri süzülen ışığım,

Sanki hayata sil baştan yazılmışım,

Ürkek bir sancı dolar içime,

Aldığım öksüz nefesimle...

Cıbıl ağaçlarla kucaklaştım

Başımı yasladığım omuzun diye...

Dün gelmiştim yine sahile,

Dalga konuştu benimle,

Çizdim köpüklerin resmini,

Astım gökyüzüne...

Velhasıl, sandalımı yamadım dün gece

Rengi atmış saç tellerimle…', 'Sensin aksimin döşendiği Serseri mayın gibi, Sensin soluksuz girdapların sebebi Adının yutkunulmuş ilk harfi gibi... Gözü kararmışlığım köşe...', ARRAY['Türk Edebiyatı','Şiir','Ceyda Ayfer Öz']::text[], 8.5, '{"poet":"Ceyda Ayfer Öz","poet_slug":"ceyda-ayfer-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/isigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çare Yok', 'care-yok-ercan-sari-zwi7b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Odam döndü hücreye

Mahkumum yine

Yarını beklemeye

Hep beklesemde

Çare yok niye

Çözüm yolu var mı

Sensizliğime

Az kaldı delirmeye

Gelde

Getir beni kendime', 'Odam döndü hücreye Mahkumum yine Yarını beklemeye Hep beklesemde Çare yok niye Çözüm yolu var mı Sensizliğime Az kaldı delirmeye Gelde Getir...', ARRAY['Türk Edebiyatı','Şiir','Ercan Sarı']::text[], 8.5, '{"poet":"Ercan Sarı","poet_slug":"ercan-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/care-yok-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmiyor Yanıma', 'gelmiyor-yanima-ercan-sari-mlz05', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ümitle başlamıştık

Bitti çok çabuk

Bilmiyorum bu sevdaya

Biz nasıl kıydık

Mahkum olduk

Yabancı olmaya

Hep baksamda

Gözünün damarına

Yok onda bir istek

Bir kıpırdama

Yüzündeki endişeyi

Koruyor hala

Korkuyor yeniden bana alışmaya

Uzaktan bakmak

Gibi değil sevdalar

Tenin tenime değmezse

Ne işe yarar

Sen yanımdaysan eğer

Aşkın sarmalar

Gelmiyor yanıma

Aşkı oyalar', 'Ümitle başlamıştık Bitti çok çabuk Bilmiyorum bu sevdaya Biz nasıl kıydık Mahkum olduk Yabancı olmaya Hep baksamda Gözünün damarına Yok onda...', ARRAY['Türk Edebiyatı','Şiir','Ercan Sarı']::text[], 8.5, '{"poet":"Ercan Sarı","poet_slug":"ercan-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gelmiyor-yanima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah Bilir', 'allah-bilir-ercan-sari-rx414', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güneş doğduya

Neler yaşadım gecede

Ben bende değildim

Geçen her saniyede

Nasıl ulaştım sabaha

Nasıl açoldı gözlerim

Bir Allah bilir

Bir de ben bilirim

Kahretti dertlerin

Sandım ki canıma kıyar

Daha yaşanacak günüm

Sorulacak hesabım var

Nasıl avuttum kendimi

Nasıl dindi gözlerim

Bir Allah bilir

Bir de ben bilirim', 'Güneş doğduya Neler yaşadım gecede Ben bende değildim Geçen her saniyede Nasıl ulaştım sabaha Nasıl açoldı gözlerim Bir Allah bilir Bir de b...', ARRAY['Türk Edebiyatı','Şiir','Ercan Sarı']::text[], 8.5, '{"poet":"Ercan Sarı","poet_slug":"ercan-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/allah-bilir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıssa-ı Musa', 'kissa-i-musa-mustafa-tanrikulu-bgayx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''Ülke-i Mısr'' olan bir yanağından kaçtı Musa

Ardında ''Beni İsrail'' vardı elinde  asa.

Firavun  ardına düşünce Hazret-i Musa''nın

Allah kudreti indirdi üzerine asanın.

Dedi ''vur kırmızı ağzına  mihrimah kulumun

Ki o dahi olsun bir kölesi benim yolumun''

Asa senin dokununca hafiften dudağına 

Onlar yol aldılar  Filistin olan yanağına.

Firavun dahi karşıya geçmek için  davrandı

Lakin o an senin ağzını kapattığın andı.

Firavundan ceset kaldı dudağının yanında 

Onu ben sanır olmayanlar kıssanın farkında.

Aslı  budur kıssa-ı Musa aleyhiselamın

Tefsir deyin yalan çıkmasın sözü Mustafam''ın.', '''Ülke-i Mısr'' olan bir yanağından kaçtı Musa Ardında ''Beni İsrail'' vardı elinde  asa. Firavun  ardına düşünce Hazret-i Musa''nın Allah kudret...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tanrıkulu']::text[], 8.5, '{"poet":"Mustafa Tanrıkulu","poet_slug":"mustafa-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kissa-i-musa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Gör', 'beni-gor-mustafa-tanrikulu-1406z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerim yollarda seni beklerken,

Camdan kadeh gibi kır beni beni.

Gayrı meydanlara çıkayım derken,

Aşkın eylemiştir sır beni beni.

Muhabbetin senin düşürdü derde,

Benim  neşem zaten dertte kederde

Ben de varım senin olduğun yerde

Kaldır perdeleri gör beni beni.

Mey olarak   susuz  dilde kurudum

Peymane olarak boşaldım doldum.

Aşkın duvarında şimdi yün oldum 

Bir örümcek ol da ör beni beni', 'Gözlerim yollarda seni beklerken, Camdan kadeh gibi kır beni beni. Gayrı meydanlara çıkayım derken, Aşkın eylemiştir sır beni beni. Muhabbet...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tanrıkulu']::text[], 8.5, '{"poet":"Mustafa Tanrıkulu","poet_slug":"mustafa-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/beni-gor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden', 'neden-ercan-otaci-cv43c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Neden hep sen deyince yoruluyor sular

Ve neden sana asina bu kadar

Daglar sehirler

Yollar ve yokuslar

Ve kus yuvalari 

Ve kus yuvalari...', 'Neden hep sen deyince yoruluyor sular Ve neden sana asina bu kadar Daglar sehirler Yollar ve yokuslar Ve kus yuvalari  Ve kus yuvalari......', ARRAY['Türk Edebiyatı','Şiir','Ercan Otaci']::text[], 8.5, '{"poet":"Ercan Otaci","poet_slug":"ercan-otaci","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/neden-64-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor İş İmiş Sevmek', 'zor-i-s-i-mis-sevmek-galip-karabatak-a6h9i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zor iş imiş sevmek! 

Sevince ölürcesine seveceksin

Gözlerine bakınca onun

Güneşin gözlerini göreceksin! 

yiğite bir nam gibi,

damardaki kan gibi,

Öyle kancık bir yalan gibi değil! 

Sevince adam gibi seveceksin! 

Zor iş imiş sevmek! 

Sevince çığlıklar susmalı

Sesine deyince nefesin

İşte o an içerin yanmalı! 

Anaya son bakış gibi

Zemheride kara kış gibi

Öyle üç beş kuruşa satış gibi değil

Yüreğine bir nakış gibi seveceksin! 

Zor iş imiş sevmek! 

Sevince yıldızlar ağlayacak

Ellerini tutunca onun

Çağlayanlar değil, alevler çağlayacak! 

Alındaki namus gibi,

Bembeyaz düşte kabus gibi,

Öyle işkencedeki “sus! ” gibi değil

Sevince Yunus gibi seveceksin!', 'Zor iş imiş sevmek!  Sevince ölürcesine seveceksin Gözlerine bakınca onun Güneşin gözlerini göreceksin!  yiğite bir nam gibi, damardaki kan ...', ARRAY['Türk Edebiyatı','Şiir','Galip Karabatak']::text[], 8.5, '{"poet":"Galip Karabatak","poet_slug":"galip-karabatak","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/zor-is-imis-sevmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elleri Öpülesi Sevgiler', 'elleri-opulesi-sevgiler-orhun-basat-4m9xa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'aynı adımlarla, 

aynı yerlere basarak, 

-yalnızca yıpranmış anıları atlayarak –

yürüdüm geçmişin ayak izlerinde.

kulağa hoş gelen melodileri, 

o eski sevgileri bulamadım.

elleri öpülesi sevgileri..

yalnızca, derinde çok derinde, 

o eski acıları yakaladım..

yürüdüm geçmişin ayak izlerinde, 

değişen pek bir şey yoktu sevgilerin dışında.

biraz daha azaldık diye, 

beyazlar; toplanmış ağlıyordu, 

ölü bir martının baş ucunda.

siyahlar daha bir siyahtı.

yaşlandığımı anladım.

dönüp bu güne, 

ölümcül yorgun, duraksamadan, 

ilk yarını adımladım..', 'aynı adımlarla,  aynı yerlere basarak,  -yalnızca yıpranmış anıları atlayarak – yürüdüm geçmişin ayak izlerinde. kulağa hoş gelen melodileri...', ARRAY['Türk Edebiyatı','Şiir','Orhun Basat']::text[], 8.5, '{"poet":"Orhun Basat","poet_slug":"orhun-basat","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/elleri-opulesi-sevgiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlükler XIV', 'dortlukler-xiv-ahmet-aksoy-ak3o1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'LXVI

Dört yanımı günahlar sarmış

Bir başımı sevaplar almış

İnsanlığım iki aradayken, bana

Bir başıma inanmak kalmış.

LXVII

Görüp göreceğinbir düş

Duyup duyacağın bir düş

Boşuna dememşler fani bu dünya

Alaıp alacağın bir düş

LXVIII

Söyleyecek sözüm yok sana

Anlayacak çabam yok sana

Bir kere çiğneyerek sırt döndün bana

Çünkü ayan beyan yok deva

LXIX

Sanmaki sürecek bu sevda daha

Bir içime düşerse başka eda

O vakit dönerim daha bir aşkla

Sen ies maziden yakın o ana

LXX(Küçük İşçi) 

Küçük bir çocuk gördüm trende

Uzandım saçından tuttum ve

O ise içten yaklaştı yanıma

Sevilmek için tek bir elle', 'LXVI Dört yanımı günahlar sarmış Bir başımı sevaplar almış İnsanlığım iki aradayken, bana Bir başıma inanmak kalmış. LXVII Görüp göreceğinbi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dortlukler-xiv-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yamanım', 'yamanim-murat-demir-ib3b7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dağlara yaslanırım

Ne yapsam taşlanırım

İstediğim her şeyi

Yaşattın,yarım yarım

Doyamadım yamanım

Nerde senin tamamın

Ben senin yarımınla

Söyle nasıl yaparım

Ya gel ya git tamamen

Bir gelip bir gitmeden

Olacaksa tam olsun

Gel nerdesin bitmeden

Aklımın yarısını

Çekip aldın hasını

Neden doldurmuyorsun

Sevdamızın tasını

Yamanım,yaman yaman

Yanarım,aman aman

Sensiz rüyalarımda

Ölürüm,çoğu zaman', 'Dağlara yaslanırım Ne yapsam taşlanırım İstediğim her şeyi Yaşattın,yarım yarım Doyamadım yamanım Nerde senin tamamın Ben senin yarımınla Sö...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yamanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine...', 'yine-sezgin-keles-wq5fk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine gönlümde bir kıpırdama,

Yine aynı aşk nameleri ağzımda,

Yine gülücükler saçıyorum çevreme,

Uzun sürmese bile...', 'Yine gönlümde bir kıpırdama, Yine aynı aşk nameleri ağzımda, Yine gülücükler saçıyorum çevreme, Uzun sürmese bile......', ARRAY['Türk Edebiyatı','Şiir','Sezgin Keleş']::text[], 8.5, '{"poet":"Sezgin Keleş","poet_slug":"sezgin-keles","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yine-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim söz dinlemez', 'kalbim-soz-dinlemez-sezgin-keles-kh0rp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir kör kuyudayım,hiç bir çıkar yol yok,

Yine senin koynundayım,senden kaçış yok,

Sana bağlı ellerim,kelepçem sensin, 

Kalbim söz dinlemez ki senden vazgeçsin.', 'Bir kör kuyudayım,hiç bir çıkar yol yok, Yine senin koynundayım,senden kaçış yok, Sana bağlı ellerim,kelepçem sensin,  Kalbim söz dinlemez k...', ARRAY['Türk Edebiyatı','Şiir','Sezgin Keleş']::text[], 8.5, '{"poet":"Sezgin Keleş","poet_slug":"sezgin-keles","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kalbim-soz-dinlemez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devran', 'devran-bogazli-boga-rmcyt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geniş bak pencereden, uzak ve derin.

Bil ki ruhunun boyutları var.

Kendini yele bırak, hafif ve serin.

Düşünce ve sözler gizli bir duvar.

Aşacak gücün varsa eğer, sakın çekinme.

At kendini boşluğa, korkma çarpmazsın.

“Akşam oldu, sabah oldu” diye yerinme,

Kır zaman zincirini varsın dağılsın.

Ne yer, ne zaman, ne de sözcükler.

Hiç birine önem verme, aldırma.

Şu anda bulduğun mutluluk yeter.

Kendini küçük hesaplara daldırma.

İşte geldi gidiyor dopdolu bir tren.

İçindekiler telaş içinde yer kapar.

Aslında ne giden var ne de gelen.

Bir bardak suda bazen fırtına kopar.

Yapar ve yıkar insan, umutlarını.

Sanki bir yere doğru yol almış gibi.

Gücün varsa göster, aç kanatlarını.

Hakikat denizini kavramış gibi.', 'Geniş bak pencereden, uzak ve derin. Bil ki ruhunun boyutları var. Kendini yele bırak, hafif ve serin. Düşünce ve sözler gizli bir duvar. Aş...', ARRAY['Türk Edebiyatı','Şiir','Boğazlı Boğa']::text[], 8.5, '{"poet":"Boğazlı Boğa","poet_slug":"bogazli-boga","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/devran-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan', 'i-nsan-bogazli-boga-tumqp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşkın dudağı kaçtı mı senden

Şaşıp kalırsın ‘ne oldu’ diye

Bir soğuk su boşalır ensenden,

Tatlı bir tebessüm sana hediye.

Birden yaşlanmış gibi olursun

Ağırlık çöker iki koluna

Yük altında kalmış gibi solursun,

Çare yok, devam etmelisin yoluna.

Hayat bu, arif olmalı insan.

Hiçbir şey kalıcı değil, yazık.

Eğer insan-i-kamil yolunda isen

Herşey geçer, arta kalan insanlık.', 'Aşkın dudağı kaçtı mı senden Şaşıp kalırsın ‘ne oldu’ diye Bir soğuk su boşalır ensenden, Tatlı bir tebessüm sana hediye. Birden yaşlanmış g...', ARRAY['Türk Edebiyatı','Şiir','Boğazlı Boğa']::text[], 8.5, '{"poet":"Boğazlı Boğa","poet_slug":"bogazli-boga","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/insan-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-bogazli-boga-80icy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zamanı gerçek sanan

Hep sürekli aldanan

Yarattığı alemi

Yılları, saatleri

Zincirmiş gibi gören

Sen ve ben değilmiyiz? 

Bütün mesele,

Zamanı bir ağ gibi örüp

Çözebilmekte.

Sebep-sonuç ilişkisini

Yerelden gene doğru

Kaydırabilmekte.

Kolay değil şüphesiz.

Bunu yapan dervişler

İlahi adaletin

Ruhuna işlemişler

Ve zaman zincirini

Kemirip bitirmişler.', 'Zamanı gerçek sanan Hep sürekli aldanan Yarattığı alemi Yılları, saatleri Zincirmiş gibi gören Sen ve ben değilmiyiz?  Bütün mesele, Zamanı ...', ARRAY['Türk Edebiyatı','Şiir','Boğazlı Boğa']::text[], 8.5, '{"poet":"Boğazlı Boğa","poet_slug":"bogazli-boga","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/zaman-108-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanmayı Unutmuş Deniz Feneri', 'yanmayi-unutmus-deniz-feneri-yavuz-mehmet-erturk-dcsl4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne pişmanlık

Ne yanmışlık

Ne kıpkırmızı kırılmışlık! 

Nazlı akan soğuk sularda 

Ayaklarım donuyor

Buz kütlelerine günbatımını gizliyorum

Kar gece de beyaz

Gündüz de beyaz

Bir tek benim elimde yanmayan kandiller

Karşılıksız sözler savruluyor ayna camlarda

Camlar aynalarda ölüyor

Sözler buz gibi, ağızdan dökülüyor

Güneşim yanmayı ıskalamış, 

Ateşim sönmeyi

Bir ömre yazık oluyor! 

Diyorum, kimseyi gördüremiyorum

Ümitsizliği bir türlü öldüremiyorum

Yüzmeyi unutmuş bir Yunus gibi debeleniyorum

Bu bataklığa kaç okyanus sığar Allahım! 

Listeler asılıyor, ben eleniyorum,

Kıpkızıl akşam, kapkaranlık şafak

Yolunu kaybetmiş bir deniz feneriyim, 

Işık saçmayı unutmuş gözlerim

Sevmeyi unutmuş yüreğim

İşte öyleyim

Güllerin boyun büktüğü çıkmış hatırımdan

Karanfiller yüzünü gölgelemiş

Erguvanda akşam olmuş, 

Şehir düşmüş, şehzade solmuş

Ocakta karamsarlık doğmuş

Ellerimde haram

Yalnızlık dizboyu

Şubatta bayram

26.01.2004

İSTANBUL/YENİBOSNA', 'Ne pişmanlık Ne yanmışlık Ne kıpkırmızı kırılmışlık!  Nazlı akan soğuk sularda  Ayaklarım donuyor Buz kütlelerine günbatımını gizliyorum Kar...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Mehmet Ertürk']::text[], 8.5, '{"poet":"Yavuz Mehmet Ertürk","poet_slug":"yavuz-mehmet-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/yanmayi-unutmus-deniz-feneri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim ve kalbin', 'kalbim-ve-kalbin-i-brahim-sengun-q13tr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Korkma! Bir tanem 

Susma! Sevdiğim 

Çekinme! düğümlenmesin boğazına boşuna

Söyle! İçine dert olmasın

Bırak! ne olacaksa olsun 

Bırak! inceldiği yerden kopsun ipler 

Bırak! zaman her şeyin ilacı 

mutluluğun için her şeye alışırım ben 

sadece bedenimdeki yürek kaldırmıyor

heyecanımı yenemiyor artık! ! ! 

Seviyorsan da sevmiyorsan da söyle can

Yeter ki, kalbime zulmetme, zalim olma 

Biliyor musun? 

Şu an yaşamıyorum zaten 

Niye mi? 

Senin için yanan,

Senin için tutuşan,

Senin için başka yüreklerle vuruşan,

Kalbim! 

Çarpmıyor! atmıyor! Durdu! 

İşte bu yüzden be can, bu yüzden..

Hayır! hayır! 

Korkma bir tanem, korkma! 

Sorumlusu sen değilsin inan 

Ve biliyor musun can? 

her gece Allah’a dualardayım 

Günlerin azaplı olmasın,

Donuk bir yüzün, gülmeyen siman olmasın 

her gece Allah’a  dualardayım can

Senin o güzel kalbin 

Çarpsın! Atsın! Durmasın!', 'Korkma! Bir tanem  Susma! Sevdiğim  Çekinme! düğümlenmesin boğazına boşuna Söyle! İçine dert olmasın Bırak! ne olacaksa olsun  Bırak! inceld...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Şengün']::text[], 8.5, '{"poet":"İbrahim Şengün","poet_slug":"i-brahim-sengun","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/kalbim-ve-kalbin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Adı', 'askin-adi-i-brahim-sengun-s45ip', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nihavent bir peşrev çalarken radyoda 

efkarım aniden debreşti yine ve/

başladı yolculuğum aşk yolunda 

ister arzu eyle ister eyleme ne/

laf dinliyor kalbim,ne de söz geçiyor gönlüme 

kapındayım şu an titriyor heyecandan ellerim,dizlerim 

aheste,aheste vurdum kapına sessizce beklemekteyim varsın/

açılmasın kapı aşkın için amadeyim,

köleyim 

ister arzu eyle ister eyleme 

laf dinlemiyor kalbim,ne de söz geçiyor gönlüme

aşkım; günbatımında denizden esen rüzgar gibi çılgın

şafak vakti yağan çiğ tanesi gibi masum 

kalbi; okyanus derinliklerinde inci tanesi 

ılık bir akşam, pırıl-pırıl gökyüzü

maşallah yarabbi  bu güzellik, kem gözlere nazar mavisi..', 'Nihavent bir peşrev çalarken radyoda  efkarım aniden debreşti yine ve/ başladı yolculuğum aşk yolunda  ister arzu eyle ister eyleme ne/ laf ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Şengün']::text[], 8.5, '{"poet":"İbrahim Şengün","poet_slug":"i-brahim-sengun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/askin-adi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mum Işığı...', 'mum-isigi-i-brahim-ethem-bingul-ebell', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karanlık dünyamın 

Loş odasındayım

Hatıralarım sanki bir mum ışığı

Düşündükçe içim aydınlanıyor

Görüyorum seni..

Uzansam tutabilir miyim ellerini,

Dokunabilir miyim saçlarına,

Duyabilir miyim o güzel kokunu

O kadar canlısın ki sanki karşımda

Tam sarılacak iken yoksun yanımda

Yine karanlık,yine loşluk

Elimde kalan sadece bir mum ışığı

Yine yokluk,yine yalnızlık', 'Karanlık dünyamın  Loş odasındayım Hatıralarım sanki bir mum ışığı Düşündükçe içim aydınlanıyor Görüyorum seni.. Uzansam tutabilir miyim ell...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mum-isigi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sendika', 'sendika-ahmet-aksoy-p7beg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Adını yazacak kadar

……Bir kelebeğin kanatlarına

İncedir işçinin yüreği

Ve serttir düşmanını

……Yıkacak kadar

Haksızlığa uğradığında

Yeterki, düşmanlık 

…….Edenler olduğunda

Emekçilerden oluşan orkestranın

Bir kakofoni olmasın seslenişi', 'Adını yazacak kadar ……Bir kelebeğin kanatlarına İncedir işçinin yüreği Ve serttir düşmanını ……Yıkacak kadar Haksızlığa uğradığında Yeterki, ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sendika-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneme', 'anneme-elif-erkut-brrkj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ufacık bir candım, 

Minik bir gözyaşı süzüldü gözlerden daha ben doğarken. Giderken de gözyaşlarına boğuldu sevenlerimde,

Giden bende… 

Tatlı bir dağ papatyasıydım kırlarda özgürce dolaşan

Apansızca güneşi yüreğinde yaşatan.

Esmekten vazgeçmeyen poyrazdım her esişinde dahada özgürleşen,

Annemin minik yavrusuydum her ağlamasında yanına koşulan 

Sonrada annesinin haini oldum onu hiç düşünmeden bırakıp giden.

Elbebek gülbebektim her istediği verilen, 

Babasının bebeğim diyemediğiydim hep sevgisine muhtaç kalan...

En başarılısı, gözdesiydim tüm ailenin 

Hiç beklenmedik hayaller peşinde..

Hayallerini gerçekleştirmek için ruhlarını karartandım tüm ailenin…

Herkesin sevdiğiydim sevildiğinin farkına varamayan 

Aslında herkeside severdim sevdiğimi gösteremeden, 

Şimdi bir sese muhtaç kaldım en yakınımdan. 

Bir ses buldum rüyalarıma girdi hayali…

Keşke affedebilseydin canım annem beni…', 'Ufacık bir candım,  Minik bir gözyaşı süzüldü gözlerden daha ben doğarken. Giderken de gözyaşlarına boğuldu sevenlerimde, Giden bende…  Tatl...', ARRAY['Türk Edebiyatı','Şiir','Elif Erkut']::text[], 8.5, '{"poet":"Elif Erkut","poet_slug":"elif-erkut","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/anneme-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can', 'can-hifzi-ozbekmez-pjwkp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevda yolunda çileyi 

Beraber çekmedik mi can

Gurbet yoluna hasreti

Beraber ekmedik mi can

Gönülleri bir eyleyip

Gurbet eli yol eyleyip

Sevdaları hal eyleyip

Beraber yanmadık mı can

Kolaymıdır aşık olmak

Hele aradığını bulmak 

Sevda kalesine bayrak

Beraber dikmedik mi can

Latifiyim gönlüm harap

Aşkınla düşmüşüm bitap

Kaderin elinden şarap

Beraber içmedik mi can

2003', 'Sevda yolunda çileyi  Beraber çekmedik mi can Gurbet yoluna hasreti Beraber ekmedik mi can Gönülleri bir eyleyip Gurbet eli yol eyleyip Sevd...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/can-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınlardan Öğrendim Bu Hayatta Ne Öğrendimse', 'kadinlardan-ogrendim-bu-hayatta-ne-ogrendimse-tahsin-ozmen-a0q00', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir kadının gözyaşı...:

Boyun büküşü bir garibin, bir yıldızın kayışı.

.

Kadın solarsa, 

Bir gülün yaprağını dolu vurur, çiçekler solar, çocuklar solar.

Kadın ağlarsa,

Yuvası bozulur bir kuşun, uzaklarda bir deniz ağlar.

Oysa kadın gülerse,

Şeker kokulu umut sarkar yuvaların saçağından, 

En umutsuzu yeniden umuda bağlar.

.

Bir kadının gözyaşı...:

Yedi milyar insanın sığınacağı bir gönülgâhın çöküşü, 

Bir düşün bitişi, bir umudun ölüşü.

Oysa tüm gül goncalarından daha güzeldir bir kadının içten gülüşü.

Avuçlarımdan kumrular uçtuysa,

Yüzümde rengârenk çiçekler açtıysa.

.

Aşk havliyle sırılsıklam sevdimse,

Güneş vurmuş sular gibi güldümse,

Onların eseri bu Dünyada güzel ne gördümse.

.

“K a d ı n l a r d a n ö ğ r e n d i m; 

Bu hayatta ne öğrendimse...!”

2004

* Düşünmek Yaşamın Pasını Silmektir, Karina Yayınevi, Ank,2018', 'Bir kadının gözyaşı...: Boyun büküşü bir garibin, bir yıldızın kayışı. . Kadın solarsa,  Bir gülün yaprağını dolu vurur, çiçekler solar, çoc...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Özmen']::text[], 8.5, '{"poet":"Tahsin Özmen","poet_slug":"tahsin-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/dehset-olurdu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gam Yemem', 'gam-yemem-hifzi-ozbekmez-qt548', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seviyorum dedin ya sen

Artık ölsem de gam yemem

Deli gibi aşığım ben

Artık ölsem de gam yemem

Seni ben çok seviyorum

Hasretinden ölüyorum

Sevdiğini biliyorum

Artık ölsem de gam yemem

Gönlümdeki tek güzelsin

Sen benim için özelsin

Demek seviyorum dersin

Artık ölsem de gam yemem

Sevdiğimsin kıymet bilen

Latifiyle aşka gelen

Benimdir o gönül hanen

Artık ölsem de gam yemem

2003', 'Seviyorum dedin ya sen Artık ölsem de gam yemem Deli gibi aşığım ben Artık ölsem de gam yemem Seni ben çok seviyorum Hasretinden ölüyorum Se...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gam-yemem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahipsizim', 'sahipsizim-hifzi-ozbekmez-2o821', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ağlarken ağlayanım yok

Ciğerim dağlayanım yok

Bana bel bağlayanım yok

Sahipsizim sahipsiz

Halimden de bilmezler

Göz yaşımı silmezler

Yüzüme hiç gülmezler

Sahipsizim sahipsiz

Yoktur soran hal hatır 

Yazan yoktur bir satır

Mutluluk çok uzaktır

Sahipsizim sahipsiz

Latifiyim söylerim

Sensiz aşkı neylerim

Ne kötüymüş kaderim

Sahipsizim sahipsiz

2003', 'Ağlarken ağlayanım yok Ciğerim dağlayanım yok Bana bel bağlayanım yok Sahipsizim sahipsiz Halimden de bilmezler Göz yaşımı silmezler Yüzüme ...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sahipsizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Yarim', 'canim-yarim-hifzi-ozbekmez-f9leg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni çok sevdiğimi bilirmisin canım yarim

Benim için buralara gelirmisin canım yarim

Beni sende rüyalarda ararmısın canım yarim

Bir gün gelip kollarınla sararmısın canım yarim

Bir gün benimle vuslata erermisin canım yarim 

Gönlümde gonca gülleri derermisin canım yarim

Bir gün latifiye aşkla bakarmısın canım yarim

Sevdayın narına sende yakarmısın canım yarim

2003', 'Seni çok sevdiğimi bilirmisin canım yarim Benim için buralara gelirmisin canım yarim Beni sende rüyalarda ararmısın canım yarim Bir gün geli...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/canim-yarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Artık', 'gel-artik-hifzi-ozbekmez-sdy7y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gurbet bana yol oldu

Gel artık canım sevdiğim

Canım perişan oldu

Gel artık canım sevdiğim

Gözlerim hep seni arar

Kollarım hep hayal sarar

Sen ver artık son bir karar

Gel artık canım sevdiğim

Dinmez gözümdeki yaşım

Zehir oldu ekmek aşım

Sevdanla delidir başım

Gel artık canım sevdiğim

Gönlümde hep soldu güller

Çok perişan oldu haller

Kelam söyleyemez diller

Gel artık canım sevdiğim

Hasret vuruyor bağrıma

Sensizlik gider ağrıma

Kulak ver benim çağrıma 

Gel artık canım sevdiğim

Aşığınım çok zordayım

Hem ateşte hem kordayım

Karardı gözüm nerdeyim

Gel artık canım sevdiğim

Sen benimsin benim olsan

Gelip de gönlüme dolsan

Ne olur yanımda kalsan

Gel artık canım sevdiğim

Hıfzının perişan hali

Konuşmuyor sustu dili

Pazartesi yada salı 

Gel artık canım sevdiğim

2003', 'Gurbet bana yol oldu Gel artık canım sevdiğim Canım perişan oldu Gel artık canım sevdiğim Gözlerim hep seni arar Kollarım hep hayal sarar Se...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/gel-artik-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Bekcisi', 'gece-bekcisi-erol-uyanik-1v7iz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Otelde bir gece bekçisi

Bekliyor elleri soğuk geceyi

Üç yldızlı bu otel, parlakmı parlak.

Temiz,bakımlı bembeyaz

Kellesi kopmuş dört kukla

Kan damlamış üstüne...(florida 97)', 'Otelde bir gece bekçisi Bekliyor elleri soğuk geceyi Üç yldızlı bu otel, parlakmı parlak. Temiz,bakımlı bembeyaz Kellesi kopmuş dört kukla K...', ARRAY['Türk Edebiyatı','Şiir','Erol Uyanık']::text[], 8.5, '{"poet":"Erol Uyanık","poet_slug":"erol-uyanik","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gece-bekcisi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanıyorum', 'yaniyorum-hifzi-ozbekmez-0qrq2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seviyorum deli gibi

Sanki mecnun hali gibi

Aşıkların piri gibi

Yanıyorum hasretinden

Aşıkların özü gibi

Ciğerinde közü gibi

Ağustosun yazı gibi

Yanıyorum hasretinden

Keremdeki haller gibi

Aslıdaki güller gibi

Aşk söyleyen diller gibi

Yanıyorum hasretinden

Latifiyim bitti sözüm

Aşkından yanıyor özüm

Kör olsun bu iki gözüm

Yanıyorum hasretinden

2003', 'Seviyorum deli gibi Sanki mecnun hali gibi Aşıkların piri gibi Yanıyorum hasretinden Aşıkların özü gibi Ciğerinde közü gibi Ağustosun yazı g...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yaniyorum-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedamet', 'nedamet-ahmet-agdere-ccras', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nasıl oldu da başlamadık hayata,

İlk aşka atılan ilk adımlarımızla..

Ha öyle ha böyle geçecekti günler

Aldırmayacaktık sahte sevdalara

Liyakatti bu gönüller yarınlara...', 'Nasıl oldu da başlamadık hayata, İlk aşka atılan ilk adımlarımızla.. Ha öyle ha böyle geçecekti günler Aldırmayacaktık sahte sevdalara Liyak...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/nedamet-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arzum...', 'arzum-i-brahim-ethem-bingul-dgej9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bırakıp gittiğim gibi mi herşey

Tenekelere ektiğimiz çiçekler neşeli mi

Bahçedeki nar ağacı küçük mü hala

Ya sen! bıraktığım gibi misin

Gözlerin ışıl ışıl herşeye,heryere

Umutla bakan mısın arzum

Ben aynı ben değilim buralarda

Öyle geri dönüşsüz

Öyle derin ki attığın kesikler bana

Ben beni bile tanımıyorum arzum

Beni tek terk etmeyen senin sevgindi,

Sen değil! 

Benim sana duyduğum sevgim,arzum

Sensiz,seninle yaptığım hiç bir şeyi yapmıyorum

Mehtabı seyretmiyorum

Ağladığım zaman gözyaşımı silmiyorum

Yıldızlara bakmıyorum

Kendi gözlerimi kendimden kaçırıyorum

Bu başlanılmış ama

Sonu hiçbir zaman gelmeyecek

Bir hikaye oldu 

Tek ve ilk arzum', 'Bırakıp gittiğim gibi mi herşey Tenekelere ektiğimiz çiçekler neşeli mi Bahçedeki nar ağacı küçük mü hala Ya sen! bıraktığım gibi misin Gözl...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/arzum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin ki aşk değil', 'senin-ki-ask-degil-kibar-tavasav-timw1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen yıktın umutları

İçimdeki

Bardaktan boşanırcasına coşan dolu dolu tutkuları

Hiç insaf etmedin

Bir sözümün 

Bir gözümün bile değeri yokmuş sende

Bu senin ki ne aşk

Ne sevgi

Nede özlem

Bu senin ki hiç bir şey değil

Bu içinde hiç bir şeyi olmayan seni 

Sevmişim ben ne yazık ki

Ve sana acıyorum

Senin ki seks sadece belki

Oysa benim ki aşk

Sevgi

Adını sen koy

Hissettiklerim  aynı senin olduğun gibi

İçimde benim için çok değerli

Ey sevgili', 'Sen yıktın umutları İçimdeki Bardaktan boşanırcasına coşan dolu dolu tutkuları Hiç insaf etmedin Bir sözümün  Bir gözümün bile değeri yokmuş...', ARRAY['Türk Edebiyatı','Şiir','Kibar Tavasav']::text[], 8.5, '{"poet":"Kibar Tavasav","poet_slug":"kibar-tavasav","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/senin-ki-ask-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece', 'sadece-aynur-uluc-esy4t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu gece yanında olmak istiyorum

Hesaplamadan

Bir formata sokmadan

Beklentiler olmadan

Engelleri takmadan

Korkmadan

Hiçbir şey sormadan

Dokunmak 

İstiyorum.', 'Bu gece yanında olmak istiyorum Hesaplamadan Bir formata sokmadan Beklentiler olmadan Engelleri takmadan Korkmadan Hiçbir şey sormadan Dokun...', ARRAY['Türk Edebiyatı','Şiir','Aynur Uluç']::text[], 8.5, '{"poet":"Aynur Uluç","poet_slug":"aynur-uluc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sadece-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tınısı Burnunda Yürek', 'tinisi-burnunda-yurek-aynur-uluc-e2xv6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beni anlatan resimde

ateşi tutup yükselme olmalı

o renkli burgularda

kaybolmak ile

sıyrılma çabasıyla koyvermenin

zevkinin çarpışması

Kadınlığından memnun oluşa artı 

bir erkek gibi hissetmek merakı

Ritmik atan kalp atışı olmalı

Küçük bir kuşun kanat çırpması

uçmaya başlangıç için

ama bunun agoni safhasındaki 

tipik hareket de olabileceği sanrısı

(19-03-2000)', 'Beni anlatan resimde ateşi tutup yükselme olmalı o renkli burgularda kaybolmak ile sıyrılma çabasıyla koyvermenin zevkinin çarpışması Kadınl...', ARRAY['Türk Edebiyatı','Şiir','Aynur Uluç']::text[], 8.5, '{"poet":"Aynur Uluç","poet_slug":"aynur-uluc","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/tinisi-burnunda-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaktaki Şehir (şiir)', 'uzaktaki-sehir-siir-aynur-uluc-ae93p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Okyanusta biraz ötesi

Özgürlük  simgesiydi

Orada hayat, darağacı 

Ölüm, pamuk bahçesiydi

Dümdüz oldu tümsekler

Dişlerin arasındaydı doğuş

Ansızın başlayan şarkının 

Atmosferinde kar ağacı

Her taraftaydı düşman

Güzellik her anda

Daireler iç içe

Denizse altlarında 

Denk düşerdi

Uzun cümlelere sözcükler

Selülozda  harfler kayardı

Anlatamazdı yine de

Tamamı tek bakışı

Kendine yer aradı kız 

Notalar ezberden akarken

Zamansız çalan ziller

Bölemedi tılsımı

Halı gibi dokumak istiyordu 

Düşleri bedenine

Renklerin boz fırçası

Koynuna motifler çiziyordu

Ayakta taşınan sihirdi yol

Yenilemeyen şekerde saklı 

Tarih nasıl derse desin

Bir ütopyaydı gelecek  şarkı

Ve onun  tadında

Yazılmamış öyküler vardı', 'Okyanusta biraz ötesi Özgürlük  simgesiydi Orada hayat, darağacı  Ölüm, pamuk bahçesiydi Dümdüz oldu tümsekler Dişlerin arasındaydı doğuş An...', ARRAY['Türk Edebiyatı','Şiir','Aynur Uluç']::text[], 8.5, '{"poet":"Aynur Uluç","poet_slug":"aynur-uluc","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/uzaktaki-sehir-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarim..(Mani)', 'yarim-mani-ferit-teksoy-hacmd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgi arsızı yarim

Gönül hırsızı yarim

Aklım,yüreğim sende

Dünya gamsızı yarim

Sevgisi sıcak yarim

Özlemi bıçak yarim

Hayali benimle de

Kendisi kaçak yarim

Yarenim,tatlım,yarim

Peteğim,balım yarim

Sen olmayınca inan

Bir yanım yarım yarim

Güzelim,gülüm yarim

Sensizlik zulüm yarim

Varlığında tesellim

Yokluğun ölüm yarim

Koç idim yıktın yarim

Boynumu sıktın yarim

Bak..nefesim kesildi

Gülerek baktın yarim

Söyle bir zalim yarim

Ne olur halim yarim? 

Sende uzat elini

Havada elim yarim

Fiziği güzel yarim

Sevgisi özel yarim

Seni çok özlüyorum

Gerisi gazel yarim

Ferit''e bebek yarim

Sevgisi öbek yarim

Eğer birgün gel dersen

Atarım göbek yarim', 'Sevgi arsızı yarim Gönül hırsızı yarim Aklım,yüreğim sende Dünya gamsızı yarim Sevgisi sıcak yarim Özlemi bıçak yarim Hayali benimle de Kend...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/yarim-mani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kış Güneşi', 'kis-gunesi-aynur-uluc-3xe7b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kış güneşisin gerçekten

hani ansızın ayazın ortasında çıkar

sıcacık eder insanın içini

yine yok olur sonra ama

 o sıcaklığı taşımaya sen

devam edersin bir süre daha

Aynur Uluç

Simge Seçki / 2006-Sayı 26', 'kış güneşisin gerçekten hani ansızın ayazın ortasında çıkar sıcacık eder insanın içini yine yok olur sonra ama  o sıcaklığı taşımaya sen dev...', ARRAY['Türk Edebiyatı','Şiir','Aynur Uluç']::text[], 8.5, '{"poet":"Aynur Uluç","poet_slug":"aynur-uluc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kis-gunesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Es Un Guacho De Mierda', 'es-un-guacho-de-mierda-bulent-bora-baltaci-cmv94', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Esmeyince esmiyor işte rüzgar

Sesim sesine değecek diye...

Şehrinde ağlıyorum işte gülüm

Mavi gömleğim,kitaplarım ve ben

Ağlıyorum işte bir ozanın türkülerinde 

Güvenparkın beton banklarında

Gözlerinde ağlasam diyorum 

Ah... Olsanda....

Şiir kıvamında

Türkü berraklığında

Usulca dökülen gözyaşlarım

Dalından kırdığım has güle su olsun istiyorum

Sağ yanım yine titriyor

Atış talimlerinde hedef seçiyorum kendimi

Tüfeğimin namlusu nişan tutumuyor...

Hep bildik şeyler

Diyorum ki kimsenin bilmediği bir yerde

Bilinmedik bir halde

Örneğin saç sakal birbirine karışık

Gözlerinden başka bir şey aramadan

Kocaman yüreğimdeki; Kocaman sevgileri, nefretleri

Dağıtsam ülkemin iyi ve kötü insanlarına

Ve yine kocaman yalnızlıkları saklasam kendime

Fehmi Dayının doğulu şivesinde 

Kendime ait hüzün tadında bir şeyler bulsam

Velhasıl bu yalnızlık 

Bir orospunun med cezir kıvamında uzanıp doğrulmasıdır

Bizden uzak... Hep uzak olsun diyorum...

Ernosto Che Guavera''nın iflah olmaz astımı vardır herşeye rağmen

Benimde sensizliğim var

Diyorum ki utanarak sıkılarak

Gel barışalım

Geç kalmışlığımı vurma yüzüme

Zaten aynalara bakamıyorum

Gel artık

Bütün dağlarını ülkemin 

Yakıp yıkmadan...

Metropol caddelerinde gezinen 

Bir ayyaş kadar günahkarım artık

Ey Tanrı gönder yağmurlarını yıkandır beni

Zaten herşey yağmurdan oldu

Vakitsiz ıslamasaydın beni

Gözlerim kör olmazdı

Kırmazdım kullarını...

Yazgımızda şarkılar olsun diyorum

Diyorum ki notalarında sen ve ben olalım

Diyorum ki gel yakalım bu şehri

Aykırı zaman akislerinde 

Çiçekleri seyre dalalım

Diyorum ki katliamına fail olalım

Katline ferman

Puştlukların...', 'Esmeyince esmiyor işte rüzgar Sesim sesine değecek diye... Şehrinde ağlıyorum işte gülüm Mavi gömleğim,kitaplarım ve ben Ağlıyorum işte bir ...', ARRAY['Türk Edebiyatı','Şiir','Bülent Bora Baltacı']::text[], 8.5, '{"poet":"Bülent Bora Baltacı","poet_slug":"bulent-bora-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/es-un-guacho-de-mierda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Ayrı Yaşamak', 'senden-ayri-yasamak-nazim-yildiz-81x9v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Senden ayrı yaşamak yaşamak değil

Bakma öyle arasıra tebessüm ettiğime

Sensizde nefes alabiliyor sensizde görebiliyorum

Lakin sensizliğe dayanamıyor yüreğim

Sana hasret olan ben değilim canım

Bir çift göz sana hasret ağlayan

Ben değilim günboyu sensizliğe çıldıran

Avuçlarım var avuçlarına hasret terleyen

Yoksa ben yıllardır yalnızlığa alıştım

Benim için gündüzün geceden farkı olmadıki

Oysa gözlerim alışamadı senin yokluğuna

Nasıl hasretse geceler mehtaba sana öylesine hasretim anla

Seni gecelerboyu özleyen ben değilim canım

Sana böylesine mısralar karalayan ben değilim

Ahh... o yüreğim varya o yüreğim

Sana hasret kanayan bir bilsen.', 'Senden ayrı yaşamak yaşamak değil Bakma öyle arasıra tebessüm ettiğime Sensizde nefes alabiliyor sensizde görebiliyorum Lakin sensizliğe day...', ARRAY['Türk Edebiyatı','Şiir','Nazım Yıldız']::text[], 8.5, '{"poet":"Nazım Yıldız","poet_slug":"nazim-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senden-ayri-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Selleri', 'zaman-selleri-sair-doga-t9pak', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'soğuktu

her yer soğuk ve sisli

gözlerimiz buluştuğunda

ısınmıştı yeryüzü

zaman durmuş

gözlerimiz konuşmuştu

bir tek

dudaklarımızdı suskun kalan

kilitli dudaklar

ve

bir şimşek çaktı

büyü bozuldu

aktı zaman seller gibi

içimde

unutamadığım hatıralar kaldı

çakan şimşeğin

ve 

akan zaman sellerinin ardından', 'soğuktu her yer soğuk ve sisli gözlerimiz buluştuğunda ısınmıştı yeryüzü zaman durmuş gözlerimiz konuşmuştu bir tek dudaklarımızdı suskun ka...', ARRAY['Türk Edebiyatı','Şiir','Şair Doğa']::text[], 8.5, '{"poet":"Şair Doğa","poet_slug":"sair-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/zaman-selleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kulağını Şehrin Kalbine Yasla', 'kulagini-sehrin-kalbine-yasla-tansel-yucelen-5rr1m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir an

içini kurşuni bir yalnızlık alıp

seni senle tek başına bırakıp

uzaklara yelken açarsa

kulağını şehrin kalbine yasla

ve beni dinle

tam o an

götürürse zaman alıp seni

gözlerimde bırakıp gözlerini

düşlerinin aktığı o uçuk diyara

kulağını şehrin kalbine yasla

ve beni dinle

işte o an

benim yüreğimi

yüreğinde duyacaksın', 'bir an içini kurşuni bir yalnızlık alıp seni senle tek başına bırakıp uzaklara yelken açarsa kulağını şehrin kalbine yasla ve beni dinle tam...', ARRAY['Türk Edebiyatı','Şiir','Tansel Yücelen']::text[], 8.5, '{"poet":"Tansel Yücelen","poet_slug":"tansel-yucelen","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kulagini-sehrin-kalbine-yasla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başkent''ten Kalkan Şark Ekspresi', 'baskent-ten-kalkan-sark-ekspresi-kibar-tavasav-8qdlh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hasret... 

Salmışım yine kendimi kendime 

Sabahın kuşluk vakti 

Sıfır yedi düdüğüyle 

Başkentten kalkan şark ekspresi 

Çift katarlı 

Yirmi dört vagon, otuz iki kompartıman 

Topla yolcularını, getir bana 

Sevdiklerimi getir, 

Sevenlerimi 

Ben çok ıraktayım 

Dolan yurdumu bir baştan 

Badem gözlü anamı getir bana, böreğini 

Çakmak bakışlı, mavi gözlü babamı 

Arkadaşlarımı getir, 

Dostlarımı 

Hamsi getir bana, simit getir, çay getir 

Fındık getir, kavun getir,... 

Bir vagonda yüklü, yüklü özlem getir bana 

Gözlerimin yeşil narından süzülen kırmızı yaş 

Poyraz esen Anadolu rüzgarı 

Oy deli kasırga 

Ceddim, vatanım, memleketim 

Ben dağların sınır kartalı 

Ben özlem yüklü şair 

Ben yalnızlıklar kralı 

Artık özledim, çok özledim boğazı 

İstanbul’u getir bana 

Kenarında denizinin balık yediğim restaurantları 

Kucaklayayım Afyonu, Manisa’yı, Bursa’yı 

Ey Anadolu''yu karış, karış turlayan rüzgar 

Ey deli ozanın esen kaynağı 

Ey yalnızların yoldaşı 

Ey serhat! ... 

Bırak eseyim sabah serinliğinde ılgıt, ılgıt 

Coşayım Nazım gibi dizelerde zılgıt, zılgıt 

İlhamın perisi 

Gönül dağım 

Yosmam 

Kucak, kucak deli gönlüme tüküren hasret 

Dumanında çıplak ayak koşuşturduğum efkarlı sigaram 

Gönül yaram 

Yık ta geç içimi 

Ağla da geç gözlerim 

Yıkılsın eller 

Tutuşsun diller 

Çöksün dünya 

Oyyy yangınım, dizeler 

Parçala param parça hasret 

Yatır yerlere 

Sal dağlara 

Dağ, dağ içimde özlem 

Dağ, dağ yangınlar 

Dağ, dağ gel üstüme efkar 

Yok olsun yalnızlığım 

Ahhh dağ, dağ 

Oy Başkentten kalkan şark ekspresi 

Yükle Munzur u, Gediz i, Meriç i, Trakya yı 

Getir Eskişehir i, Sakarya yı, Ankara yı 

Ekin toplayan 

Harman saran 

Alnından ter damlayan köylümü getir 

Emekçi işçimi 

Mazlum memurumu 

Cefakar serbest çalışanımı 

Çukurova dan yükl,ü yüklü pamukları 

Bağlarda üzüm hasadı bozanları 

Tütün kıranları, 

Tekirdağ rakısını 

Doldur bir vagona 

Antep in fıstığını 

Çorumun leblebisini 

Aydının efesini 

Isparta’nın mis kokulu güllerini doldur 

Burdurun göllerini 

Egenin denizini 

Ankara’nın zeybeğini 

Özledim ben İzmir’in köftesini 

Ormanları 

Gürül, gürül akan ırmakları 

Uçsuz bucaksız ovaları 

Antalya’nın kumsalını, plajları 

Uludağ’a yağan karı 

Koyun getir 

Kuzu getir 

Süt getir 

Getir bana Anadolu’nun her karış toprağını 

Çekeyim içime duman, duman 

Daha da doymadım 

Zonguldağın kömürünü getir bir vagonda yer altından 

Bu sabah kestiğim, beş beyaz sakalımı koydum bir kutuya 

Artacak şark ekspresi gelinceye kadar 

Çıktığım her sabaha 

Her beyaz sakalımın bir telinde 

Yurdumun bir taşı 

Dostlarımın yürekli gözleri 

Alnımın teri 

Yiğit gönlümün izi var 

Oyyy sevdaya tutsak 

Haddini bilmez Kibar 

Serhat’ın torunu 

Yalnızlıklar ülkesinin yaramaz çocuğu 

Şiire can veren abdal 

Beş kuruşsuz gönlü zengin, şiir yüklü adam 

Mutluluğun gölge prensi 

Tutma sal kendini 

Koşsun efkar ardın sıra 

Ey! 

Başkentten kalkan şark ekspresi 

Dostlarımı getir bana bir kompartımanda 

Kilim, kilim dokuyayım gönlüme, 

Sevda yüklü dost gözleri getir 

Getir bütün Anadolu’yu 

İsmini yazamadığım getir bütün dostlarımı 

Mor çiçekli dağların 

Doruğunda süzülen bir sınır kartalıyım ben 

Soğuk akşamlarda 

Yağmurun ortasında 

Çiğ düşmüş sabahlarda 

Diz çöküp aman diler geceler, karanlıklar ayaklarıma 

Düşerim cemre gibi 

Havaya 

Suya 

Toprağa 

Düşerim hainlerin korkulu bakışlarına 

Es rüzgar esebildiğin kadar 

Dostlarım geliyor 

Sevda yürekli insanlar geliyor 

Sevgilim geliyor 

Canlarım geliyor 

Şark ekspresi 

Sabah sıfır yedi düdüğüyle Başkent''ten kalkıyor 

Doldur bir kompartımana 

Mehmet Akif’i, Halide Edibi, Mevlana’yı, Yunusu 

Doldur Karacaoğlan’ı, Abdalı, Dadaloğlu’nu, Veysel’i 

Olsun yanındaki kompartımanda 

Kılıçaslan, Fatih, Yavuz Selim, Kanuni Süleyman 

Kükreyin ey dağlar 

Çökün üstüme 

Gelin üstüme 

Kaç yazar be 

Diğer kompartımanda benim, 

Elinden silahı hiç düşmemiş 

Vatan toprağını savunurken 

Al kanını 

Canını 

Ay yıldızlı bayrağım uğruna feda etmiş 

Kahraman şehit Mehmetlerim ve yanında çocukları var 

Ey militan nereye kaçarsan kaç 

Bu dağlar sana dar 

Peşindeyim senin Cehenneme kadar 

Geliyor diğer kompartımanda 

İsmet paşa, Kazım paşa, Fevzi paşa 

Mehmedim’e kurşun sıkan 

Hain aponun eli kanlı, satılmış dürzüleri 

Şarkıcı, yazar, şair adı altında şakşakçı 

Sözde özgürlük savaşçısı olduğunu iddia eden 

Her fırsatında Şehit kanı içip, az gelen 

Artması için daha da ırkçılık pompalayıp 

Kin kusan 

Duygu sömürüleriyle paralara boğulup 

Sefahat süren satılmış yürekler 

Onlarında yanında din sömürücüleri 

Korkun 

Son kompartımanda 

Sana özgürlük sunan 

Seni böyle insan yerine koyup 

Bak özgürce vatan hainliği olsa da konuşturan 

Alçaklara 

Hainlere 

Yedi düvele meydan okuyan 

Gümbür, gümbür mehter marşıyla 

Mustafa Kemal geliyor be 

Karlı dağların ardından 

Bembeyaz bir kıratın üstünde 

Mustafa Kemal geliyor 

Yıkılın 

Başkentten kalkan şark ekspresiyle 

Anadolu geliyor 

Mustafa Kemal ve ordusunun ardından 

Sevgi seli olup 

Rüzgar, rüzgar BÜYÜK TÜRK ULUSU geliyor 

Hainlerin, satılmışların, kahpelerin 

Özgürken şımarıp da sözde özgürlük arayanların 

Din sömürücülerinin, şarlatan soytarıların 

Tokat, tokat yüzlerine inmeye geliyorlar 

Mustafa Kemal geliyor yıldızlardan basamak, basamak inerek 

Korkusuzluk aşılayan 

Sevgi yoğurulmuş mangal gibi 

Koskoca yüreği geliyor bana 

Yalnızsam bile, 

O kadar da yalnız değilim burada 

Hepsi yanımda 

Sizi bu güçle ben buldozer gibi ezerim 

Hiç durmayın karşımda 

Yıkılın 

Yıkılsın hain eller 

Ağlama eylül 

Bembeyaz gelinlikler içinde 

Bir gelin kadar güzel vatanımın 

Bir teline bir şey gelmesindense 

Ben öleyim, 

Öleyim bu gece 

Dağlar kadar umutlarım var 

Sevdam var 

İçimden şiddetle haykıran 

Göğsüme çelikten bir bıçakla kazıdığım 

Vatan sevgim var 

Dost sevgim 

Gönül sevgim 

Dağ, dağ gönlüm 

Dağ, dağ içim yüreğim 

Dağ, dağ sevgim 

Oy yıkılsın eller 

Hani nerede adına militan denen soytarı hainler 

Nerede alçaklar nerede 

Kaçmayın 

Ben geliyorum 

Türk ordusu geliyor 

Oy 

Oy 

Oy 

İşte geliyor sabahın kuşluk vakti 

Sıfır yedi düdüğüyle 

Başkentten kalkan 

Anıtkabirden kalkan 

İçinde Mustafa Kemali taşıyan şark ekspresi', 'Hasret...  Salmışım yine kendimi kendime  Sabahın kuşluk vakti  Sıfır yedi düdüğüyle  Başkentten kalkan şark ekspresi  Çift katarlı  Yirmi d...', ARRAY['Türk Edebiyatı','Şiir','Kibar Tavasav']::text[], 8.5, '{"poet":"Kibar Tavasav","poet_slug":"kibar-tavasav","theme":"Türk Şiiri","is_hero":false,"total_lines":227,"source_url":"https://www.antoloji.com/baskent-ten-kalkan-sark-ekspresi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Bu Yürek Sevdaya Düşsün İstememiştim', 'ben-bu-yurek-sevdaya-dussun-i-stememistim-mehmet-ali-can-y3kur', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben yüreğim sevdaya düşsün istememiştim

Meğer bu kalp ağrısı bayram hediyesiymiş

Bahar aylarına rastlayan bir Ramazan Bayramıydı.

Evinizi henüz yeni öğrenmiştim.

Birkaç sokak ötemizdeymişsiniz.

Bir iki kez geçtim, görürüm diye,

Seni, evinin içini ve aileni

Kapınızın ardı nasıl, 

bahçeniz, avlunuz, odalarınız…

merak ediyordum,

anneni, babanı, kardeşlerini…

Belki çoçukçaydı, ama meraktı.

Sen benim yüzüme gülen ilk kızdın,

Sen gözlerimin içine bakan ilk…

Sen varlığımın farkına varan ilk…

Bayram kaçırılmaz fırsattı

Ellerinden şeker, kolonya almak,

Annenle, babanla, kardeşlerinle

Tanışmak ve konuşmak istemiştim

Kapınızdan içeriye girince, önce seni gördüm

Zarif ve ince…

İlk kez seni önlüksüz görüyordum

Meğer okul önlüğü nasıl gizlermiş seni

Uzun, düz, kırmızı eteğin,

Sırtında hırkan, içinde gömleğin,

Örgülerinden kurtulmuş,

Omuzlarına tel tel düşen saçların,

Elinde tepsi, 

Üstünde şekerlik ve kolonya şişesi

Karşımdaydın, baktın ve gülümsedin.

Ne avludaki inciri, ne bahçedeki gülleri,

Sadece gülen yüzünü, tepsi tutan ellerini

Anne, babana çevrilen gözlerini görebildim

“Bayramınız kutlu olsun” demiş miydim, bilmiyorum

Şekerinden, kolonyandan almış mıydım, bilmiyorum

Bir ceylan yüreği gibi ürpermiştim, biliyorum

Belki çocukçaydı, ama tatlıydı

İçimi ısıtıyordu varlığın

Yüzün, gözün, sesin bir bambaşkaydı

Sana karşı bütün hissettiklerim

Her erkek çocuğunun kızlara duyduğu sıradan ilgi,

Gelip geçici bir heves olmalı,

Ama asla bir aşk olmamalıydı.

Varlığın varlığım için bir ön şart

Haline gelmemeli,

Bağlanmamalıydım, yaşım küçüktü

Yolum uzun, hedeflerim büyüktü

Sadece bayramını kutlamak istemiştim

Ben bu yürek sevdaya düşsün istememiştim

Kapınıza yönelten aşkın çağrısı imiş

Bana bayram hediyen bir kalp ağrısı imiş

“Benim sınıf arkadaşım” diyerek tanıttın anne, babana

Sonrasını ise onlar sordular

“Eviniz buralarda mı”, “annen, baban kim” gibi…

Ne cevaplar verdim, bilmem, inan ki

Ayaklarım yerde değildi sanki

Beni sevmişlerdi, hissediyordum

Söylenen her kelimeyle birlikte

Kalbimi kalbine iğneliyordum

Biraz zaman geçince etrafıma bakındım

Avluda kapı yanında duran iki incire,

Dama doğru uzanan asmalara,

Bahçede boy veren üç gül dalına,

Yaşadığın evin her tarafına,

Sana tutulduğum gibi tutuldum.

Ya nefesin onlara bu tılsımı, güzelliği vermişti

Ya da benim sana bakan gözlerim…

Kapınızdan gitmek istemiyordum

İçimde sonsuz bir huzur, mutluluk

Bu ilk hissettiklerimin hoşluğu

Yanında bulunmanın sarhoşluğu

Birazdan bitecekti, biliyordum

Istırabın dışarda durduğunu

Sensizlikte beni bulacağını

Biliyordum, gitmek istemiyordum

Ne etsem ne yapsam bilemiyordum

Söylenecek sözler de tükenmişti

Artık kalkıp gitmek gerekiyordu

Bu kapıdan ayrılınca bir daha

Böyle kolay girebilecek miydim

Her istediğimde seni böylece

Evinizde görebilecek miydim

“Hoşça kalın” demiş miydim inan ki bilmiyorum

Elinizi sıkmış mıydım onu da bilmiyorum

Adımlarım değişmişti, bunu hatırlıyorum

Bundan böyle gelebileyim diye

Çekingenliğimi, korkularımı

Kapınızın eşiğine bıraktım

Bir de yüreğimi gül dallarına

Sana müptelalığım

Kapından uzaklaştıkça çoğaldı

Artık varlığın varlığımın vazgeçilmez şartıydı

Artık kalbimde ağrı, göğsümde sızı vardı

Yaşım küçük, hedefimse büyüktü,

Sevecektim ve sevdirecektim

Sadece bayramını kutlamak istemiştim

Ben bu yürek sevdaya düşsün istememiştim

Kapınıza yönelten aşkın çağrısı imiş

Bana bayram hediyen bir kalp ağrısı imiş', 'Ben yüreğim sevdaya düşsün istememiştim Meğer bu kalp ağrısı bayram hediyesiymiş Bahar aylarına rastlayan bir Ramazan Bayramıydı. Evinizi he...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Can']::text[], 8.5, '{"poet":"Mehmet Ali Can","poet_slug":"mehmet-ali-can","theme":"Türk Şiiri","is_hero":false,"total_lines":99,"source_url":"https://www.antoloji.com/ben-bu-yurek-sevdaya-dussun-istememistim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlamak', 'aglamak-taciser-kaygisiz-ukvo0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bebek olup ağlamak,

Gelin olup ağlamak,

Anne olup ağlamak.

VCe bir gün geride kalanları ağlatmak.

Çare yok,var işte.

Oşekildeibu şekilde,bir şekilde,

Ağlamak ve ağlatmak.', 'Bebek olup ağlamak, Gelin olup ağlamak, Anne olup ağlamak. VCe bir gün geride kalanları ağlatmak. Çare yok,var işte. Oşekildeibu şekilde,bir...', ARRAY['Türk Edebiyatı','Şiir','Taciser Kaygısız']::text[], 8.5, '{"poet":"Taciser Kaygısız","poet_slug":"taciser-kaygisiz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/aglamak-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarihin Önemini Bilirmisin', 'tarihin-onemini-bilirmisin-huseyin-cayikli-lb0jp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'tarihin önemi yoktu aslında.geçmişti geçmişte kalan hatıralarım ve kırık dökük sedef kakmalı aynalarım.hayata dair irdeledim konuları aşka da yaz dediler yazasım yoktu aslında.bitkindim yorgundum ruhumu sevda çıkmazına vuran bir kadına satmış gibi serkeştim.seslenişlerimi kıyı balıkçıl kuşları akşam sefaları ve birde daimi müşterisi olduğum rakı kadehleriydi neden olan sabahları beraber kapattığım meyhanelerin kimliksel biyografisiydi.Aşka dair yaz dediler bir tarihten önce bu tarihti.yıkılmıştım dökük bir viranenin arkasından baskılarında sıkılmıs bir şehir gibi damıttım acılarımı sıkısmıs yerde kalan yıllarıma.Aska dair yazdım...kadın gittmişti aşk bitmişti.yaşama dairdir tiyatro sahneleri kadın ve adam vazgeçilmez karakterleri.sevişmek ne kadar basitti.yargılanacağım akşamdı günahlarımı şeytana satma vaktiydi.kutsanmış suda yıkanacaktım.oysa bütün dinlerin lugatından afaroz edilmiştim.dinsiz gibi yaşamaktı sensiz.dini olmayan bir insan gibi felsefe aşklarıydı seni bana taşıyan taşaroncu sevdasıydı yanımda ki su.ne utopyalarımdan vazgeçebilirdim nede yardan.oysa bütün yarlar sere verilmedi mi? söyle şimdi kim kimi kandırabilir sevda çıkmazında.sen mi ben mi? endişeliyiz hayata.daha ne yazayım bilmem ki oysa iki yıl evvel bu tarihte ne diyordum şimdi ne diyorum.bir kadın buluyorum yada o beni buluyor ve tarihin anlamsal bütün yüklerini sedef kakmalı bir sandığa kapatıp ömür boyu açmamak üzere kilitliyor.

şimdi seni düşünüyorum hangi paragrafa yazmalıyım.', 'tarihin önemi yoktu aslında.geçmişti geçmişte kalan hatıralarım ve kırık dökük sedef kakmalı aynalarım.hayata dair irdeledim konuları aşka d...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/tarihin-onemini-bilirmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
