INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adım Adım', 'adim-adim-gencay-coskun-sktlu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir güne uzak

Bin yıla yakın 

Adım 

Adım 

Yalnızlığım 

Her 

Adımda 

Yakaladığım 

Yalnız senin 

Varlığın 

Ne zaman yalnız kalsam 

Seni 

Yalnız 

Seni düşünürüm 

Senin olmadığın 

Bir an 

Senin dolmadığın

Tek bir hücrem 

Hiç olmadı 

Hep içimi sana 

Dışımı dünyaya dökerim 

Usul usul geldim 

Usul usul giderim 

Gittiğim yerde 

Ben ne zaman 

Her hangi bir yere gitsem 

Senin orada olduğunu bilirim 

Adım 

Adım 

Sana yolum 

Damla 

Damla

Sevgim 

Yudum 

Yudum 

İçtiğim 

Özüm

Gözüm 

Sevdiğim', 'Bir güne uzak Bin yıla yakın  Adım  Adım  Yalnızlığım  Her  Adımda  Yakaladığım  Yalnız senin  Varlığın  Ne zaman yalnız kalsam  Seni  Yalnı...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/adim-adim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geliş-Gidiş', 'gelis-gidis-i-lyas-ozkan-2nc4p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Safrâni, görüyorsun; hep gidiyor bu âleme gelenler 

Elbet, sen de birgün, vedâ edip gideceksin

 Aldatmasın seni, hep kalacakmışçasına eğlenenler 

Gidildiğini, tek, gitmenle göstereceksin...

10.05.2000

 Çarşamba', 'Safrâni, görüyorsun; hep gidiyor bu âleme gelenler  Elbet, sen de birgün, vedâ edip gideceksin  Aldatmasın seni, hep kalacakmışçasına eğlene...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özkan']::text[], 8.5, '{"poet":"İlyas Özkan","poet_slug":"i-lyas-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gelis-gidis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak', 'birak-i-lyas-ozkan-otost', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bırak tereddüdü, bırak gafleti.. Rabb''den gelen emirler 

Birer atâyâdır, Safrâni, öp-koy başına

Bırak ma''siyeti, bırak isyanı da O''na râm oluver

Yoksa mahzun olursun, bakmazlar gözyaşına... 

27.04.2000 

Perşembe', 'Bırak tereddüdü, bırak gafleti.. Rabb''den gelen emirler  Birer atâyâdır, Safrâni, öp-koy başına Bırak ma''siyeti, bırak isyanı da O''na râm ol...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özkan']::text[], 8.5, '{"poet":"İlyas Özkan","poet_slug":"i-lyas-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/birak-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
