INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şehir', 'bu-sehir-fatime-gokcen-82hx9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ben bu şehrin yüreğine yasladım başımı

ben bu şehre ağladım her gün batımı

ben bu şehre sevdalandım yandım

birtek bu şehre haykırdım ahımı,efganımı

ateş var bu şehirde..aşk var kızıla boyanmış

her biri düştümü bir yare,biteviye yakarmış

yara açar,acıtır bilirim ama

ibrahimce dalmak başkaymış

göğe doğru bir dilek kanatlanır avucumdan

bu şehir ıslanır meleklerin gözyaşından

bir haber var,hüzün kokulu sonbahardan

vuslat mı,hasret mi heyhat! aşk sızar damarlarımdan...', 'ben bu şehrin yüreğine yasladım başımı ben bu şehre ağladım her gün batımı ben bu şehre sevdalandım yandım birtek bu şehre haykırdım ahımı,e...', ARRAY['Türk Edebiyatı','Şiir','Fatime Gökçen']::text[], 8.5, '{"poet":"Fatime Gökçen","poet_slug":"fatime-gokcen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bu-sehir-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Silinmez Yerde', 'silinmez-yerde-hasan-huseyin-ozak-vl76x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dün ismini fısıldıyordu, denizle rüzgar

Bulutlar resmini yapıyordu gökyüzünde

Senin için gülüyordu küçük çocuklar

Senin için parlıyordu gökte yıldızlar

Dün deniz daha maviydi seni görünce

İnsanlar daha mutlu, cıvıl cıvıldı

Kuşlar daha canlı uçuyordu gökte

Martılar sarhoş gibiydi, çılgın denizde

Dün daha parlaktı güneş tepede

Ağaçlar yeşermişti bahar gelmeden

Dört mevsim toplanmış, hepside bir yerde

İsmini kazıyordu silinmez yerde', 'Dün ismini fısıldıyordu, denizle rüzgar Bulutlar resmini yapıyordu gökyüzünde Senin için gülüyordu küçük çocuklar Senin için parlıyordu gökt...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özak']::text[], 8.5, '{"poet":"Hasan Hüseyin Özak","poet_slug":"hasan-huseyin-ozak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/silinmez-yerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Dem', 'son-dem-hasan-huseyin-ozak-4crvi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölüm dostmu, düşmanmı, tam bunu düşünürken

Bir an geçti önümden, tuttum entarisini

Kurtulmak için benden, korkumu kamçılarken

Bırakmadım öylece, tuttum son nefesimi

Korkularım birer birer benden kaçıp giderken

Öldürüyor şeytanı, ölüm bilmecesini

Kat kat delerek göğü, ruhum arşa giderken

Son deminde görüyor fikir işkencesini', 'Ölüm dostmu, düşmanmı, tam bunu düşünürken Bir an geçti önümden, tuttum entarisini Kurtulmak için benden, korkumu kamçılarken Bırakmadım öyl...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özak']::text[], 8.5, '{"poet":"Hasan Hüseyin Özak","poet_slug":"hasan-huseyin-ozak","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/son-dem-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düden Şelalesi', 'duden-selalesi-sadik-softa-pf2r9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kelimeler akmaya başladı; 

Mısra mısra doldu su misali.

Anlatmaya yetmedi meramımı,

Düdende biten; su misali.

Asırlar ötesine kök salmış; 

Sular dile gelmiş kuş misali.

Kuşluk vaktinde bitirip serinliği; 

Öğle sıcağında öfke salmış; 

Serinliğe kızgın misali.

Ben gelmeden önce çağlarmış Düden; 

Gözesinden çıktığında gözde misali.

Döne döne akıp ulu çınarlar gölgesinden; 

Denize koşarmış köpüklü dalgaları; 

Hasretten titreyen ceylan misali.

Çınarlar rüzgar kesilirmiş rüzgar delişmenliğinde; 

Güzeller gezermiş ürkek ürkek ahu misali.

Gülüşünü dinlermiş güzellerin, şuh dalgalar; 

Düdende çağlar ve coşarmış an be an sular; 

Kükrermiş Şelale misali.

Uzun bir koşunun ardından,

Yorulmuş, sarı yapraklar arasından,

Sesi cılız, kendi cılız, yorgun misali.

Ağaçlar kulak kesilmiş, boş, nafile; 

Tedirginlik bekler şelaleyi ki sesi çıkmaz; 

Dilsiz sanki Düden; ahraz misali.

		              

Antalya - 03.Ağustos.2001', 'Kelimeler akmaya başladı;  Mısra mısra doldu su misali. Anlatmaya yetmedi meramımı, Düdende biten; su misali. Asırlar ötesine kök salmış;  S...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/duden-selalesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Halay', 'halay-sadik-softa-kz1bb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dizil hilal şekli, yarım ay olsun; 

El belden dolansın, omuz omuza.

Naralansın davul-zurna hay olsun; 

Kollar daldan dala, omuz omuza.

	

Ağırlama ağır ağır başlasın.

Zurna fettan, davul sağır başlasın.

Halay başı, halay “bağır” başlasın.

El belden dolansın omuz omuza.

Yerlemeye geçsin, hızlansın hava.

Vursun davul-zurna sızlansın hava.

Üçayağa biraz nazlansın hava.

El elden sarılsın, omuz omuza.

Üçayağa gelsin sıra sekilsin.

Baştan sona halay hızlı çekilsin.

Davul zurna ile yer gök yıkılsın.

El daldan birleşsin, omuz omuza', 'Dizil hilal şekli, yarım ay olsun;  El belden dolansın, omuz omuza. Naralansın davul-zurna hay olsun;  Kollar daldan dala, omuz omuza. 	 Ağı...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/halay-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğul', 'ogul-sadik-softa-48vkb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Azgına cehennem, mazluma cennet

Herkes aradığın bulacak elbet,

Yine de af vardır, yoktur müebbet,

İnana yol bir şaşırma oğul.

Çareler tükenmez, aflar tükenmez,

Nâmert olma, hiç nâmertler tükenmez

Mertlik özde yaşar, mertler tükenmez,

Merdi, nâmert ile bir tutma oğul.

Bayrağına sarıl, sarsın bayraklar,

Toprağa sahip çık, kutsal topraklar,

Köke bağlı, dalda duran yapraklar,

Kökün mazidedir, unutma oğul.

İyiliği şiar edin kendine,

Kötüden uzak dur düşme fendine,

Boş hayaller kurup kendi kendine,

Boşuna hiç vakit tüketme oğul.

		

Çankırı - 21 Mayıs 2001', 'Azgına cehennem, mazluma cennet Herkes aradığın bulacak elbet, Yine de af vardır, yoktur müebbet, İnana yol bir şaşırma oğul. Çareler tükenm...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ogul-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Çare', 'ne-care-hasan-huseyin-ozak-eas92', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ölüm sonmu, başlangıçmı

ekşimi, acımı, tatlımı,

bunu hiç bilemeyeceğim.

Bir gün gelip bilsem bile,

ne çare! 

Size değil,

böceklere söyleyeceğim', 'Ölüm sonmu, başlangıçmı ekşimi, acımı, tatlımı, bunu hiç bilemeyeceğim. Bir gün gelip bilsem bile, ne çare!  Size değil, böceklere söyleyece...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özak']::text[], 8.5, '{"poet":"Hasan Hüseyin Özak","poet_slug":"hasan-huseyin-ozak","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ne-care-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bozkır Üçlemesi', 'bozkir-uclemesi-sadik-softa-p9jjv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'BOZKIR ÜÇLEMESİ

Bir bozkır üçlemesinde; 

Sıcak yakar, sineleri sarınarak.

Dere tepe yangın yeridir sanki,

Alev eser ağustos gecelerinde

Alev solur bozkırın insanı,

Sinesine alev sarınarak.

Bir bozkır üçlemesinde insan; 

Bakır tenli, yanık suratlıdır.

Yaz aylarında yanar bağrı,

Gayri yanan yiğit bağrıdır,

Alev solur bozkır insanı,

Ağustosta alev sarınır.

Bir bozkır üçlemesinde insan; 

Suya hasret, toprağa hasret; 

Güneşin kutsiyeti tütsülenir; 

Gecenin göğsünde ay gezinir; 

Yıldızlarla birleştirir bahtını,

Bozkırın ortasında yiğit gerinir.

Bir bozkır üçlemesinde insan; 

Dünya insan görmemiştir; 

İlkbaharında sonbahar güneşlenir; 

Bitmeden doğar gün yeni baştan; 

On beşinde kemale erilir.

Bir bozkır üçlemesinde insan; 

Havaya, suya, toprağa imrenilir.

Sarınır ruh bozkırın inceliğini,

İnsanlık murad alır, insanlık dirilir.

Hava suya, su toprağa, toprak tene karışır; 

Can bulur tabiat ana bozkır sıcağında; 

Kötülükler yer bulamaz, şeytan taşlanır.

Bir bozkır üçlemesinde insan; 

Toprağa bereket gelir.

Sürüyü çeken alabaş erkeçtir.

Süngüsü saplanır toprağa sümbüllerin,

Gelincik çiçeği burada gelinlenir.

Kınalı bir tazenin gözlerinde,

Mahmuzlanarak hayat canlanır. 

Bir bozkır üçlemesinde insan; 

Baharla yeniden çeliklenir.

Bir yeniyetmedir çiğdem çiçeği,

Toprağın bağrına kurulup, diklenir.

Oynak uçuşlarında kırlangıçlar,

Güne hızlı ve oynakça çöreklenir.

Bir bozkır üçlemesinde insan; 

Kavalında  kuru dere seslenir.

Gel-gitlere başlar bulut, gün ışığında; 

İğde gölgesinde gün serinlenir.

Bozkırın ortasında insan,

Ağustosta güneş gerinir.

Çankırı - 12.11.2000', 'BOZKIR ÜÇLEMESİ Bir bozkır üçlemesinde;  Sıcak yakar, sineleri sarınarak. Dere tepe yangın yeridir sanki, Alev eser ağustos gecelerinde Alev...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/bozkir-uclemesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlara Sitem', 'daglara-sitem-sadik-softa-4hmg7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senin yüceliğin senin heybetin,

Ruhuma büyük bir güven verirdi.

Başında borayı, karı görünce,

İçerimden yürekçiğim erirdi.

Seninle ererdi gönlüm murada,

Dizilişin; sıra sıra ard arda,

Hem omuz omuza, hem de sırt sırta,

Gönlüme, kalbime, güven verirdi.

Yüceliğin şaha kalkar şahlanır.

Kerem senden geçmek için ahlanır.

Aslı Hanım, Kerem’ine vahlanır.

Kalbin taşla kaya gibi gelirdi.

Zirvelerin erişilmezdi senin.

Kalmadı mı hiç kendine güvenin.

Sızlamazmış anlaşıldı yüreğin.

Görünüşün mazlum hissi verirdi.', 'Senin yüceliğin senin heybetin, Ruhuma büyük bir güven verirdi. Başında borayı, karı görünce, İçerimden yürekçiğim erirdi. Seninle ererdi gö...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/daglara-sitem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüyamdaydın', 'ruyamdaydin-hasan-huseyin-ozak-kubo0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dün yine rüyamdaydın

Hüzünle andım seni

Bunca zaman nerdeydin

Yoksa unuttunmu beni

Gelmeyeli kaç ay oldu

Ne sordun ne aradın

Niçin benle küsüyorsun

A'' gül yüzlüm sevdalım', 'Dün yine rüyamdaydın Hüzünle andım seni Bunca zaman nerdeydin Yoksa unuttunmu beni Gelmeyeli kaç ay oldu Ne sordun ne aradın Niçin benle küs...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özak']::text[], 8.5, '{"poet":"Hasan Hüseyin Özak","poet_slug":"hasan-huseyin-ozak","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ruyamdaydin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
