INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azap', 'azap-i-lyas-ozkan-l40b1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nefsim, niye sonu gelmez arzulardan usanmaz	

 Zevkler, ruha inen azap, niye hâlâ uslanmaz

-2000-', 'Nefsim, niye sonu gelmez arzulardan usanmaz	  Zevkler, ruha inen azap, niye hâlâ uslanmaz -2000-...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özkan']::text[], 8.5, '{"poet":"İlyas Özkan","poet_slug":"i-lyas-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/azap-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Dünde Bırakınca', 'seni-dunde-birakinca-hasan-huseyin-ozak-euc9x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dün deniz masmaviydi, martıların cenneti

Sevda pınarlarının eriştiği nokta

Bu günse kapkara bir cehennem

Fırtınaların cirit attığı

Canavarların avını beklediği yer', 'Dün deniz masmaviydi, martıların cenneti Sevda pınarlarının eriştiği nokta Bu günse kapkara bir cehennem Fırtınaların cirit attığı Canavarla...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özak']::text[], 8.5, '{"poet":"Hasan Hüseyin Özak","poet_slug":"hasan-huseyin-ozak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/seni-dunde-birakinca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmişim', 'sevmisim-sadik-softa-wbm94', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sevmişim; 

yollarda buz tutanda

