INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korktuğum Şey', 'korktugum-sey-hasan-huseyin-ozak-on9hx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İster döv, ister öldür

Senden korkmuyorum

Ne dersen de, yerden yere vur beni

