INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuğum', 'cocugum-sadik-softa-bhi7j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uyu; 

Mühürledim gözünü, dudaklarımla,

Rahat uyu çocuğum, güzel düşler görerek.

Yumulan gözlerinde mutluluğu bulurum,

Sabaha pırıl pırıl çıkasın süzülerek.

Yürü; 

Bir yol var ki önünde, sana daim arkadaş; 

Kucakla zamanları, ömrün oldukça yürü.

Yılların kemendini gönüllerden çözerek; 

Devran durdukça yürü, derman buldukça yürü.

Sürü; 

Zamana uymak neymiş; zaman sana uymalı.

Tak peşine zamanı, gittiğin yolda sürü.

Bu kalabalık yığın, seninle bir hız alsın; 

Tak peşine hepsini, gittiğin yolda sürü.

Büyü; 

O coşkun çocukluğun verdiği hızla büyü.

Saf, tertemiz dünyanda, her an neşeyle büyü.

Kederler uzak kalsın, melek yüzlü küçüğüm,

O küçücük dünyanı, hem büyüt, hem de büyü.', 'Uyu;  Mühürledim gözünü, dudaklarımla, Rahat uyu çocuğum, güzel düşler görerek. Yumulan gözlerinde mutluluğu bulurum, Sabaha pırıl pırıl çık...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cocugum-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan', 'i-syan-hasan-huseyin-ozak-dgm11', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dur be ey zalim dünya

Dur artık, dur diyorum

Yetti artık bu oyun

Yetti artık sahtekarlık

Verin benim emeğimi

Verin benim göz nurumu

Alın terimi

Hepsini geri istiyorum.

Yoksa,

Tazminatta istemem, malulen emeklilik de

Ben yapacağımı bilirim

İstifa ediyorum.', 'Dur be ey zalim dünya Dur artık, dur diyorum Yetti artık bu oyun Yetti artık sahtekarlık Verin benim emeğimi Verin benim göz nurumu Alın ter...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özak']::text[], 8.5, '{"poet":"Hasan Hüseyin Özak","poet_slug":"hasan-huseyin-ozak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/isyan-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elem Dökülür Yapraklardan', 'elem-dokulur-yapraklardan-sadik-softa-jsudh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Elem dökülür yapraklardan; güz günü.

Esmersi günleri karartır esmer rüzgar,

Bulutlar boşaltır üstümüze hıncını,

Kara bulutlarda, kara yağmurlar.

Sisler arkasına saklar dağlar başını,

Dağ başları nemli, uzak, dağ yollarında

Tek başına duran bekçi evleri,

Bekçi kızlarına özlem duyar.

Kabuk değiştirir taş yürekler,

Kuşların titrek, ıslak tüylerini sarsar; 

Serçe sesleri noksan dağ yollarında,

Dağ eteklerinde gün, durmadan ağlar.

Elem dökülür esmersi dağ yollarında.

Çocuklar cami avlusunda üşür,

Yoksullar daha bir ağlamaklı, 

İnsanın yüreğine acı üşüşür; 

İnsan daha bir başka acı duyar.

Ağır ağıtlarda sulu sepken uzantı,

Kurşuni bulutlar uzanır üstümüze; 

Hüzün iç burkar, ne garip bir rastlantı; 

Gün, günde yorgun yorgun bakar...', 'Elem dökülür yapraklardan; güz günü. Esmersi günleri karartır esmer rüzgar, Bulutlar boşaltır üstümüze hıncını, Kara bulutlarda, kara yağmur...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/elem-dokulur-yapraklardan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yâ Rasûlallah', 'y-ras-lallah-i-lyas-ozkan-tgz79', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İşte âcizlik, dil tutulmuş, mecal yok ifadeye

Seni anlatmak mı? Kelimeler yetmez, söz söylemeye

Döneklik mi, vefasızlık mı..? Ne olur, vurma yüzümüze 

Zaman perdesini sıyırıp da şöyle bir bak, halimize

Yâ Rasûlallah! Zaman geçtikçe başkalaşmış yollar 

Caydırmak için, sindirmek için, önümüze gerilmiş kollar

Yüzüm yok, bilmem, bu kaçıncı dönüşüm 

Hicaptan iki büklüm, feci âkıbetimi düşünmüşüm

Mahzunum, rencide olmuş, ruhum, dönekliğimden 

''Ümmetimdir'' diyerekten, bir tutuversen elimden

Bir bakıver, kalkmış da selam yollar sana, eller 

Her ne kadar, kıskansa da çıldırsa da eller...

Hani Medine''de, Ebû Eyyûb''a, misafir gelmiştin

Bir gelsen rüyalarımıza, bizi ne çok sevindirirdin

En mücrimler bile, emân alıp sığınmışlardı kapına,

Şimdi bin ruhumuzla müştâkız, inan, bir selamına

Şair değilim, hissiyatımı ifadeye yetmiyor şiirim 

İfadesizliğim içinde, devrin dertlerinden ne çok dilgirim

O zamanlar, etten-kemikten kalkan, dostların vardı

Devir ki, bizi de ''kardeşlerin''olma arzusu sardı

Safrâni, ne yapsa hep; derdini anlatır, bakma kusuruna 

Emân dileyip gelmişse, ne olur, kabul buyur huzuruna... 

30.12.1999 

Perşembe', 'İşte âcizlik, dil tutulmuş, mecal yok ifadeye Seni anlatmak mı? Kelimeler yetmez, söz söylemeye Döneklik mi, vefasızlık mı..? Ne olur, vurma...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özkan']::text[], 8.5, '{"poet":"İlyas Özkan","poet_slug":"i-lyas-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ya-rasulallah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ferman Senindir', 'ferman-senindir-i-lyas-ozkan-ux9me', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne gelirse Sen’den, râzıyız ona 

Ferman Senindir, Sultanım

Gül koklarken, dikenler batsa da 

Ferman Senindir, Sultanım

Koşarken, düşmüşüz ara sıra 

Ferman Senindir, Sultanım

Ne garip bir mekan, şu dünya 

Ferman Senindir, Sultanım

Dünyaya mukabil, ukba veriyorsun ya 

Ferman Senindir, Sultanım

Kulların düşmüşler, batmışlar batağa 

Af Senindir, rahmet Senindir, Sultanım

Boynu tasmalı kulların, kapındalar şimdi 

Kabul Senin, davet Senindir, Sultanım

Sen varsın gönlümüzde, ağyar girmedi hiç 

Muhabbet Sanadır, herşey Senindir, Sultanım

Ne yapsak, affına sığınıyoruz hep

Mağfiret Senindir, Sultanım

	

Mübarek gündür, huzurundayız yine 

Zaman Senin, mekan Senindir, Sultanım..

25.12.1999. 

Cumartesi', 'Ne gelirse Sen’den, râzıyız ona  Ferman Senindir, Sultanım Gül koklarken, dikenler batsa da  Ferman Senindir, Sultanım Koşarken, düşmüşüz ar...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özkan']::text[], 8.5, '{"poet":"İlyas Özkan","poet_slug":"i-lyas-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ferman-senindir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Yüzlüler', 'gul-yuzluler-i-lyas-ozkan-n5knl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Öyle bir ân ki, dil lâl olur 

Susar gönül, insan mahzun olur

Hadi anlat derler, ama âcizdir lisan 

Kelimeler hep dile dolanır, bağ olur...

Büyükleri anlatmak bana mı düşmüş, ne haddime 

Nezaket timsali erler önünde, kaba-sabalığım âr olur

Gayret.. ve gayret nisbetinde himmetle iç-içeler 

Geçer-gider de ömür.. ömürleri tek-misâl olur.

İlimle takva birleşince, ne de güzel dururmuş insanda 

''Ve''I- âkıbetü lilmüttekîn'' ne güzel beşaret olur

Hayatları gül bahçesinde gül dermekle geçenler 

''Fî cennât''in- naîm'' ne güzel mekan olur... 

12.12.1999 

Pazar

* Muhterem büyüklerim F.Akdemir,

Y. Yılmaz, A.Yılmaz, R. Toraman Beyefendilere ve tüm Gül Yüzlüler''e...', 'Öyle bir ân ki, dil lâl olur  Susar gönül, insan mahzun olur Hadi anlat derler, ama âcizdir lisan  Kelimeler hep dile dolanır, bağ olur... B...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özkan']::text[], 8.5, '{"poet":"İlyas Özkan","poet_slug":"i-lyas-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gul-yuzluler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittiler', 'gittiler-i-lyas-ozkan-itpg0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gittiler.. Bir ''vedâ'' diyemeden 

Gittiler.. Hicranları dinmeden 

Sıkıntıları geride bırakıp 

Cefâdan safâya gittiler

Koşturup durdular ya.. dünyada 

Birgün bile, gün yüzü görmeden gittiler 

Tohumlar saçtılar ya.. dört bir yanda 

Fidanlara doymadan gittiler

Yüreğimizde sevdasını duyduğumuz erler 

Bu yola can-baş koyan yiğitler

Geride hasret bırakıp gittiler

Sinemizde bir kor yakıp gittiler

Mevsim hazanmış bize 

Dilimizde hüzünlü şarkılar yine 

Gözyaşlari bırakıp gittiler 

Yüreğimizde sevda, hasret türküleriyle gittiler

Ellerimizde kır çiçekleri 

Gözlerimizde hayaller 

Gecemizde rüya olup gittiler 

Hüzün nağmeleri bırakıp gittiler...

06.12.1999 

Pazartesi', 'Gittiler.. Bir ''vedâ'' diyemeden  Gittiler.. Hicranları dinmeden  Sıkıntıları geride bırakıp  Cefâdan safâya gittiler Koşturup durdular ya.. ...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özkan']::text[], 8.5, '{"poet":"İlyas Özkan","poet_slug":"i-lyas-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gittiler-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-i-lyas-ozkan-i4axf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu yol çıkmaz sokak 

Dön de gel

Geceler karanlık 

Aş da gel

Dikenler kaplamış yolları 

Geç de gel

Ziftler sarmış, aydınlıkları 

Seç de gel

Kalb incileri dökülmüş yerlere 

Al da gel

Değerler kapılmış yellere 

Gör de gel

İnsan, unutmuş insanlığı 

Önüne ser de gel

Uçuruma gider, görmeyerek karanlığı 

Kollarını ger de gel

Rahmet gelmez, kararmış ömür 

Dua dua ellerini aç da gel 

Gönüller olmuş, sanki, kömür 

Rahmet hüzmelerini saç da gel

Baş okşayanı kalmamış, mahzun yetimin 

Hadi hatırını sor da gel

Onulmaz yaralar sarmış, bünyesini milletin 

Yaraları sar da gel

Sarpa sarmış, yokuş olmuş düzler 

Herbir yanda yığınla pürüzler 

Hep bahar bekler gözler 

Yokuşları, pürüzleri aş da gel...', 'Bu yol çıkmaz sokak  Dön de gel Geceler karanlık  Aş da gel Dikenler kaplamış yolları  Geç de gel Ziftler sarmış, aydınlıkları  Seç de gel K...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özkan']::text[], 8.5, '{"poet":"İlyas Özkan","poet_slug":"i-lyas-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gel-79-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çam Dağı Yolunda', 'cam-dagi-yolunda-i-lyas-ozkan-w98ad', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '*Asrın beyin yapıcısına...

Yıl 1925... Bir cemre düşer toprağa

Yıl 1925... Bir tohum atılır toprağa

Mekan ne mekan, toprak ne toprakmış 

Sarp kayalar, sarp yokuşlar varmış

Nasıl geçer, sekiz buçuk yıl, dersin 

Dost yok, yâr yok, yâran yok. 

Yalnız kalmak kolay mı zannedersin 

Dert dinleyen yok, hatır soran yok..

Milletin derdini çekmek kolay değil 

Onca ezâya rağmen, gönül koymak yok.

Sarp yokuşlar, sarp kayalar engel değil 

Yürümek var, mıhlanıp kalmak yok..

Âh Efendim! Sen, derdini çektin o günlerin

 Çabalayıp durdun, büyüsün diye güllerin 

Bak, şimdi demetlerle geliyor sevenlerin 

Günler geçtikçe, yolunu “yol” bilenlerin...

28.11.1999 

Pazar', '*Asrın beyin yapıcısına... Yıl 1925... Bir cemre düşer toprağa Yıl 1925... Bir tohum atılır toprağa Mekan ne mekan, toprak ne toprakmış  Sar...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özkan']::text[], 8.5, '{"poet":"İlyas Özkan","poet_slug":"i-lyas-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/cam-dagi-yolunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Usandım', 'usandim-i-lyas-ozkan-bvx85', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Takılıp yollarda kalmaktan

Ufak şeylerin hesabıyla uğraşmaktan 

Bir ''oh'' deyip, bin ''âh'' çekmekten 

Usandim Allah''ım, usandım...

Şikayetim kendimdendir 

Günahlarım hep elemimdir 

Tek ümidim mağfiretindir 

Herkes koşarken, düşmekten usandım

Mağfiret hazinen geniştir, tükenmez 

Kutlu yolun yolcusu yolundan dönmez 

Kul olan kul, gaflet bilmez

Beni kahreyleyen arzularımdan, usandım...

27.11.1999 

Cumartesi', 'Takılıp yollarda kalmaktan Ufak şeylerin hesabıyla uğraşmaktan  Bir ''oh'' deyip, bin ''âh'' çekmekten  Usandim Allah''ım, usandım... Şikayetim k...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özkan']::text[], 8.5, '{"poet":"İlyas Özkan","poet_slug":"i-lyas-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/usandim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamansız', 'zamansiz-hasan-huseyin-ozak-ub67v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şimdi nerden geldin ki aklıma durup dururken,en olmayacak zamanda, hemde ders çalışırken. Hem niye yarı çıplak gördüğüm kız değil de sen geliyorsun aklıma. Anlaşılan seni seviyorum galiba, inanmıyormusun? Biraz önce bende inanmıyordum ama, şu kalemin yazdığına baksana..

Ne zaman geçsem o karanlık sokaklardan

Başlar içimde tükenmez sancılarım

Titrek bir ışıktır umut, soluk bir nefes

Ve en sonunda yine seni hatırlarım', 'Şimdi nerden geldin ki aklıma durup dururken,en olmayacak zamanda, hemde ders çalışırken. Hem niye yarı çıplak gördüğüm kız değil de sen gel...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özak']::text[], 8.5, '{"poet":"Hasan Hüseyin Özak","poet_slug":"hasan-huseyin-ozak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/zamansiz-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlarmıydın', 'aglarmiydin-hasan-huseyin-ozak-hhym1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düşün ki bir an, sen ben olmuşsun, ben de sen

Düşün ki bir an, sen beni sevsende, ben seni sevmesem

Yada sever gibi görünsem

Biraz dalga geçsem seninle, vakit geçsin diye.

Ve sen beni ölesiye sevsen

Rüyalarını hep benimle süslesen

Anne demeyi unutsan, hep benim ismimi söylesen

Benim ismimi yazsan, bulutlara, sevdalara

Lakin bende o sırada, unutuversem seni

Hiç görmemiş gibi geçsem yanından

Ve artık bundan sonra hiç umursamasam

Ağlarmıydın geceleri,

Başını taşlara vururmuydun,

Şimdi benim yaptığım gibi', 'Düşün ki bir an, sen ben olmuşsun, ben de sen Düşün ki bir an, sen beni sevsende, ben seni sevmesem Yada sever gibi görünsem Biraz dalga geç...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özak']::text[], 8.5, '{"poet":"Hasan Hüseyin Özak","poet_slug":"hasan-huseyin-ozak","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/aglarmiydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bilsen', 'bir-bilsen-hasan-huseyin-ozak-paswy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sende biliyorsun, seni deliler gibi seviyorum

Boşalan bütün kadehlerimi, hep sana adıyorum

Aşktan yana şansım yokmuş, bunu şimdi anlıyorum

Ama, asıl derdimi bir bilsen

Bir defa olsun seviyorum demeden

Kapattın bu aşk sayfasını

İşte ben ona yanıyorum', 'Sende biliyorsun, seni deliler gibi seviyorum Boşalan bütün kadehlerimi, hep sana adıyorum Aşktan yana şansım yokmuş, bunu şimdi anlıyorum A...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özak']::text[], 8.5, '{"poet":"Hasan Hüseyin Özak","poet_slug":"hasan-huseyin-ozak","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bir-bilsen-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anayasa', 'anayasa-huseyin-cayikli-mrlj7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'çocuklar gülün biraz

ağlamayın

size gururla bakmak duruyor usta yazarların dilinde ki yıllardan.

ağlamayın

kapatılıyor emeğimiz.

kapatılıyor yılların emeği

kapatılıyor özgürlüğümüz

tek düşüncemiz

neyin kapatıldığını burada yazsam

anayasanın bilmem kaçınca maddesiyle benimde dilimi ve ellerimi kapatırlar.

üzülmeyin üzülmeyin

ağlamayın ağlamaya gerek yok

kapatılsada halkıma doyuran ekmek için

tutuşan zaferimiz bir utopyasa

o zaman anayasaya eklesinler

marksistler idam edilmeli diye.', 'çocuklar gülün biraz ağlamayın size gururla bakmak duruyor usta yazarların dilinde ki yıllardan. ağlamayın kapatılıyor emeğimiz. kapatılıyor...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anayasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duydum Ama Ne Kadarı Doğru', 'duydum-ama-ne-kadari-dogru-huseyin-cayikli-li140', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'duydum ki sevmişsin birini.içinde hangi dorukların karlarıyla dolaştın bilmem.ellerin hala yalana dair yazıyormu.ah eski dostum şimdi sana ne yazmalı.giderayak olurmu sevmek şakaya gelir mi.amacların ve amacına ulasma duygun ne olmus.biliyorum sevebiliyoruz çok şükür.yaşamayı becerebiliyoruz.ne mutlu bize...hala yaşayabiliyoruz.bir kadın vardır hayatında kaçıncı voltanda atıyor kalbin.bir kadın sevmişim şimdi kimbilir nerde.hadi neyse geceyi fazla uzatmadan aşka nikotin bağımlısı yaptık.bu akşamıda senle kapatalım.neya yakalım neye içelim...neye yakınalım.', 'duydum ki sevmişsin birini.içinde hangi dorukların karlarıyla dolaştın bilmem.ellerin hala yalana dair yazıyormu.ah eski dostum şimdi sana n...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/duydum-ama-ne-kadari-dogru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprağın Acısıyla Yoğrulduk', 'topragin-acisiyla-yogrulduk-hasan-kaya-78qgx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geceye verdim

Mızıkçı bir çocuğun

Küs yalnızlığını.

İğledim acıları eğirdim 

Koca bir yumak 

Mart ayazı 

Eylül yağmuru 

OrtaDoğu''nun hilali kaşın

Sözün kırılgan suskusu

Damaskos önünde vurulmuş

Bağdat’ta yatar.

Esmer teninde bir kölenin

Şaklayan kırbaç izi

Ardıma düşer

Uykularımı böler.

Suların dağlara çekildiği 

Bir sabah vakti 

Sesim yollara düşer

Hüzünlü hüzzam

Üşür 

İki yakası bir araya gelmez 

şehrin koynunda

Şahlar 

Sultanlar 

Bir de atların kırık nallarından önce

Tarihin suskun yalnızlığında

Savaşçılar kılıç kuşanmadan

Aşk vardı

Sürülmüş tarlalar

Acem ilinden gelen turnalar

Kasfkas''lara giden yollarda

                                   biz vardık

Bir masaldı

Leyla’nın dillere destan güzelliği

Peygamberler ülkesinde.

Ve bir yalan

Ağzında zeytin dalı

Cudi’ye dönen güvercin

Tenini soyunmuş 

Taştan döşeği 

Yatıyor boylu boyunca

                        bir şair

Tahta kılıçlarını kuşanmış dervişler

Başı tıraşlı 

Kaşı tıraşlı Abdallar

Alıp şiirlerini yollara düştüler.

Cana suskun 

Kana düşkün eşkıyalar kesti yolları.

Birer birer 

Düştük Sivas önünde

Çayda çıra 

Keremim yanarım.

Denizlerin

Akı ile karası arasında kalmış

Bahtsız toprağım

Sevgili yurdum

Susuyor köy köy

Yanıyor orman orman

Gidiyor şehir şehir. 

Kuruyor

Kökleriyle sökülmüş üç selvi. 

Ağzı süt kokan şairler

Kavganın orta yerinde

Dizi dizi

Dizesiz kaldı

Eskimiş Şilebezinden mintanı

Varna’dan Karadeniz''e

Akdeniz bakan şair.

Kızıl saçlarında

Kavga türküleri gezdiriyor.

Ferhat''ım 

Sümüklü oğlanım

Yiğidim ağlıyor 

Şirin şirin.

Yaralı bir serçe 

Saçak altında

Buzdan yıldızların 

Düştüğü kaldırımlarda.

Kum saatinin 

Zembereği yok kurmaya.

İnce ince

Delice akıyor zaman 

Karanlığımıza yenildik

Zara’dan geçti zulüm

Taş üstünden

Taşı aldı 

Omuz üstünde başı

Kütahya’nın çinisinde

Laleler boynu bükük kaldı

Bir fermanla

Ak mintan

Yalın ayak 

Adımız asiye çıktı

Sokak sokak sorulduk

Ev ev arandık

Kaçak öykülerimiz

Sürgün günlerimiz oldu

Sarı sıcak gülüşlü

Kara kış, çatık kaşlı

Bebeler hep ağlar

Dudakları kan kırmızısı

Yanakları al al olsun diye

Kanlı göbek bağını dudaklarına 

Yanaklarına sürdüğümüz 

Bebelerin masalıdır 

Toprağın acısıyla yoğrulmuş

Yorgun akşam güneşi gibi sessiz.

Kadınların anlattığı.

Kutsal kitapların yazmayı unuttuğu

Bir günahı işledim gururla.

Musa’nın bilmediği

İsa’nın ödemediği 

Demire tırnakla atılmış çentiklerle

Gün sayıyorum. 

Evcil nevmit geceyi vurdum

Kentsel yalnızlığımızda', 'Geceye verdim Mızıkçı bir çocuğun Küs yalnızlığını. İğledim acıları eğirdim  Koca bir yumak  Mart ayazı  Eylül yağmuru  OrtaDoğu''nun hilali ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kaya']::text[], 8.5, '{"poet":"Hasan Kaya","poet_slug":"hasan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":116,"source_url":"https://www.antoloji.com/topragin-acisiyla-yogrulduk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Notalar Savaşınca', 'notalar-savasinca-huseyin-cayikli-5xgo4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ince bir buziki sesi ve aynı akorla çalan kırık bir saz.bu iki ensturman gibidir kıbrıs adası.ben bu ikilinin arasında şaşıp kaldım nedir bu düşmanlık nedendir notalar savaşınca içimi burkan bu acı.Karşılıklı hiç aşık olmadılar mı.hiç mi sevmedi bunlar birbirini.buziki ve saz eşliğinde oturup konuşacaklarına neden yağdı üstlerine demir yağmurlar.çelik miğferlele kuşattılar içini.notalar savaştı bir kez ensturmanların hepsi buziki ve sazın duellosuna geldi.bir kere sevişmişlerde oysa kalpleri kırılmıştı iki sevgili ayrılmıştı.işte bir buruk sondur bu ayrılık hikayesi hazin öykülerin iki galibi vardır seyirciler ve tiyatro sahibi.şimdi aşka mı yoksa siyasetemi yazmalı.ince bir buziki nazının edasının kurbanı olmuş anadolu taşralı saz buna bakıp haz almıştı.neydi bunların içten çilesi.neydi bunca ses neydi ey sanat yalvarıyorum bana biraz aşktan bahset.notalar savaştı birkez sevişmek için ne de çağre kaldı.bu iki saz kendi çocuklarını sevdasız barındırdı.', 'ince bir buziki sesi ve aynı akorla çalan kırık bir saz.bu iki ensturman gibidir kıbrıs adası.ben bu ikilinin arasında şaşıp kaldım nedir bu...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/notalar-savasinca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lara', 'lara-yagmur-damlasi-7lj62', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana bir gün bir yüreğin bir başka yürekten nasıl ayrıldığını

Anlatacağım  sevdamın hoş kokusu lara

O zaman anlayacaksın korkunun nasıl baskın çıktığını aşka

Ve senin için yapılan fedakarlığı

Sen şimdi hayal dünyanda benim büyük sevdamla 

Uzaklardan habersiz mutlu ve mesut yaşa

Yemin olsun seninde gözünden akacak bir damla yaşa

Feda olsun bu aşığın canı da

Sana bir gün belki de çok uzun yıllar sonra

Bir gümüş balığının hikayesini anlatacağım uzun uzadı ya

Belki yüz yüze değilse de bir kitabın mısralarında 

Nasıl ve kimler için feda edilirmiş bir hayat bu zamanda

Aşkın ve delice bir tutkunun  fedakarca iki yürekten

Sökülüp atılmasına şahitlik eden hiç kimse olmadı

Biz hiç bıkmadık lara hiç usanmadık oysa sevmekten

Yalnızca çaresizlikti bize getiren ayrılığı

Sen mutsuz olma diye o mutsuz olmasın diye birileri

Mutsuz ve bedbaht olmasın diye ayırdık biri birimizi

Yüreğimizden yüreklerimizi koparttık oysa ne mutlu ve güzel yaşardık

Ayrılığı bile öyle zulümlerle yasadık ki onu da  abarttık

Sen şimdi kuş kanadında bir küçük yürek

Uykulara dal gelecek güzel günlere gülerek

Her ne kadar tanımasan da beni bilmeyerek

Her mutluluğun mutluluğum olarak bu hayat sürecek

Lara...

Ben şimdi karanlık gecelerimde bir tek senin mutlu olduğunu bilerek

Hayata tutunmaya çalışıyorum yalnızım ve çaresizim

Hiç kimseye söyleyemediğim çileler ile kendimi çevirerek

Suskun bezgin ve ümitsizim

Lakin yüreğimin bir köşesinde sen hep gülüyorsun lara

Boynumu büksem de buralarda senin için hep seviniyor mutlu oluyorum

Sarıl ve  huzur içinde uykulara dal o melekler meleğinin koynunda

İkinize de mutluluklar diliyorum...........................................

Büyük aşkıma ve sana lara', 'Sana bir gün bir yüreğin bir başka yürekten nasıl ayrıldığını Anlatacağım  sevdamın hoş kokusu lara O zaman anlayacaksın korkunun nasıl bask...', ARRAY['Türk Edebiyatı','Şiir','Yağmur Damlası']::text[], 8.5, '{"poet":"Yağmur Damlası","poet_slug":"yagmur-damlasi","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/lara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Zamanı', 'ask-zamani-yagmur-damlasi-ham3d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zaman en güzeli zamanların

Yaşamak doyasıya yaşamak

Baharla birlikte canlansın anıların

Güzel şeymiş şu sevgi ile tanışmak

Sen benimsin ebediyen ben senin

Ve umutlar hep bizden yana

İçimizde çiçeği açsın sevginin

Güzel gülücükler var olsun yanağında

Kokun üzerimde her zaman

Fark etmiyor ne çıkar uzak kalsan

Ne yana baksam gözlerin

Yeşil en güzeliymiş renklerin

Sevdan yaktı beni doksanın kışında

Seni arar gözlerim ne yana baksa

Olsan da fark etmez artık olmasan da

Yürek yüreğe geçmiş can cana', 'Zaman en güzeli zamanların Yaşamak doyasıya yaşamak Baharla birlikte canlansın anıların Güzel şeymiş şu sevgi ile tanışmak Sen benimsin ebed...', ARRAY['Türk Edebiyatı','Şiir','Yağmur Damlası']::text[], 8.5, '{"poet":"Yağmur Damlası","poet_slug":"yagmur-damlasi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ask-zamani-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkım Hafızamla Yaşıt', 'askim-hafizamla-yasit-mehmet-ali-can-a1pkq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüreğimi sende açtım; bilmedim bir başkasını.

Gönlümde servet-i cihan, gözümde afet-i devran,

Görülmezden, bulunmazdan, olunmazdan saydım seni

Aşkım hafızamla yaşıt; seni hep sevmiş gibiyim.

Sevdan padişahtan ferman, sensiz mekanlarım zindan,

Dönülmezden, silinmezden, salınmazdan saydım seni

Benden önce ölsen bile görmem sensiz günlerimi.

Varlığın ömrüme derman, bedenim ruhuna kurban,

Kaçılmazdan, geçilmezden, ölçülmezden saydım seni', 'Yüreğimi sende açtım; bilmedim bir başkasını. Gönlümde servet-i cihan, gözümde afet-i devran, Görülmezden, bulunmazdan, olunmazdan saydım se...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Can']::text[], 8.5, '{"poet":"Mehmet Ali Can","poet_slug":"mehmet-ali-can","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/askim-hafizamla-yasit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkar Şehrin Nüfusundan Beni', 'cikar-sehrin-nufusundan-beni-okan-savci-1kbqz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Galiba sonları yaşıyoruz seninle

Yaşadığımız anlar,

Ayrılık öncesi zamanlara benziyor

Hazırla mendilini sevgilim

Hikayemiz bitti bitiyor...

Yüklü bir geçmiş kalacak bizden geriye

Duraklar..

Sinemalar...

Çay bahçeleri...

Hepsi birer anı olarak yer decek yüreklerde.

Uykuları bölüp sabahları geciktiren,

Tarifi olmayan, 

Anlamsız bir boşluğa düşeceğiz...

Sonra birileri gelip çıkaracak bizi o yerden

Aklımıza gelecek bu ayrılık öncesi zamanlar

Ama buna aldırmadan yeni insanlar seveceğiz...

Sen yine de,

Gecelerin hüznüne koyma kendini...

Bak gündüzler uzamaya başladı,

Azalır derdin her gün bir dakika! 

Bahara kalmaz unutursun beni...

Dilsiz bir veda seçtiğim için,

Gücenme.....

Kapını açık tut sen.

Aşk elbet tekrar girecektir, 

Benim çıktığım eşikten... 

Sabah olduğunda,

Bu şehrin nüfusundan beni çıkar...

Son kez okuduktan sonra,

Çöp tenekesinde bir yer ayarla bu şiire...

Bağışla...  uyandırmak istemedim,

Birkaç günde içinde dönmezsen

Yeni bir hayat kur kendine...', 'Galiba sonları yaşıyoruz seninle Yaşadığımız anlar, Ayrılık öncesi zamanlara benziyor Hazırla mendilini sevgilim Hikayemiz bitti bitiyor... ...', ARRAY['Türk Edebiyatı','Şiir','Okan Savcı']::text[], 8.5, '{"poet":"Okan Savcı","poet_slug":"okan-savci","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/cikar-sehrin-nufusundan-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanında Olmak Vardı!', 'yaninda-olmak-vardi-nazife-abayli-z0eqx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ah! Güzel dostum! 

Şimdi,yanında olmak vardı! 

Yanında olup,

Sol yanına uzanmak vardı.

Uyandırıp sessizce,

Benli düşlerinden koparıp seni,

Konuşmak vardı.

Uyku mahmurluğunda konuşmak.

Usul usul sokulup,

Masumca,

Başımı göğsüne dayamak vardı.

Saçlarım özledi ellerini,

Saçlarımı okşatmak vardı.

Ah! Güzel dostum! 

Şimdi,yanında olmak vardı!', 'Ah! Güzel dostum!  Şimdi,yanında olmak vardı!  Yanında olup, Sol yanına uzanmak vardı. Uyandırıp sessizce, Benli düşlerinden koparıp seni, K...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yaninda-olmak-vardi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen gittin,gittin,gittin....', 'sen-gittin-gittin-gittin-nazife-abayli-myway', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen gittin,gittin,gittin....

Gitme demek istedim,

Diyemedim.

Kala kaldım,

Baka kaldım.

Ben kaldım.

Etrafıma şöyle bir baktım,

Kağıdı kalemi kaptım.

Sayfalar dolusu yazdım.

Sevişmelerimizi,

Sevinçlerimizi,

Özlemlerimizi,

Hüzünlerimizi,

Yalnızlığa,

Terketmelerimizi,

Yazdım,yazdım,yazdım.

Sonra......

Seni bana,

Beni sana yazdım.

Kokumu da ekledim,

Bir tutam saçımı.

Ellerimi,

Gözlerimi,

Ve...

Yüreğimi

Paket yaptım.

Her birini ayrı renkte,

Kurdelayla bağladım.

Sana yolladım.

Aldın mı?', 'Sen gittin,gittin,gittin.... Gitme demek istedim, Diyemedim. Kala kaldım, Baka kaldım. Ben kaldım. Etrafıma şöyle bir baktım, Kağıdı kalemi ...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sen-gittin-gittin-gittin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dua', 'dua-halil-i-brahim-ozdemir-hz640', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kararır gündüzler geceler uzar

Ölüler dirinin mezarın kazar

Çok gördü bu şehir, Allah’ım verme

Kem gözlerden koru değmesin nazar', 'Kararır gündüzler geceler uzar Ölüler dirinin mezarın kazar Çok gördü bu şehir, Allah’ım verme Kem gözlerden koru değmesin nazar...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Özdemir']::text[], 8.5, '{"poet":"Halil İbrahim Özdemir","poet_slug":"halil-i-brahim-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dua-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarınımız aydın olsun!', 'yarinimiz-aydin-olsun-nazife-abayli-0t42i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen, seni bende,

Ben, beni sende,

Bıraktım...

Bir daha geri,

Almamacasına...

Hüzünlerin hüznüm,

Korkuların korkum,

Tutkuların tutkum,

Umutların,

Umudum olsun..

Yazamadığım............

Anımsadığın ne varsa...........

Bizim olsun...............

Günümüz güzel.............

Yarınımız aydın olsun!', 'Sen, seni bende, Ben, beni sende, Bıraktım... Bir daha geri, Almamacasına... Hüzünlerin hüznüm, Korkuların korkum, Tutkuların tutkum, Umutla...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yarinimiz-aydin-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitsin', 'gitsin-murat-demir-9sl9n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne dert kalır nede dertli,dünyada

Merakını dört bir yana sal gitsin

Hiç düşünme olsan bile çok darda

Kaymağına parmağını çal gitsin

Kim kalmış ki ilelebet hayatta

Göz yaşını sele suya kat gitsin

Gelen gider,birer birer sonuçta

Dertlerini sağa sola at gitsin

Onurunu servetin say,yıkılma

Şerefsize taviz verme it gitsin

Akıllı ol uğursuza takılma

Çekinmeden rezil rüsva et gitsin

Sev sevindir görmezsede el alem

Gönüllere dolu dolu ak gitsin

Gün gelir ki yazar seni bir kalem 

Tek de kalsan meşaleni yak gitsin

Tutarsızla ne selamlaş ne tanı

Müstehaktır,ot gelmişse çöp gitsin

Üzülüpte sakın takma kafanı

Riyakardan insan olmaz kop gitsin', 'Ne dert kalır nede dertli,dünyada Merakını dört bir yana sal gitsin Hiç düşünme olsan bile çok darda Kaymağına parmağını çal gitsin Kim kalm...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gitsin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi ki...', 'i-yi-ki-hasan-basri-kale-udvn2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Keşke..

Gelmeseydin

Görmeseydin

Tanımasaydın beni..

Hadi neyse 

Sevmeseydin bari 

Benden habersiz

Hiç olmazsa deseydin de

Bilseydim...

Bakma sen bana

İnanma yazdıklarıma.

İyi ki..

Geldin 

Gördün..

Tanıdın beni..

İyi ki sevdin..

Ve iyi ki demedin

Yoksa tutamaz kendimi

Ben de seni severdim...', 'Keşke.. Gelmeseydin Görmeseydin Tanımasaydın beni.. Hadi neyse  Sevmeseydin bari  Benden habersiz Hiç olmazsa deseydin de Bilseydim... Bakma...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/iyi-ki-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderim...', 'giderim-hasan-basri-kale-obg5p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Birgün ben de giderim bu yalan dünyadan

Ağlayanlarım olur belki de arkamdan..

Sen sakın ağlama; değmez artık

Vazgeçtiğim gündür o gün senin sevdandan...', 'Birgün ben de giderim bu yalan dünyadan Ağlayanlarım olur belki de arkamdan.. Sen sakın ağlama; değmez artık Vazgeçtiğim gündür o gün senin ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/giderim-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter ki Gel', 'yeter-ki-gel-abdullah-atay-h7eu8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hazan olmadan,

hüzün dolmadan,

gün solmadan,

kuşlar yuvaya dönmeden

GEL! ..

bahar yüzlü güzel...

damarlarımda sevdan akıyor.

özlemin yüreğimi yakıyor.

gönül gözüm tek sana bakıyor.

yeter ki bir kuşluk vakti

GEL! ..

ceylan gözlü güzel...

dermansın hep  kanayan yarama.

cansuyusun sevdalarıma.

yıldız olup akşamlarıma.

yine bir leylim vakti

GEL! ..

aşkı bende gizli güzel...', 'hazan olmadan, hüzün dolmadan, gün solmadan, kuşlar yuvaya dönmeden GEL! .. bahar yüzlü güzel... damarlarımda sevdan akıyor. özlemin yüreğim...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yeter-ki-gel-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ZZZ / Neşterin İşi Bitti / Kalk Hadi..!', 'zzz-nesterin-i-si-bitti-kalk-hadi-bir-mim-kemal-ertugrul-gapsq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kardeş 

Kardeş 

Kardeşlenen

Bir sevgi

Ve 

Çimen 

Çimen

Çimlenen

Hasret

İçimde 

Ve ACI..; 

Zehir zemheri..! 

.........

.......

......

...

Neşterin

İşi bitti,

Kalk hadi..! 

28.01.2004 / 03:05

Şükürler olsun...! ...- :))))))))))))', 'Kardeş  Kardeş  Kardeşlenen Bir sevgi Ve  Çimen  Çimen Çimlenen Hasret İçimde  Ve ACI..;  Zehir zemheri..!  ......... ....... ...... ... Neş...', ARRAY['Türk Edebiyatı','Şiir','Bir Mim Kemal Ertuğrul']::text[], 8.5, '{"poet":"Bir Mim Kemal Ertuğrul","poet_slug":"bir-mim-kemal-ertugrul","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/zzz-nesterin-isi-bitti-kalk-hadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşksız', 'asksiz-ozlem-torkul-tekan-l5uk5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu şehrin taşı toprağı bir bakire kız

Gündüz sizinle kalsın, gece benim olsun.

Gizemine ermeye ehil mi adsız

Her sokağı bal dudak, öpülmemiş aşksız.

Bu şehrin ışıkları gökten inen yıldız

Bugün sizinle yansın, yarın benim olsun.

Halvet ile hasret barışır mı, imkansız

İrem bağı, son durak, dönülmemiş aşksız.

(8 Aralık 2001)', 'Bu şehrin taşı toprağı bir bakire kız Gündüz sizinle kalsın, gece benim olsun. Gizemine ermeye ehil mi adsız Her sokağı bal dudak, öpülmemiş...', ARRAY['Türk Edebiyatı','Şiir','Özlem Torkul Tekan']::text[], 8.5, '{"poet":"Özlem Torkul Tekan","poet_slug":"ozlem-torkul-tekan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/asksiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum', 'seviyorum-tabir-gokce-rnnms', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çok seviyorum 

Ağaçları ve çiçekleri 

Kavgasızca yaşıyorlar 

Koskoca ormanda 

Aynı yerde ve yan yana 

Özgürce ve dostça 

Çok seviyorum 

Ağaçları ve çiçekleri 

Tüm nimetlerini 

Karşılıksız verdiklerinden değil 

İnsanlara 

İnsanlara rağmen 

Vermeye devam ettiklerinden 

Çok seviyorum 

Ağaçları ve çiçekleri', 'Çok seviyorum  Ağaçları ve çiçekleri  Kavgasızca yaşıyorlar  Koskoca ormanda  Aynı yerde ve yan yana  Özgürce ve dostça  Çok seviyorum  Ağaç...', ARRAY['Türk Edebiyatı','Şiir','Tabir Gökçe']::text[], 8.5, '{"poet":"Tabir Gökçe","poet_slug":"tabir-gokce","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/seviyorum-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhasebe', 'muhasebe-ozlem-torkul-tekan-tj308', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Neyin sahibiyiz ki şu hayatta

Sadece emanet bir bedenimiz var

Ona da hükmümüz ölene kadar.

Yitik anılardır gönüle zarar

Bir gün kor top olur sineyi yakar.

Neyin sahibiyiz ki şu hayatta

Kaç günün toplamı bir ömür yapar

Kim cesaret edip yüreği tartar

Bil ki dengede durmuyorsa kantar

Geçmişin gelecekle bir hesabı var.

Neyin sahibiyiz ki şu hayatta

Hep mutlu oluyor mu kazananlar

Kaderi şansla karıştıran şaşar.

Elini taşın altına sok ne var

Her kara kışın sonrası bahar.

12 Ocak 2002 / 00:26', 'Neyin sahibiyiz ki şu hayatta Sadece emanet bir bedenimiz var Ona da hükmümüz ölene kadar. Yitik anılardır gönüle zarar Bir gün kor top olur...', ARRAY['Türk Edebiyatı','Şiir','Özlem Torkul Tekan']::text[], 8.5, '{"poet":"Özlem Torkul Tekan","poet_slug":"ozlem-torkul-tekan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/muhasebe-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutlar', 'umutlar-mustafa-erkan-yalcin-e30um', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her gün penceremden doğan kızıl kızıl bulutlar

Ne zaman ki beyaza dönersiniz

Kaybolur beslediğim bütün umutlar

Umutlar ahhh umutlar

Yarına mı kaldı yine bütün umutlar

Artık doğmasın güneş sönmesin umutlar...', 'Her gün penceremden doğan kızıl kızıl bulutlar Ne zaman ki beyaza dönersiniz Kaybolur beslediğim bütün umutlar Umutlar ahhh umutlar Yarına m...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Erkan Yalçın']::text[], 8.5, '{"poet":"Mustafa Erkan Yalçın","poet_slug":"mustafa-erkan-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/umutlar-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmenimsin', 'ogretmenimsin-dogan-bagis-raz7c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayat okulunda bütün dersleri zayıf olan bir öğrenciye benziyorum,

Sadece aşk dersim pekiyi

Eh kolay değil özel ders alıyorum tarafından! 

Hoca en son bir sınav yaptı

''''Aşk'''' ı bir cümleyle tanımlama sınavı 

Ben ise tek bir kelime yazdım ve

En yüksek notu aldım herzamanki gibi

Ne mi yazdım? 

Seninle karar verdiğimiz gibi

ÖLÜMÜNE......', 'Hayat okulunda bütün dersleri zayıf olan bir öğrenciye benziyorum, Sadece aşk dersim pekiyi Eh kolay değil özel ders alıyorum tarafından!  H...', ARRAY['Türk Edebiyatı','Şiir','Doğan Bağış']::text[], 8.5, '{"poet":"Doğan Bağış","poet_slug":"dogan-bagis","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ogretmenimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Havuzu', 'sevda-havuzu-dogan-bagis-4r6tx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben bir gece vakti düştüm sevda havuzuna,

Suyu da soguktu ellerim ve yüreğim gibi

Sen bir gece vakti düştün aklıma

Ellerinde sıcaktı yüreğin gibi

Şimdi bütün sevda türküleri ıslıklarımda

Şişelerde ise ne oldugunu bilmediğim içkiler

Çok yakın ellerim biliyorum

Uzatıyorsun ama ben,

Tutamıyorum...', 'Ben bir gece vakti düştüm sevda havuzuna, Suyu da soguktu ellerim ve yüreğim gibi Sen bir gece vakti düştün aklıma Ellerinde sıcaktı yüreğin...', ARRAY['Türk Edebiyatı','Şiir','Doğan Bağış']::text[], 8.5, '{"poet":"Doğan Bağış","poet_slug":"dogan-bagis","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevda-havuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umurumda değil', 'umurumda-degil-hifzi-ozbekmez-wmgvk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu dünyanın hiçbir malı

Değil umurumda değil

Ne kilimler nede halı 

Değil umurumda değil

Ne bu hasret ne bu gurbet

Bunlarda bitecek elbet

Dert çeksemde ilelebet

Değil umurumda değil

Gözümdeki bu yaşlarda

Bağrımdaki şu taşlarda

Başıma gelen işlerde

Değil umurumda değil

Senin aşkın yeter bana

Yaşıyorum kana kana

Gitsemde öbür dünyaya

Değil umurumda değil

Çektiğim bütün acılar

Bağrımdaki bu sancılar

Yediğim onca kamçılar

Değil umurumda değil

Aşkınla ah yanmışım ben

Seni benim sanmışım ben

İster yalnız kalmışım ben

Değil umurumda değil

Halim perişan olsada

Bu gönül dertle dolsada

Bahçemde gülüm solsada

Değil umurumda değil

Hıfzıyım ister gülsemde

İsretse hemen ölsemde

Sen başkasını sevsende

Değil umurumda değil

2003', 'Bu dünyanın hiçbir malı Değil umurumda değil Ne kilimler nede halı  Değil umurumda değil Ne bu hasret ne bu gurbet Bunlarda bitecek elbet De...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/umurumda-degil-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne İsteyeyim', 'ne-i-steyeyim-hifzi-ozbekmez-56blq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni sevdiğimi sende bilirsin

Çağırsam yanıma hemen gelirsin

Canını istesem hemen verirsin

Ben daha Allahtan ne isteyeyim

Gönlünü vermişsin cananım bana

Almışsın kalbimi aşkınla sana

İhtiyaç kalmadı derde dermana

Ben daha Allahtan ne isteyeyim

Açtırdın bahçemdeki gülleri

Aşkla söylettin şakıyan dilleri

Yaşattın sen bunca güzel günleri

Ben daha Allahtan ne isteyeyim

Latifinin sen taht kurdun gönlüne

Ömür kattın bu çileli ömrüne

Tek dileğim sen ömrünce gül yine

Ben daha Allahtan ne isteyeyim

2003', 'Seni sevdiğimi sende bilirsin Çağırsam yanıma hemen gelirsin Canını istesem hemen verirsin Ben daha Allahtan ne isteyeyim Gönlünü vermişsin ...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ne-isteyeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi Ki Sevmişim', 'i-yi-ki-sevmisim-hifzi-ozbekmez-eq2wy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Arayanım soranımsın

İyi ki sevmişim seni

Hem canım hem cananımsın

İyi ki sevmişim seni

Güldürensin sen yüzümü

Coşturansın sen özümü

Bahar edensin yazımı

İyi ki sevmişim seni

Bana gönül verenimsin

Yüzüme tek gülenimsin

Sen benim can sevdiğimsin

İyi ki sevmişim seni

Latifiyim çok mutluyum

Gelecekten umutluyum

Sen benim ekmeğim suyum

İyi ki sevmişim seni 

2003', 'Arayanım soranımsın İyi ki sevmişim seni Hem canım hem cananımsın İyi ki sevmişim seni Güldürensin sen yüzümü Coşturansın sen özümü Bahar ed...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/iyi-ki-sevmisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaderimsin', 'kaderimsin-hifzi-ozbekmez-mnbnd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Alnımdaki yazımsın

Gönlümdeki sızımsın

Baharımsın yazımsın

Sen benim kaderimsin

Gönüldeki yaremsin 

Ciğerdeki paremsin

Sen başka bir alemsin

Sen benim kaderimsin

Gönlümün gül dalısın

Nakış nakış halısın

Latifinin balısın

Sen benim kaderimsin

2003', 'Alnımdaki yazımsın Gönlümdeki sızımsın Baharımsın yazımsın Sen benim kaderimsin Gönüldeki yaremsin  Ciğerdeki paremsin Sen başka bir alemsin...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kaderimsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuslata Dek…', 'vuslata-dek-muammer-celik-sgrhb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geleceğim

Geleceğim o AŞKIN’ın odasına bir gün

dalacağım gözlerine yine

okşayacağım yine bebeğini gözlerinin

okşayacağım

okşayacağım gözlerinde yüreğini

gönlünü, ruhunu ve bedenini...

Soyacağım seni kisvelerden

ve giymediğin elbiselerden...

dilimle alacağım damağının tadını

gözlerimde okuyacaksın pırıl pırıl adını

sütun gibi vucudunu 

öpeceğim, ısıracağım göğüs uçlarını

ve yakacağım aşkın ateşini dudaklarında…

Diline dolaşacağım kör düğüm gibi

ineceğim göbek çukuruna 

sağanak yağan yağmur damlası gibi… 

İneceğim,  bermuda-üçgeninde yuvarlanacağım

çıkrıkla çekeceğim suyunu

içeceğim doyasıya seni

gezeceğim ve kaybolacağım içinde 

kırarcasına kendimi 

dikleşip başkaldıran tüm organlarımın tepkisini…

Yumuşayacağım önce terinde

dans ederken inleyen namelerinin ritminde

yunacağım ve  köpüreceğim sularında

akacağım palmiye yağı gibi 

tutunacağım kalbinin surlarında…

Teninde eriyeceğim

doyulamaz tadında kanatsızca uçarak 

değdireceğim başını arş-ı azam''a 

dökeceğim orgazmın ırmağını dudaklarına

coşan şelalelerinde ıslanarak 

çağlayacağım dalga dalga içine

ineceğim denizine; yelkenine FORAAA diyerek

çekeceğim kulaç kulaç, kürek kürek… 

Varacağım, varacağım limanına

koylarından kıvrılarak

sessizce indireceğim gemimin yükünü

ve yeniden yükleneceğim oradan buraya dek 

arzu dolu aşkını, özlemini, hasretini vuslata dek...

BirDeli

28.01.2004', 'Geleceğim Geleceğim o AŞKIN’ın odasına bir gün dalacağım gözlerine yine okşayacağım yine bebeğini gözlerinin okşayacağım okşayacağım gözleri...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/vuslata-dek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni yıl mesajı', 'yeni-yil-mesaji-ozgul-ozyilmaz-0tpgi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şanslıyım.. 

Çünkü; Hiç kimsenin benim kadar çok seveni, 

Benim kadar çok sevdiği yoktur..

Dost, arkadaş, sevgili, kardeş, yoldaş, sırdaş, 

Her biriniz yüreğime ayrı bir tat

Her biriniz gönlüme ayrı bir taht kurdunuz..

Bazılarınız çok uzaklarda olsada, göz görmese, 

kulak duymasa, beden hissetmese de, 

yürek asla unutmadı hiç birinizi.. 

2002 sevinçlerine rağmen zor bir yıl oldu..

Acılarımız, can''dan kayıplarımız oldu..

Kâh coştuk, kâh kahrolduk..

Ama..

Herşeye rağmen zaman durmadı, 

Biz kendi planımızı yaparken, hayat bize planını yaşattı..

Bu yılın; 

Her birinize, gönlünüze göre hoş sürprizler yaşatmasını,

Ayakta kalmanızı sağlayan, 

Yürekteki-akıldaki temel taşlarınızın (her kim ve her ne ise)   daha da bir sağlamlaşmasını dilerim.. 

Umut için.. Sabır için.. Sevenleriniz için..

Gülümseyebilmek – Gülümsetebilmek için..

İçinizdeki kışların bahara dönüşebilmesi için.

Sağlıcakla kalın.. 

Özgül..

31.12.2002', 'Şanslıyım..  Çünkü; Hiç kimsenin benim kadar çok seveni,  Benim kadar çok sevdiği yoktur.. Dost, arkadaş, sevgili, kardeş, yoldaş, sırdaş,  ...', ARRAY['Türk Edebiyatı','Şiir','Özgül Özyılmaz']::text[], 8.5, '{"poet":"Özgül Özyılmaz","poet_slug":"ozgul-ozyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yeni-yil-mesaji-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendimce..', 'kendimce-ozgul-ozyilmaz-t3sls', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne seni, ne beni 

Kimseye eş tutmadım..

Yaşadıklarımız bize özeldi

Ayrı bir renkti birleşimimiz..

Ne kimsenin doğrusunu doğru saydım

Ne kimsenin yanlışını yanlış..

Herkesin kendince bir gerekçesi olduğunu

Bir insanı yüzdeyüz anlamanın ve anlaşılmanın imkansızlığını 

Algısının çok farklı olduğunu, çok önce öğrendim..

İşte bu yüzden kimseyi yargılamamayı seçtim

Kendi içimdeki doğruları ve yanlışları keşfettim

''Ben'' olarak yaşamayı tercih ettim..

Aslolan mutlu olmak ise 

Başkaları incinmediği sürece özgürsün deli gönlüm dedim

Ve maalesef çoğu kez kendimi incittim..

Olabildiğince, alışkanlıklardan öte beklentisizleştim

Kendimi bulabilmek derken, kendimden geçtim..

23.10.2003 / Özgül.', 'Ne seni, ne beni  Kimseye eş tutmadım.. Yaşadıklarımız bize özeldi Ayrı bir renkti birleşimimiz.. Ne kimsenin doğrusunu doğru saydım Ne kims...', ARRAY['Türk Edebiyatı','Şiir','Özgül Özyılmaz']::text[], 8.5, '{"poet":"Özgül Özyılmaz","poet_slug":"ozgul-ozyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kendimce-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lorke', 'lorke-enes-onal-7omy6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Toprağından koparılamamış şark gülü

Dokonduğun herşey doğulu olur

En kutsal,en çiçekli çamur

Hanımeli kokusunu ellerinde bulur

Yakılmış dağların sönmemiş külü

Diyarbakır yıldızlarından çalınmış bir çift göz

Horozlarla değil kurt ulumalarıyla aralanır

Kara ve kötü karalarınla paralanır

Işığı saklayan ay karalanır

Türküleriyle yanacak ıslak köz

Doğunun batıdaki en asi belirişi

Saçların Fırat gibi çıldırasıya akar

Minnetsiz yağmura sadece bembeyaz kar

Simsiyah,ipince geceyi ve ipliği yakar

Yayla rüzgarlarının ovada tek delirişi

Kır çiçeğine ve kendi tenine doğan güneş 

Tam tepedeyken peygamber gölgesini izler

Teninin yangınında ısınır kimsesizler

Yalnız kırat ve kırmızı duvak gizler

Bağdat''a Nişabur''a ve Beyrut''a eş

Hasretine Diyarbakır''ı da ekliyorum 

Bu özlemle körelir bütün ahkamlar

Boşa yanar tüm avare adamlar

yağmurun sadece yapraklara damlar

Yaprağından kopup toprağıma düşmeni bekliyorum.....', 'Toprağından koparılamamış şark gülü Dokonduğun herşey doğulu olur En kutsal,en çiçekli çamur Hanımeli kokusunu ellerinde bulur Yakılmış dağl...', ARRAY['Türk Edebiyatı','Şiir','Enes Önal']::text[], 8.5, '{"poet":"Enes Önal","poet_slug":"enes-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/lorke-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derdim Büyük', 'derdim-buyuk-guner-kaymak-1nn3k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Derdim büyük dostlar nasil söylesem

Ben gönlüme göre yar bulamadim

Divane gönlümü ne ile eylesem

Kendime eglenecek yer bulamadim

Pesinden gezdigim nazla örtündü 

Yüzüme bakmadi sirtini döndü

Olanca ümüdim tükendi söndü 

Ben gönlüme göre yar bulamadim

Kimi sosyeteydi kimisi köylü 

Kimisi kisacikti kimide boylu

Bir tane çikmadi tertemiz huylu

Ben gönlume göre yar bulamadim

Benim diledigim bana bakmadi

Beni seveni''de gönlüm almadi

Zalim felek hiç yardimci olmadi

Ben gönlüme göre yar bulamadim

Çogu kaprisliydi çogu''da  havali

Çogu bakimsizdi çogu boyali

Ugrina yandigim hiç olmadi orali

Ben gönlüme göre yar bulamadim

Utangaçligi, çekingenligi bir yenemedim

Üç günlük dünya''da eglenemedim gülmedim

Ozan Güner gençligin faydasini görmedim

Ben gönlüme göre yar sevemedim

Amsterdam / 28.01.2004', 'Derdim büyük dostlar nasil söylesem Ben gönlüme göre yar bulamadim Divane gönlümü ne ile eylesem Kendime eglenecek yer bulamadim Pesinden ge...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/derdim-buyuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-ahmet-atmaca-vnxz9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dilimde nağmeler şarkılar sessiz

Söylemekten acizim dertler çaresiz

Anladım ki yaşanmaz bu hayat sensiz

Arıyorum heryerde gittin gideli', 'Dilimde nağmeler şarkılar sessiz Söylemekten acizim dertler çaresiz Anladım ki yaşanmaz bu hayat sensiz Arıyorum heryerde gittin gideli...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Atmaca']::text[], 8.5, '{"poet":"Ahmet Atmaca","poet_slug":"ahmet-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sensiz-557-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Yalnızlık', 'eski-yalnizlik-gunay-guner-mj09x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'GÜNAY GÜNER

_____________________________

ESKİ YALNIZLIK

_______________________________





KISA TARİH

henüz adı konmamışken denizlerin

izini sürdüm göçer kuşların

bir kez olsun duymamıştım

kinini barbarların

gördüm kanatlı düşlerini çocukların

ay hüznündeydi bakışları atımın

yarınsız bir anında sonsuzluğumun







KIRIK DÜŞ

Yitirdik maviyi 

Uzak denizlerinde sevdanın

Bulabilmek ellerini

Anımsamak ansızın

Çağlar öncesinin esrikliği

Geçmemişken henüz üzerimden 

Ördüm yorgun saçlarını

Zamanın ölümsüz dinginliğinden 

Soruyorum bir çocuğa aşkı

Sözcükler sığmazken düşlere 

O güldü gülecek

İki sonsuz arasında bir çağa 

Yüzünde dolunay şavkı

                  



BULUŞMA

Seni çok eskilerden bilir gibiyim

Gülüşlerin kanat çırptığı

O sevi ülkesinden

Bırak sileyim gözyaşlarını

Ellerin avuçlarımda

Isıtsın 

Anımsatsın ne kaldıysa 

Unutuluşun hasatından

Kuşlar göç ediyor

Çocukluğumun ilkyazına





ÇAĞRIŞIMLAR

Her gecenin tanığı vardır

Söylemese de yıldızlar ve ay

Çağımızın gerçeği yalandır

Hücrelerde firari güneşler

Pencereler gördüklerinden bitkin

Alışkın artık kulaklar

Çarpması demire demirin

Dünya küçüldü diyor radyonun sesi

Dünya küçükse bu yalnızlık niye? 

Bütün saatler gece

Kilitte devinen anahtar sesi

Asırlar süren düşünce

Yüzyılları çalıyor tarihten saatler

Yaşım ne? 

Kaç nötron geçti aşkların üzerinden? 

Çocukluğum geliyor gözlerime



ESKİ DAĞ

Bir ömrün yorgunluğuyla

Dedem anlatmıştı bana

Işıl ışıl bir kış gecesi

Ay büyürdü dışarda

Bilir misin neden tükenmez 

Çatlak ellerimde büyüttüğüm acı

Söğüt dallarınca sabırlı

Ağustos böceğinin şarkısı

O dağ oradadır 

Bildim bileli kendimi

Bu pencere bu sedir

Hala ocağın başında mı kedi? 

Sayılır mı yağan kar? 

Bilinir mi denizin yaşı? 

Bütün yıldızlar 

Nehirlere mi akar? 



ÖZLEM

Özlem dağdır

Munzur’sa hüzün

Sevda tenin gibi ak

Mevsim göç eden ırmak

Doludizgin bir kısrak zaman

An olur çocukluk uzayan yollar

Söğütlerin kıyısındaki yurt

Yitirilen yüzde sararan sıcak başak





YAŞAM İÇİN 

özlemekle geçti bütün bir kış

ey kırlangıç ömrüm.

savrulurken tipide yaprak 

uğuldarken senfonisi ölümün, 

baharı ak bir gergefe

beni bir karanfil gibi işle.

belki sen de anımsarsın

sırılsıklam siyah

bir geceydi her yanım, 

birlikte ağladık ardından

ölüme erken koşan 

bir  ceylanın.

saklıyorum en derin gökyüzüne kendimi

sarı rüzgarların bozkır yalnızlığından.

ne zaman sorulsam 

ansa beni dağlar

denizleri anlatıyorum.



           GÜZ VE ÖLÜM 

Ölüm

konuğudur güzün

                                                       kasım 1989







İNCİNİRSİN

Sen 

Bir incecik çiçeksin

Üzerinde

Seher çiyi

Anlatsam yansam derdimi

İncinirsin

                                                               ocak 1983





HASRET

Yad ne bilir ne anlar ağyar

Ağlayan gözümden, lalolan dilimden 

Bir sen varsın, gülen hayalin ey yar

Ağman bendedir zulüm revadır elinden.







ANIMSAMA

Eski bir sırrı bölüşürüm dalgalarla

Kıyılar çekip gideli

Deniz kaldı bir başına.







GECE VE DENİZ 

Nasıl da kızgındı atlarımız

Sürmüştük doludizgin uyuyan aya doğru

Taramıştı yelelerini yel ve deniz

Şimdi ne sen, ne atlar...

Vaham çöl, çadırım ıssız







YANGIN

Döker de gözyaşını ağaç acıyla

Yakar çiçeklerini zemheri

Çabuk büyür çocuklar hüznün koynunda







YALNIZLIK

Bugün sularla birlikte

Çekildi aşkın kıyısından sözün hükmü de

Şimdi sıra hüzündedir







TOPRAK 

Toprakta tüm yükü dünyanın

Tohumun doğumu

Ölümü yaprağın

İnsan nasıl da duymaz

Döl kokusunu yağmurun 

Sıcaklığını o büyük şiddetin

Kavgaların, kıyımların





ÇARESİZLİK

Üleşir kaygıyı ezgiler

Suskunluğun da dili var

Söylenir şey değil keder

Çaresizlik dört yanda duvar







KİMSENİN BİLMEDİĞİ

Sızarken içime ilkyazın sıcaklığı

Bir bereketli yağmur olur da 

Düşersin aklıma

Okşarken ıssız tepeleri gün

Kimsesiz yolları

Garip meseller anlatırım sana 

Kimsenin bilmediği

                                          temmuz 1987





YAZIDA KALAN

Ben değilim artık

Kırlarda seğirten

Yazılarda kaldı o çocuk 

Bilmem ki kime seslenem

Tipiler sildi izimi

Uzun, ağır kervanlar

Unuttum kendi yüzümü





YORGUN BAHAR

Böyle midir her zaman usta

Hep güzle mi başlar ayrılıklar

Anlatır esen rüzgar gözlerime bakarak

Onu yürür artık tüm çocuklar 

Her şehir, her sokak

Her güz koynumda gizlerim yorgun bir bahar







GİZEM

Belki de gizemdi her şeyin başlangıcı

Bilinmezlik

                    bir o kadar susuş

Bekleyişlerden sormak

Yanıtlanmamış ne varsa

Hayata ve ölüme dair

Bir çocuğu koklarcasına







AKŞAM 

Göle düşen şiir

Geceyi bırakıyor ardında

Yalnızlığım 

Ezgisi dinmeyen bir lir







KUŞ

Boyadın geceyi kedere

Aşka nedensiz düşülen

En gebe bulutları sevdaya

Ölüm ki bir alışkanlık ve sesin kadar yakındır bu topraklarda

                                                                       eylül 1987







YAŞAMAK

Salınmak saçmayla anlam

Dirimle ölüm

Aşkla yokluk arasında

Paylaşabilmek çılgınlığını bir ağacın 

Okşamak yüzünü rüzgarın

Bir denizin adında







Bir kentin çığlığı olmuşsa sirenler

Sabahı olmayan sokaklarında

Saatler

Yokluğu çalıyorsa her an

Ölüm baharla da gelir artık

Denizler  tufan

Bulutlar kıtlık

Alınır gözlerinden gülüşleri çocukların

Alınır ömürleri düşlerinden 





PİŞMANLIK

Her şey mümkündü

Sevebilirdik belkide

Karşılayabilirdik gün ışığını

Kaygılardan uzak, haz içinde

Her şey mümkündü







Gecenin bu terkedilmiş saatinde

Ninni söylüyor en kederli sesiyle bir anne









Bilmemki nasıl anlatır bir ozan sevdayı

Yitirirken bir bir 

Sözcükler anlamlarını









Anımsayabilsek

Gülmek nasıl bir şeydi

Yeniden koklayabilsek çiçekleri

İlk kez dinlercesine esrik

Dinleyebilsek dalgaların sesini







BEN VE ZAMAN

Salkımsöğüt suya sarkan 

Dönülmez anıların yansısı

Ben ve zaman







DAĞDA GECE

Rüzgar uğuldar

Uluşur köpekler

Uyku yalnızdır

                                       aralık 1989







Ellerin anılarca gizli

Kaldı yağmurlarıyla dost olduğum  şehirde

Dağlara götürdü bulutlar beni

Büyüdüm 

Hangi ıssızlıkta bulurum kendimi

Özgür kuşları gördüm yalnız kokunda

Derin gökleri ölümüme uzayan 

Düşündüm 

Bizde çoğalan her şeyi

Kim anımsar

Antik bir zamana eriştiğinde gençliğimiz

Kalır mı sonsuza şarkılarımız? 





YALNIZ ZAMAN

Yağmur dinmişken henüz

Göçebe umutlar düşer yeryüzüne

Günbatımlarından sağılırken hüznümüz

Bulutlar ne dosttur ne düşman

Unutulur suskunluğun dili konuşmamaktan

Yağmur hangi yaz biter

Yalnız zaman duyulur







GÖRÜŞ

Seni çok eskilerden bilir gibiyim 

Gülüşlerin kanat çırptığı

O sevi ülkesinden 

Bırak sileyim gözyaşlarını

Ellerin avuçlarımda 

Isıtsın 

Anımsatsın ne kaldıysa

Unutuluşun hasadından

Kuşlar göç ediyor 

Çocukluğumun ilkyazına

                                                               ekim 1987



BEKLEYİŞ

En son konuğum yaşamın ve sevinin ülkesinde. Öpüyorum sevincini evrimimin. Söndürüyorum güneşimi. Anladım. Hiçbir yerde yok aşkın karşılığı. Bencil şarkılardır söylenen. Her şey unutmak için ölümü. Sıkı tut zamanı. Yoksa kıyar kendine sevda. Bulutlar erir. Gül damlayıverir. 







ALIŞKANLIK

Avluda çocuk sesleri

Hoparlörde bir bozlak ezan

Vakit öğle

                   güneş bedevi

Uykuda

Damda kedi tarlada saban

Gölgelerin alınları terli

Çeşmenin şırıltısı sessiz

Konuşmalar yağmur duası

Dağlar kimsesiz





YANILSAMA

Biz hep pembe sevdalar düşledik

Bilmedik sensizliği

Dalında sevdik goncayı

Gökyüzünde martıyı

Fener olduk koylarda

Yaktık ağıtlarını eşkıyaların 

Oysa her şey dün gibi

Mavi ve kederli

Yüreklerimizde yok en küçük bir kuşku

Sanki dağda bir akşamüstü

Heybemizde kalan en son şiir

Bütün destanların sonu utku



KUĞU VE ZAMAN

Mutlu olunan zamanlar

O kadar az ki

Ancak çocuklar bilir 

Çiçeklerin dilini

Dün denilen hiçlik

Bellektir yalnızca

Beni süzer kuğular

Su boyunca





BOŞLUK

An gelip de 

Sonuna eriştiğimizde bu yolculuğun

Çılgınca aramaktan

Her zaman başkası olmaktan yorgun

Hangi boyutunda oluruz boşluğun? 







DALGALAR

Bıraksalar kaçacağım dalgalarla

Alıp güzelliğini yanıma

İzin kalsın diye 

Deniz basacağım yarama

                                                          21.6.1995     Didim







SONYAZ

Vefasızca tükenen sonyaz

Bırakmadan gökyüzüne çıplak

Esrik uçtuğu çocukluğunu.

Kıysaydı kendine kanatlı düşlerinde bellek

En sonsuzunda rahmin

Acılar büyümezdi sınırlarında varoluşun

Büyümezdi aşk, ölümcül kelebek.





Yalnız kendine sığınır evren

Tarih ki en derin boşluk

Sessiz ezgisiyle gezegen







İÇ KANAMALAR

Ölüm orucunda yitirdiğimiz canlara

Yüzlerinde nehirlerin gülüşü

Çocuklar 

Ey mavi yeri yüreğin

Öfke sönmeyen nar

Kaçıncı milat ömre sığan

Her isyan rüzgar

Bu kadar çok sevilir mi ölüm ey can

Aşkı vahdet-i vücut

Yanarak akan an 

Umudu bir gizli sükut

Birikir gizli sular

Sorar yüreğin en genç  yerine titreşen lir

Soluktaki iz

Kaç ömür daha ertelenir bahar? 





ARDINDAN

Masalsız 

leyleksiz bir bahar

Engin maviliğe ömrümü bıraksam

Hep şu ağlamak hali içime dolan

Bileydim

Ben de gelirdim ardından







KIYI

Vurulmuş bir tayım

Yorgunum yitik anılar kadar

Bilmem dayanır mı akıntıya kollarım









LİR VE NEHİR

Arar şiir bilişim çağında

Ayırmışlar ezgisinden sonsuz denizi

Hangi yorgun nehir getirir

Suyun sabrında yitik

Derin şarkısındaki gizi

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          





SORU

Mars’ta da keder var mı hocam? 

Orada da çocuklar ağlar mı? 

Genç diri demeden 

Ölüm oraya da uğrar mı? 









BÜROKRASİ

Solum sağım önüm arkam bürokrasi

İnisiyatif: pasif

Kızakta memur

Onur: süresiz izinli  firari asi

Özgürlük mü? Görüldüğü yerde vur! 

Köle: yığın. Müdür: efendi

Aşınır habire ceketlerin düğmesi.







IRMAĞIN SÖYLEDİĞİ

Öperken sesini at

Akıyor dolunaya 

Yalnızca bir andı hayat







ANNE VE ÇOCUK

Ne  tez büyüdüm anne

Bir yanım dağlar bir yanım kar

Sahi o kadar oldu mu 

Gideli akasyalar? 

Duyarım çağırırsın hala pencereden

Bense o yalnız çocuğum dalgın bahçemde.

                        23 / 7 / 1997







 BİR ŞEHRİN SONBAHARINDA YÜRÜYÜŞ

Mehmet Zaman Saçlıoğlu’na

Anlatır zaman 

Sevi ırmaklarını cennetin 

Bakışlar çocukluk

Sesi ya da sessizliği bir köyün

Giz içinde kardelen.

Solgun rüzgarın yaktığı ateş

Yalnız bir keman

Öpülür kesik elleri kalbimin

Akarken sonsuza içimizdeki an.

Çağını öldürüyoruz ihanetin, kıyısında geleceğin

Akşamın şarabında

Sonbaharında bir şehrin. 

Ne çok keder bu gülüşündeki 

der gibiydi gözleri yıldızlı bahçenin

Zamansa akıyordu 

Saçlarında ayın

SEN KONUŞTUĞUN ZAMAN 

Gürhan Uçkan’a

Sen konuştuğun zaman 

Sevinçli şarkılar söyler ağaçlar

Bereketlenir ülkem, mavilenir gecelerim

Bütün köylerim bahar.

Sen konuştuğun zaman 

Döner gelir tüm kayıplar

Kovulur sınırlarımdan yalan

Nehirlerim can.

Sen konuştuğun zaman

Yitiririm kimliklerimi

Gülüşün ki 

Çocuklara armağan

Işır gözleri 

Barışa susayan.

Sen konuştuğun zaman 

Döner dünya 

Cinnetin kıyısından.



İSKENDERUN

Dolaştım kutlu bir günle

Kazındı anılarıma bastığım kaldırımlar

Dokundu omzuma ansızın Triandafilis

Seslendi en hüzünlü sesiyle: “Gitme! ”.







KIYILARIM

Alır da gizlerimi

Vurur kıyılarıma enginliğim

Beni çağırır o sonsuz sularda

Ulaşamadığım ne varsa







ÖZGÜRLÜK

Örerken kordan raylarını içimde sevdan

Delerek dağlarını sabırlı tarihimin

Eritir tacını, tahtını zulmün

Siner dokunduğun her şeye her an

Duyumsadım ilk kez, geçerken ömrümden nehirler

Birikmesini suskun suların, sözcükten bulutların

Benliğimin, kavgasında güzelliğin

Gözlerinde yüzyıllık keder

Martı olmak nedir bildim seninle 

Dansetmek dalgalarıyla sonsuzluğun

Mavisinde derin umutların 

Esrik bir geminin düşünde



BARIŞ

Masalsız, martısız gözleriyle

Ölüm seyirlik,

Alışır mı çocuklar cesetlere

Günlük güneşlik bir dünya

Yaşamak şenlik

Denizlerce  birarada





EŞİTLİK

Mavi masallarla emzirdi halkım

Tanıdım tarlalarında

Alın terini sevdanın

Öfkeyi

Kurşun  hüznünde ağıtların

Güneşi sağdık 

Sırılsıklam siyah bir gecenin içinden

Doyulmazdı o sabahın seyrine 

Yazıldı ilk kez en mutlu şiir

Harç taşıdık o kutlu güne

Kadın erkek, köy şehir, nehir nehir

Bütün ellerde imece

Bitireceğiz bu kitabı, yenilgi yok

Sızar aydınlık her karadan

Yeter ki toplansın atlıları emeğin

Bekliyor düşmeyi bir daha, kalesinde düşman 



BİRİKEN

Meğer biriken 

Bir volkanmış öfkem

Bilmemişim 

Lavdanmış

Geçen ırmaklar içimden

Sesleniyor gece kuşları

Sığındığım düşlerimde

Bütün adreslerim yanlış

Çoğalmalarım linç





SON BAKIŞTA AŞK (*) 

Hüseyin Peker’e

Kaç ömrün sığdığı an

Geçen yıldız düşlerden

Sessizce biliyorum, aşkı ve bilinci

Yiterken gün, ufkunda bakışların

Gülüş ki nehir

Sınanır ezgisinde lir

Solgun çağlar akıyor göğümüze

Haykırabilir her an, en yalnız yerinden öfke

_________________

(*)   Walter Benjamin



AKAN GÜZ

Akıyor anılara güzün ırmağı

Denizine açılan gül akıyor

Tutkuyla devinen ten 

Soluyor huzursuz bulut

Soluyor yiten bakışlar, girdabında bulvarın

Monitörde esen ses donuyor.

Ne çok kaygı, alıp götüren

Yokluk, söğüt, kuşlar, derin gök

Ne acı unutmak 

Bin yıl önceki insanı

Ağlayışı, gülüşü, “sensiz olamam”ı, “güzel kardeşim”i 

“kanatlı sözler”i

Sessizliğime uzayan

Sonsuz iskeletimi. 

Gene de her alevde açan karanfil yüreğim

Kuruyorum sarkacını zamanın, yitmeyen kimliğime 

Yadigar kalemimde elyazılı keder 

Mektuptur ömrüm ölü çocuklara 

Uçurtmalı bir resim.

ÇOCUKLUK

Tozlu yağmurların iç sıkıntısı 

Cama vuran geçmiş 

Kasırga kopan akşamüstleri

Başakların ağırlığındaki çağrı

Bitevi göçerlik kışla gelen 

Zamansız duvarlar 

İklimlerde düşler, kindar tanrılar

Dışarısı ben

Kaldı çay bahçelerinde

Taş plakların böldüğü dalgınlık 

Sinemaların leblebi tadı 

Kokusu doğan kardeş’in

Yağmurun kutsadığı dağ.

Uykuya karışan korku 

Bakıştaki deprem

Kavaklar dallar yapraklar 

Sürer sesinde suyun 

Yorgun tarlalarda horozun sözü.

Tedirgin tadı bahçelerin', 'GÜNAY GÜNER _____________________________ ESKİ YALNIZLIK _______________________________ KISA TARİH henüz adı konmamışken denizlerin izini s...', ARRAY['Türk Edebiyatı','Şiir','Günay Güner']::text[], 8.5, '{"poet":"Günay Güner","poet_slug":"gunay-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":524,"source_url":"https://www.antoloji.com/eski-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
