INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyorum', 'biliyorum-bekir-gedikoglu-fxyel', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '…………başımın ağrıyacağını,

Biliyorum

…………sokaklarda  başı boş dolaşacağımı,

Biliyorum

…………bir çöp bidonuna kusacağımı,

Biliyorum

………… bir sokak lambasının altında sabahlayacağımı,

Biliyorum

…………. evimin adresini unutacağımı,

Biliyorum

sokak köpekleri ile çerezimi paylaşacağımı,

Biliyorum

 ………… sokak köpekleri tarafından yüzümün yalanarak uyandırılacağımı,

Biliyorum,

…………. kötü bir ayyaş olacağımı,

Biliyorum

…………. körkütük sarhoş olacağımı,

Biliyorum

………… adsız bir dilberle ahbaplık kuracağımı,

Biliyorum

………… senden ayrı kalınca nelerle karşılaşacağımı,

……………………………….Sende biliyor muydun? 

…………………………………………………………

…………………….ayrı kalınca neler yaşayacağımı

Ankara,26 Ocak 2004', '…………başımın ağrıyacağını, Biliyorum …………sokaklarda  başı boş dolaşacağımı, Biliyorum …………bir çöp bidonuna kusacağımı, Biliyorum ………… bir sok...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/biliyorum-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlıyorsam Sebebi Var', 'agliyorsam-sebebi-var-demet-kaytan-2gdip', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'AĞLIYORSAM SEBEBİ VAR

Ağlıyorsam sebebi var

Yaşadığım her saatte hatıran var

Bilirsin unutmak kolay değil

Nefes almak bile zor gelir 

Sus şimdi söyleme

Hazır değilim bu gidişe

Zaman dursun ışıklar sönsün

Son bir defa

Sür hasreti denizlere

Karışsın derinlere

Alışamam gidişine

Yine yeniliyorum', 'AĞLIYORSAM SEBEBİ VAR Ağlıyorsam sebebi var Yaşadığım her saatte hatıran var Bilirsin unutmak kolay değil Nefes almak bile zor gelir  Sus şi...', ARRAY['Türk Edebiyatı','Şiir','Demet Kaytan']::text[], 8.5, '{"poet":"Demet Kaytan","poet_slug":"demet-kaytan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/agliyorsam-sebebi-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakışların Aklımda', 'bakislarin-aklimda-demet-kaytan-dv4kz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'BAKIŞLARIN AKLIMDA

Gözlerini kaçırsanda

Bakışların aklımda

Ellerini çeksende

Sıcaklığın var hâlâ

Bir küser bir barışırdık

Ayrı düşsek savaşırdık

Herşeye rağmen

Aynı dünyada kalırdık

Bir bedende yaşardık

Taş koydular yollarıma

Yarım kaldı aşkımızda

Rüya dediler olanlara

İnanmadılar aşkımıza', 'BAKIŞLARIN AKLIMDA Gözlerini kaçırsanda Bakışların aklımda Ellerini çeksende Sıcaklığın var hâlâ Bir küser bir barışırdık Ayrı düşsek savaşı...', ARRAY['Türk Edebiyatı','Şiir','Demet Kaytan']::text[], 8.5, '{"poet":"Demet Kaytan","poet_slug":"demet-kaytan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bakislarin-aklimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşverdim', 'bosverdim-demet-kaytan-cbuuf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kime sorayım yıllarımın hesabını

Saçlarıma aklar düştü haberin varmı

Toz pembe dünyam vardı birde hayallerim

Sadece sevgi istedim haberin varmı

Boş verdim ben aşka kanmam asla yalana

Sevip sevip bir daha yanmam asla yıllarca', 'Kime sorayım yıllarımın hesabını Saçlarıma aklar düştü haberin varmı Toz pembe dünyam vardı birde hayallerim Sadece sevgi istedim haberin va...', ARRAY['Türk Edebiyatı','Şiir','Demet Kaytan']::text[], 8.5, '{"poet":"Demet Kaytan","poet_slug":"demet-kaytan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bosverdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Bir Gün', 've-bir-gun-taner-nisanci-o9o8e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dimağımda adın kalarak

Hoşça kal diyeceğim sana

En yalnız halim  bırakarak

Gideceğim,elce yabana

Gözlerimde birkaç damla yaş

Sözüm sitem olacak sana

Ne sevgili, ne dost, arkadaş

Kimsin sen, diyeceğim sana

Ve bir gün, bir köşede bedbaht

Kırgın tavrım olacak sana

Aziz hatıratından,hey hat

Tebessümün kalacak bana

                                      2003', 'Dimağımda adın kalarak Hoşça kal diyeceğim sana En yalnız halim  bırakarak Gideceğim,elce yabana Gözlerimde birkaç damla yaş Sözüm sitem ola...', ARRAY['Türk Edebiyatı','Şiir','Taner Nişancı']::text[], 8.5, '{"poet":"Taner Nişancı","poet_slug":"taner-nisanci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ve-bir-gun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aradım', 'aradim-demet-kaytan-wz72k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Alıp başımı gidersem 

Bu yardan vazgeçersem

Beni sakın kınamayın

Hayırsız zannetmeyin

Selam vermeden gidersem

Derdimi toprağa dökersem

Ardımdan ağıtlar yakmayın 

Soruda sormayın

Ben kendimi çok aradım 

Aradım aradım bulamadım

Geçen her güne 

Geçen her geceye

Çizik attım

Çok sevdim saatlerce ağladım 

Çok sevdim kan ağladı yüreğim

Anladım kadere inanmalım 

Anladım acıya dayanmalıyım

Kimbilir yalnızlığa alışmalıyım

Umuda sarılmalıyım 

Allah’a sığınmalıyım

Geçen her güne 

Geçen her geceye

El açıp yalvarmalıyım', 'Alıp başımı gidersem  Bu yardan vazgeçersem Beni sakın kınamayın Hayırsız zannetmeyin Selam vermeden gidersem Derdimi toprağa dökersem Ardım...', ARRAY['Türk Edebiyatı','Şiir','Demet Kaytan']::text[], 8.5, '{"poet":"Demet Kaytan","poet_slug":"demet-kaytan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/aradim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmez Aşkımız', 'bitmez-askimiz-demet-kaytan-375il', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ecelim gelsede yine seni ararım

Son nefesimde bile seni yaşarım

İçim daralır yollarına bakarım

Gelirsin diye adını sayıklarım

Bitmez aşkımız böyle kolay bitemez

Dilim söylemeye varmaz aklım almaz

Bu gidişin sonu hayra yorulamaz

Seven kalbim kolay kolay unutamaz

Zannetme bu hayat bensiz güzel olur

Dostum dediklerin senden kaçar olur

Yokluğum seni gün geçtikçe soldurur

Sanma aşkımız zamanla unutulur', 'Ecelim gelsede yine seni ararım Son nefesimde bile seni yaşarım İçim daralır yollarına bakarım Gelirsin diye adını sayıklarım Bitmez aşkımız...', ARRAY['Türk Edebiyatı','Şiir','Demet Kaytan']::text[], 8.5, '{"poet":"Demet Kaytan","poet_slug":"demet-kaytan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bitmez-askimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zalim', 'zalim-demet-kaytan-amvqt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerine yandım gözlerine

Bakışların ölümden de öte

Adın yıllardır dilimde

Yüreğime kazıdım gizlice

Zalimsin zalim

Dertten anlamaz hain

Sevmek suçsa söyle bileyim

Seni kalbime gömeyim', 'Gözlerine yandım gözlerine Bakışların ölümden de öte Adın yıllardır dilimde Yüreğime kazıdım gizlice Zalimsin zalim Dertten anlamaz hain Sev...', ARRAY['Türk Edebiyatı','Şiir','Demet Kaytan']::text[], 8.5, '{"poet":"Demet Kaytan","poet_slug":"demet-kaytan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/zalim-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolunu Beklerim', 'yolunu-beklerim-demet-kaytan-9ha8h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Boşuna yalan söyleme sende sevdin

Sende kalbini bu ateşle dağladın

Yine yolculuk zamanı geldi gittin

Kadere yenik düştük yine ayrıldık

Yolunu beklerim geceleri rüyamda

Yolunu beklerimündüzleri camlarda

Seni sorarım uçan kuşalara

Seni sorarım esen rüzgara

Seni sorarım yağan yağmura

Gelene gidene yıldızlara

Yolunu beklerim ümüdim koynumda

Aklım karmakarışık yüreğim buruk 

Yolunu beklerim ümidim koynumda

Geceleri hayallerde düşlerimde

Seni sorarım uçan kuşalara

Seni sorarım esen rüzgara

Seni sorarım yağan yağmura

Gelene gidene yıldızlara

Yolunu beklerim geceleri rüyamda

Yolunu beklerimündüzleri camlarda', 'Boşuna yalan söyleme sende sevdin Sende kalbini bu ateşle dağladın Yine yolculuk zamanı geldi gittin Kadere yenik düştük yine ayrıldık Yolun...', ARRAY['Türk Edebiyatı','Şiir','Demet Kaytan']::text[], 8.5, '{"poet":"Demet Kaytan","poet_slug":"demet-kaytan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yolunu-beklerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Telli Turnam Hasret Bindi Dalıma', 'telli-turnam-hasret-bindi-dalima-sair-divane-jtzpk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Telli durnam hasret bindi dalıma 

Felek ayrılık çıkardı yoluma

Al benide kanadının ucuna

Götür nazlı yarin yanına bırak

Yolunu bulursun hak buldurursa

Menzile varırsın o vardırırsa

Eğer RABBİM sana izin verirse

Götür nazlı yare bir selam bırak

Selamımı söyle öp gözlerinden

Bahset ona dağ gibi özlemimden

Sevgi götür yaralı yüregimden

Götürde ayağının dibine bırak

Hasret can evimde sevdigim ırak

Gönlümün topragı sen yokken çorak

Telli turnam banada öğret uçmak

Al beni götür sılama bırak', 'Telli durnam hasret bindi dalıma  Felek ayrılık çıkardı yoluma Al benide kanadının ucuna Götür nazlı yarin yanına bırak Yolunu bulursun hak ...', ARRAY['Türk Edebiyatı','Şiir','Şair Divane']::text[], 8.5, '{"poet":"Şair Divane","poet_slug":"sair-divane","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/telli-turnam-hasret-bindi-dalima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yunus Gibi', 'yunus-gibi-sair-divane-zvrqn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yunus gibi bir sevdaya tutuldum

Alıp beni götürdü yükseklere

Bu sevdadan ben bir çift kanat buldum

Bu sevda ile kanat açtım göklere

Rüzgar olup estim bazı dağlara

Bazı yağmur olup yağdım çöllere

Umut oldum yaralı gönüllere

Bu sevda ile kanat açtım göklere

Kartal oldum yüce dağlarda uçtum

Yunus oldum denizleri dolaştım

Yolcu oldum nice yolları aştım

Bu sevda ile kanat açtım göklere

Elimden tuttular pirler erenler

Kalp gözüyle hakikati görenler

Divane kulada destur verdiler

Bu sevda ile kanat açtım göklere', 'Yunus gibi bir sevdaya tutuldum Alıp beni götürdü yükseklere Bu sevdadan ben bir çift kanat buldum Bu sevda ile kanat açtım göklere Rüzgar o...', ARRAY['Türk Edebiyatı','Şiir','Şair Divane']::text[], 8.5, '{"poet":"Şair Divane","poet_slug":"sair-divane","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yunus-gibi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdaya Yenildim', 'sevdaya-yenildim-sair-divane-jc7wh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yorgun savaşçıyım

Ruhum bitap düştü

Elimde sancagım

Yollara yenildim sevgilim

Gerçi ayaktayım

Yıldıramadı beni hiçbir düşman

Ağardı saçlarım

Yıllara yenildim sevgilim

Kim bilir bunca yıl umutla

Bekledigim belki bir düştü

Bomboş beklerken kollarım

Hasrete yenildim sevgilim

Beklemekten yıldı gönlüm

Kalbim kaderime küstü

Ama hala umutlara açık bağrım

Sevdaya yenildim sevgilim', 'Yorgun savaşçıyım Ruhum bitap düştü Elimde sancagım Yollara yenildim sevgilim Gerçi ayaktayım Yıldıramadı beni hiçbir düşman Ağardı saçlarım...', ARRAY['Türk Edebiyatı','Şiir','Şair Divane']::text[], 8.5, '{"poet":"Şair Divane","poet_slug":"sair-divane","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevdaya-yenildim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Gelmek İstiyorum', 'sana-gelmek-i-stiyorum-sair-divane-fzatj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aramızda sıra dağlar 

Sana gelmek istiyorum

Saçlarıma yağdı karlar

Sana gelmek istiyorum

Hasret ara yerde perde

Beni gonca gülüm nerde

Bir de sevdalık var serde

Sana gelmek istiyorum

Hasret acı, Vuslat uzak

Bu engeller bize tuzak

Özlüyorum bana yazık

Sana gelmek istiyorum

Aç kalbimi bak içine

Bilmem gönlümün suçu ne

Hasret gidiyor gücüme

Sana gelmek istiyorum

Kalbim hasretinden ezik

Ayrılık elinden bezik

Merhamet et bana yazık

Sana gelmek istiyorum

Sen ışık ben pervanenim

Aşk ile dönüp yanarım

Senin deli divanenim

Sana gelmek istiyorum', 'Aramızda sıra dağlar  Sana gelmek istiyorum Saçlarıma yağdı karlar Sana gelmek istiyorum Hasret ara yerde perde Beni gonca gülüm nerde Bir d...', ARRAY['Türk Edebiyatı','Şiir','Şair Divane']::text[], 8.5, '{"poet":"Şair Divane","poet_slug":"sair-divane","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sana-gelmek-istiyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlar Gördüm Ben', 'yildizlar-gordum-ben-demet-kaytan-p5jyj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne yıldızlar gördüm ben avuçlarıma düşen

Benim hayalim sadece sen sıradan yaşam

Ne günler geçirdim ben saçlarımı beyazlatan

Sadece senle yaşadım düğünü ölümü

Ne yollardan geçtim ah ben ne yollardan

Bu sevdanın yükünü gamını kederini

Dinlermisin ki sana çaldığım şarkıları

Anlatsam anlarmısın beni gecelerimi

Aklıma geldin ya gecenin karanlığında

Resimlerin bir bir başucumda koynumda

Bir yangına düştüm canım yanar içim sızlar

Kör kuyulara düştüm ah kalbin geçit vermez', 'Ne yıldızlar gördüm ben avuçlarıma düşen Benim hayalim sadece sen sıradan yaşam Ne günler geçirdim ben saçlarımı beyazlatan Sadece senle yaş...', ARRAY['Türk Edebiyatı','Şiir','Demet Kaytan']::text[], 8.5, '{"poet":"Demet Kaytan","poet_slug":"demet-kaytan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yildizlar-gordum-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımız Var Ara Yerde', 'askimiz-var-ara-yerde-sair-divane-drrce', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hasret ne ki sevdicegim

Hasret çekilmiş bir perde

Hasret bizi ayıramaz

Aşkımız var ara yerde

Nasıl ki mevsimler geçer

Kışlar bitip bahar yeter

Elbet bu hasretlik biter

Aşkımız var ara yerde

Sevdam deniz hasret damla

Ayıramaz bizi asla

Gel sarılalım umuda

Aşkımız var ara yerde

Sayılı gün geçer elbet

Gülüm biraz daha sabret

Kanat takıp gelir vuslat

Aşkımız var ara yerde

Güzel gözlerin dolmasın

Umutların hiç solmasın

Kalbin sitem bağlamasın 

Aşkımız var ara yerde

Herşey yalan sevda gerçek

Elbet bu hasretGeçecek

Arzu ettiğin gelecek

Aşkımız var ara yerde

Allah bir Hakkı -çün böyle

Vuslat senin yüreginde

Birgün çekilir bu perde

Aşkımız var ara yerde', 'Hasret ne ki sevdicegim Hasret çekilmiş bir perde Hasret bizi ayıramaz Aşkımız var ara yerde Nasıl ki mevsimler geçer Kışlar bitip bahar yet...', ARRAY['Türk Edebiyatı','Şiir','Şair Divane']::text[], 8.5, '{"poet":"Şair Divane","poet_slug":"sair-divane","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/askimiz-var-ara-yerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Firariler', 'firariler-i-smail-bitmez-1pcou', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Arksız ırmakların delhizleri

Çıkartırmı ütopyalara

Labirentlere sığınan

Döngülerden sıkılmış firarileri

Şelalelere duyurmadan', 'Arksız ırmakların delhizleri Çıkartırmı ütopyalara Labirentlere sığınan Döngülerden sıkılmış firarileri Şelalelere duyurmadan...', ARRAY['Türk Edebiyatı','Şiir','İsmail Bitmez']::text[], 8.5, '{"poet":"İsmail Bitmez","poet_slug":"i-smail-bitmez","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/firariler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuz Aşk Denen Yalan', 'sonsuz-ask-denen-yalan-gokhan-yazici-yfflm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dünya bir tane

Ama dünyalar pek çok

Onlarca dünyanın

Biri senin,

Biri benim

Biz aşk felsefesinin iflas ettiği

İsteklerin ziyanıyız

Biz ikimiz

Bambaşka dünyaların insanıyız

Kalıcı hiç bir şey yok dünyada

Tek kalıcı ölüm var

Sonsuz aşk denen yalan

Yalan

Masallar kadar

(İstanbul 1990)', 'Dünya bir tane Ama dünyalar pek çok Onlarca dünyanın Biri senin, Biri benim Biz aşk felsefesinin iflas ettiği İsteklerin ziyanıyız Biz ikimi...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Yazıcı']::text[], 8.5, '{"poet":"Gökhan Yazıcı","poet_slug":"gokhan-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sonsuz-ask-denen-yalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay, Üç Yıldız, Yakamozlar', 'ay-uc-yildiz-yakamozlar-ozlem-torkul-tekan-p95az', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gecenin aşkıyla mı titriyor yıldızlar

Yoksa sırlı semanın rakkasları mı onlar.

Kimdir bu tabloyu hazırlayan sanatkar

Mavi perdede ay, üç yıldız ve yakamozlar.

Cihana uyar mı biçtiğiniz kılıflar

Gül, diken, pul ve kan aynı kazanda kaynar.

Atlasın eteğine takılmış çuvaldızlar

Mavi perdede ay, üç yıldız ve yakamozlar.

30 Mart 2002 / 02:16', 'Gecenin aşkıyla mı titriyor yıldızlar Yoksa sırlı semanın rakkasları mı onlar. Kimdir bu tabloyu hazırlayan sanatkar Mavi perdede ay, üç yıl...', ARRAY['Türk Edebiyatı','Şiir','Özlem Torkul Tekan']::text[], 8.5, '{"poet":"Özlem Torkul Tekan","poet_slug":"ozlem-torkul-tekan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ay-uc-yildiz-yakamozlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem Denizi', 'ozlem-denizi-ozlem-torkul-tekan-90bzo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geçmişin kuytu köşesinde gizli 

Unutulmuş bir sürgün hikayesi. 

Tozlu, kırık, dökük ve eski 

Bir o kadar da anlaşılmaz belki... 

Hüznün miladı neydi bilinmez ki 

Gurbet her iklimin nazlı dilberi 

Ağaran tana nispet olsun bari 

Yeniden doğuşlar, taze ve diri... 

Vefa küsmüş bize, uzlette şimdi 

Yılanlar bekliyor her hazineyi. 

Kaç asırlık çınarlar devrildi. 

Sırmalı mintandı bahaneleri... 

Zamansız çalan ecel çanı gibi 

Yeri göğü altüst edip gideni 

Vuracak mı ruhun vicdan neferi 

Kınınında yenik kılıç misali... 

Parlayan yıldız, zühre ve zuhali 

Gözler görmediyse gönüller seçti. 

Sır gemisi o limanda demirli 

Yılmadan bekliyor özlem denizi... 

(11 Ocak 2002)', 'Geçmişin kuytu köşesinde gizli  Unutulmuş bir sürgün hikayesi.  Tozlu, kırık, dökük ve eski  Bir o kadar da anlaşılmaz belki...  Hüznün mila...', ARRAY['Türk Edebiyatı','Şiir','Özlem Torkul Tekan']::text[], 8.5, '{"poet":"Özlem Torkul Tekan","poet_slug":"ozlem-torkul-tekan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ozlem-denizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sis', 'sis-i-smail-bitmez-pu6mj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yerle göğü birleştiren sis

Gözkapaklarımızı perdeleyince

Körebe oynadık o gece

Can kurtaranının kazların olduğu

Buharlaşan ırmağa itti gölgenin eli bizi

Çömlekçinin şekillendirdiği

Üstüne süslü boyalar serpilen 

Çamur olduk sonunda', 'Yerle göğü birleştiren sis Gözkapaklarımızı perdeleyince Körebe oynadık o gece Can kurtaranının kazların olduğu Buharlaşan ırmağa itti gölge...', ARRAY['Türk Edebiyatı','Şiir','İsmail Bitmez']::text[], 8.5, '{"poet":"İsmail Bitmez","poet_slug":"i-smail-bitmez","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sis-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erken', 'erken-pis-kedi-abc5j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'I

Seni tanımak için çok erken.

Kırılmış bir vazo

Nasıl yapıştırılamazsa

Boynu bükük kırık çiçekleri

Koruyamazsa artık,

Bir kalp içinde.

Ölüm gibi ansızın

Ölüm gibi tekrarsız

Ve ölüm gibi anlamlı 

Aşk.

Seni tanımlamak için 

Çok,çok  erken.

Derinlerine inecek 

Nefesim yok.

Yorulmuşum,

Hareket edemem

Güçsüzüm.

Küçük bir yelkenlim 

Olsa 

Senin sularına açılmak için.

Rüzgarın alabora eder beni

Batarım senin sularında

Senin yollarında

Senin kurbanın olurum.

Telefonlar ve

Saatler beraber

Çalışır benim inimde.

Bir şekilde ararsın beni

O zaman sesinde ararım seni

Sözcüklerinde.

Saatler,sözcükler,gözler,yelkenlim,kollarım,bacaklarım,rüzgarın...

Anlamlı parçalar,

Bütün olmaktan uzak.

Seni tanımak için çok erken! 

Aşk bu

Bana hangi durakta ineceğimi

Sölemediler.', 'I Seni tanımak için çok erken. Kırılmış bir vazo Nasıl yapıştırılamazsa Boynu bükük kırık çiçekleri Koruyamazsa artık, Bir kalp içinde. Ölüm...', ARRAY['Türk Edebiyatı','Şiir','Pis Kedi']::text[], 8.5, '{"poet":"Pis Kedi","poet_slug":"pis-kedi","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/erken-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın ile yanmaya geldi bu can', 'askin-ile-yanmaya-geldi-bu-can-sair-ahrazi-ucsiz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mevzu gibi ismine yaz canımı,

Sende seni anmaya geldi bu can.

Aşkına pınar gibi dök kanımı,

Sende sana kanmaya geldi bu can.

Söz bile susuz,manadır baharı,

Hükmü dile sardı,yaşar kahırı,

Elveda eder gibi son şehiri,

Sende sana dönmeye geldi bu can.

Her nasibe aşkı sual ederek,

Her düşümü hayra meal ederek,

Ömrümü yolunda helal ederek,

Sende sana yanmaya geldi bu can,

Serhatimi al da esirin olam,

Sar taşına kıble deyipte kalam,

Dünya bana gülse biter mi çilem? 

Sende sana sönmeye geldi bu can.

 ahrazi de Mevla için dolanır,

vakti zamanında kapım çalınır,

Azrail’e yok der isem alınır,

Aşkın ile yanmaya geldi bu can.', 'Mevzu gibi ismine yaz canımı, Sende seni anmaya geldi bu can. Aşkına pınar gibi dök kanımı, Sende sana kanmaya geldi bu can. Söz bile susuz,...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/askin-ile-yanmaya-geldi-bu-can-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğim Çatırdıyor...', 'yuregim-catirdiyor-i-brahim-ethem-bingul-9czjy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüreğim çatırdıyor be güzelim

İçim kaldırmıyor hatırlamayı

Bu ilk çay içtiğimiz parkı...

Ne ağır şeymiş be tatlım

Dayanamıyorum...

Hani nerde kaldı 

Yaşamla ölümün farkı...

Seni seviyorum demek ne ifade eder ki

Binlerce defa olsa bile

Ben burda senden ayrı

Sen orda uzak ellerde gayrı...

Kalbimi hissetmedim,yerine hançer koymuşlardı

Batıyordu oraya,yakıyordu

Ve damarlarımda hissettim aynı acıyı

Bir haberi duymak bu kadar ağır olmamalıydı...

Gelemezdim,göremezdim güzelimi

Ateşlerde yanan yanağına süremezdim elimi,

Sırma saçlarında ellerimi dolaştırıp,

Göğsüme bastıramazdım gamzelimi...

İçim katılıyor be tatlım

Dayanamıyorum...

Bağrımdan söküp ciğerlerimi sana göndereyim,

Ölümsüzlük ilacı bulup,gelip sana içireyim...

Ama ne çare dilberim...

O an gelipte kavuştuğunda Rab''bime

Arkandan bende gelirim,hiç merak etme...', 'Yüreğim çatırdıyor be güzelim İçim kaldırmıyor hatırlamayı Bu ilk çay içtiğimiz parkı... Ne ağır şeymiş be tatlım Dayanamıyorum... Hani nerd...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yuregim-catirdiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köy Kahvesinde Saz Dinletisi', 'koy-kahvesinde-saz-dinletisi-i-brahim-bayraktar-5m4t7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Salaş bir köy kahvesinde çayımı yudumluyorum; 

Dertli dertli çalan bir ozan; 

Oturtmuş alnına bir ömrün yorgunluğunu,

Neler hissettiği yüzünden okunuyordu.

Derin bir of çekti söze başlamadan,

Belli ki içlenmişti, gözleri dolu dolu,

Meşk ediyordu çevreyi aldırmadan,

Bezgin bakışları yüreklere dokunuyor,

Duyguları sözünden okunuyordu.

Gece gündüz çağlayan yar,

Yüreğimi dağlayan yar,

Beni hayata bağlayan yar,

Senden başka konum mu var? 

Dilim seni söyler, seni düşünür, 

Ciğerim sancı kispetini kuşanır,

Sensiz bu hayat nasıl yaşanır,

Senden başka sonum mu var? 

Altüst oldu hayatımın seyrüseferi,

Kalbim, gözümden habersiz,

İçin için ağlıyordu,

İki tombul yaş süzüldü gözümden, 

Birine dur desem, diğeri seferi.

28.01.2004', 'Salaş bir köy kahvesinde çayımı yudumluyorum;  Dertli dertli çalan bir ozan;  Oturtmuş alnına bir ömrün yorgunluğunu, Neler hissettiği yüzün...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/koy-kahvesinde-saz-dinletisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nakaratlar', 'nakaratlar-aynur-uluc-dju7h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Babam kalacak sanırdım hep o mola yerlerinde 

Çocuk aklımla korkardım

Sanırdım ki

Orada bitecek hikaye

Orada duracak zaman

Öyle olur ya film rulolarında

Bir şarkı mırıldanırdım yollarda

“Sana susadım” diyerek

Henüz gerçekleşmemiş 

Bir ölüme ağlardım 

Döndüğündeyse ok geriye

Olmamış saymak istiyor insan

Morgu bilmemiş olmak istiyor

Küçük anları yaşatıp hafızada

Mikado çöplerini arıyor minik balkonda

Nereye gitse götürüp 

İçinde taşıyor 

Nakaratları rüyalara yedirip

Yeniden diriltiyor bir çocuk bir adamı

Yeniden 

Diriltiyor

Çocuk

Adamı…', 'Babam kalacak sanırdım hep o mola yerlerinde  Çocuk aklımla korkardım Sanırdım ki Orada bitecek hikaye Orada duracak zaman Öyle olur ya film...', ARRAY['Türk Edebiyatı','Şiir','Aynur Uluç']::text[], 8.5, '{"poet":"Aynur Uluç","poet_slug":"aynur-uluc","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/nakaratlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Portakal Bahçesi', 'portakal-bahcesi-mesut-fidan-uunge', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'O sahil köşesinde otururken kendi kendime dedimki

İşte  sensin  aradığım  kişi sensin ama bunu bir türlü

Sana  söyleyemedim  kim bilir  belkide şımarmandan 

Beni terk etmenden  korktum ama beni en çok

Üzen ne oldu biliyormusun beni en çok üzen tam

Buldum derken kaybetmek işte beni ençok üzen 

Bu oldu hani  o  gece  sana söyleyememiştim  ya

şimdi  söylüyorum

                              SENİ SEVİYORUM  SENİ SEVİYORUM

                                                                        SENİ SEVİYORUM', 'O sahil köşesinde otururken kendi kendime dedimki İşte  sensin  aradığım  kişi sensin ama bunu bir türlü Sana  söyleyemedim  kim bilir  belk...', ARRAY['Türk Edebiyatı','Şiir','Mesut Fidan']::text[], 8.5, '{"poet":"Mesut Fidan","poet_slug":"mesut-fidan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/portakal-bahcesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Natalie', 'natalie-ferit-teksoy-cmnz6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'uzun sarı saçların,

mavi güzel gözlerinle

bir kanarya sevgime

bir sevgi de 

sen ekledin 

Natalie..

arı-duru 

tertemiz bir yürecik

dobra,naturel,güzel

berrak bir su gibi içilesi

neredeydin susamışken?

Natalie..

bir bahar dalısın 

henüz açılan

taze bir tomurcuk,

bir gonca

mevsimlere hiç kızmazdım

severdim

seni tanıyınca kızdım 

Natalie..

ne vardı? .. 

birazcık erken gelseydin

şöyle biraz erken

yirmi yıl kadar

hep barışık yaşıyordum 

ben oysa

senelere senden önce 

Natalie..', 'uzun sarı saçların, mavi güzel gözlerinle bir kanarya sevgime bir sevgi de  sen ekledin  Natalie.. arı-duru  tertemiz bir yürecik dobra,natu...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/natalie-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereye Bir Tanem', 'nereye-bir-tanem-taciser-kaygisiz-o51mc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nereye bir tanem,

Emir büyük yerden olsada, kahrolmamak eldemi,

Eldemi yıkılmamak, kahretmemek.

Nereye bir tanem nereye,

En zoruda bir daha dönmeyeceğini bilmek.

Yarım kalmış şişede parfümün,

Henüz bitmemişti şişteki örgün,

Pardesünü dolaba asmamışsın,

Nereye bir tanem, daha çocuğu okuldan alacaktın.

Söyle bir tanem,

Nasıl bırakırsın,nasıl böyle öksüz, böyle yıkık, söyle.

İşte böyle bırakıverdin bizleri.

Daha nice bayramlar geçirecektik seninle.

Daha kızımızı evlendirecektik.

Hayaller kurardın ne güzeldi, bazen içlenip ağlardın.

Böyle olacağını nerden bilirdin.

Hala sıcak oturduğun koltuk.

Ocakta yemeğin.

Sigaran duruyor masada.

Para çantan açık, para vermişsin kapıcıya.

Bir tanem ne güzel ayrılmıştık,öpmüştün sevgiyle beni,

Dualar; demiştin peşimden.

Ah söyle neden böyle erken.

Sen doymadan bize hayata,

Biz doymadan sana,

Ah bir tanem bir anda, bir anda.', 'Nereye bir tanem, Emir büyük yerden olsada, kahrolmamak eldemi, Eldemi yıkılmamak, kahretmemek. Nereye bir tanem nereye, En zoruda bir daha ...', ARRAY['Türk Edebiyatı','Şiir','Taciser Kaygısız']::text[], 8.5, '{"poet":"Taciser Kaygısız","poet_slug":"taciser-kaygisiz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/nereye-bir-tanem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duman Duman', 'duman-duman-ahmet-kurt-o6flt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sakın kaş çatarak yakma içimi 

Yine dağlarımda duman var duman. 

Sırrımı hüznüme aşikar etme, 

Yine dağlarımda duman var duman. 

Meçhule yürürüm yollar dolaşık, 

Ayrırır toplarım izler karışık, 

Çırpınıp duruyor bir garip aşık, 

Yine dağlarımda duman var duman. 

Yitirdim özümü şaşkın elinde, 

Şaşkınlığım türkü oldu dilimde, 

Ararım izleri bütün ilimde, 

Yine dağlarımda duman var duman. 

Baktığım her yerde durur cemalin, 

Bir selam vermeye yok mu mecalin, 

Kurdoğlu tutmadan gelip ecelin, 

Yine dağlarımda duman var duman.', 'Sakın kaş çatarak yakma içimi  Yine dağlarımda duman var duman.  Sırrımı hüznüme aşikar etme,  Yine dağlarımda duman var duman.  Meçhule yür...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/duman-duman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmeye Terk Eder miydin?', 'olmeye-terk-eder-miydin-ali-osman-yilmaz-0cm9o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her yer karla kaplı,

Beyaz gelinliğini giymiş doğa,

Bense beyaz ölümü düşlerim,

Bembeyaz kefenler içinde.

Seni düşünüyorum şimdi,

Ellerin ellerimde,

Gözlerim mavi gözlerinde,

Telli duvaklı bembeyaz,

Gelinliğinin içinde.

Dışarda yağan kar’a ve,

Gelinlik beyazlığına bakarken,

Daldığım düş dünyam,

Binlerce bahar’ın ve,

Binlerce Güz’ün anısına

Aldı götürdü beni,

Kendimi bir kez daha,

Gözden yitip,sessizlikte saklanan,

Hayaletlerin önünde,

Dikilirken buluverdim,

Her yanı kaplamış sessizlik,

El ele tutuşmuşlar,ikimiz gibi,

Sessizliğimiz ve yalnızlığımız.

Seni her düşlediğimde,

Sen sisler arasındasın,

Hayalinin kulağına,

En kutsal sözleri,ilahileri,

Fısıldadığımı biliyor musun? 

Eğer bilseydin güzelim,

Bana yazmayı bırakmaz,

Yalnızlık kalesinde beni,

Sessizliğinle bir hücrede,

Ölmeye terkeder miydin?', 'Her yer karla kaplı, Beyaz gelinliğini giymiş doğa, Bense beyaz ölümü düşlerim, Bembeyaz kefenler içinde. Seni düşünüyorum şimdi, Ellerin el...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/olmeye-terk-eder-miydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bad-ı Saba', 'bad-i-saba-durhasan-kafali-v7joj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yolun düşer yar evine uğrarsan,

Var selvi boylumu gör seher yeli.

Eğer inci dişlim uykusundaysa,

Evine sessizce gir seher yeli.

Varıp makamına ona divan dur,

Götürdüğün kalbi tanımış mı sor,

Önce eğil eteğine yüzler sür,

Payine gizlice er seher yeli.

Aşkımı abartma zaten çok büyük,

Kalksın üstümdeki bu koskoca yük.

Aşkından bir tadan yaşar mı ayık? 

Ha bunu da deyiver seher yeli.

...', 'Yolun düşer yar evine uğrarsan, Var selvi boylumu gör seher yeli. Eğer inci dişlim uykusundaysa, Evine sessizce gir seher yeli. Varıp makamı...', ARRAY['Türk Edebiyatı','Şiir','Durhasan Kafalı']::text[], 8.5, '{"poet":"Durhasan Kafalı","poet_slug":"durhasan-kafali","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bad-i-saba-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taşlama-1', 'taslama-1-durhasan-kafali-t9knu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Benim şiirime çocukça demiş biri,

Yazsın da Görelim adam gib şiiri.', 'Benim şiirime çocukça demiş biri, Yazsın da Görelim adam gib şiiri....', ARRAY['Türk Edebiyatı','Şiir','Durhasan Kafalı']::text[], 8.5, '{"poet":"Durhasan Kafalı","poet_slug":"durhasan-kafali","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/taslama-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlu ve Memnunmusun?', 'mutlu-ve-memnunmusun-ali-osman-yilmaz-ef40o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seninle ilgili,

En küçük şeyler bile,

İçimde,uzak ve gizemli,

Anılarımı karıştırıyor.

Beni alıp,geçip gitmiş,

O günlere taşıyarak,

Geleceğin penceresinden,

Geçmiş günlere bakmamı,

Söylüyor bana yavaşça.

Şimdi oralarda,

İşinden mutlu 

Ve memnun musun? 

Bense ne mutluyum,

Nede memnunun halimden.

Aç gözlülüğe benzemeyen,

Bir şeyler var içimde,

Hiçbir zaman mutlu olmamış,

Yoksulluğa da benzemeyen.

Ta derinlerimde bir şey,

İkinci bir nabız atmakta,

O mektubundan bu yana,

Süregelen bir acıda var,

Ondan sanırım,ne mutluluğum,

Ne memnuniyetim yok,

Kimseden yakınmıyorum da.

Çünkü memnuniyet aslında,

Bir tatmin,bir doyumdur,

Doyumsa sınırlı bir şeydir,

Mutluluksa daha başka,

Yaşam şarabını içmedikçe,

Gelmez mutluluk,yanına,

Mutluluğu anlayamazsın,

Hayyam’dan Neyzen’e,

Ta ezelden bu yana,

Yaşam kadehini bir yudumda,

Sevda diye,aşk niyetine,

Doya doya içmedikçe.', 'Seninle ilgili, En küçük şeyler bile, İçimde,uzak ve gizemli, Anılarımı karıştırıyor. Beni alıp,geçip gitmiş, O günlere taşıyarak, Geleceğin...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/mutlu-ve-memnunmusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoban Yalnızlığı', 'coban-yalnizligi-ahmet-kose-r2pwo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben savrulan notalarla sana

aç susuz dans ederken birlikte Edıth Pıaf sesinde

sahipsiz bir kuzu yüreğim bakarken

senin sahil gözlerine kış vakti.

Yalnızlığım bir çobanın izleri

geçer aşk sürüleri üzerimden.

Bölük pörçük geliyor damlaları yaşamın

bağlı yüreğim sularına

kopuk filmler geçiyor perdeden

sonunda düşüyor bakışlar ayak altlarıma

sen hiç aklımda yok iken.

Duvar dipleri,

kapı eşikleri

uzun yol yürüyüşleri geçiyor usumdan

tırmanırken bir yandan son yokuşlara.

En salaş anlarında yüreğimin

salınmış suları aşk kuyularımın

değirmenler gözlerime bağlı

dönüyoruz

döküyoruz

akıyoruz

çoban yalnızlığına.

28/01/04', 'Ben savrulan notalarla sana aç susuz dans ederken birlikte Edıth Pıaf sesinde sahipsiz bir kuzu yüreğim bakarken senin sahil gözlerine kış v...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Köse']::text[], 8.5, '{"poet":"Ahmet Köse","poet_slug":"ahmet-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/coban-yalnizligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-salih-dere-jrewq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zamanın en elim anında,

Görmek istersen beni,

Ben deki, Ben! 

Sende biter;', 'Zamanın en elim anında, Görmek istersen beni, Ben deki, Ben!  Sende biter;...', ARRAY['Türk Edebiyatı','Şiir','Salih Dere']::text[], 8.5, '{"poet":"Salih Dere","poet_slug":"salih-dere","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sensizlik-104-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söz', 'soz-abdullah-garip-4isk8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Söz neşeyi de derdi de artırır

Söz ümit verir, ufukları kaldırır

Söz oturanların küçük afatı olur

Söz boş insanlar da dedikodu bulur

Söz derdi,tasayı kuş gibi uçurur

Söz dostu, yaranı huzurdan kaçırır

Söz meselenin tahlili hadisenin iki yüzü

Söz gümüşse sukut altındır; sözün özü.', 'Söz neşeyi de derdi de artırır Söz ümit verir, ufukları kaldırır Söz oturanların küçük afatı olur Söz boş insanlar da dedikodu bulur Söz der...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/soz-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat kadini', 'hayat-kadini-nihat-iric-vxez7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sev dedi gozlerin', 'sev dedi gozlerin...', ARRAY['Türk Edebiyatı','Şiir','Nihat Iric']::text[], 8.5, '{"poet":"Nihat Iric","poet_slug":"nihat-iric","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/hayat-kadini-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haz Duyarım', 'haz-duyarim-hasan-huseyin-ozak-495ff', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Küçücük parmaklarını avucumda sıktığım zaman

Bir haz duyarım benliğimde

Ilık bir şeyler akar kalbime doğru

Yanan gözlerinle beni süzdüğünde

Gözlerim gözlerini bulduğu zaman

Kalp denen meret durmaz yerinde

İçim boşalır boşluğa doğru

Gözlerinle yakıp kül ettiğinde

Dudaklarım dudaklarını bulduğu zaman

Bir ses işitirim kuytu köşede

Nefes almaz olurum sonuna doğru

Yanar kül olurum senin içinde', 'Küçücük parmaklarını avucumda sıktığım zaman Bir haz duyarım benliğimde Ilık bir şeyler akar kalbime doğru Yanan gözlerinle beni süzdüğünde ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özak']::text[], 8.5, '{"poet":"Hasan Hüseyin Özak","poet_slug":"hasan-huseyin-ozak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/haz-duyarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakarış..', 'yakaris-i-brahim-ethem-bingul-zm92w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ya Rab müracatım sana

Sen herşeyi bilensin

Sevgimin büyüklüğünde

Tüm aşkların membası olan,

Ruhuma serpilen bir aşk damla damla

Böyle bir sevda istedim Senden

Verdin o aşkı bana

Tüm şükürler Sana

Ama ya Rab

Yanmaklarda ateşte

Aşk değil, hastalık ateşinde

O o kadar narin ki,

Kristal bir serçe gibi

Dayanamaz serçe yüreği

O kara gözleri açılmasın sonsuzluğa

Bir can gerekliyse ben varım

Onu alma ya Rab..

UIaşılmaza ulaştığımı düşündüğüm

O bahtsız an mı buna sebeb

Hani her kahkahanın ardından gelen

Gözyaşlarım gibi..

Ya Rab razıyım ben hasreti çekmeye

Yeter ki, gül yüzlüm iyileşsin

Merhamet eyle sen bizlere..', 'Ya Rab müracatım sana Sen herşeyi bilensin Sevgimin büyüklüğünde Tüm aşkların membası olan, Ruhuma serpilen bir aşk damla damla Böyle bir se...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yakaris-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Her Yerde Perde', 'her-yerde-perde-vahdet-nafiz-aksu-uwxe8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir iki duvar bir iki perde

Senin olduğun her yerde

İşte hayat, işte ölüm, zaman, mekan

Eser bende ben eserde

Besteler özleyen yaralı ruhum 

Sükuna ersin bir ses ver de 

Dediğimi duyup sevgili

İhtilaller yaptı sözlerde...

Besteler döktürdü aşkla ilgili…

Rüzgarın sesi o... ritmi o dalgaların…

Hüzünlü bir nihavent geçer fasıl

Ney  kesik öksürüklerle  bir  haber verir: 

Der ki... haydi… vakti geldi ağlamanın 

Demidir son baharın...

Sönmez mi hiç sinedeki ateşler

Seher yeli bağrımıza eser de 

Vuslata dair müjdeler duyarız

Gece vakti göklere süzülen seslerde

Bir hülya... bir rüya... bir düş  görülür

Uykunun ağırlaştırdığı gözlerde

Anlamadım ben bu işten 

Bir haber aldım gelişten

Bahis başladı gidişten 

Yol azığın aşk dediler

İçeceğinse ateşten 

Dedim ki hazırlıklıyım 

Bir kebabım ki razıyım

Hem ateşten hem de şişten', 'Bir iki duvar bir iki perde Senin olduğun her yerde İşte hayat, işte ölüm, zaman, mekan Eser bende ben eserde Besteler özleyen yaralı ruhum ...', ARRAY['Türk Edebiyatı','Şiir','Vahdet Nafiz Aksu']::text[], 8.5, '{"poet":"Vahdet Nafiz Aksu","poet_slug":"vahdet-nafiz-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/her-yerde-perde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak', 'yasamak-hasan-huseyin-ozak-zksrr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Doğmak, yeni bir hayata başlamak

Ölmek ve bitirmek

Yaşamaksa, doğmakla ölmek arası bir şey

Kaşla göz, varla yok arası her şey....! !', 'Doğmak, yeni bir hayata başlamak Ölmek ve bitirmek Yaşamaksa, doğmakla ölmek arası bir şey Kaşla göz, varla yok arası her şey....! !...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özak']::text[], 8.5, '{"poet":"Hasan Hüseyin Özak","poet_slug":"hasan-huseyin-ozak","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yasamak-76-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*İnce İşler', 'i-nce-i-sler-vahdet-nafiz-aksu-lchg9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Desen  ne çıkar  ki

Söz bilirim ben

Diyebilmek gerek 

Öz bilirim ben

Alemin sırrını 

Ederken seyran

Kendini görmeyen

Göz bilirim ben

Ben nice alış 

Verişler gördüm

Ağlamaktan acı 

Gülüşler gördüm

Dünyada  yüzleri 

Olan yıldızlar

Ve doğmak bilmeyen 

Güneşler gördüm

Gözden ötesini

Görmek   gerek

Görmek nasıl olur

Göstermek gerek 

Hayat ayaklara 

Dolanan iplik

Yar ile  bir olup 

Örmek gerek 

Ben ilme ilme

Örüşler gördüm

Bin desen oldum

Bin bir desen oldum

Ne senden başkayım

Ne sen oldum 

Vermek diye alışlar

Almak diye 

Verişler  gördüm

Gitmeye benzeyen 

Gelişler gördüm

Daha nice nice ….

Bunlardan bile ince 

Söz bilirim ben

Desem   ne çıkar  ki

Söz bilirim ben

Diyebilmek gerek 

Öz bilirim ben', 'Desen  ne çıkar  ki Söz bilirim ben Diyebilmek gerek  Öz bilirim ben Alemin sırrını  Ederken seyran Kendini görmeyen Göz bilirim ben Ben nic...', ARRAY['Türk Edebiyatı','Şiir','Vahdet Nafiz Aksu']::text[], 8.5, '{"poet":"Vahdet Nafiz Aksu","poet_slug":"vahdet-nafiz-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/ince-isler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-abdullah-garip-paa85', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rüyalarına gül yağan gülüm

Sulanıyordu sevgi ırmağından

Elinde gül dudağında tebessüm

Sulanıyordu muhabbet bağından

Arkadaşı melek olanı sevmek

Yoksa estetiğe kabalık mı vermek

tane tane yağan yağmurum

Yol arıyor, istiyor ruhuma inmek

Yağmur denize, yağmur kumsala hasret

Hasretiz şanlı geçmişten bahset

Yağmur damla damla muhabbet

Yol arıyor istiyor ruhuma inmek

Yağmur dörtyüz çadırın üstüne

Hükmetmişiz o gün yedi iklime

Yağmur-gözyaşı esir olan gönle

Yol arıyor, istiyor ulaşmayı bilmek

Yağmur damla damla melekle

Hesabımız olacak o gün...

Yağmur şimşek-gökgürültüsüyle

Yol arıyor, istiyor ejdada dönmek

yağmur hatırlatıyor her defada

Aranıyor şimdi üç kıtada

Benliği kayıp olmuş, her hali hatada

Yol arıyor istiyor nesli görmek', 'Rüyalarına gül yağan gülüm Sulanıyordu sevgi ırmağından Elinde gül dudağında tebessüm Sulanıyordu muhabbet bağından Arkadaşı melek olanı sev...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yagmur-105-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teslim Oldum', 'teslim-oldum-hasan-huseyin-ozak-f4f49', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karanlık gökyüzü, 

nasıl yavaş yavaş esir alıyorsa gün batarken,

ormanın yeşilini ve denizin mavisini.

Ve ardından, nasıl yavaş yavaş kayboluyorsa,

kuş cıvıltıları ve çocuk sesleri, geceye doğru.

Öylece teslim oldum,

ve teslim ettim, kendimi ve hayallerimi.

Şu an sadece beklemekteyim

Büyük ihtimal güneş tekrar doğacak

Bunu bilmenin umuduyla

Özlemekteyim...', 'Karanlık gökyüzü,  nasıl yavaş yavaş esir alıyorsa gün batarken, ormanın yeşilini ve denizin mavisini. Ve ardından, nasıl yavaş yavaş kaybol...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özak']::text[], 8.5, '{"poet":"Hasan Hüseyin Özak","poet_slug":"hasan-huseyin-ozak","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/teslim-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Manifesto', 'manifesto-ahmet-aksoy-2dhyj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düşük zamanlar manifestosu; 

Eksik harf, erken gecikmişlikler.

Yanlış soru, iki kalp hecesi 

Ular mı ulamaz mı birbirine.', 'Düşük zamanlar manifestosu;  Eksik harf, erken gecikmişlikler. Yanlış soru, iki kalp hecesi  Ular mı ulamaz mı birbirine....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/manifesto-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölemedin', 'olemedin-hasan-huseyin-ozak-gl98u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Denizde dalga her zaman vardı

Ama sen göremedin

Yollarda ufuk, ufukta umut hep vardı

Ama sen gidemedin.

Açıktı kapılar sonuna kadar

Çürüdü, söküldü yerinden, hiç kapanmadı

Ama sen giremedin.

Bu yürek hiç durmadı,

Sevdi, sevilmeyi bekledi ölene kadar

Ama sen sevemedin.

Aşkınla soğudu tenim

Bekledi mahşerde gelirsin diye

Ama sen öyle güzeldin ki

Kıyamadı Azrail

Ölemedin...', 'Denizde dalga her zaman vardı Ama sen göremedin Yollarda ufuk, ufukta umut hep vardı Ama sen gidemedin. Açıktı kapılar sonuna kadar Çürüdü, ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özak']::text[], 8.5, '{"poet":"Hasan Hüseyin Özak","poet_slug":"hasan-huseyin-ozak","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/olemedin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sence', 'sence-ahmet-aksoy-6hsy7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Varlığım sana bir güldandı

Vicdansız itince kırıldı

Yüreğim bir dikendir şimdi

Çünkü sen gittin, gülün soldu.', 'Varlığım sana bir güldandı Vicdansız itince kırıldı Yüreğim bir dikendir şimdi Çünkü sen gittin, gülün soldu....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sence-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Umuttur', 'mavi-umuttur-hasan-huseyin-ozak-wg92m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Deli gibi, elimde fırça

her şeyi, ama her şeyi maviye boyuyorum

Seni de mavilerin en orta yerine

koyu mavi, cam gibi,

bir nazar boncuğu gibi,

maviliklerin ortasına koyuyorum.

Mavi umuttur! Bir uçurtma gibi

Açtım uçurtmamı, saldım mavi gökyüzüne

Sana doğru uçuruyorum', 'Deli gibi, elimde fırça her şeyi, ama her şeyi maviye boyuyorum Seni de mavilerin en orta yerine koyu mavi, cam gibi, bir nazar boncuğu gibi...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özak']::text[], 8.5, '{"poet":"Hasan Hüseyin Özak","poet_slug":"hasan-huseyin-ozak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/mavi-umuttur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Bozuk', 'deli-bozuk-hasan-huseyin-ozak-2tqb9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüreğim donup kalıyor,

nefesim içimde hapis, sana dokunurken

Bir çöl rüzgarı gibi yalayıp geçer nefesin

Açamam gözlerimi,

Hayalimde bile seni öperken

İşte ben böyle deliririm,

deli bozuk olurum, seni her hatırlayışımda,

Durup dururken', 'Yüreğim donup kalıyor, nefesim içimde hapis, sana dokunurken Bir çöl rüzgarı gibi yalayıp geçer nefesin Açamam gözlerimi, Hayalimde bile sen...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özak']::text[], 8.5, '{"poet":"Hasan Hüseyin Özak","poet_slug":"hasan-huseyin-ozak","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/deli-bozuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlük Yakışıyor Her Renge', 'ozgurluk-yakisiyor-her-renge-bekir-mutlu-gokcesu-51hug', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mavi yapraklar

Özgün ve özgür

Uçuşuyorlar

Üzerlerinde beyaz çizgiler

Yol, yol damarlar

Sanki yaşıyorlar

Desen, desen bir perdede

Ve sıra dışı bir renkte

Uçuştukça tül

Sanki öpüşüyorlar

Nasıl güzelse

Şiir her dilde

Nasıl güzelse

İnsan her tabiiyette

Yaprak da güzel

Her mevsimde

Ve özgürlük yakışıyor 

Her renge...', 'Mavi yapraklar Özgün ve özgür Uçuşuyorlar Üzerlerinde beyaz çizgiler Yol, yol damarlar Sanki yaşıyorlar Desen, desen bir perdede Ve sıra dış...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ozgurluk-yakisiyor-her-renge-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi Geri Gel Yüreğim', 'hadi-geri-gel-yuregim-senol-yazici-13mmd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hadi geri gel yüreğim; 

İçimdeki çocuk, uyan! 

Ayakların, al kanatlı midilli,

Yaşın, kırk bilmem kaç olacak değil ya,

Bir insan parmaklarıyla

El ayak sayılır ömrün,

Varsay ki, o çağdasın.

Cahiller cesur olurmuş, bilmezsin.

Marangozun hatası ya da babanın,

Gözyaşları üstünden kazandığı paradır cesaretin,

Demezsin.

Aziz bir su parçası ol,

Ada ada, dal dal,

Yayılsın en enginine gönlün.

Göz kırparsa  kötülük, çelik bir duvar kesil,

Öyle mavi kal.

Hadi geri gel yüreğim; 

İçimdeki çocuk, uyan! 

Uzun kirpiklerini akıtarak,

-Yüzün nasıl olur bilir misin, o an? -

Kaşların altından öyle ıslak ıslak,

Bin yıl öper yüreğinde yüzünü insan,

Öyle bak.

Hadi geri gel yüreğim.

Dört yan kör, kral çıplak.

Bir sen görürsün, bir bilen sen.

Yeter mi yüreğin? 

Yettir, 

Uyan içimdeki çocuk,

Uyan, öyle bak!', 'Hadi geri gel yüreğim;  İçimdeki çocuk, uyan!  Ayakların, al kanatlı midilli, Yaşın, kırk bilmem kaç olacak değil ya, Bir insan parmaklarıyl...', ARRAY['Türk Edebiyatı','Şiir','Şenol Yazıcı']::text[], 8.5, '{"poet":"Şenol Yazıcı","poet_slug":"senol-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/hadi-geri-gel-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerelere Gideriz?', 'nerelere-gideriz-bekir-mutlu-gokcesu-2xj8w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Neden böyleyim? 

Neden ağlıyorum? 

Her şiirin arkasından

Uçup giden bir kuş misali

Bir daha görüşemeyecekmişim gibi

Oysa ben kimim? 

Kaç yer var? 

Nereye gidebilirim ki? 

Şiir nedir? 

Ve nereye gidebilir ki? 

Uçup giden kendime mi yoksa

Bu hislenişim...', 'Neden böyleyim?  Neden ağlıyorum?  Her şiirin arkasından Uçup giden bir kuş misali Bir daha görüşemeyecekmişim gibi Oysa ben kimim?  Kaç yer...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nerelere-gideriz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayragim!', 'bayragim-emine-cosgun-ay0qf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bayragim! 

Kan kirmizisi renginle seslendin

Ay yildizli gözlerinle baktin

Bir bakista 

Bizlere kendini agsik ettin.

Her yellenisinde, 

Ucuyorcasina dalgalandiginda

Sana hayran kaldik demekle degil

Sana taparcasina askimizi ilan ettik! 

    ISTE BENIM BAYRAGIM! ! !', 'Bayragim!  Kan kirmizisi renginle seslendin Ay yildizli gözlerinle baktin Bir bakista  Bizlere kendini agsik ettin. Her yellenisinde,  Ucuyo...', ARRAY['Türk Edebiyatı','Şiir','Emine Cosgun']::text[], 8.5, '{"poet":"Emine Cosgun","poet_slug":"emine-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bayragim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim...', 'kalbim-emine-cosgun-km10e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalbim,

Sevdigin insanin kalbi yufka gibi olsun! 

                    Her atisinda hissedebilmen icin

Sevgilerin derinden olsun,

                    Denizlerin asamayacagi kadar

Kalbinin sevgisi gercekci olsun, 

                    Kimsenin sevemeyecegi kadar.

Askinin dercesi dahada yucelsin,

                    Daglarin asamayacagi kadar.

Birde sevdigin dost degil,

              BASTAN INSAN OLSUN! ! !', 'Kalbim, Sevdigin insanin kalbi yufka gibi olsun!                      Her atisinda hissedebilmen icin Sevgilerin derinden olsun,            ...', ARRAY['Türk Edebiyatı','Şiir','Emine Cosgun']::text[], 8.5, '{"poet":"Emine Cosgun","poet_slug":"emine-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kalbim-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geregi Düsünüldü...', 'geregi-dusunuldu-baris-guc-iilt9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Günesli ve güzel bir günde ansizin beliren kapkara bir buluttun

Tam kurumusken gözlerim gökgürültülü  sagnak bir yagmurdu gidisin

Meteoroloji bültenlerinin bile bilmedigi bir kasirga koptu yüregimde

Firtina sonrasi sessizlikte adini haykirdim daglara sesimi yirtarcasina

Bir çig koptu bedenimden,büyük bir gürültüyle önüne ne geldiyse ezdi

Sevda tarlalarinda tüm mahsuller telef oldu, tüm emekler ziyan

Tüm sevenler magdur,ben ise suskun ve magrur

Baris Güç   sda ozlt MSN:   [email protected]', 'Günesli ve güzel bir günde ansizin beliren kapkara bir buluttun Tam kurumusken gözlerim gökgürültülü  sagnak bir yagmurdu gidisin Meteoroloj...', ARRAY['Türk Edebiyatı','Şiir','Barış Güç']::text[], 8.5, '{"poet":"Barış Güç","poet_slug":"baris-guc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/geregi-dusunuldu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuz Aşk Denen Yalan', 'sonsuz-ask-denen-yalan-gokhan-deniz-yazici-u67w4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dünya bir tane

Ama dünyalar pek çok

Onlarca dünyanın,

Biri senin

Biri benim

Biz aşk felsefesinin iflas ettiği

İsteklerin ziyanıyız

Biz ikimiz,

Bambaşka dünyaların insanıyız

Kalıcı hiç bir şey yok dünyada

Tek kalıcı, ölüm var

Sonsuz aşk denen yalan,

Yalan

Masallar kadar.', 'Dünya bir tane Ama dünyalar pek çok Onlarca dünyanın, Biri senin Biri benim Biz aşk felsefesinin iflas ettiği İsteklerin ziyanıyız Biz ikimi...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Deniz Yazıcı']::text[], 8.5, '{"poet":"Gökhan Deniz Yazıcı","poet_slug":"gokhan-deniz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sonsuz-ask-denen-yalan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim İçin', 'benim-i-cin-demet-kaytan-xx89u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bende sen gibi karanlığı gündüzlerde yaşadım

Sen karanlığımın içine sızan umut olurmusun

Zaman geçmişi anlatır

Bir rüzgar olup oralara esermisin

Sevsen sende söylermisin

Bende sen gibi geceleri yıldızlara bakarken

Hep dilek tuttum

Sen tuttuğum isim olurmusun

Benim için yağmurları durdururmusun

Aşka sadık kalmanı istesem

Bunu benim için yaparmısın', 'Bende sen gibi karanlığı gündüzlerde yaşadım Sen karanlığımın içine sızan umut olurmusun Zaman geçmişi anlatır Bir rüzgar olup oralara eserm...', ARRAY['Türk Edebiyatı','Şiir','Demet Kaytan']::text[], 8.5, '{"poet":"Demet Kaytan","poet_slug":"demet-kaytan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/benim-icin-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bin Bir Kanat', 'bin-bir-kanat-ozlem-torkul-tekan-jzxfh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Değişen bir şey yok buralarda 

Ben yine eski ben, hayatsa aynı hayat 

Hala kar yağıyor saçlarıma 

İçimdeki martılar çırpıyor bin bir kanat. 

Aylardan nisan oldu, gelmedi bahar 

Yine kırağı çalıyor, gönül bağımı 

Hala bir umutla, boş bahçelerde 

Arıyorum yitirdiğim o yıllarımı. 

Birkaç ahbap edindim, arada görüyorum. 

Aykırı dünyaların ayrı ayrı insanları. 

Havadan, sudan konuşuyoruz bazen 

Bir de biz kurtarıyoruz, sahipsiz vatanı. 

Değişen bir şey yok buralarda 

Ben yine eski ben, hayatsa aynı hayat. 

Zaman akıp gidiyor ve ben yetişemiyorum. 

İçimdeki martılar çırpıyor bin bir kanat. 

(15 Nisan 1997)', 'Değişen bir şey yok buralarda  Ben yine eski ben, hayatsa aynı hayat  Hala kar yağıyor saçlarıma  İçimdeki martılar çırpıyor bin bir kanat. ...', ARRAY['Türk Edebiyatı','Şiir','Özlem Torkul Tekan']::text[], 8.5, '{"poet":"Özlem Torkul Tekan","poet_slug":"ozlem-torkul-tekan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bin-bir-kanat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Kimim', 'ben-kimim-demet-kaytan-fza6p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aslında deli dolu yaşayan

Hayatı boş bulan

Bazen doldurup efkârlanan

Kendince yaşayan

Günü geldimi gitmek isteyenim

Sevdimi tapan

Kıskançlıktan gözünü karartan

Yiylik yapıp denize atan

Hep kazık yiyen

Ya sabır çeken

Günü geldimi gitmek isteyenim

Ağlayacağına gülen

Derdini kaleme döken

Sigarasız yaşayamayan

Bebeklere kıyamayan

Ara ara depreyone giren

Doktora gidip haplanan

Kişisine göre davranan

Bezen aptala yatan

Bazen cin kesen

Aslında herşeyi anlayan

Ama anlamamazlıktan gelenim', 'Aslında deli dolu yaşayan Hayatı boş bulan Bazen doldurup efkârlanan Kendince yaşayan Günü geldimi gitmek isteyenim Sevdimi tapan Kıskançlık...', ARRAY['Türk Edebiyatı','Şiir','Demet Kaytan']::text[], 8.5, '{"poet":"Demet Kaytan","poet_slug":"demet-kaytan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ben-kimim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneciğim', 'annecigim-demet-kaytan-rcsrr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen beni dünyaya getiren

Var olmama sebep olan

Gecesini gündüzüne katıp

Bizleri büyüten

Bilirmisin sen benim herşeyimsin

Büyüdüğümü hiç kabul etmeyen

Beni sevginle yaşatan

Yıldızım olup yolumu gösteren

Kışın yazı yaşatan

Gecemi aydınlatan

Her derdime deva olan

Bilirmisin sen olmadan ben yaşayamam

Sen beni dünyaya getiren

Dişini tırnağına takan

Yemeden yediren

Hüzünlerimi sevince dönüştüren

Beni sarıp sarmalayan

Bilirmisin sen benim kalbimsin

Sen kolum kanadım

Sen gözüm kulağım

Sen çiçeğim kitabım

Hayattaki tek varlığım

Beni ben yapan dünyama ışık saçan

Beni hiç bırakmayacağına söz verirmisin

Gidersen benide yanına alırmısın

Gözümü kapadığımda seni düşündüğümü

Her sabah kalktığımda ilk seni öpmek istediğimi

Mis kokunu içime çektiğimi

Bu deli kızının sensiz hiç uyanamayacağını 

Bilirmisin anneciğim...', 'Sen beni dünyaya getiren Var olmama sebep olan Gecesini gündüzüne katıp Bizleri büyüten Bilirmisin sen benim herşeyimsin Büyüdüğümü hiç kabu...', ARRAY['Türk Edebiyatı','Şiir','Demet Kaytan']::text[], 8.5, '{"poet":"Demet Kaytan","poet_slug":"demet-kaytan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/annecigim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alin Yazisi', 'alin-yazisi-suat-atar-ym2ag', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Olgunlar var, cilginlar var,ermis var,

Peygamber olup Halka gönül vermis var,

Hak her kulunun alnina bir sey yazmis,

Bir say bakalim alni acik kac kisi var! ! ! !', 'Olgunlar var, cilginlar var,ermis var, Peygamber olup Halka gönül vermis var, Hak her kulunun alnina bir sey yazmis, Bir say bakalim alni ac...', ARRAY['Türk Edebiyatı','Şiir','Suat Atar']::text[], 8.5, '{"poet":"Suat Atar","poet_slug":"suat-atar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/alin-yazisi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz bombos', 'sensiz-bombos-suat-atar-fh53n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerim senziz bosluga dalar,  bombos,

Saatlar sensiz zamani calar, bombos,

Koparirlar tam yoklunda beni benden,

Baktigim bütün, bütün aynalar seniz bombos! ! ! ! ! ! 

                                          Suat Atar', 'Gözlerim senziz bosluga dalar,  bombos, Saatlar sensiz zamani calar, bombos, Koparirlar tam yoklunda beni benden, Baktigim bütün, bütün ayna...', ARRAY['Türk Edebiyatı','Şiir','Suat Atar']::text[], 8.5, '{"poet":"Suat Atar","poet_slug":"suat-atar","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sensiz-bombos-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Patlamış Mısırlar,', 'patlamis-misirlar-caglar-akarsu-m78n2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Patlamış Mısırlar,

..

Yoğun karla  kaplı kış gecelerinde,

Soğuktan korunmak için,

Sığınırdık küçücük odalara,

Bir köşede ocak başı,

Yanı başında,kalın kütükler,

Bir biri arkasından, atardık,

Hiç durmamaksızın.

Keskin bir is kokusu dolardı içeri,

Dışarıda buz gibi bir ayaz,

İçeride cehennem gibi sıcak,

Ter ve soğuk bedenlerimizde,

Her gece şokunu yaşardık,

...

Yazdan kalmış kuru mısırlar,

Bir teneke kutu da sallanırken,

Tane-tane patlarken, beyaz-beyaz,

Gözlerimiz dalıp da giderdi,

Pencereden görünen uzak tepelere,,

..

Derin bir “ ah” çekerdik,

Bir bahar gelse ve kış bitse,

Aslında hep mevsimler, gelir,

Ve geçerdi,

İnsanın,bir özlemi vardı doğuştan,

Bitmez değişimleri ararda dururdu,

Bazen sevgileri tomurcuk olur,

Bazen de solar giderdi.

Patlamış mısırlar gibi yürekler,

Bir köşeye saçılırken,

Zaman bir yamyam gibi,

Her şeyi,yer ve bitirirdi.

...

2004-01-29

caglar akarsu', 'Patlamış Mısırlar, .. Yoğun karla  kaplı kış gecelerinde, Soğuktan korunmak için, Sığınırdık küçücük odalara, Bir köşede ocak başı, Yanı baş...', ARRAY['Türk Edebiyatı','Şiir','Cağlar Akarsu']::text[], 8.5, '{"poet":"Cağlar Akarsu","poet_slug":"caglar-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/patlamis-misirlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana tapmak', 'sana-tapmak-suat-atar-2wcmb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senden konusuyor dilimin bir sesi varsa,

Al hepsi senindir su hayatin neyi varsa,

Haktan seni sevmek, sana tapmak dilegimdir,

Bir gün su dünyaya yeniden gelmek varsa! ! ! ! ! ! ! ! 

                                        Suat Atar', 'Senden konusuyor dilimin bir sesi varsa, Al hepsi senindir su hayatin neyi varsa, Haktan seni sevmek, sana tapmak dilegimdir, Bir gün su dün...', ARRAY['Türk Edebiyatı','Şiir','Suat Atar']::text[], 8.5, '{"poet":"Suat Atar","poet_slug":"suat-atar","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sana-tapmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hicran dolu', 'hicran-dolu-suat-atar-uwwl1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hicran dolu bir aynaya baktim ben bu gece,

33 yilimi ardimda biraktim sanki bu gece,

Ömrümde ne yapmis ne kazanmisimki ben,

Pisman olarak hepsini kirdim yiktim yaktim bu gece', 'Hicran dolu bir aynaya baktim ben bu gece, 33 yilimi ardimda biraktim sanki bu gece, Ömrümde ne yapmis ne kazanmisimki ben, Pisman olarak he...', ARRAY['Türk Edebiyatı','Şiir','Suat Atar']::text[], 8.5, '{"poet":"Suat Atar","poet_slug":"suat-atar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hicran-dolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakamozun Türküsü', 'yakamozun-turkusu-fatih-soyler-bm1b6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '(Temmuz''a İthaf)

ne günler yaşadım bir bilsen

ne günler senden önce:

çocuk oldum, genç oldum

dayak yedim, vuruldum

gün geldi hayta oldum

gün geldi asker oldum

hasta oldum, usta oldum

aşk vurdu başıma, aman! 

deli, divane oldum

ne günler geçirdim senden önce

ne günler bir bilsen:

gün geldi su oldum

gün geldi balık oldum

yosun oldum, taş oldum

bir dalgaydım, kıyıya vurdum

gün geldi güneş oldum

gün geldi ay oldum

gündüz oldum, gece oldum

ne türküler söyledim bir duysan

ne şiirler okudum çakıl taşlarına

bir yıldızdım, yakamoz oldum

geldim, tutundum ayağına

uzattın ellerini, dolandım parmaklarına

tenine sardın beni, harelendim başında

uzakları özledim of,

martılara kanat oldum

deniz yelleri esiyor hey! 

açıklara yelken oldum

(Ocak, 2000, Ankara)', '(Temmuz''a İthaf) ne günler yaşadım bir bilsen ne günler senden önce: çocuk oldum, genç oldum dayak yedim, vuruldum gün geldi hayta oldum gün...', ARRAY['Türk Edebiyatı','Şiir','Fatih Söyler']::text[], 8.5, '{"poet":"Fatih Söyler","poet_slug":"fatih-soyler","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yakamozun-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Talih', 'talih-suat-atar-ns31s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Talih ne umut verdi nede güldürdü beni,

Binbir aci toprak gibi hep esti sürdü beni,

Zevk almayi coktan unuttum,

Her yerde o yalnizligim yakti, yikti öldürdü beni.

                                                       Suat Atar', 'Talih ne umut verdi nede güldürdü beni, Binbir aci toprak gibi hep esti sürdü beni, Zevk almayi coktan unuttum, Her yerde o yalnizligim yakt...', ARRAY['Türk Edebiyatı','Şiir','Suat Atar']::text[], 8.5, '{"poet":"Suat Atar","poet_slug":"suat-atar","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/talih-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlarsin ya', 'anlarsin-ya-suat-atar-ut67j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir bakip gözlerime her seyi anlarsin ya,

Benim ile kahirolup aglarsin ya,

Su sonzuz karanliklar hiiiccc umrumda degil,

Batmayan günes gibi icimde sen varsin ya.', 'Bir bakip gözlerime her seyi anlarsin ya, Benim ile kahirolup aglarsin ya, Su sonzuz karanliklar hiiiccc umrumda degil, Batmayan günes gibi ...', ARRAY['Türk Edebiyatı','Şiir','Suat Atar']::text[], 8.5, '{"poet":"Suat Atar","poet_slug":"suat-atar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/anlarsin-ya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelen Vurur Giden Vurur', 'gelen-vurur-giden-vurur-ahmet-kurt-l0k72', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerimde yaş eksilmez,

Gelen vurur, giden vurur.

Acılarım bir gün dinmez,

Gelen vurur, giden vurur.

Neşter değer, yara kanar,

Gün günümden kötü doğar,

Göz bulanık, yürek yağar,

Gelen vurur, giden vurur.

Gülmek tarih, gerçek ağıt,

Yaza yaza bitti kağıt,

Suyu döküp yürek soğut,

Gelen vurur, giden vurur.

Hayat sürgün, mekan hücre,

Güneş doğmaz, köşem ücra,

Deneniyor büyük icra,

Gelen vurur, giden vurur.

İlaç kayıp, doktor hasta,

İçim buruk, gönül yasta,

Bir garibim, akıl tasta,

Gelen vurur, giden vurur.

Delip attılar postumu,

Sürgün ettiler dostumu,

Kurdoğlu talih küstü mü,

Gelen vurur, giden vurur.', 'Gözlerimde yaş eksilmez, Gelen vurur, giden vurur. Acılarım bir gün dinmez, Gelen vurur, giden vurur. Neşter değer, yara kanar, Gün günümden...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gelen-vurur-giden-vurur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sev Diyemiyorum', 'sev-diyemiyorum-hasan-huseyin-ozak-wuemh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nasıl sesin çıkmaz, su diyemezsin

Gücün kalmaz, dur diyemezsin ya! 

Sev diyemiyorum işte....', 'Nasıl sesin çıkmaz, su diyemezsin Gücün kalmaz, dur diyemezsin ya!  Sev diyemiyorum işte.......', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özak']::text[], 8.5, '{"poet":"Hasan Hüseyin Özak","poet_slug":"hasan-huseyin-ozak","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/sev-diyemiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tomurcuk', 'tomurcuk-hasan-huseyin-ozak-trlvj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kapılmak bir sevdaya gönül gönül

Ve uzanmak çayıra boylu boyunca

Islanmak yağmurda siğim siğim

Her damla yağmuru öpücük sanarak

Kuzularda, çiçeklerde, kuşlarda

Sevdiğinde paylaşmak dünyayı

Ve bir ah çekmek, umut bağlamak

Elbet bir gün, elbet bir gün diyebilmek', 'Kapılmak bir sevdaya gönül gönül Ve uzanmak çayıra boylu boyunca Islanmak yağmurda siğim siğim Her damla yağmuru öpücük sanarak Kuzularda, ç...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özak']::text[], 8.5, '{"poet":"Hasan Hüseyin Özak","poet_slug":"hasan-huseyin-ozak","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tomurcuk-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vebal Senin', 'vebal-senin-i-brahim-bayraktar-71a3f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana uzanan şu elimi,

Tutmazsan vebal senin.

Adını zikreden dilimi,

Tatmazsan vebal senin.

Dik bir yokuş bu tutku,

Sarmalamış tüm ufku,

Tırmanıp da yokuşu,

Çıkmazsan vebal senin.

Kaygan bir zemin gibi,

Kendinden emin gibi,

Dün değil demin gibi,

Bıkmazsan vebal senin.

Yaşayan sen ölü benim,

Çobanı sen, sürü benim,

Ateşi sen külü benim,

Yakmazsan vebal senin.

Bir kız sevdim ıraktan,

Geçmez bizim duraktan,

Gözden göze sırattan,

Geçmezsen vebal senin.

29.01.2004', 'Sana uzanan şu elimi, Tutmazsan vebal senin. Adını zikreden dilimi, Tatmazsan vebal senin. Dik bir yokuş bu tutku, Sarmalamış tüm ufku, Tırm...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/vebal-senin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Aşk Hikayesi', 'bir-ask-hikayesi-hifzi-ozbekmez-aqcpa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dediler ki bir gün sen bir güzele yanarsın

Onun bakışlarına bir an sende kanarsın

İnanmamış gülmüştüm hiç öyle şey olur mu

Bu yaşta deli gönül hiç misafir alır mı

Demek ki büyük söylemiş sonunda yanılmışım

Bir güzelin gözüne demek bende kanmışım

Öylesine baktı ki gönlümü yaktı geçti

Demek ki kara sevda kendine beni seçti

Bakışlar güzeldi sanki birer ok gibi

Birde sevdamız oldu başka dertler yok gibi

Kara olmalıydı böyle bir sevdanın adı

Demek ki yaşananların başka oluyor tadı

El ele tutuşmanın başkaydı verdiği haz

Hiç umurumda değildi ne kış ne bahar nede yaz

Göklerde uçuyorduk sanki kuşlar misali

Belki görülmemişti böyle aşkın emsali

Bu sevdada unuttum ben gamı kederi

Onu çok sevmek midir bütün bunun nedeni

Büyük lokma ye amam büyük söz söyleme

Sonunda gönlüne uyup aşkta karar eyleme

Aradığımı buldum ya artık ondan vazgeçmem

Gözlerim açık gitmez ölsem de hiç gam yemem

Ben koca ömrümce ilk defa mutlu oldum

Diyorum ki kendime iyi ki aşık oldum

Her şeye rağmen güzel yaşamak bu sevdayı

Vaz geçmem mümkün değil verseler güneşi ayı

Latifi sende niye gülmüştün komşuna

Böyle sevdalar gelir senin asi başına

23 EYLÜL 2003 SALI SAAT: 24:00', 'Dediler ki bir gün sen bir güzele yanarsın Onun bakışlarına bir an sende kanarsın İnanmamış gülmüştüm hiç öyle şey olur mu Bu yaşta deli gön...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bir-ask-hikayesi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Aklıma Geldin', 'sen-aklima-geldin-hifzi-ozbekmez-47nb5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uykularım kaçtı gece yarısı

Sen aklıma geldin doldu gözlerim

Gönlümün sultanı aşkı canısı

Sen aklıma geldin doldu gözlerim

Sensizlik hançeri girdi bağrıma

Hasretin gidiyor benim ağrıma

Kulak ver sevdiğim benim çağrıma

Sen aklıma geldin doldu gözlerim

Hayalde rüyada seni ararken

Bu gönül aşkınla her an yanarken

Gecenin yarısı sabahlar erken

Sen aklıma geldin doldu gözlerim

Latifi seviyor şaşkın biçimde

Aşk ateşi yanıyor kalbi içinde

Her gecenin ikisinde üçünde

Sen aklıma geldin doldu gözlerim

24 EYLÜL 2003 ÇARŞAMBA SAAT: 05:30', 'Uykularım kaçtı gece yarısı Sen aklıma geldin doldu gözlerim Gönlümün sultanı aşkı canısı Sen aklıma geldin doldu gözlerim Sensizlik hançeri...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-aklima-geldin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağılma', 'dagilma-nilay-aksu-19w6r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'öfke 

bana yol ver 

gideyim 

parça parça toplayıp gittim 

ıssız bir sokak gibi 

yürüdüm kendimi 

acının dili olsa söylerdi 

yılanın tutup da içmesi zehrini 

vakur ve bir o kadar olmaz değil miydi 

ah bu dudaklar bilirdi ya tadını 

şimdi bu uzanıp 

bir yarayı acı acı öpmek gibiydi 

başını alıp gitmiş bir dağ gibi susmak 

şaşkın bir ölüm değil miydi 

durmadım yorulmadım sustum seni 

yanıtsız bir soru gibi 

boşluğa saldım kendimi 

acıyı kenetledim 

sıktım dişimi 

şimdi bu apansız sızı 

yara daha sıcak üstelik 

soğu be ey soğu', 'öfke  bana yol ver  gideyim  parça parça toplayıp gittim  ıssız bir sokak gibi  yürüdüm kendimi  acının dili olsa söylerdi  yılanın tutup da...', ARRAY['Türk Edebiyatı','Şiir','Nilay Aksu']::text[], 8.5, '{"poet":"Nilay Aksu","poet_slug":"nilay-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dagilma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaresi Sende', 'caresi-sende-hifzi-ozbekmez-8kauh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nereye baksam görürüm seni

Allahın aşkına unutma beni

Aşkında yakıyor canım sinemi

Çaresi sendedir merhemi sende

Aşktan yüce ne var söyle dünyada

Hayalin ararım bazen rüyada

Çektiğim dertlerin koca dünyada

Çaresi sendedir merhemi sende

Gönül gözü ile bakmak gerekmiş

Gönülden gönüle akmak gerekmiş

Sevda suçlusuyum yakmak gerekmiş

Çaresi sendedir merhemi sende

Latifiyim ben aşkından yanarım

Hayalde rüyada seni ararım

Sevdayın yüzünden varsa zararım

Çaresi sendedir merhemi sende

24 EYLÜL 2003 ÇARŞAMBA SAAT: 08:00', 'Nereye baksam görürüm seni Allahın aşkına unutma beni Aşkında yakıyor canım sinemi Çaresi sendedir merhemi sende Aşktan yüce ne var söyle dü...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/caresi-sende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çeşme''de Bir Pazar Sabahı', 'cesme-de-bir-pazar-sabahi-hasan-huseyin-ozak-5mtch', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sahil boyu sandallar, yavaş yavaş salınmakta

Deniz durgun, deniz durgun...

Sahil boyu insanlar, hepsi bezgin, soğuk ve soluk

Hepsi vurgun, hepsi vurgun...

Denizin maviliği, martıların süzüle süzüle raks etmesi

güldürmüyor yüzümü

İçimde öyle bir boşluk var ki,

ne yapsam, ne yapsam da dolmuyor.

Ama sen olsaydın diyorum da,

hele siz olsaydınız diyorum da

Diyorum da bir şey gelmiyor elimden

Aşina bir yüzün gülüşüne,

dost bir sesin merhabasına hasretim

Sabret gönlüm, sabret

Ne kaldı şunun şurasında,

havaların ısınmasına.

Elbet eriyecek karlı dağların buzları

Elbet eriyecek, pas tutmuş insan yürekleri

Yollar açılacak, sen geleceksin

Kalpler açılacak, sevgi gelecek, dostlar gelecek

Yavaş yavaş mırıldanacak dudaklar, 

fısıltalar gelecek

Merhabalar gelecek !', 'Sahil boyu sandallar, yavaş yavaş salınmakta Deniz durgun, deniz durgun... Sahil boyu insanlar, hepsi bezgin, soğuk ve soluk Hepsi vurgun, h...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özak']::text[], 8.5, '{"poet":"Hasan Hüseyin Özak","poet_slug":"hasan-huseyin-ozak","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/cesme-de-bir-pazar-sabahi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Var', 'hayat-var-oguzkan-bolukbasi-iezfm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'senin olduğun yerde hayat var

yani evrende

boşuna taşınmayın gezegenlere

o''nu bulun

yaşamak için

sevmek için

ve nefes alıp

su içmek için

benim gibi

o güzel sevgilimi', 'senin olduğun yerde hayat var yani evrende boşuna taşınmayın gezegenlere o''nu bulun yaşamak için sevmek için ve nefes alıp su içmek için ben...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hayat-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatın İçinden', 'hayatin-i-cinden-recep-camliguney-umkgy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gecenin  esintisi

             Kulaklarıma vuruyor

             Başımda bir ağrı

             Kalbimde sancı var

             Anlatılması güç ama 

             Hayatın içinden kopmuş

             Bir taze gülü anımsatır

             Güzel yüzün

             Belkide denizin mavimsi görünüşü

             Gözlerindeki ışıldı olmuş

             Bilinmeyen bir şeyin de

             Saçlarına samansı 

             Bİr renk vermesi gibi

             Yanakların ve dudakların

             Soframda eksik olmayan 

             Meyveleri anımsatırlar

             Anımsatırlar neden diye 

             Soracak olursan? 

             Elma gibi yanaklar 

             Kiraz gibi dudaklar

             Yenmeden tatlarına doulmazlar derimde  ondan

                      Recep Çamlıgüney

    0535 473 06 71', 'Gecenin  esintisi              Kulaklarıma vuruyor              Başımda bir ağrı              Kalbimde sancı var              Anlatılması gü...', ARRAY['Türk Edebiyatı','Şiir','Recep Çamlıgüney']::text[], 8.5, '{"poet":"Recep Çamlıgüney","poet_slug":"recep-camliguney","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/hayatin-icinden-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül ve biber', 'gul-ve-biber-sair-ajanm2-lv2af', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kullanmak serbesttir', 'kullanmak serbesttir...', ARRAY['Türk Edebiyatı','Şiir','Şair Ajanm2']::text[], 8.5, '{"poet":"Şair Ajanm2","poet_slug":"sair-ajanm2","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/gul-ve-biber-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Söyleyem Cânân için destân destân üstüne', 'soyleyem-c-n-n-icin-dest-n-dest-n-ustune-mustafa-tanrikulu-qssv2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '(Rasih''e naziredir)  

Söyleyem cânân için  destân destân üstüne

Berg-i güldendir, giyin fistân fistân üstüne

Oynamış derler kalem dest-i Sa''di''de bir zaman

Ben yazam gül-gûn için Bostân Bostân üstüne

Bir gören gül çehreni meftûn u hayran dolaşır

Bu sebebten bağırır mestân mestân üstüne

Rabbimin emriyle inşâ''  olunan köşk ağzına

La''l taşından yaptılar âstân u âstân üstüne

Ah ne gam! .. Çekmekteyiz biz aşkı,gelsin toplanıp

Mustafâ''nın her belâ cestân cestân, üstüne

Açıklama:

Beyit: Ben oturup sevgili için destan üstüne destan söyleyeyim. Ey sevgili sana getirdiğim fistanları giyin ki onların kumaşı gül yaprağıdır.

Beyit:Rivayet odur ki Sa''di-i Şirazi''nin elinde bir müddet kalem gezmiş ve Şeyh Sa''di de Bostan ve Gülistan''ı yazmıştır.Ben de (gül yaprağından fistanlar giyip gül rengine bürünen)  sevgili içn Bostan üstüne Bostan gibi nice eserler yazayım.

Beyit:Ey Sevgili senin gül gibi yüzünü bir defaya mahsus gören tutkun ve hayran bir şek,ilde dolaşır. Bunun içindir ki sarhoşlar birbirlerine  bağırırlar.

Beyit: Rabbim meleklere bir köşk yapın diye emretti. Onlar da köşkün kapı yerine la''l taşından iki eşiği üst üste yaptılar.

Beyit: Ah ne gam biz aşk gibi bit belayı çekebiliyoruz. Bundan sonra bütün belalar Mustafa''nın  üstüne sıçraya sıçraya gelsin. Fayda etmez.', '(Rasih''e naziredir)   Söyleyem cânân için  destân destân üstüne Berg-i güldendir, giyin fistân fistân üstüne Oynamış derler kalem dest-i Sa''...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tanrıkulu']::text[], 8.5, '{"poet":"Mustafa Tanrıkulu","poet_slug":"mustafa-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/soyleyem-canan-icin-destan-destan-ustune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba', 'baba-meltem-seyhan-uv96r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bugün seni düşündüm baba

Ben küçük bir kız çocuğu oldum

Sen evin dar koridorunda

Üç tekerlikli bisiklete bindirdin beni

Bugün seni düşündüm baba

Ben yaz tatiline gittim annemle

Sen yalnız kaldın İstanbul''da

Tek özlediğim sen oldun tatilde

Bugün seni düşündüm baba

Ben artık genç kız oldum

Sen bana ''Nasılsın yavrum? '' dedin

Ben sana ''İyiyim baba sen nasılsın''

Bugün düşündüm de baba

Keşke daha detaylı anlatsaydım

Keşke seni daha çok dinleseydim

Keşke hiç büyümeseydim

Bugün düşündüm de baba

Anne ile ilgili bu kadar şiir şarkı varken

Sizleri biraz ihmal ettik galiba', 'Bugün seni düşündüm baba Ben küçük bir kız çocuğu oldum Sen evin dar koridorunda Üç tekerlikli bisiklete bindirdin beni Bugün seni düşündüm ...', ARRAY['Türk Edebiyatı','Şiir','Meltem Seyhan']::text[], 8.5, '{"poet":"Meltem Seyhan","poet_slug":"meltem-seyhan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/baba-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Badem Çiçekleri, Ayrık Otları Ve Yalancı Baharlara Dair…', 'badem-cicekleri-ayrik-otlari-ve-yalanci-baharlara-dair-derin-deniz-gtt4j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ağzında zehir zemberek bir tatla uyandı. Vakit gece yarısını çoktan geçmiş olmalıydı. Tüm iç organları matkapla delinircesine acı çekiyordu. Yatağında dönmeye çalıştı. Pek başarılı olamadı. Koluna takılı serum hortumunu çekiştirdi. Gözleri hafif bulanık görüyordu. Tüm vücudu sızıdan kaskatı kesilmişti. Buraya getiriliş nedenlerini baygın haldeyken bile unutmamıştı. İçinde tuhaf bir boşluk duygusu vardı. Peki ya iyi mi etmişti? 

Dün geceye dair ayrıntılar ufak ufak bilincine üşüşüyorlardı. Kışa giriyorlardı. Hava ısısı yavaş yavaş düşmüştü. Sonbahar yapraklarını süpüren çöpçüler, daha eylemi bitiremeden sokağa taarruz eden yapraklara gizliden gizliye hiddetleniyorlar olmalıydılar. Karıncalar kaçamak gün ışığından son bir kez daha yararlanabilmek için talan edercesine kendilerini yiyecek bulabilecekleri olası alanlara bırakmışlardı belki de.

Küçük bir evi vardı. Bahçeli ve iki odalı, ancak tek kişinin yaşayabileceği, pek lüks olmayan ama yine de “buna da şükür” dedirtecek türünden bir yer evi. Birkaç sene önce ailesini kaybettikten sonra buraya gelmeye karar verdiğinde düşlediği aslında bundan daha iyisi de değildi. Kendine yetiyordu. Misafir ağırlayamıyordu pek. Ama zaten öyle çok sayılabilecek dostu olan, popularitesi yüksek biri de sayılmazdı. Minik bir kedisi vardı. Aslında bir kedi beslemek onun için en son şeydi, çünkü tüm çocukluğu kedilerden nefret ederek geçmişti. Bunun da nedenlerini biliyordu (kendi kendine gülümsedi, hep aynı numarayı yapardı kendisine; kendi kendine ucuz psikanalistçi oyunları oynar, kendine soru sorar ve tüm soruların cevaplarını bildiğine emin olurdu. Freud türevlerini artık okumuyordu. Onca okuduğu şey kendisine yetiyordu da artıyordu bile. Yıllarca önce okuduğu o garip kitaptan kalma bir deyimle “baca temizliği” yapmak konusunda üstüne yoktu. Yani zihnindekileri boşaltıyor, onlarla yüzleşiyor ve o anda kendisi için çıkmaz sandığı şeylerin nedenlerini  ortaya çıkarınca sorun kendiliğinden çözümleniyordu. Peki ya öyleyse, burada oluşunun nedeni neydi? 

Midesine giren ani bir krampla düşüncelerinden sıyrıldı. Yatağın kenarındaki komodinin üstünde bir şişe su ile bir bardak duruyordu. Uzanmaya çalıştı. Ağzı kurumuştu. Oldum olası hasta olmaktan nefret ederdi. Kendini etrafa mikrop saçan çöp tenekesi gibi hissederdi böyle zamanlar. Ama aslında kızdığı kendisiydi. Basit şeyler konusunda bile nasıl bu kadar aciz bırakabiliyordu kendisini. Etrafına göz gezdirdi. Mezarlık kadar derin bir sessizlik vardı odada. Su içmekten vazgeçti.

Şimdi zavallı kedisi ne haldeydi kimbilir? Kendisi bu kadar zayıfken, kedicik kendine beslenmek için bir şeyler hazırlayamazdı ki! Ne kadar kalacaktı acaba burada? . Neyseki “eyleme” girişmeden  hastanenin numarasını 118 den öğrenerek, “ne olur ne olmaz” diye telefonun yanına not etmişti. İyi de yapmıştı. İnsanın zihni neden öyle çok şeye gebeydi ki? Oldum olası kararlı, tutarlı, ne istediğini bilen bir insan olamamıştı. Şimdiki başarısızlığı da zaten bunun açık bir örneği değil miydi? Kırık bir tebessüm yerleşti sonra dudağına. Boğazı hala kuruydu. Güçlükle yutkunuyordu. Ara ara midesi şiddetli kramplarla sarsılmaya devam ediyordu.

Kedisini düşündü. O savsak, tembel, yarenliği bile beceremeyen kedisi… İlk ne zaman dahil olmuştu yaşamına? Geçen kıştı galiba. Demek ki yaklaşık bir senedir birlikte yaşıyorlardı. Muhteşem bir çift sayılmazlardı ama, fena da değillerdi. Gerçi onun her yere fütursuzca savrulan kıllarından nefret ediyordu. Ha hemen belirtmek gerekiyor, onu eve almaya karar vermeden önce cinsiyetinin ne olduğunu öğrenmiş sonra kabul etmişti. Kedicik bir erkekti. Tamam kendi cinslerine karşı pek adil olmayan bir davranıştı bu. Belki hemcinslerine ihanet bile sayılabilirdi. Ama ne yapsındı? Çocukluğundan kalan görüntüler gitmiyordu gözünün önünden bir türlü. Çamaşırlarının bulunduğu seleyi çekmişti bir gün divanın altından.  Tüm eşyalarının kanlı görüntüsü daha o anda midesini ayağa kaldırmıştı. Orada bir doğa mucizesinin gerçekleşmiş olması umurunda bile değildi. Bir kedi, yanında üç beş yavrusu ve kan… Hayır hayır  bir ev arkadaşı seçecekse ve bu bir kedi olacaksa kimin ne söylediğini umursamayacak aynadaki yüzüne de kahramanca bakarak verdiği kararın doğru olduğunu söyleyecekti gülümseyerek.

            Gülümsemek.. Son zamanlarda ne kadar da az kullanılmış bir eyleme dönüşmüştü hayatında. Gözleri yeniden bulutlandı. Oysa yıllar önce dedesine, hep mutlu bir kız olacağına dair söz veren kendisi değil miydi? Ya da o her şeyin o andan daha kötü olmadığı bir zamanda karşısına çıkan martının şaklabanlıkları onu güldürmüş ve bu da onu hayata daha da sıkı bağlamamış mıydı? O gün “ah keşke martıca bilsem” diye kederlenmişti de üstelik.

Aniden kulak kabarttı. Dışarıda yükselen sevdiği bir şarkının ezgileri ve yarım yamalak sözleri çalındı kulağına. “elbette bazen çiçek açıp, bazen solacağız”.. Bir arabadan geliyor olmalıydı. Ses çoktan uzaklaşmıştı. Şarkının sözlerini düşündü. Öyle değil miydi ya? Mevsimi geldiğinde güllerimiz açacak mevsimi geldiğinde de yaprağımız dökülecekti. Yaşamak dediğin dört mevsimi içinde taşıyan bir şarkıydı işte. Neden öyle içinden çıkılamaz hale sokardık ki hayatlarımızı. Bir arkadaşının deyimiyle “on beş bilinmeyenli denklem miydi yani bu”..

Ahhh! Sevgili dedesiı, yaşıyor olsaydı da başını onun sıska ama güvenli kucağına dayayabilseydi. Ne çok şey öğrenmişti ondan. Dedesinin yüzü hep bilgece gülerdi, konuşmayı az sever, konuştuğunda onun anlamadığı ama önemli olduğunu bildiği öyküler anlatırdı ona. Elindeki tesbihi hiç bırakmazdı. Hep dua eder gibi dudakları kımıl kımıldı. Canımın içi güzel elleri, son zamanlarda yaşlılıktan nasıl da titriyorlardı. Çayı bile kendi elleriyle içiriyordu dedesine. Biliyordu, onca sefalet çekmiş ve acı çekmiş olmasına rağmen dedesi şu anda  burada olmasını gerektiren nedenlerle yaşamını sonlandırmaya çalışmazdı. Gözleri bulutlandı yine. Boğazında koca bir yumruk oluştu. Bu, şu andaki durumu için çok tehlikeli bir şeydi. Bedeni doğal tepkisini gösterdi ve öksürmeye başladı. İçeriye bir kadın girdi o anda, kadına can havliyle masadaki suyu işaret etti. İçince biraz rahatladı. Kadın onun solgun yüzüne bakınca “hemşireye sesleneyim mi? ” diye sordu. Hiç takati yoktu. Hayır anlamında başını sallayınca kadın gitti.

Peki ya şimdi ne olacaktı? Beş parasızdı. İşinden ayrılmıştı. Hayır hayır, doğruyu söylemek gerekirse işi ondan ayrılmıştı, patrondan şimdiye dek işitmediği hakaretleri işitmiş ve o gün çok çirkin biçimde kovulmuştu. İçini acıtan işinden olması değildi kuşkusuz, buna neden olan şeylerdi. Dost sandığı bir grup arkadaşının ihanetine uğramıştı. Ekonomik sorunlar yüzünden firma birkaç elemanın işine son verecekti. Ama bunlar arasında en son kendisini görüyordu, çünkü o, firmanın belkemiğiydi. Herkes gider, o kalırdı. Ta ki iki gün öncesinde, rakip firmanın kendisine ait tasarımla piyasaya giriş yapmasıyla sorunlar çorap söküğü gibi gelmiş ve kendisinin işten atılmasına varan bir dizi çirkin şeyle sonlanmıştı. Kimlerin bu işte parmağı olduğunu o anda anlayamamıştı. Daha sonra öğrendiğinde ise, o ana kadar sükunetini korumaya çalışan tavırları silinmiş, yerini histerik bir kızın krizleri almıştı. Öylesine vahimce ağlıyordu ki! Bunu hak edecek ne yapmıştı? O hep dedesine ve badem çiçeklerine sadık kalmıştı. Evinin ve yüreğinin kapısı herkese açıktı. Önyargısız olmaya özen gösterirdi. Karşıdaki kendisini ne kadar hayal kırıklığına uğratırsa uğratsın ona yeni şanslar verilmesi gerektiğine inanırdı. Kimseye iyilik borçlu olduğu için değil. Kendisi böyle olduğu, e biraz da sevgili dedesinin öğrencisi olduğu içindi. 

Ama işte hayat tüm iradesini bozguna uğratmıştı. Yaşama dair bildiği, savunduğu, uyguladığı tüm öğretiler iflasın eşiğindeydi. Kederle Kafka’nın aforizmalarından birini düşündü: “sen bir ödevsin, ama görünürde hiç öğrenci yok”.. Öyle ya, kim onun ne istediğini önemsemişti şimdiye değin, onu anlamak, karanlık mağarasına yolcu olmak, el yordamıyla, girintileri çıkıntıları öğrenmek.. Ahhh! Gözlerini sımsıkı yumdu. Kafka’yı unut! dedi kendi kendisine. Şimdiye dek okuduğu kitaplardan eline ne geçmişti? Öğrendikleri yaşamı anlaşılması daha zor yapmıyorlar mıydı? Üstelik  öğrenmen gereken yeni şeyler çıkıyordu hep. Her defasında bildiğin doğru ile yaşadığın doğru arasındaki gergin ipte dans edip duran azınlıktan biriydi işte. Bu kadar soru sormasa ne olurdu sanki? Ya da yaşam bırak biraz da karmaşık kalsaydı yani..  Bu oyun kendisi için fazla -nasıl demeli- hilekar, karmaşık, bilinmeyeni bol bir denklem… Hay Allah! hasta yatağında bile deli saçması üretmek konusunda üstüne yoktu. 

Ağzının kuruduğunu hissetti yine. Ama bu kez odasının uğrayanı yoktu. Anlaşılan bu hastane pek gezgin sevmiyordu. Sürekli aynı pozisyonda yatmaktan vücudu yine ağrımaya başlamıştı. Kımıldandı. 

Neydi o kendisinin şu anki yaşam gözlüğü olan sevgili dedesinin öğretisi. Gülümsedi. Dün gibi anımsıyordu.

O zamanlar yaşadıkları kentte, yani doğup büyüdüğü ve insan olmayı öğrendiği kent, her kış-ilk bahar mevsim dönümlerinde Şubat sonu-Mart başı gibi havalar birden mevsim normallerinin üzerinde seyretmeye başlardı. İlikleri  ısınırdı öyle zamanlar. Diğer çocuklarla, kaçamak fırsatlar yaratmaya çalışırlardı güneşten erkencek nasip alabilmek için. Bu vakti özlemle bekleyenler de vardı  oysa ki. Badem  çiçekleri. Evlerinin önündeki tek renkli yaşam sürgünüydü onlar. Ahh badem ağacı,  ne çok beklerdi o ilk yazı. Çünkü çiçeklerinin erkencileri dalları yarar ve uzatırlardı kuğu gibi boyunlarını güneşe hemencecik. İlk zamanlar, belki birkaç yıl, ne kadar da üzülürdü  onlar için. Çünkü bilirdi ki, bu yalancı bahardır, çok değil birkaç gün sonra yeni fırtınalar başlayacak, yağacak dolu talan edecekti çiçekleri, ve onlar daha yaşamdan nasiplenmemişken, güneşin asıl keyfini sürmek için daha bolca vakitleri varken, yok olacaklardı. Bilirdi ve hep ağlardı onlar için. Badem ağacı bilmez miydi ki bu yalancı bahardır, güneşin koynuna sokulmak için daha çokça zamanları vardır.

Dedesi bu sessiz iç geçirişi anlamış gibi bir gün elinden tutuvermiş ve onu ağaca doğru götürmüştü. “Haydi, başını ağacın gövdesine daya” demişti. “Ne dediğini anlayabiliyor musun? ”

Hayır, doğruyu söylemek gerekirse badem ağacının gövdesinden hiç ses işitmemişti o ana değin. Zaten en uçuk kaçık çocuk hayallerinde bile ağaçla konuşmak aklına gelmemişti.

Dedesi sevgiyle saçlarını okşadı. “Onu anlaman için sana yardımcı olabilir miyim? ” diye sordu.

Ah! Evet, bunu çok istiyordu…

“O halde dinle! Diyor ki! Bizim için ağlama! Biz yalancı bahara bilerek kanıyoruz. Her şeyden önemlisi onun “sahici bahar” olduğuna inanmak istiyoruz. Çünkü O’nun bize değil, bizim O’na koyduğumuz anlam önemli. Her mevsim onun koynunda solsak da, bu bir aşktır ve biz güneşe de yaşama da aşkla bağlıyız…”



Demek böyle söylüyordu badem ağaçları. Kısacık bir zaman diliminde yaşamak bile yetiyordu onlar için. Asıl ilginç olanı hiçbir yenilgiden ders almıyorlar, her yıl aynı zamanda yeni bir yenilgi için gelinlik kız gibi düşlerinin peşine düşüyorlardı. Tek umutları bir gün o yaşadıkları şeyin “yalancı” değil onun “sahici bahar” olduğunu görebilmekti belki de. Belki bunlar onların umurunda bile değildi. Aşkla, güvenle, inatla, sadakatle, bilgelikle bağlıydılar yaşama. 

Dedesi böyle öğretmişti ona. Aşkla, güvenle, inatla, sadakatle, bilgelikle bağlı kalacaktı O da hayata. Hangi yenilgi dizlerini kırsa da, o daha büyük bir aşkla tutunacaktı yaşama. İnandığı için, kendi de anlatacaktı torunlarına... 

Ama ya dün.. Buraya getiriliş nedeni. Ah! ! ! Herkesin bir sınırı vardı işte. Dedesi burada olsaydı, O’na güveni ve inanmayı anlatırdı. Krizin etkisiyle kendini eve zor atmıştı. Evdeki fındık farelerinden kurtulmak için satın alıp sonra kedisi için yaşamsal tehdite dönüşebileceği aklına gelerek, bir kenara bırakıp kullanmadığı fare zehrini bir bardak suya boca etmiş ve bir solukta mideye indirmişti. Aradan çok zaman geçmemişti. 20-25 dk kadar. Hıçkırıklarla minik bedeni sarsılıyordu hala. Kutsal bir ayindeymiş gibi dedesinin ruhunu çağırıyordu. Tek istediği onun sıska vücuduna başını gömmek ve ağlamasını sürdürmekti.

Sonra tuhaf bir şey oldu. Portakal büyüklüğünde sarı renkli bir ışık pencereden içeriye süzüldü. Evin içinde bir tur attıktan sonra bahçeye çıktı. Birkaç ağacın ve otun arasından kaybolup gitti.

Bunun bir işaret olduğunu anlamıştı. Evet evet, dedesi onun umutsuzluğunu hissetmiş ve ona mesaj göndermişti. Peki ya mesaj neydi? Ah ne olurdu aklı biraz daha iyi çalışıyor olsaydı? Taşındığı bu kentte badem ağacı yoktu ki, dedesi onu işaret etsindi. Birkaç saat önce yağmur yağmıştı. Toprak kokuyordu her yan. Bir iki gün önce elleriyle yolarak çiçeklere yol açtığı bir iki ayrık otu yine yeni sürgün vermişlerdi. Çok değil üç beş gün sonra sanki hiç sürülmemiş gibi bahçeyi yeniden talan edeceklerdi. Şu ayrık otu da ne tuhaf bir bitkiydi yani. İnatçı, kendini beğenmiş, istenmediği halde yer işgal etmeyi seven kendini bilmezin biri. 

Düşündü bir an. Ayrık otlarının kendi yaşamlarına koydukları anlam ne olmalıydı? İnatçı bitkiler, dedi tekrar kendi kendine. Dur bakalım, sakın bu inatçılık da badem çiçeklerinin yaşam aşkı olmasındı. Evet, öyle olmalı diye geçirdi aklından. Şimdi içinde büyük bir bulmacayı çözmüş birinin rahatlığı vardı. Aslında hep gözünün önünde duran cevapları görebilmek için dedesi yine mucizevi şekilde ona yol göstermişti. Ama tüm bunlar içindeki acıyı azaltmıyordu.  Hala acı çekiyordu işte. Tek dostu yoktu. Ailesinden kimse kalmamıştı. Bir tek kedisi. O da kim bilir şu anda neredeydi. Geldiğinden beri hiç kimse bacağına dolanmadığına göre komşu evleri turlama zamanıydı.

Midesinde kramplar hissetti. Beyni son birkaç dakikadır başka şeylerle meşgul olduğundan fare zehrini tamamen unutmuştu.  Neyseki eve geldiğinde yaptığı ilk şey (demek ki dedi kendi kendine, bu fikir iş yerinden ayrıldığımdan beri kafamı meşgul ediyor olmalı, öyle ya, eve gelir gelmez yaptığı ilk işti)  telefona sarılmak olmuştu. En yakın hastanenin telefon numarasını isteyip, kaydetmişti. Çünkü son ana kadar seçim şansı elinde kalsın istiyordu. 

İşte bir yol ayrımındaydı şimdi. Kendini bu dünyaya, bu oyuna ait hissetmiyordu. Peki ya nereye aitti, ne olduğunu bilmediği bir belirsizliğe mi? Gerçekliği ağır basıyordu, bundan emindi. Gri renklerle süslenmiş hayatının tek renkli simgesi dedesi ve badem çiçekleri olmuştu. Tüm  soruları sormuş, cevaplarını vermişti, devam edecekse rutin bir yaşama devam edecekti.. Gelecekle ilgili kehanetleri yoktu. Şu andaki nokta da, gelecek de tam bir bulmacaydı. Badem çiçeklerinin ya da ayrık otlarının o inatlarında geleceğe dair inanç var mıydı ki sanki? Sadece an’ın aşkı mıydı onlarınki. Önünde iki seçenek vardı. Tıpkı onların ki gibi. Peki ya ölüm, ölüm nasıldı? Ahhh Tagor; ne diyordu o ilahi anektodta “ölüm, kapını çaldığı anda, ona ne sunacaksın? ”: Badem çiçeklerini.. Hayır hayır, onlar olmaz. Peki ya ayrık otlarını..Elbette onlar da olmaz, inatçı bitkiler, ölüm yok onlar için... Peki ya neyi? Kendimi mi? 



Eli telefona gitti. Adresini ancak verebilmişti. Sonra bilinci yitti.

                    (Ocean Rose)', 'Ağzında zehir zemberek bir tatla uyandı. Vakit gece yarısını çoktan geçmiş olmalıydı. Tüm iç organları matkapla delinircesine acı çekiyordu....', ARRAY['Türk Edebiyatı','Şiir','Derin Deniz']::text[], 8.5, '{"poet":"Derin Deniz","poet_slug":"derin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/badem-cicekleri-ayrik-otlari-ve-yalanci-baharlara-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cennetten Cehenneme Ama Önce Kıyamete', 'cennetten-cehenneme-ama-once-kiyamete-olcay-karal-fur2u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Paranın güneşte parlayan pulları yakarken gözlerimizi

Denizin kızıllığında soyacağız bedenlerimizi

Kargalar eşlik edecek kıyametin şarkısına

Gökyüzü yolumuzu çizecek kanatlı umutsuzluklarımızla

Tüm yüklerimizi krallığımız yüzünde taşıyacak

Ve tüm bebeklerimizi yakacağız ayrılmadan önce

Silahlarımızı da', 'Paranın güneşte parlayan pulları yakarken gözlerimizi Denizin kızıllığında soyacağız bedenlerimizi Kargalar eşlik edecek kıyametin şarkısına...', ARRAY['Türk Edebiyatı','Şiir','Olcay Karal']::text[], 8.5, '{"poet":"Olcay Karal","poet_slug":"olcay-karal","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/cennetten-cehenneme-ama-once-kiyamete-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Buket Çiçek Düştü', 'bir-buket-cicek-dustu-sadik-softa-taypn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gecenin ayazına, 

bir buket çiçek düştü.

Uzaklar yakınlaştı, 

hayale gerçek düştü.

Masum bakışlarında 

erirken cümle canım; 

Kaşlar yayca gerildi; 

yanağa pürçek düştü.

Gözlerini gözlerdim,

incitmeye korkardım.

Yanımdayken özlerdim,

sevda ile bakardım.

Yüreğim serinlese, 

deniz-derya yakardım; 

Çakmak çakmak gözlerden,

Kıvılcım - civek düştü.

Gecelerim karıştı,

gecenin deryasına,

Hasret kaldı uykular,

rüyaların hasına.

Bir avuç tuz döküldü; 

yaramın ortasına; 

Hayal, rüya beklerken,

önüme gerçek düştü.

      

Çankırı-29.01.2004', 'Gecenin ayazına,  bir buket çiçek düştü. Uzaklar yakınlaştı,  hayale gerçek düştü. Masum bakışlarında  erirken cümle canım;  Kaşlar yayca ge...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-buket-cicek-dustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulutların Çocukları', 'bulutlarin-cocuklari-cigdem-bir-genc-silav', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yağmurların habercisi olmalı 

Bu kurşuni gökyüzü

Nasılda sancıda bulutlar! 

Fırtına öncesi sessizliğe aldanma

Belli ki kopacak bir isyan az sonra

Ve doğacak bulutların çocukları

Damla, damla yağacaklar bir ormanın koynuna

Görür gibiyim bir serçeyi,yıkanırken 

Bulutların çocuklarıyla sarmaş dolaş...', 'Yağmurların habercisi olmalı  Bu kurşuni gökyüzü Nasılda sancıda bulutlar!  Fırtına öncesi sessizliğe aldanma Belli ki kopacak bir isyan az ...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Bir Genç']::text[], 8.5, '{"poet":"Çiğdem Bir Genç","poet_slug":"cigdem-bir-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bulutlarin-cocuklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kisaca Ben', 'kisaca-ben-onur-batur-c1hz4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayatın anlamı sen mişsin meğer,

Sensiz bir dünya kuyuya benzer.

Zaman akıyor bilmez ki keder,

An gelir gözlerin gözlerime değer.

Yüzünde var gönülden bir eser,

Sevgim aslin o pak kalbinde yer.

Şu kulun o zaman sana şükreder,

An gelir ellerin ellerime değer.

Darılma ey gönlüm buda geçer,

Aşkı tarif etse ancak aşk eder.

Bu yolda olmakda var sensiz derbeder,

An gelir kalbin kalbime değer.

İşte o an gelir yer gök inler,

Kalbim bir deniz bir deryada yüzer.

gel gör ki mustakbel buna ne der? 

Seninle bir an bir ömre değer.', 'Hayatın anlamı sen mişsin meğer, Sensiz bir dünya kuyuya benzer. Zaman akıyor bilmez ki keder, An gelir gözlerin gözlerime değer. Yüzünde va...', ARRAY['Türk Edebiyatı','Şiir','Onur Batur']::text[], 8.5, '{"poet":"Onur Batur","poet_slug":"onur-batur","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kisaca-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akamayan Ses', 'akamayan-ses-aynur-uluc-haynd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hızlanan  sesti düşüş

Yaklaşan bir fırtına

Halatını düpedüz

Bağladılar hayata

Sessiz nefessiz kaldı

Orada dilsiz kaldı

Kalbi atar görünüp

Yüreği susuz kaldı.

Azgın sular çekildi

Bir göldü manzara

Heyecan eksildi

Boşa koptu yaygara

Ne olurdu yolun sonu

Görmek  istemediler

Mecbur ettiler onu

Yaşamasın dediler

Yaşamasın bakalım

Yaşadığı yere dek

Bir de böyle akalım

Tıkadığı yere dek.', 'Hızlanan  sesti düşüş Yaklaşan bir fırtına Halatını düpedüz Bağladılar hayata Sessiz nefessiz kaldı Orada dilsiz kaldı Kalbi atar görünüp Yü...', ARRAY['Türk Edebiyatı','Şiir','Aynur Uluç']::text[], 8.5, '{"poet":"Aynur Uluç","poet_slug":"aynur-uluc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/akamayan-ses-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığa doğru', 'yalnizliga-dogru-sirma-mersin-rjho2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dili çözülmüş duyguların; 

Satırlara yansıyan dizelerinde,

Gizlenmiş birçok anlam,

Bunca zaman susan yürekten...

Sırlara mahkum gecelerden,

Soluk alan hayaller,

Uzanır yalnızlığa doğru...

22.01.03', 'Dili çözülmüş duyguların;  Satırlara yansıyan dizelerinde, Gizlenmiş birçok anlam, Bunca zaman susan yürekten... Sırlara mahkum gecelerden, ...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yalnizliga-dogru-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahipsiz Sevgim', 'sahipsiz-sevgim-sirma-mersin-sh0vl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayatın esiri olmuş; boş bir benliği taşıyorum, üzerimde...

Çoğu zaman; vurdum kendimi yalnızlığa.

Oan! çoğalan umutsuzluğumu, yalnızlığa sarıp ağlıyorum, sessizce...

Gecelere teslim olmuş; hüznü taşıyorum, yüreğimde.

Kimsenin görmediği sahipsiz sevgimle; hayalleri yaşıyorum, karanlığın koynunda! Hasretin çözüldüğü an; yüreğimden dökülen cümleleri yazıyorum,

sayfalara.Her defasında; bambaşka duygulara yorulmuş satırları, paylaşıyorum yaşamla...

26.01.04', 'Hayatın esiri olmuş; boş bir benliği taşıyorum, üzerimde... Çoğu zaman; vurdum kendimi yalnızlığa. Oan! çoğalan umutsuzluğumu, yalnızlığa sa...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sahipsiz-sevgim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Esrük Sevda', 'bir-esruk-sevda-sadik-softa-pelg1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kadehlerde ışık ışık nur.

Kafalarda bir esrük sevda savrulur.

Çölde sıcak mayalanır, gönülde sevda; 

Ferhatlar, Mecnunlar, Keremler kavrulur.', 'Kadehlerde ışık ışık nur. Kafalarda bir esrük sevda savrulur. Çölde sıcak mayalanır, gönülde sevda;  Ferhatlar, Mecnunlar, Keremler kavrulur...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bir-esruk-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Protez', 'protez-ozgur-kizilkaya-nrx33', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'çok kırdın kalbimi biliyormusun

senin yüzünden kanla sıvadım 

kalbimin aşk sızan çatlaklarını

ziyan oldu içimde biriken  onca sevginin aşkın yarısı

ziyan ettin aslında sen o aşkın yanında beni

ama sen giderken beni götürdün birazda

ve alamadım senden götürdüğün kendimi

biliyormusun şimdi yaşamam için

bana o ziyan ettiğin aşk gerek

korkarım bundan böyle

protez  bir aşkla yaşamam gerekecek', 'çok kırdın kalbimi biliyormusun senin yüzünden kanla sıvadım  kalbimin aşk sızan çatlaklarını ziyan oldu içimde biriken  onca sevginin aşkın...', ARRAY['Türk Edebiyatı','Şiir','Özgür Kızılkaya']::text[], 8.5, '{"poet":"Özgür Kızılkaya","poet_slug":"ozgur-kizilkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/protez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalanın Yanında', 'yalanin-yaninda-caglar-yildiz-u9i7x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yürüyorduk seninle bir bahar vakti

Bahar gelmemişti daha

Yollar girintili çıkıntılıydı

Ayakkabının topuğu kırıldı sırtıma alayım dedim 

Alamadım ayıp kaçardı

Sonra gecekondu mahallesinden geçerken büyük şehir belediyesi konduları yıktı

Üstümüz toz revan olmuştu

Eve gitmeye karar verdik 

Eve gidip televizyon izleyecektik ama RTÜK bütün kanalları kapatmıştı

Kapanan kanallar içinde bizde vardık

Uyuyalım dedik uykumuz yoktu yoğurt yiyelim dedik 

(Uyku yapardı) 

Kasede yoğurt kalmamıştı ayyın ortasıydı zaten cebimizde para yoktu

Uyuduk uyuduğumuzdan haberimiz yoktu

Sabah oldu

Çalışmaya mecburduk sen işi gittin bende

Sen yeni açılan bir mağzanın satış memuruydun ben ise benim ne olduğumu bilmiyordum

Sadece çalışıyordum 

Akşam oldu eve geldim evde yoktun

Masaiye kaldım zannettim kalmamıştın

Aradım nereyi arayacağımı bilmeden

Sonra cesedini buldum

Uçağın çarptığı trenin altında kalmıştın

Ben yaşamaya mecburdum yaşayamadım

Beyoğlunun arka sokaklarında şarap şişeleri içinde

İçmeden öldüm

Beyoğlunu hiç görmemiştim', 'Yürüyorduk seninle bir bahar vakti Bahar gelmemişti daha Yollar girintili çıkıntılıydı Ayakkabının topuğu kırıldı sırtıma alayım dedim  Alam...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Yıldız']::text[], 8.5, '{"poet":"Çağlar Yıldız","poet_slug":"caglar-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yalanin-yaninda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Susuyorum', 'ben-susuyorum-ozgur-kizilkaya-lz995', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'anlatabilmeyi isterdim sana seni...

imgemde her parlayıp söndüğünde yüzün,

hayalinin bende bıraktığı izleri

göstermek isterdim yüreğimde...

yazık söylemeye bile cesaretim yok

içime atıyorum, hapsediyorum sana dair hislerimi

zindanlarımda, prangalarımda, zincirlerimde

hepsi sessizliğimdir artık

içime atıyorum söylemek istediklerimi

nereden başlasam bilemiyorum,

neresinden tutsam elimde kalıyor sözlerim.

hiç kullanılmamış olmalı

sana anlatmak için kuracağım cümlelerin tüm kelimeleri,

hiç biraraya gelememiş kelimeler kavuşmalı cümlelerimde...

anlatabilmek hislerimi sana

ama o kadar zorki bu benim için

iki harfli bir kelimeyi

hecelemeye çalışmak gibi birşey bu

hissetmiyorsun sen ama

bazen cümlelerimden aşk sızıyor sana

farketmiyorsun bunu belkide

ve anlatamamak bir yılan gibi kıvrandırıyor beni

söyleyememek ise zehir...

sözcüklerin hepsi dilimi yakıyor

ve anlatamıyorum işte kahretsin...

kemiriyor beynimi düşüncelerim

kirpiklerim birbiriyle kanlı bıçaklı düşman

inadına küs kalıyorlar geceleri birbirilerine

ta ki ruhum yorgun düşene kadar

bedenim sızana kadar küs...

bu düşünce çok yoruyor beni

izahatsiz duygularım var sana dair! 

düşüncelerim ayaklanma başlatıyor

her seferinde yalnızlığımla bastırıyorum isyanlarımı

akrebin kendini sokması gibi birşey bu

kendi isyanımı kendim bastırıyorum

ne yapsam boş, sana çivilenmiş düşüncelerimin hepsi...

göremiyorsun sen aslında

nasıl yalnızlıkla kıvrandığımı

ve başımı alıp gitmek isterken çok uzaklara

bitmez sandığım yollar bile tükenmiş

artık sessizliğimle başbaşayım şimdi

ve arkamı dönüyorum yalnızlığa...

şimdi ben susuyorum sen dinle

anlatamasamda dinle sessizliğimi

sana susuyorum,

yalnızlığımı dinle, anlatamadıklarımı dinle,

anlatmak istediklerimi dinle,

kendini birde benim sessizliğimden dinle,

söyleyemediğim sözlerimden dinle kendini

ve benim gözlerimden bak kendine,

seni nasıl sevdiğimi sözcüklerle anlatamadım ama

belki sessizliğim anlatır sana

birde ondan dinle!', 'anlatabilmeyi isterdim sana seni... imgemde her parlayıp söndüğünde yüzün, hayalinin bende bıraktığı izleri göstermek isterdim yüreğimde... ...', ARRAY['Türk Edebiyatı','Şiir','Özgür Kızılkaya']::text[], 8.5, '{"poet":"Özgür Kızılkaya","poet_slug":"ozgur-kizilkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/ben-susuyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelir', 'gelir-sadik-softa-rxvyn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ademle başlar hayat, Nuhla tufanlar gelir.

İnsanı sevdada eritecek anlar gelir.

Gözlerine bakıp da aldanmayın sakın; 

Sen melaike beklersin, ne şeytanlar gelir.

                                 02.06.2003 - Çankırı', 'Ademle başlar hayat, Nuhla tufanlar gelir. İnsanı sevdada eritecek anlar gelir. Gözlerine bakıp da aldanmayın sakın;  Sen melaike beklersin,...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gelir-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanında Yalanın', 'yaninda-yalanin-caglar-yildiz-m7d2l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yürüyorduk seninle bir bahar vakti

Bahar gelmemişti daha

Yollar girintili çıkıntılıydı

Ayakkabının topuğu kırıldı sırtıma alayım dedim 

Alamadım ayıp kaçardı

Sonra gecekondu mahallesinden geçerken büyük şehir belediyesi konduları yıktı

Üstümüz toz revan olmuştu

Eve gitmeye karar verdik 

Eve gidip televizyon izleyecektik ama RTÜK bütün kanalları kapatmıştı

Kapanan kanallar içinde bizde vardık

Uyuyalım dedik uykumuz yoktu yoğurt yiyelim dedik 

(Uyku yapardı) 

Kasede yoğurt kalmamıştı ayyın ortasıydı zaten cebimizde para yoktu

Uyuduk uyuduğumuzdan haberimiz yoktu

Sabah oldu

Çalışmaya mecburduk sen işi gittin bende

Sen yeni açılan bir mağzanın satış memuruydun ben ise benim ne olduğumu bilmiyordum

Sadece çalışıyordum 

Akşam oldu eve geldim evde yoktun

Masaiye kaldım zannettim kalmamıştın

Aradım nereyi arayacağımı bilmeden

Sonra cesedini buldum

Uçağın çarptığı trenin altında kalmıştın

Ben yaşamaya mecburdum yaşayamadım

Beyoğlunun arka sokaklarında şarap şişeleri içinde

İçmeden öldüm

Beyoğlunu hiç görmemiştim', 'Yürüyorduk seninle bir bahar vakti Bahar gelmemişti daha Yollar girintili çıkıntılıydı Ayakkabının topuğu kırıldı sırtıma alayım dedim  Alam...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Yıldız']::text[], 8.5, '{"poet":"Çağlar Yıldız","poet_slug":"caglar-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yaninda-yalanin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onlar Ki', 'onlar-ki-sadik-softa-z3abb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Levhu Mahfuzda da saklıdır adları; 

Kıldan incedir, yürürler sıratları; 

Onlar ki gönül erbabıdır her dem; 

Engelsiz geçerler sıratları.

                       02.06.2003 - Çankırı', 'Levhu Mahfuzda da saklıdır adları;  Kıldan incedir, yürürler sıratları;  Onlar ki gönül erbabıdır her dem;  Engelsiz geçerler sıratları.    ...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/onlar-ki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki de bir olmak', 'i-ki-de-bir-olmak-ensar-cevval-nh0ix', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İki de bir olmak

iki de bir atmaya başlayınca kalpler

kan karışır

iki nehrin denizde buluşması gibi

ısınır,çağlar gider delicesine

öyle tebessümler yayılırki yüzlere

sanki temmuz güneşini tutmuş gibi

sanki yakamoz yutmuş gibi

ve iki de bir görünür görecekleriniz

hangi adımının önde olduğunu göremezsin

hangi adımda kaldın sayamazsın

yerden uzaksın

altından geçen bulutlara şaşırırsın

ve bir melek tutar ellerinden sımsıcak

uyanırsın alnındaki sımsıcak izle

ve anlarsın...

artık ikide birsin bu alemde

bir çift gözde tarayınca saçlarını

iki göz tek bakar artık

iki yürek yok artık

iki de bir olmuşsun artık

iki de bir...

29 Ocak 04 Üsküdar', 'İki de bir olmak iki de bir atmaya başlayınca kalpler kan karışır iki nehrin denizde buluşması gibi ısınır,çağlar gider delicesine öyle tebe...', ARRAY['Türk Edebiyatı','Şiir','Ensar Cevval']::text[], 8.5, '{"poet":"Ensar Cevval","poet_slug":"ensar-cevval","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/iki-de-bir-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derler', 'derler-sadik-softa-lugej', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yakışır, ağır olmak insana, kâmil derler,

Yakışır, kâmile ki bizde, kemal derler,

Kemal ve kamillik olgunluktandır elbet,

Ağırsa insan; ya kemal, ya kamil derler.

                                       

                                09.06.2003 - Çankırı', 'Yakışır, ağır olmak insana, kâmil derler, Yakışır, kâmile ki bizde, kemal derler, Kemal ve kamillik olgunluktandır elbet, Ağırsa insan; ya k...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/derler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GülümSeme', 'gulumseme-sadik-softa-czaxq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ey gülüm! ...  Gülümseme.

Bahtım, sen gülümseme.

Gülüm gönül vurgunu; 

Çarpılmış, gülüm seme.

	      

   27.01.2004 - Çankırı', 'Ey gülüm! ...  Gülümseme. Bahtım, sen gülümseme. Gülüm gönül vurgunu;  Çarpılmış, gülüm seme. 	          27.01.2004 - Çankırı...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gulumseme-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahşere Kadar', 'mahsere-kadar-abdullah-atay-3nzy4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Damarımdasın anbean

Aşkınla çarpar yüreğim

Boy atar sürgünde sevdam

Meşkinle açar çiçeğim...

Gönül bahçemiz şenlenir

Şakıyıp coşar bülbüller... 

Bizle raks edip eğlenir

Menekşe,lale,sümbüller... 

Ömrüme ömrünü bağlar

Güller kokan nakışların

Yaralı gönlümü dağlar

Çöller yakan bakışların...

Gecemde gündüzümde sen. 

Yokluğunda hep hüzün var. 

Bitmesin mutluluk erken, 

Mahşere kadar sözün var...', 'Damarımdasın anbean Aşkınla çarpar yüreğim Boy atar sürgünde sevdam Meşkinle açar çiçeğim... Gönül bahçemiz şenlenir Şakıyıp coşar bülbüller...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mahsere-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıldırtan Bina', 'cildirtan-bina-aynur-uluc-tc533', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çıldırtan binayı çocuklar bilir

Yeterince fanatikseler çizgilere

Çıldırtan binayı büyükler bilir

Binaya girip de akıllı  kalabildilerse', 'Çıldırtan binayı çocuklar bilir Yeterince fanatikseler çizgilere Çıldırtan binayı büyükler bilir Binaya girip de akıllı  kalabildilerse...', ARRAY['Türk Edebiyatı','Şiir','Aynur Uluç']::text[], 8.5, '{"poet":"Aynur Uluç","poet_slug":"aynur-uluc","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/cildirtan-bina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam Gibi', 'adam-gibi-mehmet-kalay-2mc82', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çok ağır dostlar,

Çok ağır...! 

Aşkı yaşamak,

Sevmek,

Yaşamı adamak.

Sevgiye esir düşmek,

Uğruna tüketilmek.

Onurun ve namusun, 

Sahte yalanlarla,

Ayaklar altında olduğunu görmek.

Ayrılık...! 

Diri, diri yakılmak.

Duru sevgiye, 

Saplantı diyenleri duymak.

Yaşama elveda derken,

Anlatmak,

Anlaşılmamak...! 

Zayıf ve dirayetsiz anılmak.

Sıcak, 

Soğuk, 

Ayaz...! 

Borç batağında,

Parkları, 

Sokakları mekan edinmek.

Bi çare mücadelede,

Sırt dönenleri görmek.

Dünden daha zor yaşamda, 

Var olma savasında,

Acılan dost ellerde, 

Mahcubiyet...! 

Dizelerle gelen duyguları, 

Buram, buram yüreğinde hissetmek.

Yaşama elveda diyen bedenlere, 

Can olmak.

Seneler senesi,

Sevgiye esir yaşamda,

Unutamamak,

Yaşarken ölüm,

Yok edilenmiş gelecek.

Velhasıl kelam dostlar,

Adam gibi,

Çıkarsızca sevmek...! 

Adam gibi adam olmak...! 

Çooook zor...! 

28.01.2004 - İstanbul', 'Çok ağır dostlar, Çok ağır...!  Aşkı yaşamak, Sevmek, Yaşamı adamak. Sevgiye esir düşmek, Uğruna tüketilmek. Onurun ve namusun,  Sahte yalan...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kalay']::text[], 8.5, '{"poet":"Mehmet Kalay","poet_slug":"mehmet-kalay","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/adam-gibi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölü Yaşam', 'olu-yasam-mehmet-kalay-myx4e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yolun yarısını geçmiş yaşamda, 

Sınavımsa yaşamak,

Ölmüşüm zaten...! 

Bedenim,

Ruhum. 

İsyanı mı yaşamalı.

Parça, parça olmuş,

Deşilmiş yüreğim.

Hep mi kanamalı. 

Darmadağın yaşam,

Her atakta,

Tuzaklara mı esir olmalı.

Suratıma indirilen her şamarda,

Derin ahlar mı çekilmeli.

Akan gözyaşlarında,

Defalarca, 

Boğulmalı mı insan.

Gülmeyen gözler, 

Karanlıklarda, 

Körlüğü mü yaşamalı.

Soruyorum hakka,

Suçum ne? 

Ölü yaşamda,

Bitmeyecek mi bu zülüm? 

24.01.2004 - İstanbul', 'Yolun yarısını geçmiş yaşamda,  Sınavımsa yaşamak, Ölmüşüm zaten...!  Bedenim, Ruhum.  İsyanı mı yaşamalı. Parça, parça olmuş, Deşilmiş yüre...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kalay']::text[], 8.5, '{"poet":"Mehmet Kalay","poet_slug":"mehmet-kalay","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/olu-yasam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Öleceğim...!', 'ben-olecegim-mehmet-kalay-8ac1s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen...! 

Dipsiz kuyularda...! 

Yüreğimi kanatıp,

Acı içinde beni boğarken.

Susmayacağım...! 

İnkarını,

Ruhsuz ruhunu anlatacağım.

Haksız haksızlığını, 

Haykıracağım...! 

Sen çektirdikçe, 

Ben yazacağım...! 

Sen...! 

Pişmanlığı yaşarken,

Okuyacaksın.

Ben, 

Öleceğim...! 

28.01.2004 - İstanbul', 'Sen...!  Dipsiz kuyularda...!  Yüreğimi kanatıp, Acı içinde beni boğarken. Susmayacağım...!  İnkarını, Ruhsuz ruhunu anlatacağım. Haksız hak...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kalay']::text[], 8.5, '{"poet":"Mehmet Kalay","poet_slug":"mehmet-kalay","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ben-olecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Titrek Bir Hüzün', 'titrek-bir-huzun-mine-ozdemirtas-ngv2l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yoksa! 

Yağmur mu yağıyor uzaklara? 

Ki, küçük kıyamet kopmuş gibi

Kararmış yüzün. Ve

Titrek bir hüzün

Gitgide sararmada yaprağında.

Bilmiyorum! 

Büyük kıyamet kuşkusu mu var  aklında.? 

Ki, sanki yüreğin göçük altında.

Bu durumda,

İnce bir sızı da; 

Kemanının telini iyice zorlamada

Korkma! 

Sana hiç söyleyen olmadı mı? 

Ki, güneş sonsuza kadar saklanamaz

Dağların arkasına

Ve.... Benim hatırıma,

Karanlığa gülümse / allah aşkına.

29/01/2004 ist.', 'Yoksa!  Yağmur mu yağıyor uzaklara?  Ki, küçük kıyamet kopmuş gibi Kararmış yüzün. Ve Titrek bir hüzün Gitgide sararmada yaprağında. Bilmiyo...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/titrek-bir-huzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Silikon Maske', 'silikon-maske-aynur-uluc-fw8z2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'tek tek boyardı imgelerini

kendi tanıklığında yol alıp bilinmezden

melodi arardı zihnine

hayâli kemanlar sesiydi fırtınaların

lir, berrak denizlerin ağıdı

yeni ''ben'' çıkana dek rahminden

bitimsiz sancılara vururdu ahengini 

siyah, yâr olurdu sarmalamaya

dudağında nefesi, yüzünde kara

fırlattığında kurtulur 

boynuna yaklaşınca anlardı

boğulduğunu

nefese direnirdi  lâkin

tâkat kalmazdı yelkovanlarda

karıncalar sarardı vücudunu

beynini süngersiler

doğruldu

güneşe baktı perdelerin ardından

ellerine baktı, kendi boynunda

boydan boya sünen zardı artık bedeni', 'tek tek boyardı imgelerini kendi tanıklığında yol alıp bilinmezden melodi arardı zihnine hayâli kemanlar sesiydi fırtınaların lir, berrak de...', ARRAY['Türk Edebiyatı','Şiir','Aynur Uluç']::text[], 8.5, '{"poet":"Aynur Uluç","poet_slug":"aynur-uluc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/silikon-maske-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimden..', 'yuregimden-ozgul-ozyilmaz-qx4rh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Göze alabilirim,

Her riski, her çılgınlığı yapabilirim..

Bir gün, yaptıklarımın utancı ile 

Gözlerine bakmaya cesaretim kalmayacağını bilsem bile

Bu kalp sancısına yenik düşüp

Gururumu ayaklarımın altına alabilir

Son bir umut çığlığı atabilirim..

Hem de çok pişman olabileceğimi bile bile

“Gel beni al” diyebilirim..

İçimde yaşattığım 

o son umut kırıntısının da yok olacağını bile bile

“Belki” umudu ile son bir kez sana 

“Emin misin? ” diye sorabilirim..

Bir yarım “yap şunu” derken

Diğer yarım da “dur yapma” savaşlarında..

Sonucunda paramparça olacak olsa da herşey

Ki sensiz zaten yarım kaldım, herşey boşlukta,

Yürek ısrarla:

“Yap şunu! Ya yok ol ya da rahatla! ” naralarında..

Yüreğimdeki sevgin kadar inandığım 

Tanrı inancımsa: 

“Sabret, vardır herşeyde bir hayır” diye 

beni rahatlatmakta..

Ama öylesine gel-gitlerdeyimki

Bedenim bitkin, yüreğim deli deli çağlamakta! ! 

Ruhum bedenime sığamamakta, daralmakta..

Atmaktayım kendimi yollara, 

Sığınmaktayım bir teselli umuduyla

Sevgi dolu dost kollarına.. 

Boşluğunu doldurmak,

Yenik düşmemek için acılara…

Bir yanım ısrarla anılara sarılmakta,

Mektuplar, yazılan-çizilen herşey yeniden okunup, resimlere bakmakta..

Ve beklenen sonuç; gözyaşlarım deli gibi çağlarken

İçimdeki yokluğunun hançeri

Daha da derinlere saplanıp 

Can çekişen ruhumu dayanılmaz acıtmakta..

Bir yanım güzel düşlerde,

Evrene, Tanrı’ya seni dilemekte

Bir yol, bir çare, bir çıkış aramakta..

Hele birde yüreğimde binlerce iç savaş varken

 Beni çıldırtan, yüreğimi deli eden o 

“Bir gün sonsuzluğun bulutlarına oturduğunda, 

ne aklın kalsın ne de kırık bir yürek.. 

Haydi hemen başla” diyen, 

o zamansız ve amansız dizeler 

beni benden almakta..

Ve işte o an kopmaktayım, 

Gözüm kararmakta

İçimdeki deli savaş sil baştan, 

Ve herseferinde daha şiddetle yeniden 

Ve yeniden başlamakta…

“Hadi ara, hadi al riskleri! ! 

Hadi boşver gururu, aptal düşünceleri

Ve ne olacaksa olsun! ! 

Bitir artık şu bekleyişi,

Ya yok ol ya da tüm ol! ! ” demekte..

Özleminle dolu kanserli yüreğimse

“Sabır güzel Allahım sabır! 

Akıl güzel Allahım akıl! 

Huzur güzel Allahım huzur,

Sen Yardım et! Sen yol göster! 

Sen yardımcı ol, 

Doğruyu yapmama bir işaret, 

Yanlışı yapmama sen engel ol Allahım! ! ” 

diye avaz avaz yakarmakta..

“İnanırım planında hiçbir şey aksamaz,

İnanırım yazılan bozulmaz,

Ve sen bana dayanma gücü, 

sabır ve sakinlik ver Allahım..

Yine sana sığındım,

Yine sana yakarıyorum..

Neyleyim yokki senden başka 

Sorgusuz sualsiz bağlandığım

Mucizelerine, hayrına inandığım..

Yokki senden başka içimdeki yangını görebilen

Ruhumun derinlerindeki isyanı ve inancı hisseden..

Sen yardım et! 

Sen bir umut, bir ışık ver 

Yaşamak için! Hayatın anlamı için! 

Yeniden şu deli yüreği ayaklandırmak için..! ! ”

Diye diye yüreğimdeki deli isyanı biraz olsun yatıştırmakta....', 'Göze alabilirim, Her riski, her çılgınlığı yapabilirim.. Bir gün, yaptıklarımın utancı ile  Gözlerine bakmaya cesaretim kalmayacağını bilsem...', ARRAY['Türk Edebiyatı','Şiir','Özgül Özyılmaz']::text[], 8.5, '{"poet":"Özgül Özyılmaz","poet_slug":"ozgul-ozyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":82,"source_url":"https://www.antoloji.com/yuregimden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalimdeki Derin Mavi', 'hayalimdeki-derin-mavi-nigar-adak-xfeth', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bülbülün yokmuş derde sabrı,

Her lahzada bin feryadı.

Ey Bülbül; ehl-i temkinem.

Sinemdeki ateş Yâr´dı.

Bir ilahi neşe doğsun,

O tatlı nağmeli dilinden.

Gölgelendirme hülyamı,

Dökülsün dizeler, yüreğinden.

Çalsın sazlar, 

İnlesin tamburlar.

Ritminde raksedeyim,

Varsın bana alem divane desin.

Sağır Sultan duysun,

İçimdeki cihana sığmaz sevgiyi.

Yeter ki, yaşatayım,

Hayalimdeki, o derin maviyi.

(Açıklama: Ehl-i temkinem - Ben temkin ehliyim - vakarlı, ağırbaşlıyım..)                

Nigar Adak

29.01.2004

Dikkat: Şiirlerimin hepsi noter tasdiklidir..! Şair adı olmadan alıntı yapılamaz..!', 'Bülbülün yokmuş derde sabrı, Her lahzada bin feryadı. Ey Bülbül; ehl-i temkinem. Sinemdeki ateş Yâr´dı. Bir ilahi neşe doğsun, O tatlı nağme...', ARRAY['Türk Edebiyatı','Şiir','Nigar Adak']::text[], 8.5, '{"poet":"Nigar Adak","poet_slug":"nigar-adak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hayalimdeki-derin-mavi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzülme!', 'uzulme-yusuf-pangal-wbr5m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Elinde bir sarı gül saklıyordu, İstanbul

Hazin sonun büyüsünden boğaz kararmıştı

Ve ellerim soğuktan birbirini sarmıştı…

Neden bu kimsesizin bahtı hep karanlıktır? 

Üzülme,hepsi geçer; efkârın bir anlıktır.

Zaman akıp gidiyor… Yıllar geçti ömründen.

Üzülme! Hangi bahar, dönmemiş ki sürgünden? 

Döner… Evet,dönecek; bunu sen de istersen.

Üzülme! Gözyaşı: beyhûdedir,ziyanlıktır.

Üzülme,hepsi geçer; efkârın bir anlıktır.

                                                                                                             

05/09/2001

                                                                                                        

*18. yaş günümde…', 'Elinde bir sarı gül saklıyordu, İstanbul Hazin sonun büyüsünden boğaz kararmıştı Ve ellerim soğuktan birbirini sarmıştı… Neden bu kimsesizin...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Pangal']::text[], 8.5, '{"poet":"Yusuf Pangal","poet_slug":"yusuf-pangal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/uzulme-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırtınam', 'firtinam-yusuf-pangal-90evn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir derya içindeyim.Rotam yanlış yönlerde…

Pusulalarım şaşmış… Dalgalar,boğulmakta…

Ufka dalmış gözlerim; hani sahiller nerde? 

Fenerlerim kaybolmuş; güneş artık âfakta…

Bulutları ağlıyor,karanlık gökyüzünün

Rüzgarlar dünden küsmüş; yelkenlerde bir hüzün…

Fişekler atılıyor… Bu ne müthiş bir düğün! 

Davul sesi mi desem? Bir gürültü, uzakta…

Rüyâmda duyduğum ses:müjdeliyor,o ânı; 

Çoşsa bile dalgalar; boğsa da dört bir yanı; 

Önümde belirecek: kurtuluşun limanı.

Bulacağım yönümü… Sen ışığını yak ta…

                                                                                                             

01/06/2002', 'Bir derya içindeyim.Rotam yanlış yönlerde… Pusulalarım şaşmış… Dalgalar,boğulmakta… Ufka dalmış gözlerim; hani sahiller nerde?  Fenerlerim k...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Pangal']::text[], 8.5, '{"poet":"Yusuf Pangal","poet_slug":"yusuf-pangal","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/firtinam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Sayfaları Karıştırırken...', 'eski-sayfalari-karistirirken-yusuf-pangal-cfmjw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Resmin ellerimde… Yüzün kederli…

Boynun ışıltılı,pür mücevherli.

Sadece dudakla gülsen yeterli...

Geçti mi senin de kapından,hazân? 

O ne solgun bakış; yüzünden sızan,

Hasta mısın yoksa? Neyin var,Sûzan? 

Gamzende saklardın türlü gülüşler; 

Ne oldu umutlar,kurduğun düşler? 

Sonbahar gülleri gibi ölmüşler…

Hâlinden bir hüzün seziliyor da…

Aynaya bakarken rûhuna sor da

Aradığı aşkı bulmuş mu,orda? 

                                                                                      

15/12/2003', 'Resmin ellerimde… Yüzün kederli… Boynun ışıltılı,pür mücevherli. Sadece dudakla gülsen yeterli... Geçti mi senin de kapından,hazân?  O ne so...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Pangal']::text[], 8.5, '{"poet":"Yusuf Pangal","poet_slug":"yusuf-pangal","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/eski-sayfalari-karistirirken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşam Üzeri', 'aksam-uzeri-yusuf-pangal-5effu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her yerde kızıllık; solgun çiçekler…

Yerinde güneşin,yeller esiyor

Mavi ay,sabırsız,doğmayı bekler; 

Zûlmet,acımadan, ufku kesiyor.

Muttasıl,yaprağın macerâsıyla; 

Gölgeler,oynaşır karanlık suda.

Dünyayı bir daha görmek yasıyla; 

Yıldızlar,kederle bekler pusuda.

Rengi değişirken aldan,karaya

Yavaşça sönüyor âhengi,ufkun.

Söyler misin bana? Ey köhne dünya! 

Ne kadar sürecek,bu derin uykun? 

                                                                                             

18/05/2002-01/042003', 'Her yerde kızıllık; solgun çiçekler… Yerinde güneşin,yeller esiyor Mavi ay,sabırsız,doğmayı bekler;  Zûlmet,acımadan, ufku kesiyor. Muttasıl...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Pangal']::text[], 8.5, '{"poet":"Yusuf Pangal","poet_slug":"yusuf-pangal","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/aksam-uzeri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar', 'bahar-yusuf-pangal-097uk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gölgeler raks eder,rüyâ oynaşır; 

Bir heves,bir akış… Şu berrak suda.

Her ağaç gövdesi,bir heycân taşır; 

Sallanır yaprağı,meltem vurunca…

İzlenmeye değer: bu yeşil bahçe; 

Havuz kenarında bülbül ötünce.

Şenlik mi,cümbüş mü…? Yoksa dün gece; 

Beklenen bir şey mi,geldi,uykuda? 

                                                                                               

07/08/2003', 'Gölgeler raks eder,rüyâ oynaşır;  Bir heves,bir akış… Şu berrak suda. Her ağaç gövdesi,bir heycân taşır;  Sallanır yaprağı,meltem vurunca… İ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Pangal']::text[], 8.5, '{"poet":"Yusuf Pangal","poet_slug":"yusuf-pangal","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bahar-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyler misin Be Hancı', 'soyler-misin-be-hanci-emin-baydil-4qj19', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sonbahar yaprakları, süsler sarı turuncu,

Ayaklarımda hışırtısı / geçmiş zamanın...

Hayalimde canlanır; bir ilk, bir de sonuncu,

Sevdayı yaşamamış sancısıymış zamanın.

Hatırlarım; ufkumda, dağlar beyaz olurdu,

Bahar gelmezdi hiç, gönlüm ayaz olurdu,

Başımdaki kar benim, ellere yaz olurdu,

Uğradığım her menzil, hancısıymış zamanın.

Yolların kıvrım kıvrım orta yerinde ömür,

Bugün de gördüm hâlâ, sürünür de sürünür.

Kan revan içindeyim, ele başka görünür,

Bunca çekmeme sebep acısıymış zamanın.

Susadıkça akıttım, içime gözyaşımı,

Vurulmuşum, süs diye saklamışlar başımı,

Her tarafta kol gezer, ölüm sormaz yaşımı,

Ecel şahin kanatlı, avcısıymış zamanın.

Hayatın merdiveni, ey ömür! Bu kaçıncı? ..

Tükendikçe, benden mi? .. Nerden alırsın hıncı? ..

Gelip de kalan var mı? Söyler misin be hancı? ! 

Anladım ki şu yollar, savcısıymış zamanın...', 'Sonbahar yaprakları, süsler sarı turuncu, Ayaklarımda hışırtısı / geçmiş zamanın... Hayalimde canlanır; bir ilk, bir de sonuncu, Sevdayı yaş...', ARRAY['Türk Edebiyatı','Şiir','Emin Baydil']::text[], 8.5, '{"poet":"Emin Baydil","poet_slug":"emin-baydil","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/soyler-misin-be-hanci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürekde yare var...', 'yurekde-yare-var-sevim-erdemir-z07sn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yürekte yare var,

gönülde atas,

arada daglar var,

kalpte hasret...

gözün gözüme degmiyor,

sözün sözüme ermiyor

engeller senden yana silinmiyor

gönülde hüsranlar var...

gel de geleyim yanina gülüm

öl de öleyim ugruna

tek engelleri sokma da araya

iste yolunda can verem iki gözüm...

bir can nedir ki ugruna feda etmeye

beklemekle bir hayat gidiyor

bu,verecegim candan da fazla...', 'yürekte yare var, gönülde atas, arada daglar var, kalpte hasret... gözün gözüme degmiyor, sözün sözüme ermiyor engeller senden yana silinmiy...', ARRAY['Türk Edebiyatı','Şiir','Sevim Erdemir']::text[], 8.5, '{"poet":"Sevim Erdemir","poet_slug":"sevim-erdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yurekde-yare-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle oldum', 'oyle-oldum-ferit-teksoy-8i95n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'üçüncü dilimde,

son dönemdeyiz

uzat elini demiştim

bir şiirimde.

öyle bir uzattın ki! 

pır pır etti yüreğim

öyle oldum liselin

sıcacıktı bana uzattığın el

gözlerim gözlerinde asılı kaldı

lâl oldu dilim.

iyi ki biraz olsun,

yazmayı biliyordum

öyle oldum şairin

masaldaki kurbağaydım önceden

bir buseyle değiştirdin dünyamı

çiçek açtı yüreğim.

ikinci baharı 

getirdin gelişinle

sığmaz oldum kabıma

öyle oldum sevgilin

görüyor doymuyorum,

seviyor kanmıyorum

seninle dolu gönlüm

yar''lığınla hayalim.

oysa senden öncesi,

tek sigara içerdim

öyle oldum tiryakin

şimdi yukardakini,

rahat bırakmıyorum

ya hiç buldurmasaydın,

yada artık ver diye.

ya bıkacak verecek,

ya kızacak verecek

öyle oldum talibin..', 'üçüncü dilimde, son dönemdeyiz uzat elini demiştim bir şiirimde. öyle bir uzattın ki!  pır pır etti yüreğim öyle oldum liselin sıcacıktı ban...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/oyle-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Yusuf Değilim', 'ben-yusuf-degilim-firat-karakurt-n39rr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yusuf eğlemişler adımı

Atmışlar karanlık bir kuyuya.

Kuyu sevinçli

Yusuf''u geldi zannetmiş

Çünkü aydınlanmıştır içi

Ama değildir onun Yusuf''u

Kuyu bir Fırat''a bakmış bir derin suyuna

Anlam verememiş içindeki bu aydınlığa.

Kuyu kör,kuyu sağır

Duymamış,görmemiş

Fırat''ın kalbindeki sevda ateşini.

Ama kuyu ruhsuz değil

Anlamış sonunda.

Kuyu gaddar değil

Boğmamış sularında,

Fırat,Yusuf olmasada.

Kuyu tatminkar,

Kuyu vefalı.

Sahip çıkmış Yusuf''una yani Fırat''ına

Çünkü ruh var kuyuda.

(Erzurum  21.12.2003)', 'Yusuf eğlemişler adımı Atmışlar karanlık bir kuyuya. Kuyu sevinçli Yusuf''u geldi zannetmiş Çünkü aydınlanmıştır içi Ama değildir onun Yusuf''...', ARRAY['Türk Edebiyatı','Şiir','Fırat Karakurt']::text[], 8.5, '{"poet":"Fırat Karakurt","poet_slug":"firat-karakurt","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ben-yusuf-degilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Yatsı Vakti', 'yine-yatsi-vakti-ahmet-aksoy-xj7xx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eski düşler düştü üzerime,

Ağır, ağır, ağır bir şekilde,

Ben geçmişte kurtulmak istenilen,

Ve o gün bugündür, kurtulunan,

Nasıl bir hayaletle yaşıyorum ki,

Gerçek onun yüzünde

Sadece, sadece, sadece,

Gerisi yarım kalmış cümlelerde,

Tam ve tükenmez bir yalan,

Aslında hayat dediğim

Çoktan sıyrıldı vücudumdan,

Gerisi yalan yanlış vakitlerde,

Kırık bir ruh hali,

Neden nedense ölüm,

Bir ayrılık vakti,

Bana yardan kalan,

Ve son satır, son cümle,

Düş kaçağına, kırgından selam.', 'Eski düşler düştü üzerime, Ağır, ağır, ağır bir şekilde, Ben geçmişte kurtulmak istenilen, Ve o gün bugündür, kurtulunan, Nasıl bir hayaletl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yine-yatsi-vakti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakut', 'yakut-ahmet-aksoy-2a6oe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dokuz ejder alevi yakamaz beni

Senin beni her zaman yaktığın gibi

Ah! bir tek katren eritir hançeremi

Aşkın döner durur içimde ruh gibi.', 'Dokuz ejder alevi yakamaz beni Senin beni her zaman yaktığın gibi Ah! bir tek katren eritir hançeremi Aşkın döner durur içimde ruh gibi....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yakut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başka Ses', 'baska-ses-i-brahim-i-spir-45xrc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gözlerime takılan türkü

bu havayı kaçıramam

ben rüzgârı toplarım

seslenir gözüme bakınca

bu ses

belleğimde isyan

nelerdi

anlatamam

dinle 

başka bir seste yüreğim', 'gözlerime takılan türkü bu havayı kaçıramam ben rüzgârı toplarım seslenir gözüme bakınca bu ses belleğimde isyan nelerdi anlatamam dinle  ba...', ARRAY['Türk Edebiyatı','Şiir','İbrahim İspir']::text[], 8.5, '{"poet":"İbrahim İspir","poet_slug":"i-brahim-i-spir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/baska-ses-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Komik Aynalar', 'komik-aynalar-ahmet-aksoy-0lwct', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'lunapark aynaları arasında

……..geçti yıllarım

ben, kimi zaman zayıf

……kimi zaman şişman

ben, kimi zaman uzun

…….kimi zaman kısa

lunapark aynaları arasında

….ellerim büyük ellerim küçük

kimi zaman tek kimi zaman on parça

luan park aynaları arasında

ne olduğumu anladım 

………..ne de olmadığımı

……..geçti yıllarım.', 'lunapark aynaları arasında ……..geçti yıllarım ben, kimi zaman zayıf ……kimi zaman şişman ben, kimi zaman uzun …….kimi zaman kısa lunapark ayn...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/komik-aynalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin', 'gittin-abdullah-garip-h07sk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gittin   uzaklara     döner misin

Unutulmayıp hatırlanmayı sever misin

Öyleyse al kalemi eline yaz

Seni sevenleri sever misin

Gönlünden, kalbinden, fikrinden yaz

Hayaline gönlüne uğra da yaz

Kalbine fikrine  uğra da yaz

Derya - ova gezip yazmasını sever misin

Gül bahçelerinden geç, kar çiçekleri seç

Gönül bahçenden geç, fikirden seç

Bağnazlıktan geç, hoşgörüden seç

Sen gönülden yazmasını sever misin

Gönül kızar, kalp susar

Akıl kızar, hizmet susar

Bilen susar, seven susar

Nakadirşinasları da sever nisin', 'Gittin   uzaklara     döner misin Unutulmayıp hatırlanmayı sever misin Öyleyse al kalemi eline yaz Seni sevenleri sever misin Gönlünden, kal...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gittin-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asude Bir baharda', 'asude-bir-baharda-abdullah-garip-7jm6v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ASUDE BİR BAHARDA			

			

Asude bir baharda			

Çiçeğin kokusunda			

Rüzgarın serinliğinde			

Pervaz et kelebeğim yakaladığın o ana			

			

  en heybetli fırtana gönülde			

Dolunayın aydınlattığı yerde			

yağmur selleri ümit deryasında			

Pervaz et kelebeğim görünmez zamana			

			

Toprağın ılıklığı ruha varmaz			

En pahalısı gönül avında kalmaz			

Yorulmadan kavuşmak olmaz			

Pervaz et kelebeğim yakaladığın o ana', 'ASUDE BİR BAHARDA			 			 Asude bir baharda			 Çiçeğin kokusunda			 Rüzgarın serinliğinde			 Pervaz et kelebeğim yakaladığın o ana			 			   e...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/asude-bir-baharda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuslat', 'vuslat-abdullah-garip-umigh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Vuslat			

			

Yorgunmusun uzaklardan geldin			

Sevgimi yitirmişe benzersin			

Sen gidince sıkıyor buralar beni			

Engel olamam kiralar elemler beni			

			

Yüreğimde ince düğüm vuslat			

İçimde bir gurbet buhurdanı vuslat			

Rüyalarımda hep gördüğüm vuslat			

A........     Adanmış baharıdır vuslat.', 'Vuslat			 			 Yorgunmusun uzaklardan geldin			 Sevgimi yitirmişe benzersin			 Sen gidince sıkıyor buralar beni			 Engel olamam kiralar eleml...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/vuslat-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmem ki...', 'bilmem-ki-abdullah-garip-erc3d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bilmem  Ki...

Bilmem yüreğinde iz var mı? 

Bilmem anlatırmısın,sevgimiz bu kadarmı

Ben hala kementleşen sevdadayım

Mesafem artı ama o tatlı andayım.

Beni hüzünlendiren anılar vardı

Akşamın gizemli dudaklarında

Ben hala kementleşen sevdadayım

Mesafem artı ama o tatlı andayım.

Uzaklara gitti bir dilber

Unutuluşun rüzgarı esip durdu

Ben hala kementleşen sevdadayım

Mesafem artı ama o tatlı andayım.

Sırrını kayıp ettim mesafelerin

S...... Bana gizli alem oldu dilber

Ben hala kementleşen sevdadayım

Mesafem artı ama o tatlı andayım.', 'Bilmem  Ki... Bilmem yüreğinde iz var mı?  Bilmem anlatırmısın,sevgimiz bu kadarmı Ben hala kementleşen sevdadayım Mesafem artı ama o tatlı ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bilmem-ki-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir An Sonra Ayrılık Vakti', 'bir-an-sonra-ayrilik-vakti-ahmet-aksoy-kj9ft', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ürkeklik arama

kurt gözlerinde siyanür vakti

aşk artığı! Senin için artık yok

vicdan ya da merhamet

terk edildin sevda coğrafyanda 

artık yalnızsın tüm dünyada

kurduğun iskele çöktü kendine

ve inşa olamaz istesende bir daha

kalk! Önce soluna sonra sağına bak

düştüğün eski düşler kaldırımı

geçeceksen üstünü silkele

ve yerde bırak üzerine asılan zamanı

yürü! Ardına bakma, 

bakarsan ezilirsin ya da bak ve ezil 

eski aşkın göz yaşları boğsun seni

göremezsen içindeki su yılanlarını

sana kalan acıtan ödünç hatıralar

geri ver, borç bitsin. kalacaksan sağlıcakla kal! 

kalmayacaksan tüken ve tüket kendini

son verdiğin ödün kendin ol, hesap bitsin! 

son söz, vakit bu şiir için erken fakat

saat ayrılığı bir an önce geçti aşk artığı

sofrada kalan kırıntıların kaldırıldı

sen ne kadar yenilsen de sindin.', 'ürkeklik arama kurt gözlerinde siyanür vakti aşk artığı! Senin için artık yok vicdan ya da merhamet terk edildin sevda coğrafyanda  artık ya...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-an-sonra-ayrilik-vakti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Turnaları', 'sevgi-turnalari-abdullah-garip-j0hj1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevgi  Turnaları

Bedenimde çıban çıban ağrılar

Sevgi turnaları yakalıyorum

Turnalar gidiyor bn kalıyorum

Yitik gülüşlerini arıyorum

Kayıpolmuş sevgilerin rasladım izine

sen gönlümde gönüllü kalmayı bilensin

Bakışına sığındım çağır beni yatayım dizine

Bir kere olsun dön de ''.......'' de

İçimdeki gurbetin vuslatı sende

Çile deryasına düştüm yelkeni sende

Bırakda git bari yüreğim sende

Bir kere olsun dön de ''.......'' de', 'Sevgi  Turnaları Bedenimde çıban çıban ağrılar Sevgi turnaları yakalıyorum Turnalar gidiyor bn kalıyorum Yitik gülüşlerini arıyorum Kayıpolm...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevgi-turnalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bedenime İnat', 'bedenime-i-nat-hasan-huseyin-ozak-n9vyw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilmezdim,

gecelerin bu kadar kahpe,

bu kadar hain,

yalnızlığınsa, yenilmez olduğunu

Yıllar yılı farkına bile varamamışım,

içimdeki çocuğun büyüdüğünü

Bir gardiyan gibi,

teker teker kilitlemekte bütün kapıları, çaresizlik

Bilmezdim,

bu yorgun kalbin hala aç, hala genç

ve şeytan gibi yeni aşklar isteyeceğini.

Geçmişi ölü gömer gibi toprağa gömüp

bedenime inat,

gün be gün gençleşeceğini', 'Bilmezdim, gecelerin bu kadar kahpe, bu kadar hain, yalnızlığınsa, yenilmez olduğunu Yıllar yılı farkına bile varamamışım, içimdeki çocuğun ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özak']::text[], 8.5, '{"poet":"Hasan Hüseyin Özak","poet_slug":"hasan-huseyin-ozak","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bedenime-inat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duydun mu', 'duydun-mu-abdullah-garip-9lhup', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Duydun mu ney sesini,içimdeki hıçkırıktır 

Her çiçekte kokun,her gülde rengin var 

Gittin gideli bu gönül kırıktır 

Her anımda,her yerimde sesin var.', 'Duydun mu ney sesini,içimdeki hıçkırıktır  Her çiçekte kokun,her gülde rengin var  Gittin gideli bu gönül kırıktır  Her anımda,her yerimde s...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/duydun-mu-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-abdullah-garip-iznue', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sensiz			

			

Sensiz geçen her gece			

dilimde ismin hece			

Yarim nerelerdesin			

yanıma gel gizlice			

			

Hoş gelir bana hoi	ana hoş gelir		

Söylediğin acı sözlerin bile hoş gelir			

Gideli gönlüme hep kış gelir			

Seni gördüğümde nev bahar gelir			

			

Gözümü açtığımda gördügüm sensin			

Gece rüyamda gündü', 'Sensiz			 			 Sensiz geçen her gece			 dilimde ismin hece			 Yarim nerelerdesin			 yanıma gel gizlice			 			 Hoş gelir bana hoi	ana hoş geli...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sensiz-71-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-abdullah-garip-9j0x3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zaman			

			

Uyku yavuklum,yatak kokundu			

Acı burgu gibi göze dokundu			

Sızı sızı elem su olmuş sızıyor			

Acıların sınıf sınıf zamanı okundu			

			

Zaman dnizinde gemiler demir almaz			

Hasret yüklenen zaman geriye gelmez			

Zaman içinde liman yok durmaz		ok duramaz	

Zamana kimse pıranga vuramaz.', 'Zaman			 			 Uyku yavuklum,yatak kokundu			 Acı burgu gibi göze dokundu			 Sızı sızı elem su olmuş sızıyor			 Acıların sınıf sınıf zamanı ok...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/zaman-109-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rabbim', 'rabbim-abdullah-garip-v9q1x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'RABBİM			

			

Dertlerime dermansın RABBİM			

Gönüllere fermansın  RABBİM			

Affeder affı seversin  RABBİM			

Kapına geldim hallerimle,			

Affına geldim hallerimle RABBİM RABBİM			

			

Sürçüp düşmelerim çoktur			

Günahlarıma sayı yoktur			

Senin affın daha çoktur			

Kapına geldim hallerimle,			

Affına geldim hallerimle RABBİM RABBİM			

			

Perde açılınca insanlığı gördüm			

Göz açılınca lütuflar buldum			

Gönlüm sukunete erim			

Kapına geldim hallerimle,			

Affına geldim hallerimle RABBİM RABBİM			

			

Gönülde sukut,ruhda huzur			

Hakkı bilen rahmet bulur			

Durma artık buna sarıl			

Kapına geldim hallerimle,			

Affına geldim hallerimle RABBİM RABBİM			

			

Gönül aradığını buldu			

Dile virdler doldu	oldu		

Göze yaşlar doldu			

Kapına geldim hallerimle,			

Affına geldim hallerimle RABBİM RABBİM			

			

Gözüm yaşı akmaz oldu			

Sineme sızılar doldu			

Yaralar lime çıban oldu

Kapına geldim hallerimle,

Affına geldim hallerimle RABBİM RABBİM', 'RABBİM			 			 Dertlerime dermansın RABBİM			 Gönüllere fermansın  RABBİM			 Affeder affı seversin  RABBİM			 Kapına geldim hallerimle,			 Af...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/rabbim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak Kendini', 'birak-kendini-hasan-huseyin-ozak-qcp0r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gitmek mi zor kalmak mı? 

Tutunmak mı siyah yaşanmışlıklara,

fırtınalarda.

Yoksa, boğulmayı göze alarak,

kapıp koyuvermek mi kendini,

Mavi Umutlara', 'Gitmek mi zor kalmak mı?  Tutunmak mı siyah yaşanmışlıklara, fırtınalarda. Yoksa, boğulmayı göze alarak, kapıp koyuvermek mi kendini, Mavi U...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özak']::text[], 8.5, '{"poet":"Hasan Hüseyin Özak","poet_slug":"hasan-huseyin-ozak","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/birak-kendini-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pardüsü', 'pardusu-abdullah-garip-21utf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Pardüsü		

			

Giymeden pardüsülük nezaketi			

Askıya takılan görgümüzü			

Nazik kibar zerafeti			

Gösterelim gerçek yüzümüzü

Nezaket ve beyefendilik

Bir tarafta da sinir ve aksilik

Biliyorsun ki sinirliyim

Meşru olansa hasbilik

Bir nezakete bin teşekkür dışarıda

Bir kusura bin haşinlik içeride

Eşini küçümseme marifeti   

Beyini kusurlama hasleti

Dışarı taşınan aile meseleleri

......................... ruh haleti

 Eşinin ailesini dışlayan

Bu yüzden birbirini haşlayan

İnsanlık o ki birleştireni bulmak

Ortak müşterekte karar kılmak', 'Pardüsü		 			 Giymeden pardüsülük nezaketi			 Askıya takılan görgümüzü			 Nazik kibar zerafeti			 Gösterelim gerçek yüzümüzü Nezaket ve beye...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/pardusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al Beni', 'al-beni-abdullah-garip-oxuu0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'dAl  Beni

Gördümemet demet sevgi dökülüyor gözünden

Hissettim sıcak sıcak sevgi akıyor elinden

Ilgıt ılgıt sevgi yeli esiyor dilinden

Al beni içine sar beni derinden

Bazen mahsunlaşıp dalıyordu uzaklara

Bazen heycanlanıp koşuyordu duraklara

Bazen hırçınlaşıp dalıyordu dudaklara

Al beni içine sar beni derinden

Ölçüyordu thammülümü,ölçüyordu sevgimi

Bozulunca leblerle koyordu dengini

Hele o gözlerin,hele o gözleri rengini

Al beni içine sar beni derinden

Koşuşturmak hayalinde,koşuşturmak halinde

Kemer olayım mı ince belinde? 

Şeker olup dilinde,dolaşayım her yerinde

Al beni içine sar beni derinden', 'dAl  Beni Gördümemet demet sevgi dökülüyor gözünden Hissettim sıcak sıcak sevgi akıyor elinden Ilgıt ılgıt sevgi yeli esiyor dilinden Al ben...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/al-beni-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Gece', 'ey-gece-abdullah-garip-08btq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ey  Gece

Ey gece koynuna aldın gülleri

Ey hazan,hazin eyledin bülbülleri

Ey ayrılık viran ettin gönülleri

Yeti koyup bağ-ı vefa olamadın

Sevdalılar gül alıp,gül satar

Gül olanlar gül tahtında yatar

Soldurursa elindeki gülleri

Mesafeler gül alırken gönülden

Gördüm ırmağı denize kul

Irmağa binmiş garip yolcuyu bul

Kavuş güle,düş yola yorul

Yplcu kayıp,denize varmadan.', 'Ey  Gece Ey gece koynuna aldın gülleri Ey hazan,hazin eyledin bülbülleri Ey ayrılık viran ettin gönülleri Yeti koyup bağ-ı vefa olamadın Sev...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ey-gece-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Satıyorum...', 'satiyorum-adnan-ferit-0jodi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tohumuna para mı saydım

Vicdansız.

Akrabam dostum da değilsin.

Elinden bir yudum su mu içtim

İki kalem sohbet bile etmedim.

Ama sen,

Bir çöktün boğazıma,

Bir daha kalkmadın.

Bırak nefes alayım,

Yaşadığımın farkına varayım.

Para dedikleri hayırsız, senin gözün kör ola,

Allah tüm dostlarını benzetsin bir gün bana.

Senin yüzünden sarıldı bu bela başıma

Senin yüzünden yaşanıyor günler onursuzca....

Elbet geçer diye başladığım her gündoğumunda

Geceyi daha erken karşılarken,

Korkar oldum  yaşamaktan 

Gece ile gündüzü aynı anda.

Bilirim ki sondur o an,

Bilirim ki nefes tükenmiş

Umutların ardından.

Can bedenden çıkmasa da,

Ruhsuz kalmış sallanır boşlukta.

Para! ! ! 

Nefret de etsem senden

Yardım et,

Söyle bana,

Denemekte vardır belki bir fayda,

Senin gözünle ne öderler bu garibanın ruhuna.

At üç beş de, kurtarırız belki onurumuzu

Onursuz dostlarının karşısında..', 'Tohumuna para mı saydım Vicdansız. Akrabam dostum da değilsin. Elinden bir yudum su mu içtim İki kalem sohbet bile etmedim. Ama sen, Bir çök...', ARRAY['Türk Edebiyatı','Şiir','Adnan Ferit']::text[], 8.5, '{"poet":"Adnan Ferit","poet_slug":"adnan-ferit","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/satiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gönül Gözyaşlarım', 'sen-gonul-gozyaslarim-abdullah-garip-shdez', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'zihnim seni düşünüyor				

yüreğim seni sevmeye mahkum				

sevdan ömrümü tüketirken				

ruhum gurbet içinde sensizliğe hasret				

				

				

busevdalarda ben ağlamaktayım				

ben girdaplarda ben yanmalardayım				

sen mesafeli arşınlayan uzaklarda				

ben ruhumun gurbet ilinde,kendime yabancıyım				

ben sevdnın ucunda sensizliğe yanıyor ve ağlıyorum				

uzaklardasın gel diyemem				

....... Sin özledim diyemem				

başkalarınınsın beni sev diyemem				

				

				

sen ağlamalarım,sen yanmalarımsın				

sen konuşamadığım ve konuşamayacağım				

sen içimde yanan ve yakan hasretimsin				

sen gönül gözyaşlarım,				

sen unutamadığım,unutamayacağımsın', 'zihnim seni düşünüyor				 yüreğim seni sevmeye mahkum				 sevdan ömrümü tüketirken				 ruhum gurbet içinde sensizliğe hasret				 				 				 b...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-gonul-gozyaslarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdadır Gözyaşımı Akıtan', 'sevdadir-gozyasimi-akitan-abdullah-garip-p9rlx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sen ayrılıklarda,sen haretlerdesin

sen bir özlem, sen bir ateşsin

sen bedenimin en ulvi yeri gönlümdesin

sevdandır gözyaşımı akıtan

ayrılıktır ben sana hasret kılan

sensiz yaşamaya mhkum olmak

yüreğimde ki en büyük acımdır

bir sevdana garip kaldım

bir de sevdan içinde kendime

sen sevdamın merkezi,svgin asırlara destan

bilsen bu sevda ne kadar gariban

sevgimin sesini duyarmısın

sen sevgiyi resmedermisin

sevginin matemi nasıldır

karanlıklarda sevgimi yakalarmısın.

sweni dağlara benzetirim

seni çiçeklerde hayal ederim

sesini sularda işitirim

kokunu topraktan alırım

gözden kalbe indin,sevildin

köz idin alavlere döndün

ruhum buruk,kalbim yanık

yüreğimde sevdan oldu şehbal     5.4.2001', 'sen ayrılıklarda,sen haretlerdesin sen bir özlem, sen bir ateşsin sen bedenimin en ulvi yeri gönlümdesin sevdandır gözyaşımı akıtan ayrılıkt...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sevdadir-gozyasimi-akitan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyor musun', 'biliyor-musun-abdullah-garip-flb1h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'biliyor  musun ......			

sevda acıdır			

sevda gözyaşıdır			

sevda kendinden geçmektir			

sevda benlikte tükeniş			

sevda sevdalınla varoluştur			

sevda duyguların gizemi			

sevda bir yanıştır			

sevda sönmeyecek bir ateş			

sevdanın mekanı yürektir			

artık ölü bir benlik,yaşayan bir sevda			

amma acı			

amma bir ateştir			

ve bir kavruluştur			

uzakta bir gönül ki yare kavuşamayacak,			

ruhu ve kalbi hep inleyecek			

bilmemki bu sevda ne zaman dinecek.', 'biliyor  musun ......			 sevda acıdır			 sevda gözyaşıdır			 sevda kendinden geçmektir			 sevda benlikte tükeniş			 sevda sevdalınla varoluş...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/biliyor-musun-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyle', 'boyle-abdullah-garip-kx812', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'böyle sevgilerden uzak,böyle yapayanlız kalmamalıydı bu yürek					

gözyaşlarımda kalbimin sancısı,yüreğimde öfke ateşi					

böyle hırçın,böyleöfke dolu akmamalıydı gözyaşlarım					

böyle yanmamalıydım,öfke ateşiyle alev alev					

yüreğimde dehlizler,ruhumda girdaplar					

ben hep böyle alacakaranlıklar içinde yapayanlız					

yanıyor yüreğim,sızlıyor kalbim,sancıyor gönlüm					

ben hep böyle alacakaranlıklar içinde yapayanlız', 'böyle sevgilerden uzak,böyle yapayanlız kalmamalıydı bu yürek					 gözyaşlarımda kalbimin sancısı,yüreğimde öfke ateşi					 böyle hırçın,böy...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/boyle-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlıuor Duygularım', 'agliuor-duygularim-abdullah-garip-jmrfs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ağlıyor duygularım

ağlıyor hislerim

bilsen nasıl kan ağlıyor yüreğim

sen,sen olmayacaksın benimle bebeğim

ellerim üşüsede

mevcudiyetim inlesede

göz yaşlarımın son damlası aksa da

sen,sen olmayacaksın benimle bebeğim

alevler içinde yanlızlığım

karanlıklar içinde sevdalı yüreğim

sen,sen olmayacaksın benimle bebeğim

yıllar gelip geçecek

sensiz,saniyeler saat,saatler yıl olacak

belki bir gün bu ömür bitecek

sevan yüreğimde hep,hp yaşayacak

sen,sen olmayacaksın benimle bebeğim

bilsen ayrılığı,bilsen gayrılığı

bilsen yürek dolusu hüzünü

sen,sen olmayacaksın benimle bebeğim

analar çocuklarına ninlilerini söyleyecek

benim sevdamın iniltisi hiç bitmeyecek

gece gündüzü,gündüz geceyi kovalayacak

bahar olup çiçekler açacak

mevsimler geçecek

hazanla güller mahzun olup solacak

birtek senin sevgin yüreğimde ebed olacak

sen,sen olmayacaksın benimle bebeğim', 'ağlıyor duygularım ağlıyor hislerim bilsen nasıl kan ağlıyor yüreğim sen,sen olmayacaksın benimle bebeğim ellerim üşüsede mevcudiyetim inles...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/agliuor-duygularim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstedim ki', 'i-stedim-ki-abdullah-garip-wrzb0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'istedim ki elim tutulsun				

istedim ki gözyaşlarım silinsin				

istedim ki banada değer verilsin				

bir yetişkin,bir genç kız denilsin				

biliyorum bu olumsuzluklar cehaletten				

ama yüreğimdeki sevgi kuyusunu dolduramamak				

ruumdaki sancıları dindirememek				

...				

işte ben bilirim sevilmemenin acısını				

sevilipte hissetirilmeyen sevginin acısını				

şimdi diyorum,ben sevgiyi yüreğimde yaşayacağım				

en derin sevgilerle,çocuklarımı büyüteceğim				

sevilmeyen insan sevemez				

sevilmeyen insan güvenemez				

sevildiğini hissetmeyenin yüreği öfkeyle dolar', 'istedim ki elim tutulsun				 istedim ki gözyaşlarım silinsin				 istedim ki banada değer verilsin				 bir yetişkin,bir genç kız denilsin				...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/istedim-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdilerde', 'simdilerde-abdullah-garip-wzshc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'şimdilerde ağlıyorum acılarım için

şimdilerde ağlıyorum çaresizliğim için

şimdilerde gözyaşlarım senin için

duyabiliyor musun hçkırıklarımı

görebiliyor musun gözyaşlarımı

silebiliyor musun ellerinle; 

yanımda değilsin elbet,

şimdilerde sen çok uzaklardasın                     

şimdilerde sen bana çok garipsin

ben hep burada yanlızım

hayalinle yaşıyor,

ellerini tutuyor,boynuna sarılıyorum

hayalinle muhabbet eiyoeum

bak şimdi yine sen yoksun

VE hep sitemle ağlıyorum.

ben böyle garip,ben böyle yalnız

ben böyle virane,ben böyle bitap

gülleri açtırdın,leylaklar soldurttun

kalbimde bir acı bahar yaşsttın

şimdilerde yine sensiz yapayanlız

şimdilerde yine sensiz ağlamaktayım.    23,3,2001', 'şimdilerde ağlıyorum acılarım için şimdilerde ağlıyorum çaresizliğim için şimdilerde gözyaşlarım senin için duyabiliyor musun hçkırıklarımı ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/simdilerde-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdigim', 'sevdigim-abdullah-garip-3qs0t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sevdiğim güzeli gidiyor

kalbimi,ruhumu da aldı götürüyor

bir sevdaki kalpte sökün ediyor.

uzaklarda gel desem gelemez

sevdası yüreğimde bir ateş

kimsecikler söndüremez

uzaktan uzağa ağlaşırım

ben hep onun hayaliyle yaşarım

sevdesını yüreğimde büyüttüm

uğruna ömrümü tükettim

yüreğimi vazgeçirtemem

ben hayalinle avunur,hasretinle koklaşırım

sevdanla ağlaşır,ağlar da konuşurum', 'sevdiğim güzeli gidiyor kalbimi,ruhumu da aldı götürüyor bir sevdaki kalpte sökün ediyor. uzaklarda gel desem gelemez sevdası yüreğimde bir ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevdigim-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerim Beynim Bilmediklerim', 'ellerim-beynim-bilmediklerim-huseyin-cayikli-ap5mc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ellerim yalana dair yaziyor.hangi sayfada yasanmis hikayeler kacinci sayfaya manset oldu eski hatiralar.yasanacak asklar ne zamandir kupon yapilip satiliyor.ben kimlere kiziyorum ben ne yapiyorum.sorgularda kac zanli suclu.kimse aslinda bilemiyor bu sorulari ekmek arasi hayat dedikleri bu.isborta tezgahlarinda yasanmis asklarin acisi.yazik oldu yarinlara derken bir meyhanenin onunde duran insanlik.', 'ellerim yalana dair yaziyor.hangi sayfada yasanmis hikayeler kacinci sayfaya manset oldu eski hatiralar.yasanacak asklar ne zamandir kupon y...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/ellerim-beynim-bilmediklerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bin Bir Alacakaranlık', 'bin-bir-alacakaranlik-abdullah-garip-w2exs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ruhmda bir ayaz,binbir alacakaranlık

gönül bağım ruhumdan kopuk

ellerimde menekşeler,yüreğimde gller

bedenimde sevda kokulu bir bahar

güneşim,günüm aydınlık

gecelerim bitap,günlerim hicran

gönlüm kara sevdayla galyan     23.3.2001', 'ruhmda bir ayaz,binbir alacakaranlık gönül bağım ruhumdan kopuk ellerimde menekşeler,yüreğimde gller bedenimde sevda kokulu bir bahar güneşi...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bin-bir-alacakaranlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlıyormusun', 'anliyormusun-abdullah-garip-2xx8z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Denizin dibi

Gönül enginliği

Ruhumun derinliği

Gözyaşımın sessizliği

Bedenimin sitemi

Anlıyor musun beni

Seni ne kadar çok sevdiğimi

Bir tanecik b sevdiğim', 'Denizin dibi Gönül enginliği Ruhumun derinliği Gözyaşımın sessizliği Bedenimin sitemi Anlıyor musun beni Seni ne kadar çok sevdiğimi Bir tan...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/anliyormusun-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bedenimde Anım', 'bedenimde-anim-abdullah-garip-zdor6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bedenimde anım

gözlerinde hasretin

kalbimde sevgin

ellerinde yaşamım

yüzünde ki tebessümün 

ruhumda huzurum', 'bedenimde anım gözlerinde hasretin kalbimde sevgin ellerinde yaşamım yüzünde ki tebessümün  ruhumda huzurum...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bedenimde-anim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Iyilik Yap Denize At', 'iyilik-yap-denize-at-huseyin-cayikli-wy68g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'mesai vaktinin geldigini anlayip fabrikanin onune giden bendim.iscilerin cikislarini izliyordum.baska bir hevesle baska bir tatla.saclarina kir dusmus yana tarali ve dunaya ya alayli gozden bakan devamli alacakaranligi gulumsemesiyle yok eden bir adam bana dogru her hafta icleri gelirdi.ben beklerdim.yola koyulurduk muhabet ederek yolu bitirirdik.o insanlara insan oldugu icin deger verirdi.kisilikleri ve ne olduklari onu hic ilgilendirmezdi onemli olan insan olmasiydi.isin tuhafi o hic birseye kiyamazdi.kizardim.yillar gecti ben yazilar yazdim afisler bastim gazetelerde kahrolsun diye baskilarin arasinda yuzum gulecek kadar mutluydum.insanlari severdim.o zamana kadar o adamla kendimi ayni hissederdim.Ama o insanlari karsiliksiz severdi bunu anlayana kadar cok irdeledim yasami.ben yapamadim.yenildim.farkliyim ondan diye ic kanamalar gecirdim.ben ne zaman bir olay karsisinda kalsam eylem yolunu secerdim o konusma.bana hep sacma gelmistir konusmalar bitmistir bence eylem vaktirdir herzaman belki gencliktir diyip gecmisimdir.hayatimin eylemlerini bir diz ustu oturup konustum o adamla bana dedi ki yasamin kendisini soyutla ve insanlari sec gibi bisilerdi.bana hala gulebilyordu.oysa o insanlari o kadar sevmisti ki onlarin verdigi acilar karsisinda gulebiliyordu nasil yapiyordu bu oyunu bilmiyordum.aslinda bilmek istemiyordum.dedigi laftir iyilik yap denize at.karsi ciktim kendisine.sonunda birgun oturup kendisine dedim nedir bu yaptigin ne nedir deyince bana laf dusmez anladim o bir humanistti.icimden geldi bunlari yazmak insanlik adina odun veren bir insana yazayim dedim.ona bu yaziyi bir mektup yaptim kendisine gonderdim 

/...nist  oglun', 'mesai vaktinin geldigini anlayip fabrikanin onune giden bendim.iscilerin cikislarini izliyordum.baska bir hevesle baska bir tatla.saclarina ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/iyilik-yap-denize-at-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Dede', 'ay-dede-huseyin-cayikli-rpqgl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sehrin alacakaranliginda korkan sokak cocuklari

ay a bakip dede diye isiginda uyuyorlardi.

ay dedenin ne onlardan haberi vardi

nede ceplerinde ki hayalerinden.

belki ondandir anne kokusu diye 

tiner cekmeleri...', 'sehrin alacakaranliginda korkan sokak cocuklari ay a bakip dede diye isiginda uyuyorlardi. ay dedenin ne onlardan haberi vardi nede ceplerin...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ay-dede-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cikmaz Sevda Sokagi', 'cikmaz-sevda-sokagi-huseyin-cayikli-szvon', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'birisi bana adres sordugunda diyesim geliyor

sola don karsinda bir kalp cikacak

orada ki bir eve gir

sana soyler

burasi 

cikmaz sevda sokagi', 'birisi bana adres sordugunda diyesim geliyor sola don karsinda bir kalp cikacak orada ki bir eve gir sana soyler burasi  cikmaz sevda sokagi...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/cikmaz-sevda-sokagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamazsın...', 'unutamazsin-hasan-basri-kale-zod3z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gün eserse senin de başında

sevda yelleri.

Açılır gönül bahçende

aşkın gülleri...

Sonra dolar gözlerin 

durup dururken

Ardından gelir hiç bilmediğin

gözyaşı selleri..

Duymaya başladığında

dayanılmaz özlemleri...

Gün batımlarını özlersin

sonbaharları bir de..

Yağmurları dost edinirsin

gökgürültülerini içindeki feryatla

bir tutarsın...

Sanırsın ki..hepsi geçer

dönersin yine geri..

Unutamazsın istesen de ''seni''

gelip,yakıp,kavurup

sonra da dönmemek üzere

terkedip gidenleri...', 'Bir gün eserse senin de başında sevda yelleri. Açılır gönül bahçende aşkın gülleri... Sonra dolar gözlerin  durup dururken Ardından gelir hi...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/unutamazsin-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Olmamalıydın', 'sen-olmamaliydin-orhan-kargoz-ood72', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gördümki unutmuş gözlerin rengimi

gördüm ki sen bile sen değilsin

ne yazık ki değişmişsin zamana,

benki vermişyim kendimi hyatına

umrumda olmadan yaşasam bile

ne sevgimde yasak var 

nede aşkımda hile.................', 'gördümki unutmuş gözlerin rengimi gördüm ki sen bile sen değilsin ne yazık ki değişmişsin zamana, benki vermişyim kendimi hyatına umrumda ol...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kargöz']::text[], 8.5, '{"poet":"Orhan Kargöz","poet_slug":"orhan-kargoz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sen-olmamaliydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sevince', 'ben-sevince-oguzkan-bolukbasi-v37vp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ben sevince

çiçekler açar yüzümde

yüzüme bak

ben sevince

kuşlar uçar yüreğimde

yüreğime bak

ben sevince

yanarım

nerede kuşlar

nerede çiçekler', 'ben sevince çiçekler açar yüzümde yüzüme bak ben sevince kuşlar uçar yüreğimde yüreğime bak ben sevince yanarım nerede kuşlar nerede çiçekle...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ben-sevince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup', 'mektup-tevfik-mengulluoglu-r6ewi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'koca koca umutlar yuvarlasam sana; o nice anaların türkülerini yakıp dumanından umutlar var ettiği o kurak,ve buz ağrıdan,mektuplarını okusam cümle cümle,her satırını aşka batırıp uçurtmalar yollasam sana görürmüydün? Neden ağrı bilemiyorum ama orayı hatırladıkça  o kan ve buz dudakların gelir aklıma,düşündükçe ellerim hiçbir yere sığmaz utangaç cümleler düşmeye başlar avuçlarımdan,yağız bir ezgi mırıldanır gece.Ellerim birbirine düşer, Alıp başımı giderim güneşin olduğu her yere, Hatırlıyor musun bilmiyorum ama Havanın bulutlu olduğu günlerde güneşin batıda uyuya kaldığını sanırmışız,şimdi ise,Güneşi her yere nakşediyor boy boy gökkuşakları indiriyoruz çocukların kalbine...Aslında gönlüm nemrutta biliyor musun? hiç büyümeyen ak kuzuların diyarı nemrut,yoo hercai değilim aslında, sadece Her sabah güneşe günaydın demek ve alabildiğine yaşamak güneşin alçak gönüllülüğünü,yazları nemruttan şafak sökerken güneşe tepeden bakılır kimi zaman,Bir o yana koşarsın bir bu yana...bir beşik gibi sallanır beyninde düşünceler arzular taarruza geçer! güneşi kucaklayasın gelir,Bir telaş alır ellerini...Korkuların birbirine dolanır. Oysa o güzelliği tadında bırak der sana içindeki ses onu izleyerek hisset ve gözlerinle dokunmayı dene,dünyada yaşamanın ve hissetmenin başka yollarıda olduğunu bilmelisin,sen varsan onuda var etmelisin der o koca nemruttaki giz.Dona kalır bakışların bir matematik kargaşası başlar beyninde yaşadıklarını yaşayacaklarından çıkarmaya,kaybettiklerini ise umduklarınla çarpmaya başlarsın,hayat sana hiçbir şey vaat etmemişti, oysa! o benliğindeki o evcileşmeyen  yabancının tutsaklığından kurtulmak için buradasın ve artık ötesi yok canım ne yana baksan uçurum,bilseydin gideceğin yeri yıllardır bir ceviz içi gibi içinde taşıdığını belki vazgeçerdin en başından,anlardın her şeyin o kabuğu kırmakla başlayacağını! ama hayatta bunlarda gerekiyormuş sevgili...''yaşam bir şeyler yaparken başka yerlerde kaybettiklerindir'' demiş anımsayamadığım bir yazar.

Özlemlerim bir kavim olmuş dört nala geliyor şimdi,Kırık tasma sesleriyle,ırgat bir sabi oluyorum,toz toprak içerisinde  kalmış bakışları,Yine aklıma düştü nemrut ne zaman köşeye sıkışsam bir imge arardı düşlerim,ufkumda boşluklar dolaşıyor,geçmiş zaman oluyordum kimi zaman,evcilleşmeyen bir yanım peşime düşüyor yalın ayak; ağrıya koşuyorum, gece güneş sancıları çekmeye başladı, az bir vakit kalmış ebesi ol ebrulim. Dur tarayım şimdi saçlarını ellerimle usulca...Biraz daha vakit var, dökülsün saçlarından bir bir hatıralar,bak Aykırı bir sevda esiyor poyrazdan,aykırı bir hüzün var saçlarında; Yum gözünü ebrulim buyruğu gelmiş çocukların,çarmıha gerilen aşklar azade olmuş; yum gözünü ebrulim Kimsesiz bir arzunun kimlik özlemiyle seviyorum seni...', 'koca koca umutlar yuvarlasam sana; o nice anaların türkülerini yakıp dumanından umutlar var ettiği o kurak,ve buz ağrıdan,mektuplarını okusa...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Mengüllüoğlu']::text[], 8.5, '{"poet":"Tevfik Mengüllüoğlu","poet_slug":"tevfik-mengulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/mektup-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gidenin Ardından', 'bir-gidenin-ardindan-oguzkan-bolukbasi-rzcle', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gidiyorlar birer birer

Bir lokma hayatı bölüştüklerimiz

Aklımızda kalan

O güzel anılar 

Gülüştüklerimiz

Niçin diye sormuyorum

Ama hep erken oluyor

Mevsiminde değilken

En sevdiğimiz çiçekler soluyor

Hüzün

Elem

Keder

Davetsiz misafirler gibi

Günlerimize doluyor

Keşke daha fazla konuşsaydık

Keşke daha fazla gülüşseydik

Keşke

Gidiyorlar birer birer

Bir lokma hayatı bölüştüklerimiz', 'Gidiyorlar birer birer Bir lokma hayatı bölüştüklerimiz Aklımızda kalan O güzel anılar  Gülüştüklerimiz Niçin diye sormuyorum Ama hep erken ...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bir-gidenin-ardindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Garip Sevda', 'bir-garip-sevda-ahmet-kurt-3q8lg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevincim hüznüme hep yenik düşer,

Bir garip sevdayla derttedir başım.

Dudağım kuruyor, aklımsa şaşar,

Bir garip sevdayla derttedir başım.

Aşk ile bir ışık gönlüme doğdu,

Güneş korkutuyor karanlık boğdu,

Yalnız insan değil yıldızlar dövdü,

Bir garip sevdayla derttedir başım.

Halimi söylemem hakime bile,

Göğsümün içinden doğuyor çile,

Hasretim dönüyor kırmızı güle,

Bir garip sevdayla derttedir başım.

Yalnız değilim ki mahzun ve mağrur,

Bana miras kaldı atamdan gurur,

Kıskacında beni amansız yoğur,

Bir garip sevdayla derttedir başım.

Geceler uykusuz, gündüzler sönük,

Hengamede geçmiş, ve bölük bölük,

Yönüm bir tek sana, tek sana dönük,

Bir garip sevdayla derttedir başım.

Kurdoğlu ölümle hayat arası,

Tütmüyor bacası, yanmaz çırası,

Yine gelip çattı hesap sırası,

Bir garip sevdayla derttedir başım.', 'Sevincim hüznüme hep yenik düşer, Bir garip sevdayla derttedir başım. Dudağım kuruyor, aklımsa şaşar, Bir garip sevdayla derttedir başım. Aş...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-garip-sevda-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emanet Endişesi', 'emanet-endisesi-bayram-tunca-2dnby', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Verdiğin nice gözler göremediler gerçekleri

Verdiğin nice kulaklar sağırdılar hakikatleri

Verdiğin nice diller haykıramadı hakikatleri

Yerinde kullanılamadık verdiğin emanetleri

B. Tunca/22.01.2003-22.01', 'Verdiğin nice gözler göremediler gerçekleri Verdiğin nice kulaklar sağırdılar hakikatleri Verdiğin nice diller haykıramadı hakikatleri Yerin...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/emanet-endisesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Olamam', 'sensiz-olamam-abdullah-atay-5qpv6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'nasıl muhtaçsa; 

gece mehtaba.

tohum toprağa.

dal yaprağa.

arı çiçeğe.

mahkum özgürlüğe.

gemi limana.

bulut rüzgara.

işte sana öyle muhtacım! ..

biliyor musun? ..

gece gibi 

çöker içime yalnızlık....

nefes alamam  sensiz

boğulurum...

bir yudum sevgiye...

bir nefes umuda...

bir tutam mutluluğa muhtacım.

yıldız bakan gözlerine.

yürek yakan sözlerine muhtaç! ...

sesine...soluğuna...her şeyine...

ben sana muhtacım! ..

anlıyor musun! ..', 'nasıl muhtaçsa;  gece mehtaba. tohum toprağa. dal yaprağa. arı çiçeğe. mahkum özgürlüğe. gemi limana. bulut rüzgara. işte sana öyle muhtacım...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sensiz-olamam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimde Bir Havuz Var', 'i-cimde-bir-havuz-var-bekir-gedikoglu-rocc6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçimde bir deniz var

.....elbetteki canlılar

Uskumrular, Labinler, Kızıllar, Dırıklar

Köpekbalıkları, Balinalar, Yunuslar

Birde...,

Dünya güzeli biri var

Ara sıra gelir kumsala

O zaman...

Sahip olurum bir deniz kızına

Dalgalarımın dillerindeki nağme,

Hep onu söyler

...işte ben buyum

...seni saran,

Bir suyum

Everest tepesinden büyük

Bir dağ var içimde

Çimenler, Şebboyler ve Güller,

Eteklerinde

Orkideler, Zambaklar ve Güller,

Otuz metre yükseklikte

Çamlar, Meşeler ve Kayınlar

Elli metre yükseklikte

Bulunurlar

Hiç bu dağa çıktın mı? 

''SENİ SEVİYORUM''

diye bağrdın mı? 

...aksi sedası

''SENİ SEVİYORUM ''

olacaktır

O kayaların ve dağların değil,

Kaburgalarımın ve yüreğimin bağırtısı olacaktır

Suyu:

Sevgi, saygı ve aşk olan

İçine:

Damla, damla damlayan

Adı:

Kalp olan

Bir havuz var içimde

.........işte arkadaşlar

Sevgisi:

Tükenmeyen

Saygısı hiç bitmeyen

Aşkı:

Karşılık bulan

...O deniz kızı

Bu havuzda yüzecektir

Hep burada kalacaktır', 'İçimde bir deniz var .....elbetteki canlılar Uskumrular, Labinler, Kızıllar, Dırıklar Köpekbalıkları, Balinalar, Yunuslar Birde..., Dünya gü...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/icimde-bir-havuz-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Kar Bulut ve Suyun Hikâyesi...', 'kar-bulut-ve-suyun-hik-yesi-naime-erlacin-4r2wf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'cümle sualler

cümle cevaplar

kar beyazında gizli

denizde noktalanır 

buzun suya erimesi

yankının özenle gizlendiği tepeler 

vadiye sığınmış suskun göllerde belki

bir dağ yamacından süzülüp ürkerek

üstüne yürüyen mağrur dağı 

sever gibi

suya hep hasret toprak

bulut mahzun 

bulut utangaç 

bulut biraz da korkak 

kaçınılmaz yazgısı

suyla toprağı kavuşturmak

bunca yük var sırtında 

ne kadar hafif oysa

nâzım bir ıssızlıkta kanatlanıp 

ak günlere hükmederek şafak vakti

taze bir gebeliğe uyanmaktır eylemi

yaşam döngüsünde yüklendiği 

en keskin anlam

en berrak

aktın

yürüdün

dondun 

bir yolculuk hikâyesi bu

varoluşu ondan sorgula 

ey insanoğlu! 

kar beyazında bekler cümle cevaplar 

tüm hallerin orada gizli

hiçbir son istemez seni 

buluttan gayri

çünkü yakışmazsın ölüme 

(30 Ocak 2004)', 'cümle sualler cümle cevaplar kar beyazında gizli denizde noktalanır  buzun suya erimesi yankının özenle gizlendiği tepeler  vadiye sığınmış ...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kar-bulut-ve-suyun-hikayesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-sair-faga-dqfsf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hazırlıksız dalgalanmaya,

Birazdan olacaklara isteksiz,

Donuk, karanlık gri mavi gözlerin…..

Ben onları böyle hiç görmedim.

Gözlerin…

Şimdi açmak istemediğin.

Hiç sırası değil uyanmanın,

Rüyalarda olmalıydı bu saatlerde….

Bu saatlerde bakmamalıydı gözlerin….

Ben onları böyle hiç görmedim.

Avuçlarınla yıldız saçarken her gece,

Karanlığı yaşamamalıydı gözlerin,

Bu gece,

Sonbahar renkli kadınını  seyretmeliydi,

Böylesine tipiye yakalanmamalıydı

Gözlerin,

Ben onları böyle hiç görmedim….

Kapat onları,

Kapat ki karanlığa bakmasınlar,

Bulutlar tutunamasın kirpiklerine

Çatlamış ovalardan

Yüreğine yağsınlar,

Geleceğin ışığı doldursun odayı,

Tencerelerden karanfil kokuları dağılsın,

Dost eller ayıklasın  acının taşlarını.

Baharları karşılasın cennet yüreğin,

Engin denizler coşsun

Martılar çiçekler atsın,

Ateşler  söndürülsün.

Genç bir ceylan yuva yapsın gözlerinde,

Derinliklerinde sonsuza kadar  saklı kalsın.

Gözlerin,

Güneşi, yıldızları  yansıtmalı,

Yeniden bakmalı  eskisi gibi

Öylesine yeşil, mavi  öylesine renkli gözlerin……

Ben onları öyle görmek isterim.', 'Hazırlıksız dalgalanmaya, Birazdan olacaklara isteksiz, Donuk, karanlık gri mavi gözlerin….. Ben onları böyle hiç görmedim. Gözlerin… Şimdi ...', ARRAY['Türk Edebiyatı','Şiir','Şair Faga']::text[], 8.5, '{"poet":"Şair Faga","poet_slug":"sair-faga","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/gozlerin-94-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gün Yanığız', 'bu-gun-yanigiz-hafize-zuluflu-81ry2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gün yanığız ikimiz de

Yüreğim

Sen sevdadan ölme noktasında

Ben gidip gelmedeyim yıllardır

O uzun yolda

Kimde görülmüş böyle sevgi

Yalan da olsa fallarda

Yaşanır yalansız gözlerde

Yaşanır

Yaşanır bu sevda

İmkansızlarda

30.1.2004', 'Bu gün yanığız ikimiz de Yüreğim Sen sevdadan ölme noktasında Ben gidip gelmedeyim yıllardır O uzun yolda Kimde görülmüş böyle sevgi Yalan d...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bu-gun-yanigiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece Aşk', 'sadece-ask-hakki-hakan-kaya-l5nv3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ne sabahlara 

zengin uyanmayı bekledim

ne de dünyayı 

varlık içinde gezmeyi

sadece aşk

benimleyse eğer

yokluk içinde ölsemde

gönlümün sonsuz zengini

ne sevildi hatalarım 

ne pişmandı sevaplarım

aşkla yoğruldu

tüm günahlarım

her gün 

geceler dolu

rüyalarımda kavuştuğum

kokuna düşman

korkuna esir

rüzgarlarla vuruştuğum

bir bebek hasretiyle

gözlerinde dolaştığım

sabahsız gecelerimin

dipsiz karanlığında

dağlarımla barıştığım

varlığım

sevgilim...', 'ne sabahlara  zengin uyanmayı bekledim ne de dünyayı  varlık içinde gezmeyi sadece aşk benimleyse eğer yokluk içinde ölsemde gönlümün sonsuz...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sadece-ask-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.Aşk', 'ask-melek-midikoglu-90pp8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gece mi gündüz''e

Gündüz mü geceye sevdalı

Kimsecikler anlayamadı

''Tutsak birbirimizi''

''Tutsak birbirimizi''

dedi ışıkları.

Hisler tutsaktı...

Ve yine

Dolunay sabaha 

Güneş akşama kavuştuysa da

Gece gündüz''e

Gündüz geceye varamadı

Kabahat Aşktaydı...', 'Gece mi gündüz''e Gündüz mü geceye sevdalı Kimsecikler anlayamadı ''Tutsak birbirimizi'' ''Tutsak birbirimizi'' dedi ışıkları. Hisler tutsaktı......', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ask-203-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen de Hatıra Oldun', 'sen-de-hatira-oldun-murat-demir-dned8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kayıp gittin elimden

O eski günler gibi

Sen de hatıra oldun

Sen de mi dünler gibi

Alışmıştım seninle

Işığa,aydınlığa

Ne yaptım ki sen beni

Terkettin karanlığa

Oysa ne çok sevmiştim

Bilmiyordun belki de

Beni perişan ettin

İş midir seninki de

Arasamda dünya da

Yaramın dermanı yok

Hep seni düşünerek

Yanacağım senden çok', 'Kayıp gittin elimden O eski günler gibi Sen de hatıra oldun Sen de mi dünler gibi Alışmıştım seninle Işığa,aydınlığa Ne yaptım ki sen beni T...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-de-hatira-oldun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güçsüzlüğümün Gücüm Olmasından Bıktım', 'gucsuzlugumun-gucum-olmasindan-biktim-aynur-uluc-ong6x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağır ağır soluyorum zehri

Hücrelerimi gezerken umutsuzluk

Direniyorum zamana 

Gerçekleşmemiş  vaatler batağında 

Alıp başını gideceksin bilinmeze

Öylesine söylenmiş,  kurtarılmış sanılan

Yalanların nehrinden varacaksın denize

Gittiğin yerde mutlu ol diyecek gücüm yok artık

Güçsüzlüğümün gücüm olmasından bıktım

Boncuklardan takı yapacağım

Her renk bir desen 

Çakışacak tüm olgular

Bakışacak ayrılanlar, derinlerde bir yerde', 'Ağır ağır soluyorum zehri Hücrelerimi gezerken umutsuzluk Direniyorum zamana  Gerçekleşmemiş  vaatler batağında  Alıp başını gideceksin bili...', ARRAY['Türk Edebiyatı','Şiir','Aynur Uluç']::text[], 8.5, '{"poet":"Aynur Uluç","poet_slug":"aynur-uluc","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gucsuzlugumun-gucum-olmasindan-biktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meyveli Gazoz', 'meyveli-gazoz-baris-guc-lyraj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çocukken içtigimiz meyveli gazozlarin tadi gibi sanirdik hayati

Oynadigimiz oyunlarda yapardik en haylaz mizikçiliklari

Daha fazlasina kafamiz çalismazdi; bilmezdik yalani,dolani

Bayram harçliklariyla dolan kumbaramizdi tüm varligimiz

Yedigimiz dondurmaydi en büyük askimiz,keske hep öyle kalsaydi

Bir oyuncakti en çilgin hasretimiz,sabah aksam düsledigimiz

Sadece simarikliktan aglardik,henüz ask acisini tatmamistik

Keske hiç büyümeseydik ve hep çocuk kalsaydik

29.01.2004   sda ozlt     MSN: [email protected]', 'Çocukken içtigimiz meyveli gazozlarin tadi gibi sanirdik hayati Oynadigimiz oyunlarda yapardik en haylaz mizikçiliklari Daha fazlasina kafam...', ARRAY['Türk Edebiyatı','Şiir','Barış Güç']::text[], 8.5, '{"poet":"Barış Güç","poet_slug":"baris-guc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/meyveli-gazoz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Sevdim Onu', 'hep-sevdim-onu-ali-osman-yilmaz-z7i0w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her şeyin çaresi bulunur,

Yalnızlığın ve terkedilmişliğin,

Ne yazık ki çaresi yok,

Vücudu saran kanser gibi,

Naçar beklersin ölümü,

Beklersin gelsin diye,

Herkes bayram kutlarken,

Kara gecelerinde.

Koydu bu kez dostlar,

Düşünürüm Hayyam gibi,

Çıkamam içinden,

Ne sözler söyledim,

Ne şiirler yazdım,

Berlin duvarı yıkıldı da,

Yıkılmadı inadı,

Tutunmak,ayağa kalkmak,

Yeniden başlamak isterim ama,

Bana ne oluyor anlayamam,

Kahpeliğini de görmedim,

Adam gibi yazardı bana,

Son yazısında gerçi,

Neler söylememi istemişti,

En ağır sözler bile yetmez,

Ettiğimin yanında diye,

Doğrusu hiçbir zaman,

Yalan söyledi diyemem.

Tükenmez bir aşk ile,

Hep sevdim onu ben,

Her şiirde,her sözde,

Yakarım aşkımın ağıdını,

Koca Adam gibi sevda türkümü,

Söze bağlar,yollarım size,

Kırmızı güllerimle birlikte.', 'Her şeyin çaresi bulunur, Yalnızlığın ve terkedilmişliğin, Ne yazık ki çaresi yok, Vücudu saran kanser gibi, Naçar beklersin ölümü, Beklersi...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/hep-sevdim-onu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Onları Böyle Hiç Görmedim', 'ben-onlari-boyle-hic-gormedim-sair-faga-2cqhc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gökyüzünde bir yıldız çığlık attı,

Gözlerin aralandı.

Gözlerin,

Yağmur öncesi deniz hali gözlerin….

Hazırlıksız dalgalanmaya,

Birazdan olacaklara isteksiz,

Donuk, karanlık gri mavi gözlerin…..

Ben onları böyle hiç görmedim.

Gözlerin…

Şimdi açmak istemediğin.

Hiç sırası değil uyanmanın,

Rüyalarda olmalıydı bu saatlerde….

Bu saatlerde bakmamalıydı gözlerin….

Ben onları böyle hiç görmedim.

Avuçlarınla yıldız saçarken her gece,

Karanlığı yaşamamalıydı gözlerin,

Bu gece,

Sonbahar renkli kadınını  seyretmeliydi,

Böylesine tipiye yakalanmamalıydı

Gözlerin,

Ben onları böyle hiç görmedim….

Kapat onları,

Kapat ki karanlığa bakmasınlar,

Bulutlar tutunamasın kirpiklerine

Çatlamış ovalardan

Yüreğine yağsınlar,

Geleceğin ışığı doldursun odayı,

Tencerelerden karanfil kokuları dağılsın,

Dost eller ayıklasın  acının taşlarını.

Baharları karşılasın cennet yüreğin,

Engin denizler coşsun

Martılar çiçekler atsın,

Ateşler  söndürülsün.

Genç bir ceylan yuva yapsın gözlerinde,

Derinliklerinde sonsuza kadar  saklı kalsın.

Gözlerin,

Güneşi, yıldızları  yansıtmalı,

Yeniden bakmalı  eskisi gibi

Öylesine yeşil, mavi  öylesine renkli gözlerin……

Ben onları öyle görmek isterim.', 'Gökyüzünde bir yıldız çığlık attı, Gözlerin aralandı. Gözlerin, Yağmur öncesi deniz hali gözlerin…. Hazırlıksız dalgalanmaya, Birazdan olaca...', ARRAY['Türk Edebiyatı','Şiir','Şair Faga']::text[], 8.5, '{"poet":"Şair Faga","poet_slug":"sair-faga","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/ben-onlari-boyle-hic-gormedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Candı, Canandı, Heyecandı...', 'candi-canandi-heyecandi-bekir-mutlu-gokcesu-fb7mm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgiydi suyu, ekmeği

Saygıydı özlediği

Değerliydi dostlukları

Kibardı, estetikti, mertti

Güçlüydü sezgisi, hisleri

İnanmadı mı 

Ulaşılmazdı dorukları

Asla sevmemişti zorlamayı

Ve asla hak etmiyordu 

Bedbahtlığı...

Sevdi mi 

Zaten açardı yedi verenleri

Mantıklı ve gerçekçiydi

Ama deli doluydu yüreği

Mutlaka bir fırtınası vardı

Ve mutlaka bir sessizliği

Öncesi ve sonrasında...

Ruhunun derinliklerinde

Çiçeklerle bezeli bahçesinde

Gözlerini kapatıp salındığı

Hayattan düşlerini süzdüğü

Bir salıncağı da vardı bence

Ellerini, gözlerini ve ruhunu

Hak eden sıcacık bir yürek

Hayal veya gerçek...

Mutlaka vardı dünyasında

Şirin bir ev ve çok sevdiği

Bir köşesi evinin içinde

Mutlaka vardı...

Azaltan değil, çoğaltandı

Candı, canandı, heyecandı 

Dünyayı yaşanır kılandı

Anamdı, karımdı, kızımdı

Hayattı, tabiattı, insandı

KADINDI...', 'Sevgiydi suyu, ekmeği Saygıydı özlediği Değerliydi dostlukları Kibardı, estetikti, mertti Güçlüydü sezgisi, hisleri İnanmadı mı  Ulaşılmazdı...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/candi-canandi-heyecandi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşksız Olamam', 'asksiz-olamam-demet-kaytan-wozg5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Teslim olmam kadere

Şans güldü yüzüme

Kim ne derse dese

Tek başıma olurum deli divane

Ben aşksız olamam yaşayamamki

Kaçsamda aşk peşimi bırakmazki

Yıllarca bekledim hep sevilmeyi

Resmini sakladım yıllarca

Yollarına uzandım boylu boyunca

Yağmurda yağsa fırtınada kopsa

Bırakmam aşkımı başka bahara', 'Teslim olmam kadere Şans güldü yüzüme Kim ne derse dese Tek başıma olurum deli divane Ben aşksız olamam yaşayamamki Kaçsamda aşk peşimi bıra...', ARRAY['Türk Edebiyatı','Şiir','Demet Kaytan']::text[], 8.5, '{"poet":"Demet Kaytan","poet_slug":"demet-kaytan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/asksiz-olamam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülmeyi Unuttum', 'gulmeyi-unuttum-demet-kaytan-1pizn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağlamaktan gülmeyi unuttum

Yalan yanlış sevdalara tutuldum

Uzaklarda ikiçift göze vuruldum

İstesemde canımdan kurtulamadım

İçim yandı yandı yandı kavruldu

Bu aşk bana cehennemi yaşattı

Gittin ya bir küsüp bir barıştım hayatla

Gittin ya kurşunlar yedi yüreğim arda arda

Gittin ya aynalarda kendimi tanıyamadım

İşte bu yüzden yıllardır gülmeyi unuttum', 'Ağlamaktan gülmeyi unuttum Yalan yanlış sevdalara tutuldum Uzaklarda ikiçift göze vuruldum İstesemde canımdan kurtulamadım İçim yandı yandı ...', ARRAY['Türk Edebiyatı','Şiir','Demet Kaytan']::text[], 8.5, '{"poet":"Demet Kaytan","poet_slug":"demet-kaytan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gulmeyi-unuttum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahşerde Bekleyeceğim', 'mahserde-bekleyecegim-demet-kaytan-t8n3p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerime inanmadım kapandım karanlığa

Sanki dün gibi anılarım döküldü sayfa sayfa

Öpüp kokladım resmini başucumda sevgili

Doyamadım bakmaya kıyamadım yırtıp atmaya

Paylaştığım geceler dörtduvar üstüme geldi

Sana deli yüreğim bir gün olsun küsmedi

Kim nederse dese içindeki aşk küllense

İnan ecelim gelse yine seni seveceğim

Ölüm çalsa kapımı

Alıp gitse canımı

Bu dünyada olmazsa 

Mahşerde bekleyeceğim', 'Gözlerime inanmadım kapandım karanlığa Sanki dün gibi anılarım döküldü sayfa sayfa Öpüp kokladım resmini başucumda sevgili Doyamadım bakmaya...', ARRAY['Türk Edebiyatı','Şiir','Demet Kaytan']::text[], 8.5, '{"poet":"Demet Kaytan","poet_slug":"demet-kaytan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mahserde-bekleyecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatımın Son Demleri', 'hayatimin-son-demleri-demet-kaytan-8vtev', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şu gözlerim uykuya hasret kaldı sevgili

Duramam düşünmeden birgün  bile seni

Çıldırırım görmesem başumda resmini

Ömrüm olsada ellerinde hazan mevsimi

Sev artık seveceksen vefasız sevgili

Yaşıyorum hayatımın son demlerini

Birkaç saat gelsen inan yeter bana

Sonra çekip gitsen hesap sormam sana

Seni tanıdığım gün bozmuştum yeminimi

Gelirsin diye oyaladım aşka susamış yüreğimi

Her kapıyı kapattım yalnız sana bağlandım

Gözlerine inandım aşktan sakınamadım', 'Şu gözlerim uykuya hasret kaldı sevgili Duramam düşünmeden birgün  bile seni Çıldırırım görmesem başumda resmini Ömrüm olsada ellerinde haza...', ARRAY['Türk Edebiyatı','Şiir','Demet Kaytan']::text[], 8.5, '{"poet":"Demet Kaytan","poet_slug":"demet-kaytan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayatimin-son-demleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yerli Falı', 'yerli-fali-ozlem-torkul-tekan-5mys9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kar gibisin dedi kadın 

Tam bir soluk benizlisin. 

Saçın, gözün ve dudağın 

Silinse eriyeceksin. 

Çok beyazsın dedi kadın 

Leke tutamaz yüreğin 

Aniden anılsa adın 

Aynaya yansımaz aksin. 

Hiç üzülme dedi kadın 

Her yana uzanır elin 

Avucunda çizgi yazgın 

Yumruğun kadar seversin. 

(14 Mart 2002)', 'Kar gibisin dedi kadın  Tam bir soluk benizlisin.  Saçın, gözün ve dudağın  Silinse eriyeceksin.  Çok beyazsın dedi kadın  Leke tutamaz yüre...', ARRAY['Türk Edebiyatı','Şiir','Özlem Torkul Tekan']::text[], 8.5, '{"poet":"Özlem Torkul Tekan","poet_slug":"ozlem-torkul-tekan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yerli-fali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Gidiyorum', 'ben-gidiyorum-ozlem-torkul-tekan-qoq7g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gömleğin ütülü, askıda

Çorapların çekmecede sağda

Takım elbisenin yerini biliyorsun.

Ben gidiyorum...

Banyo, tuvalet tertemiz

Derli toplu odalar da

Anahtar paspasın altında

Ben gidiyorum...

Yemeği yeni yaptım

Dolapta ikinci rafta

Dışarda yersin olmazsa

Ben gidiyorum...

Çocukları anneme bıraktım

Bizi hiç ayrı görmediler

Ev boş diye üzülmesinler.

Ben gidiyorum...

Bütün anıları topladım

Sana tozlarını bıraktım

Süpürme öyle kalsın

Ben gidiyorum...

2 Mart 2002 / 22:55', 'Gömleğin ütülü, askıda Çorapların çekmecede sağda Takım elbisenin yerini biliyorsun. Ben gidiyorum... Banyo, tuvalet tertemiz Derli toplu od...', ARRAY['Türk Edebiyatı','Şiir','Özlem Torkul Tekan']::text[], 8.5, '{"poet":"Özlem Torkul Tekan","poet_slug":"ozlem-torkul-tekan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ben-gidiyorum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maç Bitsin', 'mac-bitsin-ozlem-torkul-tekan-ajav7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hiç farkında değilsin ama

Kronik senin çaresizliğin.

Kapı eşiğini boş bulsan

Oturup kalacakmış gibisin.

Gözümden kaçtığını sanma 

Sahte senin mütevaziliğin

Güç ringinde yenilendir duran

Sağ gösterip,soldan vur,maç bitsin.

6 Mart 2002 / 14:00', 'Hiç farkında değilsin ama Kronik senin çaresizliğin. Kapı eşiğini boş bulsan Oturup kalacakmış gibisin. Gözümden kaçtığını sanma  Sahte seni...', ARRAY['Türk Edebiyatı','Şiir','Özlem Torkul Tekan']::text[], 8.5, '{"poet":"Özlem Torkul Tekan","poet_slug":"ozlem-torkul-tekan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/mac-bitsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efsane', 'efsane-ozlem-torkul-tekan-jeip5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşk sanılan kapıdaki misafir 

Sana rağmense senden ziyadedir. 

Boğazına takılan gam düğümü 

Nicesini boğan o viranedir. 

Sol yanına narla vurulan mühür 

Halka halka zincir ve kelepçedir. 

Yanılgının esarete dönümü 

Ruhun kayıtsız teslimiyetidir. 

Aşk sandığın kapıdaki misafir 

Onulmaz yaralı bir divanedir. 

Gönül, varlığın yaldızlı güğümü 

Taşırken dökülenler efsanedir. 

(11 Şubat 2002)', 'Aşk sanılan kapıdaki misafir  Sana rağmense senden ziyadedir.  Boğazına takılan gam düğümü  Nicesini boğan o viranedir.  Sol yanına narla vu...', ARRAY['Türk Edebiyatı','Şiir','Özlem Torkul Tekan']::text[], 8.5, '{"poet":"Özlem Torkul Tekan","poet_slug":"ozlem-torkul-tekan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/efsane-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçıyor gözlerin', 'kaciyor-gozlerin-sedat-tuvar-dju9f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bazen dalıp gidiyor gözlerin

Bir hüzün kaplıyor yüreğini

O dakikalar ah o dakikalar

Geçmek bilmiyor

Ömrümü alıyor bana dönmen

Hüznünü kıskanıyorum', 'Bazen dalıp gidiyor gözlerin Bir hüzün kaplıyor yüreğini O dakikalar ah o dakikalar Geçmek bilmiyor Ömrümü alıyor bana dönmen Hüznünü kıskan...', ARRAY['Türk Edebiyatı','Şiir','Sedat Tüvar']::text[], 8.5, '{"poet":"Sedat Tüvar","poet_slug":"sedat-tuvar","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kaciyor-gozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eyvah', 'eyvah-cemil-coskun-dzvl8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Acelece geldik dünyaya

Aşkı tadalım diye…

Ürkerek çaldık kapıyı

Yüzümüze bakılmadan kovulduk kapıdan.

Nice sonra çalında aynı kapı

Çıkmadı bize göre bir aşk.

Eyvah! Eyvah ki ne eyvah! ...

Ömrümüz aşksız ve emanet cümlelerle geçiyor.', 'Acelece geldik dünyaya Aşkı tadalım diye… Ürkerek çaldık kapıyı Yüzümüze bakılmadan kovulduk kapıdan. Nice sonra çalında aynı kapı Çıkmadı b...', ARRAY['Türk Edebiyatı','Şiir','Cemil Coşkun']::text[], 8.5, '{"poet":"Cemil Coşkun","poet_slug":"cemil-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/eyvah-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarım Kalan', 'yarim-kalan-cemil-coskun-bmtbg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Üzülme Hasankeyf, üzülme Belkız,

Dayan Fırtına Vadisi.

Diren Bergama, sıkı dur: Bolu, Düzce, Gölcük, Yalova…

Bekle gri kentimin Kırkikindi Yağmuru.

Kütük yorgunluğunu,

Yayla uykusundan kalkarak atacağız.

Tamamlanacak resimler, 

Öpülecek yarin diğer yanağı,

Bekle: “Çok şükür bu güne de diyeceğiz.”', 'Üzülme Hasankeyf, üzülme Belkız, Dayan Fırtına Vadisi. Diren Bergama, sıkı dur: Bolu, Düzce, Gölcük, Yalova… Bekle gri kentimin Kırkikindi Y...', ARRAY['Türk Edebiyatı','Şiir','Cemil Coşkun']::text[], 8.5, '{"poet":"Cemil Coşkun","poet_slug":"cemil-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yarim-kalan-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum Günü', 'dogum-gunu-cemil-coskun-h088d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her gün çoğalıyoruz, biraz da azalarak,

Tez antitez.

Çeyrek asır önce 27 Haziran’da güzeller bir arttı.

Dileğim şudur: Doldur ömrünün dört çeyreğini de…

Güzel nineler görsün dünya.

Ahmet, Mehmet, Ayşe,Fatma iyi de

Dünyada Nimet olmak ne güzel.

Hoş geldin Bertiz Salkımı hoş geldin.

Başımız gözümüz üstüne…', 'Her gün çoğalıyoruz, biraz da azalarak, Tez antitez. Çeyrek asır önce 27 Haziran’da güzeller bir arttı. Dileğim şudur: Doldur ömrünün dört ç...', ARRAY['Türk Edebiyatı','Şiir','Cemil Coşkun']::text[], 8.5, '{"poet":"Cemil Coşkun","poet_slug":"cemil-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dogum-gunu-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarhoş Atlar', 'sarhos-atlar-cemil-coskun-ng3n5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnanmıyorum hayat bilgisi kitaplarına,

Yazmadı hiçbiri; 

Bir kız çocuğunun,

On ikisinde gebelik yaptığını hayata.

İnanmıyorum hayat bilgisi kitaplarına

Yazmadı hiçbiri; 

Bir erkek çocuğunun

Yedisinde çırak olup hayata,

Yağlı, kömür suratların arasından

Haykıran dişleri,

Ve yemek molası düşleri yazmadı.

İnanmıyorum hayat bilgisi kitaplarına

Yazmadı hiçbiri; 

Çocuğun içindeki dünyayı,

Dünyanın içindeki çocukları yazmadı.', 'İnanmıyorum hayat bilgisi kitaplarına, Yazmadı hiçbiri;  Bir kız çocuğunun, On ikisinde gebelik yaptığını hayata. İnanmıyorum hayat bilgisi ...', ARRAY['Türk Edebiyatı','Şiir','Cemil Coşkun']::text[], 8.5, '{"poet":"Cemil Coşkun","poet_slug":"cemil-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sarhos-atlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost', 'dost-cemil-coskun-ulfpl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gecenin üçünde aradığım,

Başımı göğsüne dayadığım,

Ardımdaki kıvırcık gözüm,

Diken ağacından bastonum,

Serendim,

Birlikteyken çoğaldığım dostum.

Sana ananca sesleniyorum:

“Boyuna kurban olurum.”', 'Gecenin üçünde aradığım, Başımı göğsüne dayadığım, Ardımdaki kıvırcık gözüm, Diken ağacından bastonum, Serendim, Birlikteyken çoğaldığım dos...', ARRAY['Türk Edebiyatı','Şiir','Cemil Coşkun']::text[], 8.5, '{"poet":"Cemil Coşkun","poet_slug":"cemil-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dost-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör Göz', 'kor-goz-cemil-coskun-zr8z3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir kez dünyaya,

Afganlı çocuğun 

Mülteci gözüyle baktım.

Kör oldum.

Karanlığımı sadece,

“O” çocuğun merhameti yırtar.

Ağla sevgili kalbim.

Kırılma noktandan vuruldun.

Şimdi hayat; 

Kan, 

Gözyaşı ve de,

Keder kokuyor.', 'Bir kez dünyaya, Afganlı çocuğun  Mülteci gözüyle baktım. Kör oldum. Karanlığımı sadece, “O” çocuğun merhameti yırtar. Ağla sevgili kalbim. ...', ARRAY['Türk Edebiyatı','Şiir','Cemil Coşkun']::text[], 8.5, '{"poet":"Cemil Coşkun","poet_slug":"cemil-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kor-goz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şehrin Hikayesi', 'bir-sehrin-hikayesi-cemil-coskun-7xkz2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yatalaktır mevsimler bu kentte

İki ayağın büyük gelir.

Kolların dışarıda kalır hep.

Ah! Yağmurun küsü, yoksulluğun kızı kentim.

Taşırsın yoksulluğu yıllarca bana mısın demeden

Bir sevdayı kaldıramadın.

Terk edilmiş evlerin saksılarının özlemi var içimizde.

Sevgilinin belinde elimiz

Bakamadık pencereden yağmura…

Ey! sevgili şehrim bağışla

Yönergesiz geldik hayata.

Yoksulluk ve yoksunluk pıtırak otun

Sevdaya nadaslı yürekler

Elbet bu kentte de bir gün gülecekler…', 'Yatalaktır mevsimler bu kentte İki ayağın büyük gelir. Kolların dışarıda kalır hep. Ah! Yağmurun küsü, yoksulluğun kızı kentim. Taşırsın yok...', ARRAY['Türk Edebiyatı','Şiir','Cemil Coşkun']::text[], 8.5, '{"poet":"Cemil Coşkun","poet_slug":"cemil-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-sehrin-hikayesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmek Kalmak', 'gitmek-kalmak-cemil-coskun-spz4s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sıramız gelecek sessizce kayacak yıldızımız.

Geriye bir çift söz,

Ve de bir sevda kalırsa ne ala…', 'Sıramız gelecek sessizce kayacak yıldızımız. Geriye bir çift söz, Ve de bir sevda kalırsa ne ala…...', ARRAY['Türk Edebiyatı','Şiir','Cemil Coşkun']::text[], 8.5, '{"poet":"Cemil Coşkun","poet_slug":"cemil-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/gitmek-kalmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak Her Zaman Ağır Basıyor', 'yasamak-her-zaman-agir-basiyor-cemil-coskun-4l1g7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir uçurumun kenarındayım,

Gitmekle kalmak arası.

Tam gideyim derken,

Gülüşün geliyor aklıma.', 'Bir uçurumun kenarındayım, Gitmekle kalmak arası. Tam gideyim derken, Gülüşün geliyor aklıma....', ARRAY['Türk Edebiyatı','Şiir','Cemil Coşkun']::text[], 8.5, '{"poet":"Cemil Coşkun","poet_slug":"cemil-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yasamak-her-zaman-agir-basiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pencere', 'pencere-cemil-coskun-vjnpm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kırkından sonra 

İş ve eş bulan adam.

Evinden işine işinden evine

Mekik dokuyordu her akşam.', 'Kırkından sonra  İş ve eş bulan adam. Evinden işine işinden evine Mekik dokuyordu her akşam....', ARRAY['Türk Edebiyatı','Şiir','Cemil Coşkun']::text[], 8.5, '{"poet":"Cemil Coşkun","poet_slug":"cemil-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/pencere-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurban Bayramı Hoş Geldin', 'kurban-bayrami-hos-geldin-bekir-gedikoglu-o14no', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '02.07.2003 tarihinde bir tesadüf neticesinde bu sitedeki arkadaşlar ile tanıştım. Bu siteyi ve arkadaşları samimi bulduğum için onlara kalbimin ve usumuntüm kapılarını açmakta bir sakınca bulmadım. Bulacağımıda snmıyorum. Cevval şiirlerin yarattığı denizlerde yüzmeğeve göze suyu gibi akan şiirlerden kana, kana içmeğe başladım. Atatür gibi zekalı arkadaşlarım var. İçeriği görkemli ve erdemli şiirlere yorumlar yazdım, yazacağım. Bilmeden ve farkında olmadan üzdüklerim var ise af ola. Çünkü; siz benim kalbimsiniz, gözümsünüz, kulağımsınız. ''İNSAN KENDİNE ZARAR VERİR Mİ? ''  Ben 32 yıldır her sabah gazetemi okur ve diğer işlerime bakardım. Bu ilkem şu anda yıkılmış durumda. Şimdi önce sizinle sohbet ediyoeum ve ondan sonra fırsat bulursam gazeteye bakıyorum. Kısaca sizsiz bu dünya dönmüyor. Siz benim kalbimin, dilimin, bakışımın, görüşümün ve aklımın şekillenmesine çok ama çok yardımcı oluyorsunuz...ve bu zaman diliminde sizinle birlikte 1 Aralık 2004'' ün Kurban Bayramına eriştim...........................

..........Kurban Bayramınızı en içten dileklerimle kutlar, esenlikler diler ve bütün dünyada hayırlara vesile olmasını dilerim............................................................................................................      



Ankara; 30 Aralık 2004', '02.07.2003 tarihinde bir tesadüf neticesinde bu sitedeki arkadaşlar ile tanıştım. Bu siteyi ve arkadaşları samimi bulduğum için onlara kalbi...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/kurban-bayrami-hos-geldin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Adres', 'kayip-adres-cemil-coskun-hd4as', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kuş ilk uçuşunu yapar yüreğimde

Seni her gördüğümde.

Tohumlar filizlenir,

Denizler kabarır.

Gözlerinde adresimi kaybedip,

Rüzgarın savurup 

Yamaçta bir kaya dibine bıraktığı tohumun

Fidanı olmak isterim gönlünde.', 'Kuş ilk uçuşunu yapar yüreğimde Seni her gördüğümde. Tohumlar filizlenir, Denizler kabarır. Gözlerinde adresimi kaybedip, Rüzgarın savurup  ...', ARRAY['Türk Edebiyatı','Şiir','Cemil Coşkun']::text[], 8.5, '{"poet":"Cemil Coşkun","poet_slug":"cemil-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kayip-adres-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Batımı Hep Hüzünlüdür', 'gun-batimi-hep-huzunludur-cemil-coskun-i9xls', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her gün batımı

Hüznümün doğuşuna denk düşer.

Bu vakit; 

Kendime kalır,

Boynuma sarılırım.

Siperimde yoldaşsız,

Gözlerim ardında 

Sevmelerin en hası yarıda kalır.

Çıkmaz yıldızım bu gecede Yine de her gece inatla

Gökyüzüne merhaba demek için

Umuda gebe yatarım.', 'Her gün batımı Hüznümün doğuşuna denk düşer. Bu vakit;  Kendime kalır, Boynuma sarılırım. Siperimde yoldaşsız, Gözlerim ardında  Sevmelerin ...', ARRAY['Türk Edebiyatı','Şiir','Cemil Coşkun']::text[], 8.5, '{"poet":"Cemil Coşkun","poet_slug":"cemil-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gun-batimi-hep-huzunludur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurban Bayramına Girerken', 'kurban-bayramina-girerken-sukran-gunay-0rc2k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'KURBAN BAYRAMINA GİRERKEN

Yine bir bayram arifesi kapıda. Kardan soğuk, ateşten beter. 

Arife buz kesmiş, ben sessiz çığlıklarımla baş başayım.

Şaşkın gönlüm, deli tavuk gibi dellendi; açtı kanatlarını. Oturdum özümle şahlanmış gövdesine gönlümün. Öptüm yelesinden, doladım kollarımı boynuna; haydi dedim, yolumuz Anadolu´ya! 

Uçtuk; yağmur, kar, tipi, fırtına diyarlarından. Yükseldikçe yükseldik ağıta hazır bulutların üstüne. Dağları, ovaları, bilinmez diyarları aştık ve vardık mis kokularına Anavatan´ın. Sabaha oradaydık. Ezan sesleri süslerken, masmavi  gelinlikli göklerini memleketimin; durduk seyre daldık…

Camiler tıklım tıklım. Avlulara taşmış seccadeler. Bir köşede yer buldu gönlüm, arka saflarda  kıldı namazını birlikte. Tüm canlar aşk ile  tek yürek gibiydi  görünüşte… 

Beklemekteydi o anda  kurbanlar evlerde, bahçelerde. Çıt yoktu hiçbirinden. O ne sabır ve hikmettir ki gecede kalmıştı yakarışlar. Kınalı kuzuların meee! meee! leri  kesilmişti birden. Kömür gözlü ciğerlerimin suskunluğu  nedendi acaba? ! .  Karagözlü, alaca ve ak koyunlarımı sevdim birer birer can özümle. Yoktu hiç birinde tek bir direniş, sesleniş…

Yurdun tek köşesi kalmadı dolanmadığı kartal gönlümün. Hangi tarafa baksam; tir tir titriyordu bedenleri ak koyunlarımın, kıvrak keçilerimin. Birkaçı kurbanlık danalarımızın nasıl da kaçıyorlardı can havliyle? 

Geldi o beklenen an. Yaradan adıyla vuruldu boyunları. Kanları suya, toprağa  karıştı. Etleri parçalanıp doğrandı. Poşetlerde dağıtıldı sokak sokak. Çoğu da buzdolaplarının soğutucularına yerleştirildi gelecek günlere. Ah! bacım, ağam! Al gülüm ver gülümdü oynanan. Bayramlıklar giyildi. Eller öpüldü. Çocuklar sevindirildi güya... Köprü altları inliyordu oysa…Odalar çatlıyordu kahrından; yaşlıyı, fakiri, kimsesizi taşımaktan. Kavurma kokuları yakıyordu ciğerleri. Boşuna beklediler, umutlandılar… Yakarışlarla açılan elleri; gökleri deldi geçti iniltilerle… Görmediler, duymadılar; tok olanlar, bayramı kutlayanlar… 

Bayram sevinci sarmıştı gönülleri. Öylesine keyifli, öylesine ilgisizdiler yanı başlarında olanlara. Bîhaberdiler ağıt yakan göklerden. Sofralar kuruldu, kavurmalar sunuldu varsıldan varsıla... Diller süslü püslü döküldü. Bayramlar övüldü. Zikredildi cömertçe(!) Yaradan. Bir döngüdür ki; döndü yine, aynı devridaim. Yüreğim iki büklüm, can özüm yıkık dökük, başım yana düşük; taştı can evim ıslak ve gürül gürül çağlayarak yasımdan. Bayramsa çoktan hüzne döndü. Bilemediler, göremediler dostlarım...

Ne dersiniz bilmem bu garibe? ! . Olsun diyeceğim yine de; gören gözlerimden öte, duyan kulaklarımdan öte, hisseden ellerimden öte, koklayan burnumdan öte; gördüklerim, duyduklarım, hissettiklerim, kokladıklarım var. Yoksulların, yaşlıların, sokak çocuklarının, hastaların, kimsesiz ve yalnızların  yakarışlarıdır bu kez  zerrelerimde özümü yakıp kavuran. Ah! lar yükselmekte göklere; beni, seni tarumar edecek olan…

Onlar ki; kul sandılar kendilerini. Gözleri âmâ, kulakları sağır; yediler içtiler gönüllerince. Bayramı küstürdüler; bilemediler. Yine aldandı onca canlar… Düşünemediler… Çözemediler…

Bayram kederlendi, dellendi; yoldu saçını, dağladı bağrını, BEN´im gibi…

Şükran GÜNAY’dan

Şükranca', 'KURBAN BAYRAMINA GİRERKEN Yine bir bayram arifesi kapıda. Kardan soğuk, ateşten beter.  Arife buz kesmiş, ben sessiz çığlıklarımla baş başay...', ARRAY['Türk Edebiyatı','Şiir','Şükran Günay']::text[], 8.5, '{"poet":"Şükran Günay","poet_slug":"sukran-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kurban-bayrami-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Güzel', 'seninle-guzel-cemil-coskun-2ad5p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dünyanın yaşadığım yere bakan yüzüne

Vurmasın güneş.

Biz böyle iyiyiz.

Havasını soluduğum kentin

Yanmasın sokak lambaları.

Yeter bize; 

Evde mum, dışarıda ay ışığı.

Doğacaksa; 

Günaydın değil,

Gün seninle aydın 

Diyebilmek için doğmalı güneş.

Dünyanın yaşadığım yeri,

Havasını soluduğum kentine…', 'Dünyanın yaşadığım yere bakan yüzüne Vurmasın güneş. Biz böyle iyiyiz. Havasını soluduğum kentin Yanmasın sokak lambaları. Yeter bize;  Evde...', ARRAY['Türk Edebiyatı','Şiir','Cemil Coşkun']::text[], 8.5, '{"poet":"Cemil Coşkun","poet_slug":"cemil-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seninle-guzel-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-cemil-coskun-ofvvp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yağmur yağıyor.

Her damla içime doluyor

Bense düşmek istiyorum

Bir yağmur damlasının içine

Bir ırmak olup

Gürül gürül akmak.', 'Yağmur yağıyor. Her damla içime doluyor Bense düşmek istiyorum Bir yağmur damlasının içine Bir ırmak olup Gürül gürül akmak....', ARRAY['Türk Edebiyatı','Şiir','Cemil Coşkun']::text[], 8.5, '{"poet":"Cemil Coşkun","poet_slug":"cemil-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yagmur-106-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendi Yangınında Susuz Hayat', 'kendi-yangininda-susuz-hayat-cemil-coskun-zkudw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ömrümün bilançosu:

Gören bir çift göz,

Çocuğun avucuna sıkıştırılmış bir gülüş,

Her yangına bir damla su

Kendi yangınına susuz bir hayat.', 'Ömrümün bilançosu: Gören bir çift göz, Çocuğun avucuna sıkıştırılmış bir gülüş, Her yangına bir damla su Kendi yangınına susuz bir hayat....', ARRAY['Türk Edebiyatı','Şiir','Cemil Coşkun']::text[], 8.5, '{"poet":"Cemil Coşkun","poet_slug":"cemil-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kendi-yangininda-susuz-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüme Dair', 'olume-dair-cemil-coskun-qe8yz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çıplak kaldı dünya

Gözlerinle gitti mavi renk

Uykusuz adamların, susuz toprakların 

Sağ olsun başı.

Can suyu olacak her sabah sana

Dostlarının gözyaşı.

Yaşadın, bize az geldi ömrün

Öldün, kuşlar kalkmadı yuvalarından

Issız kaldı dost mekanları

Balıkçı tekneleri kıyıda öyle duruyor

Avcı köpekler, Çoban Mehmet öyle

Trafik lambaları kırmızı, deniz fenerleri siyah

Her şey öyle…

Anneler rüyasında evlatlarına hasretini emziriyor.', 'Çıplak kaldı dünya Gözlerinle gitti mavi renk Uykusuz adamların, susuz toprakların  Sağ olsun başı. Can suyu olacak her sabah sana Dostların...', ARRAY['Türk Edebiyatı','Şiir','Cemil Coşkun']::text[], 8.5, '{"poet":"Cemil Coşkun","poet_slug":"cemil-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/olume-dair-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hikaye', 'hikaye-cemil-coskun-phnij', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dünyayı koydum yüreğime 

Sığdıramadım sevdanı dünyaya…

Yatışmaz artık içimde başlattığım hikaye

Artık ben her yerden aşka çıkarım.', 'Dünyayı koydum yüreğime  Sığdıramadım sevdanı dünyaya… Yatışmaz artık içimde başlattığım hikaye Artık ben her yerden aşka çıkarım....', ARRAY['Türk Edebiyatı','Şiir','Cemil Coşkun']::text[], 8.5, '{"poet":"Cemil Coşkun","poet_slug":"cemil-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hikaye-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğul', 'ogul-cemil-coskun-5wsqa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir güldün bütün sıkıntılarımı evde,

O günden sonra kalbimi sende unuttum.', 'Bir güldün bütün sıkıntılarımı evde, O günden sonra kalbimi sende unuttum....', ARRAY['Türk Edebiyatı','Şiir','Cemil Coşkun']::text[], 8.5, '{"poet":"Cemil Coşkun","poet_slug":"cemil-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/ogul-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba', 'baba-cemil-coskun-s5648', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hey gidinin Hüseyin oğlu İsmail’i

Babam

Laf altında kalmamayı senden öğrenmiştim

Kalmıyorum: canım babacığım.

Duydum hastanede yattığını

Doktor olmak istedim

Keşke kanatlarım olsaydı

Ruhumu gönderiyorum sana…

Keşke diyor insan kırkından sonra

Bütün babalar çocuklarından bir sınıf yapsa

Şımarsam sınıfın en küçüğü olarak

Ablam yine yapsa ablalığını

Verse bana sırasını

Keşke…

Kırkından sonra hayatın mucizesi

Babalar oğul, oğullar baba

Kare kökü alır gibi alsam

Bütün acılarını

İşe yarasa okumuşluğum.

Ben de “Hayatta en çok babamı sevdim.” Can Baba.

Ne güzelmiş; babaya harçlık verip

Bayramlık almak

Gönderip çocukları, baş başa kalmak.

Okumayı değil ama okutmayı  bilen can babam

Öğretmen olmam senin en küçük eserin

İlk öğrencimin senin olmanı 

Ne çok isterdim.', 'Hey gidinin Hüseyin oğlu İsmail’i Babam Laf altında kalmamayı senden öğrenmiştim Kalmıyorum: canım babacığım. Duydum hastanede yattığını Dok...', ARRAY['Türk Edebiyatı','Şiir','Cemil Coşkun']::text[], 8.5, '{"poet":"Cemil Coşkun","poet_slug":"cemil-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/baba-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*.Bir Su ile Toprak Öyküsü', 'bir-su-ile-toprak-oykusu-vahdet-nafiz-aksu-z3r6a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kupkuru, çatlak; ıslaklık arzusuyla kavruk

Bir toprağa bırakıldığından bu yana

Mütereddit, titrek sürünmelerle akıyor su 

Su ile toprağın   ilk karıştığı gündeki  gibi 

Taze ve nefis  bir   balçık   kokusu  …..

Toprağın şehvetli çatlakları  andırıyor

Asırlar boyu öpüşmeyi bekleyen dudakları 

Hafif meyilli  ark  aratmıyor  sımsıcak kucakları 

Ne  toprak..ne su..ne kuraklık mahkumu  tohum 

Kestirebiliyor  olacakları 

Karıncalar telaşla kaçışıyor su yatağını ararken

Titriyor ağ başında böcek bekleyen 

Örümceklerin bacakları

Gözeden çıktığından beri yolunu arayan suyun

Merak ediyorsanız sesini, bülbüllerden duyun

Ana kucağında ninni konçertoları 

Dinleyen çocuklar gibi bu sesle uyuyun 

Emilmeye doymayan suyun

Emmeye doymayan toprağın

Ve bu şiddetli vuslattan

Gıdalanan kökün, yaprağın 

Sessiz şükrüne inat: 

Vuslatın seslisine aşıktır kâinat 

Bu yüzden gök gürlemelerinin suyla ünsiyeti

Suyun toprakla ünsiyeti kadardır

Suyun toprakla her vuslatında

Bu yüzden yağmurun payı vardır

Su ile toprağın ilk  karışımından  bu yana 

Nerde bir avuç toprak

Nerde bir damla su  görsem

Ruhuma ÜFLENEN bir ney dinlerim

Her rüzgarla birlikte  o yüzden  inlerim', 'Kupkuru, çatlak; ıslaklık arzusuyla kavruk Bir toprağa bırakıldığından bu yana Mütereddit, titrek sürünmelerle akıyor su  Su ile toprağın   ...', ARRAY['Türk Edebiyatı','Şiir','Vahdet Nafiz Aksu']::text[], 8.5, '{"poet":"Vahdet Nafiz Aksu","poet_slug":"vahdet-nafiz-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bir-su-ile-toprak-oykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son iki yıldız', 'son-iki-yildiz-sedat-tuvar-oyfay', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İki yıldız kalmış gökyüzünde

Diğerlerinin hepsi  sönmüş bu gece

Sanki benim gibi sonsuza dek susmuşlar

Her gece gökyüzüne bakıp

Hep aynı şeyi diledim

Dileğim isabet ettikçe sönmüş olsalar gerek

Son kalan iki yıldıza kıyamıyorum

Ya dilersem ya onlar da sönerse

Yok yok bunu yapamam

Son iki yıldızı bu akşam

Başka ihtiyacı olanlara bırakacağım', 'İki yıldız kalmış gökyüzünde Diğerlerinin hepsi  sönmüş bu gece Sanki benim gibi sonsuza dek susmuşlar Her gece gökyüzüne bakıp Hep aynı şey...', ARRAY['Türk Edebiyatı','Şiir','Sedat Tüvar']::text[], 8.5, '{"poet":"Sedat Tüvar","poet_slug":"sedat-tuvar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/son-iki-yildiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskiyen', 'eskiyen-cemil-coskun-4dnyj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İnsan mekan tuttu bedeni

Can eskidi, ten eskidi

Zaman sonsuzluğa yattı

Gece eskidi, gün eskidi

Dön bak ayrıldığın kente

Yer eskidi, yol eskidi

Aşık dil verdi sazına 

Saz eskidi, söz eskidi

Sevda mekan eyledi yüreği

Ne sevda ne de yürek eskidi.', 'İnsan mekan tuttu bedeni Can eskidi, ten eskidi Zaman sonsuzluğa yattı Gece eskidi, gün eskidi Dön bak ayrıldığın kente Yer eskidi, yol eski...', ARRAY['Türk Edebiyatı','Şiir','Cemil Coşkun']::text[], 8.5, '{"poet":"Cemil Coşkun","poet_slug":"cemil-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/eskiyen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıkma', 'sikma-cemil-coskun-qvd98', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ömrünün çeyreği kendini sıkmakla geçti

Biraz rahatlayayım dedi.

İş işten geçmişti.', 'Ömrünün çeyreği kendini sıkmakla geçti Biraz rahatlayayım dedi. İş işten geçmişti....', ARRAY['Türk Edebiyatı','Şiir','Cemil Coşkun']::text[], 8.5, '{"poet":"Cemil Coşkun","poet_slug":"cemil-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/sikma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokak', 'sokak-cemil-coskun-i2f25', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayat bize bir odalı bire ev bile vermedi

Gökyüzünü çekip üstümüze,

Soba yapmışken nefesimizi

Gece hüznünü emziriyordu

Zaman bir sevdalılara

Bir de bize mesai veriyordu

Herkes evindeyken sabah

Biz elimizde çubuğumuz

Gideceğiz şehir çöplüğüne

Hayatı karıştırmaya…', 'Hayat bize bir odalı bire ev bile vermedi Gökyüzünü çekip üstümüze, Soba yapmışken nefesimizi Gece hüznünü emziriyordu Zaman bir sevdalılara...', ARRAY['Türk Edebiyatı','Şiir','Cemil Coşkun']::text[], 8.5, '{"poet":"Cemil Coşkun","poet_slug":"cemil-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sokak-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip Yüreğim', 'garip-yuregim-i-brahim-ethem-bingul-yfgd3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hey garip yüreğim

Gel şöyle geç karşıma

Bir sen,bir ben kaldık başbaşa

Bir sen söyle,bir ben

Şikayetimiz yardan

Yaş değil kan ağladık seninle

Ondan başka bir güzeli görmedi gözlerimiz

Ne büşralarla geldi yar

Ne de sevdasını aldı yar başımızdan

He gidi garip yüreğim

Ne darbeler geçirdik sevdalarımıza

Devrilmedik', 'Hey garip yüreğim Gel şöyle geç karşıma Bir sen,bir ben kaldık başbaşa Bir sen söyle,bir ben Şikayetimiz yardan Yaş değil kan ağladık seninl...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/garip-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zühre Yüzlüm...', 'zuhre-yuzlum-i-brahim-ethem-bingul-jlpry', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Oy ceylan gözlüm,

Oy zühre yüzlüm

Nerelerdeydin

Hangi seneydi ayrılığın kara günü

Halimden kimseye şikayet etmedim

Sevgimin bedelini ödedim yıllarca

Ayrılık en acı bedel ya sevdaya

Sanırdım Zühre yüzlüm,bilmezlerde halimi

Bilmekle,anlamak arasıydı bence sevgimi

Meğer ceylan gözlüm ağlarmış yıllardan beri

Nemrut ateşine atılmış

İbrahim''in sabrı sükununda olmakmış

Onu öğrenmekmiş işin özü

Özle,özlenmekmiş...', 'Oy ceylan gözlüm, Oy zühre yüzlüm Nerelerdeydin Hangi seneydi ayrılığın kara günü Halimden kimseye şikayet etmedim Sevgimin bedelini ödedim ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/zuhre-yuzlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Sonra', 'senden-sonra-meltem-seyhan-zmz6o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni tanıdıktan sonra

Nefret ettim ben karlı günlerden

O günlerde sana ulaşmak zordu

Seni tanıdıktan sonra 

Anlamı değişti tatil günlerinin

Tek amacı seninle olmamdı

Seni tanıdıktan sonra

Korkularım oldu yepyeni bilmedik

Kaybetme korkusu gibi

Seni tanıdıktan sonra

Mutluluğun anlamı değişti

O sadece seninle seyredilen bir filmdi', 'Seni tanıdıktan sonra Nefret ettim ben karlı günlerden O günlerde sana ulaşmak zordu Seni tanıdıktan sonra  Anlamı değişti tatil günlerinin ...', ARRAY['Türk Edebiyatı','Şiir','Meltem Seyhan']::text[], 8.5, '{"poet":"Meltem Seyhan","poet_slug":"meltem-seyhan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/senden-sonra-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurlara Emanet Etmiştin', 'yagmurlara-emanet-etmistin-i-brahim-ethem-bingul-hzptz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevgili! 

Değil yüreğim çatırdamakta,

Artık kanayıp parçalanmakta..

Şu imtihan yolunda bunları da yaşamak varmış

Hepsi gözümün önünden bir bir geçiyor ne varsa yaşanmış

Elimde Adalar''da verdiğin kurumuş bir papatya

Belki de senden kalan tek maddi hatıra

Yürek artık yanmakta,kavrulmakta

Geliyorum sevgili dayanamıyorum yanına..

Beynim artık dumur olmakta

Ne dünya ne de insan umrumda

Son demleriymiş yaşamımın acı hayat yolunda

Demek bunlar yazılıymış alın yazımda..

Yaradan seni benden çok sevdi

Güzelimi,cennetinde Huri elbiseleriyle süsledi

Vakit tamam,çilem doldurdu süresini

Toprağa girme sırası sonunda bana geldi..

Beni yağmurlara emanet etmiştin

Artık bahar geldi,yağmurlar bitti sevgilim

Sürem doldu vakit tamam

Rab''bim bize merhamet etti

Ecelimle yanına geliyorum meleğim...', 'Sevgili!  Değil yüreğim çatırdamakta, Artık kanayıp parçalanmakta.. Şu imtihan yolunda bunları da yaşamak varmış Hepsi gözümün önünden bir b...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yagmurlara-emanet-etmistin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tadı Yok..', 'tadi-yok-adem-tetik-hho2s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu bayramda hüzünlü  önce ki gibi

Nerdesin dostum  anlamsız bayramlar şimdi

Tadı yok ne bayramların eskisi gibi

Çok sıkıcı geçiyor sen yokken bayramlar  şimdi

Herkes gülüyor kendi halinde

Benim gözlerimde yaşlar senin yerine

Tadı yok bu bayramın sen gittin diye

Ağlıyorum bak dostum bayram gününde', 'Bu bayramda hüzünlü  önce ki gibi Nerdesin dostum  anlamsız bayramlar şimdi Tadı yok ne bayramların eskisi gibi Çok sıkıcı geçiyor sen yokke...', ARRAY['Türk Edebiyatı','Şiir','Adem Tetik']::text[], 8.5, '{"poet":"Adem Tetik","poet_slug":"adem-tetik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tadi-yok-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şişlinin sarıgülü var.', 'sislinin-sarigulu-var-memet-zeki-ates-hm9km', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İçinizden,sizden biri,

Koruyup,kollar fakiri.

Hizmetin üstadı piri,

Şişlinin Sarıgülü var 

Bitmiyorki,hizmet ağı,

Onunla yakaladık,çağı.

Halkımızın dert ortağı,

Şişlinin Sarıgülü var.

Bayram,seyran,dernek,düğün,

Yanınızda olur o gün.

Gurur duy,Şişli''li övün,

Sizin Sarıgülünüz var

Çalışıp üretir,sürekli,

Yiğit cesur ve yürekli.

Size sarıgül gerekli

Şişlinin Sarıgülü var', 'İçinizden,sizden biri, Koruyup,kollar fakiri. Hizmetin üstadı piri, Şişlinin Sarıgülü var  Bitmiyorki,hizmet ağı, Onunla yakaladık,çağı. Hal...', ARRAY['Türk Edebiyatı','Şiir','Memet Zeki Ateş']::text[], 8.5, '{"poet":"Memet Zeki Ateş","poet_slug":"memet-zeki-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sislinin-sarigulu-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İtizarm Sultanıma', 'i-tizarm-sultanima-abdullah-garip-xvb5w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İtizarım      Sultanıma                                                                                        

Daim sen istersin muhabbeti	                                  

Bilirsin münakaşa keser halveti

Sıcak sinesidir kadının serveti	                                                              

Seni severim içten, derinden, gönülden

Ben sultanıma toz kondurmam	                                              

Hayal ile gönül doldurmam

Başka başka bakışlara aldanmam

Seni severim içten, derinden, gönülden

Hülyalarımda ak güvercin

Rüyalarımda şerbeti sen verdin

Hep seni tanıdım, hep seni bildim

Seni severim içten, derinden, gönülden

Ok gibi işler kötü sözler

Gönül senin muhabbetini özler

Sıcak sine her şeyi düzle

Seni severim içten, derinden, gönülden

İsterim gül sine açılsın

Bendeki gerginlikler saçılsın

Bize muhabbet yolu açılsın

Seni severim içten, derinden', 'İtizarım      Sultanıma                                                                                         Daim sen istersin muhabbeti	...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/itizarm-sultanima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ardımda Sade Bir Gölge', 'ardimda-sade-bir-golge-gulay-yildiz-bd6rh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir baykuşun gece iniltisi kadarsın

Gündüzün sessiz ve uykuda

''Zaman; gitmek zamanı'' der gibi kanatların

Ruhun cigan müziği tonunda bir dansta

Bir dar geçit belki sana yaşam

Pusuları gecelerin mutlu olduğun

Ben güneş enerjisine bağımlı bir çiçeğim

Geceleri bu yüzdendir solduğum

Sessizce çekiliyorum kelimelerinden

Gecene saygı duyup gündüzüne saklanıyorum

Adını kazıdığın gece yarısı şiirlerinden azad olup

Gündüzleri sakladığın yastık altı kitaplara sığınıyorum

Hayatında tutacaksın, haklısın, anılarında

Anılarınla yaşamaya mahkum hücrelerinde kalacağım

Sözlerin tınısını unutup, yazdıklarıma hapsolup

Gözlerimdeki ışıktan çok bıraktığım gölgemde yaşayacaksın

Sönen Rüzgarıma;', 'Bir baykuşun gece iniltisi kadarsın Gündüzün sessiz ve uykuda ''Zaman; gitmek zamanı'' der gibi kanatların Ruhun cigan müziği tonunda bir dans...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ardimda-sade-bir-golge-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-abdullah-garip-t8jh0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerin

Baharı eksik olmayan beldede

Hep mekan kurduğum yerdir gözlerin

Üfül üfül esen rüzgarla

İçimde çağlayan nehirdir gözlerin

Gündüzleri kayıp olan gece

Geceme aydınlık veren gözlerin

Ruhumda esen fırtına

Benliğimi saran bir büyü gözlerin

Bitmeyen arzudur gönlümde

Dilimde bestedir senin gözlerin

Bitmeyen besteme ilhamla

Hayata hayat katan gözlerin', 'Gözlerin Baharı eksik olmayan beldede Hep mekan kurduğum yerdir gözlerin Üfül üfül esen rüzgarla İçimde çağlayan nehirdir gözlerin Gündüzler...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gozlerin-95-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğiniz', 'yureginiz-abdullah-garip-gupwn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüreğiniz

Sadelikte kır çiçekleri kadar

Sevecen güzellikte gösterişsiz

Şefkatte mavi kadar

Mütebbessim ümit saçan yüreğiniz', 'Yüreğiniz Sadelikte kır çiçekleri kadar Sevecen güzellikte gösterişsiz Şefkatte mavi kadar Mütebbessim ümit saçan yüreğiniz...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yureginiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senli bir güne muhtacım', 'senli-bir-gune-muhtacim-abdullah-garip-3j7oo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Senli bir güne muhtacım



 Senli bir güne muhtacım 

 Dalgaların sesinde 

 Denize düşen ay ışığında

 Ve sakın unutma ki;                                             

 Kalbimdeki gözyaşıyla

 Seni aramaktayım

Yağmur damlalarında

Kar tanelerinde

Kuşların ötüşünde

Güllerin tomurcuk verişinde

Ağaçların yapraklarını döküşünde

Baharın kokularında

Gökyüzü

Maviliğe büründüğü anlarda

Beni hatırla      16.02.2001', 'Senli bir güne muhtacım  Senli bir güne muhtacım   Dalgaların sesinde   Denize düşen ay ışığında  Ve sakın unutma ki;                       ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senli-bir-gune-muhtacim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdanı söküp atamadım', 'sevdani-sokup-atamadim-abdullah-garip-pqoox', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevdanı Söküp Atamadım

Tarihte olmadı biliyorum biz gibi seven

Yoksa biz kavuşmadan ayrılacak mı etle kemik birbirinden

El değdiremeyeceklerini biliyorum, gönlüme ezelden

Sevdanı söküp atamadım, hiç mi hiç içimden..

Yara alıyorum, yara üzerine aşkıma göz dikenlerden

Gözümde yok mal menal, çoluk çocuk hislerimden

Sen varsın ya ay yüzlüm, gülgoncanı her dem düşünen

Sevdanı söküp atamadım, hiç mi hiç içimden.

.

Ali dağlar var şimdi arada içimi kemiren

Ruhumdan sabahın seherinde, kuşların sana söyledikleri namelerden

Vah çilem, vah çilem

Sevdanı söküp atamadım, hiç mi hiç içimden

Cana can katanım benim benim bir tanem

Kalmadı mağna da artık senden artık

Dertlerim derbederim sensiz her gecem

Sevdanı söküp atamadım, hiç mi hiç içimden

Binlerce yıl sayılan günlerdeki hayalin dese

Kabustur bunlar diye inanacağım yürekten

O hasretin kül etti, etti beni benden

Sevdanı söküp atamadım, hiç mi hiç içimden

Nasıl durulur sensiz öğret bana ne olur

Ayrı bir dünya kurdum gönlüme senden, sevginden

Ruhuma ruh katanım benim tatlı çilem

Sevdanı söküp atamadım, hiç mi hiç içimden

Yaş değil artık kan akıyor gözlerimden

Kimlere söyleyeyim ruhumdaki hasretimi bilmem

Hüsran doldu günlerime, gecelerimden; 

Sevdanı söküp atamadım, hiç mi hiç içimden

Ne kadar ağlasam, ne kadar feryat etsem

Kabulleniyorum işte bu benim çilem,

Ve bütün benliğimi saran; 

Sevdanı söküp atamadım, hiç mi hiç içimden

Ar ettim niyetlerime sitem ettim,

Bursu burcu kokan tenini ayıramadım bedenimden

İliklerime işleyen tatlı sözlerinden; 

Sevdanı söküp atamadım, hiç mi hiç içimden

Gecelerim sevda yüklü bir gemi,

Seni bana getiren menzillerden

Yüreğime aşk oklarını saplayan gözlerin yüzünden

Sevdanı söküp atamadım, hiç mi hiç içimden

Beyaz atlı yiğidim gelir sandım ötelerden

Bize de müjde verirler dedim gayb aleminden

Yiğidim dedim, yiğidim neredesin sen; 

Sevdanı söküp atamadım, hiç mi hiç içimden

Şimdi unutmam gerekiyormuş sözde seni bilmem neden

Taşladılar sevgilileri kaç bir elden

Cihanı verseler bu aşktan vazgeçmem

Sevdanı söküp atamadım, hiç mi hiç içimden

Divane gönlümde bak ne inkılaplar oluyor

N.. sandığın Mücrim yüzünden

Durmuyor kararında gündüz ve gecem

Sevdanı söküp atamadım, hiç mi hiç içimden', 'Sevdanı Söküp Atamadım Tarihte olmadı biliyorum biz gibi seven Yoksa biz kavuşmadan ayrılacak mı etle kemik birbirinden El değdiremeyecekler...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/sevdani-sokup-atamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Gün', 'o-gun-abdullah-garip-zdlqx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O Güne

İnanıyorsan beni dinle

O Gün; 

Bir türlü açmayan gonca gül açacak,

O gönül sevdikleriyle hazan ertesi buluşacak

Hep hazan olan zaman, o tarafta bahar olacak

O GÜN; 

Hani kıyametler kopacak,

Üzerine giydiremediğim beyaz elbise

Vücuduma nadanlar saracak,

O Gün; 

İşte onlar,

Hani üzgün görünenler, ağlayanlar sızılayanlar,

Sevince gark olup, gülenler murada nail olacak

O Gün; 

Üzerime atılan her toprak davetlim,

Mezar taşım şahidim olacak,

Sual Melekleri alkışlayanım,

Başucumda ki yiğidim benim olacak..

Tamam mı?', 'O Güne İnanıyorsan beni dinle O Gün;  Bir türlü açmayan gonca gül açacak, O gönül sevdikleriyle hazan ertesi buluşacak Hep hazan olan zaman,...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/o-gun-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim sana olan aşkım', 'benim-sana-olan-askim-abdullah-garip-apj6n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Benim sana olan aşkım

Gökte bir yıldız değil ki,

Güneş doğunca kayıp olsun   24.03.1998

Dalında bir gül değil ki,

Sonbahar gelince solsun

Benim bir okyanus kadar büyük

Güneş ışınları gibi kalıcı

Ve bir çocuk kadar hassastır      07.11.1977

Ey yarı didar

Senin aşkından yüreğimde ateşler kor gibi

Söyle sensiz ben ne yapayım

Yüreğimdeki acıyı nasıl dindireyim

	

Bak şimdi yine sensiz yine yapayalnız

Zihnimde hatıraların

Yüreğimde sevginle

Ruhumda siteminle 18.02.2001

Dalgalar kıyılara hırçın çarpar

Senin bakışların ise yüreğimi parçalar

Gözlerindeki o alımlı bakış,

Bana doğru gel der.

Yıllar bir ömrü,

Sana olan sevgim ise benliğimi tüketir

Bir nisan yağmuru,

Bir haziran güneşi

Ve yine gözlerim yollarda bekliyorum seni

Çünkü seni seviyorum

Çünkü seni seviyorum...29.12.1997', 'Benim sana olan aşkım Gökte bir yıldız değil ki, Güneş doğunca kayıp olsun   24.03.1998 Dalında bir gül değil ki, Sonbahar gelince solsun Be...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/benim-sana-olan-askim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Böyle Garip', 'ben-boyle-garip-abdullah-garip-dio73', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben Böyle Garip			

Ben böyle garip,ben böyle yalnız		

Ben böyle virane,ben böyle bitap		

Gülleri açtırdın,leylaklar soldurttun	

Kalbimde bir acı bahar yaşattın		

Şimdilerde yine sensiz yapayalnız	

Şimdilerde yine sensiz ağlamaktayım.    23,3,2001', 'Ben Böyle Garip			 Ben böyle garip,ben böyle yalnız		 Ben böyle virane,ben böyle bitap		 Gülleri açtırdın,leylaklar soldurttun	 Kalbimde bir...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ben-boyle-garip-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Havuz Başı', 'havuz-basi-firat-karakurt-s8yla', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geceler karanlık,

Işıklar yanmıyor

Suda bir parıltı neden olmuyor.

Yoksa kalbimdeki ateşmi sönüyor

Sönüyorda benim ruhum duymuyor

Neden ben seni,seni sevmişim

Yoksa yanlış birisini mi seçmişim.', 'Geceler karanlık, Işıklar yanmıyor Suda bir parıltı neden olmuyor. Yoksa kalbimdeki ateşmi sönüyor Sönüyorda benim ruhum duymuyor Neden ben ...', ARRAY['Türk Edebiyatı','Şiir','Fırat Karakurt']::text[], 8.5, '{"poet":"Fırat Karakurt","poet_slug":"firat-karakurt","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/havuz-basi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim', 'ozledim-firat-karakurt-nfov2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerine öyle baktım 

Yüreğimden silemedim

Şu koskoca dünyada ben sensiz edemedim

Edemedim 

Edemedim

Yar sensiz edemedim', 'Gözlerine öyle baktım  Yüreğimden silemedim Şu koskoca dünyada ben sensiz edemedim Edemedim  Edemedim Yar sensiz edemedim...', ARRAY['Türk Edebiyatı','Şiir','Fırat Karakurt']::text[], 8.5, '{"poet":"Fırat Karakurt","poet_slug":"firat-karakurt","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ozledim-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden sonra...', 'senden-sonra-ferit-teksoy-zidtr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dün boğazdaydım akşam,Kavakta senden sonra

Yer güzel boğaz ve manzaraysa harika

Üçü bendim,bir arkadaş,dört kişiydik masada

Sohbet güzel,yemek nefis,rakı ise bambaşka

Rakı dedim de sahi,sanki tadı değişmiş,

Bir başka güzel şimdi,yeniden keşfedilmiş.

Bak! ..anlatayım sana dün gece neler oldu? 

Muzip arkadaşıyla çok koyu bir sohbette

Ferit''se düşünceli,kafası başka yerde

Dinozor kontrollü,ikisine bakıyor

Biri hata yaparsa,hemen ikaz ediyor

Sohbet sürüp giderken,bilmem kaçıncı saat? 

Arkadaştan uyarı; ''''nerdesin dostum,anlat? ''''

Nasıl derim ben şimdi başıma gelenleri? 

Nasıl anlatırım ona birini sevdiğimi? 

Diyemedim ki dostum''''yüreğim uzaklarda''''

''''Ben buradayım ama,beynim onun yanında''''

İyi ki Dinozor var,durumu gördü hemen

Cevabı yapıştırdı,kem-küm bile etmeden

''''Bir sıkıntım olsaydı hiç saklarmıydım senden? ''''

''''Hava biraz serin de içim ürperdi birden''''

Allahtan uzatmadı,konu kapandı hemen

İşte böyleydi gece biraz buruk,biraz şen

Bir sen kaldın içimde dün geceden yadigar

Bir de tadı değişen o güzelim rakı var..', 'Dün boğazdaydım akşam,Kavakta senden sonra Yer güzel boğaz ve manzaraysa harika Üçü bendim,bir arkadaş,dört kişiydik masada Sohbet güzel,yem...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/senden-sonra-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsmi yarda', 'i-smi-yarda-sair-ahrazi-662fa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Âmâ gözde fer olur yârin düşü,

Şehri aşka bir ebedlik tan verir.

Bilmez vakti anıdır mecnun kişi,

İsmi yarda bin ömürlük can verir.', 'Âmâ gözde fer olur yârin düşü, Şehri aşka bir ebedlik tan verir. Bilmez vakti anıdır mecnun kişi, İsmi yarda bin ömürlük can verir....', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ismi-yarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tamirci Çırağı Çocuk', 'tamirci-ciragi-cocuk-sabahittin-kurtoglu-v67mk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gözlerinde

hüzün

var

elleri

yaralı

küçük

tamirci

çırağı

çocuk

rüzgar

fırtınayla

geliyor

sanki

uçacak

gibi

cılızsın

çocuk

yaralı

ellerinle

ellerimi

sıkıca tut

çocuk', 'gözlerinde hüzün var elleri yaralı küçük tamirci çırağı çocuk rüzgar fırtınayla geliyor sanki uçacak gibi cılızsın çocuk yaralı ellerinle el...', ARRAY['Türk Edebiyatı','Şiir','Sabahittin Kurtoğlu']::text[], 8.5, '{"poet":"Sabahittin Kurtoğlu","poet_slug":"sabahittin-kurtoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/tamirci-ciragi-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maşrapa', 'masrapa-sabahittin-kurtoglu-f0r8r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'şarap

içmeninde

tadı

kalmadı

kalayı

dökülmüş

bakır

maşrapamdan

kanım

bakırlaştı

kristal

kadehle de

içmenin

keyfi

yok

şarabıma

kumlar

ve

küller

karıştı', 'şarap içmeninde tadı kalmadı kalayı dökülmüş bakır maşrapamdan kanım bakırlaştı kristal kadehle de içmenin keyfi yok şarabıma kumlar ve küll...', ARRAY['Türk Edebiyatı','Şiir','Sabahittin Kurtoğlu']::text[], 8.5, '{"poet":"Sabahittin Kurtoğlu","poet_slug":"sabahittin-kurtoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/masrapa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Delinin sessizliğindeyim', 'bir-delinin-sessizligindeyim-ali-osman-yilmaz-6bjqc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yitirmişliğin acısıyla,

Güneşini kaybeden,

Gecelere mahkum,

Ellerinde yalnızlığın kelepçeleri,

Sessizlik adasında sürgün,

Okyanusun ortasında ki,

Rotasını bulamayan,

Geminin kaptanı gibiyim.

Konuşacak kimse olmayınca,

Dolanırım adada dilsiz,

Ama yazıyorum içimdekileri,

Yüreğim yanımda oldukça,

Bu aşk için attıkça gümbürdeyerek,

Yazdıklarımı şişelere koyacak,

Yalnızlığımın gardiyanı deniz,

Dalgalarında salına salına,

Şiirlerimi her gün sana getirecek.

Suskunluğum aldatmasın seni,

Bir delinin sessizliğindeyim,

Sanma ki bir tas akıl,

Gidermeye yeter deliliğimi,

Aklımı yitirmedim ama,

Kullanacak yer bulamıyorum,

Ondan böyle çırpınışım.

Güneş göstermeyecekse seni,

Hangi ışığı bekleyeceğim? 

Benim ışığım,güneşim,sendin,

Tek bir ışık var,

O içimde gördüğün,

Aşk kandilinden yayılan,

Nice güneşlere bedel,

Hala beni yaşatan,

Yüreğimin sesini,

Duymanı sağlayan,

Senden bana armağan,

Aşkımın enerjisidir.', 'Yitirmişliğin acısıyla, Güneşini kaybeden, Gecelere mahkum, Ellerinde yalnızlığın kelepçeleri, Sessizlik adasında sürgün, Okyanusun ortasınd...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bir-delinin-sessizligindeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Subutay', 'subutay-huseyin-ateskaan-wxpob', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sizlerden sonra neler olur diye düsünmüstünüz

Oba nam bulsun topragi bol olsun istemistiniz

Hep Türk diye bir asyayi süzmüstünüz

Siz topragi doyursun diye kana bezdirmistiniz

Yazitta dediginize göre bizi hiç düsünmemissiniz

Oysa azda olsak su zamanda sizleri bilenlerdeniz

Gelecekte birileride bizi bilecek

Hep birlikte bir gün karsilasacagiz toprak bitecek', 'Sizlerden sonra neler olur diye düsünmüstünüz Oba nam bulsun topragi bol olsun istemistiniz Hep Türk diye bir asyayi süzmüstünüz Siz topragi...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Ateşkaan']::text[], 8.5, '{"poet":"Hüseyin Ateşkaan","poet_slug":"huseyin-ateskaan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/subutay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O günden sonra! ! ! ! ! ! ! ! ! ! !', 'o-gunden-sonra-ali-osman-yilmaz-874x7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yalnız yağmur olsa? 

Ortalık kar ve fırtına,

Kıyametler kopmada,

İçimde sen oldukça,

Belki hüzünlü ama,

Seninleyim daima,

O günden sonra! ! ! ! ! ! ! ! ! ! ! 

Senin yaşadığını bildikçe,

Şiirlerinde seni okudukça,

İsterse yalnızlığın kelepçeleri,

Sessizliğin koynunda,

Yaşamaya mahkum kılsada,

İçimdeki cevher,İnan güzelim,

Yaşatacak Koca Adamı,

Ölmem sana olan aşkım,

Seninle birlikte,

Bende yaşadıkça.', 'Yalnız yağmur olsa?  Ortalık kar ve fırtına, Kıyametler kopmada, İçimde sen oldukça, Belki hüzünlü ama, Seninleyim daima, O günden sonra! ! ...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/o-gunden-sonra--siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayaklarını Sev', 'ayaklarini-sev-aynur-uluc-igy1u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ayaklarını sev 

o ayaklar bana getirecek seni

ilk görüşte dokunmak istediğim o ayaklar

bazen  ayaklarını seyrediyorum gizli gizli

ateşli bir şey tartışırken takılıyor gözüm

alıp sürüklüyor  ayağındaki ten

bir ayak manyağı olduğumdan mı nedir

her görüşümde daha da seviyorum

ayağından hoşlanmadığım birini

hatta sevmekten korkuyor  sözüm

dedim ya manyağım ben.

 (2001)', 'ayaklarını sev  o ayaklar bana getirecek seni ilk görüşte dokunmak istediğim o ayaklar bazen  ayaklarını seyrediyorum gizli gizli ateşli bir...', ARRAY['Türk Edebiyatı','Şiir','Aynur Uluç']::text[], 8.5, '{"poet":"Aynur Uluç","poet_slug":"aynur-uluc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ayaklarini-sev-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep', 'hep-abdullah-garip-5q7lc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hep…

Dizi dizi sen vardın, hep gecelerimde,

Sevgi sözcüklerin

Hece heceydi hep dilimde,

Gönlümde sızım inceden ince; 

Yaşlarım inci inciydi secdelerimde', 'Hep… Dizi dizi sen vardın, hep gecelerimde, Sevgi sözcüklerin Hece heceydi hep dilimde, Gönlümde sızım inceden ince;  Yaşlarım inci inciydi ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hep-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözü Yaşlıya', 'gozu-yasliya-abdullah-garip-931qu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözü Yaşlıya

Attığım adım sanaydı biliyorsun,

O ayrı günler yara açmadı mı sanıyorsun,

Kurumadı yaşlar, dinmedi sızılar görüyorsun,

Nedir gözlerindeki ıslak yoksa sen ağlıyor musun? 

O eski günleri biliyorum sen de arıyorsun

Sanki hissediyorum, olanlardan pişmanlık duyuyorsun

Kim bilir belki de bana gönül koyuyorsun

Yine sana dokundu, yoksa sen ağlıyor musun? 

Biz bilemeyiz, Allah (cc)  kerim diyorsun

Bir de ahd-ı peymandan bahsediyorsun

Sen her şeyi hüsn-ü kabül görüyorsun

Gönlünü dolup taşıran nedir, yoksa sen ağlıyor musun? 

Anıları bırakıp uzaklara mı gidiyorsun,

Arzularımı, emellerimi eminim biliyorsun

Sil gözlerini, ümitleri olsun istemiyor musun

Söyle şimdi bana, beni seviyor musun?', 'Gözü Yaşlıya Attığım adım sanaydı biliyorsun, O ayrı günler yara açmadı mı sanıyorsun, Kurumadı yaşlar, dinmedi sızılar görüyorsun, Nedir gö...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gozu-yasliya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Bir Dostum', 'oyle-bir-dostum-abdullah-garip-h8jww', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öyle Bir Dostum

Öyle bir dostum olacak ki

Beni benden çok sevecek

Beni sevgi diyarına götürecek

Ellerimi tutacak boynuma sarılacak

Gözyaşımı silecek  saçlarımı okşayacak

Bana her konuda yardım edecek

Her zaman yanımda olacak

Bana dertlerimi unutturacak

Varlığıyla ruhuma huzur yüzüme tebessüm

Bir dosta bir arkadaşa ihtiyacım var

Sensizim ey dost

Yetiş imdada artık dayanamıyorum

                                            03.04.1998', 'Öyle Bir Dostum Öyle bir dostum olacak ki Beni benden çok sevecek Beni sevgi diyarına götürecek Ellerimi tutacak boynuma sarılacak Gözyaşımı...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/oyle-bir-dostum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Almuhtada’nın Izdırabı', 'almuhtada-nin-izdirabi-ali-osman-yilmaz-kvqdd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uyuyan güneş kentinin üstüne gece ve sessizlik çökmüştü.Zeytin ve  Defne koruluklarıyla dolu heybetli tepeler arasındaki evlerin lambaları sönmüştü. Tanrıların evlerinin önünde dev bekçiler gibi dikilen mermer sütunlar gümüş ay ışığıyla yıkanıyordu.                        

	Ruhların uykuya yenik düştüğü o saatlerde büyük rahibin oğlu Nathan titreyen elinde bir meşale taşıyarak iştar tapınağına girdi.Lambaları ve tütsüleri yaktı,kısa süre içinde en uzak köşelere bile mür ve tütsü kokuları yayıldı.Sonra altın ve fildişi kakmalı sunağın önünde diz çöküp sağ elini iştara doğru kaldırdı ve tıkanır gibi bir sesle şöyle haykırdı; ’’’Ey Büyük İştar, Aşk ve Güzellik Tanrıçası, bana merhamet et''de,Ölüm’ün elini,ruhumun senin arzunla seçtiği sevdiğimin,aşkımın üstünden uzak tut.

               Ne hekimlerin ilaçları,ne de büyücülerin büyüleri fayda etti.Geriye senin kutsal isteğinden başka bir şey kalmadı.Rehberim ve yardımcımda sensin.Yaralı yüreğime ve acıyla inleyen ruhuma bak da, dualarımı kabul et.

              Sevdiğimin yaşamını bana bağışla ki,aşk ayinleriyle sana tapınabileyim ve yaşamımızı ve sevgimizi senin yoluna adayalım.

	‘’Büyük rahip Hiramın oğlu hizmetkarın Nathan,eşsiz bir güzeli sevdi ve onu kendine eş olarak seçti.Ama bazı dişi cinler onun güzelliğini ve benim tutkumu kıskanıp ona ölümcül bir hastalık üflediler,şimdi ölümün habercisi kara kanatlarını üstüne germiş,keskin pençelerini açmış,yatağının başında bekliyor.Yalvarırım bize merhamet et.Daha yaz yaşına ulaşmamış bu çiçeği koru’’.

                ‘’O'''' nu Ölümün pençeinden kurtar ki,sana ilahiler söyleyelim, onuruna tütsüler yakalım, sunağında kurbanlar keselim,şişelerini parfümle dolduralım,revakının altını Güller ve menekşelerle süsleyelim.

                  Sevincin keder karşısındaki bu savaşında,Aşk ölüme üstün gelsin.

(Cibran.Kendimle Konuşmalar)  Ali Osman Yılmaz

Acı Tanrım,şu gönlümün sesine,

Acı Koca Adama,dertli sinesine,

Hep harabata yön tutar ayağım,

Acı tanrım,Aşkla yanan yüreğime.

(Hayyam)', 'Uyuyan güneş kentinin üstüne gece ve sessizlik çökmüştü.Zeytin ve  Defne koruluklarıyla dolu heybetli tepeler arasındaki evlerin lambaları s...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/almuhtada-nin-izdirabi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanık Çınar Yaprakları Ve Kış Kuşları', 'yanik-cinar-yapraklari-ve-kis-kuslari-ahmet-kose-tcsqe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yanık çınar yaprakları örtüyor sıcak adımlarımı

savrulan aşk uğultularının donukluğunda.

Avucumda sevgili

üşüyen kış kuşları

ellerim paltomun ceplerinde

sıcacık yürüyoruz sevgili kış kuşlarımla.

Bunca kayıplar yitirmedi bendeki insanı

onca duvarlar yıkılırken üstüme,

bence 

sızılı ve örselenmiş olan 

geçmiş ti.

Senin suçun değildi yürek incitmeleri

dokunmamışsın hiç ince camlı yürek pencerelerine

giderken bu bilmediğin buzlu göl patikalarında.

Boğulursunuz dumanından yaklaşmayın

yanık yürek yangılarının yamacına

serilmişim bir dağ yatağına sere serpe

upuzun bırakmışım gönlümü

bir tepesinden, 

bir eteğine yatağımın

dağılmışım dağlarımın içinde,

serilmiş üzerime 

mavi yıldızlı aylı yorganım,

kalk!  diyor...dirimim! 

çık! deniz feneri terasına

dök! yanık çınar yapraklarını kalbinden

denize sıfır

mavi kokulu dünyandan

uçsuz ufuksuz

sevginin dalgalı derinliklerine...

Ne duruyorsun

bulmuşken böyle bir hayali fırsatı...! 

''04-bitez', 'Yanık çınar yaprakları örtüyor sıcak adımlarımı savrulan aşk uğultularının donukluğunda. Avucumda sevgili üşüyen kış kuşları ellerim paltomu...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Köse']::text[], 8.5, '{"poet":"Ahmet Köse","poet_slug":"ahmet-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yanik-cinar-yapraklari-ve-kis-kuslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haberin Var mı?', 'haberin-var-mi-ebru-delice-cxzc5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bu gece...

senli düşlerle içtim

artık rakı içmiyorum

nane likörüm bana yetiyor

boğazımı yakarken........

senli düşleri de yakıyor

bu öyle bir yangın ki

sönmüyor! 

düşlerim

.............sensizliğim

.................. ve ben

kor alevlerde yanan; 

..........sevdasız sevdam

----

sarhoş olmak istiyorum

sensizliğin sarhoşluğundan

alkolün sarhoşluğuna geçemiyorum

SENİ SEVİYORUM

SENİ İSTİYORUM

haberin var mı?', 'bu gece... senli düşlerle içtim artık rakı içmiyorum nane likörüm bana yetiyor boğazımı yakarken........ senli düşleri de yakıyor bu öyle bi...', ARRAY['Türk Edebiyatı','Şiir','Ebru Delice']::text[], 8.5, '{"poet":"Ebru Delice","poet_slug":"ebru-delice","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/haberin-var-mi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Sevgiliye', 'eski-sevgiliye-ebru-delice-m8cvi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bilirsin 

gururum namusumdur

kesmez beni acılar

beni vururlarsa

ancak arkamdan vururlar...........', 'bilirsin  gururum namusumdur kesmez beni acılar beni vururlarsa ancak arkamdan vururlar..............', ARRAY['Türk Edebiyatı','Şiir','Ebru Delice']::text[], 8.5, '{"poet":"Ebru Delice","poet_slug":"ebru-delice","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/eski-sevgiliye-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Menfaat', 'menfaat-ahmet-aksoy-8zz3d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kimbilir belkide gerçekde hayat, 

menfaatler kumpanyası,

bizlerse, senaryosu kaybolmuş 

bir oyunun oyuncuları

kimbilir belkide işleyen çark,

bizim usumuzla dönüyor,

kim inkar eder

günahkar olduğunu,

hesaplar üzerine kurulmuş yaşamlar

loş bir ışık altında kesişiyor,

herşey karşılıklı diyor sakallı bilgeler,

bizse; yani, çoğumuz ya da çok azımız,

“efendim hiç öyle olur mu diyerek”

gülüyoruz bıyık altından yarım ağızlarla,

oysa çoğumuz ya da çok azımız,

aklında düzenlerle giriyor çıplak yataklara,

ne verirsen onu alırsın demiyor belki 

demiyor ama öyle söylemiyor bilinç altı,

oynanan menfaatler kumpanyası,

ya katıl ya da seyirci ol diyemiyor insan,

çünkü dışarı da kalanları göremez içeri de olan,

yine de son söz; söz meclisten dışarı, 

dışardayım diyen dışarıda kalsın,

ya da en azından öyle sansın,

içeride olana sözüm, 

çıkar ağzındaki çıkarı

bakalım kiminki daha büyük bu şiirde….', 'kimbilir belkide gerçekde hayat,  menfaatler kumpanyası, bizlerse, senaryosu kaybolmuş  bir oyunun oyuncuları kimbilir belkide işleyen çark,...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/menfaat-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Başka Özledim Seni', 'bir-baska-ozledim-seni-hasan-huseyin-ozak-lscoy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nedendir bilmem,

bu gün bir başka özledim seni

Nefes alırken, nefesimi bir başka çektim içime

Sigaramı bir başka içtim

Ağlamak geldi içimden, durup dururken

Bir başka küfür ettim,

bir başka baktım şu kahpe dünyaya

Ardından,

her zamanki gibi yatağıma gidip,

yorganı kafama dek çektim

Ve yine sana geldim', 'Nedendir bilmem, bu gün bir başka özledim seni Nefes alırken, nefesimi bir başka çektim içime Sigaramı bir başka içtim Ağlamak geldi içimden...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özak']::text[], 8.5, '{"poet":"Hasan Hüseyin Özak","poet_slug":"hasan-huseyin-ozak","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bir-baska-ozledim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-mustafa-samil-sevim-j7fwx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'B  ahar geldi sandım yüreğime; 

U  zun sürecek sandım seninle.

K  ahretsin yanıldım ben yine; 

E  ninde sonunda ayrıldık işte; 

T  utunamadık birbirimize.

V e hazin son sevgimizde.

E zdik yüreğimizi ikimizde.

Ş amil BUKET siz ne yapacak şimdi,

A cısını kalbine nasıl gömecek şimdi,

M adem unutmak bu kadar kolay diyorsun.

İ stersen sen unut beni.

L akin sonsuza dek unutmayacağım seni.', 'B  ahar geldi sandım yüreğime;  U  zun sürecek sandım seninle. K  ahretsin yanıldım ben yine;  E  ninde sonunda ayrıldık işte;  T  utunamadı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Şamil Sevim']::text[], 8.5, '{"poet":"Mustafa Şamil Sevim","poet_slug":"mustafa-samil-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ayrilik-139-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyorsun', 'biliyorsun-mustafa-samil-sevim-mx03g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'B  en Seni Sevdim biliyorsun; 

U  nutamayacağımı biliyorsun.

K  albimdeki yerini biliyorsun.

E  riyip bitmeyeceğimizi biliyorsun; 

T  ükenip gitmeyeceğimizi biliyorsun.', 'B  en Seni Sevdim biliyorsun;  U  nutamayacağımı biliyorsun. K  albimdeki yerini biliyorsun. E  riyip bitmeyeceğimizi biliyorsun;  T  ükenip...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Şamil Sevim']::text[], 8.5, '{"poet":"Mustafa Şamil Sevim","poet_slug":"mustafa-samil-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/biliyorsun-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cevap Veremem', 'cevap-veremem-mustafa-samil-sevim-o1j6h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'B  ir gün ölürsem eğer; 

U  nutmak istemem seni.

K  albime gömersem eğer; 

E  min ol ki; 

T  a sonsuza kadar unutmam seni.

Ç  ehreni görmemiş olabilirim.

E  llerini tutmamış.

T  arifsiz bir sevgiyle severim seni,

İ  nanır mısın bilemem,

N  eden diye sorma cevap veremem.', 'B  ir gün ölürsem eğer;  U  nutmak istemem seni. K  albime gömersem eğer;  E  min ol ki;  T  a sonsuza kadar unutmam seni. Ç  ehreni görmemi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Şamil Sevim']::text[], 8.5, '{"poet":"Mustafa Şamil Sevim","poet_slug":"mustafa-samil-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/cevap-veremem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yavrularımıza', 'yavrularimiza-sair-saftirik-zj7kg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yavrularımıza

Anlayamadık…

Biz çocukken derlerdi de

Kuşaklar çatışıyormuş bilemedik

Kapasitemiz yetmedi belki! ...

Büyüdük…

Zaman su gibi

Akarken ömrümüzde

Çağınız geldi dediler.Evlendik...

Kurtulmak isterken çocukluğumuzdan

Çocuk sahibi olduk

Derken.Evlilik neymiş? Niye evlenirmiş insan 

Evlendik çağımız gelmiş diye

Zaman bu.Su gibi dedim ya

Önce bir sonra iki çocuk

Geldiler dünyaya sorulmadı onlara 

Gelmek ister misiniz  dünya ya? 

Canımıza can kattınız siz

Evliliği yuva yaptınız siz

Bilmeden, bizi biz yaptınız siz

Yuvamızın neş’eleri size müteşekkiriz

Kuşak çatışmasıymış bize ne

Biz sizin kuşağınızız kime ne

Büyük yanında sevilmezmiş bize ne 

Sevmeye doyamayız sizi kime ne

Ne kadar şükretsek azdır! Yaradana…

Sizleri sağlıklı olarak bize bağışlayana

Acınızı göstermesin bize…Aman  haa…

Varlığınıza,sağlığınıza duacıyız her zaman…

                Saftirik                                                                                                        29/01/2004', 'Yavrularımıza Anlayamadık… Biz çocukken derlerdi de Kuşaklar çatışıyormuş bilemedik Kapasitemiz yetmedi belki! ... Büyüdük… Zaman su gibi Ak...', ARRAY['Türk Edebiyatı','Şiir','Şair Saftirik']::text[], 8.5, '{"poet":"Şair Saftirik","poet_slug":"sair-saftirik","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yavrularimiza-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamadın', 'anlamadin-sair-saftirik-y0330', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Anlamadın! ...

Bir idik iki olduk

Demiş  atalarımız

Yuva kurunca gençken

Ben de anlamadım önceleri

Evlenmekle yuva kurduğumu zannettim

Sonra, sessizliği fark ettim

Anladığımı zannettim

İkiydik üç olduk

Bir şeyler değişti hayatımızda

Masum gülüşler ve ağlayışlar

Değiştiğini zannettim bir şeylerin yaşantımızda

Evlenmek ya da yuva kurmak

Böyle  değildi  gönlümde

Fırtınalar kopmalıydı hem özümde hem benliğimde

Sığınacak liman ararken gözlerinde…

Günler geçerken böylece

Sabır taşına döndüm kendimce.

Öylece dalmışken hayat mücadelesine

Birde baktım ki dört can olmuşuz, şöylece

Emeklemeler… bebeğimizle eşdeğerken bile…

Birde kendime sordum

Nedir acaba anlaşılmayan diye

Sen mi beni anlamadın.

Yoksa…..

Ben mi seni anlamadım

Çözemedim büyük sırrını muammanın

Korktum birdenbire

Anlaşılmadan mı bitecek hayatım….

Son bir umutla, bir daha baktım

Üzgünüm ama,sen beni anlamadın….

Elveda …Elveda…tatlım….

		             Saftirik

                                            29.1.2004', 'Anlamadın! ... Bir idik iki olduk Demiş  atalarımız Yuva kurunca gençken Ben de anlamadım önceleri Evlenmekle yuva kurduğumu zannettim Sonra...', ARRAY['Türk Edebiyatı','Şiir','Şair Saftirik']::text[], 8.5, '{"poet":"Şair Saftirik","poet_slug":"sair-saftirik","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/anlamadin-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sevgilin oldu mu...', 'bir-sevgilin-oldu-mu-i-brahim-ethem-bingul-mhonu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Onlarca defa cama üfleyip

Sevdiğinin adını yazdın mı

Güneş doğarken ellerini açıp 

Sevgiliye dua ettin mi hiç

Yüreğinin en pare pare olduğu anda,

Onu yanında isteyipte

Yüreğinin yanında hissettin mi

Sayısız kapısına gidip,

Demeliyim dediğin,

İki kelimen oldu mu hiç

Uyandığında,

Günaydın diyen,

Sıcaklığını hissettiğin

O ışıl ışıl gözlerinde

Yüreğini gördüğün

Yüreğini taşıyan

Bir sevgilin oldu mu hiç', 'Onlarca defa cama üfleyip Sevdiğinin adını yazdın mı Güneş doğarken ellerini açıp  Sevgiliye dua ettin mi hiç Yüreğinin en pare pare olduğu ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-sevgilin-oldu-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Feryatlarım...', 'feryatlarim-i-brahim-ethem-bingul-51pn9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hoş geldin yaşamaya korktuğum sevda atışım

Hoş geldin bitimsiz nefesim

Hoş geldin tutamadığım tövbem

Ben ne seher yıldızındaydım

Nede limansız denizde

Bilinmezliğin ortasında

Hep sendin bir sen

Bak burası gönül sarayım sana ait

Hani sana göstermeye hep korktuğum

Bak burası başımı duvarlara vurduğum yer

Hani seni çıkartmak istercesine içinden

Bak burası gönül han''ım yolcular için

Hani seni silecektiler ya işte onlar

Bak bunlarda feryatlarımı duyan yedi meleğim

Hani bana elveda diyecek gücü verenler', 'Hoş geldin yaşamaya korktuğum sevda atışım Hoş geldin bitimsiz nefesim Hoş geldin tutamadığım tövbem Ben ne seher yıldızındaydım Nede limans...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/feryatlarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mum Kendine Işık Vermez!', 'mum-kendine-isik-vermez-ozan-si-ar-agdasan-jss0b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eridim mumlar misali

Mum kendine Işık vermez

Çiğnendim kumlar timsali

Çöl çeşmeğe Aşık vermez! 

Canan dedim candan yandım

Şafaklarda doğan tandım...

Kepçe kepçe dosta sundum

Namert se bir Kaşık vermez

Alın, ağ oldu allarım

Sevda atımı nallarım

Bir yavru gibi sallarım

Kuru ağaç Beşik vermez

Yaşamadım hep yaşattım

Şerbet sundum, ağı tattım

Gece ''rüzgar ile yattım''...

Şiar güne Eşik vermez! ...

Söz ve Müzik:ozan ŞİAR Ağdaşan ''İnadına Sevdamız'' Can Yay. 

Sevdamız Güneştir       albümü Avrupa   www.siarcan.com', 'Eridim mumlar misali Mum kendine Işık vermez Çiğnendim kumlar timsali Çöl çeşmeğe Aşık vermez!  Canan dedim candan yandım Şafaklarda doğan t...', ARRAY['Türk Edebiyatı','Şiir','Ozan ŞİAR Ağdaşan']::text[], 8.5, '{"poet":"Ozan ŞİAR Ağdaşan","poet_slug":"ozan-si-ar-agdasan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/mum-kendine-isik-vermez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuyruklu yıldız', 'kuyruklu-yildiz-hicabi-ceylan-tam6n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sır gibi gizledik gerçekleri

Yüz sürdü geleceğe 

İçimizde büyüttük 

Sevgimizi 

Söyleyemedik birbirimize

Aynı canda nefesti

Birlikte soluduğumuz

Beraberken birbirine hasretti

Sevgimizde

Arayıp ta bulduğumuz

Düşüncelerimizde büyüdü

Beslendi dostluğumuz

Önce emekledi, sora yürüdü

Bilinmeyen bir sırdı sanki

Zor bulup ta 

Kaybetmeye korktuğumuz

Senle hayatı paylaşımdı

Güzel olan

Canımda candın

Canında candım

Kalpten kalbe uzanan

(canımda can olan/can dostuma)', 'Sır gibi gizledik gerçekleri Yüz sürdü geleceğe  İçimizde büyüttük  Sevgimizi  Söyleyemedik birbirimize Aynı canda nefesti Birlikte soluduğu...', ARRAY['Türk Edebiyatı','Şiir','Hicabi Ceylan']::text[], 8.5, '{"poet":"Hicabi Ceylan","poet_slug":"hicabi-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kuyruklu-yildiz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buz dağı', 'buz-dagi-hicabi-ceylan-hqcyx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kar yağdı 

Sevgimizin üstüne

Belki bahanesiydi bu

Çekip gidişine

Fırtınalar dinmedi 

Gariban yüreğimde

Küreksiz sandal gibi

Kaldım denizlerde

Bu can ölmüştü

Çekip gittiğinde

Nefes almak için

Bekliyor dönüşünü

Papatyaları elinde', 'Kar yağdı  Sevgimizin üstüne Belki bahanesiydi bu Çekip gidişine Fırtınalar dinmedi  Gariban yüreğimde Küreksiz sandal gibi Kaldım denizlerd...', ARRAY['Türk Edebiyatı','Şiir','Hicabi Ceylan']::text[], 8.5, '{"poet":"Hicabi Ceylan","poet_slug":"hicabi-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/buz-dagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atillah Icli', 'atillah-icli-guner-kaymak-coxgh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gezelim görelim''in can sunucusu

Yaktin yüregimizi Atillah Içli

Kültürümüz sana minnettar,borçlu

Yerin doldurulamaz senin Atillah Içli

Örfümüzü adetimizi bize tanittin

Yillarca dolasmadik köy birakmadin

Dügünler''de bulundun halaylar''da oynadin

Yerin doldurulamaz  senin Atillah Içli

Gülücükler eksilmezdi hiç yüzünden

Hiç bir ayrinti kaçmaz idi gözünden

Mütevazilik, dürüstlük vardi özünden

Yerin doldurulamaz senin Atillah Içli

Yanik sesinden çok türküler dinledik

Sayende kültürümüz''ün degerini ögrendik

Hayran olduk sana sevdik, imrendik

Yerin doldurulamaz senin Atillah Içli

O ne kibarlikti o ne güzel  zarafet 

Simdi yüregimizi sardi hararet

Güner Allah''tan sana diliyor rahmet

Yerin doldurulamaz senin Atillah Içli

Amsterdam / 30.01.2004', 'Gezelim görelim''in can sunucusu Yaktin yüregimizi Atillah Içli Kültürümüz sana minnettar,borçlu Yerin doldurulamaz senin Atillah Içli Örfümü...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/atillah-icli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör Nokta', 'kor-nokta-kayip-golge-75d8f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yollar tıkandı önümde

Ahhhh ayak izlerim; 

önümdeki çiçek tarhlarının orağı

ışıkla bastım sanmıştım

her yan kan, her yan ateş

parmaklarım acıya değdi

acı içime aktı

yumaşacık okşadım sanmıştım

ellerim şehvetin çarmıhında asılı kaldı

sesim; neşeli bi çocuk ıslığı olacak demiştim

masum oyunuma katılsın diye diğerleri

feryatlar parçaladı benliğimi

kalbim renklerini sürdü sonsuza

süzüldüm; beyaz oldum

sussssssssss dedim sesime

kıpırdanışlar bitti

sustum

bekleyeceğim  kondüktörün tiz sesini

biletimi kesinceye dek 

hadi diyecek

ve kalkıp ineceğim yaşam treninden

çok yok', 'yollar tıkandı önümde Ahhhh ayak izlerim;  önümdeki çiçek tarhlarının orağı ışıkla bastım sanmıştım her yan kan, her yan ateş parmaklarım ac...', ARRAY['Türk Edebiyatı','Şiir','Kayıp Gölge']::text[], 8.5, '{"poet":"Kayıp Gölge","poet_slug":"kayip-golge","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kor-nokta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiddetsiz Sitem', 'hiddetsiz-sitem-oguzkan-bolukbasi-mrhrf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bırak dökülsün kadehlerden

zehir zıkkım içtiğimiz bade

yaşlar süzülsün gözlerden

çiçekler solsun o güzel bahçede

canan nerede

can nerede

ufuklar ulaşılmaz değil

görünmez oldu

kala kaldık bir yerlerde

sisler içinde

uzatınca tutacağımız eller nerede

sesimize cevap verecek sesler nerede

canan nerede

can nerede', 'bırak dökülsün kadehlerden zehir zıkkım içtiğimiz bade yaşlar süzülsün gözlerden çiçekler solsun o güzel bahçede canan nerede can nerede ufu...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hiddetsiz-sitem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çukur', 'cukur-orhun-basat-56v6h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sen; 

yüreğime doğan yeni gün, 

soframda bembeyaz örtü, 

kadehim... 

baktıkça okyanus gözlerine, 

ritminde eridiğim. 

içimdeki, sev diyen dürtü.. 

sen; 

yatağimda en çılgın kadın, 

sarılıp çoğaldığım. 

sağıldığım.. 

göbeğinde durur, 

senin yokluğunda, 

içine gömüldüğüm çukur....', 'sen;  yüreğime doğan yeni gün,  soframda bembeyaz örtü,  kadehim...  baktıkça okyanus gözlerine,  ritminde eridiğim.  içimdeki, sev diyen dü...', ARRAY['Türk Edebiyatı','Şiir','Orhun Basat']::text[], 8.5, '{"poet":"Orhun Basat","poet_slug":"orhun-basat","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/cukur-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostluğa Davet*', 'dostluga-davet-bayram-tunca-sunao', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hey ademoğlu dost eyledim gelsene 

Bak gönül postumu serdim otursana 

Otur Allah aşkına dertleşelim seninle 

Misafirim ol, kabulümsün her şeyinle 

30.01.2004-13.30', 'Hey ademoğlu dost eyledim gelsene  Bak gönül postumu serdim otursana  Otur Allah aşkına dertleşelim seninle  Misafirim ol, kabulümsün her şe...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dostluga-davet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Halini Sevdim', 'her-halini-sevdim-i-brahim-ethem-bingul-bog2b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gençliğim, dizleri üzerine çökmüş

Sana olan bilinmez bitmez sevgimi

Kimi zaman anladın,

Kimi zaman anlamadın

Ben senin en olumsuz,

Ben senin en duyarsız,

Hatta anlamazlıktan gelen

Halini bile sevdim', 'Gençliğim, dizleri üzerine çökmüş Sana olan bilinmez bitmez sevgimi Kimi zaman anladın, Kimi zaman anlamadın Ben senin en olumsuz, Ben senin...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/her-halini-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sağ Sütunda Mavi,Bembeyaz Eller ve Utanma', 'sag-sutunda-mavi-bembeyaz-eller-ve-utanma-enes-onal-p0m8h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zaman akrebin yavaşlığı kadar hızlı akıyor,

Ve bir an en fazla bir kere yaşanıyor.

Görülmez derine izler bırakıyor,

Define gibi paha biçilmedem yaşlanıyor.

Bir resim; herhangi olmayan bir zamanda,

Fırça ve mavi yok çizilemeyecek bir daha.

Bembeyaz eller; herhangi olmayan mekanda,

Kirlendi sonra,kara çalacak sabaha.

Günaha deymek bir sevap arefesinde,

Şeytanda görmek cennetin en güzelini.

Utanmanın maviyle süslenmiş kafesinde,

Bulmak bir kalabalığın özelini.

İnceldiği yerden kopmuyor anı,

Zaman celladının günleri altında.

Sıçrıyor geceler üstüne kanı,

Yitirilmişliğin en İmdat katında.

Bıçak ucu kadar keskin sevda,

Tam soğumuşken keser elini.

Bıraksan okşamayı bir darda,

Pas tutar,doğrultamaz belini.

Sağ sütunun durması kimin umrunda,

Mavi soldu,eller kirlendi ve yüzler arsız.

Parçalandı bu resim daha ilk vurgunda,

Geriye kalan sağ sütun; o da yarsız...', 'Zaman akrebin yavaşlığı kadar hızlı akıyor, Ve bir an en fazla bir kere yaşanıyor. Görülmez derine izler bırakıyor, Define gibi paha biçilme...', ARRAY['Türk Edebiyatı','Şiir','Enes Önal']::text[], 8.5, '{"poet":"Enes Önal","poet_slug":"enes-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sag-sutunda-mavi-bembeyaz-eller-ve-utanma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk-ı Müebbet', 'ask-i-muebbet-enes-onal-bokdo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerinin yeni doğmuş çocuğa bakıyor hali

Ve o gözlerde yolumu kaybetme ihtimali

Kaçırıyor uykularımı geceler boyu

Geceler ölümüne sessiz,geceler koyu

Yok sana anlatabileceğim güzel bir rüya

Hatırladığım teninin coğrafyasında birsürü hülya

Kendimi hayal uçurumundan aşağı bırakıyorum

Tam toprağına kavuşacakken nehrine akıyorum

İdamlığın son isteğidir elinden şerbet

Ama bilir son ölüm değil Aşk-ı Müebbet

Ellerin karıncanın güneşe bakması kadar imkansız

Anlatamıyorum gemilerime bu umut okyanusu limansız

Yağmur yağıyor içime yağıyormuş gibi

Bilmiyor bir kibrit değil bunun sebebi

Yağmur yağıyor yürüyorum bir yukarı bir aşağı

Ama tarif edemiyor gözlerim bir gökkuşağı

Güzelliğin sadece aynalarda kalsın

Sen öpülmeyecek yani bitimsiz masalsın

Seni unutmak da ölüm gibi karanlık 

Seni unutmak da ölüm gibi bir anlık

Her mısrada yüzlerce ANNA deviriyorum

Sen çıkacaksın diye sayfaları usulca çeviriyorum

Züleyha''yı seni düşünerek okuyorum

Seni ölene kadar sevmekten çok korkuyorum...', 'Gözlerinin yeni doğmuş çocuğa bakıyor hali Ve o gözlerde yolumu kaybetme ihtimali Kaçırıyor uykularımı geceler boyu Geceler ölümüne sessiz,g...', ARRAY['Türk Edebiyatı','Şiir','Enes Önal']::text[], 8.5, '{"poet":"Enes Önal","poet_slug":"enes-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ask-i-muebbet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Aşka Dair...', 'aska-dair-naime-erlacin-1vjf4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'tersyüz olduğun

çarptığın kapılarda arama kendini

şafaklara sökülen kapılardan sor

onlar ki 

ansızın gelen konuklar gibi 

aşkın masumiyetine vesile idiler

ıtırlı bir sarmaşıkça sarıp ruhunu

ne düne seni

ne bugüne

zamanın ötesine götürdüler 

ele geçmez bir şeydi aşk

her figüran 

son perdeyi oynayan 

yiğit oyuncu 

köleler sahnesinde çatıldı yazgı 

ölçüsü yok acının

aşka müebbet verdiler 

ayazda bir yürek 

masumiyetin omuz başında 

inler yaralı kuş misali

girdabın insanı yuttuğu yerde 

her gül dikenli

her yer çileli gül bahçesi 

onmasa her vurgunda

ondurmasa da 

aşk 

yine aşk

biraz fırtına 

biraz rüzgâr gerek 

insan ruhuna

yelkeni rüzgâr almayanın aşkı da olmaz 

(*)      Bayramınız mutlu; rüzgârınız bol olsun dostlar.     

(31 Ocak 2004)', 'tersyüz olduğun çarptığın kapılarda arama kendini şafaklara sökülen kapılardan sor onlar ki  ansızın gelen konuklar gibi  aşkın masumiyetine...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/aska-dair-117-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esma Abla', 'esma-abla-enes-onal-cpf5m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Esma abla 

Sevdaya dair ne biliyorsan yalanmış,

Hakikatler ince bir gamzede kalmış,

Nesneler kahpece ikiyüzlü çıkarmış,

Ama dediğin gibi değil; 

İkinci yüzler hep aynıymış.

Mutluluk sadece malum anlarda varmış,

Gerisi siyah-beyaz,gerisi azapmış,

Sol taraf bin batman yük yaparmış,

Abla yanlış biliyorsun; 

Gözler kurur,yürek kanarmış.

Şah damarı onun kalbine akarmış,

İrade yukarı değil aşağı bakarmış,

İnsanı kırmızı değil siyah yakarmış,

Sen anlatmıştın bana ama; 

Mecnunu O değil,o mecnun yaparmış...', 'Esma abla  Sevdaya dair ne biliyorsan yalanmış, Hakikatler ince bir gamzede kalmış, Nesneler kahpece ikiyüzlü çıkarmış, Ama dediğin gibi değ...', ARRAY['Türk Edebiyatı','Şiir','Enes Önal']::text[], 8.5, '{"poet":"Enes Önal","poet_slug":"enes-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/esma-abla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-abdusselam-bugur-qve3g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevmek, 

Özlemek, 

Beklemek var aslında 

Ayrılık diye bir şey yoktur 

Sevgili. 

………… 

Özlemle beklemek, 

Yaşarken beklemek, 

Yaşayıp beklerken ölmek var aslında 

Ayrılık dediğimiz koca bir yalan. 

Esen rüzgarlara seni sormak, 

Yağmurlarla birlikte ağlamak varmış 

Sevgili. 

………… 

Sevmedim kimseyi seni sevdiğim kadar

İnanmadım hiç kimseye sana inandığım kadar. 

Hep bir gün dönmeyeceğin korkusu 

kahrediyor beni 

kaderde sensizlikte varmış 

haberim yokmuş 

Sevgili. 

………… 

Ne sen bu kadar sevilmeliydin 

Ne de benim bu kadar sevmeye 

Hakkım vardı! 

Sensizliğin kollarında şimdi! 

Seni soruyorum 

gecelerime,

Seni dokuyorum 

şiirlerime 

Hasret saat''inin dakikaları 

Tüketiyor ömrümü nerdesin sen? 

………… 

Açılan her kapının ardında 

Seni gözlemek, 

Çalan şarkılarda sesini duymak, 

Şiirlerde, kitaplarda seni aramak varmış 

Sevgilim...', 'Sevmek,  Özlemek,  Beklemek var aslında  Ayrılık diye bir şey yoktur  Sevgili.  …………  Özlemle beklemek,  Yaşarken beklemek,  Yaşayıp beklerk...', ARRAY['Türk Edebiyatı','Şiir','Abdüsselam Bügür']::text[], 8.5, '{"poet":"Abdüsselam Bügür","poet_slug":"abdusselam-bugur","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/ayrilik-140-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Servetim', 'tek-servetim-hifzi-ozbekmez-6dhm7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgilim çok mutluyum 

Çünkü sana aşığım

Çok üzgünüm 

Çünkü sana hasretim

Çok üzgünüm

Çünkü var gurbetim

Çok ama çok mutluyum 

Çünkü aşkın benim tek servetim

2003', 'Sevgilim çok mutluyum  Çünkü sana aşığım Çok üzgünüm  Çünkü sana hasretim Çok üzgünüm Çünkü var gurbetim Çok ama çok mutluyum  Çünkü aşkın b...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/tek-servetim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Arife', 'bugun-arife-bayram-tunca-gwn9g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bak, bugün günlerden arife

Dualarımız, en güzel hulufe

Dua edelim, bütün ümmete

Belki şefaat ederler bizlere

B. Tunca/31.01.2004-13.31', 'Bak, bugün günlerden arife Dualarımız, en güzel hulufe Dua edelim, bütün ümmete Belki şefaat ederler bizlere B. Tunca/31.01.2004-13.31...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bugun-arife-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sordular', 'seni-sordular-hifzi-ozbekmez-se0af', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerinden yaşı dökende omu

Kalbini yerinden sökende omu

Gönlüne aşkıyla akanda omu

Seni sordular hep yok diyemedim

Seninde sevdiğin var mı dediler

Onsuz sana dünya dar mı  dediler

Kalbini çalan o yar mı dediler

Seni sordular hep yok diyemedim

Hıfzı demek sende aşık olmuşsun

Hasretiyle sararıp ta solmuşsun

Onun gözlerinden ilham almışsın

Seni sordular hep yok diyemedim', 'Gözlerinden yaşı dökende omu Kalbini yerinden sökende omu Gönlüne aşkıyla akanda omu Seni sordular hep yok diyemedim Seninde sevdiğin var mı...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-sordular-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömür Kattın', 'omur-kattin-hifzi-ozbekmez-o006r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İyi ki sen varsın benim gönlümde

Nasıl yaşardım ben sensiz ömrümce

Bahtım açılıyor sen bir gülünce

Sen ömrüme ömür kattın sevdiğim

Hayalin gözümden bir an gitmiyor

Sensiz hayat beni mutlu etmiyor

Sevgin bir hazine gülüm bitmiyor

Sen ömrüme ömür kattın sevdiğim

Sen gönlüme girdin şansım açıldı

Aşk şarabı yar elinden içildi

Gönlümde güllerim açtı saçıldı

Sen ömrüme ömür kattın sevdiğim

Latifiyim artık aşığım sana

Biliyorum sende vurgunsun bana

Umudumsun artık benim dünyada

Sen ömrüme ömür kattın sevdiğim

2003', 'İyi ki sen varsın benim gönlümde Nasıl yaşardım ben sensiz ömrümce Bahtım açılıyor sen bir gülünce Sen ömrüme ömür kattın sevdiğim Hayalin g...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/omur-kattin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güllerin Dünyası', 'gullerin-dunyasi-i-brahim-ethem-bingul-50lj8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Burası güllerin dünyası

Burada gül yenilir,

Gül içilir,

Gül konuşulur,

Gül giyilir..

Gül sevgidir,

Gül güzelliktir,

Gül doyulmazlıktır,

Gül aşktır..

Güllerin dünyasında; 

Bağışlanmak vardır,

Merhamet vardır,

Hasret vardır,

Vuslat vardır..

şevkat dünyasıdır bu dünya

Sevilir dost yinede,sırtından vursada

Sıvazlanır omzu,yeterki gururu kalkmasın ayağa..

Sevilirsin,sevdikçe

Bağlanırsın,bağlandıkça

Kabul edilirsin,kabullendikçe..

Sevilmek tek arzun olur

Yaşamın hayat bulur

Gül kokusundan birazda sana bulaşsın istiyorsan

Hoşgeldin gül dünyasına,geç şöyle buyur..', 'Burası güllerin dünyası Burada gül yenilir, Gül içilir, Gül konuşulur, Gül giyilir.. Gül sevgidir, Gül güzelliktir, Gül doyulmazlıktır, Gül ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gullerin-dunyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emanetsin...', 'emanetsin-i-brahim-ethem-bingul-j6ebd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüreğime demir attın

Derinlere saplanıp,kök saldın..

Duygularımı yeşertip,canlandırdın

Sevginin nasıl olduğunu anlattın

Olmaz dediğim oldu

Yürek sevdi,bağlandı

Hislerim renklendi,şekil aldı

Hayatım anlam kazandı

Sıcacık sevgin

Huzur veren ellerin

Işıl ışıl parlayan gözlerin

şükürler olsun YaRab ben daha ne isterim

Kokun ellerimden gitmesin

Kötülükler bize gelmesin

Yaradan bu güzelliği bölmesin

Ölürsem,sevdiklerime emanetsin..', 'Yüreğime demir attın Derinlere saplanıp,kök saldın.. Duygularımı yeşertip,canlandırdın Sevginin nasıl olduğunu anlattın Olmaz dediğim oldu Y...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/emanetsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahipsiz Benliğim', 'sahipsiz-benligim-sirma-mersin-eqfub', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ayrılığa  düşen düşlerimizden; başka...

Sensizliğe alışamamış özlemden; 

Susmayan bir yürekten, başka...

Başka başka umutların peşine giden; 

Sahte sevmelerin  aldanışı ile,

Yalan dünyanın içinde,

Yaşamaya çalışmak zorunda olan benliğim...

Acı tatlı anılarla çoğalan; bekleyişle 

Zamanı geçirmek,

Her defasında; kaybolan mutluluğu bulmadan,

Hüzün şehrine doğru yol almak zorunda kalırım,

Sahipsiz benliğimle...

27.01.04', 'Ayrılığa  düşen düşlerimizden; başka... Sensizliğe alışamamış özlemden;  Susmayan bir yürekten, başka... Başka başka umutların peşine giden;...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sahipsiz-benligim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamın CV''si', 'yasamin-cv-si-sirma-mersin-yraau', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Adı: Kader

Soyadı: Tesadüf

Adresi: Sevgi çıkmazı Sk. Hüzün ap. N.3  Acı / Mutsuzluk

Medeni Hali: Şans

Doğduğu Yer: Kalp

Doğum Tarihi: Hazanın 10''nu - sene bilmem kaç? 

Uyruğu: Yalnızlıklar Cumhuriyeti

Baba Adı: Umut

Anne Adı: Sevinç

Tahsil Durumu: Hayal dünyası okulundan birincilikle mezun.

Hobileri: Yürekten sevmek, çaresizliğe mahkum olmak, yalan yanlış sahte sözlere aldanmak, gözyaşlarını boşa akıtmak...

Gelecekten Beklentisi: Değerini anlayacak birinle, ömrünü geçirmek...

Yoğun duyguların esiri olacak, mutluluğu bulmak...

30.01.04', 'Adı: Kader Soyadı: Tesadüf Adresi: Sevgi çıkmazı Sk. Hüzün ap. N.3  Acı / Mutsuzluk Medeni Hali: Şans Doğduğu Yer: Kalp Doğum Tarihi: Hazanı...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yasamin-cv-si-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsim', 'mevsim-huseyin-cayikli-v2rl6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'böyle ilkbahar yağmuru gibi elime düşmemeliydin.ben sonbahardaydım.yeşilenmeden kurumuştu yapraklarım.surgün gibi bir mevsimdi.böyle gelmemeliydin.adına yakışan bütün güzellikleri hayatımda soyutlamalıydım oysa hep somut anlamında kaldılar.sebepsiz  suratımın arkasında biraz iyimser biraz kemiren biraz dalgalı adam oturuyor oysa.böyle ilkbahar zamanı gibi geldin oysa kıştı mevsim.şimdi yokluğun bir ocak ayının soz zamanlarında esiyor.havaya bakıyorum biraz bulutlu yaşama dair sana bir yağmur ben akıyorum.', 'böyle ilkbahar yağmuru gibi elime düşmemeliydin.ben sonbahardaydım.yeşilenmeden kurumuştu yapraklarım.surgün gibi bir mevsimdi.böyle gelmeme...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/mevsim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günaydın Dünya', 'gunaydin-dunya-huseyin-cayikli-26j9t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'dünya cocukların''a

gunaydın dunya

yanımda oturan sakat bir cocugun günlüğünden yazıyorum.

beni beraberinde götür dünya

savaşların ağır bedelleriyle ödendiği günlük yaşantımızda 

bir nefes alabilmek için bana borç ver dünya.

sıkıldığım ajans haberlerinin ortasında kaldım 

beni kurtar dünya

sana bütün aşkların ve güzelliklerin adına sesleniyorum

Günaydın dünya.

insanların sustuğu içine attıları öfkeyle şiddetiyle sana seslemiyorum

güzelliklerin ve nan''ın aşkına.

sevdaya satılmış bütün kelimelerimin 

tozlu raftalarda ki kitaplarımın.

gece boyu düşündüğüm baş ağrılı nöbetlerimin arasından sesleniyorum sana

beni dinle dünya.

sana sakat bir çocuğun günlüğünden diyorum bunları

Günaydın dünya.', 'dünya cocukların''a gunaydın dunya yanımda oturan sakat bir cocugun günlüğünden yazıyorum. beni beraberinde götür dünya savaşların ağır bedel...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gunaydin-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Geldim Bak', 'ben-geldim-bak-oguzkan-bolukbasi-5f6gw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ben geldim

dün eldim

bugün sevgili

yarın hatıra

bakınca yaşananlara

bir devri daim

bir kısır döngü

durmaksızın bir tekrar

ama nedense insan

kendininkini

biricik

ve tek sanar

laf aramızda

öyle sanmasında yarar var

yoksa bu kadar şiiri kim yazar', 'ben geldim dün eldim bugün sevgili yarın hatıra bakınca yaşananlara bir devri daim bir kısır döngü durmaksızın bir tekrar ama nedense insan ...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ben-geldim-bak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşil SU...', 'yesil-su-i-brahim-ethem-bingul-whsc2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'O yeşil gözlerin

O yosun renkli gözlerin

Huzurun ta kendisi

O muhteşem yüreğin

Karşılıksız seven

Karşılık beklemeyen

Sevdiğini söyleyen

Yalnız beni düşünen

Bende seni seviyorum

Kalbindeki sıcacık yerde kalacağım

Her zaman bir tanem', 'O yeşil gözlerin O yosun renkli gözlerin Huzurun ta kendisi O muhteşem yüreğin Karşılıksız seven Karşılık beklemeyen Sevdiğini söyleyen Yaln...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yesil-su-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram da Küçük Kıza Büyüme Hayalleri şiiri', 'bayram-da-kucuk-kiza-buyume-hayalleri-siiri-nevin-kalafatoglu-ayx26', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'küçük bir kızım ben 

şiir satırlarında seksek oynayan

hoplayan zıplayan

bebeklerini kaybettiği için ağlamayan

küçük bir kızım ben 

içimde  gözyaşlarını inci  yapar

biriktiririm ben

bir papatya bir inci dizerim satırlarıma

billur tanelerinden

küçücük bir kızım ben

dökülür sayfalara inciler

birini bulur şiirler

taç giydirirdim papatyalardan

Küçücük bir kızım ben kalemi olmayan

ıslansın içimdeki duygular aşklar şiirler

yalnız ve küçük bir kızım ben hoş görülen

ama ayağıma  dökülecek bir gün orkideler..

papatyalar şebnem izleri sanki minik bilezikler

küçük bir kızım ben öylesine 

hayal vadilerinde

bebeklerini kaybettiğinde bile inci üreten

kocaman yürekli

küçücük kızım ben..

kadın gibi görünen 

hiç büyüyemeyen

31.01.2004', 'küçük bir kızım ben  şiir satırlarında seksek oynayan hoplayan zıplayan bebeklerini kaybettiği için ağlamayan küçük bir kızım ben  içimde  g...', ARRAY['Türk Edebiyatı','Şiir','Nevin Kalafatoğlu']::text[], 8.5, '{"poet":"Nevin Kalafatoğlu","poet_slug":"nevin-kalafatoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bayram-da-kucuk-kiza-buyume-hayalleri-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kibrit Çaktım Geceye', 'bir-kibrit-caktim-geceye-cigdem-bir-genc-28bo5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Alazlanmış gece 

Yıldızlarla örülü gökyüzü telaşta

Gözlerin bu gece alabildiğine kuzguni

Gökyüzü yangın yeri

Oysa bir kibrit çakmıştım sadece geceye

Karanlıkta buluşturmak için gözlerimi gözlerinle...', 'Alazlanmış gece  Yıldızlarla örülü gökyüzü telaşta Gözlerin bu gece alabildiğine kuzguni Gökyüzü yangın yeri Oysa bir kibrit çakmıştım sadec...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Bir Genç']::text[], 8.5, '{"poet":"Çiğdem Bir Genç","poet_slug":"cigdem-bir-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bir-kibrit-caktim-geceye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çekil! Çekil dedim!', 'cekil-cekil-dedim-nazife-abayli-ll3an', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bitmek üzere mi? 

Yürüdüğüm merdivenler.

Ölüm şimdi şuracığımda! 

Hemen dibimde! 

Sıkıştırıyor,

Bastırıyor beni.

Ama boşuna! 

Yanaşma daha fazla,

Çekil! 

Soluğumu dinliyor,

Kalp atışlarımı sayıyorsun.

Nedir çalmak istediğin? 

Sıcak eller uzat bana,

Kucak dolusu sevgiler uzat.

Yarım kaldı dünlerim,

Yarım kaldı güzelliklerim,

Henüz çok gencim.

Sen olmadan yaşamasını bilirim.

Çekil! Çekil dedim!', 'Bitmek üzere mi?  Yürüdüğüm merdivenler. Ölüm şimdi şuracığımda!  Hemen dibimde!  Sıkıştırıyor, Bastırıyor beni. Ama boşuna!  Yanaşma daha f...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/cekil-cekil-dedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece sevdim ben....! ! !', 'sadece-sevdim-ben-nazife-abayli-71vn1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bütün dünlerle,

Bugünler arasından,

Bezgin geçtim çoğu zaman.

Burnumu tıkayarak.

Kötü kötü kokan,

Kıskançlıkları,

Düşmanlıkları,

Nefretleri,

Tiksintileri koklamadım.

Sağır oldum duymadım,

Dilsiz oldum konuşmadım.

Kör oldum,

Değneğimle sürünerek,

Bezgin geçtim çoğu zaman.

Güçlükle,

Ve de...

Sakınarak,

Tek tek bastım merdivenlere.

Sırtımı döndüm,

Ahlaksızca hükmedenlere.

İki gözümle değil,

Yürek  gözümle gördüm..

Ve....

Sadece sevdim ben....! ! !', 'Bütün dünlerle, Bugünler arasından, Bezgin geçtim çoğu zaman. Burnumu tıkayarak. Kötü kötü kokan, Kıskançlıkları, Düşmanlıkları, Nefretleri,...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sadece-sevdim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey yalnızlık!', 'ey-yalnizlik-nazife-abayli-3cpbs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey yalnızlık! 

Vatanım benim,

Yalnızlık! 

Ne tatlı seslenir,

Sesin bana.

Yaban ellerde,

Öylesine uzun süre,

Yaban gibi yaşadım ki,

Sana gözyaşlarıyla,

Dönmemek elde değil!', 'Ey yalnızlık!  Vatanım benim, Yalnızlık!  Ne tatlı seslenir, Sesin bana. Yaban ellerde, Öylesine uzun süre, Yaban gibi yaşadım ki, Sana gözy...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ey-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Genç bir Ruh''a', 'genc-bir-ruh-a-orkan-sanci-0bo7w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen ağladın o gece

Hıçkırarak, başına gelenlere 

Yaşadıklarına lanet ettin

ve haksız yalnızlığına

Sen haykırdın o gece

Pencereyi açıp tüm kente

Ama soğuk ve bencil karanlıkta

Seni kimse duymadı

Sen üşüdün o gece

Tenin soğuktu, kalbin yaralı

Sonra bir damla yaş aktı gözünden

Yorgunca, derinden, dalgalı

Sen öldün o gece

Ruhun buluştu meleklerle

O gece sen öldün

Ben ağladım

(Ankara 2004 Ocak)', 'Sen ağladın o gece Hıçkırarak, başına gelenlere  Yaşadıklarına lanet ettin ve haksız yalnızlığına Sen haykırdın o gece Pencereyi açıp tüm ke...', ARRAY['Türk Edebiyatı','Şiir','Orkan Şancı']::text[], 8.5, '{"poet":"Orkan Şancı","poet_slug":"orkan-sanci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/genc-bir-ruh-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kirvem', 'kirvem-abdullah-garip-qjem9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kirvem

Garibem Abdullah garibem

Yollar ırak ki yanına gelem

Şair olduğunu nereden bilem

Antoloji de gezerim artık kirvem

Okudum okudum Eskişehirli

Annem şiirleri çok sihirli

Yediyüz yiğirmiye ulaşmış ufaklı irili

Şirlerinde gezerim artık kirvem

Ahlar çekiyor, aşklar çekiyor

Derinden derinden vahlar çekiyor

Güzeller içinde Eskişehir’i seçiyor

Tebrikler sana olsun kirvem

Abdullah Garip 31.01.2004', 'Kirvem Garibem Abdullah garibem Yollar ırak ki yanına gelem Şair olduğunu nereden bilem Antoloji de gezerim artık kirvem Okudum okudum Eskiş...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kirvem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Süzülüp Gelen', 'suzulup-gelen-yasar-pullu-pu3i5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ağıtlarla doğmuşuz anamızdan

_______________tarlalarda

başak sarısında huzur bulmuşuz

höllük elemiş sarmışlar bizi

tenimizin toprağa benzemesi ondan.

Zemheride sıtma tutmuş

Ağustosta yanmışız en olmaz yerimizden

onun için

hiç bir delhiz soğutmaz bizi.

Yazmışlar taa içimize

silinmez bir yazgı bu

bu namustur, bu yiğitlik

bacı gardaş, ana baba

bu da ser diye

boyun eğmişiz.

Hepsi için önce serden geçmeyi yazmışlar

önce bunu bilmişiz

coğrafyamız gibi kazınmış yüzümüze

tenimiz kadar yakın ve yanık.

Zaman olmuş

inceden ince fikrimizle süzmüşüz

delolmuşuz

nedir gerçek diye

bazı akıl almamış bazı yürek

kanayıp durmuşuz

ömrümüz özümüze

özümüz ömrümüze çelişki olmuş

demem o ki bu sepepten

yani bundan

kan yaş olup

her tan yeri

can yerimizden akmışız..', 'Ağıtlarla doğmuşuz anamızdan _______________tarlalarda başak sarısında huzur bulmuşuz höllük elemiş sarmışlar bizi tenimizin toprağa benzeme...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Püllü']::text[], 8.5, '{"poet":"Yaşar Püllü","poet_slug":"yasar-pullu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/suzulup-gelen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaresiz Gözlerin', 'caresiz-gozlerin-gurbuz-vural-lxxzl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Saklasan beni,

-bir suçlu gibi- gözlerine.

Sığınsam kaybolsam bir süre.

Yoksulluktan,açlıktan,savaştan...

Her ağladığında,

tuzlu bir anlam ifade etsem,

dudaklarında...

Bir mülteci gibi,

sığınsam -çaresiz -gözlerine...

Gözlerinde yardım ve yataklık suçu

işlesen benim için...

Yusuf Güler', 'Saklasan beni, -bir suçlu gibi- gözlerine. Sığınsam kaybolsam bir süre. Yoksulluktan,açlıktan,savaştan... Her ağladığında, tuzlu bir anlam i...', ARRAY['Türk Edebiyatı','Şiir','Gürbüz Vural']::text[], 8.5, '{"poet":"Gürbüz Vural","poet_slug":"gurbuz-vural","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/caresiz-gozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerde hata yaptık? ..', 'nerde-hata-yaptik-ferit-teksoy-wojdq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nerde hata yaptık? ..neden böyleyiz? 

Bu kin,şiddet niye? ..anlayamadım 

Ormanlar yanıyor seyrediyoruz

Denizler kokuyor aldırmıyoruz

Dağlarda ceylanlar gezmiyor artık

Denizde balıklar yüzmüyor artık

Kuş neslinin yarısını yok ettik

Körfezlerin tamamını b.. ettik

Kıyılarda çöpten dağlar oluştu

Piknik yerlerimiz pisten kokuştu

Balığı bitirdik çöp avlıyoruz

Hem yok ediyor hem ağlıyoruz

Düğün ve maçlarda korna sesinden

Bebekler ağlıyor beşiklerinden

Otobüste dede,nine ayakta

Delikanlı oturuyor koltukta

Böyle olur haklıya aptal derseniz

Hakkı yerer,haksızı överseniz

Torpil bul öne geç marifet

Hakkına razıysan geriden seyret

Kazan da sonuçta ağada sen,paşa da

Çal istersen önemsiz,kral gibi yaşa da

Büyük batağa girmiş böyle pislik kokarsa

Küçük de öyle olur o örneğe bakarsa

Bütün bunlara sebep biz sevgiyi yitirdik

Sevgiyi yitirince saygıyı da bitirdik

Kendi ellerimizle bir canavar yarattık

Nasıl yeneceğiz onu bilemiyoruz artık

Yeniden kazanmakta anahtar sözcük''''sevgi''''

İnsana,hayvana,doğaya sevgi

Bakışlara sevgi..dillere sevgi

Tek anahtar sevgi..tek çözüm sevgi', 'Nerde hata yaptık? ..neden böyleyiz?  Bu kin,şiddet niye? ..anlayamadım  Ormanlar yanıyor seyrediyoruz Denizler kokuyor aldırmıyoruz Dağlard...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/nerde-hata-yaptik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'El', 'el-huseyin-cayikli-jhpnu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sevilmekten usanan kadın sigarasını yakmıştı

bir tiyatro sahnesinde iki oyuncu yapay gülücükleriyle

ümitasyon bir aşk oyunu oyuıyorlardı.

söylenen yalanlar kadına aitti.

yalanları kadın ayakustu bir şehirin gezmelerinden çalmıştı.

sana diyecek son söz

ben sana bir yazı yazsam

kadın aklıma gelir ben biraz daha tükenirim.

öyle el gibi durma

elim zaten senin aşkını taşıyan kalbinin nasırıyla kaplı.', 'sevilmekten usanan kadın sigarasını yakmıştı bir tiyatro sahnesinde iki oyuncu yapay gülücükleriyle ümitasyon bir aşk oyunu oyuıyorlardı. sö...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/el-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Bayram', 'her-bayram-zeki-ergin-648zg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sevinesim geliyor her bayram

çığlık çığlığa salıncaklarda

bayramlıklarımla yatmak istiyorum

ayıplamayın dostlar

ben her bayram çocukluğuma gidip

çocuklarla çocuk olmak istiyorum

özlemim büyür her bayram

arar dururum onları

anam babam ve diğerleri

o günlere gidip 

ellerini öpmek istiyorum

_erenköy 31oca''04', 'sevinesim geliyor her bayram çığlık çığlığa salıncaklarda bayramlıklarımla yatmak istiyorum ayıplamayın dostlar ben her bayram çocukluğuma g...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/her-bayram-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varlığım Yokluğum Gibi', 'varligim-yoklugum-gibi-erkin-gedik-0omq4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Umut etmek güzeldi

Hatta umutsuzca sevmek

Unuttum şimdi

Kolay olmadı

Bende kovaladım hayatı

Özledim

Bir an sarılır gibi oldum

Koptum birden

Yıkıldım dedim

Ayaktaydım

Tutmuyordu oysa dizlerim

Taşımaz gibiydi artık

Öylesine ordaydım

Varlığım yokluğum gibiydi

Hiç olmamışmıydım

Bitiyormuydum yoksa

Kaçtım kurtuldum

Yani bir gün daha

Yarın yine benimleydi hüzün

Yanından geçtim hayatın

O da benim yakınımdan

Görmedi

Tanımadı belki

Varlığım yokluğum gibiydi

Hayır üzgün değildim

Ne de pişman

Kaybettiğim birşey yoktu

Kazandığım hiç birşey

Sonsuz bir farkındalık

Ya da sonsuz bir yalnızlık mı demeli

Ne farkeder

Sonundaydım işte hayatın

Kimseler yoktu benden başka

Varlığım yokluğum gibiydi

Hiç olmamışmıydım

Tükeniyormuydu umutlar yoksa

                                                13-08-2001 / Zonguldak', 'Umut etmek güzeldi Hatta umutsuzca sevmek Unuttum şimdi Kolay olmadı Bende kovaladım hayatı Özledim Bir an sarılır gibi oldum Koptum birden ...', ARRAY['Türk Edebiyatı','Şiir','Erkin Gedik']::text[], 8.5, '{"poet":"Erkin Gedik","poet_slug":"erkin-gedik","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/varligim-yoklugum-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruh Kovalamacası', 'ruh-kovalamacasi-osman-velioglu-8scc7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sensizliğin boyut boyut hiçliği 

Kavramlara beni mahkum etmişti 

Düşüncenin senden gelen açlığı... 

Gitmişti kadınım, ömür gitmişti, 

Yıllar öncesiydi son çağrım sana, 

Sen gel veya gelme, avaz bitmişti. 

Bir kara sevda - ki ağdadır cana- 

Koskoca hayatı sildi süpürdü. 

Bir yürek, bin hasret bıraktı bana. 

Günler çalkalandı, saat köpürdü, 

Boğuldu senliğim an arasında. 

Sadece seviler temizdi, pürdü. 

Kurtcuklar beslendi aşk yarasında 

Beynimi kemirdi her biri benim. 

Al canlar yetişti is karasında. 

Sünger gibi emdi geceyi tenim, 

Ben beni kaybettim binlerce bende. 

Evreni kapladı boyum ve enim. 

Ruhum peşisıra, hayalin önde, 

Yol aldı muttasıl, hiç tutamadım. 

Yokluğum bendeydi, varlığım sende. 

Bir kerecik olsun, unutamadım!', 'Sensizliğin boyut boyut hiçliği  Kavramlara beni mahkum etmişti  Düşüncenin senden gelen açlığı...  Gitmişti kadınım, ömür gitmişti,  Yıllar...', ARRAY['Türk Edebiyatı','Şiir','Osman Velioğlu']::text[], 8.5, '{"poet":"Osman Velioğlu","poet_slug":"osman-velioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ruh-kovalamacasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilinmez..', 'bilinmez-hasan-basri-kale-dxuvu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kalpten kalbe bir yol varmış dediler

Aşık olan anlar gerisi bilmez dediler

Ben de bileyim aşık olup dedim..güldüler

Allah vergisidir sonradan bilinmez dediler..', 'Kalpten kalbe bir yol varmış dediler Aşık olan anlar gerisi bilmez dediler Ben de bileyim aşık olup dedim..güldüler Allah vergisidir sonrada...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bilinmez-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hepsi Yalan...', 'hepsi-yalan-hasan-basri-kale-hkig6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşkmış,sevdaymış,yanmakmış,yakmakmış hepsi yalan

Özlemekmiş,istemekmiş,gelmekmiş hepsi yalan

Yıllardır döner durur,sorar dururum hangisi gerçek

Dönmekmiş,sormakmış,gerçekmiş hepsi yalan.', 'Aşkmış,sevdaymış,yanmakmış,yakmakmış hepsi yalan Özlemekmiş,istemekmiş,gelmekmiş hepsi yalan Yıllardır döner durur,sorar dururum hangisi ger...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hepsi-yalan-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğer...', 'eger-hasan-basri-kale-ccbuq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün gelip kapını çalabilseydim eğer

Gül yüzüne aşık olup coşabilseydim eğer

Seyrana çıkardı ruhum bir başka alemde

Senden gayrısını silip sadece sen olabilseydim eğer...', 'Bir gün gelip kapını çalabilseydim eğer Gül yüzüne aşık olup coşabilseydim eğer Seyrana çıkardı ruhum bir başka alemde Senden gayrısını sili...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/eger-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başlıksız Şiirler', 'basliksiz-siirler-gokhan-yazici-58w4i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şiirler yazdım dize dize

Başlıklarını koymadım.

Sen koy isimlerini

Sevgi koy,

Aşk koy,

Tebessüm koy,

Nefret koyma

Ayrılık koyma.

İçimi döktüm süze süze

Bomboş artık içim.

Rüzgar eser,sallar beni

Sen sallama...Sarsma

Vurma kalbime tekmeyi

Beni incitme.

Sen; yeni açmış çiçek

Kendine dikkat et

Ezmesinler seni.

Aklım hep sende,

Şu kalbim de senin olsun

İçimde beslediğim,

Tüm duygular senin olsun.

Atma duygularımı sokağa,

Saçıp savurma.

Harcama şu aşkımı

Beni harcama.', 'Şiirler yazdım dize dize Başlıklarını koymadım. Sen koy isimlerini Sevgi koy, Aşk koy, Tebessüm koy, Nefret koyma Ayrılık koyma. İçimi döktü...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Yazıcı']::text[], 8.5, '{"poet":"Gökhan Yazıcı","poet_slug":"gokhan-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/basliksiz-siirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram Ve Çocuk Kısacık', 'bayram-ve-cocuk-kisacik-oguzkan-bolukbasi-pxrvv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'işte bir bayram

''ben kaç bayram çocuktum''

elbiselerim başucumda yattım

ayakkabılarımı boyattım

şimdi ruhumda bir çocuk

zıp zıp zıplar

ama nedense

hiç öyle eskisi gibi değil bayramlar', 'işte bir bayram ''ben kaç bayram çocuktum'' elbiselerim başucumda yattım ayakkabılarımı boyattım şimdi ruhumda bir çocuk zıp zıp zıplar ama ne...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bayram-ve-cocuk-kisacik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel ki;', 'gel-ki-tabir-gokce-zdl7p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'şimdi

fütursuz dizelere 

yaslamışım başımı

gecenin sessizliğinde

sensizliğe susuyorum

gel ki

sukût''un kaç karat olduğunu

cümle aleme haykırayım', 'şimdi fütursuz dizelere  yaslamışım başımı gecenin sessizliğinde sensizliğe susuyorum gel ki sukût''un kaç karat olduğunu cümle aleme haykıra...', ARRAY['Türk Edebiyatı','Şiir','Tabir Gökçe']::text[], 8.5, '{"poet":"Tabir Gökçe","poet_slug":"tabir-gokce","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gel-ki-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '... Gibi bir sey', 'gibi-bir-sey-tabir-gokce-rkqkf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karanlık bir odaya kapanmak

Bakabilmek için güneşe

Ya da fenerle yaklaşmak

Aydınlığına çoban yıldızının

Baharı siyaha boyamak gibi bir şey

Nefret sandalında kürek çekmek

En yiğit sevgilerin deryasına

Ya da at gözlükleriyle bakmak yaşama

Yakalamak için mutluluğu

Kor alevlerde donmak gibi bir şey

Unutmak, yok etmek, silmek izlerini

Yaşanmış tükenmiş bile olsa aşkların

Ya da varlığına aldırmamak

Gel diyebilecek kadar özlediğin sevgilinin

“Güneşi balçıkla sıvamak” gibi bir şey', 'Karanlık bir odaya kapanmak Bakabilmek için güneşe Ya da fenerle yaklaşmak Aydınlığına çoban yıldızının Baharı siyaha boyamak gibi bir şey N...', ARRAY['Türk Edebiyatı','Şiir','Tabir Gökçe']::text[], 8.5, '{"poet":"Tabir Gökçe","poet_slug":"tabir-gokce","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gibi-bir-sey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşsizlik Notları', 'i-ssizlik-notlari-ahmet-aksoy-3axl2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'I

Bendeki teyakkuz hali

Aslında bir ruh göçü

Gözlerim uyanık görünsede

Bir ayrılık vakti

II

Parça başına öder, mutsuzluğunu acıların

Zaman üstüne kapanır, için daralırken

Oysa sen koca işsiz, zaten ilk kendin işlersin

Teyel yerlerini, kaderin sana biçtiği kıyafetin

IIII

Hayatı kendine bir yelken yap

İşsiz! Bekleki bir rüzgar essin

Belik o zaman, belki,

Gıdım dıdım ilerlersin

Ve mutsuz kaldırımlarda

Düştüğün yerden kalkıp

Bir kaç adım ilerlersin

Oysa delikli yelken

Ne kadar götürmez ki senden

Bunu, en iyi sen bilirsin! 

IV

Geçimsiz saatler bu saatler

İşte hayat gibi

Konsematris mutluluklar

Kimi zaman benim masamda

Kimi zaman başkasının masasında

Hep kalkık otururken

Hep gözü başka uzaklarda

Bense hep aynı sandalyede

Ne zamandır sönmüş balon gibi

Bir nefes yok ki

Şişeyim

Bir nefes yok ki göze girip

Sayılayım

Uçsuz ayıklanmışlığımda.

V

Sizlik, en çok şimdi koyuyor sana

Talimliydin yokluğa aslında

En çok şimdi kayıyor ellerin

En çok şimdi sendeliyorsun

En çok şimdi yalnızsın

Sizlik, en çok şimdi koyuyor sana

Talimliydin yokluğa aslında

Aşk, mutluluk, para

Ve daha nicce virgüller vardı hayatında

Siz, sız, suz, ve daha nice

Yokluk ekiydi sende olan

Ama hiç bu kadar zora düşmemiştin

Şimdiyse, zirveye işsiz düştün.

VI

Dokunduğum anlardan, geçmişimden

Silinmiş izi uzuvlarımın

Renkler şeffaf mineraller gibi

Farklarını yitirmişler

Bu yüzden siyah beyaz

Zamanlarad haps olmuş düşüncelerim

Çünkü nicedir işsizim

Geçmişim bile bana uzak sanki

Hükmünü yitirmiş sözlerim

Ah! işsizliğim, bir sen

Sırt çevirmiyorsu bana

Açıkça bir sen vurmuyorsun

Oysa ikimizde biliyoruz

Senden kaynaklanıyor acılarım

Ve bir terk etsen beni

Doğacak güneşim belki

Git dememe kalmadan geldiğin gibi 

sıyrılsan hayatımdan ki ikimizde 

biliyoruz açıktan açığa vurmadığını

ama hep uyutarak yaktığını.', 'I Bendeki teyakkuz hali Aslında bir ruh göçü Gözlerim uyanık görünsede Bir ayrılık vakti II Parça başına öder, mutsuzluğunu acıların Zaman ü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":71,"source_url":"https://www.antoloji.com/issizlik-notlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkım Eşkiya..', 'askim-eskiya-engin-ozcan-aigz5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'en güzeli seninle kuşatılmaktı 

namluların sevda kustuğu çatışmalarda..

en yanlız ben.. 

en ulaşılmaz sen.. 

iki kişilik sevda siperleri kazmışız..yanlızlığımıza

bırak kahretsin zaman ikimizide.. 

toprağa karışıp aynı kökte hayat bulan... 

asi bir gülün amansız çiçekleri olalım...

seninle yenilmeleri

ve en çokta zamana yenilişimizi sevdim.. 

yüzünde eski sevdaların kırısıklarını birde.. 

çaresizlik içinde.

seni öyle sevdimki.. 

geceyi dün gündüze 

geceyi dün bize hapsettim....

gel sevdayı çeyrek gece trenine binelim seninle.. 

bana idamlık bir mahkum rolü verilmiş..

boğazımda ilmik.. avuçlarımda sen.. 

gözlerimle yağmur bedenimle toprak.. 

benliğimle senin olmalıyım...

farkındamısın? ? ? 

büyüdük hayallerimizle.. 

büyüdük.. 

büyüdü sevdalar.. 

binalar büyüdü.. 

ben büyüdüm.. 

içimdeki çocuğu öldürürcesine severken seni.. 

sen büyüdün...

gel...gidelim bitanem.. 

zamanın tükendiği yere.. 

gidelim.. sen..ben..birde aşkımız olsun... 

seninle cocukluğumun dağlarını aşalım... 

sedanın ovasını.. 

katran karası gözlerine hapsolduğum... 

birtanem.. 

aydınlığım puslu gecelerin ayazında.. 

gel..kanyakla beraber ver kendini bana... 

ateşler içinde yanalım... 

bedenlerimiz soğumadan gömsünler bizi 

tezek kokan..

doğacak yeni günün şafağına.....

aşkım eşkiya 

namlusu süngülü gezer.. 

aşkım eşkıya..

sazına kan değer...

tellerine..gönlüm...

mızrabı.. 

giyotine benzer...

Engin ÖZCAN

31.01.2004

istanbul', 'en güzeli seninle kuşatılmaktı  namluların sevda kustuğu çatışmalarda.. en yanlız ben..  en ulaşılmaz sen..  iki kişilik sevda siperleri kaz...', ARRAY['Türk Edebiyatı','Şiir','Engin Özcan']::text[], 8.5, '{"poet":"Engin Özcan","poet_slug":"engin-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/askim-eskiya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sivas Yanığı iki OtuzüçTemmuz Aydın 93', 'sivas-yanigi-iki-otuzuctemmuz-aydin-93-yusuf-kemal-metin-o7gl0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ağacın 

ormanına

suyun 

susamışlığına 

      yanan 

utancıdır 

     	iki otuz üç

aydın dünyadan

yüreğime sızan

ak kor

       yoğunluğunda

ak kor

kızıl

kan.

alevlerin

alevi içinde

hep o

Hızır

hınzır

iman

  Sivas yangını

kavururken

aydınlıkla barışık

kar boran

umut tozan

  buzul dağlarımı

inancımı yitirdim

kirli

yeşil bayrağınızı diktiğiniz

inançsızlığın

soysuz

    uğursuz

              sorgusuz

              cüce tepelerinde.



aydın 

insanımın

küle bandırılan

insancıl eti

 yakarken

onurlu kızıllığında

   onursuz 

         kara laneti

ben kuyudaki 

         kuytudaki 

         alev dudaklı gül

sen şehr-i sivas 

kimliğinde

      adı sivas olan kül

söyle

kaçıncı bin yangın bu

işte suysa

su

işte ekmekse

ekmek

ve işte insancıl onurun

kutsanmış emek

yaralıyım

yangınlıyım deme

hele

bir sinsi kibrite

       asla boyun eğme

alevim gururumdur

bir 

  pir sultan 

    benim ateş oğlumdur

ve gaflet

ve dalalet

ve adalet

ve hatta

      hıyanet

yaşamsal 

          onurumdur

kan akar kızılırmağım

kan ağlar baharım kışım

kan uyur anam babam

kan kusar hala leş yiyiciler

bin lanet lanetime

ey sabrımı sınayan katledilişler

gördükçe göz 

söyledikçe söz

yandıkça köz 

oldum

gökte sevinç

 	        yerde zılgıt ağıt

evrene kül tozarım

volkanım patladı bir kez

gayrı 

        çok zor susarım.', 'ağacın  ormanına suyun  susamışlığına        yanan  utancıdır       	iki otuz üç aydın dünyadan yüreğime sızan ak kor        yoğunluğunda ak...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Kemal Metin']::text[], 8.5, '{"poet":"Yusuf Kemal Metin","poet_slug":"yusuf-kemal-metin","theme":"Türk Şiiri","is_hero":false,"total_lines":88,"source_url":"https://www.antoloji.com/sivas-yanigi-iki-otuzuctemmuz-aydin-93-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedense her bayram', 'nedense-her-bayram-nazife-abayli-enwqk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nedense her bayram,

Hüzün çöker üstüme,

Sevinemem.

Yastığımın altında sakladığım,

Ne ayakkabılarım,

Ne de,

Giymeye kıyamadığım,

Bayramlık elbiselerim.

Ne elini öpeceğim annem,

Ne de babam var.

Kalmadı dostlar.

Yüreğim buruk.

Yüreğim perişan.

Yüreğim darmadağan.

Sevgilimde gelemiyor uzaklardan.

Çocuklarım  olmasa yanımda,

Kahrımdan öleceğim bu bayram.', 'Nedense her bayram, Hüzün çöker üstüme, Sevinemem. Yastığımın altında sakladığım, Ne ayakkabılarım, Ne de, Giymeye kıyamadığım, Bayramlık el...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/nedense-her-bayram-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben! Seni Sevdim!', 'ben-seni-sevdim-nazife-abayli-brd05', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben,

Yaşamasını bileni sevdim.

Yaşarken fark edeni,

Fark etmek isteyeni sevdim.

Ben,

Erdemini sevdim.

Erdemini seveni sevdim.

Ruhunun eli açık olanı,

Ruhunu kendine,

Saklamayanı sevdim.

Ben,

Eyleminden önce,

Söyleyeni,

Söylediğinden fazlasını,

Yapanı sevdim.

Zar atıp kazandığında,

Utananı sevdim.

Ben,

Ruhundan yara alanı,

Hüzünlerle,sevinçlerle,

Ruhunu doldurup, 

Taşıranı sevdim.

Ben,

Yüreğini sevgiyle dolduranı,

Ve......

Özgür yürekli adamı  sevdim.

Ben! 

SENİ SEVDİM..!', 'Ben, Yaşamasını bileni sevdim. Yaşarken fark edeni, Fark etmek isteyeni sevdim. Ben, Erdemini sevdim. Erdemini seveni sevdim. Ruhunun eli aç...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ben-seni-sevdim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sendedir Benliğim', 'sendedir-benligim-oguzkan-bolukbasi-0ix9a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerim kaybeder ufukta seni

Yüreğim bekliyor geri dönmeni

Bir umuda hapsedip de gittin

Kim çıkaracak bu odalardan beni

Yaşamak diyorsan seninle güzel

Mutluluk dediğin sen varsan eğer

Gülüşün bir ömre dünyaya bedel

İstersen harınla yak kül et beni

Bu açan güllere sevda diyorlar

Sebebi sendedir hiç bilmiyorlar

Düşümsün aşkımsın kıskanıyorlar

Uykularına sar bırakma beni', 'Gözlerim kaybeder ufukta seni Yüreğim bekliyor geri dönmeni Bir umuda hapsedip de gittin Kim çıkaracak bu odalardan beni Yaşamak diyorsan se...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sendedir-benligim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram Kutlaması*', 'bayram-kutlamasi-bayram-tunca-vs4d4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bugün günlerden bayramdır bayram 

Her kul, sevdiğine hayrandır hayran 

Hakiki dostsa, dostunu arayıp soran 

Bayramınızı kutlar dostunuz Bayram 

01.02.2004-09.30', 'Bugün günlerden bayramdır bayram  Her kul, sevdiğine hayrandır hayran  Hakiki dostsa, dostunu arayıp soran  Bayramınızı kutlar dostunuz Bayr...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bayram-kutlamasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
