INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğim', 'sevdigim-seyhmus-sait-aydin-ok1qz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '16

SEVDİĞİM

İyne batar söylenen tüm namede

Saz seninmi söz seninmi sevdiğim.

Arkana bakmadan gider olmuşsun

Yoldan kalkan toz seninmi sevdiğim.

.                       

Çok çabuk alınır çabuk küsersin

Deli rüzgar olup başta esersin

Bana neden bunca cefa edersin

Hiç bitmeyen naz seninmi sevdiğim

Dilimdesin şarkı oldun söylerim

Güneşsin yakarsın ateş neylerim

Ben sensiz bu gönlü nasıl eğlerim

Bozuk çalan saz seninmi sevdiğim

 Şeyhmus   Sait aydın                   28.06.2003', '16 SEVDİĞİM İyne batar söylenen tüm namede Saz seninmi söz seninmi sevdiğim. Arkana bakmadan gider olmuşsun Yoldan kalkan toz seninmi sevdiğ...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sait Aydın']::text[], 8.5, '{"poet":"Şeyhmus Sait Aydın","poet_slug":"seyhmus-sait-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevdigim-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bende kalsın', 'bende-kalsin-seyhmus-sait-aydin-e0d9p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'BENİ BENDE BIRAK. (n….)                                                                      17

                                (Unutmakmı 30yılı ha ;) 

Beni bana bırak bende kalayım

Şiirlerim sende kalsın sevdiğim

Seni oya gibi kalbe işledim

Öpüşlerim tende kalsın sevdiğim

Can olmuşsun can evimde yaşarsın

Kan olmuşsun damarımda sevdiğim

Seni kendi özüm ile eşledim

Bakışlarım sende kalsın sevdiğim.

Bir gülüşe tüm ömrümü adadım

Sitemlerin sende kalsın sevdiğim

Her gece rüyamda seni düşledim

Uykularım sende kalsın sevdiğim

Nazlarına naz ekleyip kacarsın

Kaçışların sende kalsın sevdiğim

Ben kapatır sen derdimi açarsın

Benim derdim bende kalsın sevdiğim

Ayrılalı Bunca oldu sormadın

Vefasızlık sende kalsın sevdiğim

Hala tomurcuksun,Bende,solmadın.

Kuruyan gül sende kalsın sevdiğim

Zamanı unuttum saatler senin

Geçmişte verilen vaatler senin

Tenim çürüsede bak ruhum senin

Yaşananlar bende kalsın sevdiğim.

                                  Sait Aydın

                                 (05.07.2003)', 'BENİ BENDE BIRAK. (n….)                                                                      17                                 (Unutmakmı 3...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sait Aydın']::text[], 8.5, '{"poet":"Şeyhmus Sait Aydın","poet_slug":"seyhmus-sait-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bende-kalsin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmez bu sevda', 'bitmez-bu-sevda-seyhmus-sait-aydin-fby2x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'BU SEVDA BİTMEZ

Köyümün güzel kızı

Sarı saçların 

Omuzlarından Dökülürdü 

Ve ben hep düşünürdüm.

Mademki,

Vermiyor aşkına cevap

Hapset yeşil gözlerine kendini

tut o sarı saçlara

As kendini derdim.

Sen su doldurmaya 

Çeşme başına geldiğinde

Uzaktan seni seyreder 

Sarı saçlarında kendimi asmayı 

Yeşil gözlerinde ölmeyi düşlerdim

Sen Ondört ben Onaltı yaşlarında

Delimi deli

İki çılgın serseri.

Yaz tatillerinde köye geldiğimde

Eve gitmez size gelirdim

Sarı saçlarını yeşil gözlerini

Birde

O erkeksi 

Deliliğini özlerdim.

Hoş geldin amaa,,,,,,,,

Boşuna geldin der gibi

Reddi bakışlarını özlerdim.

Köyün kızları bana yangın

Ben sana yangın

Başımda kavak yelleri

Dinlemezdimki hiç kimseyi

Akşamları beklerdim.

Hani saklanbaç oynadığımız,

Harimole oynadığımız,

günlerin akşamlarını.

Yeterki elin elime değsin

Erirdim biterdim.

 Akşamlar’ki

Onlarda kara sevdalıydı sanki

Bulutlara,

Sarı saçlım gibi

Hişç dokunmadan akşamlara,

Bir parmak ucu vedasıyla

Kayıp giderlerdi uzaklara.

Oyunlar biter

Sende giderdin.

Akşamları bana,,,,,,

Bulutları sana bezetirdim.

Tüm kayıp giden bulutlara,

Bir veda öpücüğünden

Mahzun bıraktığı için akşamları,,

Stem ederdim.

Zaman geçer,

Yaz biter.

Tatil biter,

Bu sevda bitmez derdim.

Aradan 40 yıl geçti sarı saçlı kız

Saçların ağardı biliyorum

Yeşil gözlerinde şimdi nem var,

 Ne olursa olsun bunu unutma,

 Bende bu sevda bitmez

Sait Aydın.15.08.2003', 'BU SEVDA BİTMEZ Köyümün güzel kızı Sarı saçların  Omuzlarından Dökülürdü  Ve ben hep düşünürdüm. Mademki, Vermiyor aşkına cevap Hapset yeşil...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sait Aydın']::text[], 8.5, '{"poet":"Şeyhmus Sait Aydın","poet_slug":"seyhmus-sait-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/bitmez-bu-sevda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhsuzlara Mesaj!', 'ruhsuzlara-mesaj-abdulkadir-karaman-nrgez', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni duyan, dinleyen kim? 

Konuş, konuş boşa gitsin! 

Duysa bile…anlayan kim? 

Konuş, konuş boşa gitsin! 

Ömür koşa koşa bitsin! 

Nasihatin yüzü soğuk…

Suçluların özü soğuk…

Herkes derki...sözü soğuk

Konuş, konuş boşa gitsin! 

Derler: boş ver, yaşa, gitsin! 

Bilmeyen, bilmem demiyor

Aç olan az az yemiyor

İhtiras canı emiyor

Konuş, konuş boşa gitsin! 

Bir iş var mı, hoşa gitsin? 

İyilikten bilmez kimse…

Hor görür, hem sevmez kimse…

Doğruya yer vermez kimse…

Konuş, konuş boşa gitsin! 

Yağ yak, yalan döşe gitsin! 

Muteber olan riyakar

Sahtekarlık çok can yakar

Yalan nice evi yıkar

Konuş, konuş boşa gitsin! 

Kış demeyin kuşa, gitsin! 

Sâdıka rağbet eden yok! 

Haine kucak açan çok! 

Allah’tan korkmayandan kork! 

Konuş, konuş boşa gitsin! 

Aç, çoğu, dört köse gitsin! 

Merhametsiz duygusuzlar…

Vurdumduymaz, kaygısızlar…

Saygı bekler, saygısızlar…

Söz işlemez taşa, gitsin! 

Konuş, konuş boşa gitsin! 

06.10.02

www.kadirkaraman.com', 'Seni duyan, dinleyen kim?  Konuş, konuş boşa gitsin!  Duysa bile…anlayan kim?  Konuş, konuş boşa gitsin!  Ömür koşa koşa bitsin!  Nasihatin ...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/ruhsuzlara-mesaj-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Odun', 'odun-suat-oktay-vqpaq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ey odun! 

odundan oduna fark vardir; 

yontulmuslar, yontulmamislar...

sadece odun olma! 

ille de odun kalacaksan,

yontulmus kal! 

Ya kendi kendini yont,

ya da bir ustaya yonttur! 

Hic olmazsa yontulmus olarak yasa! 

28/01/04 (Nödinge-Göteborg)', 'ey odun!  odundan oduna fark vardir;  yontulmuslar, yontulmamislar... sadece odun olma!  ille de odun kalacaksan, yontulmus kal!  Ya kendi k...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/odun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost ve Düşman', 'dost-ve-dusman-suat-oktay-si5og', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'eger düşmanlarin coksa ve onlari bertaraf edip

kurtulmak istiyorsan, caresi var! 

düşmanlarinla dost ol! 

bak, göreceksin; 

o zaman bi`tane bile düşmanin kalmayacak! 

31/01/04 (Nödinge-Göteborg)', 'eger düşmanlarin coksa ve onlari bertaraf edip kurtulmak istiyorsan, caresi var!  düşmanlarinla dost ol!  bak, göreceksin;  o zaman bi`tane ...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dost-ve-dusman-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Günahlar Geçti', 'i-lk-gunahlar-gecti-zafer-zengin-etnika-2bzs0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Akşam,gece ve sabah

Kokusuz gecen saatler

..

Tenin de cocuk dünyası

Gözlerin cennet

İçinde isyanlar kokuyor

Gidemiyorsun işte

Elvedalar için de saklı

Biraz daha içmelisin

Kanımdan,canımdan

Bakışında yakma beni

                İlk günahlar geçti...

..

Asırlar olmuş asılalı

Sonum senin ellerin de

Yak beni istersen

Uçurumlardan savur külümü

İncitme 

               Kanatlarım nefesin olsun...

..

Sessizlikte seyrettim

Yangınlar cıkmıştı

              gözyaşların da...

Uzattım elimi

Göğe değdim

             Üşüdüm yanlızlığın da...

..

gülün kokusun da saatler

can üşür

sensiz geçer nöbetler

içimde alevler

yüreğim yanar

bedenim titrer

üşür,

            yoksulluk tutan ellerim...

21.01.2004', 'Akşam,gece ve sabah Kokusuz gecen saatler .. Tenin de cocuk dünyası Gözlerin cennet İçinde isyanlar kokuyor Gidemiyorsun işte Elvedalar için...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ilk-gunahlar-gecti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yansımalar IV', 'yansimalar-iv-ahmet-aksoy-drsg2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '-Dudaklarımda Olgun-

dudalarımdan mor saçaklar akıyor şimdi,

öptüğün dudaklarımdan

bir yol oldu

bir yaradan bir kabuğa kadar.

ve ağzımdaki seni

…..hiçbir sensen gideremedi.

evrildin içimde,

……..şimdi, zaman senezoyik.

-Aşk Kaçağı-

ikindide dükkan açardım

geçmişte hep sana,

yetişmek istediğim halde

………kaçardım,

şimdiyse! şimdiyse! şimdiyse! 

kaçtığım yolda gözüm,

sen evrildin içimde,

….şimdi zaman yok

….dönmeye!', '-Dudaklarımda Olgun- dudalarımdan mor saçaklar akıyor şimdi, öptüğün dudaklarımdan bir yol oldu bir yaradan bir kabuğa kadar. ve ağzımdaki s...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yansimalar-iv-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gariptir benim köylüm,', 'gariptir-benim-koylum-mehmet-akar-w7kui', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gariptir benim çiftçim,benim köylüm.

Ama insandır; insaflıdır,sevecendir,saftır.

Çalışkandır! 

Çalışır; yalnız karın tokluğuna...

kimi zaman hükümete,

kimi zaman toprak ağalarına.

Çocuk gibidir,isteyemez emeğinin karşılığını

ırgatlık yapar; üç beş kuruşa; 

aç yatar çoğu zaman,doyuramadan karnını.

Gariptir işte benim çiftçim,benim köylüm.

Almasını,istemesini bilmez,hesap soramaz.

Çok misafirperverdir; paylaşmasını da bilir,

ağzından lokmasını alsan sesini çıkarmaz.

Hayalperesttir.

Parası yoktur ama çook zengin hayalleri vardır! 

Zengin olmak ister hep,şehirli gibi yada.

İnançlıdır,vatanseverdir,cesurdur,merttir

ama bir çocuk gibi de saftır.

Dedim ya işte; gariptir benim insanım!', 'Gariptir benim çiftçim,benim köylüm. Ama insandır; insaflıdır,sevecendir,saftır. Çalışkandır!  Çalışır; yalnız karın tokluğuna... kimi zaman...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akar']::text[], 8.5, '{"poet":"Mehmet Akar","poet_slug":"mehmet-akar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gariptir-benim-koylum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korku', 'korku-yagmur-damlasi-34234', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'şimdi gözlerimde iki damla yaş oldun akıyorsun

kangren olmuş bir yara gibi bu sevdayı

kesip atacağım biliyorsun.......

sen benden habersiz ben senden uzaklarda

yaşamaksa yaşamak dediğimiz buysa

manasını bilmediğim bir çok sözü bırakıp bir yana

ne çok hasretim sana koşmaya....

yüreğim durma diyor hadi durma koş ona

aklım olmazların tam ortasında

senli hayaller sensiz gerçeklere karışsada

bu aşkı kendim yaşıyorum bir başıma

on sekiz yaşımın militan sevdaları gibi

üstüme başıma boyalar bulaşmasada derdimi

anlatmak için haykırışlarım......

o zaman vatandı,milletti şimdi sen

kor ku yo rum..........................................! 

vatanı hiç kurtaramadım ben

bu aşkıda hiç edeceğim belli oldu şimdiden

KORKUYORUM', 'şimdi gözlerimde iki damla yaş oldun akıyorsun kangren olmuş bir yara gibi bu sevdayı kesip atacağım biliyorsun....... sen benden habersiz b...', ARRAY['Türk Edebiyatı','Şiir','Yağmur Damlası']::text[], 8.5, '{"poet":"Yağmur Damlası","poet_slug":"yagmur-damlasi","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/korku-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak Sevda', 'uzak-sevda-yagmur-damlasi-l0mb1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gece bir yılanın koynuna girercesine ürperirsin 

sessiz ve haindir Meşin dağında sevdan 

ve ben güzel gözlüm bilirsin 

anlamam yalandan dolandan 

sensizliği sevda gibi işledim yüreğime 

tut ki bir kurşun yarasıdır iyileşir bir gün olura 

izi kalsa da gözükmeyen bir yerlerimde 

bıraktım gitti her şeyi zamana 

Ankara nasılda tütüyorsun gözümde buram buram 

ve sevdam gibi yalnızlığım gibi uzaklardan seslenişim sana 

ah ne kadar hain ve ne kadar zulum bu yaşamak denen rüyam 

sen uykunun kim bilir kaçıncı zamanında 

meleklerle yanak yanağa 

yaktığım bilmem kaçıncı sigaranın miğdemi delmesi gibi 

acıyla yaşıyorum hasretini, 

gözlerimin ıraklarda kaldığı bilmem kaçıncı gün 

saymadım desem yalan olur ya 

söylemeye bile korkuyorum sensizliği daha dün 

dün gibiydi ellerin ellerimde yürürken Ankarada 

sen kadınımsın bilirsin beni dedim ya 

meşin dağında yürek ister hem sevdalı olacaksın 

hem gözünü kırpmadan ölüme koşacaksın 

hemde bunca hengamenın bunca kargaşanın içinde 

sevdana şiir yazacaksın deli derler adama deli birde', 'Gece bir yılanın koynuna girercesine ürperirsin  sessiz ve haindir Meşin dağında sevdan  ve ben güzel gözlüm bilirsin  anlamam yalandan dola...', ARRAY['Türk Edebiyatı','Şiir','Yağmur Damlası']::text[], 8.5, '{"poet":"Yağmur Damlası","poet_slug":"yagmur-damlasi","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/uzak-sevda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Sonatı', 'sevgi-sonati-yagmur-damlasi-s3j8u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir yaz akşamında yüreğini bana açtın

Kanatlarını gök yüzüne..........................

Daha az önce yüreğimsin diyordun ki bak nasıl kaçtın

Uzanıp yastığın göğsüne.......................

Sabah görüşelim canım sabah görüşelim de

Sabah olacak mı onu bir bilsem

Güneş aynı tepelerin ardından yine bak yine

Doğacak bize merak etme diyebilsem

Sen uyandığında yastığın mutlu yüzünden

Kim bilir ben nerede ve nasıl ne halde

Bakacaksın ya var mıyım yok mu yüreğinde

Nerelerden haber alacaksın ki benden

Kimim ve neyim meselesine getirdiğin yorum

Harikaydı be canım bak aynısını yazıyorum

can dostum,arkadaşım,ahretliğim,sevenim

söyletme haydi git.................ne diyeyim

dedin ve böylece gittin rüyalarımızdan sabaha

karanlıklarla bırakıp beni baş başa

ve sen uyandığında ben gülümseyerek sana

yine hoş geldin diyeceğim sevgimle ve aşkımla

yarın sabah olursa belki ellerini tutamayacağım yine

gözlerine bakamayacağım ya olsun

Sen gelişinle zaten yegane mutluluğumsun.

Yarın olsa ne olmasa ne yüreğimdesin ve hep benimle

benim olmadığım zamanlarda bile biliyorum ki sen benimlesin

ya beni düşünüyor ya bana yazıyorsun.

Benimle gözünden yaşlar döküyorsun

benim ile yine bütün neşelerin

biliyorum hiç bir şeyi anlatmana gerek yok ki

seni sensiz seninle ve her an yaşıyorum

duymak için görmek için çabalamalar ne kadar boşa ki

duyduklarımıza gördüklerimize asla inanmıyorum

biz hakikat de mi hayalde miyiz

uzanıyorum varsın ama tutamıyorum

çölde mi deniz de miyiz..................................................', 'Bir yaz akşamında yüreğini bana açtın Kanatlarını gök yüzüne.......................... Daha az önce yüreğimsin diyordun ki bak nasıl kaçtın ...', ARRAY['Türk Edebiyatı','Şiir','Yağmur Damlası']::text[], 8.5, '{"poet":"Yağmur Damlası","poet_slug":"yagmur-damlasi","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sevgi-sonati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzun Sessiz Ve Yalnız', 'uzun-sessiz-ve-yalniz-yagmur-damlasi-rla5f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bu gece bütün şiirlerimi yakarak

bu sevdayı arkamda bırakacak

dahası adını bir daha anmayacak

uzun bir yolculuğa çıkacağım.......

Kalemi kırarak; kağıdı yakarak

yaşanan her anı tek tek unutarak

tüm rüyalardan uyanarak

sessiz bir yolculuğa çıkacağım

kimselere haber bırakmayacak

aslında öyle ki tam da kaçarak

arkama bile bakmayarak

yapayalnız bir yolculuğa çıkacağım

özlemlerime kavuşamamak

emellerime ulaşamamak

elde değil ki uzansan yakalamak

dilim bağlı elim bağlı bir yolculuğa çıkacağım', 'bu gece bütün şiirlerimi yakarak bu sevdayı arkamda bırakacak dahası adını bir daha anmayacak uzun bir yolculuğa çıkacağım....... Kalemi kır...', ARRAY['Türk Edebiyatı','Şiir','Yağmur Damlası']::text[], 8.5, '{"poet":"Yağmur Damlası","poet_slug":"yagmur-damlasi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/uzun-sessiz-ve-yalniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Direniyorum', 'direniyorum-yagmur-damlasi-n2csa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'aleve sön denir mi...........? 

Yagmura yağma yada

böylesine parça parça olmuşken yüregim

bana kal.............

Kolaymi saniyorsun

yasamak sevgili özlemin dedigi gibi cam gök yüzümüzde

kanat çirpmak olsaydi......

Belki hiç bu kadar çok hava bosluguna düsmezdim 

ve ben yüksek daglarin en uç yamaçlarina sevdali 

bulanik sularin sazani

ve ben gökten düsen her damlada

yagmurun bir yüregi ferahlattigini düsünürken

kendi yüregime sakladigim

kor parçasini

sönmemesi için çiplak ellerimle

aciya aciya destigim gecelerde

kurtulmak için yüregimden

kendi öz canima kastettim

sonunda allahin huzuruna çikmak olmasa belkide çoktan

çekip de gidiverecektim,

ilk yaradilista verdigim o söz

sen benim rabbimsin

bir ondan dönmedim geriye

bir o söz üzerine devam ediyorum

bu sonsuz iskencede

inatla israrla direnmeye', 'aleve sön denir mi...........?  Yagmura yağma yada böylesine parça parça olmuşken yüregim bana kal............. Kolaymi saniyorsun yasamak s...', ARRAY['Türk Edebiyatı','Şiir','Yağmur Damlası']::text[], 8.5, '{"poet":"Yağmur Damlası","poet_slug":"yagmur-damlasi","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/direniyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can yoldaşım nerdesin?', 'can-yoldasim-nerdesin-ferit-teksoy-n30bv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gecelerce heyecanlı çığlıklar atan

Zamana sığmıyan sohbetler katan

Boşluktaki eli sıkıca tutan

İpek ellim,tatlı dillim nerdesin? 

Nerde benim canımdan can bildiğim? 

Yanımdayken dertlerimi sildiğim

Bütün sırlarımı tek tek verdiğim

Dert ortağım,can yoldaşım nerdesin? 

Gökte arıyorken yerde bulduğum

Rüyasını görüp hayra yorduğum

Uçan kuştan haberini sorduğum

Sevgi sözlüm,gülen yüzlüm nerdesin? 

Nerde benim tatlı dilli yoldaşım? 

Nerde benim dostum,nerde sırdaşım? 

Nerde benim sırrı berk arkadaşım? 

Ben seninle ben''im..ya sen nerdesin? 

En çok sen bilirsin yanan canımı

Versem de kurtulsam bütün kanımı

Çok mu buldun minik heyecanımı? 

Sitemkarım,çok özledim,nerdesin?', 'Gecelerce heyecanlı çığlıklar atan Zamana sığmıyan sohbetler katan Boşluktaki eli sıkıca tutan İpek ellim,tatlı dillim nerdesin?  Nerde beni...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/can-yoldasim-nerdesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu şehirde', 'bu-sehirde-salih-demirci-tftlq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Rotarlı düşlerin peşisıra

Yüzüp yetişmek isterken,

Tutku problemlerinden

Kalan ne varsa,

Git şarabıyla dökülüp 

Karıştı denize

Git şarabının mahzeni var mı? 

Karanfil koyu mumla yaşarız

Bu şehirde', 'Rotarlı düşlerin peşisıra Yüzüp yetişmek isterken, Tutku problemlerinden Kalan ne varsa, Git şarabıyla dökülüp  Karıştı denize Git şarabının...', ARRAY['Türk Edebiyatı','Şiir','Salih Demirci']::text[], 8.5, '{"poet":"Salih Demirci","poet_slug":"salih-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bu-sehirde-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Kent', 'bu-kent-ayca-tekin-j1fyx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bu kente geçmişimi verdim

geçmişin cömertliği ile süsleyip

bayramlığımı giydirip

dişlerini söktürüp te verdim

uyanık düşlere saklı karabasanları

söylencelere yazılı tüm acıları

öğrendim

sonuna dek direndim direncimin

sonuna dek direneceğim

(üsküdar 1995)', 'bu kente geçmişimi verdim geçmişin cömertliği ile süsleyip bayramlığımı giydirip dişlerini söktürüp te verdim uyanık düşlere saklı karabasan...', ARRAY['Türk Edebiyatı','Şiir','Ayça Tekin']::text[], 8.5, '{"poet":"Ayça Tekin","poet_slug":"ayca-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bu-kent-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Kız', 'kucuk-kiz-ayca-tekin-r9s97', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'nerede uyur o küçük kız

hangi bulut uçurur düşlerini güne

kaç sevgi alır uzanıp ellerine

yine mi üşür yalnız gecelerde kırılmış

düşleri kalın perdeler ardına saklanmış

buldumu dersin kesilen ağaçlarını 

hala saklar mı utanarak bacaklarını

nerede uyur nerdedir o küçük kız

(alanya 1998)', 'nerede uyur o küçük kız hangi bulut uçurur düşlerini güne kaç sevgi alır uzanıp ellerine yine mi üşür yalnız gecelerde kırılmış düşleri kalı...', ARRAY['Türk Edebiyatı','Şiir','Ayça Tekin']::text[], 8.5, '{"poet":"Ayça Tekin","poet_slug":"ayca-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kucuk-kiz-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredesin', 'neredesin-yagmur-damlasi-0uezi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kimse bizi özlemesin

Ama özleyen biri varsa bilsin,

Yüreğindeki benim..........! 

Kefenimiz elbisemizdir

Her daim boynumuzda yağlı ip

Dönmemek var bir gün gidip

Bu hali bilmeyen sevmesin

Süslü kelimeler uzak bize

Yar koynu tuzak,

Dün göğsümüzde 

Patlayan mermi

Ki yalandan sevmek

Güzelin haramındansa

Helalin çirkini 

Başımızın üstündedir,

Neredesin sorusu

Ey sevgili

Zulmün ta kendisidir', 'Kimse bizi özlemesin Ama özleyen biri varsa bilsin, Yüreğindeki benim..........!  Kefenimiz elbisemizdir Her daim boynumuzda yağlı ip Dönmem...', ARRAY['Türk Edebiyatı','Şiir','Yağmur Damlası']::text[], 8.5, '{"poet":"Yağmur Damlası","poet_slug":"yagmur-damlasi","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/neredesin-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram-2', 'bayram-2-mumtaz-begen-3rm67', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Fikirler bir başka görüşler ayrı,

Unutmuş gitmişiz vefayı, hayrı,

Yalansam söyleyim, şimdi bayramlar,

Neye benzemiyor bayramdan gayri?', 'Fikirler bir başka görüşler ayrı, Unutmuş gitmişiz vefayı, hayrı, Yalansam söyleyim, şimdi bayramlar, Neye benzemiyor bayramdan gayri?...', ARRAY['Türk Edebiyatı','Şiir','Mümtaz Beğen']::text[], 8.5, '{"poet":"Mümtaz Beğen","poet_slug":"mumtaz-begen","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bayram-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram - 3', 'bayram-3-mumtaz-begen-598uv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kul olma sırrına erebildik mi,

Kibiri yerlere serebildik mi,

Yoksula yetime  etin yanında,

Bu bayram sevgide verebildik mi?', 'Kul olma sırrına erebildik mi, Kibiri yerlere serebildik mi, Yoksula yetime  etin yanında, Bu bayram sevgide verebildik mi?...', ARRAY['Türk Edebiyatı','Şiir','Mümtaz Beğen']::text[], 8.5, '{"poet":"Mümtaz Beğen","poet_slug":"mumtaz-begen","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bayram-3-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Gibi', 'kar-gibi-ender-altinisik-qw0l2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kar gibi beyaz bir kuğu’ydun sen

tatlı suyu bulamadığı için tuzlu sularda yüzen...

Sen doğru aşk ı bulmak için

	yanlış sularda yüzerken

gökyüzü döküyordu içini sulu sepken…

Yağmurla karışık yağıyordu kar

aşk doluyordu içimize ağır ağır.

Karanlıktı rüzgar uğulduyordu

kırık kalplerimize çarpıyordu loş ışıklar.

ilk akşamında aşk ın ellerimdeydi ellerin

gözlerinde gereksiz bir intihar…

Kar kadar masum bir kuğuydun sen

sımsıcak yüreğimde erimekten ürken…

Özlediklerim sende,

düşlerim,gülüşlerim seninle

Bir adım at aşk’a

	gel benimle.

Ve sımsıkı sarıl şimdi

	tüm kaybettiklerine.

Kar  kadar yalnız bir kuğu’sun sen.

Yüreğime yağdıkça hem üşüyen,hem sevinen

kimsesiz bir sokak çocuğuyum ben…', 'Kar gibi beyaz bir kuğu’ydun sen tatlı suyu bulamadığı için tuzlu sularda yüzen... Sen doğru aşk ı bulmak için 	yanlış sularda yüzerken göky...', ARRAY['Türk Edebiyatı','Şiir','Ender Altınışık']::text[], 8.5, '{"poet":"Ender Altınışık","poet_slug":"ender-altinisik","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kar-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dua (Eşim; Eşsizim Burcu''ma)', 'dua-esim-essizim-burcu-ma-adnan-ferit-o076g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İki yıl önce 

Tamam dedik yastığı alalım,

Hatta bir kesmedi iki tane.

Sağlama bağlamıştık işi seninle.

Yaşımıza başımıza rağmen

Evde dolaşan iki çoçuğun ruhuydu.

Ve,

Evimiz çikolatadan yapılmıştı,

Birbirimizi yemedik

Evimizden sebeplendik.

Oyunlar oynadık başbaşa

Sen her zaman pollyanna oldun

Ben kah arslan kral,kah yoksul köylü

Ama her daim mecnundum.

Aldım verdim

Ben seni yendim.

Daha doğrusu

Aldım, 

Dünyaları vermek istedim

Veremedim.

Hep ben yendim,

Oysa gerçekte kazanan sendin.

Hiç hissettirmedin hiç ezdirmedin.

Ne diyebilirimki aslında ben,

Dileyebilirim sadece yürekten,

Allah çikolata evimizi eksik etmesin,

Birde dost bildiklerime

Senin gibi eş

Senin gibi sevgili

Senin gibi eşssiz güzellik versin.

AMİN..', 'İki yıl önce  Tamam dedik yastığı alalım, Hatta bir kesmedi iki tane. Sağlama bağlamıştık işi seninle. Yaşımıza başımıza rağmen Evde dolaşan...', ARRAY['Türk Edebiyatı','Şiir','Adnan Ferit']::text[], 8.5, '{"poet":"Adnan Ferit","poet_slug":"adnan-ferit","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/dua-esim-essizim-burcu-ma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidelim Gönlüm', 'gidelim-gonlum-bekir-mutlu-gokcesu-853q2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uçtu gönlüm

Uçtu da göçtü gönlüm

Bu diyardan geçti

Düştü gönlüm

Ha dayan, ha gayret

Kaç da kurtar canını

Gülünü, sümbülünü

Bu diyarda yanlış var

Ezelden bilirsin de

Adını koyamadıydın

Hadi kıpırda vaktin dar

Ha gayret gönlüm

Ey şiir yüreklim

Ey, ey, ey...

Neleri yutturdular bize

Yutmaya pek hazırmışız biz de

Hay bize, hey bize...

Hey, hey, hey...

Eller el kalsın, beyler bey

Biz çekip gidelim

Gidelim gönlüm...', 'Uçtu gönlüm Uçtu da göçtü gönlüm Bu diyardan geçti Düştü gönlüm Ha dayan, ha gayret Kaç da kurtar canını Gülünü, sümbülünü Bu diyarda yanlış...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gidelim-gonlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk ve Katil', 'ask-ve-katil-akif-kurtulus-a379o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'uzaklık avutur 

ve sessizlik başlar acıtmaya 

ihanet, ayrılığa borçlanmaktır 

bilinmez, kimden akar en çok kan orda 

her aşk bir gün, kendi katilini bulur 

silah çeker  biri, öteki ortak olur suça 

mecalim yok yeni cinayetlere, körelmiş maharetim 

bir kurbanım var ki, öldüm ölesi bende yaşar 

şifrelerimi çözdüm, buydu son ustalığım 

gönlüm dehlizimde beni boş yere arar 

bütün yakınlarımı buluşturdu vicdanım 

benden eksilen hakikat, fazlaymış artık hayata 

tek mülküm kaderimdi, vedalaştım 

unutulur emanette zaten, ruhum da 

görgü tanıkları, posta güvercinleri, akbabalar 

aşk çekişen biri var olay yerinde, belki o aklar 

kundakladım gövdemi, ankazdan ibaretti o da 

parola sordu birbirine dağılmış parçalarım 

yüzüme sürmek için sakil sözler aradım 

iyice sürttüm çehremi toprağa, 

rengim atsın, aşınsın harflerim 

bir parem düşman olsun kırkına 

ücramla çarpıştım yetmedi 

omuzbaşımla barıştım dinmedi 

kapattım sesimi, ışığımı söndürdüm 

yaktım, benden kalan ne varsa 

küllerimi bulduğum bu kuyu köşede 

bir hava kabarcığı altında 

              GÖRDÜM: 

beni uzaklık avutmuş 

sessizlik acıtmış seni', 'uzaklık avutur  ve sessizlik başlar acıtmaya  ihanet, ayrılığa borçlanmaktır  bilinmez, kimden akar en çok kan orda  her aşk bir gün, kendi ...', ARRAY['Türk Edebiyatı','Şiir','Akif Kurtuluş']::text[], 8.5, '{"poet":"Akif Kurtuluş","poet_slug":"akif-kurtulus","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ask-ve-katil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Sarayi', 'gonul-sarayi-guner-kaymak-y6kkg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönül sarayimi viran eyledin

Artik kimseleri sevemez oldum

Tek gözlü gecekondu''ya çevirdin

Gönlüme misafir bile alamaz oldum

Ümüdimi,arzumu,hevesimi tükettin 

Kadrimi,kiymetimi hiç bilmedin

Zeytin gözlüm beni hiçmi sevmedin

Derdimi kimselere açamaz oldum

Kendime olan güvenimi yitirdim

Ask pazarinda sermayemi bitirdim

Yasadiklarimizi hep aklima getirdim

Bir an bile sensiz duramaz oldum

Ask''ta risk var bunu zaten bilirdim

Elimde degil senin için ölürdüm

Her gece rüyamda seni görürdüm

Artik kabus dahi göremez oldum

Inancim kalmadi aska sevgiye

Izdirap gözyasi senden hediye

Bir daha dönüpte bakmam geriye

Burnumun ucunu göremez oldum

Güner derki yaralarim derinden

Canimdan biktim askin elinden

Kurtulamadim el alemin dilinden

Milletin içine çikamaz oldum

Amsterdam / 01.02.2004', 'Gönül sarayimi viran eyledin Artik kimseleri sevemez oldum Tek gözlü gecekondu''ya çevirdin Gönlüme misafir bile alamaz oldum Ümüdimi,arzumu,...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gonul-sarayi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Kentin Sisi', 'bu-kentin-sisi-huseyin-cayikli-mb2li', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir limandır bu kent ve kent ısıklarına saklanmıstır.ne zaman sis düşse kırmızı yanaklarıyla bir kız çocugu oturur dağların eteklerine.ben biraz daha hicaz olurum bu kentte.içimde biraz sitemkar arnavut bir çocuk oturur biraz macır bakar gözlerime.biraz yalın biraz alıngan ben bir bestenin güftesi olurum.bu kent kızıl yıldızıdır gözlerimin.ekmeğimin amacıdır kim bilebilir sevdaların belkide başkentidir.Aşkın resmi geçididir burada ki yollar.aşk bir kentin limanlarına sıkışmış. sislerden görünmüyor dağın yamacında ki kız çocuğu.ben ne zaman birşeylere yemin etsem uzakta bir gemi acil S.O.S çağrısını verir bende her akşam içimin deniz fenerini yakarım hayata inat.', 'bir limandır bu kent ve kent ısıklarına saklanmıstır.ne zaman sis düşse kırmızı yanaklarıyla bir kız çocugu oturur dağların eteklerine.ben b...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/bu-kentin-sisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belirgin', 'belirgin-gokhan-deniz-yazici-u6nv5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zamanın

        belirsiz

             saatlerindeyim

                               her an.

Belirgin olan bi şey var:

Her zaman aklımdasın

Mesela şu an! 

Bu gün de yanımda değilsin,

Gene yarın''da mısın? 

                            Kalmadı mecalim,

Yarın''ın ardında kaç yarın var; be ey zalim? 

Acaba hangi yarın''da ikimizin de yeri var? 

Acaba hangi aşığın alnında korkunun teri var? 

Korkuyorum; korkuyorum senden

Hüzün olacaksın diye bana,

Korkuyorum; korkuyorum ama

İçimdesin neyleyim...

Toprak...Uçsuz bucaksız kıraç toprak! 

Belli belirsiz bir bulut

                      ufuk çizgisi üstünde

Belirgin olan bir şey var,

Seni beyhude özlüyorum,

Bir ot bile bitmez bu topraklar üstünde.

Izdırabımın ezgisi yüzün

                      gitmiyorsa gözümden,

Çile çekmeye susadığım

                      belliyse her halimden,

Al! Tozlu kalbinde sakla

                      sana süzülen hasretimi

Kahrediyorum; kahrediyorum kendi kendimi, 

Yine de özlüyorum seni; 

                       özlüyorum neyleyim... 

Ezadayım...

Kavuşmak, umutsuz tahliye

Sonu gelmez cezadayım.

Bil ki, beklediğim her gün

                     damla damla kin''dir! 

Bu ayrılığın eceli, elbette ki yakındır.

Kabustayım...Gafletteyim

Ah nerdesin uyanış! 

Bu bir nefret değil,

                    bu sana bir yakarış,

Yokluğun demir ökçelerle

                    gezerken içimde,

Gururum kanar da bir ''ah'' etmem

İşte ben böyleyim! 

Bana eza''yı lütfetsen de 

           gene içimdesin neyleyim.', 'Zamanın         belirsiz              saatlerindeyim                                her an. Belirgin olan bi şey var: Her zaman aklımdasın M...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Deniz Yazıcı']::text[], 8.5, '{"poet":"Gökhan Deniz Yazıcı","poet_slug":"gokhan-deniz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/belirgin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Hatırla...', 'beni-hatirla-hasan-basri-kale-df477', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Birgün..

Seversen birini sen de

delice

Sırılsıklam aşık olursan

eğer birine..

Beni hatırla...

Peşinde koşmaktan

yorgun düşer ve

Gözlerin dalarsa sık sık

O''nun hayaline..

İki damla yaş 

yanağına süzüldüğünde..

Beni hatırla...

Dün birlikte yürüdüğünüz

Kalabalık ve gürültülü kaldırımlar 

ıpıssız ve bomboşsa şimdi

hissedebildiğin tek şey o ayazda

sadece O''nun hasretiyse eğer

Beni hatırla...

Ulaşamadığın sevgili

bir kış akşamı geçer de karşına

Derse ki sana

Yeter..bırak peşimi.! 

senden olmaz..ne arkadaş ne sevgili..

sen değilsin gönlümdeki

derse..

beni hatırla...

çaresiz..

bakakaldığında ardından tek başına

Buğulanmasın sakın gözlerin

sakın ağlama..

İçim yanar o an kıyamam sana..

Çok üzülme olur mu ulaşılmazım

sadece 

karşılıksız sevgim gelsin aklına

ve beni hatırla....', 'Birgün.. Seversen birini sen de delice Sırılsıklam aşık olursan eğer birine.. Beni hatırla... Peşinde koşmaktan yorgun düşer ve Gözlerin dal...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/beni-hatirla-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün Mutlaka...', 'bir-gun-mutlaka-erol-kesici-wkvo4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün mutlaka günes bizim icin`de dogacak

Gecenin karanliginda yildizlar piril piril parlayacak

Simdi gözünden akan yaslar...

Bir Gün Mutlaka... kuruyacak

Güler gecersin aklina geldikce mazi..

Mutluluga dönüsür....

Bir gün mutlaka...

Seven Sevdigine kavusur...

Hayaller gercek olur...

Izdiraplar son bulur

Bir Gün Mutlaka...hersey toprak olur

Bir Gün Mutlaka...hersey unutulur', 'Bir gün mutlaka günes bizim icin`de dogacak Gecenin karanliginda yildizlar piril piril parlayacak Simdi gözünden akan yaslar... Bir Gün Mutl...', ARRAY['Türk Edebiyatı','Şiir','Erol Kesici']::text[], 8.5, '{"poet":"Erol Kesici","poet_slug":"erol-kesici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-gun-mutlaka-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül', 'gul-zafer-zengin-etnika-qvqfk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gül

Gülüme

Gülerken

Güldüm

Gülümsedi

Gülümdü

Gülenimdi

Gülümsedim

         Sımsıcak

24 ocak 2004', 'Gül Gülüme Gülerken Güldüm Gülümsedi Gülümdü Gülenimdi Gülümsedim          Sımsıcak 24 ocak 2004...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gul-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızıyorum İşte Yalnızlığıma', 'kiziyorum-i-ste-yalnizligima-zafer-zengin-etnika-pafa6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hiç beni çağırmadın

kurduğun düşlerin içine

öfkem bu yüzden

                   yalnızlığıma...

..

nasıl gecer günler bilmezsin

sen beni 

akşam üstü görmezsin

bir yanım sancıdıkça

kızıyorum işte

                   yalnızlığıma...

..

satır satır yazıyorum işte

gör yanlızlığımı, tanı

bırakma düşlerinden uzağa

kızıyorum işte 

                    yalnızlığıma...

14.01.2004', 'hiç beni çağırmadın kurduğun düşlerin içine öfkem bu yüzden                    yalnızlığıma... .. nasıl gecer günler bilmezsin sen beni  akş...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kiziyorum-iste-yalnizligima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımızı Haykıracağım!', 'askimizi-haykiracagim-nazife-abayli-dsjdh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ayrılık ve hüzün anlatan,

Aşk acısını anımsatan,

Mısralar yazmak,

İstemiyorum artık.

Hazan''ı yaşıyorum demiştim! 

Şimdi! 

Yeşerdim,

Çiçeklendim,

Bahar oldum.

Yaşıyorum.

Yazacağım.

Seni yazacağım,

Senli sevdamı yazacağım.

Seni şiirlerle anlatacağım.

Beni sen eden benliğini,

Seni ben eden benliğimi,

Yüreğini,

Emeğini,

Gülümseyen gözlerini,

Dilinden dökülenleri,

Ruhunun güzelliğini,

Cesaretini,

Sevecenliğini yazacağım.

Aşkımızı haykıracağım!', 'Ayrılık ve hüzün anlatan, Aşk acısını anımsatan, Mısralar yazmak, İstemiyorum artık. Hazan''ı yaşıyorum demiştim!  Şimdi!  Yeşerdim, Çiçeklen...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/askimizi-haykiracagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler Dostumdur', 'geceler-dostumdur-baris-guc-5phgr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir agustos yaz gecesi; her yer kiyamet sicak

Rüzgar uykuda, yapraklarda çit yok

Disarida cir cir böceklerinin civil civil sesi yankilaniyor

Gül ve igde agaçlarinin hoyrat kokusu dolmus,buram buram cigerlerime

Ay bir kadin yüzü gibi tüm güzelligini  hoyratça sergiliyor

Biliyormusun? Ay ve günesin ortak bir yani var bize benzeyen

Birbirlerine asik,birbirlerini kovalayan ama asla bir araya gelemeyecek olan

Ansizin bir köpek havliyor sokakta çiglik çigliga

Bir hirsiz gibi düslerime giren seni görmüs olmali

Tutup denize mi atmali,bogmali bu hain yalnizligi

Agustos sicagi degil bu beni böyle alev alev kavuran

Geceler; hatiranla beni cayir cayir yakan

Gecelerin intikami degil bu gözlerimden akan yaslar

Senin insafsizligin; her gece içimi paramparça yapan

Geceler dostumdur, seni sikayet ettigim, gözyaslarimi bir sir gibi saklayan

Geceler sirdastir, en magrem anilarimizi ve sirlarimizi paylasan

Geceler arkadastir, yalnizligimizda bizi uykuyla kucaklayan

02.02.2004   sda ozlt MSN:   [email protected]', 'Bir agustos yaz gecesi; her yer kiyamet sicak Rüzgar uykuda, yapraklarda çit yok Disarida cir cir böceklerinin civil civil sesi yankilaniyor...', ARRAY['Türk Edebiyatı','Şiir','Barış Güç']::text[], 8.5, '{"poet":"Barış Güç","poet_slug":"baris-guc","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/geceler-dostumdur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabah Yelleri', 'sabah-yelleri-abdullah-atay-e2qcx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'aşk  yeşerten gözlerden,

ay gülüşlü yüzlerden,

’sevdiceğim’ diyen sözlerden,

sevdalar getirdi sabah yelleri...

leylak kokulu saçlardan,

yay çizilen kaşlardan,

belik belik örülü başlardan,

sevgiler getirdi sabah yelleri...

kına yakılı ellerden,

sevda yanığı benlerden,

türkü dilli tellerden

selamlar getirdi sabah yelleri...

kekik kokulu ormanlardan,

tınaz savrulu harmanlardan

sevda vurulu fermanlardan

seni getirdi sabah yelleri...', 'aşk  yeşerten gözlerden, ay gülüşlü yüzlerden, ’sevdiceğim’ diyen sözlerden, sevdalar getirdi sabah yelleri... leylak kokulu saçlardan, yay ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sabah-yelleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Sayfaları Karıştırırken(II)', 'eski-sayfalari-karistirirken-ii-yusuf-pangal-phk7t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Resmin ellerimde… Yüzün kederli… 

Boynun ışıltılı,pür mücevherli. 

Gülse de dudağın; nane şekerli...

Geçti mi senin de kapından,hazân? 

O ne solgun bakış; yüzünden sızan, 

Uyku mu yoksa...? Neyin var,Sûzan? 

Gamzende saklardın türlü gülüşler; 

Ne oldu umutlar,kurduğun düşler? 

Sonbahar gülleri gibi ölmüşler… 

Hâlinden bir hüzün seziliyor da… 

Aynaya bakarken rûhuna sor da 

Umduğu aşkı  bulmuş mu,orda? 

15/12/2003', 'Resmin ellerimde… Yüzün kederli…  Boynun ışıltılı,pür mücevherli.  Gülse de dudağın; nane şekerli... Geçti mi senin de kapından,hazân?  O ne...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Pangal']::text[], 8.5, '{"poet":"Yusuf Pangal","poet_slug":"yusuf-pangal","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/eski-sayfalari-karistirirken-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç mi Sevmiyorsun', 'hic-mi-sevmiyorsun-sefer-kurt-sh9r3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hiç mi sevmiyorsun

Benim için yüreğin hiç sızlamıyor mu 

Gece hayallerini süslemiyor muyum

Oysa ben hep seninleyim hayallerimde 

Öylesine seviyorum ki anlatamam

Seninle doğdu güneşim 

Ve seninle gülmeli yüzüm

Sana olan aşkım sevgim yetmez mi

Hiç mi sevmiyorsun 

çiçekler gördüğünde burukluk hissetmiyor musun

Ya kolkola gezen sevgililer

Sahile vuran o rüzgar 

Deli deli coşmuyor mu yüreğinde 

İskeleye yanaşan gemi 

Bunların hiç biri sevgimi hatırlatmıyor mu sana

Ya gül çiçekleri

Sevginin simgesi değil mi

Kırılan cam şişesi değil kalbimdir bilesin

Bu aşkımı gözyaşlarına çeviren sensin

Elini vicdanına koy duy şu sesi 

Hiçbir umut yok mu

Yüreğin hiç acı çekmiyor mu 

İyi düşün güzelim iyi düşün

Sen beni hiç sevmiyor musun

Hiç sevmiyor musun', 'Hiç mi sevmiyorsun Benim için yüreğin hiç sızlamıyor mu  Gece hayallerini süslemiyor muyum Oysa ben hep seninleyim hayallerimde  Öylesine se...', ARRAY['Türk Edebiyatı','Şiir','Sefer Kurt']::text[], 8.5, '{"poet":"Sefer Kurt","poet_slug":"sefer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hic-mi-sevmiyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutacaksın', 'unutacaksin-sefer-kurt-9yqd7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sabah uyandığında sokağa atacaksın kendini

Geçmişi hatırlayıp anılar yakalayacak seni

Umutların peşine düşüp artıracak hayallerini 

Arayacak gözlerin beni ateş olup kavrulacaksın 

Çok zor olacak imkansız olacak ama unutacaksın

Şu park diyeceksin yaşlı gözlerle bakacaksın

Ellerin ellerimi arayacak bulamayacaksın

Bakacaksın oturduğumuz yere kendini tutamayacaksın

İçin kabaracak gözlerin yaşaracak ağlayacaksın

Çok zor olacak imkansız olacak ama unutacaksın

Oturup sahile boş gözlerle bakacaksın denize

Deniz mavi aşkımızın maviliği hani nerede 

Siyahtan ne farkı var ki bilinmez bir çile

Lanet okuyup maviye sahile kızacaksın

Çok zor olacak imkansız olacak ama unutacaksın

Bir vapur yanaşacak iskeleye umutların artacak

Sevinçten gözlerin büyüyecek hepsi boşa çıkacak

Kızacaksın vapura adımların hızla kaldırımı yalayacak

Rüzgar çıkacak umutlarınla birlikte savrulacaksın

Çok zor olacak imkansız olacak ama unutacaksın

Ayrılık şarkıları dinleyeceksin son zamanlarda 

Değişik hayaller düşler kuracaksın karanlıklarda 

Konuşmayacaksın korkarak bakacaksın insanlara

Kaçacaksın korkacaksın ve ebedi susacaksın

Çok zor olacak imkansız olacak ama unutacaksın

Benim değerimi bilmedin beni çok arayacaksın

Beni unutup hayatına sahip çıkıp yaşamaya çalışacaksın

Kavrulacaksın biliyorum zaman zaman ağlayacaksın

Akan gözyaşlarını silip gülmeye çalışacaksın

Çok zor olacak imkansız olacak ama unutacaksın', 'Sabah uyandığında sokağa atacaksın kendini Geçmişi hatırlayıp anılar yakalayacak seni Umutların peşine düşüp artıracak hayallerini  Arayacak...', ARRAY['Türk Edebiyatı','Şiir','Sefer Kurt']::text[], 8.5, '{"poet":"Sefer Kurt","poet_slug":"sefer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/unutacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden', 'neden-sefer-kurt-kmptv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yürek yakıyor acı veriyorsun

Neden varsın aşk söyle neden

Hayatı zehir edip güldürmüyorsun insanı

Neden varsın aşk neden söyle neden

	

Bulut var bak yine yağmur yağıyor

Yağma yağmur göz yaşlarım toprağı ıslatıyor

O sular inan ki yarama merhem olmuyor 

Öyleyse neden yağıyorsun yağmur neden

	

Doğma güneş zaten içim yanıyor 

Sıcaklığın gönlüme ızdırap oluyor

Aşk ateşine güç ve direnç katıyor

Yakıyorsan neden vuruyorsun söyle neden 

Esme rüzgar deli deli esme 

Alıp gidemezsin dertleri geriye

Çare olmaz olmaz gönül işine

Neden esiyorsun söyle neden

	

Deniz mavi aşkta yok mavilik

Aşk saftı hani nerede o sadelik

Sevgi ararken mutluluğu verdik

Neden gelmiyorsun mutluluk neden', 'Yürek yakıyor acı veriyorsun Neden varsın aşk söyle neden Hayatı zehir edip güldürmüyorsun insanı Neden varsın aşk neden söyle neden 	 Bulut...', ARRAY['Türk Edebiyatı','Şiir','Sefer Kurt']::text[], 8.5, '{"poet":"Sefer Kurt","poet_slug":"sefer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/neden-66-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Hallerde Türkiye', 'ne-hallerde-turkiye-sefer-kurt-pya0y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Solda islamı  harcama davası 

Sağda sözde müslümanlık kavgası 

Bunların hepsi koltuk sevdalısı 

Uyan millet uyan bak ne hallerde Türkiye

Gençlik içki kumar batağında sorsan Avrupa''lı

Kalpleri kazınmış beyinleri yıkanmış içleri karalı

Gençlik kaldır başını aç gözlerini bak nerede Amerika''lı 

Uyan gençlik uyan bak ne hallerde Türkiye

Ne çabuk unuttunuz on büyük şanlı Osmanlı''yı 

Fatih''leri Yavuz''ları çok erken unuttunuz onları

Bak hala her yerde geziyor onların adları

Uyan millet uyan bak ne hallerde Türkiye

Seçime yakın en iyisi benim deyip veriler sözleri

Koltuğa oturunca her şeyi unuturlar hiç çıkmaz sesleri

Sanki eşşek arısı sokmuş o bülbül gibi konuşan dilleri

Uyan millet uyan bak ne hallerde Türkiye

Hey millet siz uyudukça yukarıdakiler koltuğa geriliyor 

Uyan millet uyan ülke geriye doğru gidiyor

Sözde Avrupa birliği diyorlar o rüyalarına bile girmiyor

Uyan millet uyan bak ne hallerde Türkiye', 'Solda islamı  harcama davası  Sağda sözde müslümanlık kavgası  Bunların hepsi koltuk sevdalısı  Uyan millet uyan bak ne hallerde Türkiye Gen...', ARRAY['Türk Edebiyatı','Şiir','Sefer Kurt']::text[], 8.5, '{"poet":"Sefer Kurt","poet_slug":"sefer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ne-hallerde-turkiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi Git', 'hadi-git-sefer-kurt-h05th', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geceler umutlarla kararmıyor

Bu gönlüm sensiz olamıyor

Umutsuz bu dünyada yaşanmıyor

Hep sevmiştim seni seviyorum yar

Git hadi git söndür kalbimdeki aşk ateşini

Git hadi git unut gitsin bu büyük  sevgimizi

Git hadi git durma vur kalbime hançeri 

Git hadi git unut beni sende git 

Sen içimde sakladığım son aşkımsın

Çekip gidersen içimi yakarsın 

İçimde yeşeren aşk bahçemi yıkarsın

Hep sevmiştim seni seviyorum yar

Git hadi git

Aşk bahçemden al git her şeyi

Ben alıştım acılara

Acıların çocuğu oldum

Git hadi git acılara at beni öyle git

Sen benim son yıldızımsın

Sen benim son gülümsün

Sen gönül kapımın son meleğisin 

Sen gidersen gecelerim yıldızsız 

Günlerim gülsüz kalır

Eğer yinede gideceksen

Durma git 

Hadi git hadi...', 'Geceler umutlarla kararmıyor Bu gönlüm sensiz olamıyor Umutsuz bu dünyada yaşanmıyor Hep sevmiştim seni seviyorum yar Git hadi git söndür ka...', ARRAY['Türk Edebiyatı','Şiir','Sefer Kurt']::text[], 8.5, '{"poet":"Sefer Kurt","poet_slug":"sefer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hadi-git-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Soruyorum', 'seni-soruyorum-sefer-kurt-izip6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir efkar bir hüzün bastı yüreğime

Gecenin karanlığına değil yıldızlara soruyorum seni

Sensiz geçen günlerde dayanamıyorum özlemine 

Havada uçan kuşa bülbüle soruyorum seni

	

Sensiz geçen günlerde dertliyim ben dertli

Yanarken içim yüreğim ateşli

Geçmiyor günler gecelerse çileli

Karşıdaki dağlara taşlara soruyorum seni

	

Siyah görsem kömür gözlerin geliyor aklıma

Bir tebessüm var o kiraz dudaklarında

Elma yanaklarınsa duruyor  karşımda 

Karanfile soruyor menekşeye soruyorum seni

Biter çileler güzelim sen gönlünü ferah tut 

Unut geçmişi benim gibi sende unut

Her gelen yeni gün yeni bir umut

Güneşe soruyorum yağmura soruyorum seni 

	

Soruyorum seni rüzgara soruyorum 

Doğan güneşe gecenin yıldızlarına soruyorum

Sensiz geçen günlere zamana isyan ediyorum

Sevdiğim için kalbime soruyorum seni', 'Bir efkar bir hüzün bastı yüreğime Gecenin karanlığına değil yıldızlara soruyorum seni Sensiz geçen günlerde dayanamıyorum özlemine  Havada ...', ARRAY['Türk Edebiyatı','Şiir','Sefer Kurt']::text[], 8.5, '{"poet":"Sefer Kurt","poet_slug":"sefer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seni-soruyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz İkimiz', 'biz-i-kimiz-sefer-kurt-7l27a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıllarca savaştık çilelerle

Bıkmadan usanmadan yılmadan

Mutlu olmak için çırpındık yıllarca

Başaracağımıza inandık

Şimdi mutluluğu yakaladık biz ikimiz

Dağları sokmuşlardı aramıza

Aşacağız dedik tırmanmaya başladık 

Taşları engel bilmeyip aştık

Hedefimiz vardı sonunda ulaştık

Dağın zirvesinde biz birbirimize kavuştuk 

Kaderle yarıştık biz ikimiz

Geceler yas tutardı yüreğimizde

Ne ay nede yıldız vardı 

Zifiri karanlıkta birbirimize ulaştık 

Aşkımızla karanlığı aydınlattık

Sevgimizi her şeyden üstün tuttuk biz ikimiz

Biz böyle sevdik işte

Yüreğimizdeki kurşunu şekere çevirdik

Uzakta da olsak ayrılığı mutlulukla pekiştirdik

Biz hayattan korkmadık

Aşkımızı silah yapıp onula savaştık

Ve kazandık

Şimdi sımsıkı sarıldık birbirimize 

Bu mutluluğu ebedi sürdürmek için 

Söz verdik biz ikimiz', 'Yıllarca savaştık çilelerle Bıkmadan usanmadan yılmadan Mutlu olmak için çırpındık yıllarca Başaracağımıza inandık Şimdi mutluluğu yakaladık...', ARRAY['Türk Edebiyatı','Şiir','Sefer Kurt']::text[], 8.5, '{"poet":"Sefer Kurt","poet_slug":"sefer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/biz-ikimiz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhanet', 'i-hanet-sefer-kurt-g6w6z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Neden bırakıp gittin

Oysa mutluydum seninle

Neden sebepsiz terk ettin beni

Bu ihanetinin sebebi neydi 

Neden yalnızlığa ittin beni

Bu beden sana muhtaç oysa

Ya bu gönül...

Deniz sakin bu gün yine

Sessiz ve dalga yok

Sahilde eski bir tekne 

Kürekleri içinde çürümeye terk edilmiş

Aynı senin beni terk ettiğin gibi

Oturdum teknenin üstüne

Ellerim ellerini aradı

Gözlerim gözlerini

Kollarım sarmak istedi seni

Hani şarkımız var ya

Onu söylemek istedim 

Sen yokken varmadı dilim söylemeye

İhanet şarkıları söyledim içimden

Neden mi 

Çünkü senin bu yaptığına ne denir ki

İhanet güzelim ihanet

Senin bu yaptığına ihanet denir

İhanet ihanet...', 'Neden bırakıp gittin Oysa mutluydum seninle Neden sebepsiz terk ettin beni Bu ihanetinin sebebi neydi  Neden yalnızlığa ittin beni Bu beden ...', ARRAY['Türk Edebiyatı','Şiir','Sefer Kurt']::text[], 8.5, '{"poet":"Sefer Kurt","poet_slug":"sefer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ihanet-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıyamam', 'kiyamam-sefer-kurt-qkrsc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine gece yarısı

Karanlıklar yine çökmüş üzerime 

Başımı duvara yasladım

Seni düşündüm bu gece sevgilim

Nedense ilk gözlerin geldi aklıma

Kara gözlerini hatırladım

Hani bakıştığımız günler var ya

Yine öyle baktım sanki 

Yanağını okşadım sonra

Yine sen gülümsedin bana

Dudakların geldi aklıma

Öpmeye kıyamadığım dudakları

Gülümseyip yine öpüştüm seninle

Elini tuttum yeniden 

Pamuk gibi ellerin

Avuçlarımdan süzüldü usulca

Hep hayalinle yaşıyorum sevgilim

Bitiyor askerlik döneceğim sana

Hayalini daha yaşamayacağım

Seninle olacağım artık

Öyle çok seviyorum ki anlatamam

Kıyamam sevgilim kıyamam

Ne sevgime nede sana

Kıyamam sevgilim asla kıyamam', 'Yine gece yarısı Karanlıklar yine çökmüş üzerime  Başımı duvara yasladım Seni düşündüm bu gece sevgilim Nedense ilk gözlerin geldi aklıma Ka...', ARRAY['Türk Edebiyatı','Şiir','Sefer Kurt']::text[], 8.5, '{"poet":"Sefer Kurt","poet_slug":"sefer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kiyamam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet', 'gurbet-ercan-otaci-f1vrm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yagmur yagar istasyonlar islanir

Gavur tren aci aci seslenir

Ne yollar tukenir ne can uslanir

Uyanir gurbeti sabahlarimin

Gozlerim hep bildik bir seyler arar

Yuregim aklimi atese surer

Eski bir hatira kanima girer

Catlar kabuklari yaralarimin

Ben yururum yolum izimden ayri

Oturur aglarim gozumden ayri

Yanarim sancimdan sizimdan ayri

Usur dudaklari dualarimin', 'Yagmur yagar istasyonlar islanir Gavur tren aci aci seslenir Ne yollar tukenir ne can uslanir Uyanir gurbeti sabahlarimin Gozlerim hep bildi...', ARRAY['Türk Edebiyatı','Şiir','Ercan Otaci']::text[], 8.5, '{"poet":"Ercan Otaci","poet_slug":"ercan-otaci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gurbet-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmayı Unuttum', 'unutmayi-unuttum-sefer-kurt-596gb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geceler bir sessiz oluyor

Sessizlik bendemi saklı acaba 

Yoksa sessizlikte ben miyim saklı

Karanlıklar umutsuz oluyor

Aydınlıklarsa hep hayalde

Sevgi acıya endeksli 

Umutlar hüzünle kararıyor

Hüzünse aşkın dostu zaten

Sevmek acıyla ölüm arasında 

Ölüm bir nevi mutluluk aslında

Yok olmak asla değil

	

Hayat gecelerde saklı 

Gecelerde hep düşüncelere

Mutluluk ufukta hiç gözükmez 

Bana uzak

Uzağa çok yakın

Ufukta yeşeren umutlar kapkara 

Kara günler benim dostum 

Dostluklara saklı geçmişi unutmamak 

Hiçbir şeyi unutamadım bu güne kadar

Tek unuttuğumsa unutmak

Sadece unutmayı unuttum

Unutmayı unuttum', 'Geceler bir sessiz oluyor Sessizlik bendemi saklı acaba  Yoksa sessizlikte ben miyim saklı Karanlıklar umutsuz oluyor Aydınlıklarsa hep haya...', ARRAY['Türk Edebiyatı','Şiir','Sefer Kurt']::text[], 8.5, '{"poet":"Sefer Kurt","poet_slug":"sefer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/unutmayi-unuttum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Unutamam', 'ben-unutamam-sefer-kurt-t0g8s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kader aldı götürdü bizi

Unutturdu hayatın güzel yüzünü

Karanlıklara attı umutları karartı

Uzaklaştırdı bizi sevdiklerimizden

Yaşamayı unutturdu

Ben uzakta olsam bile 

Sizi asla unutamam

Aramasanız sormazsanız da 

Ben sizi unutamam

Geceleri unuturum

Yaşamayı unuturum

Sizleri asla unutamam

Ben kalbime yazdım sizler

Ben yüreğime kazıdım

Kopartamam kalbimdeki sayfayı

Silemem içimdeki yazıyı

Beni unutsanız bile ben unutamam

Beni unutanları ben unutamam

Ben unutamam', 'Kader aldı götürdü bizi Unutturdu hayatın güzel yüzünü Karanlıklara attı umutları karartı Uzaklaştırdı bizi sevdiklerimizden Yaşamayı unuttu...', ARRAY['Türk Edebiyatı','Şiir','Sefer Kurt']::text[], 8.5, '{"poet":"Sefer Kurt","poet_slug":"sefer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ben-unutamam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dudaklarında Son Bulsaydım', 'dudaklarinda-son-bulsaydim-sefer-kurt-45t6d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ellerimde resmin

Hayalin gözlerimde

Hani o sevgi yolu var ya

Oradayız yine

Zamansız zamanlarda özlüyorum seni

Zamanım sensiz geçmiyor

Kalbim zamansız yerlerde atıyor

Korkuyorum bazen yokluğundan

Dünya boş geliyor bana

Kapatıyorum gözlerimi 

Ve sen yine benimlesin

Keşke bir poyraz olsaydım 

Esip üşütseydim seni

Bir meltem olsaydım

Sarıp sarmalasaydım seni

Hepsi bir yana 

Keşke bir yağmur tanesi olsaydım

Dudaklarında son bulsaydım', 'Ellerimde resmin Hayalin gözlerimde Hani o sevgi yolu var ya Oradayız yine Zamansız zamanlarda özlüyorum seni Zamanım sensiz geçmiyor Kalbim...', ARRAY['Türk Edebiyatı','Şiir','Sefer Kurt']::text[], 8.5, '{"poet":"Sefer Kurt","poet_slug":"sefer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dudaklarinda-son-bulsaydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümse Bana', 'gulumse-bana-sefer-kurt-1g1c1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gecenin sessizliğinde hatırlarsan beni

Kiraz dudaklarını büküp gülümse bana

Gecede yıldızlar kayarken

Ay dede masumca sana bakarken

Umudum olup gel de gülümse bana

Aşkın olduğu yerde bir içim su 

Gözlerin yaşsız şimdi kupkuru

Kılarda açan çiçekler gibi gülümse bana

Aşkın ruhuyla süslendi mi o beden

Gönlün sevgi ile dolarsa gülümse bana

	

Dağlar çıka çıka aşılır

Günler geçtikçe dem vurur

Sular akar akar durur

Aşkımız ne durur ne yorulur

Bu aşk için...

Candan gönülden kalbinden gülümse bana', 'Gecenin sessizliğinde hatırlarsan beni Kiraz dudaklarını büküp gülümse bana Gecede yıldızlar kayarken Ay dede masumca sana bakarken Umudum o...', ARRAY['Türk Edebiyatı','Şiir','Sefer Kurt']::text[], 8.5, '{"poet":"Sefer Kurt","poet_slug":"sefer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gulumse-bana-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelecek misin', 'gelecek-misin-sefer-kurt-8fpc6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşkım çığlık atıyor belki duyarsın diye

Bu sesi duyup kulak verecek misin 

Yüreğimde ateş var sönmek bilmiyor

Kor kor yanan alevleri görüp söndürecek misin

	

Aşkım ızdırap gönlümse düşmüş derde

Akarken göz yaşlarım yüreğimde çile

Ne olur aşkım ne olur bebeğim gel dön geriye

Uzaktan sevip benim için göz yaşı dökecek misin

Çile diyorsun aşkın adına sen

Biliyorum seviyorsun dilinde hep ben

Aşkın tohumu benim eğer sevmek istersen 

Sevgi bahçesine beni beni de ekecek misin

Kalbim hapistir içindeyse aşk mahkumları

Sensin işte o kapının tek anahtarı

Açarsan saracaktır seni sevginin büyülü kolları

Yıkıp tapuları kollarına kendini bırakacak mısın

Bu aşk ateşini bir gün söndürecek misin

Sevgi bahçesine mutluluk çiçeği ekecek misin

Akan göz yaşlarımı ellerinle silecek misin

Benim için aşkım için geri gelecek misin', 'Aşkım çığlık atıyor belki duyarsın diye Bu sesi duyup kulak verecek misin  Yüreğimde ateş var sönmek bilmiyor Kor kor yanan alevleri görüp s...', ARRAY['Türk Edebiyatı','Şiir','Sefer Kurt']::text[], 8.5, '{"poet":"Sefer Kurt","poet_slug":"sefer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gelecek-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin Sevgilim', 'gittin-sevgilim-sefer-kurt-q898j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Göz yaşlarım akıyor dinmiyor ki 

Yüreğim yanıyor kanıyor sanki

Unut diyorsun unutamam ki

Unutmak o kadar kolay mı sevgilim

	

Bu aşk sancı oldu gönlümde

Nasılda bırakıp gittin beni ellere

Öyle sevmiştim ki kıydın sevgime

Hançer saplayıp ta gittin sevgilim

Gülmüyor yüzüm gülemem ki

Senden başka kimseyi sevemem ki

Ben sensiz asla yaşayamam ki

Gitmek bu kadar kolay mı sevgilim', 'Göz yaşlarım akıyor dinmiyor ki  Yüreğim yanıyor kanıyor sanki Unut diyorsun unutamam ki Unutmak o kadar kolay mı sevgilim 	 Bu aşk sancı ol...', ARRAY['Türk Edebiyatı','Şiir','Sefer Kurt']::text[], 8.5, '{"poet":"Sefer Kurt","poet_slug":"sefer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gittin-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adım Adım', 'adim-adim-tabir-gokce-4kcor', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'her gün bir adım geliyorum sana

yani,

adım adım mutluluğa...

geliyorum, aç kollarını bana...', 'her gün bir adım geliyorum sana yani, adım adım mutluluğa... geliyorum, aç kollarını bana......', ARRAY['Türk Edebiyatı','Şiir','Tabir Gökçe']::text[], 8.5, '{"poet":"Tabir Gökçe","poet_slug":"tabir-gokce","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/adim-adim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boz Dumanlı Yelelerin Kabarmış', 'boz-dumanli-yelelerin-kabarmis-sadik-softa-oxg22', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Boz dumanlı yelelerin kabarmış; 

Bağrında çiçekler gülüyor dağlar.

Duman duman saçların da ağarmış; 

Beyaz beyaz yüzün gülüyor dağlar.

Yücelerin aslanların otağı; 

O gül bağrın ceylanların yatağı; 

Yürekten bağlanmış gönlümün bağı; 

Gönlümde sevgilim gülüyor dağlar.

Sevgim harmanlanmış, toz-duman bağrım; 

Sevmek tek günahım, sevgiye çağrım; 

Yaz olsun hep, kış görmesin baharım; 

Beyaz beyaz yüzün gülüyor dağlar.

Savrulayım başındaki dumanla; 

Bir ömrü savurdun, geçti amanla; 

Taşlaşamaz, mümkün deyil zamanla; 

Beyaz beyaz yüzün gülüyor dağlar.

Senin heybetine sevgilim girmiş; 

Başındaki duman sevgimden dermiş; 

Sevdam, sevdiğime zaten esirmiş; 

Beyaz beyaz yüzün gülüyor dağlar.

12.01.2004', 'Boz dumanlı yelelerin kabarmış;  Bağrında çiçekler gülüyor dağlar. Duman duman saçların da ağarmış;  Beyaz beyaz yüzün gülüyor dağlar. Yücel...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/boz-dumanli-yelelerin-kabarmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece', 'bu-gece-yusuf-pangal-rd4e1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tutmuyor ellerim,kalemlerimi

Hâlimi sâkiler,yazsın bu gece

Anlatmakla olmaz; elemlerimi

Bir ressam elleri,çizsin bu gece

Duydukça,mâziden yel estirirler

Gönlümü yakıyor eski şiirler.

Çağır meyhaneci! Yeni şairler,

İnciden sözleri dizsin bu gece...

''Beğenmem'' derseniz,alnımdan vurun; 

Yerini yalnızca gönlüme sorun; 

Bahçeye zümrütten,bir havuz kurun; 

İçinde kuğular yüzsün bu gece...

Bu nasıl adalet,bu nasıl yargı; 

Hâlimin,Mecnûn''dan kalmadı farkı; 

Eski bir plaktan çalarken şarkı; 

Gözyaşım,acaip azsın bu gece...

Yangında tutuşup,sevmişse yürek

Suç mudur,aşkını düşte dilemek? 

İsyanıma kızmış,küsmüşse felek; 

Yoluma tuzaklar kazsın bu gece...

Yangınlar,dünyamı ederken hârap

Eylesin şarkılar,gerçeği serap...

Meyhaneci bana verdiğin şarap,

Kırılmaz buzları,çözsün bu gece...

Durmayın dostlarım,hâlimi yazın...

Vur teline Hâşim,inlerken sazın; 

Aklımı başımdan uçuran kızın,

Hayâli kalbimde gezsin bu gece...', 'Tutmuyor ellerim,kalemlerimi Hâlimi sâkiler,yazsın bu gece Anlatmakla olmaz; elemlerimi Bir ressam elleri,çizsin bu gece Duydukça,mâziden ye...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Pangal']::text[], 8.5, '{"poet":"Yusuf Pangal","poet_slug":"yusuf-pangal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bu-gece-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ört Beni', 'ort-beni-sinan-eldem-51ixl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '/Çalan her kapının tokmağı ben olayım, beni tutan sen,

Gidilen sen ol tüm kaçışlarda, firari ben! /

Bu iklim tanıdık sana,

Ki tüm rüzgârlar sana eser.

Yürürsün usul usul esintisinde

Tüm yolların bana çıkar-

sa sığınırız çift kişilik hazlara.

Ayazlarına yaslanırız aşina sokakların

Gece üşür-

se üşürüz beraber, tenimde soğur terin! 

/Dudaklarında durur cefakâr susuşların,

Yeni bir aşka davettir çocuksu bakışların! /

Sağarız alazında kaldığımız karanlıkları,

Memelerin iri bir tutunmak olur içimdeki açlığa.

Tutunucak yerini bulamazsak hayatın

Avuçlarımız boş kalır-

sa tutunduğum bacakların olur

Sen asılırken boynuma.

Yüzümüze kapanan kapıları kimse açmaz-

sa sevişiriz biz de savaştığımız tüm meskünlarda! 

/Soyundum tüm kabuklarımdan, saçlarınla ört beni,

Sevişecek dermanın kalmadıysa, gözlerimden öp beni! /

29/1/2004', '/Çalan her kapının tokmağı ben olayım, beni tutan sen, Gidilen sen ol tüm kaçışlarda, firari ben! / Bu iklim tanıdık sana, Ki tüm rüzgârlar ...', ARRAY['Türk Edebiyatı','Şiir','Sinan Eldem']::text[], 8.5, '{"poet":"Sinan Eldem","poet_slug":"sinan-eldem","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ort-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk', 'cocuk-sadik-softa-w6a83', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bakışların puslu, kaşların çatık,

Ağlamaya hazır gibisin çocuk.

Üstünde ürkeklik, boynun da bükük,

Yetim gibi, öksüz gibisin çocuk.

Dertler birikmişler, tam bir düzüne,

Hüzün perdesini çekmiş yüzüne,

Bakışların gömülmüşler hüzüne,

Yetim gibi, öksüz gibisin çocuk.

Minicik ellerin hüzün mü tutar? ! 

Yüzündeki maske saflığı yutar,

Bakışını çilelerden çek, kurtar,

Yetim gibi, öksüz gibisin çocuk.

Çileye bürünmüş, gama bilenmiş,

Bakışların çile, sanki dillenmiş,

Gülücükler hani senin kölenmiş,

Yetim gibi, öksüz gibisin çocuk.

19.11.2003', 'Bakışların puslu, kaşların çatık, Ağlamaya hazır gibisin çocuk. Üstünde ürkeklik, boynun da bükük, Yetim gibi, öksüz gibisin çocuk. Dertler ...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cocuk-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerim Seni Aradı', 'gozlerim-seni-aradi-sadik-softa-ggt2g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerim hep eni aradı; 

Gecenin mahmurluğunda.

Kaybolan saatlerin ardından,

Saat geceye merdiven dayadı; 

Gözlerim hep seni aradı.

Tortulaştıkça tortulaştı; 

Yalnızlık kabuk bağladı.

Kırıldı zembereği, çarkı tıkandı; 

Sensizlik gözlerime yamandı; 

Yalnızlık kabuk bağladı.

Bir heyüla gibi dikildi zaman; 

Sehere vardı, uzadı da uzadı; 

Dudaklarım adını yamadı; 

Sabaha merdiven dayadı; 

Gözlerim hep seni aradı.', 'Gözlerim hep eni aradı;  Gecenin mahmurluğunda. Kaybolan saatlerin ardından, Saat geceye merdiven dayadı;  Gözlerim hep seni aradı. Tortulaş...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gozlerim-seni-aradi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülnâme', 'guln-me-omer-albayrak-53930', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Râbbil âlemin’sin sırrı kâinat! 

Senin eserindir bütün mahlûkat.

Himmetine muhtaç mü’min, müminat,

Dilimizde tekbir, tahmid, telbiye; 

Lûtfu kereminle çıkar cezbeye! ..

Nebiler, nebisi Resûl-i zişan,

En büyük muzize Hazreti Kur’an.

Şükürsüz, zikirsiz koyma Yaradan! 

Dilimizde tekbir, tahmid, telbiye; 

Lûtfu kereminle çıkar cezbeye! ..

Taa Bezm-i eleste eyledim iman,

Bütün kâinatı sensin Yaradan.

Mîzan’da, Sırat’ta etme perişan! 

Dilimizde tekbir, tahmid, telbiye; 

Lûtfu kereminle çıkar cezbeye! ..

Yâ Rabb senden olur ancak hidâyet; 

Her günümüz bir Leyle-i Kadir’et! 

Vuslat düğününe dönsün kıyamet.

Dilimizde tekbir, tahmid, telbiye; 

Lûtfu kereminle çıkar cezbeye! ..

Müctehidi eyle aklın, irfanın

Hikmet deryasında yıka imanın.

Fitnesinden halâş eyle şeytanın,

Dilimizde tekbir, tahmid, telbiye; 

Lûtfu kereminle çıkar cezbeye! ..

Mağfiret kapından kovma Ömer’i,

Cennet-ül Muallâ olsun makberi.

Ashâb-ı güzin’le içsin Kevser’i.

Dilimizde tekbir, tahmid, telbiye; 

Lûtfu kereminle çıkar cezbeye! ..

* 22 Mayıs 2003 *', 'Râbbil âlemin’sin sırrı kâinat!  Senin eserindir bütün mahlûkat. Himmetine muhtaç mü’min, müminat, Dilimizde tekbir, tahmid, telbiye;  Lûtfu...', ARRAY['Türk Edebiyatı','Şiir','Ömer Albayrak']::text[], 8.5, '{"poet":"Ömer Albayrak","poet_slug":"omer-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gulname-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ayrılık Dansı', 'bir-ayrilik-dansi-sadik-softa-sid46', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir kara sis içinde, dağ yamaçları,

Boz renkli, yeleli kurtlar misali.

Kan çanağına döner gözlerim,

Meydan okur acılara yeni baştan; 

Kara bulutlar misali kararır,

Kararır başım, dağ başı gibi.

Duygu kabarır... Coşkuludur; 

Şimşekler çıkar gözlerimden; 

Ulgar Dağları''na dönük yönüm; 

Turnalarla dertleşirim yürekten,

Yıldız ışıkları sönüp kaybolur; 

Kararır başım, dağ başı gibi.

Ay kaybolur, zifiri karanlık; 

Yalnızlık kabuk bağlar,

Çakmak çakmak olur gözlerim; 

Kalemle buluşmuş parmaklarım,

Zirvesindeyim hasretin, ayrılığın; 

Kararır başım, dağ başı gibi.', 'Bir kara sis içinde, dağ yamaçları, Boz renkli, yeleli kurtlar misali. Kan çanağına döner gözlerim, Meydan okur acılara yeni baştan;  Kara b...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-ayrilik-dansi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-Bilirim-', 'bilirim-mehmet-ozkilinc-ld67e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senin hayalinle geçen yaşamın

Açılarla dolu olduğunu bilirim

Anlamsız geçen bu yaşamın ardından

Yetirilmemiş umutları bilirim

Sensizlik içinde olan bu arayış

Nereye kadar sürecek bilemem

Düşüncemdeki her anın bile 

Umutlara gebe olduğunu bilirim

Senin sevgine tutsak olan bu beden 

Seninle bulur neşe kaynağını

Haykırsam ıssız gecelere seni

Aydınlanan dünyamı bilirim

Yanımda hiç bulunmamış olmasanda 

Senin hayelinle avunur bu gönlüm

Kavuşacağım günün aşkını 

Hasretini çeke çeke bilirim

Seni bulmak için çıktığım yolda 

Ardı sıra dikilmiş açıları gördüm

Ömüme çıkan her engelde 

Sana kavuşacağımı bilirim

Hasretinle yanan bu kalbim 

Açıları tattığını bilirim

Seni bir anlık görmemde

Açıların bittiğini bilirim

Oysa ne kadar uzaktım sana 

Bilmeden gidiyorum bu yolda

Ne olur hep karşıma çıksan

Senin sen olduğunu bilirim 

Yalnız kendime anlatırdım seni

Dinmek bilmeyen bir korkuyla

Bu korkunun verdiği cesaretle

Seni bir gün bulacağımı bilirim

Sana bir gün kavuşacağımı bilirim

MEHMET ÖZKILINÇ

07/08/2002', 'Senin hayalinle geçen yaşamın Açılarla dolu olduğunu bilirim Anlamsız geçen bu yaşamın ardından Yetirilmemiş umutları bilirim Sensizlik için...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özkılınç']::text[], 8.5, '{"poet":"Mehmet Özkılınç","poet_slug":"mehmet-ozkilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/bilirim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımız', 'askimiz-emin-baydil-22uuv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir doğum sancısıdır, içimizi yakan aşk,

Altımızda yürüyen, bir zaman merdiveni.

Görürüm, az ötede birleşir yollarımız,

Vuslatına katmakmış, gurbetin derdi beni.

Doğar Güneş’ten erken, gecenin seherinde

Kollarını kaldırır, göklere tan yerinde.

Yedi kat semânın da gördüm en derininde,

Tüllenmiş, yârim orda, aşk ile sardı beni.

Uzattığım kalbimdi, bir bayram hediyesi

Bir şiirdi belki de içinde aşkın sesi.

Gönlünün esiriydim, altındandı kafesi,

Çiçeklerden seccade altıma serdi beni.

Şimdi, tut ellerimi Cennet bahçesi yakın

Artık coşmak vaktidir, can kuşlarında akın

Salıncaklar kurulsun bizi orda bırakın,

Ebem kuşağı tutup yolunca verdi beni.

Beğdili’yim ne desem bilmem ki, cananıma

Kelebekler kıskansın, gel otur bir yanıma.

Gönlüm aşkınla mesttir, bakma sen giryanıma

Seni uzaklar almış, dağların ardı benim.

                              01.02.2004-Kastamonu', 'Bir doğum sancısıdır, içimizi yakan aşk, Altımızda yürüyen, bir zaman merdiveni. Görürüm, az ötede birleşir yollarımız, Vuslatına katmakmış,...', ARRAY['Türk Edebiyatı','Şiir','Emin Baydil']::text[], 8.5, '{"poet":"Emin Baydil","poet_slug":"emin-baydil","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/askimiz-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğluma', 'ogluma-sukru-demir-n39ix', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Birgün büyüyeceksin 

hep ağlarken

gülmeyi öğreneceksin

babam yok diyeceksin

taşlı yollarda koşarken

çamurlu yollarda yuvarlanırken

babam yok diyeceksin

işte hayat böyle büyütecek seni.

Bir çocuğu babasıyla gördüğünde

başını bacakların arasına alıp

ağlayacak

isyan edecek

babam yok diyeceksin

işte hayat böyle büyütecek seni.

Baba hasretinde yanarken

okulda gizli gizli ağlarken 

sevdiğin biri karşına çıkacakken

uzaklaşıp kaçmak isteyecek

haykıracaksın 

sevmek istemiyorum diyerek

babam yok diyeceksin.

Unutma oğlum ağlarken güleceksin.

Birgün ölsem

ne sana ne kardeşine

hanlar hamamlar

yatlar katlar bırakamayacağım

kucağıma alıp sevemesemde

seninle koşup oynayamasamda

kimsenin bırakamayacağı kadar 

yüreğimi ve sevgimi bırakacağım.

Hayatın taşlı yollarında koşarken

ağlayarak gülmeyi öğreneceksin.', 'Birgün büyüyeceksin  hep ağlarken gülmeyi öğreneceksin babam yok diyeceksin taşlı yollarda koşarken çamurlu yollarda yuvarlanırken babam yok...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Demir']::text[], 8.5, '{"poet":"Şükrü Demir","poet_slug":"sukru-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ogluma-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söz ver bana', 'soz-ver-bana-mehmet-ozkilinc-102uv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Saflığınla kal öyle

Tertemiz yüreğin kirlenmesin

Yalansız dünyandaki bahara 

Kirli eller deymesin

Seni anlamayan bu dünyada 

Sana yalan söylenecek

Umutların bir bir yok olacak 

Sende küçümseneceksin

Hadi söz ver bana

Büyümeye özenme

Hadi söz ver bana 

Büyümeye özenme

Ezilirsin anlamsız dünyada 

Hayat zindan bazen sana 

Çekilirsin belkide yanlızlığa

Yalnızlık güzel gelir sana

Zaman olur kalbin kırılır 

Dünyan başına yıkılır

Umutların tek tek söndürülür

Hayata bakışın değişir

Ahhh! bir anlayabilsen beni 

Sana ne sölemek istedimi

Belki bir gün anlayacaksın

Vakit çoktan bitmiş olacak

Hadi söz ver bana 

Büyümeye özenme

Hadi söz ver bana 

Büyümeye özenme

Ezilirsin anlamsız dünyada 

Hayat zından olur sana

Çekilirsin belkide yalnızlığa

Yalnızlık güzel gelir sana 

HADİ SÖZ VER BANA 

BÜYÜMEYE ÖZENME! ! ! ! 

24/03/2003', 'Saflığınla kal öyle Tertemiz yüreğin kirlenmesin Yalansız dünyandaki bahara  Kirli eller deymesin Seni anlamayan bu dünyada  Sana yalan söyl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özkılınç']::text[], 8.5, '{"poet":"Mehmet Özkılınç","poet_slug":"mehmet-ozkilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/soz-ver-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece', 'bu-gece-omer-albayrak-nquar', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dostun eşiğine koydum başımı,

Bastıkça ezilip tozdum bu gece.

Yâr dizinde tâbir ettim düşümü,

Nazı niyâz sanıp üzdüm bu gece.

Nefsin îdamına kırdım kalemi,

Sevgime sermâye yaptım çilemi,

Kâinatta saklı binbir gizezemi; 

Yumak yumak sarıp çözdüm bu gece! ..

Damlaya karışıp deryaya aktım,

Karanlığa dalıp, ışığa çıktım.

Yokluk aynasında, Varlığa baktım.

Benliğim eritip süzdüm bu gece.

Türk’ü, Türkçe Yesevi’den dinledim,

Yunus’larla asırlara ünledim,

Semâzenle coştum, neyle inledim; 

Gönül atlasını gezdim bu gece.

Kimisi şems idi, kimi Mevlânâ; 

Can attım, canların halvetgâhına.

Hâli pür-melâlim, şahlar-Şahı’na:

Kâğıtsız, kalemsiz yazdım bu gece.

Saf saf dizi dizi Kırklar, Yediler; 

Ilâhî vecd ile sarhoş idiler.

Köhne cesedime can üflediler,

Sırlar deryasında yüzdüm bu gece.

Binbir Alperen’li irfan ordusu,

Sundular Ömer’e bir cam dolusu.

Âbı-hayat mıydı yoksa Bengisu? 

Kana kana içip sızdım bu gece! ..', 'Dostun eşiğine koydum başımı, Bastıkça ezilip tozdum bu gece. Yâr dizinde tâbir ettim düşümü, Nazı niyâz sanıp üzdüm bu gece. Nefsin îdamına...', ARRAY['Türk Edebiyatı','Şiir','Ömer Albayrak']::text[], 8.5, '{"poet":"Ömer Albayrak","poet_slug":"omer-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bu-gece-64-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Feryadın Inkılâbı', 'feryadin-inkil-bi-omer-albayrak-fevdf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönül ne of dinler nede amanı,

Ölümle mühürlü aşkın fermanı.

Menzil-i Mâşuk-sa çilenin sonu,

Sevdikçe kıskanır kıral çobanı.

Aşkın ateşinde gonca gül açar,

Güle hasret çeken bülbül kan kusar.

Seven adamışsa canı, canana; 

Kurban Ismail’de olsa boğazlar.

Mecnun olabilmek Kays’ın hüneri,

Kutlamak gerekir böyle zaferi.

Kâinat güzeli olsa bakamaz; 

Mevlâ’ya yönelen gözlerin feri.

Mansur’un kanıyla yunmuş ceseti,

Kaç sevdalı öder böyle diyeti? 

Ferhat gibi kayalarıdırır,

Aşıksın, mâşuka olan hasreti.

Ömer, Kerem gibi yanar tutuşur,

Bine bölsen kalbi BIR de buluşur.

Gün gelir Hızır’la, Ilyas misâli,

Seven, Hakkın cemâline kavuşur! ..', 'Gönül ne of dinler nede amanı, Ölümle mühürlü aşkın fermanı. Menzil-i Mâşuk-sa çilenin sonu, Sevdikçe kıskanır kıral çobanı. Aşkın ateşinde ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Albayrak']::text[], 8.5, '{"poet":"Ömer Albayrak","poet_slug":"omer-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/feryadin-inkilabi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Mayıs Sabahı', 'bir-mayis-sabahi-ahmet-aksoy-f3153', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'onlar asıldılar

….ve bir ideoloji ağacında

üç meyva gibi duruyorlar.', 'onlar asıldılar ….ve bir ideoloji ağacında üç meyva gibi duruyorlar....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/bir-mayis-sabahi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meçhul Sevgiliye', 'mechul-sevgiliye-ajda-meseli-5d5rz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gün, göz gözü görmez olunca...

Hasret, dalgın rüzgar misali esecek baş ucunda.

Bir an, arkanı dönüp maziye bakacaksın şöyle bir; 

İşte o zaman dargın hatıralar belirecek karşında.

Bir garip hüzün kaplayacak içini...

O an, hasreti yudum yudum içeceksin, zehir gibi.

İçinde bir umutsuzluk filizlenecek yavaş yavaş,

Pişmanlık çığlıkları, delecek yüreğini.', 'Bir gün, göz gözü görmez olunca... Hasret, dalgın rüzgar misali esecek baş ucunda. Bir an, arkanı dönüp maziye bakacaksın şöyle bir;  İşte o...', ARRAY['Türk Edebiyatı','Şiir','Ajda Meşeli']::text[], 8.5, '{"poet":"Ajda Meşeli","poet_slug":"ajda-meseli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mechul-sevgiliye-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygular', 'duygular-ajda-meseli-4hdcc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bunlar ilham saatleri dostlar.

Bir ırmak gibi coşar duygular.

Derken, birer birer dökülür mısralar.

Ve böyle anlarda yaşar, en sıradan olanlar.

''Unuttum''dedikleriniz canlanıverir.

En sönük kalan aşk dahi bir meş''ale oluverir.

Ve yandıkça yanar, coşar duygular...

Bir kibrit alevidir, bu yangına sebep olan.

Bazen engin bir denizdir duygular.

Rüzgarda, hırçın dev dalgaları andırırlar.

Hani bazen deniz durulur da, çarşaf gibi olur ya...

İşte o zaman, dertlerine derman dost arar duygular.

En masum anlarda, rengarenk çiçeklerdir duygular.

Dertler biriktiğinde, güçlü bir çığlıktır içimize dolan...

Acı tek bir söz ile mahvolur, kırılır duygular.

Tatlı bir sözde ise petek petek baldır duygular.

İşte gecenin geç saati; 

Duygular, beni yazmaya zorlar.

Yazmayacağım desen, ilham perisi gelmez bir daha

Ve küser, incinir bana duygular...

Kaçırmamak gerek,

Bunlar ilham saatleri dostlar.', 'Bunlar ilham saatleri dostlar. Bir ırmak gibi coşar duygular. Derken, birer birer dökülür mısralar. Ve böyle anlarda yaşar, en sıradan olanl...', ARRAY['Türk Edebiyatı','Şiir','Ajda Meşeli']::text[], 8.5, '{"poet":"Ajda Meşeli","poet_slug":"ajda-meseli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/duygular-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kulak Ver', 'kulak-ver-ajda-meseli-m255y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir kelebek kadar narindir yüreğim.

İncitme yar, incitme.

Sar beni kollarına usulca...

Ve kulak ver yüreğime! 

Narin narin kanat çırpışları, sana.

Senin sevda denizine düştü yüreğim.

Ne olur, onun sıcaklığını sakla.

Ve kulak ver! 

Dalga dalga sevda sözleri, sana.

''İlle de sen'', diyor nazlı yüreğim.

Usul usul ağlıyor yalnız kalınca.

Kulak ver! 

''Sen sen'' diye çarpan yürek atışları, sana.', 'Bir kelebek kadar narindir yüreğim. İncitme yar, incitme. Sar beni kollarına usulca... Ve kulak ver yüreğime!  Narin narin kanat çırpışları,...', ARRAY['Türk Edebiyatı','Şiir','Ajda Meşeli']::text[], 8.5, '{"poet":"Ajda Meşeli","poet_slug":"ajda-meseli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kulak-ver-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Insanlar', 'biz-insanlar-suat-atar-v40o8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Insana iylik gelmiyor

Aci sözler yürek deliyor

Herkes bir birini ardindan vuruyor

Dedikodular basini almis gidiyor.

Neden biz Insanlar böyleyiz 

Yalanlarla kalbler kirariz 

Kötü konusani dost 

Iyi konusani düsman biliriz.

Bir Insani iyi huylu görünce 

Ne safmis deyip kullanmaya kalkariz

Bilmezlerki gercek dost odur

Cünkü icinde kötülük yoktur.

Kötü konusana iyi söz söylemistir

Ona bir adim gelene o iki adim gitmistir

Düsmana karsilik olarak dostluk vermistir

Ama yinede kiymeti bilinmemistir.

Bu dünyada iyi olmayacaksin

Düsene birde sen vuracaksin 

Sade kendi cikarin icin calisacaksin

Sanki sen mi bu dünyayi kurtaracaksin! ! ! ! ! ! ! ! !', 'Insana iylik gelmiyor Aci sözler yürek deliyor Herkes bir birini ardindan vuruyor Dedikodular basini almis gidiyor. Neden biz Insanlar böyle...', ARRAY['Türk Edebiyatı','Şiir','Suat Atar']::text[], 8.5, '{"poet":"Suat Atar","poet_slug":"suat-atar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/biz-insanlar-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağışla Beni Gün', 'bagisla-beni-gun-zafer-zengin-etnika-vvsjw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bağışla beni gün

Yetişemedim

Doğuşuna.

        öksüz kalmadın ya! 

Bağışla,

Gece yaşamıştım hayat''ı

Bağışla

        Ayaz''a kalmadın ya! 

Bağışla beni gün

Sen büyürken,

          Ben yaşlandım ya! 

Bağışlada,sırtımı döneyim

İçimde uslanmaz adama

         Aşksız kalmadın ya! 

21.01.2004', 'Bağışla beni gün Yetişemedim Doğuşuna.         öksüz kalmadın ya!  Bağışla, Gece yaşamıştım hayat''ı Bağışla         Ayaz''a kalmadın ya!  Bağ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bagisla-beni-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgimin Eseri', 'sevgimin-eseri-ajda-meseli-qv8m5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sende yaşıyorum aşkın sihirli tesirini...

Yıllanmış şarapların acılığındadır eskiler.

Kelebek misali hassastır ruhum

Düşünürken seni...

Bakma; zaman zaman kızdığıma 

Ve bu kadar alıngan olduğuma...

Her hassas yanım, sevgimin bir eseridir aslında.

Telefonlarını beklemezdim gecelerce...

Gönül vermeseydim sana.

Bir nimettir sesini duymak,

Ve aşkını hissetmek ılık ılık deli yüreğimde.

Bakma; sana bu kadar soğuk davrandığıma...

Seninle geçen her anımda,

Duygularımın esiriyim, anlamasan da.', 'Sende yaşıyorum aşkın sihirli tesirini... Yıllanmış şarapların acılığındadır eskiler. Kelebek misali hassastır ruhum Düşünürken seni... Bakm...', ARRAY['Türk Edebiyatı','Şiir','Ajda Meşeli']::text[], 8.5, '{"poet":"Ajda Meşeli","poet_slug":"ajda-meseli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevgimin-eseri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-ajda-meseli-vuxyg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dalıp dalıp hayallere

Düşüyorum sensizliğe.

Özlemin sımsıkı sarıyor beni; 

Sensizlik, demir aldı bu gece.

Bu gece kaldım karanlıklar içinde.

Sensizlik, benziyor hayatın gri rengine. 

Özlemin bir mum ışığıdır hayalimde; 

Sensizlik, karanlığın esiri bu gece.

Gözlerimden akan yaşlarda 

Yağmur gibi sensizlik bu gece.

Soğuk yatağımda dalıyorum hayallere; 

Sensizlik, seni aldı bu gece.', 'Dalıp dalıp hayallere Düşüyorum sensizliğe. Özlemin sımsıkı sarıyor beni;  Sensizlik, demir aldı bu gece. Bu gece kaldım karanlıklar içinde....', ARRAY['Türk Edebiyatı','Şiir','Ajda Meşeli']::text[], 8.5, '{"poet":"Ajda Meşeli","poet_slug":"ajda-meseli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sensizlik-105-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya sahnesi', 'dunya-sahnesi-suat-atar-nuoyr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her sevmede simsek gibi caktik gectik,

Sönmüs nice vulkanlari yaktik gectik,

Aslinda su dünya denilen sahneye biz ciktik diyemem,

Sadece baktik, gördük ve gectik! ! ! ! ! ! ! ! ! !', 'Her sevmede simsek gibi caktik gectik, Sönmüs nice vulkanlari yaktik gectik, Aslinda su dünya denilen sahneye biz ciktik diyemem, Sadece bak...', ARRAY['Türk Edebiyatı','Şiir','Suat Atar']::text[], 8.5, '{"poet":"Suat Atar","poet_slug":"suat-atar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dunya-sahnesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Birden Sonra', 'gece-birden-sonra-ajda-meseli-7fl61', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaşıyorum gece birden sonra...

Bana sormayın serin sabahları.

Ya da gün ışığında şehrin gürültüsü nedir? 

Derseniz, bilemem.

Yaşıyorum gece birden sonra...

Yazmama izin veren ağaçlar sağolsun.

Ağaçlar diyorum,

Yoksa derdimi dökecek kağıt mı bulurdum? 

Yaşıyorum gece birden sonra...

Kalemi de icat edenler sağolsun.

Hatta dürüst yaşayan herkes sağolsun...

Ben de düşünmek ve düşündüklerimi yazmak için varım.

Yaşıyorum gece birden sonra...

Uykuyu da severim hani.

''Yaz, yaz'' dedikçe içimdeki ses,

Nasıl bırakırım kalemi? 

Önce şiir, sonra uyku.

Birden sonra geceleri...

Anlat gönlüm derdini, vefasız sevgilini...

Ve daha nice aklına geleni...

Anlat gönlüm,

Şiirin vazgeçilmezliğini...

Anlat gönlüm anlat...

Kısaca; birden sonra geceleri,

Hayat güzel.', 'Yaşıyorum gece birden sonra... Bana sormayın serin sabahları. Ya da gün ışığında şehrin gürültüsü nedir?  Derseniz, bilemem. Yaşıyorum gece ...', ARRAY['Türk Edebiyatı','Şiir','Ajda Meşeli']::text[], 8.5, '{"poet":"Ajda Meşeli","poet_slug":"ajda-meseli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gece-birden-sonra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Halk Ne İstiyor?', 'halk-ne-i-stiyor-yusuf-ziyaeddin-sivaslioglu-usqr4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Halk

Ne  Bey  istiyor

Ne  de  Beyzade

Halk

Kendinden  birini  istiyor

Hazır  ise  hizmete

Devletin  gündemi  başka

Milletin ki  başka

Devlet  güvenlik  derdinde

Halk  muhtaç  aşa

Hortum  davaları

Bulurken  yüzleri

Demokrasi  diye

Yutturdular  bu  düzeni

DGM''ler çete  doldu

Hapishaneler  taştı

Batıyorken  bankalar

Devlet  el  açtı

Gelin  barıştıralım

Devlet  ile  Milleti

Böyle  gelmiş

Böyle  gitmez

Kuralım  hakça  düzeni

(İstanbul, 2 Şubat 2004)', 'Halk Ne  Bey  istiyor Ne  de  Beyzade Halk Kendinden  birini  istiyor Hazır  ise  hizmete Devletin  gündemi  başka Milletin ki  başka Devlet...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziyaeddin Sivaslıoğlu']::text[], 8.5, '{"poet":"Yusuf Ziyaeddin Sivaslıoğlu","poet_slug":"yusuf-ziyaeddin-sivaslioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/halk-ne-istiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşlarım', 'kuslarim-yusuf-ziyaeddin-sivaslioglu-epkhl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ak  başlı

Alacalı,  beyazlı

Taklacı  kuşlarım

Herbirinizin  hatırasını

Kalbimde  saklarım

Papaklı, paçalı

Mardinli, Urfalı

Postacı  kuşlarım

Yaşlandım  bakamam  artık

Gönül kafesinde  beslerim

Kanat  sesin

Kabararak  ötüşün

Aşıklar  gibi  öpüşün

Gökyüzünde  süzülüşün

Sadece  yokluğun

İçimdeki  hüzün

(İstanbul, 2 Şubat 2004)', 'Ak  başlı Alacalı,  beyazlı Taklacı  kuşlarım Herbirinizin  hatırasını Kalbimde  saklarım Papaklı, paçalı Mardinli, Urfalı Postacı  kuşlarım...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziyaeddin Sivaslıoğlu']::text[], 8.5, '{"poet":"Yusuf Ziyaeddin Sivaslıoğlu","poet_slug":"yusuf-ziyaeddin-sivaslioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kuslarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yengem Fevziye''ye', 'yengem-fevziye-ye-ajda-meseli-zt9a7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir yengem vardı benim.

Adı Fevziye...

Geceleri geç yatar, sabahları erken kalkardı...

Şu dünyanın çalışma faslı, en çok ona bakardı.

Kimseye tek bir acı sözü yoktu onun.

Tanımazdı kötülüğün K''sini.

Bir melekti o, aynı zamanda bir sabır taşı.

Beni kollarına alırdı ne zaman görse...

Onca işi arasında mısır patlatırdı bana...

Ne masallar anlatırdı.

Bu gece birden aklıma geliverdi.

Okurken ölümün yorumunu kitaptan...

Yüreğimde ani ve derin sızılar oluştu,

O zalim geçen yıllardan sonra.

Çocukluğumun büyük bir kısmı geçti onunla...

Yanıma koşardı, şehirden geldiğimi duyunca.

Anlat bakalım, derdi; ''Ne var ne yok oralarda? ''

''Özlemedin mi bizleri? '' Zamandan geçti bir hafta...

Sonra biraz muhabbet, biraz kahkaha

''Gel, bize gidelim'' diye sözü bağlardı sonunda.

Hadi ama, herkes var, bir sen yoksun sofrada...

Son görüşmemiz geldi şimdi de aklıma...

Bir veda anıydı.

Kimseyle kucaklaşmamıştım ondan başka.

''Seni bir daha nerede göreceğim? '' dedi,

Ve ikimizin de gözyaşı karıştı yağmura...

İçim bir garip oldu. İlk defa ağlarken gördüm onu...

En son; beni unutamadığını yazmıştı, gönderdiği mektupta.

Doya doya ağlayamadım, göçtüğünü duyunca.

Tabutunu da göremedim, o giderken sonsuza.

''Kahretsin! '' dedim; 

Ne vardı sınırlar bizi ayırmasa...

Asıl acı olan ise; bir fotoğrafı bile yok,

Koyabileceğim baş ucuma.

Çok sevdiğim yengem, konuk bu gece mısralara...

Elimizden gelmiyor bir şey söylemek,

''Ruhun şad olsun'' demekten başka.

Zavallı yengem, hiç aklına gelir miydi ki,

Bir şiirde hayat bulacağını 

Yaşarken şu zalim dünyada? ...

Canım yengem benim,

Bu gece ölümsüzleştirdim seni...

Oturduğum masanın başında.', 'Bir yengem vardı benim. Adı Fevziye... Geceleri geç yatar, sabahları erken kalkardı... Şu dünyanın çalışma faslı, en çok ona bakardı. Kimsey...', ARRAY['Türk Edebiyatı','Şiir','Ajda Meşeli']::text[], 8.5, '{"poet":"Ajda Meşeli","poet_slug":"ajda-meseli","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/yengem-fevziye-ye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerinde Yaşamayı İsterdim...', 'gozlerinde-yasamayi-i-sterdim-halil-i-brahim-m56va', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerinde yaşamayı isterdim

Anlamsız,manasız değil; 

Kederden başka birşey vermeyen 

Hayat gibi...

gözlerinde yaşamayı isterdim

olsun,çözemesem de

gözlerinde yaşamayı isterdim

mutluluk saklı; taa derinlerinde

gözlerinde yaşamayı isterdim

bazen ela; bazen bal rengi

ama yok,hayır gözlerin sana ait

bambaşka bir renk

gözlerinde yaşamayı isterdim

doğrusu; sana o okadar yakın olmayı

herşeye senin gözünle bakmayı 

mutluluğu sevgiyi seninle paylaşmayı

bu hayatı benimle paylaşmanı isterdim', 'Gözlerinde yaşamayı isterdim Anlamsız,manasız değil;  Kederden başka birşey vermeyen  Hayat gibi... gözlerinde yaşamayı isterdim olsun,çözem...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim']::text[], 8.5, '{"poet":"Halil İbrahim","poet_slug":"halil-i-brahim","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gozlerinde-yasamayi-isterdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırk Beşinci Yaş Şiiri(Babama)', 'kirk-besinci-yas-siiri-babama-ajda-meseli-yhi4n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugün doğum günün.

Kutlu olsun! derim sana.

Yaşın kırk beş oldu, ne mutlu...

Eriyorsun yavaş yavaş hayatın baharına.

Diyeceksin ki, bahar dediğin ne ki? 

Ömrüme hakim olan hep kış güneşi.

Olsun, aldırma! Bu güneş, kış da olsa ısıtır seni; 

Tıpkı bir buzdağını eritir gibi.

Seni sevmek şereftir bana! 

Hayatta bilirim az çok çektiklerini, dertten yana.

Sen sen ol, sakın yenilme zamana! 

Fener ol ellerimde, hep yol göster bana...', 'Bugün doğum günün. Kutlu olsun! derim sana. Yaşın kırk beş oldu, ne mutlu... Eriyorsun yavaş yavaş hayatın baharına. Diyeceksin ki, bahar de...', ARRAY['Türk Edebiyatı','Şiir','Ajda Meşeli']::text[], 8.5, '{"poet":"Ajda Meşeli","poet_slug":"ajda-meseli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kirk-besinci-yas-siiri-babama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamın Çocuksu Sevinci', 'yasamin-cocuksu-sevinci-ajda-meseli-nrvsm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Önemli mi genç ya da yaşlı olmak? 

Yaşamın çocuksu sevincidir aslolan.

İşte onun tadını çıkarmaya bak

Tüm zamanlar içinde...

Hatta,''yalan'' dediğimiz şu yuvarlak içinde

En baş gerçek varsa budur; 

Az önce de değindiğim gibi:

''Yaşamın çocuksu sevinci vardır.''', 'Önemli mi genç ya da yaşlı olmak?  Yaşamın çocuksu sevincidir aslolan. İşte onun tadını çıkarmaya bak Tüm zamanlar içinde... Hatta,''yalan'' d...', ARRAY['Türk Edebiyatı','Şiir','Ajda Meşeli']::text[], 8.5, '{"poet":"Ajda Meşeli","poet_slug":"ajda-meseli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yasamin-cocuksu-sevinci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam Bir Masal Olsa Gerek', 'yasam-bir-masal-olsa-gerek-ajda-meseli-fdg98', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Pencereden bakıyorum,

Arabalar gelip geçiyor.

Benimse içimde sen,

Sen ve unutulmaz hatıralar...

Hayat, dışarıda başka türlü,

İçeride matem havası...

Zaman akıyor, hayat geçiyor dışarıda...

Benise içimde, bu hızlı akışı durduran

SEN.

Dedeciğim, şimdi anlıyorum; 

Bir varmışla bir yokmuşlu masallarını...

Daha dün şakalarına gülerken ben,

Bugün o buruk hatıra geldi aklıma

Ağlıyorum ben.

Bir gülmek, bir ağlamak...

Yaşamak belki de bundan ibaret.

Dönüyor dünya, bitiyor nice hayatlar...

Yaşam, bir masal olsa gerek.', 'Pencereden bakıyorum, Arabalar gelip geçiyor. Benimse içimde sen, Sen ve unutulmaz hatıralar... Hayat, dışarıda başka türlü, İçeride matem h...', ARRAY['Türk Edebiyatı','Şiir','Ajda Meşeli']::text[], 8.5, '{"poet":"Ajda Meşeli","poet_slug":"ajda-meseli","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yasam-bir-masal-olsa-gerek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostluğun Kalp Atışı(Melahat Abla''ya)', 'dostlugun-kalp-atisi-melahat-abla-ya-ajda-meseli-fpctq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir yürek atışıdır insanı hayata bağlayan...

Sevgiyle dolu bir yürek atışı.

Bir çiçeği koklamak bile çoğu zaman,

Derin bir mutluluk verir insana...

Çiçek solar, kurur günlerin ardından.

Yıllar sonra gülümser sana,

Tozlu bir defterin yaprakları arasından.

Apayrı bir anı tazelenir gözlerinde,

Seni apayrı duygulandıran.

Böyle bir dostluk işte, seninle yaşanan.

Her anı bir çiçek, sevgiyle koklanan.

Umutlar filizleniyor her saklanan hatıranın ardından...

Dostluğumuzun kalp atışlarını duydum, sonsuzluktan.', 'Bir yürek atışıdır insanı hayata bağlayan... Sevgiyle dolu bir yürek atışı. Bir çiçeği koklamak bile çoğu zaman, Derin bir mutluluk verir in...', ARRAY['Türk Edebiyatı','Şiir','Ajda Meşeli']::text[], 8.5, '{"poet":"Ajda Meşeli","poet_slug":"ajda-meseli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dostlugun-kalp-atisi-melahat-abla-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Firdevs''e Özlem', 'firdevs-e-ozlem-ajda-meseli-7wend', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gece kuşlardan aldım haberini.

İçimi ürpertti, acıklı acıklı ötüşleri.

Yüreğimde sen, baş ucumda sen, tüm kainatı kaplayan sen...

Görünürde çok uzaklardasın,

Aslında hemen yanı başımda yanan bir ateş kadar sıcaksın.

Bir rüyaydı sanki, geride kalan yıllar.

Bilmem ki ne alemdedir, eskitemediğimiz o tozlu yollar.

Hayat, bir varmış bir yokmuştan ibaret bir masal.

Seni görmeyeli, on yıl geçti aradan.

Pırıl pırıldı çocukluğumuz.

Güneş kadar sıcaktı dostluğumuz.

Yıldızlar mı kıskandı bizi, ne? 

Akıp giden yıllara sinmiş yokluğumuz.

Bana düşen şimdi, özlemek seni.

Her anışımda, hava bile değiştirir kendini.

Buram buram hüzün kokar her taraf...

Ortalıkta dolaşır yokuğunun çaresiz ayak sesleri.

Bazen, bir kuş olsam, diye geçer aklımdan.

Kanatlanıp sizin oraya, yanına uçsam.

Özlemin verdiği coşkuyla seni kucaklasam,

Seninle tatlı tatlı çocukluğumuzdan konuşsam.

İşte böylesi hayallerle avunurum kimi zaman...

Hiçbir şeyi özlemedim, seni özlediğim kadar.

Umudum var,

Bir gün bize de yol verecek dağlar...

Tek dileğim,

Yaşamını sarsın boydan boya mutluluklar.

Ankara''dan Ajda''dan sana kucak dolusu selamlar!', 'Bu gece kuşlardan aldım haberini. İçimi ürpertti, acıklı acıklı ötüşleri. Yüreğimde sen, baş ucumda sen, tüm kainatı kaplayan sen... Görünür...', ARRAY['Türk Edebiyatı','Şiir','Ajda Meşeli']::text[], 8.5, '{"poet":"Ajda Meşeli","poet_slug":"ajda-meseli","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/firdevs-e-ozlem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bende-yi dergâh-ı silm olduk selâmet bekleriz', 'bende-yi-derg-h-i-silm-olduk-sel-met-bekleriz-mustafa-tanrikulu-6csr4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bende-yi dergâh-ı silm olduk selâmet bekleriz

Mukteda-yı dîne tâbi''iz ki kâmet bekleriz.

Biz ki şahs-ı nefsi taltîf etmedik bunca zaman

Ehl-i su-i zann sanmış kim  imâmet bekleriz. 

Âb-ı der-geh katresi zannımca  zemzem gibidir.

İstemezim  ben su bârân-ı rahmet bekleriz.

Sevdiğim nûr işve-fûrûş; anlamaz derdim nedir 

Derdimin dermanıdır dâim muhabbet bekleriz.

Mustafâ derler bir âdem aşk sahrâsın gezer

Bir de diyormuş ki ''bu sahrâda nevbet bekleriz''', 'Bende-yi dergâh-ı silm olduk selâmet bekleriz Mukteda-yı dîne tâbi''iz ki kâmet bekleriz. Biz ki şahs-ı nefsi taltîf etmedik bunca zaman Ehl-...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tanrıkulu']::text[], 8.5, '{"poet":"Mustafa Tanrıkulu","poet_slug":"mustafa-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bende-yi-dergah-i-silm-olduk-selamet-bekleriz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Zamanı', 'siir-zamani-ajda-meseli-cc6ei', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu saatleri beklerim her gece.

Ağır ağır aralanır romantizmin kapıları,

Saat on ikiyi geçince.

Şimdi şiir vaktidir, deyip gizlice; 

Sessiz sessiz dalarım karanlığın içine. 

Ve aldığım gibi kalemi elime

Dökülür kelimeler, birer birer dizelere.

Kimi zaman yalnızlığımı, kimi zaman korkularımı,

Çoğu zaman da aşklarımı anlatırım 

Bu masum dizelere.

Açıldıkça açılır romantizmin kapıları; 

Coşar benliğim...

Ne varsa içimde yaprak misali dökülür,

Sır dolu defterin sahifelerine...', 'Bu saatleri beklerim her gece. Ağır ağır aralanır romantizmin kapıları, Saat on ikiyi geçince. Şimdi şiir vaktidir, deyip gizlice;  Sessiz s...', ARRAY['Türk Edebiyatı','Şiir','Ajda Meşeli']::text[], 8.5, '{"poet":"Ajda Meşeli","poet_slug":"ajda-meseli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/siir-zamani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Aşkın Bu...', 'senin-askin-bu-ajda-meseli-lp0dl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayalin belirir düşüncemde

Çoğu zaman...

Düşündükçe, seni sevdiğimi anımsarım; 

Kimi zaman...

Sevgiyle dolan yüreğim, hislerini dile getirir

Bazan...

Senin aşkın bu,

Zaman zaman bana şiirler yazdıran.', 'Hayalin belirir düşüncemde Çoğu zaman... Düşündükçe, seni sevdiğimi anımsarım;  Kimi zaman... Sevgiyle dolan yüreğim, hislerini dile getirir...', ARRAY['Türk Edebiyatı','Şiir','Ajda Meşeli']::text[], 8.5, '{"poet":"Ajda Meşeli","poet_slug":"ajda-meseli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/senin-askin-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Çocuk Kalplere Göre Değil', 'ask-cocuk-kalplere-gore-degil-umut-ulbegi-78lai', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çocuk kalbime

son oyuncağım kaçtı

şehrin en eski oyuncakçısı için bile

aşk

gözlerde telaş,

ölüm kadar yavaştı.

Kalbim

sıkışırken 

küçük işlere bakmak

geçti aklımdan

susadığım kadın

soğuk, donuk gözleriyle

bana baktı.

'' Sana hiç öyle bakmadım diyorsun, duyuyorum.''

''Aşk

çocuk kalplere göre değil''

diye fısıldadı içimdeki sessiz sancı

kapanan kapının altından 

kırmızı

siyah

kan geçişlerinde

kalbimden söktüğüm oyuncağın

suskun salınışı kaldı.', 'Çocuk kalbime son oyuncağım kaçtı şehrin en eski oyuncakçısı için bile aşk gözlerde telaş, ölüm kadar yavaştı. Kalbim sıkışırken  küçük işle...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ask-cocuk-kalplere-gore-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebeğim', 'bebegim-i-brahim-ethem-bingul-pkjse', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Günlerden bayrammış kimin umurunda,

Sordum bugün sana

Bebeğim ömrümü verdim sana

İstersen değil ömrümü, canımı veririm sana

Birkez olsun sevgilim dermisin bana

O gizli kalmış,

Utangaç yüreğinin arkasına saklanmış

Belki de, sevdanla sarhoş

Ama hiç vekarını bozmadan

Bebeğinim bundan sonra,

Seni seviyorum demiştin, sen bana

Bebeğim, işte şimdi bayram bana...', 'Günlerden bayrammış kimin umurunda, Sordum bugün sana Bebeğim ömrümü verdim sana İstersen değil ömrümü, canımı veririm sana Birkez olsun sev...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bebegim-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değerlerim..', 'degerlerim-ferit-teksoy-6a0tb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Doğru yönden esmiyorsa rüzgarım

Yerimde sayarım yelken açamam

Sığınacak liman,liman değilse

Atacak çapayı,ipi istemem

Alın teri,emek..iki kutsalım

Haksız olsun ama olsun diyemem

Şişkin cüzdan yada ün için

Bin yalan kıvıran tipi istemem

Kazanmanın karşılığı kaybetmek

Kaybetmeyi defterimden silemem

Helalinden olsun,varsın az olsun

Rüşvet ile olan işi istemem

Aç kalmaya razı olurum,fakat

Boğazıma dizilecek aşı istemem

Yastığa koyunca gece başımı

Kâbuslar görecek düşü istemem', 'Doğru yönden esmiyorsa rüzgarım Yerimde sayarım yelken açamam Sığınacak liman,liman değilse Atacak çapayı,ipi istemem Alın teri,emek..iki ku...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/degerlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ses', 'ses-birol-bayram-yrhi7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'SES

ses kulaktan kulağa

simsiyah bir halıyla kaplattığım

yüzümde,

  nerden çıktığı belli olmayan

    bir ses dinleniyor

      ısıtan ortalığı

       serin bir bahar sabahı

göz kırpımı kadar bir zamanda

yaklaşıyor seslerimiz birbirine

    bir kırpıyoruz gözümüzü

    gözümüzü bir daha açmıyoruz

yere bırakılmış

kalplerin üstünde

    dansediyoruz

      yere bırakılmış

        ve unutulmuş

          kalplerin...

sana dağlarımı anlatıyorum

günlerce, gecelerce

  içimdeki yanan ateşleri

  ateşlerin dağlardaki kırık yankılarını,

  ateş böceklerini,

  bana ihanet eden ben''leri,

  çeteleri, katilleri, hırsızları,

    gözlerimle...

bir büyü yerleşiyor

parmak izlerimize

gizlice

soru işaretlerinden bıkkın gözlerim

sükûnetin o sakin limanını

arıyor gözlerinde

  sükûnetin o sakin limanını

soru işaretleri

birbir çalıyorlar

aramızdaki büyüyü

  korkuyorum! 

    ellerimi bir çift yumruk halinde

    koltuk altlarıma saklıyorum! 

soru işaretleriyle

birer mil çekiyorsun yavaş yavaş gözlerime

kör oluyorum! 

  bir karanlık odada

  seni

  el yordamıyla

  seviyorum.

Birol Bayram', 'SES ses kulaktan kulağa simsiyah bir halıyla kaplattığım yüzümde,   nerden çıktığı belli olmayan     bir ses dinleniyor       ısıtan ortalığ...', ARRAY['Türk Edebiyatı','Şiir','Birol Bayram']::text[], 8.5, '{"poet":"Birol Bayram","poet_slug":"birol-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/ses-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-ahmet-aksoy-prbql', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bu vakitlerde, nereye gitsem,

olduğum yerden duyuluyor

……..çakalların uğultusu,

kurdukları meclislerde uluyorlar,

…ülkem ah benim ülkem,

çakalların bağdaş kurup oturduğu,

.ve sonrada doğa dedikleri düzen,

neden sonra düzelecek,

…..elbet düzelecek,

doğa dedikleri canavarlıklar

………bir gün devrilecek,

peki ya ben görecek miyim,

…..verilen kavganın

…………utkunu,

ruhum ölüme yenilmeden.', 'bu vakitlerde, nereye gitsem, olduğum yerden duyuluyor ……..çakalların uğultusu, kurdukları meclislerde uluyorlar, …ülkem ah benim ülkem, çak...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ozlem-139-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanma', 'sanma-huseyin-cayikli-yu4y5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'mevsim kış olup oturacağımı hayata küseceğimi sanma.uzaktasın bir nefes kadar oysa.yaşarım nede olsa.aşk uzaksa bu şehir biraz da körfez koksa çekilmez değil çekilir elbet sensizlik.biraz daha kahrolarak yazarım bir iki satırı senin için.mevsim kış olup oturacağımı sanma bir paket sigara eskimiş şarap anlatır seni ben yine yazarım eskimiş sayfalarıma tükenen murekebimle.', 'mevsim kış olup oturacağımı hayata küseceğimi sanma.uzaktasın bir nefes kadar oysa.yaşarım nede olsa.aşk uzaksa bu şehir biraz da körfez kok...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/sanma-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akar Oluktan Oluk', 'akar-oluktan-oluk-emin-baydil-rx606', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çıkarım yokuşları, ter içinde bedenim,

Her adımda bir başka, âlemle nefesteyim.

Caddeler kolay bana, inişleri n''edeyim

Meğer hayat çileymiş, altından kafesteyim.

Her nehirde bir girdap, almamışsa benden iz,

Bırakın karışayım, bir pınarın suyuna,

Elekten geçirmemiş, her zehri yutmuş deniz,

Artık, bırakın beni! .. Sonsuzluk uykusuna.

Dağ olalı her tümsek, aşmış kendi kendince

Gâripler mi? ! ... Vuslatın yollarını sormada.

Ne zaman verilecek? ! Hesabı ince ince,

Akıl... Habire akıl, dişlileri yormada.

Ne yapsam, kâr etmiyor; her vakit aklım zorda,

Hangi meçhul bir yerde, son bulur bu yolculuk.

Her daim kazar gönül, ölürse kalır orda

Geçer öteden öte, akar oluktan oluk...

Kastamonu-02.02.2004', 'Çıkarım yokuşları, ter içinde bedenim, Her adımda bir başka, âlemle nefesteyim. Caddeler kolay bana, inişleri n''edeyim Meğer hayat çileymiş,...', ARRAY['Türk Edebiyatı','Şiir','Emin Baydil']::text[], 8.5, '{"poet":"Emin Baydil","poet_slug":"emin-baydil","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/akar-oluktan-oluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Aşkın Mahzun Gözleri...', 'askin-mahzun-gozleri-naime-erlacin-hs47j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yangın akşamlarda kaybettik gözlerimizi

durgun denizlerin

uzağına düşürerek kendimizi

bir tek aşk doğmazdı küllerinden

biz

bir elde kürek

bir elde sabır

kâh içindeydik tutuşan aşkın

kâh terk-i diyâr ettik

kimyamız tuttu biliyorsun 

diyorum ki: 

şimdi kaybolsak

boşluğa karışsak

yok olsak meselâ

bilinmedik bir zaman

bilinmedik bir adreste

yine buluşuruz mutlaka

bunun adı gönül tutsaklığı

bunun adı 

karasevda olmalı

aldırma kararmalarıma

cemreler fışkırıyor yüreğimden

bir adım kala son durağa

yazılıyor aşka dair diller yeniden

sisli bir alemde 

gözü kapalı yolculuk ederken

güzergâhta bulduğum 

vazgeçilmez gölgemsin sen

güzel şeymiş aşk 

senden öğrendim

aşkın ebedi bekleyişinde

aşkın mahzun gözlerinden

bunun adı mukadderat olmalı

(2 Şubat 2004)', 'yangın akşamlarda kaybettik gözlerimizi durgun denizlerin uzağına düşürerek kendimizi bir tek aşk doğmazdı küllerinden biz bir elde kürek bi...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/askin-mahzun-gozleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-mustafa-sen-1-igbaa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bakır leğenlerimde 

gümüş fırtınalar esmiyor,

çocukluğuma giden kağıt gemilerime...

ve ben eski zaman heykellerinin yalnızlığını yaşıyorum 

hem de bir soluk ötende...', 'bakır leğenlerimde  gümüş fırtınalar esmiyor, çocukluğuma giden kağıt gemilerime... ve ben eski zaman heykellerinin yalnızlığını yaşıyorum  ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Şen 1']::text[], 8.5, '{"poet":"Mustafa Şen 1","poet_slug":"mustafa-sen-1","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ask-204-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-deniz-sevgi-i7bx7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'her zemheri bahara evirilir

her karanlık gün ışığına 

her uçurum kanatlanmaya

ve her acı güzel günlere 

yeter ki yüreğimizde eksik olmasın umudun sevinci', 'her zemheri bahara evirilir her karanlık gün ışığına  her uçurum kanatlanmaya ve her acı güzel günlere  yeter ki yüreğimizde eksik olmasın u...', ARRAY['Türk Edebiyatı','Şiir','Deniz Sevgi']::text[], 8.5, '{"poet":"Deniz Sevgi","poet_slug":"deniz-sevgi","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/umut-100-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklarıma...', 'cocuklarima-nergis-demet-kc14q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir bir yıkıldığını göreceksin,

onların,

onların güvendikleri dağların.

neyin,kimlerin yıkılması gerektiğini,

bilirsen.

neyin,kimlerin ayakta kalması

gerektiğini de.

bir de sabredebilirsen...

küskünlükle,

kırgınlıkla,

kızgınlıkla değil.

sevgiyle,umutla,sevinçle,inançla aşkla...

savaşabilirsen.

aynı zamanda,

zarif kalmayı başarabilirsen,

bir gün,

ne kadar haklı olduğunu,

beklediğine  değdiğini,

göreceksin.

dimdik,

dağ gibi ayakta dikilirken...', 'bir bir yıkıldığını göreceksin, onların, onların güvendikleri dağların. neyin,kimlerin yıkılması gerektiğini, bilirsen. neyin,kimlerin ayakt...', ARRAY['Türk Edebiyatı','Şiir','Nergis Demet']::text[], 8.5, '{"poet":"Nergis Demet","poet_slug":"nergis-demet","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/cocuklarima-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş''li günler...', 'gunes-li-gunler-nergis-demet-q5aqn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'güneşli günler yaşadık,

bir zaman.

onunla doğduk güne,

onunla battık geceye,

gün geldi,

başka dünyalara doğmak için,

mavi aydınlığını içimize,

bir parça ışığını avuçlarımıza,

bırakıp gitti.

yanmadı ellerimiz,

kokusu kaldı,gül gibi,

gün kokusu,

sadece...', 'güneşli günler yaşadık, bir zaman. onunla doğduk güne, onunla battık geceye, gün geldi, başka dünyalara doğmak için, mavi aydınlığını içimiz...', ARRAY['Türk Edebiyatı','Şiir','Nergis Demet']::text[], 8.5, '{"poet":"Nergis Demet","poet_slug":"nergis-demet","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gunes-li-gunler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taş Kilidi KIRIVERDİK...', 'tas-kilidi-kiriverdi-k-ozan-si-ar-agdasan-jvf1v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönül kapısın kapatan

Taş kilidi KIRIVERDİK

Petek ile sarmaş yatan

Çiçeklere ARIVERDİK! ...

Binler, on bölüm yüz tutmuş

Baharlar hazan güz tutmuş

Akan suyumuz, buz tutmuş

Karlı dağlar YARIVERDİK

Ağacı yer ağaç kurdu

Kalbimiz kanadı durdu

Sevdam on ikiden vurdu

Yaramızı SARIVERDİK

Şiar canana can deriz

Bağrımız açar gideriz

Özgürce uçar gideriz

Mavi Göğe VARIVERDİK! ....

Taş kilidi KIRIVERDİK

Çiçeklere ARIVERDİK! ....

Söz ve Müzik: Ozan ŞİAR Ağdaşan     ''İnadına Sevdamız'' Şafak Yay

Yorum: Aşık Şahturna (Şah turna)                        www.siarcan.com', 'Gönül kapısın kapatan Taş kilidi KIRIVERDİK Petek ile sarmaş yatan Çiçeklere ARIVERDİK! ... Binler, on bölüm yüz tutmuş Baharlar hazan güz t...', ARRAY['Türk Edebiyatı','Şiir','Ozan ŞİAR Ağdaşan']::text[], 8.5, '{"poet":"Ozan ŞİAR Ağdaşan","poet_slug":"ozan-si-ar-agdasan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tas-kilidi-kiriverdik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram Şenliği', 'bayram-senligi-salih-ozalasan-fm454', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bulutlar ağlamasa tabiat kururdu

Hayaller olmasa sevenler ölürdü

Bayramlar olmasa uzaktakiler unutulurdu

Her anınız bayram şenliğinde geçse

Sonserseri Salih çok mutlu olurdu

Yaşama sarıl bayram şenliğiyle

Sevdalara tutul Aslı Kerem güzelliğinde

Sen hatırlarsan, hatırlanırsın yeri geldiğinde

Unutan değilim, unutma günü geldiğinde

Sonserseriyi hatırla Salih adı geçtiğinde

Salih Özalaşan', 'Bulutlar ağlamasa tabiat kururdu Hayaller olmasa sevenler ölürdü Bayramlar olmasa uzaktakiler unutulurdu Her anınız bayram şenliğinde geçse ...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bayram-senligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Isırımlık Elma', 'bir-isirimlik-elma-zafer-zengin-etnika-la8ai', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'cocugum diyorum

gıyabımda yargılamalar

idamlar yapılıyor...

ßir ısırımlık elma

                 ilmek gibi

diziliyor bogazıma...

elmayı sevdim

cocuktum

ekmek yokken

ben elmayla doydum

cocuktum ulan...Bir ısırımlık elma...

elma kadar

kırmızı kadar cocuktum...

saklamadım bombalardan

yüreğimi

              emanettir

sahibine teslim edilecek

..

ıssız tepelerde

top mermilerinin dövdüğü

ağaç kadar

daldım, cocuktum

meyvaydım 

derken bir parcam koptu

                             soldum

büyüdüm

gene cocuktum

..

ne gariptir

saklanbac oynayan iki kedinin

cocukluğa carpması

..

Babalar cocuk olur gece vakti.

30 kasım 2003', 'cocugum diyorum gıyabımda yargılamalar idamlar yapılıyor... ßir ısırımlık elma                  ilmek gibi diziliyor bogazıma... elmayı sevd...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bir-isirimlik-elma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Harmanı Bu Ellerimin', 'harmani-bu-ellerimin-zafer-zengin-etnika-2sacz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'harmanı bu ellerimin

nerene dokunsam toprak kokusu

ne yana baksam

yüzümde rüzgar

harmanı bu ellerimin

kim dokunsa içimde sızı

ne yana dönsem çatlarım kıskançlıktan

keşke sabah olmasaydın

öpmeseydim

şafak grisi yanağından

harmanı bu aklımın

             harman ola 

sabah ola

..

gülümsemen yaz içim de

üşüyorum...

duyuyormusun! 

anlıyormusun! 

titremelerim neden...

fısıldama ismimi kulağıma

             ölmüştüm

dirildim...

10.01.2004', 'harmanı bu ellerimin nerene dokunsam toprak kokusu ne yana baksam yüzümde rüzgar harmanı bu ellerimin kim dokunsa içimde sızı ne yana dönsem...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/harmani-bu-ellerimin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalımdaki Son Yaprak', 'dalimdaki-son-yaprak-vahittin-bozgeyik-xr8zn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Üçyüz altmışbeş gün beni yakıp da

Kaybolma su gibi coşkun akıp da

Gözünün altından gizli bakıp da 

Gönlünü ellere verme ha sakın...

İçimde köz gibi bazan yanarsın

Bazan buz kesilip hemen donarsın

Eriyince sanki coşkun pınarsın

Akıp da sellere verme ha sakın...

Bak sevgilim geldi yine sonbahar

Garip bir ağaçta tek bir yaprak var

İşte o yaprak ben,sen ise rüzgar

Esip de yellere verme ha sakın', 'Üçyüz altmışbeş gün beni yakıp da Kaybolma su gibi coşkun akıp da Gözünün altından gizli bakıp da  Gönlünü ellere verme ha sakın... İçimde k...', ARRAY['Türk Edebiyatı','Şiir','Vahittin Bozgeyik']::text[], 8.5, '{"poet":"Vahittin Bozgeyik","poet_slug":"vahittin-bozgeyik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dalimdaki-son-yaprak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arabesk Şiirler 1', 'arabesk-siirler-1-adnan-ferit-x6qbs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bak bu gün gözlerim yorgun gönlüm de kırıksa

Saçlarım bembeyaz olmuş

Tellerinde satır satır acılarımı okuyabiliyorsan

İnan hepsinin bir tek suçlusu var

O da sensin....

Mevsim yazsa, bense hala geceleri

Tir tir titriyorsam

Her insan gibi ecelimle ölecekken

Sayende şimdi bir ölüysem

İnan hepsinin bir tek suçlusu var

O da sensin..

Yazdığım satırlar yetmeyecek 

Hepside ıslanan mendillerle

Atılacaksa çöplüğe

Öldüğümde bir çiçek bile gelmeyecek

Beni mezarcıyla kalfası gömecek

Ve tahtadan bir levhada kalacaksa ismim

İnan hepsinin bir tek suçlusu var

O da sensin.....

(Lise yılları)', 'Bak bu gün gözlerim yorgun gönlüm de kırıksa Saçlarım bembeyaz olmuş Tellerinde satır satır acılarımı okuyabiliyorsan İnan hepsinin bir tek ...', ARRAY['Türk Edebiyatı','Şiir','Adnan Ferit']::text[], 8.5, '{"poet":"Adnan Ferit","poet_slug":"adnan-ferit","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/arabesk-siirler-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arabesk Şiirler 2', 'arabesk-siirler-2-adnan-ferit-mg4fr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Köşedeki durakda zaman öldürmeler.

Çıkışını beklerken,

Bir el  cepte,gizli gizli bozuklukları hesaplamalar.

Çay içersek şu tutar,sahlep pahalıya patlar,

Onun evi yakın ama,bu gün de yürünebilir o yollar.

 Zaman kavgaları,

Geç kaldın,

Hayır kalmadım atışmaları.

Etek giyilmesine şeklen karşı olmak üzerine nutuklar,

Bu arada bacaklara atılan gizli bakışlar.

Sakız çiğnerken dikkatli olmak gerek,

Ayıptır çakkada çakkada ağız bir karış açık çiğnemek.

Sokakta  öyle dağınık yürünmez,

Kalçaları çok oynayan kızlar için iyi şeyler düşünülmez.

Arka sokak bizim için daha emin

Oynaşmak değil isteğim,hani görmesin ablan ya da abin.

İnan  evleneceğiz,hele bir işe gireyim

Hatırlamadın mı falcı da söyledi

Üç vakte kadar ben damat sen gelin.

Neden karşı koyuyorsun ki,karım olacaksın ya sonunda,

Bekaret beyinde olmalı eskidendi o iki bacak arasında.

Yaşandı bunların hepsi aramızda.

Ve sonunda dayanamayıp kaçtın

Tamamen de  haklıydın.

Arabesk aşkımın

Arabesk sonu.

Ben hazırlamış olsam da bunu

Dayanamıyorum 

Seni çok özlüyorum.', 'Köşedeki durakda zaman öldürmeler. Çıkışını beklerken, Bir el  cepte,gizli gizli bozuklukları hesaplamalar. Çay içersek şu tutar,sahlep paha...', ARRAY['Türk Edebiyatı','Şiir','Adnan Ferit']::text[], 8.5, '{"poet":"Adnan Ferit","poet_slug":"adnan-ferit","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/arabesk-siirler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerine Sığınmak', 'ellerine-siginmak-huseyin-cayikli-15azo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'incifer''e

ellerine sığınmak istiyorum öyle sıradan olduğum zamanlarda.suçlarımdan arınmak ellerinde.öldüğümde bir tek şahit ellerinin olmasını isterim sığınmak istiyorum bir gece yarısı.yaralandığım zaman kanayan bir yanım olmanı istiyorum.sevmek istiyorum bir şehri senin yuzünden bir şehrin limanına sığındım bir kentin acısını taşıyorum ellerimde sana dair ne varsa kendimce yazıyorum korkarak ve üşüyerek ellerine sığınıyorum.', 'incifer''e ellerine sığınmak istiyorum öyle sıradan olduğum zamanlarda.suçlarımdan arınmak ellerinde.öldüğümde bir tek şahit ellerinin olması...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/ellerine-siginmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni çok özlüyorum! ! ! !', 'seni-cok-ozluyorum-nazife-abayli-7z3nl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Oturdum sevda türküleri dinliyorum,

Sen gidince ardından.

Bir elimde sigaram,

Bir elimde tükenmeyen biram.

Ve önümde,

Meze yaptığım özlemim.

İçiyorum,içiyorum,içiyorum.....

Dinlediğim türkülerin,

Her  nağmesinde

Sigaramdan çektiğim,

Her nefeste,

Biramdan aldığım,

Her yudumda,

Sen varsın.

Seni çok özlüyorum! ! ! !', 'Oturdum sevda türküleri dinliyorum, Sen gidince ardından. Bir elimde sigaram, Bir elimde tükenmeyen biram. Ve önümde, Meze yaptığım özlemim....', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/seni-cok-ozluyorum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Sana', 've-sana-zafer-zengin-etnika-si6uq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ve sana gül kopardım içimden

Hüznü kırmızı yanan

Burnumu uzattım sana

Kokusu içinden

Biraz senden

Biraz benden

..

Karmaşığım gece vakti

1 ocak 2004', 'Ve sana gül kopardım içimden Hüznü kırmızı yanan Burnumu uzattım sana Kokusu içinden Biraz senden Biraz benden .. Karmaşığım gece vakti 1 oc...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ve-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Üşüyen Yürek', 'i-ki-usuyen-yurek-zafer-zengin-etnika-viwkj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kimin gözünden düşer

iki üşüyen yürek

yıldızı geceden saklı

kar taneleri

..

hangi aşık ağlar

beyaz beyaz

kimsesiz mi gece

kar yağarken

bir kış gecesi

..

düşünenleri var

mevsimin en güzel hali

..

cocuk üşür aşık

..

kış gecesi

yıldızında 

kar tanesi

..

iki eli

iki yüreği üşür adamın

ağaçlarda uyur uykusu

dalında ağır bakışı

çay çeker bir yanı

bir yanı döşte yar

bir yanı intihar

..

iki yüreği üşür şairin

cok değil

iki dizesi

gülü bahardan kalan

gülümsemesi yaz

..

iki dize

iki şair

iki yürek üşür

iki saat geçe 

üşüyor

üşüyebildiği kadar gece

17 aralık 2003', 'kimin gözünden düşer iki üşüyen yürek yıldızı geceden saklı kar taneleri .. hangi aşık ağlar beyaz beyaz kimsesiz mi gece kar yağarken bir k...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/iki-usuyen-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Yangın', 'uc-yangin-zafer-zengin-etnika-iuxdq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'üç yangınım vardı

birini eller

birini kopmuş gelen seller aldı

bir sende kaldı...

..

ellerim yanıyor

dalıp unuttuğum

sigaralardan

gözlerim yanıyor

umutsuz tüten dumanlardan

cigerim dört köşe

karardıkça bana ağlıyor...

geceler hırıltılı uykusuz

ahh bu aklım 

ahh ne kadar umutsuz...

..

umudum kadar

yalnız olan var mı...

su mavielma

su mavi dünyada...

14.agust.2003', 'üç yangınım vardı birini eller birini kopmuş gelen seller aldı bir sende kaldı... .. ellerim yanıyor dalıp unuttuğum sigaralardan gözlerim y...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/uc-yangin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekle!', 'bekle-nazife-abayli-e5ac8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Can dostum.

Canım dostum.

Aşkım.

Şu,arkanda gördüğün,

Okyanus var ya! 

Ve okyanusa paralel uzanan,

Dağlar,

Kıvrılan yollar.

O kadar uzak bedenimiz,

Bedenimize.

Bir de dinlediğin,

Şu fon müziği var ya,

Ne kadar,

Bekleme yar ben gelemem,

Diyorsa da,

Geleceğim sana! 

Ama sonra.

Koşullar uygun olunca.

Yüreğimle.

Bedenimle.

Saçlarımla.

Her şeyimle.

Ve.........

Tükenmeyen hasretimle.

Geleceğim sana! 

Seni seviyorum! 

Bekle!', 'Can dostum. Canım dostum. Aşkım. Şu,arkanda gördüğün, Okyanus var ya!  Ve okyanusa paralel uzanan, Dağlar, Kıvrılan yollar. O kadar uzak bed...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bekle-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkta Yarın Yoktur!', 'askta-yarin-yoktur-nazife-abayli-qwlww', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey sevgili! 

Hadi oyalanma.

Aşk bizlere verdiği büyüyü,

Geri alır yoksa.

Yaşa,doya doya yaşa.

An''ı an'' da yaşa.

Aşkta yarın,

Yoktur çünkü.', 'Ey sevgili!  Hadi oyalanma. Aşk bizlere verdiği büyüyü, Geri alır yoksa. Yaşa,doya doya yaşa. An''ı an'' da yaşa. Aşkta yarın, Yoktur çünkü....', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/askta-yarin-yoktur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Bana Verdi!', 'seni-bana-verdi-nazife-abayli-ykcsy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ateşler içinde alnım,

Yağmurun yıkadığı,

Pencereme dayadım.

Uyku mahmurluğunda gözlerim,

Yollara baktı,

Seni aradı.

Her geçeni elinde valizle,

Sen sandı.

Pınarlarından,

Bir iki damla yaş akıttı.

Penceremi yıkayan,

Yağmura karıştı.

Yüreğim dile geldi sonra,

Dedi:

Ağlaman boşuna,

Bak bir etrafına,

Kaç zamanın kaldı şurada? 

Kavuşmanın mutluluğuyla,

Karışır gözyaşın,

Sevdiğinin gözyaşlarına.

Ellerim sonra,

Ellerim dillendi,

Dur sen,akan gözyaşını,

Sileyim dedi,

Aldı kalemi,

Yazdığı dizelerde,

Seni bana verdi!', 'Ateşler içinde alnım, Yağmurun yıkadığı, Pencereme dayadım. Uyku mahmurluğunda gözlerim, Yollara baktı, Seni aradı. Her geçeni elinde valizl...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/seni-bana-verdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhanet', 'i-hanet-abdullah-atay-ugnpx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sabaha döllenirken geceler boyu

kaç kez boğuldum...

kaç kez boranlarında savrulup

sevdalarında kavruldum.

kaç kez...

darağacı sarkacında,

umarsızlık burgacında

kaç kez öldüm kaç kez? ..

kaç kez çöreklendi yüreğime soğuk ve soluk benizli ölüm.

heyhat! ..

bunlar değil beni helak eden.

ölümüne sevdalar ölümlerle yok olmaz ki.

sevdaları katleden tek şey; 

 ateş kuyularında barınan,

 acılarda kıvrılan,

yalanlara sarılan,

zehir saçan bir yılan

 ''İHANET'' adında suçludur sadece.

 hiç bitmez ki...', 'sabaha döllenirken geceler boyu kaç kez boğuldum... kaç kez boranlarında savrulup sevdalarında kavruldum. kaç kez... darağacı sarkacında, um...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ihanet-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*İyi ki…', 'i-yi-ki-vahdet-nafiz-aksu-80h0a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İyi ki yıldızsın göğümüzde 

Her  tan vakti sen  doğsaydın

Yüzünden dökülen ateşlerle 

Ne derya kalırdı ne umman 

Güneş olsaydın 	

İyi ki yıldızsın göğümüzde 

Ormanlar tutuşuyor olurdu 

Dağlar kor olurdu 

Bulutlar ağlıyor olurdu 

Rüzgar olsaydın 

İyi ki yıldızsın göğümüzde

Daha kopmadan bulutundan 

Fıkır fıkır kaynayan 

Beyaz bir lav olurdun 

Kar olsaydın

İyi ki yıldızsın göğümüzde

Yıldırımlar saçan  gözlerinle 

Ateş dökülen yüzünle 

Uzaklardasın iyi ki 

Ey sevgili 

Ne olurdu halimiz 

Girip koynumuza 

Yar olsaydın …', 'İyi ki yıldızsın göğümüzde  Her  tan vakti sen  doğsaydın Yüzünden dökülen ateşlerle  Ne derya kalırdı ne umman  Güneş olsaydın 	 İyi ki yıl...', ARRAY['Türk Edebiyatı','Şiir','Vahdet Nafiz Aksu']::text[], 8.5, '{"poet":"Vahdet Nafiz Aksu","poet_slug":"vahdet-nafiz-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/iyi-ki-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Adam', 'o-adam-mehmet-akar-ihr7f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '-Çalışmak

Neredeyse,karın tokluğuna...

Sabahın köründen; gece yarısına dek

güneşin,fırtınanın(yaz-kış) altında.

Makinalaşmış bir adam gibi.

-Düşünmek

Ay sonunu,faturaları,borçları

öğle yemeğini,sıgara parasını.

Orospuları.(en gözdesini ve fiyatını) 

-Eğlenmek

Acı acına sokakları gezmek,şarap aşırmak

camekanlara bakmak,zar sallamak

bağıra bağıra küfür sallamak,sarhoş olmak.

-Sevmek

Sarhoş gezmeyi,küfürlü konuşmayı

sokak köpeklerini.

Bütün kaldırımları,bütün yosmaları

-ölmek

kimi zaman bir kaza,kimi zaman damda.

Bazan bir kurşun fiyatına.

Bilimum serserice.', '-Çalışmak Neredeyse,karın tokluğuna... Sabahın köründen; gece yarısına dek güneşin,fırtınanın(yaz-kış) altında. Makinalaşmış bir adam gibi. ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akar']::text[], 8.5, '{"poet":"Mehmet Akar","poet_slug":"mehmet-akar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/o-adam-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Şiir Dergâhı...', 'siir-derg-hi-naime-erlacin-tskow', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'soyunur şiir 

telâşlı bir çıplaklığa

dem tutar

kalemle kan

âtiden bir yargıç gibi sorular soran

semazenin tek

şiirin iki eli gökte

son durakta açar gül

daimi bir bekleyiştir şiir

bilinmeyen

bilineni aklar kimi zaman

en parlak huzmedir hakikat

şiirin firarî gölgesinde 

soğuktan yansıyan

gizlenir heyhat! 

üşümeler bana kalsın

bilince ve geleceğe verdim şiiri

emanetim olsun yeddi emine

o ki koynunda isyandan 

bir hikmet saklar

acemi dervişten âlim çıkmaz

vedianın sahibi sensin ey şair! 

biteviye soğurken bedenin

sürdür semahı, ellerin gökte

yan

tutuş 

kavrul şiirin kızıl alevinde

bakarsın bir gün

o ateşte bir dergâh açar! *

(*)    “Okullar şiir yaratamayacağına göre, şiirler okul yaratabilir” – Filistinli çağdaş şair Mahmud Derviş’in (1941 -)    bu özdeyişinden esinlenilmiştir.

(3 Şubat 2004)', 'soyunur şiir  telâşlı bir çıplaklığa dem tutar kalemle kan âtiden bir yargıç gibi sorular soran semazenin tek şiirin iki eli gökte son durak...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/siir-dergahi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yılı Yüz Geçmiş', 'yili-yuz-gecmis-burcu-arzu-cinar-d5uyv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Büyüme kal böyle

Ama bil 

Sen aldıkça ben yaşlanıyorum

Çizgilerim artıyor

Yüzümde,yüreğimde

Yılı yüz geçmiş sen görmemişsin

Ben o ara bitmişim

Sen hala oyuncak peşinde

Kukla elinde

Kuklalara yenik düşmüşsün

Yeni düşürmüşsün beni,yüreğimi.

Yenilmeme izin verme,

Yenilirsen yenilirim ancak

Yel değirmenlerini düşman edinme

Rüzgarı yüreğimize lazım

Kuklaları yenik düşürme

Duvarda onlara ihtiyaç var

Bu yüreğin sana ihtiyacı olduğu kadar.

Geçmişe ihtiyacımız olduğu kadar,

Yenik düşme

Düşersen,düşerim,

Kuyunun dibi bekler beni...', 'Büyüme kal böyle Ama bil  Sen aldıkça ben yaşlanıyorum Çizgilerim artıyor Yüzümde,yüreğimde Yılı yüz geçmiş sen görmemişsin Ben o ara bitmiş...', ARRAY['Türk Edebiyatı','Şiir','Burcu Arzu Çınar']::text[], 8.5, '{"poet":"Burcu Arzu Çınar","poet_slug":"burcu-arzu-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yili-yuz-gecmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret İse Turna Bir Cana', 'hasret-i-se-turna-bir-cana-zafer-zengin-etnika-j31yh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biliyorum

İki gözün

İki elin

İki ayağın

Bir yüreğin

Yalnız kalışını

Tepeden tırnağa

Hasret...

Hasret...

Gülün yamacı kırmızıyken

Ritim tutar yürek saati

hasret...

hasret...

Bir zaman

Hasret...

Hasret...

Dem tutuyor

Ciğarası gözlerinde adamın

Hasret...

Hasret...

Tutabildiği

Bir bulutun bakışıdır oysa

Hasret...

Hasret...

Hasret ise turna

Bir cana

Bahardan bahar''a gelir yurduna

Hasret...

Hasret...

03.01.2004', 'Biliyorum İki gözün İki elin İki ayağın Bir yüreğin Yalnız kalışını Tepeden tırnağa Hasret... Hasret... Gülün yamacı kırmızıyken Ritim tutar...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/hasret-ise-turna-bir-cana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakın Özgür Kalsın Şiir', 'birakin-ozgur-kalsin-siir-muammer-celik-4mr35', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Soyunuktur duygular

Huriler gibi uriyen

Dile gelirler

Şairlerin dilinden

Giyinirler rengarenk

Sözcüklerden giysileri

Kimi zaman al, yeşil

Kimi zaman kara

Kimi zaman hakka yönelirler 

Kimi zaman da aşka bakışır şiirler... 

Firaridir şiir kimi zaman

Yasaklanmış duyguların zindanından

Kimi zaman insanın kendinden

Vururlar bazen yarin hasret deminden

Bazende akarlar kendiliklerinden

Özgürdür şiir aklın kuralından

Mantığın hegomanyasından

Kaçamak yaparlar bazen 

Şairinin telörgülü gönlünden

Esir diyarların gökyüzünden

İsyankardır şiirler kendi şairine

Yansıtırlar günahkar duygularını 

Utanmadan

Çekinmeden

Arlanmadan

Uslanmadan

Cennet-vari içdünyalardan

Yakalanırlar oysa

avcı, amazon kadınlara

Yada insafsız maço erkeklere

Yaban ellere, dinsizlere ve imansızlara

Bazen de atarlar insanı tanımsız duygulara

Alabildiğince özgürse şiir

Olabildiğinca isyankar ise eğer; 

özgürlüğünü  kaybedip

düşmüştür esir  Akıl ve Mantığa 

Okulunu kurup bir gün, terbiye edilirse eğer…

BirDeli

03.02.2004', 'Soyunuktur duygular Huriler gibi uriyen Dile gelirler Şairlerin dilinden Giyinirler rengarenk Sözcüklerden giysileri Kimi zaman al, yeşil Ki...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/birakin-ozgur-kalsin-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüşün Küçük', 'gulusun-kucuk-zafer-zengin-etnika-oprxt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözüm Kibin Sevdim Seni

Bakışım Vermedim Ellere

Gittim Biliysen

Son Baktığın Yere

Cok Rüzgar Tutum Yüzüme

Sen Gelmisen...

..

kaç kış gecti saymamışam

düşünmüş düşünmüş ağlamışam

bebelere bakıp

seni hatırlamışam

gülüşün küçük

seni hatırlayıp ağlamışam

..

leçeğin kalmış ya elimde

sen diye bakıp sayıklıyam

kokunu almışlar burnumdan

cok özliyem bilimisen

bu yanda adın yok

adına kendime saklamışam...

..

saçın uzunmudur bilmiyem...

gözlerin yeşilin galası

ya ellerin memlekette fırat

beş parmağı bir zozan

yanağıma vuriyem seni

öpiyem

öpiyem gül kokisen...

..

ölem mi lo bu yokluğa

karne veriyler senin adına

biraz tayın, dostlardan selam

yanlız kaliyem,ağliyem

göz yaşım bahar da sel

cok güliyem çok ağlıyem...

düğünler de göriyem goşmamızı

sen gaçiysen

ben saklaniyem...

..

sen yoksun

bana git diyiler

korkiyem

sensiz nasıl gidilir bilmiyem...

..

linç oliyem sabaha karsı

günüm açmiyi

ölüyem işte

kuşların gittiği mevsim de...

Bir dostun ''zilan'' adlı şiirinde esinlendim, Yüreğine sağlık DOST.

11.01.2004', 'Gözüm Kibin Sevdim Seni Bakışım Vermedim Ellere Gittim Biliysen Son Baktığın Yere Cok Rüzgar Tutum Yüzüme Sen Gelmisen... .. kaç kış gecti s...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/gulusun-kucuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkum Yok Artık', 'korkum-yok-artik-hasan-huseyin-ozak-wf5m5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biliyor musunuz ben,

anamdan işittim ilk azarı

Daha beşikteyken, ağladım da uyutmadım diye

Babamdan işittim ilk küfürü,

büyüdüm de başına bela oldum diye

En sevdiğim öğretmenimden yedim ilk tokadı,

oyuna dalıp, ders zilini duymadım diye

Ey siz dünya kötüleri! 

Felek denen düzenbazlar

Sizler daha ne yapabilirsiniz ki bana

Korkum yok artık karanlık gecelerden

Merakım da yok artık,

güneş tekrar doğar mı diye

Ey ilahi güç çek kılıcını

Savur savurabildiğin kadar', 'Biliyor musunuz ben, anamdan işittim ilk azarı Daha beşikteyken, ağladım da uyutmadım diye Babamdan işittim ilk küfürü, büyüdüm de başına be...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özak']::text[], 8.5, '{"poet":"Hasan Hüseyin Özak","poet_slug":"hasan-huseyin-ozak","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/korkum-yok-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Göz Ya Gönül', 'ya-goz-ya-gonul-hasan-huseyin-ozak-l2hb9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gündüzleri yüreğimin ateşi sönüyor

Geceleriyse gözlerimin feri

Çok uğraştım ama, ikisi bir arada geçinemiyor

Ya göz, yada gönül

İki pencereden birden bakılmıyor', 'Gündüzleri yüreğimin ateşi sönüyor Geceleriyse gözlerimin feri Çok uğraştım ama, ikisi bir arada geçinemiyor Ya göz, yada gönül İki pencered...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özak']::text[], 8.5, '{"poet":"Hasan Hüseyin Özak","poet_slug":"hasan-huseyin-ozak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ya-goz-ya-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizim', 'sensizim-halil-i-brahim-651sz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şimdi sensiz bu hayatta

Unutulmaz anılarla

Acı çekmekten başka

Bir şey var mı hayatımda? 

Şimdi sen söyle aşkım 

Sevgiyi paylaşacaktım

Gün her sabah doğduğunda

Ellerinle uyanacaktım

Yok, artık olmuyor sensiz

Nasıl da dayanmışım

Bunca ay bi tanemsiz

Artık hep üşüyorum

Bilirsin sevginle ısınırdım

Ellerim üşüdüğünde

Yüreğinle ısıtırdın...', 'Şimdi sensiz bu hayatta Unutulmaz anılarla Acı çekmekten başka Bir şey var mı hayatımda?  Şimdi sen söyle aşkım  Sevgiyi paylaşacaktım Gün h...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim']::text[], 8.5, '{"poet":"Halil İbrahim","poet_slug":"halil-i-brahim","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sensizim-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderken', 'giderken-ahmet-aksoy-4ce2b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'giderken tortunu da al

..öyle terk et aşk mahalini.

söz! 

düşünmeyeceğim bir daha seni,

topla pılını pırtını ve yok ol! 

bir daha düşmesin izin usuma,

gideceksen benden 

..........tamamen kurtul! 

ya da en iyisi; 

büyük bir valiz al kendine

kalbimi, beynimi koy! 

doldur içine

sana dair bende ne varsa! 

ve at herhangi bir nehre

..........yok ol! 

önce benden, sonra kendinden

................kurtul.

.......giderken

....öyle terk et aşk mahalini

söz! 

mü?', 'giderken tortunu da al ..öyle terk et aşk mahalini. söz!  düşünmeyeceğim bir daha seni, topla pılını pırtını ve yok ol!  bir daha düşmesin i...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/giderken-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız', 'yalniz-friedrich-nietzsche-lc15z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Haykırışan kargalar 

Darmadağın uçuşuyor kente doğru.

Neredeyse yağacak kar

Yeri yurdu olana ne mutlu! 

Donmuş kalakaldın,

Hanidir gözlerin arkada! 

Boşuna kaçışın, ey çılgın,

Kıştan uzaklara! 

Dilsiz ve soğuktur binlerce çöle 

Açılan bir kapıdır dünya! 

İnsan senin yitirdiğini yitirse

Bir yerlerde duramaz bir daha! 

Sen şimdi solgun, sarı

Kış gurbetlerine lânetli,

Hep soğuk gök katlarını 

Arayan bir duman gibi.

Uç git, kuş, söyle ezgini

Issız çöl kuşlarının sesiyle! 

Göm, gizle, ey çılgın, kanayan kalbini

Buzların, alayların içine! 

Haykırışan kargalar

Uçuşuyor kentten yana, dağınık; 

Neredeyse yağacak kar

Yeri yurdu olmayana çok yazık! 

F. Nietzsche

(çev. Behçet Necatigil)', 'Haykırışan kargalar  Darmadağın uçuşuyor kente doğru. Neredeyse yağacak kar Yeri yurdu olana ne mutlu!  Donmuş kalakaldın, Hanidir gözlerin ...', ARRAY['Türk Edebiyatı','Şiir','Friedrich Nietzsche']::text[], 8.5, '{"poet":"Friedrich Nietzsche","poet_slug":"friedrich-nietzsche","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yalniz-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birleşmeyecek', 'birlesmeyecek-cansu-deniz-u1lta', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgi değil, aşk değil

Ne idüğü belli değil

Kar ayazı içimi titretir

Düşünürken ise seni içim erir

Bağırmak avazım çıktığı kadar

Rahatlatmaz keskin çığlıklar

Sinemi delen hüzün

Bilirim gelemezsin güzün

İndirdim yelkenleri suya

Çıkmak haram bu yola

Sevdiceğim bilmezsin

Bilsen de sezdirmezsin

Yollarımız ayrıldı sevgi adına

Taştan duvarlar örüldü umut adına

Sevgi umuta, umut acıya

Ellerimiz asla birleşmedi bir daha...', 'Sevgi değil, aşk değil Ne idüğü belli değil Kar ayazı içimi titretir Düşünürken ise seni içim erir Bağırmak avazım çıktığı kadar Rahatlatmaz...', ARRAY['Türk Edebiyatı','Şiir','Cansu Deniz']::text[], 8.5, '{"poet":"Cansu Deniz","poet_slug":"cansu-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/birlesmeyecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanrı''nın Antonius''u Bırakması', 'tanri-nin-antonius-u-birakmasi-konstantinos-kavafis-iffqb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gece yarısı ansızın duyarsan 

eşsiz ezgilerle, naralarla 

görünmeyen bir alayın geçtiğini 

boş yere ağlama talihin döndü, 

hiçbir iş başaramadın, her düşün 

boş çıktı diye. 

Nicedir hazırmış gibi, bir yiğit gibi, 

Hele kendini aldatmaya kalkma, deme ki 

bir düştü bu, belki yanlış duydum; 

böyle boş umutlara kapılacak kadar alçalma, 

Nicedir hazırmış gibi, bir yiğit gibi, 

böyle bir şehre layık olan sana yaraşırcasına, 

kararlı adımlarla yaklaş pencereye; 

duygulanarak dinle, ama korkakların 

yanıp yakılmalarıyla değil, 

son bir kez doya doya dinle o sesleri, 

o gizli alayın eşsiz çalgılarını, 

sonra veda et ona, yitirdiğin İskenderiye''ye. 

Çeviren: Cevat Çapan', 'Gece yarısı ansızın duyarsan  eşsiz ezgilerle, naralarla  görünmeyen bir alayın geçtiğini  boş yere ağlama talihin döndü,  hiçbir iş başaram...', ARRAY['Türk Edebiyatı','Şiir','Konstantinos Kavafis']::text[], 8.5, '{"poet":"Konstantinos Kavafis","poet_slug":"konstantinos-kavafis","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/tanri-nin-antonius-u-birakmasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yak ateşi', 'yak-atesi-tevfik-karinca-tg6ol', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'anlamsızlığın yaşattıklarına bak

gözlerimde yitirdim seni

tek suçlusu benim değil mi? 

şimdi yak elindeki ateşi 

söndürmeden, rüzgara kaptırmadan

damarlarımdaki tüm kan

dolaşıyor beynimde sanki

yumruklarım duvarlarda kan izi

hazmedemiyorum seni

sensizliği değil ama

tek suçlusu benim değil mi? 

şimdi yak elindeki ateşi

söndürmeden yakmadan bedenini 

bunca yaşanmışlığın içinde

ruhumu kirletiyorum

unutmak adına seni

ve tek suçlusu benim değil mi', 'anlamsızlığın yaşattıklarına bak gözlerimde yitirdim seni tek suçlusu benim değil mi?  şimdi yak elindeki ateşi  söndürmeden, rüzgara kaptır...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Karınca']::text[], 8.5, '{"poet":"Tevfik Karınca","poet_slug":"tevfik-karinca","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yak-atesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda', 'elveda-tevfik-karinca-0lqx9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bitmiyor içimdeki hüzün

yaşama küsmüşüm

son türkümü söylüyorum kendi adıma

ne düşler ne hayaller 

size bıraktım

başaramadım yaşamayı beceremedim

oyunlar size

sevgiler size

mutluluk size

benden elveda', 'bitmiyor içimdeki hüzün yaşama küsmüşüm son türkümü söylüyorum kendi adıma ne düşler ne hayaller  size bıraktım başaramadım yaşamayı becerem...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Karınca']::text[], 8.5, '{"poet":"Tevfik Karınca","poet_slug":"tevfik-karinca","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/elveda-78-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Newr-i çeşmin böyle sű zân mıydı mâh-ı dil-rübâ', 'newr-i-cesmin-boyle-s-z-n-miydi-m-h-i-dil-rub-mustafa-tanrikulu-ro3nn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Newr-i çeşmin  böyle sûzân mıydı mâh-ı dil-rübâ

Yandı kalbim öyle bir yükseldi  âh-ı dil-rübâ...

Kays''a Leylâ gösterirmiş dâimâ vefâ-yı hakk

Görmedim senden vefâ bende-yi Şâh-ı dil-rübâ

Olmaz idim sana meftûn amma ettim bir nazar

Aldı ol vâkit karârım çeşm-i siyâh-ı dil-rübâ

Göz yumup her nâzına çektim eyvallâhı ben

Olduğumdan beridir rehvân-ı râh-ı dil-rübâ 

Mustefa sen âşık-ı cins-i latif olmuş iken

Aldı benden dil-i mecrûhum  İlâh-ı dil-rüba 

Açıklama:

Beyit:Ey gönül alan ay yüzlü sevgili senin gözlerinin nuru böyle yakıcı mıydı? Gönül alıcı âh öyle bir yükseldi ki kalbim yandı.

Beyit:Ey gönül alan Şâh''ın kölesi Sevgili ben senden vefâ görmedim. Halbuki Leylâ Mecnûn''a gerçek bir vefayla bağlıymış.

Beyit:Ben sana kolay kolay tutulmazdım ama gel gör ki bir kere sana bir kere baktım. İşte o zaman kararımı almıştır gönül alan siyah gözlerin.

Beyit:Ben gönül alıcı bu yolun(aşk:râh-ı dil-rübâ)  yolcusu olduğumdan beri senin söylediğin her şeye ettiği her naza ''eyvallah'' dedim.

 Beyit:Ey Mustafa sen cins-i lâtife aşık olmuşken gönül alıcı Tanrı benden yaralı gönlümü aldı.', 'Newr-i çeşmin  böyle sûzân mıydı mâh-ı dil-rübâ Yandı kalbim öyle bir yükseldi  âh-ı dil-rübâ... Kays''a Leylâ gösterirmiş dâimâ vefâ-yı hakk...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tanrıkulu']::text[], 8.5, '{"poet":"Mustafa Tanrıkulu","poet_slug":"mustafa-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/newr-i-cesmin-boyle-s-369-zan-miydi-mah-i-dil-ruba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anladın mı Bebeğim...', 'anladin-mi-bebegim-i-brahim-ethem-bingul-mijbu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir baktım gönül teline

Aşk nağmeleri söylemekte

Gönül bülbülleri aşkla, meşkte

Bİr garip yürek ben

Bir taze bahar sen

Kaf dağından inen

Züleyha''yı ağlatıp, Leyla''yı inleten

Bu sevda pınarı

Kalb-i gülizarı da mesken kıldı

Vakti tamamdayım deme neredeydin

Keder bana uzak makamı mesteyim

Bebeğim, kanadı incili meleğim,

Taze bahar çiçeğim

Bebeğimsin, bebeğim..

Ama korumasız olan benim yüreğim

Al eline kalbimi

Bak artık bu yürek sensin

Anladın mı bebeğim...', 'Bir baktım gönül teline Aşk nağmeleri söylemekte Gönül bülbülleri aşkla, meşkte Bİr garip yürek ben Bir taze bahar sen Kaf dağından inen Zül...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/anladin-mi-bebegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evrim', 'evrim-turgay-kaygi-24o7r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ey benimden içerideki ben

kalk yattığın yerden de

çapaklı gözlerle

düş yollarına

tabiat ananın

git de öp

elini etiğini

yalvar yakar

''bir değişik maluka çevir beni ana! '' diyerek...

ister tosbağa

ister kurbağa

ister sümüklü böcek

ister sümüklü burunlara

kırmızı ışıklarda kağıt mendil satmayı

hayat belleyen

anasını-babasını bellediğimin çocuklarından biri ol! 

ne edersen et

bana dönme! 

dön geriye

başladığın yerde bit! 

çiliyor işte yine yağmur

beklemezdim bunu senden tanrım! 

eriyip gidecek yine korkarım

sarhoşluğum, mayhoşluğum ve

sancıma sürdüğüm inancım! 

ağzı açık

beni ve evreni izleyen siz

dadacı dadıların elinde büyümüş

debdebeli deliler! 

nerde üzerine kalp

çizilmiş ağaçları kemiren

dalkurutanlara rastlarsanız

benden bilin! 

vodvillere beyit ola ki

tüm

''aşkımız ölümsüz olacak bir tanem! ''

iddialarını çürüteceğim! 

(inegöl,  02.02.2004', 'ey benimden içerideki ben kalk yattığın yerden de çapaklı gözlerle düş yollarına tabiat ananın git de öp elini etiğini yalvar yakar ''bir değ...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kaygı']::text[], 8.5, '{"poet":"Turgay Kaygı","poet_slug":"turgay-kaygi","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/evrim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürek Tamircisi...', 'yurek-tamircisi-i-brahim-ethem-bingul-rraik', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir tamirci edesıyla girdi dünyama önce

Sonra; kırılmış, yıkılmış, saçılmış yüreğime

Şöyle bir baktı üzüntülü ve alaylı biçimde

''''Değmez, bir yürek değmiş'''' dedi bu yüreğe

''''Bu yüreği denizde yıkayalım''''

''''Seher yelinde kurutalım''''

''''Arzu ile yerine koyup''''

''''Bir bebek sevdası ile tekrar çalıştıralım''''

 Dedi ve gitti....', 'Bir tamirci edesıyla girdi dünyama önce Sonra; kırılmış, yıkılmış, saçılmış yüreğime Şöyle bir baktı üzüntülü ve alaylı biçimde ''''Değmez, bi...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yurek-tamircisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Defolu Masal', 'defolu-masal-turgay-kaygi-6ilqw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'evvel zaman içinde kalbur saman içinde

ankara ostim''de üç gün üç gece

kereste istifledik düpedüz:

şahin ağa, kel ibo, haydar''ın mustafa, tırrı selo,

bi de koca rasim, bi de ben! 

kamyoncu dede''yide unutmamalı! 

yaşları 60''la 20 arasında değişen

7 ameleye

bi nevi 7 cüceye,

bilhassa da

koca rasim''in kıçı cırık, yamadan yoksun pantolonuna

ithaf edilmiştir bu masal! 

hayal mayal değil ulan bu! 

sofrasında ekmeğinen pekmezde

bulunsun diye daha şafak sökmeden 

kalasların altına giriyor

tek gözlü şahin ağa! 

bir oğlanı öğretmen çıkarmış çok şükür ya! 

geriden gelen ikisine

defter, kitap, kalem, silgi alabilmek için

şubat''taki seçimlerde allahın izniyle

kızılcahamam''ın ''çükören köyüne

muhtar seçilene dek

nasırlı ellerine yük değmesi gerek

haydar''ın mustafa''nın...

en gencimiz selo mardinli

yoruldukça odun devşirmekten

her saatbaşında bir

önce küfrediyor

sonrada cevabını zaten bildiği halde 

yeniden soruyor

daha yüzünü görmediği nişanlısını

alıp getirmek ankara''ya

kaça patlar diye

bandırma''dan...

kamyoncu dedem

aydede''den daha bi bembeyaz, daha bi ay yüzlü dedem! 

ne ekmek arar, ne de su! 

yeter ki cigarası yanadursun ağzının kenarında! 

belli belirsiz demli bir çay geçer

arada bir aklından...

kel  ibo! ah kel ibo! 

bütün derdi

arabanın deposunu fulledikten sonra

çoluğu çocuğu doluşturup içine

köye gidebilmek bayramda! 

doktor halit''in oğlu ibrahim

dedilermiydi köyde

akan sular dururmuş! 

hay gidinin koca rasim''i

koca avucu kadar kocaman cep telefonuyla

durmadan çağrı yapar karıya

herhal

''daha ölmedim! ''

anlamında! 

ulan o yaşta böyle komedi olur mu? 

kerestedeki yarıkları

pantolonunun kıçındakiyle

mukayese edip durur herif! 

bir yandan da

uyandırmak için

küfredip bağırır bana:

''yazdın nııı! '' diye! 

yazdım bak rasim dedem

hepinizi yazdım...

tastamam 7 koca cüce...

belki 48 saatten fazladır

bir yastığa koyamadığı küçücük yanağına

babasının

''uyan gız! ''

diyerek bi tokat patlattığı

otobüsteki

altı-yedi yaşlarındaki

şu sarışın bebek de

pamuk prensesi olsun bu masalın

masal almak kaleme

karnı tok, sırtı pek, aklı başında adam işi! 

benim gibi berduştan

hakikaten masal uman

ne kadar kaşalot varsa

kafasına

zehirli elma atsın

büyücü! 

(inegöl,  02.02.2004)', 'evvel zaman içinde kalbur saman içinde ankara ostim''de üç gün üç gece kereste istifledik düpedüz: şahin ağa, kel ibo, haydar''ın mustafa, tır...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kaygı']::text[], 8.5, '{"poet":"Turgay Kaygı","poet_slug":"turgay-kaygi","theme":"Türk Şiiri","is_hero":false,"total_lines":84,"source_url":"https://www.antoloji.com/defolu-masal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız Olmasam', 'yalniz-olmasam-oguzkan-bolukbasi-9gvrl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ben yalnızım

kelimelerim de yalnızdır

ben bana

kelimelerim meramıma yeter

birde derbeder

notalar sıraya dizilmek için gelseler

de aksa yüreğimden şiirler

ve sen doğsan

sen 

yalnız olmasam', 'ben yalnızım kelimelerim de yalnızdır ben bana kelimelerim meramıma yeter birde derbeder notalar sıraya dizilmek için gelseler de aksa yüreğ...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yalniz-olmasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden diye Bilirmisin?', 'neden-diye-bilirmisin-erhan-ergun-l62q5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bilirmisin sen neden benim ilk kiz arkadasimsin? 

Bilirmisin senden önce olanki imkanlarimi kullanmadigimi? 

Anlatayim sana, cünkü sen simdiye kadar ilk asik

olabilecegimki kizdin, ilk seve bilecegimki kizdin.

O Hayat’a olanki sevgin beni sana baglatiyordu.

Senin cevrende olanki mutsuz insanlari güldürürsün,

umutsuzluga kaptirmasin! 

Ve bu sebepler beni sana karsi büyülüyordu.

Ama artik bos bu sözler bir cocuk oyuncagi gibi oynadin

benimlen ve artik zevk alamadigin icin attin beni

bir köseye! Oysa ben sana ne kötülük yaptim? 

Ve sunuda bil o yüzügü artik bende geri istemiyorum!', 'Bilirmisin sen neden benim ilk kiz arkadasimsin?  Bilirmisin senden önce olanki imkanlarimi kullanmadigimi?  Anlatayim sana, cünkü sen simdi...', ARRAY['Türk Edebiyatı','Şiir','Erhan Ergün']::text[], 8.5, '{"poet":"Erhan Ergün","poet_slug":"erhan-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/neden-diye-bilirmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Grecek oldu', 'grecek-oldu-erhan-ergun-gs7bw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ah BEYAZ Gülüm benim! 

Sonunda en büyük korkum gercek oldu! 

Bundan sonra ben ne olacam? 

Benimde’mi icki en iyi arkadasim olacak bundan sonra? 

Seninlen ben ne hayaller kurmustum, 

sana kalbimin isigin’lan büyüyen hic bir 

zaman icin solmayan bir Gül verecektim! 

Kücük ufak birsey verecektim sana beni

her zaman yaninda cebinde tasiya bilmen icin

ve beni özlediginde sesimi dinleye bilmen icin! 

Ben bu oyunun basinda kaybettim, ellimde olanki

jokerleri kullanmadim! 

Ve eger sorarsan neden? Cünkü ben sana asik

oldugum icin kör oldum! Ama ne yapacaksin

BENIM kaderim böyleymis!', 'Ah BEYAZ Gülüm benim!  Sonunda en büyük korkum gercek oldu!  Bundan sonra ben ne olacam?  Benimde’mi icki en iyi arkadasim olacak bundan son...', ARRAY['Türk Edebiyatı','Şiir','Erhan Ergün']::text[], 8.5, '{"poet":"Erhan Ergün","poet_slug":"erhan-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/grecek-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkum', 'korkum-erhan-ergun-qsekd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar ask ne demektir anlamazdim,

dostlarim dertlerini, ask dertlerini, bana anlatirken,

derman olmaya calisirdim ama olamiyordum,

cünkü ask ne demektir bilmezdim! 

Her gecen gün görüyordum ve yasiyordum,

kendilerini sevdiklerine kavusamadilar diye,

nasil yigip bitirdiklerini! 

Kaldiriyordular kadehleri arka arkaya,

bogluyordular yaktiklari Zigarralarin dumaninda.

Ve bende ozaman kendime yemin etmistim bir kiz

yüzünden kendimi yipratmayacagmi! 

Ama simdik anliyorum’ki o yeminim bosaydi! 

Onlar kavusamadilar diye yaniyorlar, 

eger bense sevdigimi bir gün göremidigim

diye yaniyorum.

Soruyorum size ben kavusamasam, o zaman 

ben ne olurum?', 'Bir zamanlar ask ne demektir anlamazdim, dostlarim dertlerini, ask dertlerini, bana anlatirken, derman olmaya calisirdim ama olamiyordum, cü...', ARRAY['Türk Edebiyatı','Şiir','Erhan Ergün']::text[], 8.5, '{"poet":"Erhan Ergün","poet_slug":"erhan-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/korkum-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorular', 'sorular-erhan-ergun-zgtqe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aklimda suan okadar cok sorular varki,

hangi birine cevap arayacagmi bilemiyorum! 

Bu soru isaretleri aramizi bozuyor,

onlar yüzünden güven kalmadi! 

Her gece sen beni unutacaksin

korkusuyla uyuyorum, artik sen 

benim olmayacaksin korkusuyla

nefes aliyorum! Anliyormusun beni? 

Gel etme, uzaklar götür korkularimi,

hic bir zaman icin geri dönmeyecek yerlere! 

Cünkü artik gözpinarlarim tükendi,

gücüm kalmadi bunlara katlanmaya!', 'Aklimda suan okadar cok sorular varki, hangi birine cevap arayacagmi bilemiyorum!  Bu soru isaretleri aramizi bozuyor, onlar yüzünden güven ...', ARRAY['Türk Edebiyatı','Şiir','Erhan Ergün']::text[], 8.5, '{"poet":"Erhan Ergün","poet_slug":"erhan-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sorular-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimde...', 'i-cimde-bekir-mutlu-gokcesu-47g5g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kök salar

Yüreğimde

Özlemin

Gecelerce

Bir fidan 

Serpilişinde

Kıpır, kıpır

Kıpırdar

Baharım 

İrkilişimde

Sen geldikçe

Su gibi 

Dizelerle

Dirilir şiir

Can yürür

Hücrelerime

Tek bir harf

Olasım

Bir tek kelime 

Kalasım gelir

Dirilişinde

Hayranlığımın

Ötesinde

Ama dallanır

Yapraklanırım 

Hece, hece

Çiçek, çiçek

Allanır

Sevdalanırım

Bir ağaç gibi

Sessizce

Görkemli

Bir aşk büyür

İçimde...', 'Kök salar Yüreğimde Özlemin Gecelerce Bir fidan  Serpilişinde Kıpır, kıpır Kıpırdar Baharım  İrkilişimde Sen geldikçe Su gibi  Dizelerle Dir...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/icimde-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçları Sarı Kadın', 'saclari-sari-kadin-zafer-zengin-etnika-dfk4s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sen, sacları sarı kadın

bir masada bırakmıstın son mektubu

..

sacların yine sarı mı

hani penye severdin

yakısır bana derdin

sökerdin bir gece vakti ellerimi

sarıl sarıl bana derdin

söyle sacları sarı kadın

ellerimi özledin mi

yine penye giydin mi

..

kapa gözlerini öp derdin

uyurken kapanıyor sadece

düşlerimde sensin derdim yine

söyle sacları sarı kadın

derdin benmiyim yine

sacların sarımı söyle

27 EKİM 2003', 'sen, sacları sarı kadın bir masada bırakmıstın son mektubu .. sacların yine sarı mı hani penye severdin yakısır bana derdin sökerdin bir gec...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/saclari-sari-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Anlamazsın', 'sen-anlamazsin-zafer-zengin-etnika-g31wu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ateş kuşları düştü

Başka savaşlar

Başkalarının savaşları

Komşulaşmış en kanlı günlere

..

Umuda vurulan sopalar

Kursun deliklerinden soluklanır

Bir gülüş doğar içinde

Gül güler

Sen anlamazsın

..

Sorular çözümsüz karanlıklara açılır

Askı unuturlar

Ve sen bilemezsin

..

Sen askı savaşta yasamadın

Sen bilemezsin

Öpüyorum şavkını 

Yanağın yumuşuyor

..

Ben koşan çocuklara bakıyorum

Toz duman içinde 

Ve savaşa gülen bir tek onlar

Sen hiç görmedin ki 

Sen anlamazsın

..

tozu dumana katan emirler yağar

ilki on tane 

..

intikamın çocukları

sancılarından vuruyorlar

tüm tapınak seslerini

hepsi aynı sekle bürünüp

canlı bir tavsan kanında boğuluyorlar

göz kapakları

gün gibi kapanıyor

umuda koşuyor çocuklar

onlar gülüyorlar kurşunlara

sen hiç görmedin ki 

sen anlamazsın

..

yaslı ağır toprak

yutuyor bereketli kumları

terli terli

bir bardak yağmur boşanıyor 

karsısında yıllar çatlıyor

bir  tekrar

bir tekrar hayat

ve çocuklar gülüyor toplara

sen hiç görmedin ki

sen anlamazsın

..

damarına vuruyorlar yeşil kazaklı askerler

kopuyor canlar

ve sevdiklerine

madalyalar veriliyor

kahramanlar

aksam üstleri uğurlanıyorlar

dinlencelerine

afrika ezgileri

son duaları

ve çocuklar gülüyor ölülere

sen hiç görmedin ki 

sen anlamazsın

..

yaşamışım

bir kursun elime

bir kursun gözüme

kolum ayrı koşar benden

bir parçam benden önce ölmüş

topraktır simdi

bir domates dalında

ve çocuklar gülüyor bahçelere

sen hiç görmedin ki

sen anlamazsın

..

mülteciyim ben

çocuk gülüşlerine

bir parça mutluluk

sıcağına vurulmuş analarda

irine boyalı gökte

parlayan yıldız gördüm

ihtiyardı baksı

ben ağlayan gün gördüm

sen görmedin ki hiç

sen ağlamazsın

sen anlamazsın

..

bir can al bana

kansız ve savaşsız

çocuklarla koşalım güneşe ve umuda

ben hiç görmedim

ben anlamam ki

10 eylül 2003', 'Ateş kuşları düştü Başka savaşlar Başkalarının savaşları Komşulaşmış en kanlı günlere .. Umuda vurulan sopalar Kursun deliklerinden soluklan...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":94,"source_url":"https://www.antoloji.com/sen-anlamazsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Parasız Yatılı', 'parasiz-yatili-oguzkan-bolukbasi-ecalx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'leyli meccani

yani parasız yatılı öğrenciydim yüreğinde

aşkın birinci sınıfından atıldım

aylak aylak geziyorum şimdi

bir yüreğe sap olamadım', 'leyli meccani yani parasız yatılı öğrenciydim yüreğinde aşkın birinci sınıfından atıldım aylak aylak geziyorum şimdi bir yüreğe sap olamadım...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/parasiz-yatili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Habersiz', 'habersiz-hasan-huseyin-ozak-xss26', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güneş yine batacak

Kuşlar tatlı bir telaşla,

yine yuvalarına dönecek

Kavaklar, huu çeker gibi,

yine salına salına dans edecek

Ve babamın nasırlı ellerinde,

yemek sonrası, bir bardak yorgunluk çayı

Yine sabahı bekleyip,

yine toprağı işleyecek

Abimin saçları,

yine bir kaç tel daha beyaza dönecek

Öbür tarafta; 

Kahvede pişpirikler oynanacak

Gazinolar, meyhaneler,

yol kenarında bekleyen kadınlar,

atılan şuh kahkahalar

Ve yeğenlerim,

tüm bu olup bitenlerden habersiz

böylesi bir dünyada,

büyümeye devam edecek', 'Güneş yine batacak Kuşlar tatlı bir telaşla, yine yuvalarına dönecek Kavaklar, huu çeker gibi, yine salına salına dans edecek Ve babamın nas...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özak']::text[], 8.5, '{"poet":"Hasan Hüseyin Özak","poet_slug":"hasan-huseyin-ozak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/habersiz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gezmeye Sevdalandım', 'gezmeye-sevdalandim-nazife-abayli-e7zkd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kaç gündür evdeyim,

Dışarıya çıkmadım.

Gökyüzünün rengini,

Havanın ısısını,

İnsanların tasasını,

Hissetmedim,görmedim.

Bugün gezmeye sevdalandım.

Önce kendime,

Bir demet çiçek aldım,

Karanfilin birini,

Yakama taktım.

Kokladıkça uyandım.

Caddelerde yürüdüm.

Gökyüzünün maviliğini,

Bir kenarda öpüşenleri,

Seyyar satıcıları,

Tatlıcıları,

Sahil yolundaki pazarcıları,

İnsanların koşuşturmasını,

Arabaların çarpışmasını,

Dalgaların azgınlığını,

Havanın nemini,

Balıkçıların sesini,

Çöplüklerin pisliğini,

Serserileri,

Gezginleri,

Dostlarımın inceliğini

Kahvedeki çayın demini,

Rüzgarın sitemini,

Gördüm görmesine de....

Bir seni göremedim.

Nerelerdesin?', 'Kaç gündür evdeyim, Dışarıya çıkmadım. Gökyüzünün rengini, Havanın ısısını, İnsanların tasasını, Hissetmedim,görmedim. Bugün gezmeye sevdala...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gezmeye-sevdalandim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümse', 'gulumse-ahmet-kurt-p5hd0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dünyanın hüznünü bırak bir yana,

İçinden gelerek, duyup gülümse.

Ruhunla barışıp koca cihana,

Başını dik tutup, bakıp gülümse.

Gülümse yüzünde, karargah olsun,

Gülümse kalbine muhabbet dolsun,

Gülümse açmayan çiçekler solsun,

Bütün benliğinde durup gülümse.

Atıver paslanan ham geçmişini,

Kırıver karanlık gam testisini,

Yalnız neşe kalsın, sil gerisini,

Şen şakrak güleni görüp gülümse.

Bu gülüş herkese elbet yakışır,

Gülüşte küskünler bile barışır,

Çınlayan feryatlar yele karışır,

Rüzgarı, yağmuru silip gülümse.', 'Dünyanın hüznünü bırak bir yana, İçinden gelerek, duyup gülümse. Ruhunla barışıp koca cihana, Başını dik tutup, bakıp gülümse. Gülümse yüzün...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gulumse-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tik Tak', 'tik-tak-hasan-huseyin-ozak-gwqyr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bütün saatler kurulu

Tik tak Tik tak, 

zaman geçiyor

Rüyadayım ama hissedebiliyorum,

uyanma saatinin geldiğini

Göz kapaklarımı aralayıp,

bakmak istiyorum akreple yelkovana

Ama korkuyorum

İyi de, böyle de olmuyor hani,

uyur uyanık rüya görmek

Saatin kaça kurulu olduğunu bilmeden,

rahatça uyuyabilmek', 'Bütün saatler kurulu Tik tak Tik tak,  zaman geçiyor Rüyadayım ama hissedebiliyorum, uyanma saatinin geldiğini Göz kapaklarımı aralayıp, bak...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özak']::text[], 8.5, '{"poet":"Hasan Hüseyin Özak","poet_slug":"hasan-huseyin-ozak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tik-tak-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanalım-Görelim', 'yanalim-gorelim-hasan-huseyin-ozak-h9fli', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yanmayan ışık verir mi

Verince eksilir mi

Gölgeye ayna tutsam

Gölgeyi gösterir mi..? ?', 'Yanmayan ışık verir mi Verince eksilir mi Gölgeye ayna tutsam Gölgeyi gösterir mi..? ?...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özak']::text[], 8.5, '{"poet":"Hasan Hüseyin Özak","poet_slug":"hasan-huseyin-ozak","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yanalim-gorelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Narsist', 'narsist-atila-gunal-b9b84', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bana seni anlatma

Ben sendeki seni

Bendeki gibi seviyorum

Bana beni anlatma

Bendesin diye

Yokluğunda kendimi seviyorum...

03-02-2004', 'Bana seni anlatma Ben sendeki seni Bendeki gibi seviyorum Bana beni anlatma Bendesin diye Yokluğunda kendimi seviyorum... 03-02-2004...', ARRAY['Türk Edebiyatı','Şiir','Atila Günal']::text[], 8.5, '{"poet":"Atila Günal","poet_slug":"atila-gunal","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/narsist-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanyon', 'kanyon-atila-gunal-ja3kb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Adın

İçimin boş duvarlarında yankılanıyor

