INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ulaşılmaz Gaye', 'ulasilmaz-gaye-gurol-kuscu-6gvhu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Durmaksızın sayfalarını çevirir zaman,

Yaşadıkça ruhlar bitmeyen bir hikayenin

Ebediyetin varlığına ederek iman,

Peşinden gider gönül ulaşılmaz gayenin', 'Durmaksızın sayfalarını çevirir zaman, Yaşadıkça ruhlar bitmeyen bir hikayenin Ebediyetin varlığına ederek iman, Peşinden gider gönül ulaşıl...', ARRAY['Türk Edebiyatı','Şiir','Gürol Kuşcu']::text[], 8.5, '{"poet":"Gürol Kuşcu","poet_slug":"gurol-kuscu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ulasilmaz-gaye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanrıçam’’', 'tanricam-ali-osman-yilmaz-xoy6f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Soruyordu bana görenler,

Hangi tanrıçanın bu heykel? 

Kim tapınır bu tanrıçaya? 

Bilemezler elbet,

Benden başka kim tapınır ki? 

Senin karşında böyle,

Gideceğim yolu bile unuttum,

Yağmur yağıyor,hem de sağnak,

Her yer gibi ben de,

Sırılsıklam ıslak.

Tanrıçanın alnında,yağmur taneleri, 

Dizilmişler,sıralı inci gibi,

Gözlerinde sürme bile var,

Yağmur tanelerinden inciler,

Ve gözlerin bana gülümsüyor.

Saçlarına taktığım,

Hercailer ve menekşeler,

Elinde tuttuğun kırmızı gül,

Boynunda gümüşten kolye,

Başının üstünde dolanmakta,

Yağmur yüklü sevgi bulutları,

Giysilerin parıldıyor,

Dalga dalga rüzgarda.

Her yer karanlık,

Bir yıldız bile yok,

Yağmur bulutları kaplamış ortalığı,

Islak ve sessiz bir gece,

Ne ses ne ışık,

Issız bir yalnızlık her yan,

Ve karanlığın ortasında bir insan,

Gözünü dikmiş yağmur tanelerine bakıyor,

Sabah olunca gün ışıyacak,

Ve nasıl parlayacak güneş kayalıklardan,

Ve tanrıçam gidecek yeni sevgilere,

Yeni sevgilinin kollarına atılacak,

Ardından sessiz ve ıssız yalnızlıktan,

Sessiz ve yalnız bakakalacağım,

Bilmem ki bendeki mutluluğu,

Yeni sevgilide bulabilecek Mi?', 'Soruyordu bana görenler, Hangi tanrıçanın bu heykel?  Kim tapınır bu tanrıçaya?  Bilemezler elbet, Benden başka kim tapınır ki?  Senin karşı...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/tanricam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tünel', 'tunel-gurol-kuscu-4aluy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akıldan üstündür akıl; elden üstündür el

Fikrimden başka yok kaçabileceğim tünel', 'Akıldan üstündür akıl; elden üstündür el Fikrimden başka yok kaçabileceğim tünel...', ARRAY['Türk Edebiyatı','Şiir','Gürol Kuşcu']::text[], 8.5, '{"poet":"Gürol Kuşcu","poet_slug":"gurol-kuscu","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/tunel-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saat Kulem', 'saat-kulem-gurol-kuscu-9kgmn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hep sensizliği beş geçse de bu alemde

Kala olmayacak benim saat kulemde', 'Hep sensizliği beş geçse de bu alemde Kala olmayacak benim saat kulemde...', ARRAY['Türk Edebiyatı','Şiir','Gürol Kuşcu']::text[], 8.5, '{"poet":"Gürol Kuşcu","poet_slug":"gurol-kuscu","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/saat-kulem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim İçin....', 'benim-i-cin-adem-tetik-xvk5l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hep ben ağlayacak değilim elbet

Bir gün benim için de ağlayan olur

Yüreğinde hasreti sevgisi ile

Ardımdan iki damla göz yaşı döken de bulunur....

Kim bilir çooook uzakta küçük bir şehirde

Yüreğinde özlemi hasreti ile

Dinmek bilmeyen sancısı ağrısı ile

Gün olur benim içinde ağlayan olur

Günlerce bitmeyen umuda sarılıp

Gelekcek diye hayallere dalıp

Bir gün olsun bir acı haberim alıp

Gün olur benim içinde ağlayan olur

Bellimi olur adımız düşmez dilinden

Dert vermiş tanrı ne gelir elinden

Bir vefasızın çektirdiklerinden

Bakarsın o zaman benim için de ağlayan olur

Hüzünle sevdayı hergün yoğurup 

Gelecektir diye hayaller kurup 

Gurbetten bir gün bir haber duyup 

Bakarsın benim içinde ağlayan', 'Hep ben ağlayacak değilim elbet Bir gün benim için de ağlayan olur Yüreğinde hasreti sevgisi ile Ardımdan iki damla göz yaşı döken de bulunu...', ARRAY['Türk Edebiyatı','Şiir','Adem Tetik']::text[], 8.5, '{"poet":"Adem Tetik","poet_slug":"adem-tetik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/benim-icin-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neydi Adın?', 'neydi-adin-gurol-kuscu-4xn3s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar deliler gibi sevdiğim kadın

Sorsalar da söyleyemem şimdi neydi adın! ! !', 'Bir zamanlar deliler gibi sevdiğim kadın Sorsalar da söyleyemem şimdi neydi adın! ! !...', ARRAY['Türk Edebiyatı','Şiir','Gürol Kuşcu']::text[], 8.5, '{"poet":"Gürol Kuşcu","poet_slug":"gurol-kuscu","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/neydi-adin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzelliğin Deseni', 'guzelligin-deseni-gurol-kuscu-vc50y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Olmalıydı ki siman güzelliğin deseni

Ondan bu adam deliler gibi sevdi seni', 'Olmalıydı ki siman güzelliğin deseni Ondan bu adam deliler gibi sevdi seni...', ARRAY['Türk Edebiyatı','Şiir','Gürol Kuşcu']::text[], 8.5, '{"poet":"Gürol Kuşcu","poet_slug":"gurol-kuscu","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/guzelligin-deseni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım babam', 'canim-babam-hicabi-ceylan-noi41', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kartal bakışlı

Çatma kaşlı babam

Sert yüzünün ardında

Sıcaklık saklı 

Adam gibi adam 

Nasıl oldu anlayamadım

Gözümün önünde mum gibi eridi

dağlar gibi heybetli duran babam

Şimdi bakamıyorum yüzüne

Baktıkça acıyor içimdeki yaram

Baba! ! sana odana girip

nasılsın demeye çekiniyorum

başını kaldırıp 

solgun yüzünle, uzaklara dalan gözünle

ve fersiz nefesinle

iyiyim deyişin var ya! 

Dayanamıyorum.

Bırakma beni baba 

daha hazır değilim sensizliğe

oda sıcak üşüyorum diyorsun

ısıtmıyor mu? Seni

artık örtündüğün battaniye

yaşadıklarım filim şeridi gibi

gözlerimin önünde

siyah önlüğümle okula gidiyorum

elim ellerinde

bırakma beni baba

dayanamam sensizliğe

nasılda göğsün kabarmıştı 

ben vatan borcunu ödemeye gittiğimde

bir türlü unutamıyorum canım babam

su yolu yapmıştın Çanakkaleyi 

ikinci askerliğini yapıyordun benimle

bak! şimdi bende baba oldum

benim için hissettiklerini

ve beni çok sevdiğini

şimdi daha iyi anlıyorum baba

doktorlar yapacak bir şey yok

bitmiş bu adam dedi

içim kanadı yüreğim delindi

ben hiç böyle olmamıştım canım babam

yinede yitirmedim umudumu

onlar Allah mı? Nerden bilir ki? 

Dualarım hep senin için

Baba daha hazır değilim ben

Ne olur beni yetim bırakma', 'Kartal bakışlı Çatma kaşlı babam Sert yüzünün ardında Sıcaklık saklı  Adam gibi adam  Nasıl oldu anlayamadım Gözümün önünde mum gibi eridi d...', ARRAY['Türk Edebiyatı','Şiir','Hicabi Ceylan']::text[], 8.5, '{"poet":"Hicabi Ceylan","poet_slug":"hicabi-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/canim-babam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açamayan Gülüm', 'acamayan-gulum-zafer-zengin-etnika-u73er', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sadık kalamadım

gülün kokusuna

her çiçekte 

gülü aradıkça

rengini gördüm

her açanda

dem tutuşlar

içine döndüğüm

o güzel yar

o güzel bakışa hapsoldu

unuttum gayrı

ne renkti ağlayışı

Hiç sormadım

gülün gözyaşını

sormadım...

18 subat 2004', 'sadık kalamadım gülün kokusuna her çiçekte  gülü aradıkça rengini gördüm her açanda dem tutuşlar içine döndüğüm o güzel yar o güzel bakışa h...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/acamayan-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaç Kurtar Kendini', 'kac-kurtar-kendini-zafer-zengin-etnika-nod2w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'umudu yüklemişken içime

açmayan gülüme seslendim

- kaç benden Kurtar kendini

dönüşü olmayan hayatın

için de yüzüyorum

senin rengini bilmediğim gibi

yüzmeyide bilmiyorum

..

boğuyorum akşam üstleri

çatlamış gözlerimi

ellerime düşürdüm

rengin deki yangını

sana sarıldım

küstüğüm 

son çiçekten sonra

gelecekmisin bahar da

dayanamıyorum 

bu yangın''a

ah lara vuruyorum başımı

ıssız da adını düşünüyorum

kokun biraz uzak benden

hani acıkmasam

kıpırdamayacağım yerimden

öylesi harmanlanmışsın tenimden

öyle harmanlanmışsın terimden

sessiz öpüyorum 

gülen gözlerinden

ince bir türküdür ellerime konan sıcaklığın...

18 subat 2004', 'umudu yüklemişken içime açmayan gülüme seslendim - kaç benden Kurtar kendini dönüşü olmayan hayatın için de yüzüyorum senin rengini bilmediğ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kac-kurtar-kendini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül', 'gonul-serdar-safran-m6uyw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gülüm diye sarıldım

Suçum ne de kırıldın

Ne yaptım da darıldın

Gönlüm artık naz çekmez

Şaşırdım neler yapsam

Kaldırıp kendim atsam

Güneşe perde çeksem

İnsafsız yar affetmez.

Yeter…Yeter…Nazların

Kime? ..Niye? ..Pozların

Yıktığın enkazların

Bu kalp artık poz çekmez.

Yıllardır yorgun kalbim

Atması durgun kalbim

Naz çekmez,vurgun kalbim

Ne yapsam,yar anlamaz

Yâr cilveli,nazlıdır

Sözleri niyâzlıdır

Şikâyeti hazlıdır

Bu gönül hiç uslanmaz…

(2004-Kastamonu)', 'Gülüm diye sarıldım Suçum ne de kırıldın Ne yaptım da darıldın Gönlüm artık naz çekmez Şaşırdım neler yapsam Kaldırıp kendim atsam Güneşe pe...', ARRAY['Türk Edebiyatı','Şiir','Serdar Safran']::text[], 8.5, '{"poet":"Serdar Safran","poet_slug":"serdar-safran","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gonul-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saftirik', 'saftirik-serdar-safran-b4mki', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sizin aklınız ermez dediler

Büyüklerimiz daha iyi bilir

Geçicidir bu günler

Safça inandık…

Ne oluyor diye soracak olduk

Sabretmek lazım,sabret dediler

Sabrettik hep beraber

Düzelir diye bekledik…

Düzelecek ama,sıkmalı halk kemeri

Ne delik kaldı,ne de sıkacak beli

Dost! ...ülkeden gelecekmiş haberi

Göz,kulak yolda kaldı…

Düşüyor dediler enflasyon

Ne ceket kaldı,ne de don

Sıfırları atsak mı? ...Devalüasyon

Çarşı-pazarda gözümüz kaldı

Niye ki sadece biz sıkarız kemeri

Deveyi hamutuyla yutuyor biri

Semirin siz,biz sıkalım kemeri

Bulamazsınız böyle dert çekeri

	

Buldunuz  benim gibi saftirik

Oynayın rolünüzü,hem de olsun lirik

Az yedin,çok yedin rekabeti seyrettik

Gözümüz ekranda kaldı….

08/04/2004', 'Sizin aklınız ermez dediler Büyüklerimiz daha iyi bilir Geçicidir bu günler Safça inandık… Ne oluyor diye soracak olduk Sabretmek lazım,sabr...', ARRAY['Türk Edebiyatı','Şiir','Serdar Safran']::text[], 8.5, '{"poet":"Serdar Safran","poet_slug":"serdar-safran","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/saftirik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İntikam', 'i-ntikam-tunay-karaca-sbm2t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Söz verdim kendime, seni yeneceğim

Boşuna uğraşma, yolundan gitmeyceğim

Söz verdim kendime, seni yeneceğim

Seni sen ile alt edeceğim

Söz verdim kendime, seni öldüreceğim

Senden daha güçlü olduğumu göstereceğim

Ellerimde kelepçe, boynumda ilmik, pişman değilim

Suçsuzum, nefs-i müdafa idi derim', 'Söz verdim kendime, seni yeneceğim Boşuna uğraşma, yolundan gitmeyceğim Söz verdim kendime, seni yeneceğim Seni sen ile alt edeceğim Söz ver...', ARRAY['Türk Edebiyatı','Şiir','Tunay Karaca']::text[], 8.5, '{"poet":"Tunay Karaca","poet_slug":"tunay-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/intikam-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarış', 'yaris-haluk-ozdemir-ganvx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu bir yarıştır 

Kazananı olmayan

Delicesine koşuyor herkes

Farkına bile varmadan

Yarış bitecek elbet

Farklı,farklı zamanlarda

Benim hiç acelem yok

Çok işim var buralarda', 'Bu bir yarıştır  Kazananı olmayan Delicesine koşuyor herkes Farkına bile varmadan Yarış bitecek elbet Farklı,farklı zamanlarda Benim hiç ace...', ARRAY['Türk Edebiyatı','Şiir','Haluk Özdemir']::text[], 8.5, '{"poet":"Haluk Özdemir","poet_slug":"haluk-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yaris-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akıllandım', 'akillandim-haluk-ozdemir-wgh29', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aldığım dersler bana yeter

Vermeyeceğim artık değer

Kimseye hak ettiğinden fazla

İyi olmalı; iyilik yapmalı ama

Bilinmiyor yaptığın iyilik

Üstüne vazife olunca

Ben yine yapacağım iyilik

Hak edene hakkınca', 'Aldığım dersler bana yeter Vermeyeceğim artık değer Kimseye hak ettiğinden fazla İyi olmalı; iyilik yapmalı ama Bilinmiyor yaptığın iyilik Ü...', ARRAY['Türk Edebiyatı','Şiir','Haluk Özdemir']::text[], 8.5, '{"poet":"Haluk Özdemir","poet_slug":"haluk-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/akillandim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ara Renkler', 'ara-renkler-gokhan-oflazoglu-ln8zv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hep birlikte bir yaşam

tekdüzelik kaplıyor alanları

sevinirken, gülerken.

Bir örnek salınımlar,

üzülürken, ağlarken.

Önceden ısmarlanmış aşklarımız,

yeryüzü kültürü bir elden.

Ara renkler kayboluyor,

biz sessizce çalışırken.

Arınmak olası değil artık,

hayat üstümüze gelirken.

18/02/2004', 'Hep birlikte bir yaşam tekdüzelik kaplıyor alanları sevinirken, gülerken. Bir örnek salınımlar, üzülürken, ağlarken. Önceden ısmarlanmış aşk...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ara-renkler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimde Adamım', 'yuregimde-adamim-aynur-uluc-bc07f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir tanem

Adamım

Canım

Can eriğimsin benim

İçimde ebruli

Kulağımda ezgi

Gecede güneşin yolu

Yüreğimde kıpırtısın

Ne desem ne söylesem 

Tamını anlatamadığım

Erkeğimsin dopdolu

(2001)', 'Bir tanem Adamım Canım Can eriğimsin benim İçimde ebruli Kulağımda ezgi Gecede güneşin yolu Yüreğimde kıpırtısın Ne desem ne söylesem  Tamın...', ARRAY['Türk Edebiyatı','Şiir','Aynur Uluç']::text[], 8.5, '{"poet":"Aynur Uluç","poet_slug":"aynur-uluc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yuregimde-adamim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başı Bağsız Hayaller eski', 'basi-bagsiz-hayaller-eski-aynur-uluc-znrpk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bedenime çizmediğin

resmi hayal ediyorum

içime işleyen buğulu sesini

sendeki sertliğin karşılığı

katıksız yumuşaklığı

bakışında yüzen berraklığı

düşlerin ufkundaki çizgide

bekliyorum seni

nefesimi tutuyor

suluyorum toprağını

tek şarkıda buluşuyor notalar

bereket tanrısı olmaya aday

endamını hayal ediyorum

ve yuvarlak ucundan okşuyorum

başıboş tınıları', 'bedenime çizmediğin resmi hayal ediyorum içime işleyen buğulu sesini sendeki sertliğin karşılığı katıksız yumuşaklığı bakışında yüzen berrak...', ARRAY['Türk Edebiyatı','Şiir','Aynur Uluç']::text[], 8.5, '{"poet":"Aynur Uluç","poet_slug":"aynur-uluc","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/basi-bagsiz-hayaller-eski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebeğim', 'bebegim-ayca-aydemir-ot4zq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Annem almış getirmiş

Koymuş bir yerlere

Sonra bana vermiş

Ben sen diye konuşuyormuşum

Almışım bebeğimi

Ondan on gün sonra dişlerim çıkmış

O günden sonra bebeğimi kaybetmişim

Çok üzülmüşüm

Artık büyüdüm

Unuttum nasıl üzüldüğümü

Artık oyuncaklara değil

Ders almalara merakım

17/01/2004

İstanbul', 'Annem almış getirmiş Koymuş bir yerlere Sonra bana vermiş Ben sen diye konuşuyormuşum Almışım bebeğimi Ondan on gün sonra dişlerim çıkmış O ...', ARRAY['Türk Edebiyatı','Şiir','Ayça Aydemir']::text[], 8.5, '{"poet":"Ayça Aydemir","poet_slug":"ayca-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bebegim-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bil ki ben ölmüşüm', 'bil-ki-ben-olmusum-salih-ozalasan-1zbha', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sonsuzluk senin olmak

Mutluluk kollarında ölmek

Yalnızlık sen koklamadan solmak

Sevda seni seviyorum diyebilmek

Kalmamışsa yüreğimde

Bunlara benzer duygular

Gözlerim baksa, yüreğim atsa da

Bil ki değeri yok, çünkü ben ölmüşüm

Yanardağ olsam, lavları yakıp kavuran

Bir aslan olsam yelesi savrulan

Dünyada tek olsam, hep aranan

Bil ki değeri yok, çünkü ben ölmüşüm

Y.Tarihi 18-02-2004

Salih Özalaşan', 'Sonsuzluk senin olmak Mutluluk kollarında ölmek Yalnızlık sen koklamadan solmak Sevda seni seviyorum diyebilmek Kalmamışsa yüreğimde Bunlara...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bil-ki-ben-olmusum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şen olasın ey zalim gurbet,', 'sen-olasin-ey-zalim-gurbet-ali-osman-yilmaz-hji5n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şen olasın ey zalim gurbet,

Yurdumdan ettin beni,

Bir sevgili uğruna,

Dağlar,ülkeler aşırttın,

Bir güzele çarptın beni,

Aşk elinde oyuncak ettin,

Gubarırsın artık değil Mi? 

Sevda ocağına atıp,

Bir yiğidi daha,har ettin.

Şen olasın zalim gurbet.', 'Şen olasın ey zalim gurbet, Yurdumdan ettin beni, Bir sevgili uğruna, Dağlar,ülkeler aşırttın, Bir güzele çarptın beni, Aşk elinde oyuncak e...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-olasin-ey-zalim-gurbet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk ülkesi,', 'mutluluk-ulkesi-ali-osman-yilmaz-ukrhy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mutluluk ülkesi,

Çok mu uzaklardadır? 

Yıllardır yürürüm umutla,

Varmak için mutluluk ülkesine.

Gelenler anlatır hep,

Nasıl mutlu olunduğunu,

Mutluluk ülkesinde.

Yoruldum,dizlerim sızlar,

Bacaklarım taşımaz artık,

Mutluluk enerjisinden yoksun,

Yakıtı bitmiş araba gibiyim,

Ne kadar itekleseler de,

Menzile varma umudu yok,

Hoşça kal mutluluk ülkesi,

Sana ulaşmak için,

Bende artık umut  yok.', 'Mutluluk ülkesi, Çok mu uzaklardadır?  Yıllardır yürürüm umutla, Varmak için mutluluk ülkesine. Gelenler anlatır hep, Nasıl mutlu olunduğunu...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mutluluk-ulkesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İade', 'i-ade-ahmet-aksoy-m1chi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sözcükler iade sarmalı,

sarmalı! bir el ve bir avuç,

avuç! uç uç şair meleği

meleği! görelim nereye kondurur,

kondurur! bu sarmal seni

seni seni seni seni seni...', 'sözcükler iade sarmalı, sarmalı! bir el ve bir avuç, avuç! uç uç şair meleği meleği! görelim nereye kondurur, kondurur! bu sarmal seni seni ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/iade-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
